\section{The conjecture} \label{sec:conjecture}
In this section, we state our main conjecture, and proceed to reformulate it in several interpretations. We also demonstrate why the conjecture becomes false if one tries to generalise it in some canonical directions. These results will not be used in the remainder of the paper, and we will actually apply some results from later sections to complete arguments in the current section.



\subsection{The first formulation}\label{SecFF}

Let $E$ be a finite subgroup of the additive group $\bk^+$. In particular $E\simeq C_p^r$, for some $r\in\mN$.

\subsubsection{} Via the subgroup inclusion 
$$E<\bk^+\simeq U(\bk)<SL_2(\bk),\quad \lambda\mapsto \left(\begin{array}{cc}
    1 &0  \\
    \lambda& 1 
\end{array}\right),$$
we have a restriction functor from the category of finite-dimensional algebraic representations $\Rep SL_2$ to $\Rep_{\bk} E$, and we denote by $\cT$ the essential image of the restriction functor
$$\Tilt SL_2 \to \Rep_{\bk} E.$$



\begin{lemma}[\cite{CF}*{Theorem~5.3.5, Remark~5.3.9(2)}, see also \cite{BE}*{Proposition~4.11}] \label{lem:restricted-tilting}
$\cT$ is already a pseudo-tensor subcategory. More precisely, the indecomposable modules in $\cT$ are, up to isomorphism, $T_i$, for $0\le i<p^r$, where we use the same notation for an $SL_2$-tilting module and for its restriction to $E$.  In particular $T_{p^r-1}\simeq \bk E$.
\end{lemma}


By \cite{Selecta}, we also have thick tensor ideals in $\cT$, 
$$0\subset \cT_{r+1}\subset \cT_r\subset\cT_{r-1}\subset\cdots\subset \cT_1=\cT ,$$
where $\cT_i$ has indecomposables $T_j$, for $p^{i-1}-1\le j$. For example, $\cT_{r+1}$ is simply the category of projective $\bk E$-modules. It follows immediately from the classification of tensor ideals in $\Tilt SL_2$ from \cite{Selecta} that these are the only thick tensor ideals in $\cT$.


\begin{aconjecture} \label{conj-a} Inside $\Rep_{\bk}E$, the subcategory $\cT_r$ is a thick tensor ideal. In other words, for every $X\in \Rep_{\bk}E$ and $T_i$ with $i\le p^{r-1}-1$, we have
\begin{equation}\label{eqXoT}
    X\otimes T_i\;\in\; \cT_{r}.
\end{equation}
\end{aconjecture}



One can define the full subcategory 
$$\widetilde{\cT}\;\subset\; \Rep_{\bk}E$$
on objects $X$ that satisfy \Cref{eqXoT}. 


\begin{lemma} \label{lem:closure} $\widetilde\cT$ is an $\Omega$-invariant pseudo-tensor subcategory of $\Rep_\kk E$, i.e., it is closed under tensor products, duals, $\Omega$-shifts, direct sums, and taking direct summands.  
\end{lemma}

\begin{proof} Consider arbitrary $X,Y\in\widetilde\cT$, and $i\le p^{r-1}-1$.
As $T_i$ is self-dual, it is a direct summand in $T_i^{\o3}$. Thus $T_i\o(X\o Y)\stackrel\oplus\subset (T_i\o X)\o (T_i\o Y)\o T_i$ lies in $\cT_r$, due to the closure properties of the latter. This shows $X\o Y\in\widetilde\cT$.
The isomorphisms $T_i\o X^*\cong T_i^*\o X^*\cong (T_i\o X)^*$ show that $\widetilde\cT$ is closed under duals. 
As we have a stable isomorphism $T_i\o\Omega(X)\cong\Omega(T_i\o X)$ and $\cT_r$ contains all projective objects, $\Omega X\in\widetilde\cT$.
As $\cT_r$ is closed under direct sums and taking direct summands, $\widetilde\cT$ is closed under these operations, as well.
\end{proof}



Then \Cref{conj-a} simply states:
\begin{aconjecture} \label{conj-aa}
We have
  $\widetilde{\cT}=\Rep_{\bk} E$. 
\end{aconjecture}

\begin{remark} \label{rem:T-tilde}
    \begin{enumerate}
    \item For the moment, the only cases in which \Cref{conj-a} is proved are $r=1$ and $p^r=4$, see \cite{CF}. In this case, one can prove the conjecture directly from the classification of indecomposable modules and their fusion rules. In \Cref{sec:Loewy} we provide a new proof that does not rely on such explicit knowledge.
    \item The most relevant case is $E:= \mF_q^+$, for a finite subfield $\mF_q\subset \bk$ of order $q=p^r$, but thus far we have no indication that this case behaves differently from other cases.
    \item For the main application in \cite{CF}, in the formulation of \Cref{conj-aa} it would actually be sufficient to show that $\widetilde{\cT}$ contains the subcategory of $\Rep_{\bk} E$ consisting of direct summands of restrictions along $E\to S_{q}$ (as in \cite{CF}*{5.1.5--5.1.7}), with $q=p^r$, of representations in the subcategory $\mathbf{T}\mathbf{C}^{q}\subsetneq \Rep_{\bk} S_q$ from \cite{PolyF}*{Question~3.1.8}. 
    \item One can replace \eqref{eqXoT} with the ({\it a priori} weaker) condition $X\otimes T_i\in \cT$. Indeed, $T_i$ is a direct summand of $T_i\o T_i^*\o T_i$. So if $T_i\o X\in\cT$, then $T_i\o X\in \langle T_i\o T_i^*\o\cT\rangle_\oplus\subset\cT_r$, as $\cT_r$ is a thick tensor ideal in $\cT$
\end{enumerate}
\end{remark}


\begin{lemma}\label{lem:justS}
    For any $X\in\Rep E$, $X\in\widetilde{\cT}$ if and only if $S\otimes X\in\cT$, if and only if $S\otimes X\in\cT_r$.
\end{lemma}

\begin{proof}
By \cite{Selecta}, the thick tensor ideal $\cT_r$ is generated by
$$S:=St_{r-1}=T_{p^{r-1}-1}.
$$ This demonstrates the first equivalence, the second follows from \Cref{rem:T-tilde}(4).\end{proof}




\begin{lemma} \label{lem:restricted-sl-in} Let $X$ be any restriction to $E$ of an $SL_2$-module all of whose $SL_2$-composition factors have highest weights at most $p^r-1$. Then $X\in\widetilde\cT$.
\end{lemma}

\begin{proof} By \cite{BEO}*{Lemma~3.3} or \cite{AbEnv}*{Lemma~4.3.4}, $S\o L_i$ is a tilting $SL_2$-module for all $0\le i\le p^r-1$. As tilting modules have trivial extensions, this means $S\o X\in\cT$. Hence we can apply \Cref{lem:justS}.
%As $S$ generates $\cT_r$, $S\o T_i\in\cT$ for all $i\le p^r-1$. This suffices to show the assertion by \Cref{rem:T-tilde}(4).
\end{proof}

\begin{lemma} \label{lem:SL2-std} The restriction of any standard or costandard $SL_2$-module $X$ lies in $\widetilde\cT$.
\end{lemma}

\begin{proof} By duality, it suffices to consider $X=\nabla_i$, the restriction to $E$ of the costandard module with highest weight $i$, for $i\ge0$. 

We can think of $\nabla_i$ as the span of all monomials of degree $i$ in $\kk[x,y]$. It is a $U(\kk)$-module, and hence an $E$-module, where the action of a lower unitriangular matrix with off-diagonal entry $\lambda$ sends $x^a y^b$ to $(x+\lambda y)^a y^b$. For each $k\ge0$, there is a short exact sequence of vector spaces
$$
0\to
\nabla_{k-1}
\xrightarrow{f}
\nabla_{k+i}
\xrightarrow{g}
\nabla_i
\to0 ,
$$
where $f(x^a y^b)= x^a y^{b+i+1}$ and $g(x^a y^b)$ is $x^{a-k} y^b$ if $b\le i$, and zero otherwise. $f$ is always a $U(\kk)$-module morphism, and one can check that $g$ is one if $p$ divides $k$. Thus, in this case, the above is in particular a short exact sequence of $E$-modules.

We can now specialize $k$ to $p^r$, then $\nabla_{p^r-1}=T_{p^r-1}$ is projective, and hence injective, over $E$ by \Cref{lem:restricted-tilting}, so $\nabla_{p^r+i}$ and $\nabla_i$ agree up to projective summands, for all $i$, and it suffices to consider $X=\nabla_i$ for $i<p^r$. But then $X\in\widetilde\cT$ by \Cref{lem:restricted-sl-in}.
\end{proof}


The following lemma is not used in the rest of the paper, but relies on later results.

\begin{lemma} \label{lem:SL2-simples} Let $X\in\Rep E$ be any Frobenius twist of a restricted $SL_2$-tilting module, or any restricted simple $SL_2$-module. Then $X\in\widetilde\cT$.
\end{lemma}

\begin{proof} By Steinberg's tensor product theorem, the second assertion follows from the first assertion, using \Cref{lem:closure}. Now it suffices to consider $X=L_1^{(j)}$, for $j\ge0$, as any Frobenius twist of a tilting module is a direct summand in a tensor power of the latter. But such $X$ are $2$-dimensional and of Loewy length two, so they are in $\widetilde\cT$ by \Cref{Exam:1} or \Cref{cor:ll-2-any-r} below.
\end{proof}




The fact that $S$ is a generator of $\cT_r$ also means that \Cref{conj-a} is equivalent to the following restricted version:


\begin{aconjecture} \label{conj-b}
    For every $X\in \Rep_{\bk}E$,  we have $X\otimes S \in \cT_r$.
\end{aconjecture}


Moreover, \Cref{conj-b} is then equivalent to the following formulation.

\begin{aconjecture} \label{conj-c}
    The category of $S$-projective modules in $\Rep E$ is precisely $\cT_r$.
\end{aconjecture} 




Before we move on to further reformulations of the conjecture, we formulate some statements that are implied by the conjecture. For the moment, we have no proof for any of them.

For reference below, observe that restricting the $SL_2$-representation to $B=U\rtimes T$ equips
$$\bk C_p^r\;\simeq\;\End_U(St_r),$$
see \Cref{LemmaLambda}, with the structure of an algebra in the category of $T$-representations. In other words, the group algebra $\bk C_p^r$ inherits a $\mZ$-grading. 

\begin{lemma}\label{lem:consequences} If \Cref{conj-a} is true, then the following statements are true for every $S$-projective module $Y$ in $\Rep_\kk E$:
    \begin{enumerate}
        \item $Y$ is self-dual.
        \item $Y$ has a graded lift, with respect to the $\mZ$-grading of $\bk E$ above.
        \item $Y$ has a filtration with every subquotient a copy of $S$.
        \item $Y$ is the restriction of an $SL_2$-module.
        \item Assume $Y$ is indecomposable and not projective, set $t:=\Hom_E(\unit, Y)$ and $d:=\dim_\kk Y$. Then $t=2^\ell$ and $d=\ell' 2^\ell p^{r-1}$ for some $0\le\ell\le r-1$ and $1\le\ell'\le p-1$. In particular, $t\le 2^{r-1}$, $d$ is divisible by $p^{r-1}$, and $d\le (p-1)(2p)^{r-1}$.
    \end{enumerate}
\end{lemma}
\begin{proof}
Part (1) is immediate since all tilting modules of $SL_2$ are self-dual already over $SL_2$.

For part (2), consider the algebra homomorphisms
$$\bk E\;\hookrightarrow\;\bk U(\bk)\;\to\; \End_U(St_r).$$
These are algebra homomorphisms in the category of $T(\bk)$-representations, such that the composite is an isomorphism and the source and target are rational $T$-representations. In other words, the inclusion of $\bk E$ into $\bk U(\bk)$ is one of algebras with $T(\bk)$-actions. Now an arbitrary $X\in \Rep SL_2$ has a (weight) $\mZ$-grading, and since the action of $E$ comes from
$$\bk E\;\hookrightarrow\;\bk U(\bk)\;\to\; \End_{\bk}(X),$$
it follows that this grading is compatible with the $\bk E$-module structure. Applying this to tilting modules proves (2).



Now we prove part (3). It follows from \Cref{lem:self-ext1} below that $T_{j}$ for $p-1\le j\le 2p-2$ is a self-extension of $St_1$ over $E$. It then follows from iteration of Donkin's tensor product formula \eqref{DTPT}, that every $T_i$ for $i\ge p^{r-1}$ is of the form
$$T\otimes X^{(r-1)}$$
where $T$ is a tilting module which has, as an $E$-representation, a filtration with quotients $S$, and $X$ is some tilting module. Taking a Loewy filtration of $X$ as an $E$-representation then concludes the proof. Note that for $p=2$, we do not need \Cref{lem:self-ext1}
as then the result follows almost immediately from Donkin's tensor product formula.

Part (4) is immediate. 

For part (5), we may assume $Y\cong T_i$ for some $p^{r-1}-1\le i\le p^r-2$. We can write $i+1=\sum_{k=0}^{r-1} i_k p^k$ with $i_{r-1}\neq0$. Set $\ell':=i_{r-1}$ and let $\ell$ be the number of non-zero non-leading coefficients in the above $p$-adic expansion of $i+1$.

To describe the possible values of $t$, we can use that by \Cref{PropT}, $t=\ell^\nabla(T_i)$, the length of the $\nabla$-flag of $T_i$ as an $SL_2$-module. The $\nabla$-modules appearing in the $\nabla$-flag of $T_i$ are given by $\nabla_{i'-1}$, where $i'$ ranges over all numbers obtained by inverting the signs of an arbitrary subset of the non-leading coefficients $\{i_0,\dots,i_{r-2}\}$ in the $p$-adic expansion of of $i+1$ by \cite{STWZ}*{Proposition~3.3}. There are $2^\ell$ distinct numbers $i'$ obtained in this way.

To describe $d$, we use that
$$
T_i \cong T_{p-1+i_0}^{(0)}\o T_{p-1+i_1}^{(1)}\o\dots\o T_{p-1+i_{r-2}}^{(r-2)}\o T_{i_{r-1}-1}^{(r-1)}
$$
by \cite{STWZ}*{Proposition~3.4}, where the superscripts indicate Frobenius twists. So $\dim T_i = \ell' 2^\ell p^{r-1}$. This number is always divisible by $p^{r-1}$, and is at most $(p-1) (2p)^{r-1}$. Note that this maximal dimension is attained for $T_{p^r-2}$. 
\end{proof}

Note that \Cref{lem:consequences}(5) is compatible with what we show in \Cref{lem:dim-periodic} below.

\subsection{The second formulation}
Fix $r\in\mZ_{>0}$.
Let $V$ be a faithful two-dimensional $C_p^r$-representation.

\begin{aconjecture} \label{conj-d}
Let $\cT$ be the pseudo-tensor subcategory generated by $V$ in $\Rep_{\bk}C_p^r$. Let $\cP\subset\cT$ be the category of projective modules in $\Rep_{\bk}C_p^r$. The unique
minimal thick tensor ideal in $\cT$ among those that strictly contain $\cP$ remains a thick tensor ideal in $\Rep_{\bk}C_p^r$.
\end{aconjecture}

To argue that \Cref{conj-d} is equivalent to the previous three, and for later use, we first introduce some notation. 


\subsubsection{}\label{Sec2dim}Any indecomposable two-dimensional $C_p^r$-representation has a basis $v_1,v_2$ so that
$$X_iv_1\;=\;\lambda_i v_2,\quad\mbox{and}\qquad X_iv_2=0,\quad\mbox{for some }\quad
\ulambda:=(\lambda_1,\ldots,\lambda_r)\;\in\; \mA^r(\bk)\backslash \{0\}$$
and denote the module by $V_{\ulambda}$.
The modules $V_{\ulambda}$ and $V_{\umu}$ are isomorphic if and only if $\ulambda$ and $\umu$ have the same image in $\mP^{r-1}(\bk)$. We will alternate between interpreting $\ulambda$ in $\mA^r(\bk)\backslash\{0\}$ and $\mP^{r-1}(\bk)$. We also write
$$\ulambda^{(i)}:=(\lambda_1^{p^i},\ldots,\lambda_r^{p^i})$$
for $i\in\mN$, and hence $(V_{\ulambda})^{(i)}\simeq V_{\ulambda^{(i)}}$, with the former the $i$-th Frobenius twist of $V_{\ulambda}$.
If we interpret $\ulambda\in\mA^r$, then $V_{\ulambda}$ has a canonical short exact sequence
$$0\to\bk\xrightarrow{1\mapsto v_2} V_{\ulambda}\to \bk\to 0.$$
The representation $V_{\ulambda}$ defines a group homomorphism
$$C_p^r\;\to\; SL_2(\bk),\quad g_i\mapsto \left(\begin{array}{cc}
    1 &0  \\
    \lambda_i & 1 
\end{array}\right)$$
so that $V_{\ulambda}$ is the restriction of the vector representation $V=T_1$.


\begin{lemma}\label{Lem:Moore}
    The following conditions are equivalent on 
    $\ulambda=[\lambda_1:\lambda_2:\cdots:\lambda_r]$ in $\mP^{r-1}(\bk)$:
    \begin{enumerate}
        \item $V_{\ulambda}$ is faithful;
        \item The elements $\lambda_i\in\bk$ are linearly independent over $\mF_p$.
        \item The determinant of the Moore matrix 
        $$ \mathbb{M}(\ulambda):=\begin{pmatrix}
\lambda_1 & \lambda_2 & \lambda_3 & \cdots & \lambda_r  \\
\lambda_1^p & \lambda_2^p & \dots \\
\dots \\
\lambda^{p^{r-1}}_1 & \dots&&&\lambda_r^{p^{r-1}}
\end{pmatrix}$$
is non-zero.
    \end{enumerate}
\end{lemma}
\begin{proof}
    Equivalence of (1) and (2) follows from the group homomorphism before the lemma. Equivalence between (2) and (3) is \cite{Go}*{Lemma~1.3.3}.
\end{proof}
We denote the set of $\ulambda$ satisfying the equivalent properties in \Cref{Lem:Moore} by $\mA_f^r$ or $\mP_f^{r-1}$.


By identifying $C_p^r$ with its image in $SL_2$, the unique ideal in \Cref{conj-d} corresponds to $\cT_r$, by the discussion leading up to \Cref{conj-a}. Hence \Cref{conj-d} is just a direct reformulation of \Cref{conj-a}.


\subsection{The third formulation}

\subsubsection{}
Let $G$ be a finite group and take a faithful $X\in \Rep_{\bk} G$. We consider the full subcategory $\cT_X$ of $\Rep_{\bk}G$ comprising direct sums of direct summands in $\Omega^m(X^{\otimes n})$, $m\in \mZ$ and $n\in\mZ_{>0}$. We denote by $\cI_X$ the thick tensor ideal in $\Rep_{\bk}G$ generated by $X$. Then we have $\cT_X\subset\cI_X$.
One can ask whether $\cI_X=\cT_X$. Naturally, this will very rarely be the case.


\begin{aconjecture} \label{conj-e}
    For $G=C_p^r$, with $r\in\mZ_{>1}$ and $X=St_{r-1}$, via some embedding $C_p^r<\bk^+<SL_2(\bk)$ as in \Cref{SecFF}, we have $\cI_X= \cT_X$.
\end{aconjecture}

To prove equivalence with the previous formulations, more specifically \Cref{conj-b}, it suffices to show that $\cT_{St_{r-1}}$ is $\cT_r$. This is precisely the content of \Cref{Lem:TOT} below.

One can further reformulate (and try to understand better) the conjecture, by obtaining more conceptual definitions for the modules in $\Rep_{\bk} C_p^r$ `of the form' $St_{r-1}$ for embeddings into $SL_2$. For example, when $r=2$, we have:

\medskip

\begin{aconjecture} \label{conj-e2}
    For $G=C_p^2$, and $X$ a self-dual periodic faithful module of dimension $p$, we have $\cI_X= \cT_X$.
\end{aconjecture}

Indeed, we will prove that $X$ as in \Cref{conj-e2} are precisely restrictions of Steinberg modules, for $r=2$ in \Cref{lem:uniqueselfdual}. Note that this characterisation fails for $r>2$, see \Cref{Sec8}. 



\begin{remark}

        We will show in \Cref{Sec9} that \Cref{conj-e2} fails if we remove the condition that $X$ be self-dual. Similarly, we show in \Cref{Sec8} that \Cref{conj-e} fails (for $r>2$) if we generalise it to all $X\in \Rep C_p^r$ that are, like the Steinberg modules $St_{r-1}$, self-dual periodic faithful and of dimension $p^{r-1}$.

 We regard this ease with which we can disprove the property $\cI_X=\cT_X$ for lookalikes $X$ of $St_{r-1}$ as further evidence for the validity of the conjecture.

\end{remark}

\subsection{Some context for \texorpdfstring{$q=9$}{q=9}}\label{Sec9}
Here we consider $p=3$ and $E=C_3^2$, the elementary abelian $3$-group of order $q=9$ (\textit{i.e.} $r=2$).

For $\ulambda\in \mP^1_f$, we can write
$\ulambda=[1:\lambda]$, for a unique $\lambda\in \bk\backslash \mF_3$.
We set
$$\tilde{\lambda}:=\binom{\lambda}{2}\;=\;\frac{\lambda(\lambda-1)}{2}\;=\;\lambda-\lambda^2\;\in\bk,$$
and consider the matrices in $\Mat_3(\bk)$
$$\mI= \left(\begin{array}{ccc}
       1  & 0 &0 \\
       0  & 1&0\\
       0&0&1
    \end{array}\right)\quad\mbox{and}\quad \mJ=\left(\begin{array}{ccc}
       0  & 0 &0 \\
       1  & 0&0\\
       0&1&0
    \end{array}\right).$$ We interpret $\mJ^0$ as $\mI$.

    For this value of $\ulambda$, the module $S=St_1$ for $E$ is given by
    $$X_1\mapsto \mJ,\quad X_2\mapsto \lambda\mJ+\tilde{\lambda} \mJ^2$$
More generally, we can parametrise the three-dimensional periodic modules with the same support $\{\blambda\}$, with $\blambda=[\lambda:-1]$. These modules are $S(\mu)$, for $\mu\in\bk$, where $S(\mu)$ corresponds to
$$X_1\mapsto \mJ,\quad X_2\mapsto \lambda\mJ+(\tilde{\lambda}+\mu) \mJ^2.$$
In particular, $S(0)=St_1$ and $S(\mu)=M_{\lambda,\tilde{\lambda}+\mu}$ in the notation of \cite{Benson-vector-bundles}*{Example~1.13.1}, which furthermore shows that
$$S(\mu)^\ast\simeq S(-\mu).$$

We investigate six-dimensional periodic modules.

\begin{lemma}\label{LemClas3}
    \begin{enumerate}

        \item The isomorphism classes of indecomposable six-dimensional $E$-representations with support $\{\blambda\}$ are labelled by $\bk\times\{0,1,2\}$. This assignment sends $(\mu,i)\in\bk\times \{0,1,2\}$ to the $E$-representation $N^{(i)}(\mu)$ with
        $$g_1\mapsto \left(\begin{array}{c|c} \mI+\mJ &0\\\hline
        0&\mI+\mJ\end{array}\right) \quad\mbox{and}\quad g_2\mapsto\left(\begin{array}{c|c} \mI+\lambda\mJ+(\tilde{\lambda}+\mu)\mJ^2 &0\\\hline
        \mJ^i&\mI+\lambda\mJ+(\tilde{\lambda}+\mu)\mJ^2\end{array}\right).$$
        \item The modules $N^{(0)}(\mu)$ are cyclic. The cyclic submodules of maximal dimension in $N^{(1)}(\mu)$, resp. $N^{(2)}(\mu)$, have dimension five, resp. four.
        \item The only non-split first extensions between the modules $S(\mu)$ take the form
        \begin{enumerate}
            \item $0\to S(\mu)\to N^{(0)}(\kappa)\to S(\nu)\to 0$, for $2\kappa=\mu+\nu$;
            \item $0\to S(\mu)\to N^{(1)}(\kappa)\to S(\nu)\to 0$, for $2\kappa=\mu+\nu$;
            \item $0\to S(\mu)\to N^{(2)}(\mu)\to S(\mu)\to 0$.
        \end{enumerate}
    \end{enumerate}
\end{lemma}
\begin{proof}
Let $N$ be a 6-dimensional $E$-representation with support $\{\blambda\}$. In particular, $N$ is projective over $C_3\times 1$ and we can take a basis where $g_1$ acts as in part (1) and $g_2$ via block matrix with zero in the top right block. In other words, $N$ is an extension of two 3-dimensional representations that are projective over $C_3\times 1$. 
Hence, the support of each of these $3$-dimensional representations is a proper subvariety of $\mP^1$, i.e., a finite, possibly empty set of points. Being of dimension $3$, the representations cannot be projective over $E$, so their support is a non-empty finite set of points. As the support variety of an indecomposable representation is connected by \cite{Carlson-connected}, each of these representations is a direct sum of representations whose support is a point. The latter summands are periodic, and of dimension at least $3$. Hence, the support of each of the $3$-dimensional representations is a point. Now by \Cref{sup:ses}, both of these points have to be $\blambda$. So the $3$-dimensional modules are of the form $S(\mu)$ and $S(\nu)$. 

To conclude the proof, we thus need to analyse the extensions between modules of the form $S(\mu)$. To simplify expressions one can apply an automorphism $\phi$ of $\bk E$ which sends $X_1$ to $X_1$ and $X_2$ to $X_2+\lambda X_1+\tilde{\lambda}X_1^2$. Then $S(\mu)$ is the twist by $\phi$ of the module $R(\mu)$ where $X_1$ acts by $\mJ$ and $X_2$ acts by $\mu\mJ^2$. One thus needs to understand
$$\Ext^1(R(\mu),R(\nu))\;\simeq\;\uHom(\Omega R(\mu), R(\nu)).$$
Here, $\Hom(\Omega R(\mu), R(\nu))$ always has dimension 3 and is a cyclic $\End(R(\nu))$-module. The dimension of $\uHom(\Omega R(\mu), R(\nu))$ is 3 when $\mu=\nu$ and 2 otherwise, due to the non-zero composite
$$\Omega R(\mu)\hookrightarrow \bk E\tto R(\nu).$$
To conclude the lemma one then needs to show that isomorphisms between the middle terms in (3)(a) respectively (3)(b) are governed by $\mu+\nu$. That the middle terms only depend on $\mu+\nu$ follows from a direct base change. That $N^{(i)}(\kappa)$ is not isomorphic to $N^{(i)}(\kappa')$ for $\kappa\not=\kappa'$ follows by directly verifying that for all submodules $S(\kappa)$ in $N^{(i)}(\kappa)$, the quotient is $S(\kappa)$.
\end{proof}





\begin{proposition}\label{Prop3d}
\begin{enumerate}
    \item  If $\mu+\nu\not=0$, we have
    $$
    S(\mu)\otimes S(\nu)= S\left(\frac{\mu\nu}{\mu+\nu}\right)\oplus N^{(0)}\left(\frac{\mu\nu}{\mu+\nu}\right).
    $$
    \item  If $\mu=0=\nu$, then
    $$
    S(0)\otimes S(0)= S\left(0\right)\oplus N^{(1)}\left(0\right).
    $$
    \item Finally, if $\mu\not=0$ and $\mu+\nu=0$, then $S(\mu)\otimes S(\nu)$ is an indecomposable non-projective module $Q$, independent of $\mu$, of dimension $9$ with $\dim\End(Q)=15$ and a Loewy series with dimensions $3,3,3$.
\end{enumerate}

\end{proposition}

\begin{proof}
    This follows from straightforward but tedious computations. For example, assume that $\mu+\nu\not=0$.

    We label the bases of $S(\mu)$ and $S(\nu)$ corresponding to the above matrix definitions by $\{e_1,e_2,e_3\}$ and $\{f_1,f_2,f_3\}$. Then we can verify that $e_1\otimes f_1$ generates a (cyclic) submodule $R$ which fits into a short exact sequence
    $$0\to S(-\mu\nu/(\mu+\nu))\to R\to S(0)\to 0,$$
    where the submodule is (as is clear from the claimed short exact sequence and cyclicity of $R$) generated by 
    $$X_2(e_1\otimes f_1)-\lambda X_1(e_1\otimes f_1)-\tilde{\lambda}X_1^2(e_1\otimes f_1)$$
    By \Cref{LemClas3}, $R$ is then isomorphic to $N^{(0)}(\mu\nu/(\mu+\nu))$.

    Finally, we can find a complementary submodule isomorphic to $S(\mu\nu/(\mu+\nu))$ generated by 
    $$e_1\otimes f_2-e_2\otimes f_1-(e_1\otimes f_3-e_3\otimes f_1)+\alpha X_1(e_1\otimes f_1)+\beta X_1^2(e_1\otimes f_1),$$
    for appropriate $\alpha,\beta\in \bk$, most importantly $\alpha=(\nu-\mu)/(\mu+\nu)$.
\end{proof}

\begin{remark}
The special case $\mu=\nu$ of \Cref{Prop3d} is easily verifiable. Indeed, in this case 
$$\wedge^2 S(\mu)\;\simeq\;S(\mu)^\ast\;\simeq\;S(-\mu).$$
 In this case $\alpha=0=\beta$ in the proof of \Cref{Prop3d} and the short exact sequence is simply
$$0\to S(\mu)\to R\to S(0)\to 0.$$
\end{remark}




If we consider the group homomorphism $C_3^2\to SL_2(\bk)$ corresponding to $\ulambda$, then
    $$S=St_1=T_2\mapsto S(0),\quad T_3\mapsto N^{(2)}(0),\quad T_4\mapsto N^{(1)}(0),\quad T_5\mapsto N^{(0)}(0). $$
This leads to:


\begin{example}
   For all $\nu\neq0$, we have
    $$S\otimes S(\nu)\;\simeq\; S \oplus T_5,$$
    in line with \Cref{conj-b}.
\end{example}

In sharp contrast, we find:

\begin{corollary}\label{Cor:Anti}Assume that $\bk$ is uncountable.
    Whenever $\mu\not=0$, we have $\cI_{S(\mu)}\not\subset \cT_{S(\mu)}$. Hence $S(\mu)$ `does not satisfy~\Cref{conj-e}'.
\end{corollary}
\begin{proof}
    By construction, the number of indecomposables in $\cT_{S(\mu)}$ is countable. However, by \Cref{Prop3d}, the number of indecomposables in $\cI_{S(\mu)}$ is at least the order of the field.
\end{proof}

\begin{remark}
    The assumption that $\bk$ be uncountable in \Cref{Cor:Anti} is only for convenience, since the module $S(\mu)$ is actually algebraic.
\end{remark}

%\begin{proof}
 %   By self-duality and \Cref{RemFirst}, we know where $T_2$ is sent to and that $T_3,T_4,T_5$ are sent to $\{N^i_{\lambda,\tlam}\mid i\}$. To identify which tilting is sent to which 6-dimensional module, we can employ \Cref{LemClas3}(3). Indeed, using the standard flag, we know that the maximal cyclic $U$-module in $T_3,T_4,T_5$ has dimension $4,5,6$. These dimensions cannot increase by restricting along $C_3^2<U(\bk)$.
%\end{proof}


%\begin{example}
%\Cref{Prop3d} thus agrees with the well-known tensor product 
%$$T_2\otimes T_2\;\simeq\; T_4\oplus T_2$$
%in $\Tilt SL_2$ for $p=3$.
%\end{example}

\begin{remark}
    \Cref{Prop3d}(1) also demonstrates that for $S(\mu)$ with $\mu\not=0$, indecomposable $S(\mu)$-projective modules need not have a filtration with all subquotients isomorphic to $S(\mu)$, in contrast to \Cref{lem:consequences}(3).
\end{remark}



\subsection{Some context for \texorpdfstring{$q=8$}{q=8}}\label{Sec8}
Here we consider $p=2$ and $E$ an elementary abelian $2$-group of order $q=8$ (\textit{i.e.} $r=3$).


The most immediate properties of $S=St_2=T_{7}$ are that it is $4$-dimensional and periodic, self-dual and faithful as a $E=C_2^3$-representation. We study all such modules, and observe that self-duality is automatic.
\begin{lemma}\label{Lem:4dim}
Let $M$ be a faithful periodic 4-dimensional module in $\Rep E$.
\begin{enumerate}
    \item $M\simeq A\otimes B$, for two-dimensional modules $A,B$.
    \item $M$ is self-dual.
    \item $M$ is algebraic.
\end{enumerate}
\end{lemma}
\begin{proof}
    Since two-dimensional modules are self-dual and algebraic, see \cite{CF}*{Remark~5.3.9(3)}, we only need to prove part (1).

    Consider therefore $[1:\mu:0]$ and $[1:\alpha:\beta]$ in $\mP^2$. Then, we can directly compute that $A\otimes B$ is the $E$-representation
    $$\bk E/(X_1+aX_2+bX_3+cX_2X_3),$$
    with 
    $$\mu=a^{-1},\quad \beta=\frac{1+a}{b+c},\quad \alpha=\frac{b+ca^{-1}}{b+c}.$$
Up to relabelling the $X_i$, every faithful periodic 4-dimensional module is of the above form.
\end{proof}

    %Every (faithful) 4-dimensional periodic module is self-dual. They are all of the form $A\otimes B$ for two-dimensional modules $A,B$. (in particular they are all algebraic, as tensor products of two algebraic modules)


    Now we single out which such modules correspond to Steinberg modules. For a faithful periodic 4-dimensional module $M$, call a 2-dimensional module $W$ `complementary' if $M\otimes W$ is projective. Any such module defines a $\bk$-linear morphism
    $$\beta_W:\;H^1(E,\bk)\;\to\;\End(M),$$
by sending a self-extension 
$$0\to \unit \xrightarrow{f} Y\xrightarrow{g}\unit\to 0$$
to the left vertical arrow in the commutative diagram (the middle vertical arrow is not unique)
$$\xymatrix{
0\ar[r]&M\ar[r]\ar[d] &M\otimes W\ar[r]\ar[d]&M\ar[r]\ar@{=}[d]&0\\
0\ar[r]&M\ar[r]^-{M\otimes f} &M\otimes Y\ar[r]^-{M\otimes g}& M\ar[r]&0
}$$
where the top row is defined similarly to the bottom row. Note that the left vertical arrow is uniquely defined as a consequence of the equality $\uEnd(M)=\End(M)$. The latter equality follows for instance from dimensional arguments. Indeed, $M\otimes M^\ast$ cannot contain an a projective direct summand, since, by support considerations, its complement $Q$ would be projective over some subgroup of $E$ isomorphic to $C_2^2$ which leads to a contradiction (using \Cref{Lem:4dim}(1))
$$
4\le\dim\End(M) = \dim\Hom(\one,M\o M^*) \le 1+(\dim_\kk Q)/4 = 3.
$$




    \begin{proposition}\label{Prop:4dim}
        The following conditions are equivalent on 4-dimensional faithful periodic modules $M$ over $E=C_2^3:$
    \begin{enumerate}
        \item $M$ is the restriction of $St_2$ for some embedding of $E$ into $SL_2$;
        \item $M\simeq V\otimes V^{(1)}$ for a (two-dimensional) module $V$;
        \item There exists a complementary $W$ for which the image of
        $$\beta_W:\,H^1(E,\bk)\to\End(M)$$
        is a subalgebra.
        \item There exists a complementary $W$ for which the image of 
        $$H^1(E,\bk)\xrightarrow{\beta_W}\End(M)\tto\End(M)/\Aut(M)$$
        is finite.
    \item There are finitely many isomorphism classes of modules of the form $M\otimes Y$, with $Y$ a two-dimensional module.
    \end{enumerate}
    \end{proposition}
\begin{proof}
    Equivalence between (1) and (2) is straightforward. We write $M=A\otimes B$ (with $A$ and $B$ non-isomorphic two-dimensional modules) and observe
    $$\End(M)\;\simeq\;\End(A)\otimes \End(B)\;\simeq\; k[t]/t^2\otimes k[s]/s^2.$$
    It follows that $\End(M)/\Aut(M)$ consists of two points (represented by an arbitrary isomorphism and an arbitrary morphism with 1-dimensional image) and one $\mP^1$-family represented by morphisms with 2-dimensional image. A 3-dimensional subspace of $\End(M)$ which contains $1$ is a subalgebra if and only if its image in $\End(M)/\Aut(M)$ is finite. For these modules we can also observe that 
    $$\End(M)/\Aut(M)\;\simeq\; \Ext^1(M,M)/\Aut(M)$$ is canonically in bijection with the isomorphism classes of self-extensions of $M$. Here, the isomorphism between $\End(M)$ and $\Ext^1(M,M)$ can be realised such that $\beta_W$ factors as
    $$H^1(E,\bk)\xrightarrow{\sim}\Ext^1(\unit,\unit)\xrightarrow{M\otimes-}\Ext^1(M,M)\xrightarrow{\sim}\End(M).$$
    It follows that (3) and (4) and (5) are equivalent.

    That (2) implies (3) will be proved rigorously in the proof of \Cref{ThmCarlson}. To show that (3) implies (2), we can observe that, under the above identifications, the dimension of the image of an endomorphism of $M$ corresponds (by adding 4) to the dimension of the submodule of $A\otimes B\otimes Y$ generated by the tensor product of the three generators. Since a 3-dimensional subspace of $\End(M)$ is a subalgebra if and only if it contains an element with image of dimension 1, it suffices to prove that the tensor product of generators in $A\otimes B\otimes Y$ can only be of dimension 5 when (up to permutation) $A=B^{(1)}$ and $Y=B^{(1)}$, which follows from a direct computation.
 \end{proof}




    \begin{corollary}
Let $X$ be a self-dual faithful periodic $\bk E$-module of dimension 4 that is not of the form $St_2$, for any embedding $E<SL_2(\bk)$, then $\cI_X\not=\cT_X$.
    \end{corollary}
    \begin{proof}
        By \Cref{Lem:4dim} $\cT_X$ contains finitely many indecomposable objects, while $\cI_X$ contains infinitely many by \Cref{Prop:4dim}.
    \end{proof}


