\section{Analysing the restrictions of Steinberg modules} \label{sec:analyse}

We continue the set-up from the previous section.
We thus have an inclusion of groups $E:=C_p^r\hookrightarrow \bk^+$, which we further interpret as an inclusion into $SL_2(\bk)$. This information is equivalent to the data of some $$\ulambda=(\lambda_1,\ldots,\lambda_r)\in \mA^r_f(\bk).$$


Denote by $T_i$, $0\le i< p^r$  the image of the corresponding $SL_2$-tilting module in $\Rep E$.




\subsection{Endomorphisms of Steinberg modules}
The following was proved in \cite{CF}*{Proposition~ 5.3.8}, where $\ell^\nabla$ refers to the length of the $\nabla$-flag of a module.
\begin{proposition}\label{PropT}
For all $0\le i<p^r$, we have 
    \begin{enumerate}
    \item
    $\dim_{\bk}\Hom_{E}(\unit,T_i)\,=\,\ell^\nabla(T_i),$
    \item $\dim_{\bk}\Hom_{E}(V,T_i)\,=\,2\ell^\nabla(T_i)-\dim_{\bk}\Hom_{SL_2}(\unit,T_{i})$.
    \end{enumerate}
\end{proposition}



\begin{lemma}\label{LemCyc}
The $C_p^r$-modules $St_i$ are cyclic for $0\le i\le $r.
\end{lemma}
\begin{proof}
    Since $St_i=\nabla_{p^i-1}$, and the module is self-dual, this follows from \Cref{PropT}(1).
\end{proof}


\subsubsection{}\label{basis}
By abuse of notation we choose a basis written as $\{e_1,e_2,\ldots, e_p\}$ of $St_1^{(j)}$ for each $0\le j <r$. We choose the basis of $St_1$ via the following isomorphism
$$ \bk[x,y]_{p-1}\,\xrightarrow{\sim}\, St_1,\qquad x^{p-i}y^{i-1}\mapsto (p-i)! \,e_i,\quad\tfor 1\le i\le p.
$$
Similarly, the basis of $St_1^{(j)}$ is chosen such that $e_i$ in $St_1^{(j)}$ corresponds to $e_i^{\otimes p}$ in the realisation of $St_1^{(j)}$ as a subquotient of $(St_1^{(j-1)})^{\otimes p}$.

Due to this simplification of notation it is important to take into account the convention that 
$$\bigotimes_i St_1^{(a_i)}\;:=\; St_1^{(a_1)}\otimes St_1^{(a_2)}\otimes \cdots,\quad \text{for }\{a_i\in\mN\}.$$



\subsubsection{}\label{EndS1} With our choice of basis of $St_1$, one can now verify that
$$\End_U(St_1)\;\simeq\;\End_E(St_1)\;\simeq\; \bk[z]/z^p,$$
where $z^a$, for $0\le a<p$, corresponds to the endomorphism
$$e_i\;\mapsto \; \begin{cases} e_{i+a}&\text{ if }i+a<p\\
0&\text{ otherwise.}
\end{cases}$$
Indeed, by \Cref{LemCyc}, we know that $St_1$ is cyclic over $E$, so the dimension of the endomorphism algebra is bounded by $p$. It thus suffices to observe that each of the suggested endomorphisms is $U$-linear.



\begin{lemma}\label{LemmaLambda}
    There is an algebra isomorphism
    $$\bk[z_1,\ldots, z_{r-1}]/(z_i^p\mid 1\le i<r)\;\xrightarrow{\sim}\; \End_E(S)=\uEnd_E(S),$$
    where each basis element $\prod_{j}z_j^{a_j}$,
 is sent to the endomorphism determined by
    $$e_1\otimes e_1\otimes\cdots \otimes e_1\;\mapsto \; e_{1+a_1}\otimes e_{1+a_2}\otimes \cdots \otimes e_{1+a_{r-1}}.$$

\end{lemma}
\begin{proof}
    We have the obvious injective algebra morphism
    $$\left(\bk[z]/(z^p)\right)^{\otimes r-1}\simeq\bigotimes_{i=0}^{r-2}\End_E(St_1^{(i)})\;\hookrightarrow\;\End_E(S).$$
    Moreover, since $S$ is cyclic by Lemm\Cref{LemCyc}, we have
    $$\dim_k\End_E(S)\;\le\; \dim_k S \;=\; p^{r-1},$$
    so the above injection must be a bijection.

    It only remains to show that $\End_E(S)$ equals its quotient $\uEnd_E(S)$. This follows from adjunction, since 
    $S^\ast\otimes S=S^{\otimes 2}$ does not contain a projective summand. Indeed, $S^{\otimes 2}$ is a direct sum of $T_j$ with $j\le 2p^{r-1}-2<p^r-1$, so we can use \cite{CF}*{Remark~5.3.9(2)}.
\end{proof}






\subsection{Support and Heller shifts of tilting modules}\label{SecSuppHell}


\begin{proposition} \label{prop:Omega-Ti}
    In $\Stab E$ we have
    $$\Omega( T_{a+p^{r-1}b})\;\simeq\; T_{a+ p^{r-1}(p-2-b)},$$
    for all $p^{r-1}-1\le a\le 2p^{r-1}-2$ and $0\le b\le p-2$.
\end{proposition}
\begin{proof}
    By iterating Donkin's formula, \cite{Jantzen}*{E.9}, we have
    $$T_{a+p^{r-1}b}\;\simeq\; T_{a}\otimes T_b^{(r-1)}$$
    in the chosen range of $a,b$. Over $U$, so certainly over $E<U(\bk)$, we have a short exact sequence
    \begin{equation}\label{eqsesT}0\to T_{p-2-b}\to T_{p-1}\to T_b\to 0,\end{equation}
    where all tilting modules are also (co)standard objects. Also by Donkin's formula, 
    $$T_{a}\otimes T_{p-1}^{(r-1)}\;\simeq\;T_{a+ p^{r}-p^{r-1}}. $$
    Since $a+ p^{r}-p^{r-1}$ is at least $p^r-1$, this module is projective in $\Rep E$. We can thus conclude the proof by considering the tensor product with $T_a$ of the $(r-1)$-th Frobenius twist of the short exact sequence in \Cref{eqsesT}.
\end{proof}


\begin{example}\label{ex:Omega-Ti}
\begin{enumerate}
    \item For $p>2$, we have
    $$\Omega(T_{2p^{r-1}-2})\;\simeq\; T_{p^r-2}.$$
    \item If $p=2$, then
    $\Omega(T_i)\simeq T_i$ for all $i\ge 2^{r-1}-1$.
\end{enumerate}

\end{example}

\label{sec:supp}





 \begin{lemma}\label{LemDescSt1}
 Normalise the expression $\ulambda=[\lambda_1:\cdots:\lambda_r]\in\mP^{r-1}_f$ so that $\lambda_1=1$.
     Over $C_p^r <\bk^+$, we then have
     $$St_1=T_{p-1}\simeq k[X_1,X_2, \ldots, X_r]/(X_a-\sum_{i>0} \binom{\lambda_a}{i}X_1^i\mid 1<a\le r).$$
 \end{lemma}
 \begin{proof}
     We can realise $St_1=\nabla_{p-1}$ as the degree $p-1$ polynomials in $k[x,y]$, where the two generators act by
     $$g_1: f(x,y)\mapsto f(x+y,y)\,\mbox{ and }\, g_a: f(x,y)\mapsto f(x+\lambda_a y,y),$$
     for $a>1$.
     In particular, the action of $g_a$ on $St_1$ depends polynomially on $\lambda_a$, with maximal degree $p-1$. As we can determine polynomials of degree $\le p-1$ by their values on~$\mF_p$, more concretely, the action of $g_a$ equals the action of 
     $$\sum_{j=0}^{p-1}p_j(\lambda_a) g_1^j$$
     for polynomials $p_j$ of degree $p-1$ satisfying $p_j(i)=\delta_{i,j}$ for $0\le i,j<p$. This can be rewritten to show that the action of $X_2$ equals the action of
     $$\sum_{j\ge 0}\left(\sum_{i=j}^{p-1}\binom{i}{j}p_i(\lambda_a)\right)X_1^j-1\;=\;\sum_{j>0}\binom{\lambda_a}{j}X_1^j.$$
     Since $St_1$ is a cyclic module, see \Cref{LemCyc}, and has dimension $p$, the conclusion follows.
 \end{proof}
 \begin{remark}
The lemma can be extended to describe $T_i$ for $i<p$, but we do not require this.
 \end{remark}

\begin{proposition}\label{PropSupp}
    The support of $SL_2$-tilting modules considered over $C_p^r$ via $\ulambda\in\mP^{r-1}_f(\bk)$ is given as follows. For $j\in\mN$ and 
    $$p^j-1\;\le\; i\;<\; p^{j+1}-1$$
    we have
    $$\supp(T_i)\;=\;\{\underline{\alpha}\in\mP^{r-1}\mid \sum_{s=1}^r \alpha_s \lambda_s^{p^l}=0\text{ for all }0\le l< j\}.$$
\end{proposition}

Before giving the proof we clarify the statement with some examples. Note that the support in \Cref{PropSupp} can be interpreted via an intersection of hyperplanes determined by some of the rows of the Moore matrix $\mathbb{M}(\ulambda)$, as in \Cref{Lem:Moore}.

\begin{example}\label{ExSupp}
    \begin{enumerate}
        \item We have $\supp T_i=\mP^{r-1}(\bk)$ for $i<p-1$.
        \item The support of $T_i$ for $p-1\le i<p^2-1$ is the hyperplane in $\mP^{r-1}$ determined by $\ulambda$.
        \item The support of $T_i$ for $p^{r-1}-1\le i<p^r-1$ is a single point $\blambda$. For example, we have
        $$\blambda\;=\;\begin{cases}
        [\lambda_2:-\lambda_1],&\text{if } r=2,\\
        [\lambda_2\lambda_3^p-\lambda_3\lambda_2^p:\lambda_3\lambda_1^p-\lambda_1\lambda_3^p:\lambda_1\lambda_2^p-\lambda_2\lambda_1^p],&\text{if } r=3.
        \end{cases}$$
        \item We have $\supp T_i=\varnothing$ for $i\ge p^r-1$, as $\mathbb{M}(\ulambda)$ is invertible.
    \end{enumerate}
\end{example}

For future reference, we reformulate parts (3) and (4) of the example as the following corollary.

\begin{corollary}\label{Cor:Supp}
    Assume $\ulambda\in\mP^{r-1}_f(\bk)$. Then the support of $St_{r-1}$ is given by the point $\blambda\in\mP^{r-1}(\bk)$, uniquely determined by
    $$\sum_{i=1}^r\lambda_i^{p^l}\blambda_i=0,\qquad\mbox{for all}\quad 0\le l\le r-2.$$
    Moreover, $\sum_{i=1}^r\lambda_i^{p^{r-1}}\blambda_i\not=0$.
\end{corollary}


\begin{proof}[Proof of \Cref{PropSupp}]
    Using the ideal structure of $\Tilt SL_2$, see \cite{Selecta}*{\S 5.3}, it suffices to prove the claim for the specific tilting modules
    $$St_j\;=\; T_{p^j-1}\;\simeq\; \bigotimes_{l=0}^{j-1} T_{p-1}^{(l)},$$
    for $j\in\mZ_{>0}$. Note that we thus ignore the trivial case `$St_0=\unit$'. It follows from \Cref{LemDescSt1} and Carlson's lemma (see for instance \cite{Benson-vector-bundles}*{Lemma~1.9.8}) that
    $$\supp T_{p-1}\;=\;\{\underline{\alpha}\mid \sum_{s=1}^m \alpha_s \lambda_s=0\}.$$
    From this we can easily derive 
    $$\supp T_{p-1}^{(l)}\;=\;\{\underline{\alpha}\mid \sum_{s=1}^m \alpha_s \lambda^{p^l}_s=0\}.$$
    The conclusion thus follows from the tensor product property of support in \eqref{sup:tensor}.
\end{proof}

\begin{remark} \label{rem:SX-projective} It immediately follow that $St_{r-1}\o X$ is a projective module for any $E$-module $X$ whose support does not contain $\blambda$ as in \Cref{Cor:Supp}.
\end{remark}

\begin{lemma}\label{lem:uniqueselfdual}
    If $r=2$, then $St_1$ is the unique $p$-dimensional self-dual periodic module with support~$\{\blambda\}$.
\end{lemma}
\begin{proof}
We already know that $St_1$ satisfies these properties. Consider an arbitrary periodic $p$-dimensional $C_p^2$-representation $M$. Since $X_1$ acts freely on $M$, we can identify $M$ with $\bk[X_1]/X_1^p$. The isomorphism class of $M$ is then completely determined by the action of $X_2$ on $1$. In other words, the action of $X_2$ of $M$ is equal to the action of
$$\sum_{i=1}^{p-1}a_iX_1^i$$
and the numbers $\{a_1,\ldots, a_{p-1}\}$ determine the isomorphism class of $M$. Furthermore, $a_1$ determines the support of $M$. Now, even without carrying out the computation, one can observe that demanding that the corresponding relation between $X_2$ and $X_1$ on $M^\ast$ will be the same results in a system of $p-1$ polynomial equations in the coefficients $a_i$ so that a unique solution will exist that writes $a_i$, for $i>1$, as a given polynomial in $a_1,\ldots, a_{i-1}$. Hence, for each support, there is only one self-dual module, which thus must be $St_1$.
\end{proof}


\subsection{Self-extensions of the Steinberg modules}




\begin{lemma}\label{lem:self-ext1}
    Consider $i,j\in\mN$ with $i\le p^{j+1}-1$ and let $H$ be an abstract subgroup of $U(\bk)$. Then the following conditions are equivalent:
\begin{enumerate}
    \item $T_{p^j+i-1}$ is a self-extension of $St_{j}=T_{p^j-1}$ over $U$;
    \item $T_{p^j+i-1}$ is a self-extension of $St_{j}=T_{p^j-1}$ over $H$;
    \item $\dim_{\bk}T_{p^j+i-1}=2\dim_{\bk} St_j$. 
\end{enumerate}


\end{lemma}
\begin{proof}
Clearly, (1) implies (2) and (2) implies (3), so we prove that (3) implies (1).

Let $L_i$ be the simple $SL_2$-representation of highest weight $i$. Firstly, by \cite{BEO}*{Lemma~3.3} or \cite{AbEnv}*{Lemma~4.3.4}, $St_j\otimes L_i$, as an $SL_2$-representation, is tilting.
Hence $T_{p^j+i-1}$ is an $SL_2$-summand of $St_{j}\otimes L_i$.

Denote by $e_+$ a vector in the simple module $L_i$ of weight $i$ and by $e_-$ a vector of weight $-i$. Then $e_-$ spans a $U$-submodule and $e_+$ is a generator of $L_i$ over $U$. Thus we have a $U$-linear inclusion and surjection
$$St_{j}\simeq St_{j}\otimes e_-\;\hookrightarrow\; St_{j}\otimes L_i\;\tto\; St_{j}\otimes e_+\simeq St_{j},$$
which compose to zero, induced from the socle and top $\unit\hookrightarrow L_i\tto \unit$. If we assume condition (3), then to prove condition (a) it suffices to show that this inclusion and surjection remain an inclusion and surjection when we restrict the middle term to the summand $T_{p^j+i-1}$. Moreover, by duality it suffices to prove one of these claims.

To conclude the proof we thus show that the composite
$$T_{p^j+i-1}\subset St_{j}\otimes L_i\tto St_j$$
is surjective. Since $St_j=L_{p^j-1}$ is generated, as an $U$-representation, by its highest weight vector $v_+$, it suffices to show that this highest weight vector is in the image. This follows immediately, because $v_+\otimes e_+$, which is of weight $p^j+i-1$, belongs to $T_{p^j+i-1}$.
\end{proof}


\begin{corollary}
    \label{cor:self-ext1}
    The following conditions are equivalent on $l\in\mN$, for $E=C_p^r$.
    \begin{enumerate}
        \item $T_l$ is a self-extension of $S=St_{r-1}$ over $E$;
        \item $l=p^{r-1}+ap^i-1$ for $0\le i<r-1$ and $0<a<p$, or $l=2p^{r-1}-1$.
    \end{enumerate}
    In particular, there are $pr-p-r+2$ isomorphism classes of indecomposable modules in $\cT$ that are self-extensions of $S$.
\end{corollary}
\begin{proof}
    This is an application of \Cref{lem:self-ext1} and Donkin's formula. 


Assume first that $p>2$. It follows from the dimension formula in \cite{STWZ}*{Section~2} that the only $SL_2$-tilting modules of dimension $2p^{r-1}=2\dim St_{r-1}$ are $T_l$ for $l$ as in (2). The conclusion thus follows from \Cref{lem:self-ext1}.

For $p=2$, the same dimension formula shows that the only $SL_2$-tilting modules of dimension $2^r=2\dim St_{r-1}$ are 
$$T_{2^a+2^{i_1}+\cdots+2^{i_b}-1}$$
with $a+b=r$ and $a>i_1>i_2>\cdots$. By the results in \Cref{sec:supp}, a necessary condition for such modules to be self-extensions of $St_{r-1}$ over $E$ is that they have support contained in a singleton which in turn requires $a\ge r-1$ by \Cref{PropSupp}. These cases yield precisely $T_l$ with $l$ as in (2), so the conclusion follows as for $p>2$.
\end{proof}


\begin{remark} \label{rem::extensions}
    We can derive more extensions from the above results. For example
    \begin{enumerate}
        \item The modules $T_{mp},\dots,T_{mp+p-2}$ are self-extensions of $T_{mp-1}$ over $E=C_p^2$, for any $1\le m<p$. Indeed, by Donkin's formula, we can reduce this to the case $m=1$, which is contained in \Cref{cor:self-ext1}.
        \item That $T_l$, with $l$ as in \Cref{cor:self-ext1}(2), is a self-extension of $St_{r-1}$ remains true over any~$C_p^{r'}$.
    \end{enumerate}
\end{remark}

\begin{remark}\label{rem-ex}
\begin{enumerate}
    \item The self-extensions of $S$ in \Cref{cor:self-ext1} for the cases `$a=1$' are of the form
    $$T_{p^{r-1}+p^i-1}\;\simeq\; S\otimes V^{(i)}.$$
    For $p=2$, these are all the self-extensions in $\cT$, but not for $p>2$. In other words, for $p>2$, there are self-extensions of $S$ in $\cT$ which do not come from
    $$\Ext^1_E(\unit,\unit)\;\xrightarrow{S\otimes -}\;\Ext^1_E(S,S),$$
    see \Cref{ex-moreex}.
    \item For $r=2$, all self-extensions of $S$ in $\Rep E$ are (restrictions of) tilting modules. For $r>2$ this is no longer the case.
\end{enumerate}

\end{remark}







\subsection{Tensor powers of the Steinberg modules}
Recall the tensor ideal $\cT_r$ in the category $\cT\subset \Rep E$ of restrictions of $SL_2$-tilting modules from \Cref{SecFF}.
\begin{lemma}\label{Lem:TOT}
The ideal $\cT_r\subset\cT$ comprises the direct sums of direct summands of non-empty tensor products of $S=St_{r-1}$ and $\Omega S$. More precisely:
\begin{enumerate}
    \item If $p=2$, then the isomorphism classes of indecomposable $E$-modules appearing as summands in $S^{\otimes 3}$, resp. $S^{\otimes 4}$, are
    $$\{T_{2i-1}\mid 2^{r-2}\le i\le 2^{r-1}\}\quad\mbox{resp.}\quad \{T_{2i}\mid 2^{r-2}\le i< 2^{r-1}\}.$$
    \item If $p>2$, then the isomorphism classes of indecomposable $E$-modules appearing as summands in $S^{\otimes p+1}$, resp. $\Omega(S^{\otimes p+1})$, are
    $$\{T_{2i}\mid \frac{p^{r-1}-1}{2}\le i\le \frac{p^{r}-1}{2}\}\quad\mbox{resp.}\quad \{T_{2i+1}\mid \frac{p^{r-1}-1}{2}\le i< \frac{p^{r}-1}{2}\}.$$
\end{enumerate}

\end{lemma}
\begin{proof}
    All computations below are over $SL_2$.

Consider first $p=2$. In this case $S=T_{2^{r-1}-1}$ and $S^{\otimes 2}=T_{2^{r}-2}$. It then follows from Donkin's tensor product theorem that, up to multiplicities,
    $$S^{\otimes 3}\;\simeq\; \bigoplus_{0\le i_j\le 1} \left(T_{1+2i_0}\otimes T_{1+2i_1}^{(1)}\otimes \cdots\otimes T_{1+2i_{r-1}}^{(r-1)}\right).$$
    By considering the highest weight of each summand if follows that each $T_j$, with $j$ odd and $2^{r-1}-1\le j\le 2^r-2$, is a summand of $S^{\otimes 3}$.

    The above summands of $S^{\otimes 3}$ can, again by Donkin's formula, be written as
    $$T_1\otimes T_{a_1}^{(1)}\otimes \cdots \otimes T_{a_{r-1}}^{(r-1)},$$
where each $a_j$ is either $1$ or $2$. Taking the tensor product of this tilting module with $S$ yields a summand
    $$T_2\otimes T_{a_1'}^{(1)}\otimes \cdots\otimes  T_{a_{r-1}'}^{(r-1)},$$
    where $a'_j=3-a_j$ (in other words, $a'_j=2$ when $a_j=1$ and vice versa).
The above tilting modules are precisely $T_j$ for $j$ even and $2^{r-1}-1\le j\le 2^r-2$, and these thus appear as summands in $S^{\otimes 4}$.


That no other summands appear follows from parity, highest weight and the tensor ideal structure.

Now consider $p>2$. A direct computation shows that
$$T_{p-1}^{\otimes 2}\;\simeq\; \bigoplus_{a=0}^{(p-1)/2}T_{p-1+2a}.$$
It then follows from direct highest weight consideration that the summands in $T_{p-1}^{\otimes i+1}$ are precisely $T_{p-1+2a}$ for $0\le a \le i(p-1)/2$.
It thus follows that $S^{\otimes (p+1)}$ has summands (which are thus tilting modules)
$$T_{p-1+2a_0}\otimes T_{p-1+2a_1}^{(1)}\otimes \cdots\otimes T_{p-1+2a_{r-1}}^{(r-1)}$$
for all $0\le a_j\le p(p-1)/2$. The highest weights of these tilting modules range over
$$p^{r-1}-1+2a,\quad 0\le a\le p\frac{p^{r-1}-1}{2}.$$
The result for $\Omega(S^{\otimes p+1})$ then follows from \Cref{prop:Omega-Ti}.
\end{proof}




\subsection{The annihilator of the Steinberg module}
We investigate the action of elements of the annihilator ideal $\Ann_{\bk E}S$ of the Steinberg module $S=St_{r-1}$ in the group algebra $\bk E$.

\begin{lemma}\label{Lem:UseSL2}
    For $i,j\in\mN$ with $j\ge i$, we have an epimorphism $\Delta_j\tto \Delta_j$ of $U$-representations, so in particular of $E$-representations. The kernel of the morphism is spanned by $j-i$ weight vectors of lowest weights.
\end{lemma}
\begin{proof}
    We can easily describe the dual monomorphism
    $$\bk[x,y]_i=\nabla_i\hookrightarrow \nabla_j=\bk[x,y]_j,\quad x^{i-a}y^a\mapsto x^{i-a}y^{a+j-i},$$
    from which the result follows.
\end{proof}

For the following lemma, recall our conventions from \ref{basis}.
\begin{lemma}\label{Lemxi0}
    Fix $\xi\in\Ann_{\bk E}S$. Consider $t\in\mZ_{>0}$ and $a_i\in\mN$ for $1\le i\le t$. The element $\xi$ sends $e_1\otimes\cdots \otimes e_1$ in $\otimes_{i=1}^tSt_1^{(a_i)}$ to a linear combination of
        $$e_{b_1}\otimes e_{b_2}\otimes \cdots\otimes e_{b_t}\quad\mbox{with}\quad \sum_{i=1}^t (b_i-1)p^{a_i}\ge p^{r-1}.$$
    %\begin{enumerate}
       % \item The element $\xi$ acts trivially on $e_1\otimes\cdots \otimes e_1$ in %$\otimes_{i=1}^tSt_1^{(a_i)}$ if $(p-1)\sum_{i}p^{a_i}<p^{r-1}$.
        %\item 



    %\end{enumerate}
\end{lemma}
\begin{proof}
 We set $a:=(p-1)\sum_{i=1}^tp^{a_i}$, the maximal possible value of $\sum_{i=1}^t (b_i-1)p^{a_i}$. Using the highest weight structure of $\Rep SL_2$, we know that there is an $SL_2$-linear morphism 
    $$\Delta_a\;\to\; \bigotimes_{i=1}^tSt_1^{(a_i)}$$
    that sends the highest weight vector of $\Delta_a$ to $e_1\otimes \cdots \otimes e_1$.


    If $a\le p^{r-1}-1$, it follows that $\xi\in \Ann S$ acts trivially on the quotient $\Delta_a$ of $S=\Delta_{p^{r-1}-1}$, see \Cref{Lem:UseSL2}. Hence $\xi$ acts trivially  on $e_1\otimes\cdots \otimes e_1$ as predicted.

    Conversely, assume $a\ge p^{r-1}$. It now follows from \Cref{Lem:UseSL2} that $\xi$ sends the highest weight vector of $\Delta_a$ to vectors of weights strictly below $a-2(p^{r-1}-1)$, from which the claim follows.
\end{proof}



\subsubsection{}\label{defxi}Since $S\otimes St_1^{(r-1)}\simeq \bk E$, there is a unique $\xi\in\bk E$ for which 
$$\xi(e_1\otimes \cdots \otimes e_1)\;=\;e_1\otimes \cdots\otimes e_1\otimes e_2\;\in\; S\otimes St_1^{(r-1)}.$$
Since $S$ is cyclic, $\xi$ is in $\Ann_{\bk E}S$.

\begin{lemma}\label{Powxi}
    Let $\xi\in\bk E$ be as in \ref{defxi}.
    \begin{enumerate}
        \item For every $1\le i\le p$, we have
        $$\xi^{i-1}(e_1\otimes \cdots \otimes e_1)\;=\; e_1\otimes \cdots\otimes e_1\otimes e_i\;\in\; S\otimes St_1^{(r-1)}.$$
        \item For every $0\le i<r-1$ and $a,b\in\mN$, we have
        $$\xi(\rad^a S\otimes \rad^b St_1^{(i)})\;\subset\; \rad^{a+1} S\otimes \rad^{b+1} St_1^{(i)}$$
    \end{enumerate}
\end{lemma}
\begin{proof}
    Part (1) can be proved by induction on $i$, since we can interpret, via \ref{EndS1}, the submodule of $St_1^{(r-1)}$ spanned by $\{e_2,\ldots, e_p\}$ as the quotient $St_1^{(r-1)}/\bk e_p$, where $e_{l+1}$ in the former corresponds to the equivalence class of $e_l$.

    It is a general property that for two $E$-representations $U_1,U_2$ and $\eta\in \Ann(U_1)\cap \Ann(U_2)$, 
    $$\eta (\rad^a U_1\otimes \rad^b U_2)\;\subset\;\rad^{a+1} U_1\otimes \rad^{b+1} U_2.$$
Indeed, without loss of generality we can assume that $U_1\not=0$, so that $\eta\in \rad \bk E$. It then follows that
$$\Delta(\eta)\;=\; \eta\otimes 1+1\otimes \eta+ \sum_i\eta^1_i\otimes \eta^2_i$$
    with $\eta^j_i\in \rad \bk E$. Applying this expression to $U_1\otimes U_2$ demonstrates the claim.



    Since $\xi$ acts trivially on $S$, it also acts trivially on its quotient $St_1^{(i)}$, for $i\le r-2$. 
\end{proof}



\section{Extensions between specific uniserial modules} \label{sec:ext}

The main goal of \Cref{sec::subcategories} below is to compute the image of the map
\begin{equation} \label{eq:psi}
\omega_{U,W} = S\o-: \Ext^1_E( U,W)\to\Ext^1_E(S\o U,S\o W)    
\end{equation}
for $S=St_{r-1}$ the highest Steinberg module in $\Rep E=\Rep C_p^r$, determined by $\ulambda\in\mA^r_f$ as before, and for modules $U,W$ in a full abelian subcategory $\cC\subset\Rep E$ that is equivalent to $\Rep C_p$ such that $S\o Q\simeq\kk E$, for $Q$ the indecomposable projective in $\cC$. 

The description of the image of $\psi$ will be used in subsequent sections. As an immediate consequence, we will also obtain the following result:

\begin{theorem} \label{thm:S-tensor-ext-uniserials} Let $U$ be a uniserial $p$-dimensional representation with $\blambda\not\in\supp(U)$. Then for any extension $X$ of two quotients of $U$, we have $S\otimes X\in\cT$.
\end{theorem}

\begin{proof} See \Cref{cor:S-tensor-ext-Ud-Ue}.
\end{proof}


\subsection{Parametrising extensions} In this subsection, we describe the extensions in the source of $\psi$, see \Cref{eq:psi}.

To alleviate notation, we fix a generator $1_X=1$ for any cyclic module $X$. For any uniserial module $U$, such as $St_1$, we additionally fix an endomorphism $z_U=z$ with a one-dimensional kernel. By abuse of notation, this allows us to denote a basis of $U$ by 
 $$(z_U^i(1_U))_{0\le i< \dim U}=(z_U^i)_{0\le i< \dim U}=(z^i)_{0\le i< \dim U}.$$ 

\subsubsection{} Fix some $1\le k\le r$. Assume $\cC\subset\Rep E$ is a topologising subcategory equivalent to $\Rep C_p^{r-k}$. Let $Q$ be the indecomposable projective object of $\cC$. Assume also $\cC'\subset\Rep E$ is another topologising subcategory such that $\cC'\simeq\Rep C_p^k$, and let $Q'$ be its indecomposable projective object. Assume $Q\o Q'\simeq\kk E$ in $\Rep E$. 

We will write $\Omega_{\cC}$ for the shift inside $\cC$.

\begin{remark} The assumptions on $\cC$ imply that it is the full subcategory on those objects of $\Rep E$ which are subobjects of $Q^m$ for some $m\ge1$, or equivalently, quotient objects of $Q^m$ for some $m\ge1$.
Hence, $\one\in\Rep E$ is the unique simple object of $\cC$ up to isomorphism.
\end{remark}

\begin{example} (a) Let $\cC$ be the full subcategory on those modules on which $X_1,\dots,X_k\in\kk E$ all act as zero. Then $\cC$ satisfies the above assumptions. Furthermore, we could let $\cC'$ be the full subcategory on those modules on which $X_{k+1},\dots,X_r\in\kk E$ all act as zero

(b) Let $\cC$ be the full abelian (or equivalently, topologising) subcategory generated by $St_{r-k}$. Then $\cC$ satisfies the above assumptions. For $\cC'$ we can take the full abelian subcategory generated by $St_{1}^{(r-k)}\otimes \cdots St_1^{(r)}$.
\end{example}



\begin{definition} For any $m\ge1$ and any epimorphism $\pi:Q^m\to U$ in $\cC$, we define two subspaces of $Q^m\o Q'$,
$$
M_\pi:=\ker\pi \o Q'+Q^m\o \rad(Q') , 
$$
$$
\text{and}\quad
K_\pi:=\ker\pi\o\rad(Q')+Q^m\o\rad^2(Q') .
$$
\end{definition}
The following results can be viewed as a concrete realisation of the Künneth formula
$$
\Ext^1_E(U,W)\;\simeq\;\left(\Ext^1_{\cC}(U,W)\otimes \Hom_{\cC'}(\unit,\unit)\right)\oplus \left(\Hom_{\cC}(U,W)\otimes \Ext^1_{\cC'}(\unit,\unit)\right).
$$

\begin{lemma} \label{lem::extensions-from-subcategory} For any $U\in\cC$, there is a morphism $\pi_U\in\stHom(\Omega U,\Omega_{\cC} U\oplus U^k)$ such that the induced map
$$
\stHom(\Omega_{\cC}U\oplus U^k,W)\to \stHom(\Omega U,W),\quad
f\mapsto f \pi_U ,
$$
is an isomorphism for all $W\in\cC$.

More concretely, assume $\pi:Q^m\to U$ is an epimorphism for some $m\ge1$, and set $M:=M_\pi$ and $K:=K_\pi$. Then $M$ is stably isomorphic to $\Omega U$, $M/K\simeq\ker\pi\oplus U^k$, and $\pi_U$ can be taken to be the natural epimorphism $M\to M/K$.
\end{lemma}

\begin{proof}

By the assumptions, $\ker\pi$ is stably isomorphic to $\Omega_\cC U$ in the stable category of $\cC$. We have a short exact sequence
$$
0\to M\to Q^m\o Q'\xrightarrow{\pi\o (Q'\twoheadrightarrow\one)} U\to 0
$$
with $M=\ker\pi \o Q'+Q^m\o \rad(Q')$. Hence $M$ is stably isomorphic to $\Omega U$.

Under the equivalence $\cC'\simeq\Rep C_p^k$, $Q'$ can be viewed as $\kk[X_1,\dots,X_k]/(X_i^p)$. Let $z_i$ be the endomorphism of $Q'$ sending $1\mapsto X_i$. By assumption, $Q\o Q'\simeq\kk E$. Hence we can pick $(\eta_i)_i\in\kk E$ such that $\eta_i(1\o 1)=1\o X_i$ in $Q\o Q'$ for all $i$. Then $\eta_i|_{Q\o Q'}=Q\o z_i$, so 
$$
\sum \eta_i(M)
= \sum \eta_i(\ker\pi\o Q' + Q^m\o \rad(Q'))
= \ker\pi\o \rad(Q') + Q^m\o\rad^2(Q')
= K
.
$$

Also, $\eta_i Q\simeq \eta_i(Q\o \soc(Q'))\simeq 0$ for all $i$. This implies $\eta_i|_W=0$ for all $W\in\cC$ and all $i$. This means any morphism in $\Hom(M,W)$ factors uniquely through $M/K$. 

To describe $M/K$, note that the intersection of the subspaces $\ker\pi\o Q'$ and $Q^m\o\rad(Q')$ of $Q\o Q'$ is $\ker\pi\o\rad(Q')$. Hence, their images intersect trivially already in the quotient space $Q\o Q' / (\ker\pi\o\rad(Q')$, which implies that $M/K$ is isomorphic to
$$
\frac{\ker\pi\o Q'}{(\ker\pi\o\rad(Q')+Q^m\o\rad^2(Q'))\cap( \ker\pi\o Q')}
\oplus
\frac{Q^m\o\rad(Q')}{\ker\pi\o\rad(Q')+Q^m\o\rad^2(Q')} ,
$$
which in turn is isomorphic to
$$\ker\pi\o \frac{Q'}{\rad(Q')}
\oplus
\frac{Q^m}{\ker\pi}\o\frac{\rad(Q')}{\rad^2(Q')}
\cong \ker\pi \oplus U^k ,
$$
as asserted. 
\end{proof}

\begin{corollary} \label{cor::R-o-Hom} In the situation of \Cref{lem::extensions-from-subcategory}, let $R\in\Rep E$ be any module such that $R\o Q$ is projective in $\Rep E$. Consider $U,W\in\cC$ and the map
$$
\psi:R\o-:\stHom(\Omega U,W)\to\stHom(R\o\Omega U,R\o W). 
$$
Then with $\pi_U$ as in \Cref{lem::extensions-from-subcategory}, the induced map
$$
\stHom_\cC(\Omega_{\cC}U\oplus U^k,W)\to \im(\psi),\quad
f\mapsto R\o f \pi_U ,
$$
is an epimorphism.
\end{corollary}

We can now specialize $k$ to $r-1$ to obtain concrete descriptions of $\im(\psi)$. For all $1\le d\le p$, we pick a representative $U_d$ for the isomorphism class of indecomposable objects of dimension $d$ in $\cC\simeq\Rep C_p$. Note that $Q\simeq U_p$ and there are short exact sequences
$$
0\to U_{p-d}\to U_p\to U_d\to 0
$$
for all $d$, so $\Omega_\cC U_d\simeq U_{p-d}$.

For all $1\le d,e\le p$, we define an index set
$$
I_{d,e} := \{m\in\mZ\mid \max(0,e-d)\le m <\min(p-d,e)\} .
$$

\begin{lemma} \label{lem::Rep-Cp-stable-homs} For all $1\le d,e\le p$, the maps $(1\mapsto z^m)_{m\in I_{d,e}}$ correspond to a basis of $\stHom_\cC(U_d,U_e)$. 
\end{lemma}

\begin{proof} The maps $(1\mapsto z^m)$ as above for $\max(0,e-d)\le m\le e-1$ form a basis for $\Hom(U_d,U_e)$. Those with $m\ge p-d$ factor via the indecomposable projective $U_p$ in $\cC$. On the other hand, any projective object $Q$ in $\cC$ is a direct sum of copies of the uniserial module $U_p$, any map from $U_d$ to $Q$ has its image in $\soc_d(Q)=\rad_{p-d}(Q)$, so any map from $U_d$ to $U_e$ via $Q$ has its image in $\rad_{p-d}(U_e)$. This means the maps $(1\mapsto z^m)$ with $m\ge p-d$ span the space of morphism that factor via a projective object. This implies the assertion.
\end{proof}

\begin{definition} 
For any $1\le d\le p$ and $U:=U_d$, we fix a surjection $\pi:U_p\to U$ and an epimorphism $\pi_U: M_\pi\tto M_\pi/K_\pi\simeq \Omega_\cC U_d\oplus U_d^{r-1}\simeq U_{p-d}\oplus U_p^{r-1}$ as in \Cref{lem::extensions-from-subcategory}.
Let $\rho_0:U_{p-d}\oplus U_d^{r-1}\tto U_{p-d}$ and $(\rho_i:U_{p-d}\oplus U_d^{r-1}\tto U_d)_{1\le i\le r-1}$ be the structural projections of the direct sum.
We set
$$
f_{d,e,i,m} := (1\mapsto z^m) \rho_i \pi_U : M_\pi\to U_e .
$$
for all $1\le e\le p$, $0\le i\le r-1$, and $m\in\begin{cases} I_{p-d,e} & i=0 \\ I_{d,e} & 1\le i\le r-1 \end{cases}$.
\end{definition}

\begin{corollary} \label{lem::parametrization-stable-hom} If $k=r-1$, then in the situation of \Cref{lem::extensions-from-subcategory} and \Cref{cor::R-o-Hom} with $U=U_d$ and $W=U_e$ in $\cC\simeq\Rep C_p$, the space $\im(\psi)$ is spanned by the maps induced by the maps $(R\o f_{d,e,0,m})_{m\in I_{p-d,e}}$ and $(R\o f_{d,e,i,m})_{1\le i\le r-1,m\in I_{d,e}}$ just defined.
\end{corollary}

\begin{proof} This follows immediately from \Cref{cor::R-o-Hom} with \Cref{lem::Rep-Cp-stable-homs}.
\end{proof}



\subsection{Tensor products with Steinberg modules} \label{sec::subcategories}

\subsubsection{}\label{Qxi} Recall $S:=St_{r-1}=St\o St^{(1)}\o\dots St^{(r-2)}$. We fix a $Q\in\Rep E$ that generates a full topologising subcategory equivalent to $\Rep C_p$ and that satisfies $S\o Q\simeq\kk E$.



Recall that for any uniserial module $U$, such as $St$ and $Q$, we have fixed a generator $1_U=1$ and an endomorphism $z_U=z$ with a one-dimensional kernel, yielding a basis $(z_U^i)_{0\le i<\dim U}=(z^i)_{0\le i< \dim U}$. 

Let $z_i:=St\o\dots\o z\o St^{(i)}\o\dots\o St^{(r-2)}$ be the corresponding endomorphism of $S$ for all $1\le i\le r-1$. Set $\psi'_i:=z_{i+1}^{p-1}\dots z_{r-1}^{p-1}$ for all $0\le i\le r-1$, so $\psi'_{r-1}=\id_S$.


As $S\o Q\simeq\kk E$, we can pick $\xi\in\kk E$ such that $\xi(1\o 1)=1\o z$ in $S\o Q$. Then $\xi|_{S\o Q}=S\o z$ and $\xi|_S=0$. We fix such a $\xi$.


\begin{remark} It follows immediately that any $Q$ as in \ref{Qxi} is uniserial of dimension $p$, and its support does not contain the one point which is in the support of $S$ (see \Cref{sec:supp}).
\end{remark}

We will use the following idea for cyclic modules like $S$:


\begin{lemma}
Let $M$ be a cyclic $E$-module with an endomorphism $f$ and $i\in\mZ_{>0}$. Then $f\in\rad^i(\End(M))$ if and only if $\im(f)\subset\rad^i(M)$.
\end{lemma}

\begin{proof}
Assume $\im(f)$ lies in $\rad^i(M)$. Let $m$ be a generator of $M$. Then there is an element $y\in\rad^i(\kk E)$ such that $f(m)=ym$. This implies $f=y|_M$. Furthermore, $y$ is a sum of $i$-fold products of elements from $\rad(\kk E)$. Elements from $\rad(\kk E)$ are nilpotent, hence their action on $M$ lies in the radical of $\End(M)$. This means $f$ lies in $\rad^i(\End(M))$.

Now assume $f$ lies in $\rad^i(\End(M))$. Then $f$ is a sum of $i$-fold products of elements from $\rad(\End(M))$. As $M$ is cyclic, each element in $\rad(\End(M))$ is given by the action of an element in $\kk E$, which will have to lie in $\rad(\kk E)$, as otherwise, it would be invertible in $\kk E$. This means $\im(f)$ lies in $\rad^i(M)$.
\end{proof}

One of the most important properties of the Steinberg module $S$ for our purposes is the following result. We are interested in $S\otimes S$ as we will realise $S\otimes \Omega X$, for the relevant $X$, as a submodule in $S\otimes S\otimes X$. $\xi$ is as in \Cref{Qxi}.


\begin{lemma} \label{lem::xi-S-S}
There are automorphisms $(u_i)_{0\le i\le r-2}$ of $S$ such that
$$
\xi|_{S\o S} \in \sum_{0\le i\le r-2} u_i \psi'_i \o z_{i+1} + S\o\rad^2(\End(S)) .
$$    
\end{lemma}

\begin{proof}
As a special case \Cref{Lemxi0} we have
$$
\xi(1\o 1) \in \sum (z_1^{a_0}\dots z_{r-1}^{a_{r-2}}\o z_1^{b_0}\dots z_{r-1}^{b_{r-2}}) (1\o 1)
$$
for those tuples $(a_i)_i, (b_i)_i$ in $\{0,\dots,p-1\}$ that satisfy
$$
\sum_{0\le i\le r-2} (a_i+b_i) p^i  \ge p^{r-1} .
$$
The tuples corresponding to elements in $S\o\rad^2(S)$ are those with $\sum b_i>1$. The remaining tuples satisfying the condition correspond exactly to elements $(m_i(z_1,\dots,z_i) \psi'_i\o z_{i+1})(1\o1)$ for some $i$ and some monomials $m_i$. Hence,
$$
\xi(1\o1) \in \sum_{0\le i\le r-2} (u_i(z_1,\dots,z_i) \psi'_i \o z_{i+1})(1\o1) + S\o\rad^2(S)  
$$
for some polynomials $u_i$.

Assume, in order to find a contradiction, that $u_j$ has constant term $0$ for some $j$.  Consider the endomorphism 
$$
f := (z_1\dots z_j)^{p-1}\o (z_1\dots z_j z_{j+2}\dots z_{r-1})^{p-1} z_{j+1}^{p-2}
$$
of $S\o S$. As $\im(z_{St^{(i)}}^{p-1})\simeq\one$ and $\im(z_{St^{(i)}}^{p-2})\simeq V^{(i)}$, the image of $f$ is isomorphic to $St^{(j)}\o\dots\o St^{(r-2)}\o V^{(j)}$, but the above formula for $\xi$ and the assumption that $u_j$ has constant term zero imply $\xi|_{S\o S}\, f=0$. So $\xi$ acts as zero on $St^{(j)}\o\dots\o St^{(r-2)}\o V^{(j)}$. But then $\xi$ acts as zero on $V^{(r-1)}$, which is a subquotient of the latter module, as can be seen via the inclusions and surjections of $SL_2$-modules 
$$
St_1^{(j)}\otimes St_1^{(j+1)}\otimes \cdots \otimes St^{(r-2)}_1\otimes V^{(j)}\simeq T_{p^{r-1-j}}^{(j)}
\;\hookleftarrow\; \Delta_{p^{r-1-j}}^{(j)} \;\tto\;  L_{p^{r-1-j}}^{(j)}\simeq V^{(r-1)} .
$$
$\xi$ acting as zero on $V^{(r-1)}$ implies that $\xi$ sends $St^{(r-1)}$ to its second radical. But then it would follow that $\xi$ sends 
$$\kk E\simeq S\o St^{(r-1)}\simeq S\otimes Q$$ to its second radical, which is a contradiction, as $\xi_{S\o Q}(1\o1)=1\o z$ by assumption.



Hence, the constant terms of all $u_i$ are non-zero, so they are automorphisms of $S$.
\end{proof}

\begin{definition}
Set $$\psi_{r-1}:=\psi'_{r-1}=\id_S,\quad \psi_i:=u_i \psi'_i$$ with $u_i$ as in \Cref{lem::xi-S-S} for all $0\le i\le r-2$.
\end{definition}

\begin{corollary} \label{lem::image-xi-d} For all $1\le d\le p$,
$$
\xi^d|_{S\o Q\o S} \in \sum_{0\le i\le r-2} (\psi_i\o \rad^{d-1}(\End(Q))\o z_{i+1}) + S\o \rad^d(\End(Q))\o S + S\o Q\o \rad^2(\End(S)) .
$$
\end{corollary}

\begin{proof} \Cref{lem::xi-S-S} proves the case $d=1$. The cases $d>1$ follow by induction in $d$ using that $\psi_i\psi_j=0$ for all $0\le i,j\le r-2$.
\end{proof}

Now let $\cC$ and $\cC'$ be the full abelian subcategories of $\Rep E$ generated by $Q$ and $Q':=S$, respectively. Then $\cC\simeq\Rep C_p$ and $\cC'\simeq\Rep C_p^{r-1}$.


\begin{lemma} \label{lem::s-o-om-c-u} For any indecomposable $U\in\cC$,  $S\o\Omega_\cC U$ is stably isomorphic to $\Omega(S\o U)$.
Moreover, the stable isomorphism can be realised as follows: pick an epimorphism $\pi:Q\to U$ and set $d:=\dim(U)$. Then with $M=M_\pi\subset Q\o S$ as in \Cref{lem::extensions-from-subcategory}, the vector $\xi^d(1\o1\o1)$ in $S\o Q\o S$ lies in the submodule $S\o M$ and generates a direct summand isomorphic to $S\o\ker\pi$ with a projective complement in $S\o M$.
\end{lemma}

\begin{proof}
We have a commutative diagram
$$
\begin{tikzcd}[column sep=2cm]
S\o\Omega U
    \ar[r]
    \ar[d]
&
S\o Q\o S
    \ar[r,"S\o(1\o1 \mapsto 1)"]
    \ar[d,"S\o(1\o1 \mapsto 1)"]
&
S\o U
    \ar[d,"="]
\\
S\o\ker\pi
    \ar[r]
&
S\o Q
    \ar[r,"S\o\pi"]
&
S\o U
\end{tikzcd}
$$
where the rows are exact, and the left vertical arrow is determined by the remaining diagram. The middle vertical arrow splits, as $S\o Q$ is projective, and we may assume the splitting sends $1\o1\mapsto 1\o1\o1$. This induces a splitting of the left vertical arrow. As $S\otimes \ker\pi$ is generated by $\xi^d(1\o1)$ inside $S\o Q$, the image of $S\o\ker\pi$ under the splitting of the left vertical arrow is generated by $\xi^d(1\o1\o1)$.
\end{proof}

Recall that we have picked representatives $(U_d)_d$ for the isomorphism classes of indecomposable objects in $\cC$, labeled by their dimension $d$. Note that if $\pi:Q\to U_d$ is an epimorphism, then $\ker\pi\simeq U_{p-d}$. For all $1\le d,e\le p$, we consider the map 
$$
\omega_{d,e}:=S\o- : \stHom(\Omega U_d,U_e)\to\stHom(\Omega(S\o U_d),S\o U_e)\simeq\stHom(S\o U_{p-d},S\o U_e).
$$


Recall that, for all $1\le d,e\le p$,
$$
I_{d,e} = \{m\in\mZ\mid \max(0,e-d)\le m\le \min(p-d,e)-1\} .
$$


\begin{proposition} \label{prop::im-omega} $\im(\omega_{d,e})$ is spanned by the set $F_1\cup F_2$, where 
$$
F_1 := \{S\o (1\mapsto z^m)\}_{m\in I_{p-d,e}} 
\quad\text{and}\quad
F_2 := \begin{cases}
\{ \psi_i\o z^{d-1} \}_{0\le i\le r-2} & d=e \\
\emptyset & d\neq e
\end{cases}.
$$
Any non-zero element in $\im(\omega_{d,e})$ equals one of the elements in $F_1\cup F_2$ up to an automorphism of $S\o U_{p-d}$ and of $S\o U_e$.
\end{proposition}

\begin{proof} Set $U=U_d$ and $W=U_e$. Then we are in the set-up of \Cref{lem::parametrization-stable-hom} with $\im(\omega_{d,e})=\im(\psi)$. Using \Cref{lem::parametrization-stable-hom} and \Cref{lem::s-o-om-c-u}, all we have to show is that $(S\o f_{d,e,\ell,m})|_{\langle \xi^d(1\o1\o1) \rangle}$ is stably zero or one of the maps in $F_2$ for all $1\le \ell\le r-1$ and $m\in I_{d,e}$, depending on $d$ and $e$. Using \Cref{lem::image-xi-d}, we know that
$$
\xi^d(1\o1\o1) \in \sum_i (1\o\eta^{d-1})(\psi_i\o Q\o z_{i+1})(1\o1\o1) + S\o\rad^d(Q)\o S + S\o Q\o\rad^2(S).
$$
for $\eta\in\kk E$ such that $\eta(1\o1)=z\o1$ in $Q\o S$. Using the concrete formula for $f_{d,e,\ell,m}$ shows then that
$$
(S\o f_{d,e,\ell,m}) (\xi^d(1\o1\o1)) \in (1\o\eta^{d-1}) (\psi_{\ell-1}\o z^m)(1\o1)
= (\psi_{\ell-1}\o z^{m+d-1})(1\o1)
\quad\in S\o U_e
$$
which is $0$ as soon as $m>e-d$. This is true, in particular, if $d>e$. If $d\le e$, then the only non-zero cases correspond to $m=e-d$ and satisfy
$$
(S\o f_{d,e,\ell,e-d})( \xi^d(1\o1\o1) ) \in (\psi_{\ell-1}\o z^{e-1})(1\o1) \kk ,
$$
which yields the desired result if $d=e$. Finally, if $d<e$, then the map $U_{p-d}\to U_e, 1\mapsto z^{e-1},$ factors through the indecomposable projective $U_p$ in $\cC$. Hence, the map $S\o f_{d,e,\ell,e-d}$ viewed as a map from $\Omega(S\o U_p)\simeq S\o U_{p-d}$ to $S\o U_e$ is stably zero in this case, too. This shows the assertions.
\end{proof}


We can now identify the extensions that form the spanning set in \Cref{prop::im-omega}.

\begin{lemma} \label{lem::S-Ud}
For any $1\le d\le p$, we have isomorphisms
$$ S\o U_d \simeq S\o T_{d-1}^{(r-1)}\simeq T_{dp^{r-1}-1} .
$$    
\end{lemma}

\begin{proof} The second isomorphism is an application of Steinberg's tensor product theorem / Donkin's formula.

For the first isomorphisms, consider the map
$$
f: \kk E\simeq S\o U_p \to S\o T_{d-1}^{(r-1)}, \quad 1\o 1\mapsto 1\o 1.
$$
It is surjective, as the module on the right-hand side is a quotient of $S\o T_{p-1}^{(r-1)}\simeq S\o St^{(r-1)}\simeq\kk E$, so it is cyclic. We claim that $f \xi^d|_{S\o U_p}=0$. Indeed, the claim follows from noting that 
$$
\xi|_{S\o T_{d-1}^{(r-1)}} \in S\o\rad\End(T_{d-1}^{(r-1)}),
$$
as $\xi|_S=0$ and $\xi\in\rad(\kk E)$. From the claim it follows that $f$ factors through $S\o (U_p/z^d U_p)\simeq S\o U_d$. A dimension count then confirms that we have constructed an isomorphism as desired.
\end{proof}

\begin{lemma} \label{lem::identify-extensions}
In the setting of \Cref{prop::im-omega}, the maps $(S\o(1\mapsto z^m))_{m\in I_{p-d,e}}$ in $F_1$ correspond to the modules $S\o(U_m\oplus U_{d+e-m})\simeq T_{mp^{r-1}-1}\oplus T_{(d+e-m)p^{r-1}-1}$, viewed as extensions via the short exact sequences
$$
S\o \Big(U_e\xrightarrow{1\mapsto(-1,z^{d-m})} U_m\oplus U_{d+e-m}
\xrightarrow{(1,0)\mapsto z^{d-m}, (0,1)\mapsto 1} U_d \Big)
$$
(with the conventions , $T_{-1}:=0$, $U_0:=0$, $1_{U_0}:=0$). Assuming $d=e$, the maps $(\psi_i\o z^{d-1})_{0\le i\le r-2}$ in $F_2$ correspond to the modules $S\o U_d\o V^{(i)}\simeq T_{dp^{r-1}+p^i-1}$, viewed as extensions via the short exact sequences
$$
S\o U_d\o\Big( 
\one \xrightarrow{1\mapsto z} V^{(i)}\xrightarrow{1\mapsto 1} \one \Big).
$$
\end{lemma}

\begin{proof} Using that by \Cref{lem::S-Ud}, $S\o U_d\simeq T_{dp^{r-1}-1}$ and, consequently, $S\o U_d\o V^{(i)}\simeq T_{dp^{r-1}+p^i-1}$, the given extensions are non-isomorphic as modules. As the orbits of the maps in $F_1\cup F_2$ under the action of the automorphism groups contain $\im\omega_{d,e}$, and as there are as many extensions as elements in $F_1\cup F_2$, the extensions and maps are in bijection.

To identify which extension corresponds to each map, we first observe that for all $m\in I_{p-d,e}$, the diagram
$$
\begin{tikzcd}[column sep=3cm]
U_{p-d}
    \ar[r,"{1\mapsto z^d}"] 
    \ar[d,"{1\mapsto z^m}"]
& U_p
    \ar[r,"{1\mapsto 1}"]
    \ar[d,"{1\mapsto (-z^{m-d},1)}"]
& U_d
    \ar[d,"="]
\\
U_e
    \ar[r,"{1\mapsto(-1,z^{d-m})}"]
& U_{m} \oplus U_{d+e-m}
    \ar[r,"{(1,0)\mapsto z^{d-m}, (0,1)\mapsto 1}"]
& U_d
\end{tikzcd}
$$
commutes, has exact rows, and the left square is a pushout. Tensoring the diagram with $S$ shows the desired correspondence for the maps in $F_1$. This also implies that the maps in $F_2$ are in bijection with the remaining extensions.

To relate the remaining extensions with the maps in $F_2$, we realise $V^{(i)}$ as the quotient of $St_1^{(i)}$ via the map $1\mapsto 1$, see \Cref{Lem:UseSL2}. 
We specialise $Q=St_1^{(r-1)}$, which is possible as $S\o St_1^{(r-1)}\simeq\kk E$. Note that the relation between a map in $F_2$ and the self-extension of $S$ it determines is independent of the choice of $Q$. 
It follows from \Cref{Powxi} that the morphism 
$$\bk E\simeq S\otimes St_1^{(r-1)}\;\to\; S\otimes V^{(i)},\quad 1\o 1\mapsto 1\o 1 ,$$
factors through the quotient $S\otimes V^{(r-1)}$. Indeed, using \Cref{Powxi}(1) it suffices to verify that 
$$
1\o z^2 =  \xi^2(1\o1) \in S\otimes St_1^{(r-1)}$$
is sent to zero, which is implied by \Cref{Powxi}(2).
It follows that there exists a commutative diagram (whose rows are short exact sequences) 
$$
\begin{tikzcd}[column sep=3cm]
S 
    \ar[r,"1\mapsto1\o z"] 
    \ar[d,"\psi",dashed] 
& S\o V^{(r-1)} 
    \ar[r,"s\o z^k\mapsto s \delta_{k,0}"] 
    \ar[d,"1\o1\mapsto1\o1"] 
& S \ar[d,"="] 
\\
S 
    \ar[r,"1\mapsto1\o z"] 
& S\o V^{(i)} 
    \ar[r,"s\o z^k\mapsto s \delta_{k,0}"]
& S
\end{tikzcd}\qquad,
$$
where $\psi$ is uniquely defined by the identity $\psi(1)\o z=\xi(1\o 1)$ in $S\o V^{(i)}$. Now \Cref{lem::xi-S-S} shows that $\psi=\psi_i$, which identifies the remaining extensions as asserted.
\end{proof}



Combining \Cref{prop::im-omega} and \Cref{lem::identify-extensions}, we obtain the following implications for \Cref{conj-a}:

\begin{corollary} \label{cor:S-tensor-ext-Ud-Ue} For all $1\le d,e\le p$ and any extension $X$ in $\Rep E$ of $U_d$ and $U_e$, $X$ lies in $\widetilde\cT$, i.e., $S\o X$ lies in $\cT$.
\end{corollary}

This proves \Cref{thm:S-tensor-ext-uniserials}, as for any uniserial $p$-dimensional representation $U$ with $\blambda\not\in\supp(U)$, $U\o S\cong\kk E$.


Specialising $d=e=1$ in \Cref{prop::im-omega}, we obtain the following result which will be relevant in \Cref{sec:Carlson} and \Cref{sec:Loewy}:

\begin{corollary} \label{cor:im-omega-1-1}
(a) $\im(\omega_{1,1})\subset\stHom(\Omega S,S)\simeq\stHom(S\o U_{p-1},S)$ is spanned by $(\psi_i\o f_0)_{0\le i\le r-1}$,  where $f_0:U_{p-1}\to\one$ is any epimorphism.

(b) Every non-zero element in $\im(\omega_{1,1})$ is (uniquely) of the form $u\psi_i \o f_0$ for some $0\le i\le r-1$ and $u\in \Aut(S)$.

(c) The stable morphism represented by $\psi_i\o f_0$ corresponds to the self-extension $S\o V^{(i)}$ of $S$ under $\Ext^1(S,S)\simeq \uHom(\Omega S,S)$. 

\end{corollary}


\section{Carlson modules}
\label{sec:Carlson}




\subsection{Statement of the results}

Fix $r\in\mZ_{>1}$. We set $E=C_p^r$, and take
$$\ulambda = (\lambda_1,\lambda_2,\ldots,\lambda_r)\,\in\,\mA_f^{r}(\bk),$$ defining an embedding of $E$ into $SL_2(\bk)$, which we use to interpret $T_i$ as $E$-representations. In particular, we consider $V=T_1$ and
\begin{equation}\label{Sp2}
    S:=St_{r-1}=T_{p^{r-1}-1}=St_1\otimes St_1^{(1)}\otimes \cdots\otimes  St_1^{(r-2)}.
\end{equation}

\subsubsection{}
Recall, see for instance \cite{Benson-vector-bundles}*{\S 1.10}, that for a finite group $G$, $d\in\mN$ and $\zeta\in H^d(G,\bk)$, we have the corresponding Carlson module $L_\zeta$. This is defined via a short exact sequence
$$0\to L_\zeta\to \Omega^d\unit\xrightarrow{\hat{\zeta}}\unit\to 0,$$
where we used $\zeta\mapsto \hat{\zeta}$ for the isomorphism $H^d(G,\bk)\simeq \uHom_G(\Omega^d\unit,\unit)$.
We point out that, contrary to \cite{Benson-vector-bundles}, we do not make an exception for $\zeta=0$, meaning that $L_0\simeq \Omega^d \unit$.

The following theorem, which is the main result of this section, `verifies \Cref{conj-a} for Carlson modules'.

\begin{theorem}\label{ThmCarlson}
    For any $d\in\mN$ and $\zeta\in H^d(E,\bk)$, the tensor product
    $S\otimes L_\zeta$ is, up to projective summands, either isomorphic to $0$, to $S$, to
    $$T_{p^r-p^{r-1}+p^i-1}\;=\; \Omega(S\otimes V^{(i)}),\quad\text{ for some }0\le  i\le r-2,$$
    or, if $p>2$, isomorphic to
    $$T_{p^r-2p^{r-1}-1}\;=\; \Omega(S\otimes V^{(r-1)}),\quad\mbox{or}\quad T_{p^{r}-p^{r-1}-1} \;=\;\Omega(S) .$$ 
\end{theorem}

\begin{corollary} \label{cor:Carlson} Any Carlson module is contained in $\widetilde\cT$.
\end{corollary}

\begin{remark}
    Each option in \Cref{ThmCarlson} actually occurs, as follows from the proof. %Note that, for $p=2$, the list in \Cref{ThmCarlson} contains two redundancies, since $S\otimes V^{(r-1)}$ is projective and~$\Omega(S)\simeq S$.
\end{remark}

\begin{example}\label{Exam:1}
We use the standard description of the cohomology rings of elementary $p$-groups, as recalled in \Cref{Carlson2} and \Cref{Carlsonodd} below.
   Using the isomorphism
        $$\chi:H^1(E,\bk)\;\xrightarrow{\sim}\; \mA^r, \quad \sum_{i=1}^r \mu_i y_i\mapsto (\mu_1,\mu_2,\ldots, \mu_r),$$
 for any non-zero $\zeta\in H^1(E,\bk)$, it follows from the definitions that, with notation for two-dimensional modules as in \ref{Sec2dim},
        $$ L_\zeta\;\simeq\; \Omega(V_{\chi(\zeta)})\quad\mbox{and hence}\quad S\otimes L_\zeta\simeq\Omega(S\otimes V_{\chi(\zeta)}).$$
        \Cref{ThmCarlson} thus also implies that every two-dimensional module is in $\widetilde{\cT}$.
\end{example}


The rest of the section is devoted to the proof. The proof will be split up into the separate cases $p=2$ and $p>2$, but we start with some generalities that will apply to both cases.




\subsection{Generalities on periodic modules}
Let $G$ be a finite group such that $p$ divides $|G|$.

\subsubsection{}\label{DefineOmega} For the remainder of this section, we {\em define} $\Omega:=\Omega^1$ as the functor on $\Rep G$ or $\Stab G$
$$\Omega\;:=\; -\otimes \Omega(\unit),$$
with $\Omega(\unit)$ defined as the kernel of the counit $\varepsilon: \bk G\to \bk$.


\subsubsection{}\label{central} For any $M\in \Rep G$, we have the algebra morphism
\begin{equation}\label{HomAlgMor}
    H^\ast(G,\bk)\;\simeq\; \Ext^\ast_G(\unit,\unit)\;\xrightarrow{M\otimes-}\; \Ext^\ast_G(M,M)\;\simeq\; \bigoplus_{i\ge 0}\uHom_G(\Omega^i M,M),
\end{equation}
where for convenience we assumed that $\End_G(M)\tto \uEnd_G(M)$ is an isomorphism. It is well-known that this algebra morphism is central in the `super sense', meaning that 
$$f (M\otimes h)\;=\; (-1)^{ab} (M\otimes h)f$$
for $f\in \Ext^a(M,M)$ and $h\in \Ext^b(\unit,\unit)$.


The algebra structure on the right-hand side in \eqref{HomAlgMor} is given by
$$fg\;:=\; f\circ \Omega^a(g),$$
for $f:\Omega^a\unit\to\unit$ and $g:\Omega^b\unit\to\unit$.

\subsubsection{}\label{tauperiod}

Now assume that $M$ is periodic with period $\tau\in\mZ_{>0}$. Then there exists 
$$\phi:\Omega^\tau M\xrightarrow{\sim}M  $$
in $\Stab G$. We assume further that $\phi$ is central as an element of $\Ext^\ast_G(M,M)$.
We can define the quotient algebra of $\Ext^\ast_G(M,M)$ by the ideal generated by the (non-homogeneous) central element 
$$\id_M-\phi\;\in \; \End_G(M)\oplus \uHom_G(\Omega^\tau M,M)\;\subset\;\Ext^\ast_G(M,M). $$
Since $\phi$ induces isomorphisms between $\uHom_G(\Omega^i M,M)$ and $\uHom_G(\Omega^{i+\tau} M,M),$
it follows that this quotient algebra of $\Ext^\ast_G(M,M)$ can naturally be identified with its subspace
$$\bigoplus_{i=0}^{\tau-1}\Ext^i_G(M,M)\;\simeq\; \bigoplus_{i= 0}^{\tau-1}\uHom_G(\Omega^i M,M).$$
With the inherited algebra structure on this space, \eqref{HomAlgMor} thus yields an algebra morphism
$$\Upsilon^{M}_{\phi}\;:\; H^\ast(G,\bk)\;\to\;\bigoplus_{i= 0}^{\tau-1}\uHom_G(\Omega^i M,M). $$

\begin{lemma}\label{LemPsi}\label{Propf}We use the assumptions and notation from \ref{tauperiod}.
    For $\zeta\in H^d(G,\bk)$, the object $M\otimes L_\zeta $ of $\Stab G$ depends only on $\Upsilon^M_\phi(\zeta)$. 
\end{lemma}
\begin{proof}
    By definition, and using $\Omega^dM=M\otimes \Omega^d\unit$, we have the exact triangle in $\Stab G$ 
    $$
    M\otimes L_\zeta \to \Omega^dM \xrightarrow{~M\otimes\hat{\zeta}~} M \to
    $$
where $M\otimes \hat{\zeta}$ is precisely the image of $\zeta$ under \eqref{HomAlgMor}. 
Moreover, the assignment that sends an element of $\sqcup_i \uHom(\Omega^iM,M)$ to the isomorphism class of the cocone in $\Stab G$ is invariant under the operation that sends $f:\Omega^iM\to M$ to $f\phi=f\circ \Omega^i(\phi)$, since $\Omega^i(\phi)$ is an isomorphism.
\end{proof}




\subsection{Even characteristic}\label{Carlson2}
Here we consider the case $p=\mathrm{char}(\bk)=2$. Then $St_1=V$, so in particular
\begin{equation}\label{Sp22}
    S:=St_{r-1}=T_{2^{r-1}-1}=V\otimes V^{(1)}\otimes \cdots\otimes  V^{(r-2)}.
\end{equation}


\subsubsection{}Recall from \cite{Benson-vector-bundles}*{\S 1.8} that 
$$H^\ast(E,\bk)\;\simeq\; \bk[y_1,\ldots , y_r]$$
as graded algebras, where $y_i$ has degree $1$, so that
$$\widehat{\cdot}\;:\;H^1(E,\bk)\xrightarrow{\sim}\uHom(\Omega^1\unit,\unit)=\Hom(\Omega^1\unit,\unit),\qquad \sum_{a=1}^r c_ay_a\mapsto \{X_i\mapsto c_i\},$$
with $\Omega^1\unit$ realised as the radical in $\bk C_2^r=\bk[X_1,\ldots,X_r]/(X_i^2)$.

\subsubsection{}\label{defphi2}For any non-zero $\zeta\in H^1(E,\bk)$, we have the epimorphism
$$S\otimes\hat{\zeta}\,:\, \Omega(S):=S\otimes\Omega^1\unit\to S$$
with kernel $S\otimes L_\zeta$. This morphism is an isomorphism in $\Stab E$ if and only if $S\otimes L_\zeta$ is projective, which, by \cite{Benson-vector-bundles}*{Proposition~1.10.3} and \Cref{Cor:Supp}, is equivalent to the condition $\sum_{i=1}^r \zeta_i \blambda_i$ being non-zero. Also by \Cref{Cor:Supp}, this condition is satisfied for
$$\zeta\;=\;\sum_{i=1}^r \lambda_i^{2^{r-1}}y_i.$$
Moreover, by construction, see \ref{central}, the resulting
\begin{equation}\label{phi2}\phi\,:\, \Omega(S)=S\otimes\Omega^1\unit\,\to\, S,\quad v\otimes X_i\mapsto \lambda_i^{p^{r-1}}v\end{equation}
yields an isomorphism in $\Stab E$ which is central in $\Ext^\ast(S,S)$.
In conclusion, we are in the situation of \ref{tauperiod}, with $\tau=1$ and algebra morphism
\begin{equation}\label{AlgM2}
    \Upsilon^{S}_{\phi}\;:\; H^\ast(E,\bk)\;\to\;\End_E(S).
\end{equation}







\begin{proof}[Proof of \Cref{ThmCarlson} for $p=2$]
By \Cref{cor:im-omega-1-1}(a) applied to the case $Q=V^{(r-1)}$, the image~$I$ of \eqref{AlgM2} restricted to
$$H^1(E,\bk)\;\to\; \End(S)$$
is spanned by the endomorphisms $\psi_i\in \End(S)$, for $0\le i\le r-1$. Since $\psi_0$ is the identity and $\psi_i\psi_j=0$ for $i,j>0$, it follows that this image $I$ is a subalgebra. The algebra $H^\ast(E,\bk)$ is generated in degree $1$ and hence the image of the algebra morphism \eqref{AlgM2} equals $I$.

By \Cref{Propf}, it is therefore sufficient to prove the theorem for $ L_\zeta\in H^1(E,\bk)$. Firstly, we have
$$S\otimes L_0\;=\; S\otimes\Omega^1\unit\;\simeq\; S.$$
By \Cref{cor:im-omega-1-1}(b) and (c) and \Cref{Exam:1}, the non-zero cases produce
$$S\otimes L_0\;\simeq\; S\otimes V^{(i)}\;\simeq\;T_{2^{r-1}+2^i-1},$$
which concludes the proof.
\end{proof}

