\subsection{Odd characteristic}\label{Carlsonodd}

\subsubsection{}\label{HomOdd}
Here we consider the case $p=\mathrm{char}(\bk)>2$. Recall from \cite{Benson-vector-bundles}*{\S 1.8} that 
$$H^\ast(E,\bk)\;\simeq\; \bk[x_1,\ldots , x_r]\otimes \Lambda[y_1,\ldots , y_r]$$
as graded algebras, where $x_i$ is of degree $2$ and $y_i$ is of degree $1$.





We can construct an isomorphism $\Omega^2 S\to S$ similarly as for the case $p=2$ in \ref{defphi2}. Indeed, by \cite{Benson-vector-bundles}*{Proposition~1.10.3}\footnote{There is actually a minor mistake in the formulation of \cite{Benson-vector-bundles}*{Proposition~1.10.3} for $p$ odd. In the formula on the penultimate line $f^{(p)}(Y_1,\ldots, Y_r)$ should be replaced by $f(Y_1^p,\ldots, Y_r^p)$, see also \cite{Benson-vector-bundles}*{Corollary~1.10.2} or \cite{Carlson-coh-ring-mod}*{2.20, 4.5, or proof of 7.2}.}, an element $\zeta=\sum_a \zeta_a x_a\in H^2(E,\bk)$ induces an isomorphism $S\otimes \hat\zeta$ in $\Stab E$ if and only if $\sum_a\zeta_a\blambda_a^p\not=0$. Hence we can define
$$\phi: \;S\otimes \Omega^2\unit\xrightarrow{S\otimes \widehat{\zeta}}S,\qquad\mbox{for }\;\zeta=\sum_{a=1}^r\lambda_a^{p^{r}}x_a.$$
Again, since $H^{2\ast}(E,\bk)\to\Ext^\ast(S,S)$ is central, it follows that $\phi$ is central and we are in the situation of \ref{tauperiod} for $\tau=2$, with $\mZ/2$-graded algebra morphism
\begin{equation}\label{AlgMp}
    \Upsilon^{S}_{\phi}\;:\; H^\ast(E,\bk)\;\to\;\End_E(S)\oplus\uHom_E(\Omega S,S)
\end{equation}



\begin{lemma}\label{PrepH2}
    Under the isomorphism $\Ext^2_E(\unit,\unit)\simeq H^2(E,\bk)$, the exact sequence
$$0\to \unit\xrightarrow{1\mapsto e_p} St_1^{(l)}\xrightarrow{e_1\mapsto e_2} St_1^{(l)}\xrightarrow{e_1\mapsto 1} \unit\to 0,$$
for $0\le l<r$, is sent to $(\sum_a\lambda_a^{p^{l+1}}x_a)/(p-1)!$.
\end{lemma}
\begin{proof}
We prove the case $l=0$. The general case can be proved similarly, or simply reduced to $l=0$ by replacing $\ulambda$ with $\ulambda^{(l)}$.
    For $l=0$, we need to fill in the dashed arrows in the commutative diagram with exact rows
    $$\xymatrix{
    &\bk E^r\oplus \bk E^{\frac{1}{2}r(r-1)}\ar[r]\ar@{-->}[d]& \bk E^r\ar[r]\ar@{-->}[d]&\bk E\ar[r]\ar@{-->}[d]&\unit\ar[r]\ar@{=}[d]&0\\
    0\ar[r]&\unit\ar[r]&St_1\ar[r]& St_1\ar[r] & \unit\ar[r]&0.
    }$$
In the upper row, $\bk E\to\unit$ is the counit, the morphism $(\bk E)^r\to\bk E$ sends the $r$ generators $1\in \bk E$ to $\{X_i\mid 1\le i\le n\}$. For the left-most arrow on the top row, the first $r$ copies of $\bk E$ send $1$ to $X_i^{p-1}$ in the corresponding copy of $\bk E$ in the target. The remaining $r(r-1)/2$ copies of $\bk E$, labelled by $1\le i<j\le r$, send their generator to the difference of $X_i$ in the $j$th copy with $X_j$ in the $i$th copy. The right term in the upper arrow is then naturally labelled by the $r$ elements $x_i\in H^2(E,\bk)$ and the $r(r-1)/2$ elements $y_iy_j\in H^2(E,\bk)$, for $i<j$.

Using the rules
$$X_i e_a\;=\; \sum_{b>a}\frac{\lambda_i^{b-a}}{(b-a)!}e_b,\quad \mbox{for}\; 1\le i\le n\mbox{ and }1\le a\le p,$$
then allows one to verify that the left-most dashed arrow corresponds to $(\sum_i\lambda_i^p x_i)/(p-1)!$.
\end{proof}


\begin{lemma}\label{ImH2}
    The image of
    $$\Span\{x_1,\ldots, x_r\}\subset H^2(E,\bk)\;\to\; \uEnd_E(S)$$
    under $\Upsilon^S_\phi$ is $\bk \id_S$.
\end{lemma}
\begin{proof} By \Cref{Lem:Moore}, the determinant of $\mathbb{M}(\ulambda)$, or equivalently, that of $\mathbb{M}(\ulambda^{(1)})$ is non-zero. It follows that the span of the elements $\sum_{a=1}^r \lambda_a^{p^{i+1}}x_a$, for $0\le i<$r equals the span of the $x_a$.
    It follows from \Cref{PrepH2} and our choice of $\phi$ that
    $$\theta_i\;:=\;\Upsilon^S_\phi\left(\sum_{a=1}^r \lambda_a^{p^{i+1}}x_a\right)/(p-1)!$$
    fits into a commutative diagram
    $$\xymatrix{
0\ar[r]& S\ar[r]^-{v\mapsto v\otimes e_p}\ar[d]_{\theta_i}&S\otimes St_1^{(r-1)}\ar[d]\ar[rr]^-{v\otimes e_j\mapsto v\otimes e_{j+1}}&&S\otimes St_1^{(r-1)}\ar[r]^-{v\otimes e_1\mapsto v}\ar[d]& S\ar[r]\ar@{=}[d]&0\\
0\ar[r]& S\ar[r]_-{v\mapsto v\otimes e_p}&S\otimes St_1^{(i)}\ar[rr]_{v\otimes e_j\mapsto v\otimes e_{j+1}}&&S\otimes St_1^{(i)}\ar[r]_-{v\otimes e_1\mapsto v}& S\ar[r]&0.
}$$
Furthermore, any commutative diagram of the above form must have $\theta_i$ for its left arrow. In particular, $\theta_{r-1}=\id_S$.

Now consider $i<r-1$. We can choose the right morphism from $S\otimes St_1^{(r-1)}$ to $S\otimes St_1^{(i)}$ to send $v\otimes e_1$ to $v\otimes e_1$. With $\xi$ from \ref{defxi} it follows from \Cref{Powxi}(1) that the diagonal morphism from $S\otimes St_1^{(r-1)}$ to $S\otimes St_1^{(i)}$ then sends $v\otimes e_1$ to $\xi(v\otimes e_1)$. Applying \Cref{Powxi}(2) twice shows that this element is contained in
$$S\otimes \rad St_1^{(i)}\;\cap\; St_1\otimes \cdots \otimes St_1^{(i-1)}\otimes \rad St_1^{(i)}\otimes St_1^{(i+1)}\otimes\cdots St_1^{(r-2)}\otimes St_1^{(i)}. $$
Consequently, the left morphism from $S\otimes St_1^{(r-1)}$ to $S\otimes St_1^{(i)}$ can be chosen to take values in
$$St_1\otimes \cdots \otimes St_1^{(i-1)}\otimes \rad St_1^{(i)}\otimes St_1^{(i+1)}\otimes\cdots St_1^{(r-2)}\otimes St_1^{(i)}.$$
By \Cref{Powxi}(1) it then follows that the composition of $\theta_i$ with the inclusion $S\subset S\otimes St_1^{(i)}$ takes values in
\begin{eqnarray*}
    &&\xi^{p-1}\left(St_1\otimes \cdots \otimes St_1^{(i-1)}\otimes \rad St_1^{(i)}\otimes St_1^{(i+1)}\otimes\cdots St_1^{(r-2)}\otimes St_1^{(i)}\right)\\
    &\subset& St_1\otimes \cdots \otimes St_1^{(i-1)}\otimes \rad^p St_1^{(i)}\otimes St_1^{(i+1)}\otimes\cdots St_1^{(r-2)}\otimes St_1^{(i)}\;=\;0,
\end{eqnarray*}
where the inclusion follows from \Cref{Powxi}(2) applied to the non-standard choice of factors $S$ and $St_1^{(i)}$ in $S\otimes St_1^{(i)}$. Hence, we find $\theta_i=0$, which concludes the proof.
\end{proof}


\begin{proof}[Proof of \Cref{ThmCarlson} for $p>2$]
    First we show that the image of
    $$H^1(E,\bk)^{\otimes 2}\;\to\; \uHom_E(\Omega S,S)^{\otimes 2}\;\to\; \uEnd_E(S)$$
    is zero, where the second map is multiplication inside the algebra structure on
    $$\uEnd_E(S)\oplus\uHom_E(\Omega S,S)$$
    from \ref{tauperiod}.
    Indeed, let $f\in \uHom_E(\Omega S,S)$ correspond to $1\otimes f_0$ as in \Cref{cor:im-omega-1-1}, for $Q=St_1^{(r-1)}$, in particular, it is in the image of $H^1(E,\bk)\to\uHom(\Omega S,S)$. Then it follows that the image of $H^1(E,k)$ in $\uHom(\Omega S,S)$ consists of elements $af$ with $a\in \End(S)$. But inside the algebra $\Ext^\ast_E(S,S)$ (so certainly inside the above quotient) we have, for arbitrary $a,b\in\uEnd_E(S)$, we have
    $$(af)(bf)\;=\;ab f^2\;=\;0,$$
    as elements of $H^1(E,\bk)$ square to zero.

    The previous paragraph, together with \Cref{ImH2}, shows that the image of $H^2(E,\bk)$ under~$\Upsilon_\phi^S$ in \eqref{AlgMp} is the span of the identity. It thus follows that the image of $H^1(E,\bk)\oplus H^2(E,\bk)$ under~$\Upsilon_\phi^S$ is a $\mZ/2$-graded subalgebra. Indeed, it consists of the direct sum of the space spanned by the identity and a space that squares to zero, by the above paragraph.

    By \Cref{LemPsi}, and the fact that $H^\ast(E,\bk)$ is generated in degrees 1 and 2 (and the fact that morphism~\eqref{AlgMp} is $\mZ/2$-graded), it thus suffices to prove the theorem for $d=1$ and $d=2$. It follows from the above description of the image of $H^2(E,\bk)$ in $\End(S)$ and \Cref{LemPsi} that, for any $\zeta\in H^2(E,\bk)$, the module $S\otimes L_\zeta$ is, up to projective summands, $0$ or isomorphic to $S$. It follows from \Cref{cor:im-omega-1-1}(2) and \Cref{Exam:1} that for $\zeta\in H^1(E,\bk)$, the module
    $S\otimes L_\zeta$ is, up to projective summands,
    $$\Omega(S\otimes V^{(i)})\;\simeq\; \Omega(T_{p^{r-1}-1+p^i})\;\simeq\;
    \begin{cases} 
    T_{p^{r}-p^{r-1}+p^i-1},&\text{for } 0\le i<r-1,\\
    T_{p^r-2p^{r-1}-1},&\text{for } i=r-1,
    \end{cases}$$
    where we used \Cref{prop:Omega-Ti}, or alternatively $S\otimes L_\zeta\simeq\Omega S$.
\end{proof}

