\section{Modules of Loewy length two} \label{sec:Loewy}

In this section, we will show that, for general $p$ and $r$, tensor products $S\o X$, for modules $X$ of Loewy length $2$, split into modules of the form $S\o Y$, for $Y$ of dimension $1$ or $2$. It will then follow that $S\o X$ is always in $\cT$ (and hence, even in $\cT_r$ by \Cref{rem:T-tilde}(4)). 



\subsection{Simplifying extensions} \label{sec::simplify-ext}
We start with a very general observation. Let $\cA$ be a Frobenius category, let $\stHom$ and $\stEnd$ denote hom-spaces in its stable category $\underline{\cA}$. For $X,Y\in\cA$ and $f\in\stHom(\Omega X,Y)$, we denote by $E_f$ the extension of $Y$ by $X$ determined by $f$.

\begin{lemma} \label{lem::extensions-posets} Consider two finite sets of objects $(X_i)_{i\in I}$ and $(Y_j)_{j\in J}$ and morphisms $f_{ij}\in\stHom(\Omega X_i,Y_j)$ in $\underline{\cA}$, for all $i\in I,j\in J$.
Assume $k\in I,\ell\in J$ are fixed indices and for all $k\neq i\in I$ and $\ell\neq j\in J$, there are $a_i\in\stHom(\Omega X_i,\Omega X_k)$ and $a'_j\in\stHom(Y_\ell, Y_j)$ such that
$$
f_{i\ell} = f_{k\ell} a_i
\quad\text{and}\quad
f_{kj}= a'_j f_{k\ell} .
$$
Then $E_f$, the extension of $\bigoplus_j Y_j$ by $\bigoplus_i X_i$ determined by $f=(f_{ij})_{ij}$, is isomorphic to a direct sum $E_{f_{kl}}\oplus E_{\hat f}$, where $E_{\hat f}$ is the extension of $\bigoplus_{j\neq\ell} Y_j$ by $\bigoplus_{i\neq k} X_i$ determined by morphisms $\hat f=(\hat f_{ij})_{i\neq k,j\neq \ell}$, where
$$
\hat f_{ij} 
= f_{ij} - f_{kj} a_i 
= f_{ij} - a'_j f_{k\ell} a_i
= f_{ij} - a'_j f_{i\ell}
\quad\text{for all }i\neq k,j\neq\ell .
$$
\end{lemma}

\begin{proof} The statement is a version of Gaussian elimination for the matrix $(f_{ij})_{i,j}$.

Set $a_k:=0\in \stEnd(\Omega X_k)$ and $a'_\ell:=0\in\stEnd(Y_\ell)$. Let $\sigma$ be the automorphism of $\bigoplus_i \Omega X_i$ uniquely determined by its restrictions $\sigma|_{X_i}=\id_{\Omega X_i}-a_i$, let $\tau$ be the automorphism of $\bigoplus_j Y_j$ uniquely determined by its corestrictions $\tau|^{Y_j}=\id_{Y_j}-a'_j$. Then $\tau f \sigma$ is a direct sum of the morphism $f_{k\ell}$ and the morphism $\hat f:\bigoplus_{i\neq k}\Omega X_i\to\bigoplus_{j\neq \ell} Y_j$ specified above.
\end{proof}


\begin{corollary} \label{cor::linear-poset-ext}
Consider $X\in\cA$. Assume $A\subset\stEnd(X)$ and $A'\subset\stEnd(\Omega X)$ are subalgebras and $M\subset\stHom(\Omega X,X)$ is an $(A,A')$-subbimodule.  Assume $(g_k)_{1\le k\le t}$ is a finite set of elements in $M$ such that

(a) for any non-zero $g\in M$, there is an index $k$ and automorphisms $u\in A^\times$, $u'\in (A')^\times$ such that $g=u g_k=g_k u'$, and

(b) $g_k\in A g_\ell$ and $g_k\in g_\ell A'$ for all $1\le k\le \ell\le t$.

Assume $f=(f_{ij})_{i,j}$ is a $m\times n$-matrix with entries in $M$. Then $E_f$ is isomorphic to a direct sum of objects from the set $\{X\}\cup\{E_{g_k}\}_k$.
\end{corollary} 

\begin{proof} This follows from repeated applications of \Cref{lem::extensions-posets}.

Indeed, each non-zero $f_{ij}$ equals $g_k$ for some $k$ up to units in $A$ and $A'$ by (a). Let $k_0$ be the maximal $k$ appearing, let $i_0,j_0$ be such that $f_{i_0,j_0}$ corresponds to $g_{k_0}$. Then by \Cref{lem::extensions-posets} using (b), $E_f$ has a direct summand isomorphic to $E_{m_{k_0}}$, and one isomorphic to $\hat f$, where $\hat f$ is the $(m-1)\times(n-1)$-matrix obtained from $f$ via Gaussian elimination and removal of the $i_0$-th row and $j_0$-th column, using elements of $A$ and $A'$ as ``scalars''.

The assumptions ensure that $\hat f$ will still be of the form required to repeat the process as long as $\hat f$ has at least one row and column.
\end{proof}

\subsection{Set-up} 
We now turn to the category $\Rep C_p^r$, for an arbitrary prime $p$ and some $r\ge1$. As before, we fix an embedding $C_p^r\hookrightarrow SL_2$. We denote by $(T_i)_{0\le i\le p^r-1}$ the restrictions of the $SL_2$-tilting objects in $\Rep C_p^r$, and by $(St_j=T_{p^j-1})_{1\le j\le r}$ the restricted Steinberg modules. Also as before, we set $V:=T_1$ and $S:=St_{r-1}$.

\begin{lemma} \label{lem::Omega-stD} $\Omega$ restricts to the endofunctor $-\o T_{p-2}^{(r-1)}$ on the full subcategory of $\Stab C_p^r$ on $S$-projective objects.
\end{lemma}

\begin{proof} $S$, and hence any non-projective $S$-projective object $X$, has a one-point support consisting of a point not fixed by the Frobenius automorphism by \Cref{Cor:Supp}. Hence, $T_{p-1}^{(r-1)}\o S\o X$ is projective, and the assertion follows, as $T_{p-2}^{(r-1)}\simeq\ker(T_{p-1}^{(r-1)}\to\one)$.
\end{proof}

In the following, we consider $\stHom(\Omega S, S)$ as an $\stEnd(S)$-bimodule, using $\Omega$ for the right action.

\begin{lemma} \label{lem::Hom-Omega-S-S} For any non-zero $C_p^r$-morphism $f_0:T_{p-2}^{(r-1)}\to\one$, the map 
$$
\stEnd(S)\to\stHom(\Omega S,S)\simeq\stHom(S\o T_{p-2}^{(r-1)} ,S), \quad
f\mapsto f\o f_0,
$$
is an isomorphism of $\stEnd(S)$-bimodules, using the identifications
$$
\stEnd(S)\simeq\stEnd(\Omega S)\simeq\stEnd(S\o T_{p-2}^{(r-1)}), \quad
f\mapsto \Omega f\mapsto f\o T_{p-2}^{(r-1)} .
$$
\end{lemma}

\begin{proof}
    The map is a well-defined morphism of bimodules. $S\o\Omega S=T_{p^{r-1}-1}\o T_{p^r-p^{r-1}-1}$ has no projective summands, as follows directly from considering the tensor product of the corresponding $SL_2$-tilting modules, which does not have a submodule isomorphic to $T_{p^r-1}$, as the corresponding highest weight does not appear. This means $\stHom(\Omega S,S)\simeq\Hom(\Omega S,S)$, which means the described bimodule morphism is injective. 

    As $\Omega S$ is cyclic, 
    $$\dim\stHom(\Omega S,S)\le\dim S= p^{r-1},$$ which is exactly the dimension of $\stEnd(S)$ by \Cref{LemmaLambda}.
\end{proof}

For the rest of the section, we fix a choice of $f_0:T_{p-2}^{(r-1)}\tto\one$.


\subsection{Groups of rank two} 
We first consider $r=2$. While the implications (like \Cref{prop::self-ext-S}) will also follow from the more general results in \Cref{sec::LL2-r-arbitrary}, they are somewhat more elementary, as they do not rely on the ideas and results of \Cref{sec::subcategories}.

\begin{lemma} \label{lem::ext-maps-r2} Assume $r=2$. Then there are $(\phi_i)_{1\le i\le p}\in\stEnd(S)$ such that

(a) for any non-zero element $g\in\stHom(\Omega S,S)$, there is an $1\le i\le p$ and automorphisms $u,u'\in\stAut(S)$ such that $g=u \phi_i \o f_0=\phi_i u'\o f_0$, and

(b) $\phi_i\in \phi_j\stEnd(\Omega S)$ and $\phi_i\in\stEnd(S)\phi_j$ for all $1\le j\le i\le p$. 
\end{lemma}

\begin{proof} Set $A:=\stEnd(S)\simeq\End(S)\simeq \kk[z]/z^p$, see \Cref{LemmaLambda}. By \Cref{lem::Hom-Omega-S-S}, $M:=\stHom(\Omega S,S)$ is isomorphic as an $A$-bimodule to the regular $A$-bimodule. 

As $z\in A$ is nilpotent, any element of $A$ is a power of $z$ up to multiplication by a unit. The assertions follow with $\phi_i:=z^{i-1}$.
\end{proof}





\begin{proposition} \label{prop::self-ext-S} Assume $r=2$. For all $a,b\ge0$, any extension of $S^a$ by $S^b$ is in $\langle S=T_{p-1},T_p,\dots, T_{2p-1}\rangle_\oplus\subset\cT$. 
\end{proposition}

\begin{proof} The extensions are parametrised by $\stHom((\Omega S)^a,S^b)\simeq \stHom(\Omega S,S)^{a\times b}$.

It follows from \Cref{lem::ext-maps-r2} with \Cref{cor::linear-poset-ext} that any extension as above is a direct sum of self-extensions of $S$ corresponding to the $p$ maps $\phi_i$, and copies of $S$ itself.

By \Cref{lem::ext-maps-r2} there are at most $p$ isomorphism classes of non-split self-extensions of $S$. The conclusion follows from \Cref{cor:self-ext1} which realises $p$ such extensions.
\end{proof}

It follows that \Cref{conj-a} is true for $r=2$ when restricted to modules of Loewy length at most $2$:
\begin{corollary} \label{cor:ll-2}
    Any module of Loewy length at most $2$ lies in $\widetilde\cT$.
\end{corollary}

\begin{proof}
    $S\o X$, for $X$ of Loewy length $2$, is of the form studied in \Cref{prop::self-ext-S}.
\end{proof}

\begin{corollary} \label{cor:extensions-p2} For $p=2$ and $r=2$, the tensor product $S\o X$ is in $\langle T_1,T_2,T_3\rangle_\oplus=\cT_r\subset\cT$ for all $X\in\Rep C_2^2$.
\end{corollary}

\begin{proof} It suffices to consider non-projective indecomposable objects $X$. As the projective indecomposable $C_2^2$-module has Loewy length $3$, such $X$ have Loewy length at most $2$.
\end{proof}

The above proves \Cref{conj-a} for $p=r=2$. A direct proof of this case using the classification of indecomposable $C_2^2$-modules was given in \cite{CF}*{Remark~5.4.4}. \Cref{cor:extensions-p2} is the simplest proof of \Cref{conj-b} in this special case without invoking the classification of indecomposable $C_2^2$-modules that we are aware of.


\begin{corollary}\label{CorSelfExt} For any $p$ and $r=2$, and for $a,b\ge0$, any extension of $(\Omega S)^a$ by $(\Omega S)^b$ is in $\langle  T_{p^2-2p-1},\Omega S=T_{p^2-p-1},T_{p^2-p},\dots,T_{p^2-2}\rangle_\oplus$. 
\end{corollary}

\begin{proof} By taking Heller shifts and identifying the obtained modules using \Cref{prop:Omega-Ti}.  
\end{proof}

\begin{example} \label{expl::self-ext-S} For $p=3$, $r=2$, the non-split self-extensions of $S$ are exactly the modules $T_3,T_4,T_5$ by \Cref{prop::self-ext-S} and its proof.
\end{example}

\subsection{Groups of arbitrary rank} \label{sec::LL2-r-arbitrary}

For $r>2$, \Cref{prop::self-ext-S} will no longer be true, see \Cref{rem-ex}, but an analogue of \Cref{cor:ll-2} will still hold.
To establish this, we restrict to ``$S$-projective'' extensions. Consider the map $$
\omega_{\one,\one}=S\o-:\stHom(\Omega\one,\one)\to\stHom(\Omega S,S).
$$
We summarize some result from \Cref{sec::subcategories}, yielding an ``$S$-projective'' analogue of \Cref{lem::ext-maps-r2}.

\begin{lemma} \label{lem::ext-maps-any-r} There is a subalgebra $A\subset\stEnd(S)$ and elements $(\psi_i)_{1\le i\le r}\in A$ such that $M:=A\o f_0=\im\omega_{\one,\one}$ and

(a) for any non-zero element $g\in M$, there is an $1\le i\le r$ and automorphisms $u,u'\in A^\times$ such that $g=u \psi_i \o f_0=\psi_i u'\o f_0$, 

(b) $\psi_i\in \psi_j A$ and $\psi_i\in A\psi_j$ for all $1\le j\le i\le r$,

\end{lemma}

\begin{proof} This follows immediately from \Cref{cor:im-omega-1-1}.   
\end{proof}


\begin{proposition} \label{prop::self-ext-S-any-r} Let $X$ be any module of Loewy length $2$. Then $S\o X$ is in $\langle T_{p^{r-1}-1}=S, T_{p^{r-1}}\simeq S\o V, T_{p^{r-1}+p-1}\simeq S\o V^{(1)},\dots, T_{p^{r-1}+p^{r-1}-1}\simeq S\o V^{(r-1)} \rangle_\oplus \subset \cT$.
\end{proposition}

\begin{proof} The object $S\o X$ can be viewed as an extension of $S^a$ by $S^b$, for $a=\dim(X)-\dim\soc(X)$ and $b=\dim\soc(X)$, corresponding to a map in $(\im\omega_{\one,\one})^{a\times b}\subset \stHom(\Omega S,S)^{a\times b}$.

It follows from \Cref{lem::ext-maps-any-r} with \Cref{cor::linear-poset-ext} that any extension as above is a direct sum of self-extensions of $S$ corresponding to the maps $\psi_i$ and copies of $S$ itself.

The self-extensions of $S$ corresponding to the maps $(\psi_i)_{1\le i\le r}$ are identified as the modules $(S\o V^{(j)})_{1\le j\le r}$ in \Cref{cor:im-omega-1-1}.
\end{proof}

\begin{corollary} \label{cor:ll-2-any-r}
    Any module of Loewy length at most $2$ lies in $\widetilde\cT$.
\end{corollary}

\begin{example}\label{ex-moreex} Consider $p=3,r=2$. In view of \Cref{expl::self-ext-S}, note that out of the three non-split self-extensions of $S$, only only $T_3\cong S\o V$ and $T_5\simeq S\o V^{(1)}$ can appear in a tensor product of the form $S\o X$, for $X$ of Loewy length $2$.
\end{example}




