\appendix
\section{Bounded Softmax Function}
\label{sec:boundedSoftmax}

\begin{theorem}[Bounded Softmax]
Let be $u$ the desired lower bound to the softmax function and $k=\#(A)$, with
$$A=\left\{i\in\{1,2,...,n\}: \dfrac{e^{x_i}}{\sum_{j=1}^n e^{x_j}}\geq u\right\}$$
The function 
    \begin{equation}
        \mathbf{b}_i(\mathbf{x})=\left\{\begin{array}{cl}
            \dfrac{e^{x_i}}{\sum_{j\in A} e^{x_j}}\cdot\left(1-(k-n)u\right) & \text{if } i\in A\\
            u & \text{if } i\notin A
        \end{array}\right.
    \end{equation}
is the unique solution to problem \ref{eq:bounded}.
\end{theorem}
\begin{proof}
The KKT conditions for this problem are
\begin{itemize}
    \item{\textbf{Stationary:} 
    \begin{align*}
        \mathbf{0}= \dfrac{\partial}{\partial \mathbf{b}}\Biggl(\sum_{j=1}^n b_i\ln{(b_i)}-\mathbf{x}^\top \mathbf{b}-\sum_{j=1}^n \gamma_j b_j +&\sum_{j=1}^n \eta_j (b_j-1)  +\cdots\\
        &\cdots +\sum_{j=1}^n  \mu_j (u-b_j) + \lambda \left[1-\sum_{j=1}^n b_j\right]\Biggr)
    \end{align*}
    }
    \item{\textbf{Complementary slackness:}
        $$-b_j \gamma_j=0,\qquad \eta_j (b_j-1) = 0, \qquad \mu_j (u-b_j) = 0$$
    }
    \item{\textbf{Primal Feasibility:}
        $$1^\top \mathbf{b}=1,\qquad 0<\mathbf{b}<1,\qquad \mathbf{b}\geq u$$
    }
\end{itemize}
Then, from the stationary condition we get
\begin{align*}
    \dfrac{\partial}{\partial \mathbf{b}}\left( \mathbf{b}^\top\ln{\mathbf{(b)}}-\mathbf{x}^\top \mathbf{b}-\mathbf{\gamma}^\top \mathbf{b} +\eta^\top (\mathbf{b}-\mathbf{1}) +\mathbf{\mu}^\top (\mathbf{u}-\mathbf{b}) +\lambda \left[1-\mathbf{1}^\top \mathbf{b}\right] \right)&= \mathbf{0}\\
    \ln{\mathbf{(b)}}+\mathbf{1}-\mathbf{x}-\gamma +\eta -\mu - \lambda &= \mathbf{0}\\
    -\mathbf{1}+\mathbf{x}+\gamma -\eta +\mu + \lambda &=\ln{\mathbf{(b)}} 
\end{align*}
Therefore, for each $j=1,...,n$,
$$b_j = e^{-1+x_j +\gamma_j -\eta_j +\mu_j +\lambda}$$
Now, using the primal feasibility conditions, since $0<\mathbf{b}<1$, $\gamma_j=\eta_j=0$, thus for each $j=1,...,n$, $$b_j = e^{-1+x_j +\mu_j +\lambda}$$
Hence,
\begin{enumerate}
    \item{If $b_j > u$, $\mu_j=0$ and for each $j=1,...,n$, since $\mathbf{b}^\top \mathbf{1}=1$
    $$\sum_{j=1}^n b_j = \sum_{j=1}^n e^{-1+x_j  +\lambda}=1\quad\Longrightarrow \lambda = 1-\ln{\left(\sum_{j=1}^n e^{x_j}\right)}$$
    Then,
    \begin{align*}
        b_j &= e^{-1+x_j +\lambda}\\
        b_j &= e^{-1+x_j +\left(1-\ln{\left(\sum_{j=1}^n e^{x_j}\right)}\right)}\\
        b_j &= e^{x_j -\ln{\left(\sum_{j=1}^n e^{x_j}\right)}}\\
        b_j &= \dfrac{e^{x_j}}{\sum_{j=1}^n e^{x_j}}
    \end{align*}
    which is the classical softmax function (\ref{eq:softmax}). Moreover,
    $$A=\left\{i\in\{1,2,...,n\}: \dfrac{e^{x_i}}{\sum_{j=1}^n e^{x_j}}\geq u\right\}=\{1,2,...,n\}\Longrightarrow k=\#\left(A\right)=n$$
    and
    $$b_j =\dfrac{e^{x_j}}{\sum_{j=1}^n e^{x_j}}=\dfrac{e^{x_j}}{\sum_{j=1}^n e^{x_j}}\cdot\left(1-(k-n)u\right)$$
    }
    \item{If $b_j>u$ for $j=1,...,k$ and $b_j = u$ for $j=k+1, ..., n$, then
        $$\sum_{j=1}^k b_j = \sum_{j=1}^k e^{-1+x_j  +\lambda}=1-(n-k)u\Longrightarrow \lambda = 1+\ln{\left(1-(n-k)u\right)}-\ln{\left(\sum_{j=1}^k e^{x_j}\right)}$$
    Then, for $j=1,...,k$
    \begin{align*}
        b_j &= e^{-1+x_j +\lambda}\\
        b_j &= e^{-1+x_j +\left(1+\ln{\left(1-(n-k)u\right)}-\ln{\left(\sum_{j=1}^k e^{x_j}\right)}\right)}\\
        b_j &= e^{x_j +\ln{\left(1-(n-k)u\right)}-\ln{\left(\sum_{j=1}^k e^{x_j}\right)}}\\
        b_j &= \dfrac{e^{x_j}}{\sum_{j=1}^n e^{x_j}}\cdot \left(1-(n-k)u\right)
    \end{align*}
    which is the classical softmax function (\ref{eq:softmax}) applied over the $k$ coordinates left and multiplied by the remained weight. Thus,
    $$b_j=\left\{\begin{array}{cl}
        \dfrac{e^{x_j}}{\sum_{j=1}^n e^{x_j}}\cdot \left(1-(n-k)u\right) & \text{if } j\in A\\
        u & \text{if } j\notin A
    \end{array}\right.$$
    }
\end{enumerate}
\end{proof}

