    \subsection{Stationary solutions}

    In the remainder of the paper, we will be concerned with $\Omega$-symmetric and -periodic stationary solutions bifurcating from the pure conduction state $\Bar{h}=1$. To this end, we notice that we can rewrite the stationary thin-film equation 
	\begin{equation}
		\label{eq:stationary-thin-film}
		\nabla\cdot
		\sprlr{
			h^3
			\sprlr{\nabla\Delta h-g\nabla h}
			+
			M\frac{h^2}{(1+h)^2}\nabla h
		}
		=0.
	\end{equation}
	as a second-order elliptic problem with a carefully chosen nonlocal right-hand side. We write $h=1+v$, where $v>-1$, yielding
	\begin{equation*}
		\nabla\cdot
		\sprlr{
			(1+v)^3
			\sprlr{\nabla\Delta v-g\nabla v
				+
				M\frac{1}{(1+v)(2+v)^2}\nabla v
		}}
		=0.
	\end{equation*}
	Using that
	\begin{equation*}
		\frac{1}{(1+v)(2+v)^2}\nabla v
		=
		\nabla \sprlr{\frac{1}{2+v}+\log\sprlr{\frac{1+v}{2+v}}}
	\end{equation*}
	we find that 
	\begin{equation*}
		\nabla\cdot
		\sprlr{
			(1+v)^3
			\nabla\sprlr{\Delta v-gv
				+
				M
				\sprlr{\frac{1}{2+v}+\log\sprlr{\frac{1+v}{2+v}}
		}}}
		=0.
	\end{equation*}
	This problem is of the form $\nabla\cdot\sprlr{a(v)\nabla G(v)}=0$. 
	If $v>-1$, the function $G(v)$ is well-defined and $\Omega$-periodic, and $a(v)>0$ uniformly in $\Omega$.
	By uniqueness for this elliptic Neumann problem
	\begin{equation*}
		\nabla\cdot\sprlr{a(v)\nabla G(v)}=0
		\quad\iff\quad
		G(v)\equiv \tilde{K},\;\tilde{K}\in\Rbb.
	\end{equation*}
	Hence, we can reformulate the stationary thin-film equation \eqref{eq:stationary-thin-film} as
	\begin{equation}
		\label{eq:integrated-stationary-problem}
		\Delta v-gv
		+
		M
		\sprlr{\frac{1}{2+v}+\log\sprlr{\frac{1+v}{2+v}}}
		=MK(v),
	\end{equation}
	where $MK(v)$ is the integration constant depending on $v$ and $M>0$.
	We choose
	\begin{equation}
		\label{eq:K}
		K(v)=
		\fint_\Omega\frac{1}{2+v}+\log\sprlr{\frac{1+v}{2+v}}\de \bfx,
	\end{equation}
	which ensures that \Cref{eq:integrated-stationary-problem} has nontrivial solutions with vanishing mean.



	\section{Local bifurcation theory}
    \label{sec loc bif}
    In this section, we establish the bifurcation of periodic patterns from the pure conduction state.
    The latter destabilises at $M=M^\ast$ with respect to long-wave perturbations, and we choose $M$ as bifurcation parameter.
    Having set the size of the domain $\Omega\in\{\square,\hexagon\}$ by fixing $k_0$, we now determine the bifurcation point $M^*(k_0)$ at which patterns with the same size bifurcate.
    Consider 
	\begin{equation*}
		M^\ast(k_0)=M^\ast+4 k_0^2=4g+4 k_0^2
	\end{equation*}
	such that for $M=M^\ast(k_0)$ the dispersion relation \eqref{disp rel} vanishes at $\abs{\bfk}=k_0$
	\begin{equation*}
		\lambda_{M=M^\ast(k_0)}(\bfk)=0, \quad\text{if}\;\abs{\bfk}=k_0.
	\end{equation*}
	Further, it holds $\partial_M \lambda_{M}(\k)|_{M=M^*(k_0)} > 0$ for $|\k| = k_0$. Hence, for the choice $M = M^*(k_0)$, we expect the bifurcation of an $\Omega$-periodic solution from the pure conduction state.

    \begin{remark}
    \label{rema other bifurcation points}
        We note that at $(v,M)=\sprlr{0,M^\ast(nk_0)}$, where $n\in\N_+$, we expect the bifurcation of periodic solutions such that $\Omega$ fits $n$ periods per dimension.
    \end{remark}

	We now set up the corresponding bifurcation problem. First, we introduce the following function spaces
	\begin{align*}
		\Xcal&\coloneqq
		\set{v\in\Hrm_\per^2(\Omega)}
		{v\;\textrm{is $\Omega$-symmetric,}\;
			\fint_\Omega v \de x=0},\\
		\Ycal&\coloneqq
		\set{v\in\Lrm_\per^2(\Omega)}
		{v\;\textrm{is $\Omega$-symmetric,}\;
			\fint_\Omega v \de x=0},\\
		\Ucal&\coloneqq
		\set{v\in\Xcal}
		{v>-1},
	\end{align*}
	where $\Hrm^k_\per(\Omega)$ is the Sobolev space of $\Omega$-periodic functions and $\Xcal$ and $\Ycal$ carry the $\Hrm_\per^2(\Omega)$- and the $\Lrm_\per^2(\Omega)$-norm, respectively.
	With this notation, we can define the analytic bifurcation function
	\begin{align*}
		F\colon\Ucal\times\Rbb\longrightarrow\Ycal \; \colon \; F(v,M)=
		\Delta v-gv
		+
		M\sprlr{\frac{1}{2+v}+\log\sprlr{\frac{1+v}{2+v}}}
		-MK(v),
	\end{align*}
	where the constant $K(v)$ is defined in \eqref{eq:K}.
	Note that the Laplacian is invariant under the $\Omega$-symmetries and our choice of $K(v)$ ensures that $F(v,M)$ has vanishing mean for any $(v,M) \in \Ucal\times\R$.
	The bifurcation problem therefore is 
	\begin{equation}
		\label{bif problem}
		F(v,M)=0.
	\end{equation}

    In the following, we establish local bifurcation results for the square and the hexagonal lattice, respectively. 
    We treat both cases separately, since the resonance in the hexagonal lattice makes the quadratic interactions of critical Fourier modes relevant.
    As a consequence, the bifurcation of hexagonal patterns is generally transcritical, while square patterns arise from a pitchfork bifurcation.

    \subsection{Local bifurcation of square patterns}    
	Assuming $\square$-symmetry, it turns out that a bifurcation from a one-dimensional kernel occurs and the Crandall--Rabinowitz local bifurcation theorem in \cite[Thm. 8.3.1]{buffoni2003} applies.
    We obtain the following result.
	\begin{theorem}[Local bifurcation on the square lattice]
		\label{thm loc bif squ}
		Fix $k_0>0$ and let $\Omega=\square$. Then a subcritical pitchfork bifurcation occurs at $(v(0),M(0)) = (0,M^*(k_0))=(0,M^\ast+4 k_0^2)$, that is, there exists $\varepsilon>0$ and a branch of solutions 
		\begin{equation*}
			\Ccal_\loc\coloneqq\set{\sprlr{v(s),M(s)}}{s\in(-\varepsilon,\varepsilon)}
			\subset \Ucal\times\Rbb
		\end{equation*}
		to the bifurcation problem \eqref{bif problem}
		with expansions
		\begin{equation}
			\label{expansions squ}
			\begin{split}
				v(s) & = s\hat{\xi}_0+\tau(s),
				\\
				M(s) & = M^\ast(k_0)-\frac{\sprlr{g+k_0^2}\sprlr{104+203k_0^2}}
            {24\pi^2\sprlr{1+k_0^2+k_0^4}}
				s^2+\Ocal(\abs{s}^3),
			\end{split}
		\end{equation}
		where $\tau(s)=\Ocal(\abs{s}^2)$ in $\Xcal$ as $s\to0$, and $\hat{\xi}_0$ is the normalised kernel element defined in \eqref{kernel element squ}.
	\end{theorem}

	\begin{proof}
		The proof follows from a straightforward application of the Crandall-Rabinowitz theorem, see e.g.~\cite[Thm.~8.3.1]{buffoni2003}. Note that by our choice of $K(v)$ in \eqref{eq:K} we obtain $F(0,M)=0$ for all $M\in\Rbb$.

		\noindent\textbf{Step 1:} Existence of local bifurcation curve. We need to check the following three conditions:
		the linearisation $L$ of $F\sprlr{\cdot,M^*(k_0)}$ about $v\equiv0$ is Fredholm of index zero and has a one-dimensional kernel. Finally, the transversality condition \eqref{transversality} needs to be satisfied. 

		We calculate the linearisation of $F\sprlr{\cdot,M^\ast(k_0)}$ about $v\equiv 0$
		\begin{equation*}
			L\coloneqq \partial_v F\sprlr{0,M^\ast(k_0)}
			=\Delta+\sprlr{\frac{1}{4}M^\ast(k_0)-g}
			=\Delta+k_0^2.
		\end{equation*}
		Note that for $w \in \Xcal$ by the vanishing mean condition the derivative of the constant term vanishes
		\begin{equation*}
			\partial_v K(0)(w)
			=
			\fint_\Omega \frac{w}{4} \de x
			=0.
		\end{equation*}

		The Fourier symbol of $L$ is given by
		\begin{equation*}
			\hat{L}(\bfk) = k_0^2 \sprlr{1-\abslr{\bfk}^2},\qquad \bfk=
			\begin{pmatrix}
				k_1\\
				k_2
			\end{pmatrix}
			\in\Zbb^2,
		\end{equation*}
		and therefore
		\begin{equation*}
			\ker \hat{L}=\set{\bfk\in\Zbb^2}{\abs{\bfk}=1}.
		\end{equation*}
		By $\square$-symmetry, this reduces to the one-dimensional subspace of $\Xcal$
		\begin{equation}
			\label{ker L}
			\ker L = \mathrm{span}
			\dprlr{
            \sum_{\boldsymbol{\gamma}\in\Lambda_\square}
            a_{\boldsymbol{\gamma}}\ee^{\ii \boldsymbol{\gamma}\cdot\bfx}
            \ \ \textup{\textbf{:}}\ \  
            \textrm{$a_{\boldsymbol{\gamma}}$ satisfy \eqref{eq:cond-symmetry}}
            }
            = \mathrm{span}
			\dprlr{\hat{\xi}_0}
		\end{equation}
        and we denote a kernel element and its normalisation by
        \begin{equation}
        \label{kernel element squ}
            \xi_0\coloneqq\ee^{\ii k_0x}+\ee^{-\ii k_0x}+\ee^{\ii k_0y}+\ee^{-\ii k_0y},
            \qquad
            \hat{\xi}_0\coloneqq\frac{\xi_0}{\normlr{\xi_0}_\Xcal}.
        \end{equation}

		The range of $L$ in $\Ycal$ has codimension one, since
		\begin{equation*}
			\ran L 
			=\mathrm{span}
			\dprlr{
            \sum_{\boldsymbol{\gamma}\in\Gamma \setminus\Lambda_\square}
            a_{\boldsymbol{\gamma}}\ee^{\ii \boldsymbol{\gamma}\cdot\bfx}
            \ \ \textup{\textbf{:}}\ \  
            \textrm{$a_{\boldsymbol{\gamma}}$ satisfy \eqref{eq:cond-symmetry}}}, 
		\end{equation*}
		which proves that $L$ is Fredholm of index zero with one-dimensional kernel.

		Finally, we check the transversality condition
		\begin{equation}
			\label{transversality}
			\partial^2_{v,M}
			F\sprlr{0,M^\ast(k_0)}(\xi_0,1)
			\notin \ran L.
		\end{equation}
		Therefore, we calculate
		\begin{equation*}
			\partial^2_{v,M}F\sprlr{0,M^\ast(k_0)}(\xi_0,1)
			=
			\partial_v\sprlr{
				\frac{1}{2+v}+\log\sprlr{\frac{1+v}{2+v}}-K(v)
			}\bigg\rvert_{v=0}(\xi_0,1)
			=
			\frac{1}{4}\xi_0
			\notin \ran L.
		\end{equation*}
        Hence, the Crandall–Rabinowitz theorem applies and gives the existence of a local bifurcation curve $\Ccal_\loc$.

		\noindent\textbf{Step 2:} Expansion of solutions and local behavior of bifurcation curve. Using \cite[Cor. I.5.2]{kielhofer2012}, we obtain
		\begin{equation*}
			v(s)=s\hat{\xi}_0+\tau(s),
		\end{equation*}
		where $\tau(s)=\Ocal(\abs{s}^2)$ in $\Xcal$ as $s\to0$.
		Next, we calculate the Taylor expansion of $M(s)$ about $s=0$.
		The first derivative of $M(s)$ at $s=0$ vanishes by \cite[Eq. I.6.3]{kielhofer2012} and 
		\begin{equation*}
			\partial_{vv}^2F\sprlr{0,M^\ast(k_0)}\left[\hat{\xi}_0,\hat{\xi}_0\right]=-\frac{M^\ast(k_0)}{2}\hat{\xi}_0^2+\frac{M^\ast(k_0)}{2}\fint_\Omega \hat{\xi}_0^2 \de x\in\ran L.
		\end{equation*}
		The second derivative is given by \cite[Eq. I.6.11]{kielhofer2012}
		\begin{equation*}
			\ddot{M}(0)=-\frac13\frac{
				\int_\Omega \sprlr{Q\partial_{vvv}^3F\sprlr{0,M^\ast(k_0)}\left[\hat{\xi}_0,\hat{\xi}_0,\hat{\xi}_0\right]-3Q\partial_{vv}^2F\sprlr{0,M^\ast(k_0)}\left[\hat{\xi}_0,A\right]}
				\cdot\hat{\xi}_0\de x
			}{
				Q\int_\Omega
				\partial_{v,M}^2F\sprlr{0,M^\ast(k_0)}\hat{\xi}_0\cdot\hat{\xi}_0
				\de x
			},
		\end{equation*}
		where $Q$ is the projection in $\Ycal$ along $\ran L$, and 
		% \begin{align*}
		% 	A&\coloneqq-L^{-1}(\Id-Q)\partial_{vv}^2F\sprlr{0,M^\ast(k_0)}\left[\hat{\xi}_0,\hat{\xi}_0\right]
		% 	\\&=
