	\subsection{Local bifurcation of hexagonal patterns}
	\label{subsec hex setup bif}
    In this subsection we prove bifurcation of hexagonal patterns. The proof is similar to the square case and we only provide the necessary modifications. The main difference comes from the fact that hexagonal patterns originate from a transcritical bifurcation.

    \begin{theorem}[Local bifurcation on the hexagonal lattice]
		\label{thm loc bif hex}
		Fix $k_0>0$ and let $\Omega=\hexagon$. Then a transcritical bifurcation occurs at $(v(0),M(0)) = (0,M^*(k_0))=(0,M^\ast+4 k_0^2)$, that is, there exists $\varepsilon>0$ and a branch of solutions 
		\begin{equation*}
			\Ccal_\loc\coloneqq\set{\sprlr{v(s),M(s)}}{s\in(-\varepsilon,\varepsilon)}
			\subset \Ucal\times\Rbb
		\end{equation*}
		to the bifurcation problem \eqref{bif problem}
		with expansions
		\begin{align}
			\label{expansions hex}
			\begin{split}
				v(s)&=s\hat{\psi}_0+\tau(s),
				\\
				M(s)&=M^\ast(k_0)+
                \frac{2\sprlr{g+k_0^2}}{3^\frac14\pi \sqrt{k_0^2+1+\frac{1}{k_0^2}}}
                s+\Ocal(\abs{s}^2),
			\end{split}
		\end{align}
		where $\tau(s)=\Ocal(\abs{s}^2)$ in $\Xcal$ as $s\to0$, and $\hat{\psi}_0$ is the normalised kernel element defined in \eqref{kernel element hex}.
	\end{theorem} 

\begin{proof}
    Fortunately, $L=\Delta+k_0^2$ still acts diagonally on Fourier modes, and we can compute
	\begin{align}
		\label{L on hexagonal mode}
		L
		\ee^{\ii k_0\left(n_1x-\frac{n_2}{2}x+\frac{\sqrt3 n_2}{2}y\right)}
		=
		k_0^2\sprlr{1-n_1^2-n_2^2+n_1n_2}
		\ee^{\ii k_0\left(n_1x-\frac{n_2}{2}x+\frac{\sqrt3 n_2}{2}y\right)}.
	\end{align}
	A Fourier mode with wave number $\bfk = n_1 \k_1 + n_2 \k_2$ lies in $\ker L$ if and only if $\bfk \in \Lambda_{\hexagon}$.
    Hence, by $\hexagon$-symmetry, $\ker L$ is the one-dimensional subspace of $\Xcal$ given by
	\begin{equation*}
		\ker L = \mathrm{span}
		\dprlr{
            \sum_{\boldsymbol{\gamma}\in\Lambda_\hexagon^\ast}
            a_{\boldsymbol{\gamma}}\ee^{\ii \boldsymbol{\gamma}\cdot\bfx}
            \ \ \textup{\textbf{:}}\ \  
            \textrm{$a_{\boldsymbol{\gamma}}$ satisfy \eqref{eq:cond-symmetry}}
        }
        = \mathrm{span}
		\dprlr{\hat{\psi}_0}
	\end{equation*}
    and we denote a kernel element and its normalisation by
    \begin{equation}
    \label{kernel element hex}
        \psi_0\coloneqq
        \ee^{\ii k_0x}
        +\ee^{\ii k_0\left(-\frac{1}{2}x+\frac{\sqrt3}{2}y\right)}
        +\ee^{\ii k_0\left(x-\frac{1}{2}x+\frac{\sqrt3}{2}y\right)}
        +\,\text{c.c.},
        \qquad
        \hat{\psi}_0\coloneqq\frac{\psi_0}{\normlr{\psi_0}_\Xcal},
    \end{equation}
    where $\text{c.c.}$ denotes the complex conjugated terms.
    Therefore, similar to the square case the existence of a local bifurcation curve follows by Crandall--Rabinowitz. 

	The main difference to the square case is the behavior of $M(s)$ close to $s=0$.
	In particular, 
	\begin{equation*}
		\dot{M}(0)=-\frac12\frac{\langle\partial_{vv}^2F\sprlr{0,M^\ast(k_0)}\left[\hat{\psi}_0,\hat{\psi}_0\right],\hat{\psi}_0\rangle}{\langle\partial_{v,M}^2F\sprlr{0,M^\ast(k_0)}\left[\hat{\psi}_0,1\right],\hat{\psi}_0\rangle} = \frac{8\sprlr{g+k_0^2}}{\normlr{\psi_0}_\Xcal}=\frac{2\sprlr{g+k_0^2}}{3^\frac14\pi \sqrt{k_0^2+1+\frac{1}{k_0^2}}} >0
	\end{equation*}
    by \cite[Eq. I.6.3]{kielhofer2012}.
	Therefore, a transcritical bifurcation takes place and the proof is complete.
