	% 	\\&=
 %        \frac{1}{\normlr{\psi_0}_\Xcal^3}\frac{32\sqrt{3}\pi^2\sprlr{g+k_0^2}}{k_0^2}
	% \end{align*}
	% and
	% \begin{equation*}
	% 	\langle\partial_{v,M}^2F\sprlr{0,M^\ast(k_0)}\left[\hat{\psi}_0,1\right],\hat{\psi}_0\rangle
