\noindent {\bf Abstract:}  This paper focuses on deriving several curvature inequalities involving the Ricci and scalar curvatures of the horizontal and vertical distributions in anti-invariant Riemannian submersions from quaternionic space forms onto Riemannian manifolds. In addition, a Ricci curvature inequality for anti-invariant Riemannian submersions is established. The equality cases for all derived inequalities are also examined.


\noindent {\bf Keywords:}  Quaternionic 
K\"ahler manifold; quaternionic space form; anti-invariant submersion.  \newline
\noindent {\bf MSC 2020:} 53C12, 53C15, 53C26, 53C55.

\section{Introduction}
In 1993, B.-Y. Chen established foundational relationships between the extrinsic and intrinsic invariants of submanifolds in real space forms \cite{Chen}. Later, in 1999, he derived a sharp inequality connecting the Ricci curvature and the squared mean curvature for submanifolds \cite{Chen99}. These findings have since inspired a broad spectrum of research, leading to the development of numerous results in various ambient geometries. For a comprehensive study, see \cite{Chenbook}. Several authors \cite{Aydin, Ayi,  Naghi, Sahin16, MMT} have further explored Chen-like inequalities.

As noted in \cite{Falcitelli-Ianus and Pastore}, a central theme in Riemannian geometry is the comparison of geometric properties of different types of maps between Riemannian manifolds. In this context, the concept of Riemannian submersion, introduced by B. O’Neill in 1966 \cite{O'Neill}, plays a pivotal role. O'Neill formulated key equations governing Riemannian submersions, which have found applications in diverse fields such as supergravity, statistical machine learning, analysis on manifolds, and image processing. The geometric features of Riemannian submersions have been further investigated by Besse \cite{Besse}, Escobales Jr. \cite{Eco}, and many others.

In a related development, Watson \cite{Watson} introduced and studied almost Hermitian submersions between almost complex manifolds, showing that both the horizontal and vertical distributions remain invariant under the almost complex structure of the total space. Later, in 2010, \c Sahin \cite{Sahin-10} explored anti-invariant Riemannian submersions from almost Hermitian manifolds to Riemannian manifolds, demonstrating that the fibers are anti-invariant under the almost complex structure. Consequently, the horizontal distribution is not preserved by this structure.

In this manuscript, we investigate inequalities involving the Ricci and scalar curvatures on the vertical and horizontal distributions of anti-invariant Riemannian submersions from quaternionic space forms. Section 2 presents the foundational geometric properties of Riemannian submersions and quaternionic K\"ahler manifolds. In Section 3, we derive new inequalities for the Ricci and scalar curvatures associated with the vertical and horizontal distributions, and we analyze the equality cases in detail.
\section{Preliminaries}
This section revisits fundamental definitions and presents established results related to Riemannian submersions and quaternionic K\"ahler manifolds, which will be utilized in the paper.  

\subsection{Submersion}

We will now present a set of definitions and results for future reference.

\begin{defn-new}
{\rm \cite{Baird}} A $C^{\infty }$-map $\pi:\left(
M,g_{M}\right)  \rightarrow \left( N,g_{N}\right) $  between Riemannian  manifolds $\left( M,g_{M}\right) $ and $\left( N,g_{N}\right) $ is said to be  $C^{\infty }$-submersion if
\begin{description}
\item[(i)] $\pi$ is surjective. 
\item[(ii)] The differential $\left(\pi_*\right)_p$ has maximal rank for any $
p \in M$.\newline
\end{description}
\end{defn-new}
\begin{defn-new}
{\rm {\cite{Falcitelli-Ianus and Pastore, O'Neill}}}
Let $(M,g_{M})$ and $
(N,g_{N})$ be Riemannian manifolds with $\dim (M)=m>n=\dim (N)$. A smooth surjective map $\pi :M\rightarrow N$ is said to be Riemannian submersion if $\pi$ satisfies the
following axioms:
\begin{description}
\item[(i)] $\pi$ has maximal rank.
\item[(ii)] The differential $\pi_{\ast }|_{(\operatorname{ker} \pi
_{\ast })^{\perp }}$ is a linear isometry.
\end{description}
\end{defn-new}



\noindent{\bf Remark:} For each $q\in N$, $\pi ^{-1}(q)$ is an $(m-n)$-dimensional submanifold of $%
M $. The submanifolds $\pi ^{-1}(q)$, $q\in N$, are called fibers. A vector
field on $M$ is called vertical if it is always tangent to the fibers. A vector
field on $M$ is called horizontal if it is always orthogonal to the fibers. A
vector field $X$ on $M$ is called basic if $X$ is horizontal and $\pi $%
-related to a vector field $X^{\prime }$ on $N$, that is, $\pi _{\ast
}X_{p}=X_{\pi _{\ast }(p)}^{\prime }$ for all $p\in M.$ We denote the
projection morphisms on the distributions $\operatorname{ker}\pi _{\ast }$ and $(\operatorname{ker} \pi
_{\ast })^{\perp }$ by ${\cal V}$ and ${\cal H}$, respectively. The sections
of ${\cal V}$ and ${\cal H}$ are called vertical vector fields and
horizontal vector fields, respectively. So
\[
{\cal V}_{p}=T_{p}\left( \pi ^{-1}(q)\right) ,\qquad {\cal H}%
_{p}=T_{p}\left( \pi ^{-1}(q)\right) ^{\perp }.
\]

\medskip


\noindent Let $\pi:\left( M,g_{M}\right) \rightarrow \left( N,g_{N}\right) $ 
be a Riemannian submersion. Given any vector field $U\in \Gamma (TM)$, 
we have  
\[
U={\cal V}U+{\cal H}U,  
\]
where ${\cal V}U\in \Gamma \left( {\operatorname{ker}}\pi_{\ast }\right)$ and
${\cal H}U\in \Gamma \left( \left( {\operatorname{ker}}\pi_{\ast }\right) ^{\perp }\right) $.


The second fundamental tensors of all fibers $\pi ^{-1}(q),\ q\in N$ give
rise to configuration tensors ${\mathcal{T}}$ and ${\mathcal{A}}$ in $M$ defined by O'Neill 
\cite{O'Neill}.  
\begin{eqnarray}
{\cal A}_{E}F &=&{\cal H}\nabla _{{\cal H}E}{\cal V}F+{\cal V}\nabla _{{\cal %
H}E}{\cal H}F, \\
{\cal T}_{E}F &=&{\cal H}\nabla _{{\cal V}E}{\cal V}F+{\cal V}\nabla _{{\cal %
V}E}{\cal H}F
\end{eqnarray}
for $E,F\in \Gamma (TM)$, where $\nabla $ is the Levi-Civita connection of $
g_{M}$.

From the above equations, we have  
\begin{equation}
\nabla _{X}Y={\cal T}_{X}Y+\widehat{\nabla }_{X}Y,
\end{equation}
\vspace{-0.7cm}
\begin{equation}
\nabla _{X}V={\cal H}\nabla _{X}V+{\cal T}_{X}V ,  \label{eq-aa}
\end{equation}
\begin{equation}
\nabla _{V}X={\cal A}_{V}X+{\cal V}\nabla _{V}X,
\end{equation}
\begin{equation}
\nabla _{V}W={\cal H}\nabla _{V}W+{\cal A}_{V}W,
\end{equation}
for $X,Y\in \Gamma  \left( {\operatorname{ker}}\pi_{\ast }\right)$ and $V,W\in
\Gamma \left( \left( {\operatorname{ker}}\pi_{\ast }\right) ^{\perp }\right) $, where $\widehat{
\nabla}_{X}Y={\cal V}\nabla _{X}Y$. If $V$ is basic, then ${\mathcal{A}}_{V}X={\cal H} 
\nabla _{X}V.$

\noindent It is easy to find that for $p\in M,$ $X\in {\cal V}_{p}$ and $U\in {\cal H}
_{p}$, the linear operators  
\[
{\mathcal{A}}_{U},{\mathcal{T}}_{X}:T_{p}M\rightarrow T_{p}M  
\]
are skew-symmetric. 
\newline The tensor fields ${\mathcal{T}}$ and ${\mathcal{V}}$ satisfy
\begin{align}
    {\mathcal{T}}_{U}W={\mathcal{T}}_{W}U,\\
    {\mathcal{A}}_{X}Y=-{\mathcal{A}}_{Y}X
\end{align}
for any $U,W \in {\mathcal{V}}(M)$ and $X,Y \in {\mathcal{H}}(M).$
\begin{lem} \rm{\cite{Gulbahar}}
    Let $ (M, g_{M})$  and $(N,g_{N})$ be Riemannian manifolds admitting a Riemannian submersion $\pi:M \rightarrow N.$ Let  $\left\{U_1, ..., U_r
, X_1, ..., X_\ell \right \}$  be an orthonormal
frame of $T_{p}M$  such that ${\mathcal{V}} = span \left \{U_1, ..., U_r  \right \}, {\mathcal{H}} = span \left \{X_1, ..., X_\ell \right \}$. Then at any point $p \in M,$ we have
    \begin{equation} \label{eq-3.15}
\sum_{s=1}^{\ell} \sum_{i,j=1}^{r}{({\mathcal{T}}_{ij}^{s})}^{2}= \frac{1}{2}r^{2} \lVert H \rVert ^{2} + ({\mathcal{T}}_{11}^{s}-{\mathcal{T}}_{22}^{s}- ... - {\mathcal{T}}_{rr}^{s})^{2} + 2\sum_{s=1}^{\ell} \sum_{j=2}^{r} ({\mathcal{T}}_{1j}^{s})^{2}-2\sum_{s=1}^{\ell} \sum_{2\leq i<j \leq r} ({\mathcal{T}}_{ii}^{s}{\mathcal{T}}_{jj}^{s}-({\mathcal{T}}_{ij}^{s})^{2}).
