\subsection{Quaternionic K\"ahler Manifold}

Let $M$ be a $4m$-dimensional $C^{\infty }$-manifold and let $E$ be a rank 3
subbundle of End $(TM)$ such that for any point $p\in M$ with a neighborhood
$U$, there exists a local basis $\left\{ J_{1},J_{2},J_{3}\right\} $ of 
sections of $E$ on $U$ satisfying  
\[
J_{\alpha}^{2}=-id,\quad J_{\alpha }J_{\alpha +1}=-J_{\alpha +1}J_{\alpha
}=J_{\alpha +2}  
\]
for all $\alpha \in \{1,2,3\}$,  where the indices are taken from $\{1,2,3\}$
modulo $3$. Then $E$ is said to  be an almost quaternionic structure on $M$
and $(M,E)$ an almost  quaternionic manifold \cite{Alekseevsky-Marchiafava}.

Moreover, let $g_M$ be a Riemannian metric on $M$ defined by  
\[
g_M\left( J_{\alpha }X,J_{\alpha }Y\right) =g_M(X,Y)  
\]
for all vector fields $X,Y\in \Gamma (TM)$, where the indices are taken from
$\{1,2,3\}$ modulo $3$. Then $(M,E,g_M)$ is said to be an almost quaternionic Hermitian manifold \cite%
{Ianus-Mazzocco-Vilcu} and the basis $\left\{ J_{1},J_{2},J_{3}\right\} $ is
said to be a quaternionic Hermitian basis.

An almost quaternionic Hermitian manifold $(M,E,g_M)$ is said to be a 
quaternionic K\"{a}hler manifold \cite{Ianus-Mazzocco-Vilcu} if there exist 
locally defined $1$-forms $\omega _{1},\omega _{2},\omega _{3}$ such that 
for $\alpha \in \{1,2,3\}$ modulo $3$  
\begin{equation}
\nabla _{X}J_{\alpha }=\omega _{\alpha +2}(X)J_{\alpha+1}-\omega _{\alpha
+1}(X)J_{\alpha +2}  \label{eq-qkm}
\end{equation}
for $X\in \Gamma (TM)$, where the indices are taken from $\{1,2,3\}$ modulo $
3$.

If there exists a global parallel quaternionic Hermitian basis $\left\{ 
J_{1},J_{2},J_{3}\right\} $ of sections of $E$ on $M$ (i.e. $\nabla J_{\alpha}=0$
for $\alpha \in \{1,2,3\}$, where $\nabla $ is the Levi-Civita connection of
the metric $g_M$, then $(M,E,g_M)$ is said to be a hyperk\"ahler manifold \cite%
{Besse}.
\begin{defn}
We call a Riemannian submersion $\pi:\left( M,E,g_{M}\right) \rightarrow 
\left( N,g_{N}\right) $ from quaternionic K\"ahler 
manifold $(M,E,g_{M})$  onto a Riemannian manifold $\left( N,g_{N}\right) $ an anti-invariant submersion {\rm \cite{Park-17}}
 if $J_\alpha\left( \operatorname{ker}\pi_{\ast }\right) \subset \left( {\ \operatorname{ker}} 
\pi_{\ast }\right) ^{\perp }$. 
\end{defn}
\noindent Let $\pi$ be an anti-invariant submersion  from quaternionic K\"ahler 
manifold $(M,E,g_{M})$  onto a Riemannian manifold $\left( N,g_{N}\right) $%
. Given a point $p\in M$ with a neighborhood $U$, we have an  
anti-invariant basis $
\{J_{1},J_{2},J_{3}\}$ of sections of $E$ on $U$. Given $X\in \Gamma  \left(
\left( \operatorname{ker}\pi_{\ast }\right) ^{\perp }\right) $, we have  
\begin{equation}\label{eq-7..}
J_\alpha X=B_{J_\alpha}X+C_{J_\alpha}X, \quad \alpha \in \{1,2,3\},
\end{equation}
where $B_{J_\alpha}X\in \Gamma \left( \operatorname{ker}\pi_{\ast }\right) $ and $C_{J_\alpha}X\in \Gamma
\left( \left( \operatorname{ker}\pi_{\ast }\right) ^{\perp }\right) $.


We denote the Riemannian curvature tensors of Riemannian manifolds $(M,g_{M}), (N,g_{N}),$ the vertical distribution ${\mathcal{V}}$ and the horizontal distribution ${\mathcal{H}},$ by $R, R', \hat{R}, R^{*}$, respectively.
Then the Gauss-Codazzi type equations \cite{O'Neill} are given by the following:
\begin{eqnarray}
    R(U,V,F,W) = \hat{R}(U,V,F,W) + g_{M}({\mathcal{T}}_{U}W,{\mathcal{T}}_{V}F) - g_{M}({\mathcal{T}}_{V}W,{\mathcal{T}}_{U}F),\label{eq-1} 
    \end{eqnarray}
    \begin{eqnarray}
    R(X,Y,Z,H) &=& R^{*}(X,Y,Z,H) - 2g_{M}({\mathcal{A}}_{X}Y,{\mathcal{A}}_{Z}H)\notag\\&& +g_{M}({\mathcal{A}}_{Y}Z,{\mathcal{A}}_{X}H) - g_{M}({\mathcal{A}}_{X}Z,{\mathcal{A}}_{Y}H), \label{eq-2} 
    \end{eqnarray}
    \begin{eqnarray}
    R(X,V,Y,W) &=& g_{M}((\nabla_{X}{\mathcal{T}})(V,W),Y) + g_{M}((\nabla_{V}{\mathcal{A}})(X,Y),W)\notag\\&&  - g_{M}({\mathcal{T}}_{V}X,{\mathcal{T}}_{W}Y) + g_{M}({\mathcal{A}}_{Y}W,{\mathcal{A}}_{X}V),\label{eq-3}
\end{eqnarray}
and
\begin{equation}
    \pi_{*}(R^{*}(X,Y)Z)=R'(\pi_{*}X,\pi_{*}Y)\pi_{*}Z,
\end{equation}
for all $U,V,F,W \in {\mathcal{V}}(M)$ and $X,Y,Z,H \in {\mathcal{H}}(M).$

\vspace{0.4cm}
\noindent Let $\{U_{1},\ldots,U_{r}\}$ be an orthonormal frame of the vertical distribution ${\mathcal{V}}$. The mean curvature vector field $H$ of any fibre of the Riemannian submersion $\pi$ is given by
\begin{equation}
    H=\frac{1}{r}N, \quad {\text \rm where }  \quad N=\sum_{j=1}^{r}{\mathcal{T}}_{U_{j}}U_{j}.
\end{equation}
The Riemannian submersion $\pi$ has totally geodesic fibres if ${\mathcal{T}}$ vanishes identically on $M$ and $\pi$ has totally umbilical fibres if
\[ {\mathcal{T}}_U V ={\mathcal T}(U,V)= g_{M}(U, V) H, \]
where $U, V \in {\mathcal{V}}(M)$ and $H$ is the mean curvature vector field of any fibre. 
The horizontal distribution $\mathcal{H}$ is integrable if  ${\mathcal{A}}$  vanishes identically. 

\vspace{0.2cm}
\noindent Let $\left( M,E,g_{M}\right) $ be a quaternionic K\"ahler manifold and let $X$ be a non-null vector on $M.$
Then the $4$-plane spanned by $\{X,J_{1}X,J_{2}X,J_{3}X\}$, denoted by $Q(X),$  is called a quaternionic
$4$-plane. Any $2$-plane in $Q(X)$  is called a quaternionic plane. The sectional curvature of
a quaternionic plane is called a quaternionic sectional curvature. A quaternionic K\"ahler
manifold is a quaternionic space form if its quaternionic sectional curvatures are equal
to a constant, say $c.$ A quaternionic K\"ahler manifold $ (M, E, g_{M})$  is a
quaternionic space form, denoted $M(c),$  if and only if its Riemannian curvature tensor $R$ on $M(c)$ is given by \rm{\cite{S Ishi}}
\vspace{-.1cm}
\begin{equation} \label{eq-2.9}
\begin{aligned}
    R(X, Y)Z = \frac{c}{4} \Bigg\{ & g_{M}(Y, Z)X - g_{M}(X, Z)Y \\
    & + \Bigg[ \sum_{\alpha = 1}^{3} \Big(
        g_{M}(J_{\alpha}Y, Z) J_{\alpha}X 
        - g_{M}(J_{\alpha}X, Z) J_{\alpha}Y 
        + 2g_{M}(J_{\alpha}Y, X) J_{\alpha}Z
    \Big) \Bigg] \Bigg\},
\end{aligned}
\end{equation}
for $X,Y,Z\in \Gamma (TM)$.

\subsection{Some useful results}
Now, we are stating some results that we will use in this work.
\begin{lem} \label{lem-14}{\rm \cite{Apostol}} Let $a_1, a_2, \ldots , a_n$ be $n$-real numbers ( $n>1$ ), then

$$
\frac{1}{n}\left(\sum_{i=1}^n a_i\right)^2 \leq \sum_{i=1}^n a_i^2
$$
with equality if and only if  $a_1=a_2=\ldots=a_n$.
\end{lem}
\begin{lem} \label{lem-11} Let $a$ and $b$ be non-negative real numbers, then

$$
\frac{a+b}{2} \geq \sqrt{a b}
$$
with equality if and only if $a=b$.
\end{lem}
\section{Ricci Inequalities for Quaternionic Space Form}

In this section, we establish some inequalities on the vertical and horizontal distributions for anti-invariant submersions from quaternionic space forms to Riemannian manifolds.\\

\noindent Let  $(M(c), g_{M})$ be a quaternionic space form, $ (N, g_{N})$ a Riemannian manifold and
 $\pi : M(c) \rightarrow N$  an anti-invariant submersion. Furthermore, let  $\left\{U_1, ..., U_r
, X_1, ..., X_\ell \right \}$  be an orthonormal
frame of $T_{p}M(c)$  such that ${\mathcal{V}} = span \left \{U_1, ..., U_r  \right \}, {\mathcal{H}} = span \left \{X_1, ..., X_\ell \right \}.$  Then using \rm(\ref{eq-1}), \rm(\ref{eq-2}) and \rm(\ref{eq-3}), we have
\begin{equation}
\begin{aligned}
    \widehat{R}(U,V,F,W) &=\frac{c}{4} \Bigg\{ g_{M}(V,F)g_{M}(U,W) - g_{M}(U,F)g_{M}(V,W) \\
    &+ \Bigg[ \sum_{\alpha = 1}^{3} \Big( g_{M}(J_{\alpha}V,F) g_{M}(J_{\alpha}U,W) 
        - g_{M}(J_{\alpha}U, F) g_{M}(J_{\alpha}V,W) \\
        &+ 2g_{M}(J_{\alpha}V, U) g_{M}(J_{\alpha}F,W)
    \Big) \Bigg] \Bigg\}- g_{M}({\mathcal{T}}_{U}W,{\mathcal{T}}_{V}F)+g_{M}({\mathcal{T}}_{V}W,{\mathcal{T}}_{U}F),
\end{aligned}
\label{3.1}
\end{equation}

\begin{equation}
\begin{aligned}
    R^{*}(X,Y,Z,H) &=\frac{c}{4} \Bigg\{ g_{M}(Y,Z)g_{M}(X,H) - g_{M}(X,Z)g_{M}(Y,H) \\
    &+ \Bigg[ \sum_{\alpha = 1}^{3} \Big( g_{M}(J_{\alpha}Y,Z) g_{M}(J_{\alpha}X,H) 
        - g_{M}(J_{\alpha}X, Z) g_{M}(J_{\alpha}Y,H) \\
        &+ 2g_{M}(J_{\alpha}Y, X) g_{M}(J_{\alpha}Z,H)
    \Big) \Bigg] \Bigg\}+ 2g_{M}({\mathcal{A}}_{X}Y,{\mathcal{A}}_{Z}H)-g_{M}({\mathcal{A}}_{Y}Z,{\mathcal{A}}_{X}H) \\
    &+g_{M}({\mathcal{A}}_{X}Z, {\mathcal{A}}_{Y}H).
\end{aligned}
\label{eq-3.2}
\end{equation}

\begin{thm}
Let $ \pi : M(c) \rightarrow N $  be an anti-invariant submersion from a quaternionic space form $ (M(c), g_M) $ onto
a Riemannian manifold $ (N, g_N).$ Then  
\begin{equation} \label{eq-3.3}
 \widehat{Ric}(U) \geq \frac{c}{4}(r-1)-r g_{M}\left( {\mathcal{T}}_{U}U,H\right), 
\end{equation} 
where $U$ is a unit vertical vector of $M(c)$.\newline
The equality case of {\rm (\ref{eq-3.3})} holds if and only if each fiber is totally geodesic.
\end{thm}

\noindent {\bf Proof:} Let $\{U_{1},U_{2}\ldots,U_{r}\}$ be a local orthonormal frame of the vertical distribution $ \operatorname{ker} \pi_{\ast}$ and $U$ a vertical vector. 
Since 
\[\widehat{Ric}(U)\equiv\widehat{Ric}(U,U) =\sum_{i = 1}^{r} \hat{R}(U,U_{i},U_{i},U).\]
Using equation \rm{(\ref{3.1})} we have 
$$
\begin{aligned}
    \widehat{Ric}(U) &=\frac{c}{4} \sum_{i = 1}^{r}\Bigg\{ g_{M}(U_{i},U_{i})g_{M}(U,U) - g_{M}(U,U_{i})g_{M}(U_{i},U) \\
    &+ \Bigg[ \sum_{\alpha = 1}^{3} \Big( g_{M}(J_{\alpha}U_{i},U_{i}) g_{M}(J_{\alpha}U,U) 
        - g_{M}(J_{\alpha}U, U_{i}) g_{M}(J_{\alpha}U_{i},U) \\
        &+ 2g_{M}(J_{\alpha}U_{i}, U) g_{M}(J_{\alpha}U_{i},U)
    \Big) \Bigg] \Bigg\}-\sum_{i = 1}^{r} g_{M}({\mathcal{T}}_{U}U,{\mathcal{T}}_{U_{i}}U_{i})+\sum_{i = 1}^{r}g_{M}({\mathcal{T}}_{U_{i}}U,{\mathcal{T}}_{U}U_{i}).
\end{aligned}
$$
Since $\pi$ is an anti-invariant submersion, therefore we get $g_{M}\left( J_{\alpha}U,U_{i}\right)=0 \quad \forall i, \alpha.$ \\
Now, we have 
\[ \widehat{Ric}(U)= \frac{c}{4}\sum_{i = 1}^{r}\left( 1-g_{M}(U,U_{i})^2\right)-\sum_{i = 1}^{r} g_{M}({\mathcal{T}}_{U}U,{\mathcal{T}}_{U_{i}}U_{i})+\sum_{i = 1}^{r}g_{M}({\mathcal{T}}_{U_{i}}U,{\mathcal{T}}_{U}U_{i}).\]
\begin{equation} \label{eq-6}
\widehat{Ric}(U)= \frac{c}{4}(r-1)-rg_{M}\left( {\mathcal{T}}_{U}U,H\right)+ \sum_{i = 1}^{r} \lVert{\mathcal{T}}_{U}U_{i} \rVert ^{2}. 
\end{equation}
\[\widehat{Ric}(U)\geq  \frac{c}{4}(r-1)-rg_{M}\left( {\mathcal{T}}_{U}U,H\right).\]
By using (\ref{eq-6}), we can say that the equality case of {\rm (\ref{eq-3.3})} holds if and only if each fiber is totally geodesic.
\begin{thm}
Let $ \pi : M(c) \rightarrow N $  be an anti-invariant submersion from a quaternionic space form $ (M(c), g_M) $ onto
a Riemannian manifold $ (N, g_N).$ Then
\begin{equation} \label{eq-3.4}
\hat{\tau} \geq \frac{c}{4}r(r-1) - r^{2} \lVert H\rVert ^{2}.
\end{equation}
The equality case of \rm (\ref{eq-3.4}) holds if and only if each fiber is totally geodesic.
\end{thm}
\noindent {\bf Proof:} 
We know that 
\[ \hat{\tau} = \sum_{j=1}^{r} \widehat{Ric}(U_{j},U_{j}).\]
Using \rm(\ref{eq-6}), we get
% \[ \hat{\tau} =\sum_{1\leq i < j \leq r} \hat{R}(U_{i},U_{j},U_{j},U_{i})\]
% \[ \hat{\tau} =\sum_{ 1\leq i < j \leq r} {R}(U_{i},U_{j},U_{j},U_{i})- \sum_{ 1 \leq i < j \leq r}g_{M}\left( {\mathcal{T}}_{U_{i}}U_{i}, {\mathcal{T}}_{U_{j}}U_{j} \right) + \sum_{ 1 \leq i < j \leq r} g_{M}\left( {\mathcal{T}}_{U_{j}}U_{i}, {\mathcal{T}}_{U_{i}}U_{j} \right)\]
% Since $J_{\alpha} {\mathcal{(V)}}\subset {\mathcal{H}} $ so all $J_{\alpha}$ 
% terms vanishes and therefore, we get
% \[  \hat{\tau} = \frac{c}{4} \frac{r(r-1)}{2}-\sum_{ i < j }g_{M}\left( {\mathcal{T}}_{U_{i}}U_{i}, {\mathcal{T}}_{U_{j}}U_{j} \right) + \sum_{ i < j} g_{M}\left( {\mathcal{T}}_{U_{j}}U_{i}, {\mathcal{T}}_{U_{i}}U_{j} \right) \]
% \begin{equation} \label{eq-3.5}
% 2 \hat{\tau} = \frac{c}{4}{r(r-1)}- r^{2} \lVert H \rVert ^{2} + \sum_{ i,j=1}^{r} g_{M}\left( {\mathcal{T}}_{U_{i}}U_{j}, {\mathcal{T}}_{U_{i}}U_{j} \right)
% \end{equation}
\begin{equation} \label{eq-8.} 
\hat{\tau} = \frac{c}{4}{r(r-1)}- r^{2} \lVert H \rVert ^{2}+ \sum_{i,j = 1}^{r} \lVert{\mathcal{T}}_{U_j}U_{i} \rVert ^{2} .\end{equation}
\[  \hat{\tau} \geq \frac{c}{4}{r(r-1)}- r^{2} \lVert H \rVert ^{2}.\]

\begin{thm}
Let $\pi: M(c) \rightarrow N $ be an anti-invariant submersion from a quaternionic space form $(M(c),g_{M})$ onto a Riemannian manifold $(N,g_{N}).$ Then
\begin{equation} \label{eq-7}
Ric^*(X) \leq \frac{c}{4} \Bigg\{ (\ell -1) 
    +\sum_{j=1}^{\ell} \sum_{\alpha = 1}^{3} 
        3g_{M}(C_{J_{\alpha}}X, X_{j})^2
      \Bigg\},\end{equation}
where $X$ is a unit horizontal vector of $M(c)$.\\
The equality case of \rm(\ref{eq-7}) holds if and only if ${\mathcal{H}}(M)$ is integrable.
\end{thm}
{\bf Proof:}  Let $\{X_{1},X_{2}\ldots,X_{\ell}\}$ be a local orthonormal frame of the horizontal distribution $ (\operatorname{ker} \pi_{\ast})^\perp$.
Since 
\[ {Ric}^{*}(X) =\sum_{j = 1}^{\ell} {R}^{*}(X,X_{j},X_{j},X),\]
using equation \rm{(\ref{eq-3.2})}, we have 
\begin{equation}
\begin{aligned} \label {eq-3.7}
    Ric^*(X) &=\sum_{j=1}^{_\ell}\frac{c}{4} \Bigg\{ g_{M}(X_{j},X_{j})g_{M}(X,X) - g_{M}(X,X_{j})g_{M}(X_{j},X) \\
    &+ \Bigg[ \sum_{\alpha = 1}^{3} \Big( g_{M}(J_{\alpha}X_{j},X_{j}) g_{M}(J_{\alpha}X,X) 
        - g_{M}(J_{\alpha}X, X_{j}) g_{M}(J_{\alpha}X_{j},X) \\
        &+ 2g_{M}(J_{\alpha}X_{j}, X) g_{M}(J_{\alpha}X_{j},X)
    \Big) \Bigg] \Bigg\}+ 2g_{M}({\mathcal{A}}_{X}X_{j},{\mathcal{A}}_{X_{j}}X)\\
    &-g_{M}({\mathcal{A}}_{X_{j}}X_{j},{\mathcal{A}}_{X}X) +g_{M}({\mathcal{A}}_{X}X_{j}, {\mathcal{A}}_{X_{j}}X).
\end{aligned}
\end{equation}
Using (\ref{eq-7..}), we have $$ 
\begin{aligned}
  Ric^*(X) &=\sum_{j=1}^{\ell}\frac{c}{4} \Bigg\{ (1-g_{M}(X,X_{j})^{2}) 
    + \sum_{\alpha = 1}^{3} 
        3g_{M}(C_{J_{\alpha}}X, X_{j})^2
      \Bigg\}\\&
    - \sum_{j=1}^{\ell}\left(3 g_{M}({\mathcal{A}}_{X}X_{j},{\mathcal{A}}_{X}X_{j})
    +g_{M}({\mathcal{A}}_{X_{j}}X_{j},{\mathcal{A}}_{X}X)\right).
\end{aligned}
$$
\begin{equation}
  Ric^*(X) =\frac{c}{4} \Bigg\{ (\ell -1) 
    +\sum_{j=1}^{\ell} \sum_{\alpha = 1}^{3} 
        3g_{M}(C_{J_{\alpha}}X, X_{j})^2
      \Bigg\}-  \sum_{j=1}^{\ell}3 \lVert{\mathcal{A}}_{X}X_{j} \rVert ^{2}.
      \label{eq-7.}
\end{equation}
\begin{equation*} 
Ric^*(X) \leq \frac{c}{4} \Bigg\{ (\ell -1) 
    +\sum_{j=1}^{\ell} \sum_{\alpha = 1}^{3} 
        3g_{M}(C_{J_{\alpha}}X, X_{j})^2
      \Bigg\}.\end{equation*}
By using (\ref{eq-7.}), we can say that the equality case of \rm(\ref{eq-7}) holds if and only if ${\mathcal{H}}(M)$ is integrable.
\begin{thm}
Let $\pi: M(c) \rightarrow N $ be an anti-invariant submersion from a quaternionic space form $(M(c),g_{M})$ onto a Riemannian manifold $(N,g_{N}).$ Then
\begin{equation}\label{eq-3.11}
\tau^* \leq \frac{c}{4}\Bigg\{ \ell (\ell -1) 
    +\sum_{i=1}^{\ell} \sum_{\alpha = 1}^{3} 
        3\lVert C_{J_{\alpha}}X_i\rVert^2
      \Bigg\}. 
\end{equation}
The equality case of \rm (\ref{eq-3.11}) holds if and only if ${\mathcal{H}}(M)$ is integrable.
\end{thm}
{\bf Proof:} 
We know that 
\[ {\tau}^{*} = \sum_{i=1}^{\ell} {Ric}^*(X_{i},X_{i}).\]
Using \rm(\ref{eq-7.}), we get
\begin{equation*}
\tau^* =\frac{c}{4}\sum_{i=1} ^{\ell}\Bigg\{ (\ell -1) 
    +\sum_{j=1}^{\ell} \sum_{\alpha = 1}^{3} 
        3g_{M}(C_{J_{\alpha}}X_i, X_{j})^2
      \Bigg\}-  \sum_{i,j=1}^{\ell}3 \lVert{\mathcal{A}}_{X_i}X_{j} \rVert ^{2}. 
\end{equation*}
\begin{equation}
\tau^* =\frac{c}{4}\Bigg\{\ell (\ell -1) 
    +\sum_{i=1}^{\ell} \sum_{\alpha = 1}^{3} 
        3\lVert C_{J_{\alpha}}X_i\rVert^2
      \Bigg\}-  \sum_{i,j=1}^{\ell}3 \lVert{\mathcal{A}}_{X_i}X_{j} \rVert ^{2}, 
      \label{eq-3.10}
\end{equation}
where $$\lVert C_{J_{\alpha}}X_i\rVert^2=\sum_{j=1}^{\ell}g_{M}(C_{J_{\alpha}}X_i, X_{j})^2.$$

\begin{equation*}
\tau^* \leq \frac{c}{4}\Bigg\{ \ell (\ell -1) 
    +\sum_{i=1}^{\ell} \sum_{\alpha = 1}^{3} 
        3\lVert C_{J_{\alpha}}X_i\rVert^2
      \Bigg\}. 
\end{equation*}
