\noindent Define \rm{\cite{Gulbahar}} 
\begin{equation} \label{eq-3.12}
 {\mathcal{T}}_{ij}^{s}= g_{M}({\mathcal{T}}_{U_{i}}U_{j},X_{s}),
\end{equation}
\noindent where $ 1\leq i, j\leq r$ and $1 \leq s \leq \ell$
and
\begin{equation} \label{eq-3.13}
{\mathcal{A}}_{ij}^{\beta}=g_{M}({\mathcal{A}}_{X_{i}}X_{j},U_{\beta}),
\end{equation}
 where $1 \leq i, j \leq \ell $ and $1 \leq \beta \leq r.$  
\newline 
\noindent Since $\{U_1, \ldots, U_r\}$ is an orthonormal frame of ${\mathcal{V}}(M)$. Then, it follows that
 \[
 g(\nabla_E N, X) = \sum_{j=1}^r g((\nabla_E {\mathcal{T}})(U_j, U_j), X),
\]
 for any $E \in \Gamma (TM)$ and $X \in {\mathcal{H}}(M)$ \rm{\cite{Falcitelli-Ianus and Pastore}}.

The horizontal divergence of any vector field $X$ on ${\mathcal{H}}(M)$ is given by ${\delta}(X)$ and defined by
\[
{\delta}(X) = \sum_{i=1}^\ell g(\nabla_{X_i} X, X_i),
\]
where $\{X_1, \ldots, X_\ell \}$ is a local orthonormal frame of ${\mathcal{H}}(M)$. Then one has \rm{\cite{Besse}}
\begin{equation} \label{eq-3.14}
\delta(N)=\sum_{i=1}^{\ell} \sum_{k=1}^{r} g_{M}((\nabla _{X_{i}}{\mathcal{T}})(U_{k},U_{k}),X_{i}).
\end{equation}

\begin{thm}
Let $\pi: M(c) \rightarrow N $ be an anti-invariant submersion from a quaternionic space form $(M(c),g_{M})$ onto a Riemannian manifold $(N,g_{N}).$ Then we have 
\begin{equation} \label{eq-3.16}
\widehat{Ric}(U_{1}) \geq \frac{c}{4}(r-1) -\frac{1}{4}r^{2} \lVert H \rVert ^{2}.
\end{equation}
% \[\widehat{Ric}(U_{1}) \geq \frac{c}{4}(r-1)-\frac{1}{4}r^{2} \lVert H \rVert ^{2}.\]
The equality case of {\rm (\ref{eq-3.16})} holds if and only if
$$
\begin{aligned}
{\mathcal{T}}_{11}^{s}&={\mathcal{T}}_{22}^{s}+ \cdots + {\mathcal{T}}_{rr}^{s},\\
{\mathcal{T}}_{ij}^{s}&=0, \quad j=2,\ldots, r.
\end{aligned}
$$
\end{thm}
{\bf Proof:} Using \rm(\ref{eq-3.12}) in \rm(\ref{eq-8.}), we have
\begin{equation} \label{eq-3.17}
 \hat{\tau}=\frac{c}{4}r(r-1)-r^{2}\lVert H \rVert ^{2} +\sum_{s=1}^{\ell} \sum _{i,j=1}^{r} ({\mathcal{T}}_{ij}^{s})^{2}.
\end{equation}
Thus using \rm(\ref{eq-3.15}) in \rm (\ref{eq-3.17}) can be written as
\begin{equation} \label{eq-3.18}
 \hat{\tau}=\frac{c}{4}r(r-1)- \frac{1}{2}r^{2}\lVert H \rVert ^{2}+({\mathcal{T}}_{11}^{s}-{\mathcal{T}}_{22}^{s}- ... - {\mathcal{T}}_{rr}^{s})^{2} + 2\sum_{s=1}^{\ell} \sum_{j=2}^{r} ({\mathcal{T}}_{1j}^{s})^{2}-2\sum_{s=1}^{\ell} \sum_{2\leq i<j \leq r} ({\mathcal{T}}_{ii}^{s}{\mathcal{T}}_{jj}^{s}-({\mathcal{T}}_{ij}^{s})^{2}).
\end{equation}
Then from \rm(\ref{eq-3.18}), we have
 \begin{equation} \label{eq-3.19}
 \hat{\tau} \geq\frac{c}{4}r(r-1)- \frac{1}{2}r^{2}\lVert H \rVert ^{2}-2\sum_{s=1}^{\ell} \sum_{2\leq i<j \leq r} ({\mathcal{T}}_{ii}^{s}{\mathcal{T}}_{jj}^{s}-({\mathcal{T}}_{ij}^{s})^{2}).
\end{equation}
Taking $U=W=U_{i}, \quad V=F=U_{j}$ in {\rm(\ref{eq-1})} and using {\rm(\ref{eq-3.12})}, we get
\begin{equation}\label{eq-3.20}
 \sum_{2 \leq i < j \leq r}R(U_{i},U_{j},U_{j},U_{i})=  \sum_{2 \leq i < j \leq r} \hat{R} (U_{i},U_{j},U_{j},U_{i})+ \sum_{s=1}^{\ell} \sum_{2\leq i<j \leq r} ({\mathcal{T}}_{ii}^{s}{\mathcal{T}}_{jj}^{s}-({\mathcal{T}}_{ij}^{s})^{2}).
\end{equation}
Using {\rm(\ref{eq-3.20})} in {\rm(\ref{eq-3.19})}, we get
\begin{equation} \label{eq-3.21}
 \hat{\tau}\geq\frac{c}{4}r(r-1)- \frac{1}{2}r^{2}\lVert H \rVert ^{2}+2 \sum_{2 \leq i < j \leq r} \hat{R} (U_{i},U_{j},U_{j},U_{i})-2 \sum_{2 \leq i < j \leq r}R(U_{i},U_{j},U_{j},U_{i}).
\end{equation}
We also have
\begin{equation} \label{eq-3.22}
 \hat{\tau}= 2\sum_{2 \leq i < j \leq r} \hat{R} (U_{i},U_{j},U_{j},U_{i})+ 2\sum_{j=1}^{r} \hat{R} (U_{1},U_{j},U_{j},U_{1}).
\end{equation}
Considering {\rm(\ref{eq-3.22})} in {\rm(\ref{eq-3.21})}, we obtain
\begin{equation}\label{eq-3.33}
 2\widehat{Ric}(U_{1}) \geq \frac{c}{4}r(r-1)- \frac{1}{2}r^{2}\lVert H \rVert ^{2}-2 \sum_{2 \leq i < j \leq r}R(U_{i},U_{j},U_{j},U_{i}).
\end{equation}
By {\rm(\ref{eq-2.9})}, we have
\begin{equation}\label{eq-24}
\sum_{2 \leq i < j \leq r}R(U_{i},U_{j},U_{j},U_{i})=\frac{c}{8}(r-1)(r-2).
\end{equation}
From {\rm(\ref{eq-3.33})} and {\rm(\ref{eq-24})}, we obtain  
% \[\widehat{Ric}(U_{1}) \geq \frac{c}{4}(r-1)-\frac{1}{4}r^{2} \lVert H \rVert ^{2}.\] 
\[\widehat{Ric}(U_{1}) \geq \frac{c}{4}(r-1)-\frac{1}{4}r^{2} \lVert H \rVert ^{2}.\]
\begin{thm}
    Let $\pi: M(c) \rightarrow N$ be an anti-invariant submersion from a quaternionic space form $ (M(c),g_{M})$ onto a Riemannian manifold $(N,g_{N}).$ Then we have 
    \begin{equation} \label{eq-3.25}
2 Ric^{*}(X_{1}) \leq \frac{c}{4}\left(2(\ell-1)
+3\lVert C_{J_\alpha}X_{1} \rVert ^{2} \right).
    \end{equation}
    The equality case of {\rm(\ref{eq-3.25})} holds if and only if 
    \[{\mathcal{A}}_{1j}^{\beta}=0, \hspace{0.1mm} j=2,...,\ell.\]
