Taking $X=H=X_{i},\quad Y=Z=X_{j}$ in {\rm(\ref{eq-2})} and using {\rm(\ref{eq-3.13})}, we obtain
\begin{equation} \label{eq-3.28}
 2\sum_{2 \leq i<j \leq \ell}R(X_{i},X_{j},X_{j},X_{i})=2\sum_{2 \leq i<j \leq \ell}R^{*}(X_{i},X_{j},X_{j},X_{i})+6\sum_{\beta=1}^{r}\sum_{2 \leq i<j \leq \ell}({\mathcal{A}}_{ij}^{\beta})^{2}.
\end{equation}
Using {\rm(\ref{eq-3.28})} in {\rm(\ref{eq-3.27})}, we get
\begin{equation} \label{eq-3.29}
\begin{aligned}
\tau_{*}&= \frac{c}{4}\left( \ell(\ell-1) + 3 \sum_{i=1}^{\ell}\sum_{\alpha=1}^{3}\lVert C_{J_\alpha }X_i \rVert ^{2}\right)-6\sum_{\beta=1}^{r}\sum_{j=2}^{\ell}({\mathcal{A}}_{1j}^{\beta})^{2}\\
&+2\sum_{2 \leq i<j \leq \ell}R^{*}(X_{i},X_{j},X_{j},X_{i})-2\sum_{2 \leq i<j \leq \ell}R(X_{i},X_{j},X_{j},X_{i}).
\end{aligned}
\end{equation}
From {\rm(\ref{eq-2.9})}, we obtain
\begin{equation} \label{eq-3.30}
\sum_{2 \leq i<j \leq \ell}R(X_{i},X_{j},X_{j},X_{i})=\frac{c}{4}\left( \frac{(\ell-1)(\ell-2)}{2}+ 3 \sum_{2 \leq i<j \leq \ell}\  \sum_{\alpha=1}^{3} g_{M}(C_{J_\alpha}X_{i},X_{j}) ^{2}\right).
