\end{equation}\begin{equation}
\begin{aligned}
\tau & =\sum_{j, k=1}^r R\left(U_j, U_k, U_k, U_j\right)+\sum_{i=1}^\ell \sum_{k=1}^r R\left(X_i, U_k, U_k, X_i\right) \\
& +\sum_{i, s=1}^\ell R\left(X_i, X_s, X_s, X_i\right)+\sum_{s=1}^\ell \sum_{j=1}^r R\left(U_j, X_s, X_s, U_j\right) .
\end{aligned}
\label{eq-9}
\end{equation}
Let us denote,
\begin{equation}\label{eq-35}
