&\frac{c}{4} \left[ (\ell+r)(\ell+r-1) + 3 \sum_{\alpha=1}^{3}\sum_{i=1}^{\ell} \left(  \lVert C_{J_\alpha}X_i \rVert ^{2} + 2\lVert B_{J_\alpha}X_i \rVert ^{2}\right) \right]\\&=2\widehat{Ric}(U_{1}) + 2{Ric}^{*}(X_{1})+\frac{c}{2} \left( \frac{(\ell-1)(\ell-2)}{2}+ 3 \sum_{\alpha=1}^{3}\sum_{2 \leq i<j \leq \ell}^{} g_M( C_{J_\alpha}X_i, X_j) ^{2} \right) \\
&+\frac{1}{2}r^{2} \lVert H \rVert ^{2}-({\mathcal{T}}_{11}^{s}-{\mathcal{T}}_{22}^{s}- \cdots- {\mathcal{T}}_{rr}^{s})^{2}
-2\sum_{s=1}^{\ell}\sum_{j=2}^{r}({\mathcal{T}}_{1j}^{s})^{2}+6\sum_{\beta=1}^{r}\sum_{s=2}^{\ell}({\mathcal{A}}_{1s}^{\beta})^{2}-2\delta(N)\\
&+ 2\sum_{i=1}^{\ell}\sum_{k=1}^{r}\left( g_{M}({\mathcal{T}}_{U_{k}}X_{i},{\mathcal{T}}_{U_{k}}X_{i})
-g_{M}({\mathcal{A}}_{X_{i}}U_{k}, {\mathcal{A}}_{X_{i}}U_{k}) \right)+\frac{c}{4}(r-1)(r-2).
\end{aligned}
\end{equation}
Using {\rm(\ref{eq-24}), \rm(\ref{eq-3.30}), \rm(\ref{eq-35})} and {\rm(\ref{eq-38})} in {\rm(\ref{eq-3.39})}, we obtain the inequality
$$
\begin{aligned}
&\frac{c}{4}\left(\ell r+\ell+r+\sum_{\alpha =1}^{3}\left( \sum_{i=1}^{\ell} \lVert B_{J_\alpha}X_i \rVert ^{2}+3 \lVert C_{J_\alpha}X_{1} \rVert ^{2}\right) \right) \\
&\leq \widehat{Ric}(U_{1})+Ric^{*}(X_{1}) + \frac{1}{4} r^{2} \lVert H \rVert ^{2}+3 \sum_{\beta =1}^{r} \sum_{s=2}^{\ell} ({\mathcal{A}}_{1s}^{\beta})^{2} -\delta (N) + \left\| {\mathcal{T}}^{\mathcal{V}}\right\|^{2}-\left\| {\mathcal{A}}^{\mathcal{H}} \right\|^{2}.
\end{aligned}
$$

\vspace{0.3cm}
\noindent From {\rm(\ref{eq-35}), \rm(\ref{eq-38}), \rm(\ref{eq-3.34}), \rm(\ref{eq-3.35})} and {\rm(\ref{eq-3.36})}, we obtain
\begin{equation}\label{eq-3.47}
\begin{aligned}
& \frac{c}{4}\left((\ell+r)(\ell+r-1)+\sum_{\alpha =1}^{3}\left( \sum_{i=1}^{\ell} 6\lVert B_{J_\alpha}X_i \rVert ^{2}+3 \lVert C_{J_\alpha}X_{1} \rVert ^{2}\right) \right)\\&= \hat{\tau}+ \tau^* 
 +r^2\|H\|^2-\left\|{\mathcal{T}}^{\mathcal{H}}\right\|^2+3\left\|{\mathcal{A}}^{\mathcal{V}}\right\|^2-2 \delta(N)+2\left\|{\mathcal{T}}^{\mathcal{V}}\right\|^2-2\left\|{\mathcal{A}}^{\mathcal{H}}\right\|^2.
\end{aligned}
\end{equation}
From {\rm(\ref{eq-3.47})}, we obtain the following theorem:
\begin{thm} \label{th-7}
Let $\pi: M(c) \rightarrow N$ be an anti-invariant submersion from a quaternionic space form $\left(M(c), g_M\right)$ onto a Riemannian manifold $(N,g_{N})$. Then we have
\begin{equation} \label{eq-3.48}
\begin{aligned}
 \hat{\tau}+ \tau^* & \leq  \frac{c}{4}\left((\ell+r)(\ell+r-1)+\sum_{\alpha =1}^{3}\left( \sum_{i=1}^{\ell} 6\lVert B_{J_\alpha}X_i \rVert ^{2}+3 \lVert C_{J_\alpha}X_{1} \rVert ^{2}\right) \right) \\
&-r^2\|H\|^2+\left\|{\mathcal{T}}^{\mathcal{H}}\right\|^2+2 \delta(N)-2\left\|{\mathcal{T}}^{\mathcal{V}}\right\|^2+2\left\|{\mathcal{A}}^{\mathcal{H}}\right\|^2,
\end{aligned}
\end{equation}
\begin{equation}\label{eq-3.49}
\begin{aligned}
 \hat{\tau}+ \tau^* & \geq \frac{c}{4}\left((\ell+r)(\ell+r-1)+\sum_{\alpha =1}^{3}\left( \sum_{i=1}^{\ell} 6\lVert B_{J_\alpha}X_i \rVert ^{2}+3 \lVert C_{J_\alpha}X_{1} \rVert ^{2}\right) \right) \\
& -r^2\|H\|^2+\left\|{\mathcal{T}}^{\mathcal{H}}\right\|^2-3\left\|{\mathcal{A}}^{\mathcal{V}}\right\|^2+2 \delta(N)-2\left\|{\mathcal{T}}^{\mathcal{V}}\right\|^2.
\end{aligned}
\end{equation}
\noindent Equality cases of {\rm(\ref{eq-3.48})} and {\rm(\ref{eq-3.49})}  hold for all $p \in M$ if and only if horizontal distribution $\mathcal{H}$ is integrable.
\end{thm}
From Theorem~\ref{th-7}, we have the following corollary:
\begin{cor}Let $\pi: M(c) \rightarrow N$ be an anti-invariant submersion from a quaternionic space form  $(M(c), g_M)$  onto a Riemannian manifold  $(N, g_N)$  such that each fibres be totally geodesic. Then we have
\begin{equation}\label{eq-3.50}
\begin{aligned}
&  \hat{\tau}+ \tau^* \leq \frac{c}{4}\left((\ell+r)(\ell+r-1)+\sum_{\alpha =1}^{3}\left( \sum_{i=1}^{\ell} 6\lVert B_{J_\alpha}X_i \rVert ^{2}+3 \lVert C_{J_\alpha}X_{1} \rVert ^{2}\right) \right)+2\left\|{\mathcal{A}}^{\mathcal{H}}\right\|^2, 
\end{aligned}
\end{equation}
\begin{equation}\label{eq-3.51}
\begin{aligned}
&  \hat{\tau}+ \tau^* \geq \frac{c}{4}\left((\ell+r)(\ell+r-1)+\sum_{\alpha =1}^{3}\left( \sum_{i=1}^{\ell} 6\lVert B_{J_\alpha}X_i \rVert ^{2}+3 \lVert C_{J_\alpha}X_{1} \rVert ^{2}\right) \right)-3\left\|{\mathcal{A}}^{\mathcal{V}}\right\|^2.
\end{aligned}
\end{equation}
\noindent Equality cases of {\rm(\ref{eq-3.50})} and {\rm(\ref{eq-3.51})} hold for all $p \in M$ if and only if horizontal distribution $\mathcal{H}$ is integrable.
\end{cor}
From {\rm(\ref{eq-3.47})} we obtain following theorem:
\begin{thm} \label{th-9} Let $\pi: M(c) \rightarrow N$ be an anti-invariant submersion from a quaternionic space form  $(M(c), g_M)$  onto a Riemannian manifold  $(N,g_{N}).$ Then we have
\begin{equation}\label{eq-3.52}
\begin{aligned}
 \hat{\tau}+ \tau^* & \geq \frac{c}{4}\left((\ell+r)(\ell+r-1)+\sum_{\alpha =1}^{3}\left( \sum_{i=1}^{\ell} 6\lVert B_{J_\alpha}X_i \rVert ^{2}+3 \lVert C_{J_\alpha}X_{1} \rVert ^{2}\right) \right) \\
& -r^2\|H\|^2+2 \delta(N)-2\left\|{\mathcal{T}}^{\mathcal{V}}\right\|^2+2\left\|{\mathcal{A}}^{\mathcal{H}}\right\|^2-3\left\|{\mathcal{A}}^{\mathcal{V}}\right\|^2,
\end{aligned}
\end{equation}
\begin{equation}\label{eq-3.53}
\begin{aligned}
 \hat{\tau}+ \tau^* & \leq \frac{c}{4}\left((\ell+r)(\ell+r-1)+\sum_{\alpha =1}^{3}\left( \sum_{i=1}^{\ell} 6\lVert B_{J_\alpha}X_i \rVert ^{2}+3 \lVert C_{J_\alpha}X_{1} \rVert ^{2}\right) \right) \\
& -r^2\|H\|^2+\left\|{\mathcal{T}}^{\mathcal{H}}\right\|^2+2 \delta(N)+2\left\|{\mathcal{A}}^{\mathcal{H}}\right\|^2-3\left\|{\mathcal{A}}^{\mathcal{V}}\right\|^2.
\end{aligned}
\end{equation}
\noindent Equality cases of {\rm(\ref{eq-3.52})} and {\rm(\ref{eq-3.53})} hold for all $p \in M$ if and only if the fibre through $p$ of $\pi$ is a totally geodesic submanifold of $M$.
\end{thm}
From Theorem~\ref{th-9}, we have the following corollary:
\begin{cor}
Let $\pi:$ Let $\pi: M(c) \rightarrow N$ be an anti-invariant submersion from a quaternionic space form  $(M(c), g_M)$  onto a Riemannian manifold  $(N, g_N)$  such that ${\mathcal{H}}$ be integrable. Then we have
