\begin{thm} \label{th-15}Let $\pi: M(c) \rightarrow N$ be an anti-invariant submersion from a quaternionic space form $\left(M(c), g_M\right)$ onto a Riemannian manifold  $(N, g_N).$ Then we have
\begin{equation}\label{eq-3.58}
\begin{aligned}
& \frac{c}{4}\left((\ell+r)(\ell+r-1)+\sum_{\alpha =1}^{3}\left( \sum_{i=1}^{\ell} 6\lVert B_{J_\alpha}X_i \rVert ^{2}+3 \lVert C_{J_\alpha}X_{1} \rVert ^{2}\right) \right) \\ & \leq  \hat{\tau}+ \tau^* 
+r(r-1)\|H\|^2+3\left\|{\mathcal{A}}^{\mathcal{V}}\right\|^2-2 \delta(N)+2\left\|{\mathcal{T}}^{\mathcal{V}}\right\|^2-2\left\|{\mathcal{A}}^{\mathcal{H}}\right\|^2.
\end{aligned}
\end{equation}
\noindent Equality case of {\rm(\ref{eq-3.58})} holds for all $p \in M$ if and only if we have the following statements:
\begin{enumerate}
    \item $\pi$ is a Riemannian submersion that has a totally umbilical fibres.
    \item ${\mathcal{T}}_{i j}=0$, for $i \neq j \in\{1,2, \ldots, r\}$.
\end{enumerate} 
\end{thm}
{\bf Proof:} From {\rm(\ref{eq-3.47})}, we have
\begin{equation} \label{eq-3.59}
\begin{aligned}
& \frac{c}{4}\left((\ell+r)(\ell+r-1)+\sum_{\alpha =1}^{3}\left( \sum_{i=1}^{\ell} 6\lVert B_{J_\alpha}X_i \rVert ^{2}+3 \lVert C_{J_\alpha}X_{1} \rVert ^{2}\right) \right) 
=\hat{\tau}+ \tau^*+r^2\|H\|^2 \\
&-\sum_{s=1}^\ell \sum_{j=1}^r\left({\mathcal{T}}_{j j}^s\right)^2
-2 \sum_{s=1}^\ell \sum_{j \neq k}^r\left({\mathcal{T}}_jk^s\right)^2+3\left\|{\mathcal{A}}^{\mathcal{V}}\right\|^2-2 \delta(N)+2\left\|{\mathcal{T}}^{\mathcal{V}}\right\|^2-2\left\|{\mathcal{A}}^{\mathcal{H}}\right\|^2 .
\end{aligned}
\end{equation}
Using Lemma~(\ref{lem-14}) in {\rm(\ref{eq-3.59})}, we obtain
$$
\begin{aligned}
&\frac{c}{4}\left((\ell+r)(\ell+r-1)+\sum_{\alpha =1}^{3}\left( \sum_{i=1}^{\ell} 6\lVert B_{J_\alpha}X_i \rVert ^{2}+3 \lVert C_{J_\alpha}X_{1} \rVert ^{2}\right) \right) 
\leq  \hat{\tau}+ \tau^*+r^2\|H\|^2\\
&-\frac{1}{r} \sum_{s=1}^\ell\left(\sum_{j=1}^r {\mathcal{T}}_{j j}^s\right)^2-2 \sum_{s=1}^\ell \sum_{j \neq k}^r\left({\mathcal{T}}_{jk}^s\right)^2+3\left\|{\mathcal { A }} ^ {\mathcal{V}}\right\|^2-2 \delta(N)+2\|{\mathcal{T}}^{\mathcal{V}}\|^2-2\left\|{\mathcal{\mathcal { A }} ^ { H }}\right\|^2,
\end{aligned}
$$
which is equivalent to {\rm (\ref{eq-3.58})}. Equality case of {\rm (\ref{eq-3.58})} holds for all $p \in M$ if and only if
$$
{\mathcal{T}}_{11}={\mathcal{T}}_{22}=\ldots={\mathcal{T}}_{rr} \quad \text { and } \quad \sum_{s=1}^\ell \sum_{j \neq k}^r\left({\mathcal{T}}_{jk}^s\right)^2=0,
$$
which completes proof of the theorem.
\newline \noindent
Using a similar proof approach as in Theorem~\ref{th-15}, we have the following theorem:
\begin{thm} \label{th-16} Let $\pi: M(c) \rightarrow N$ be an anti-invariant submersion from a quaternionic space form ( $M(c), g_M$ ) onto a Riemannian manifold $\left(N, g_N\right)$.Then we have
\begin{equation} \label{eq-3.60}
\begin{aligned}
& \frac{c}{4}\left((\ell+r)(\ell+r-1)+\sum_{\alpha =1}^{3}\left( \sum_{i=1}^{\ell} 6\lVert B_{J_\alpha}X_i \rVert ^{2}+3 \lVert C_{J_\alpha}X_{1} \rVert ^{2}\right) \right)  \geq  \hat{\tau}+ \tau^* \\
& +r^2\|H\|^2-\left\|{\mathcal{T}}^{\mathcal{H}}\right\|^2+\frac{3}{\ell}\operatorname{tr}\left({\mathcal{A}}^{\mathcal{V}}\right)^2-2 \delta(N)+2\left\|{\mathcal{T}}^{\mathcal{V}}\right\|^2-2\left\|{\mathcal{A}}^{\mathcal{H}}\right\|^2.
\end{aligned}
\end{equation}
Equality case of {\rm(\ref{eq-3.60})} holds for all $p \in M$ if and only if ${\mathcal{A}}_{11}={\mathcal{A}}_{22}=\ldots={\mathcal{A}}_{\ell \ell}$ and ${\mathcal{A}}_{i j}=0$, for $i \neq j \in\{1,2, \ldots, \ell \}$.
\end{thm}
From Theorem~\ref{th-16}, we have the following corollary:
\begin{cor}Let $\pi: M(c) \rightarrow N$ be an anti-invariant submersion from a quaternionic space form ( $M(c), g_M$ ) onto a Riemannian manifold $\left(N, g_N\right)$ such that each fiber is totally geodesic. Then we have
\begin{equation} \label{eq-3.61}
\begin{aligned}
 \frac{c}{4}\left((\ell+r)(\ell+r-1)+\sum_{\alpha =1}^{3}\left( \sum_{i=1}^{\ell} 6\lVert B_{J_\alpha}X_i \rVert ^{2}+3 \lVert C_{J_\alpha}X_{1} \rVert ^{2}\right) \right)  
 \geq \hat{\tau}+ \tau^*+\frac{3}{\ell} \operatorname{tr}\left({\mathcal{A}}^{\mathcal{V}}\right)^2-2\left\|{\mathcal{A}}^{\mathcal{H}}\right\|^2.
\end{aligned}
\end{equation}
Equality case of {\rm(\ref{eq-3.61})} holds for all $p \in M$ if and only if ${\mathcal{A}}_{11}={\mathcal{A}}_{22}=\ldots={\mathcal{A}}_{\ell \ell}$ and ${\mathcal{A}}_{i j}=0$, for $i \neq j \in\{1,2, \ldots, \ell \}.$
\end{cor}

