\subsection{Approximate functional equation}

Let $\chi$ be a primitive Dirichlet character modulo $q$. Our assumptions imply that $\chi\eta_j$ is primitive modulo $q$ for $j\in\{1,2\}$, and so the Dirichlet $L$-function $L(s,\chi\eta_j)$ satisfies the functional equation
\begin{align}\label{fe}
\Lambda(\tfrac12+s,\chi\eta_j)&:=\Big(\frac{q}{\pi}\Big)^{s/2}\Gamma\Big(\frac{1/2+s+\kappa_j}{2}\Big)L(\tfrac12+s,\chi\eta_j)\nonumber\\
&=i^{-\kappa_j} \epsilon_{\chi\eta_j}\Lambda(\tfrac12-s,\overline{\chi\eta_j}).
\end{align}

We are in a position to derive a standard approximate functional equation in our context.

\begin{lem}\label{lem:afe}
Let $G(s)$ be an even entire function of rapid decay in any fixed strip $|\emph{Re}(s)| \leq C$ satisfying $G(0)= 1$.
For $x>0$, define
\begin{equation}\label{formulaV+}
V(x)=\frac{1}{2\pi i}\int_{(1)}\frac{\Gamma\big(\frac{1/2+s+\kappa_1}{2}\big)\Gamma\big(\frac{1/2+s+\kappa_2}{2}\big)}{\Gamma\big(\frac{1/2+\kappa_1}{2}\big)\Gamma\big(\frac{1/2+\kappa_2}{2}\big)}G(s)x^{-s}\frac{ds}{s}.
\end{equation}
For any $X>0$, we have
\begin{align*}
L(\tfrac 12,\chi\eta_1)L(\tfrac 12,\overline{\chi\eta_2})&=\sum_{m,n\geq1}\frac{\chi\eta_1(m)\overline{\chi\eta_2}(n)}{\sqrt{mn}}V\Big(\frac{\pi mn}{qX}\Big)\\
&\qquad + i^{-(\kappa_1+\kappa_2)}\epsilon_{\chi\eta_1}\epsilon_{\overline{\chi\eta_2}}\sum_{m,n\geq1}\frac{\overline{\chi\eta_1}(m)\chi\eta_2(n)}{\sqrt{mn}}V\Big(\frac{\pi mnX}{q}\Big).\nonumber
\end{align*}
\end{lem}

\begin{proof}
From Cauchy's residue theorem we have
\begin{align}\label{residue}
&\frac{1}{2\pi i}\int_{(1)}G(s)X^s\frac{\Lambda(1/2+s,\chi\eta_1)\Lambda(1/2+s,\overline{\chi\eta_2})}{\Gamma(\frac{1/2+\kappa_1}{2})\Gamma(\frac{1/2+\kappa_2}{2})}\frac{ds}{s}\nonumber\\
&\qquad=\frac{1}{2\pi i}\int_{(-1)}G(s)X^s\frac{\Lambda(1/2+s,\chi\eta_1)\Lambda(1/2+s,\overline{\chi\eta_2})}{\Gamma(\frac{1/2+\kappa_1}{2})\Gamma(\frac{1/2+\kappa_2}{2})}\frac{ds}{s}+\text{Res}_{s=0}.
\end{align}
The residue at $s=0$ is $L(\tfrac 12,\chi\eta_1)L(\tfrac 12,\overline{\chi\eta_2})$.
By \eqref{fe} and the change of variables $s\longleftrightarrow-s$ in \eqref{residue}, we obtain 
\begin{align*}
&L(\tfrac 12,\chi\eta_1)L(\tfrac 12,\overline{\chi\eta_2})=\frac{1}{2\pi i}\int_{(1)}G(s)X^s\frac{\Lambda(1/2+s,\chi\eta_1)\Lambda(1/2+s,\overline{\chi\eta_2})}{\Gamma(\frac{1/2+\kappa_1}{2})\Gamma(\frac{1/2+\kappa_2}{2})}\frac{ds}{s}\\
&\qquad\ + i^{-(\kappa_1+\kappa_2)}\epsilon_{\chi\eta_1}\epsilon_{\overline{\chi\eta_2}}\frac{1}{2\pi i}\int_{(1)}G(s)X^{-s}\frac{\Lambda(1/2+s,\overline{\chi\eta_1})\Lambda(1/2+s,\chi\eta_2)}{\Gamma(\frac{1/2+\kappa_1}{2})\Gamma(\frac{1/2+\kappa_2}{2})}\frac{ds}{s}.
\end{align*}
The lemma now follows by writing the $L$-functions in terms of Dirichlet series and then integrating term-by-term.
\end{proof}

\begin{rem}\label{boundforV}
We have
\[
x^j \frac{\partial^jV(x)}{\partial x^j}\ll_{j,C}(1+x)^{-C}
\]
for any fixed $j\geq0$ and $C > 0$. Furthermore, we have
\[
V(x)=1+O_\varepsilon(x^{1/2-\varepsilon}).
\]
\end{rem}

