The following lemma evaluates $c_\eta$ when $\eta$ is an imprimitive character.

\begin{lem}\label{lem:generalized_Gauss_sum}
Let $n\in \Z/q\Z$. 
Let $\nu={\rm ord}_p(n)$, and write $n=p^\nu n'$ with $\gcd(p,n')=1$. 
Suppose that $\eta$ is a nontrivial imprimitive character modulo $q$ of height $0 < h < k$; in other words $\eta$ is induced from a primitive character $\eta^*$ modulo $p^h$.
Then, $c_\eta(n)$ is nonzero if and only if $\nu=k-h$, in which case
    $$
    c_\eta(n)=p^{k-h} \tau(\eta^*) \overline{\eta^*}(n') \quad \text{and} \quad |c_\eta(n)|=p^{k-h/2}.
    $$
\end{lem}

\begin{proof}
    By \cite[Theorem 9.12]{MV07}, $c_\eta(n)$ is nonzero only if $\nu \leq k-h$. We now assume that $\nu \leq k-h$. Then by the same theorem,
    $$
    c_\eta(n)=\overline{\eta^*}(n') \eta^*(p^{k-h-\nu}) \mu(p^{k-h-\nu})
    \frac{\varphi(p^k)}{\varphi(p^{k-\nu})} \tau(\eta^*).
    $$
    The factor $\eta^*(p^{k-h-\nu})$ is nonzero if and only if $k-h-\nu=0$, in which case
    $$
    c_\eta(n)=p^{k-h} \tau(\eta^*) \overline{\eta^*}(n').
    $$
    It follows that $|c_\eta(n)|=p^{k-h+h/2}=p^{k-h/2}$.
    The lemma is proved.
\end{proof}

We now compute a character average that will appear in the moment calculation.

\begin{lem}\label{lem:averageing_character_twist_chieta1_barchieta2}
    Let $n\in (\Z/q\Z)^\times$.
            If $n^{p-1} \not\equiv 1 \ (\emph{mod}\ p^{k-h})$, then
    $$
    \frac{1}{|\co|}  \sum_{\chi\in \co} \epsilon_{\chi\eta_1}\epsilon_{\overline{\chi\eta_2}} \chi(n) = 0.
    $$
    If $n^{p-1} \equiv 1 \ (\emph{mod}\ p^{k-h})$, then
    $$
    \frac{1}{|\co|}  \sum_{\chi\in \co} \epsilon_{\chi\eta_1}\epsilon_{\overline{\chi\eta_2}} \chi(n) \ll p^{-h/2}.
    $$
\end{lem}


\begin{proof}
   Using equation \eqref{normalized} and opening both Gauss sums, we have
        \begin{align*}
    	\frac{1}{|\co|}  \sum_{\chi\in \co} \epsilon_{\chi\eta_1}\epsilon_{\overline{\chi\eta_2}} \chi(n)
    	&= \frac{1}{q|\co|} \sum_{\chi\in \co}
    	\chi(n)\ \sumstar_{u,v \, (\text{mod}\ q)} \chi\eta_1(u)\overline{\chi\eta_2}(v)e_q(u+v) \\
    	&=  \frac{1}{q|\co|} \sum_{\chi\in \co}
    	\chi(n)\ \sumstar_{v,w \, (\text{mod}\ q)} \chi\eta_1(w) \eta_1\overline{\eta_2}(v) e_q(vw+v) \\
    	&=  \frac{1}{q|\co|}\ \sumstar_{w \,  (\text{mod}\ q)} \eta_1(w) \sum_{\chi\in \co}
    	\chi(nw)\ \sumstar_{v \, (\text{mod}\ q)} \eta(v) e_q(v(w+1)) \\
    	&=  \frac{1}{q}\ \sumstar_{w \, (\text{mod}\ q)} 
    	\eta_1(w)  \mathbb{E}_\co[\chi(nw)]c_\eta(w+1) .
    \end{align*}

