    $$
    k-h=\ord_p(w+1) = \ord_p(\zeta\bar{n}+1)=\ord_p(\zeta+n).
    $$
    It follows that $n\equiv -\zeta\ (\text{mod}\ p^{k-h})$, and thus  
    $$n^{p-1} \equiv 1 \ (\text{mod}\ p^{k-h}).$$
    The first statement is proved. 

    Next we assume that $n^{p-1} \equiv 1 \ (\text{mod}\ p^{k-h})$. We have 
    \begin{align*}
    \frac{1}{|\co|}  \sum_{\chi\in \co} \epsilon_{\chi\eta_1}\epsilon_{\overline{\chi\eta_2}} \chi(n)
    	&= \frac{1}{q}\ \sumstar_{w \, (\text{mod}\ q)}  \eta_1(w)
    	\mathbb{E}_\co[\chi(nw)] c_\eta(w+1)  \\
    	&=  \frac{1}{q} \sum_{\zeta \in \boldsymbol{\mu}_{p-1}} \ 
    	\sumstar_{\substack{w \, (\text{mod}\ q)\\ w\equiv \zeta\bar{n} \, (\text{mod}\ p^{k-1})}} 
    	\eta_1(w) \mathbb{E}_\co[\chi(nw)] c_\eta(w+1) .
    \end{align*}
    By Lemma \ref{lem:generalized_Gauss_sum}, $|c_\eta(w+1)| \leq p^{k-h/2}$. 
    Since $| \mathbb{E}_\co[\chi(nw)]|\leq 1$, $| \eta_1(w)|=1$, and the number of summations is finite ($p$ is a fixed prime), the second statement follows.
\end{proof}

