\subsection{Character averages for thin Galois orbits}

In this section, we study character averages for thin Galois orbits.

\begin{lem}\label{lem:thin-orbit-char-avg}
Let $0\leq\kappa\leq k-1$ and $n\in (\Z/q\Z)^\times$. If $\mathbb{E}_{\co_\kappa}[\chi(n)]\neq 0$, then $n^{p-1} \equiv 1 \ (\emph{mod}\ p^{\min(\kappa+1,k-1)})$. 
\end{lem}

\begin{proof}
This is \cite[Lemma 3.1]{KMN16}.
\end{proof}


We have an analog of Lemma \ref{lem:averageing_character_twist_chieta1_barchieta2} for thin Galois orbits.

\begin{lem}\label{lem:averageing_character_twist_chieta1_barchieta2_thin}
    Let $n\in (\Z/q\Z)^\times$. 

    \begin{enumerate}
        \item[{\rm (i)}] If $n^{p-1} \not\equiv 1 \ (\emph{mod}\ p^{\min(\kappa+1,k-h)})$, then
    $$
    \frac{1}{|\co_\kappa|}  \sum_{\chi\in \co_\kappa} \epsilon_{\chi\eta_1}\epsilon_{\overline{\chi\eta_2}} \chi(n) = 0.
    $$
        \item[{\rm (ii)}] Suppose that $\kappa > k-h/2$.
        If $n^{p-1} \equiv 1 \ (\emph{mod}\ p^{\min(\kappa+1,k-h)})$, then $n^{p-1} \equiv 1 \ (\emph{mod}\ p^{k-h})$ and
    $$
    \frac{1}{|\co_\kappa|}  \sum_{\chi\in \co_\kappa} \epsilon_{\chi\eta_1}\epsilon_{\overline{\chi\eta_2}} \chi(n) \ll p^{k-h/2-\kappa}.
    $$
    \end{enumerate}
\end{lem}


\begin{proof}
    Opening both Gauss sums as in the proof of Lemma \ref{lem:averageing_character_twist_chieta1_barchieta2}, we get
        \begin{equation*}
    	\frac{1}{|\co_\kappa|}  \sum_{\chi\in \co_\kappa} \epsilon_{\chi\eta_1}\epsilon_{\overline{\chi\eta_2}} \chi(n)
    	=  \frac{1}{q}\ \sumstar_{w \, (\text{mod}\ q)} 
    	\eta_1(w)  \mathbb{E}_{\co_\kappa}[\chi(nw)]c_{\eta_1\overline{\eta_2}}(w+1) .
    \end{equation*}
    By Lemma \ref{lem:generalized_Gauss_sum}, $c_{\eta_1\overline{\eta_2}}(w+1) \neq 0$ only if $\ord_p(w+1)=k-h$. By Lemma \ref{lem:thin-orbit-char-avg}, $\mathbb{E}_{\co_\kappa}[\chi(nw)]\neq 0$ only if $(nw)^{p-1}\equiv 1\ (\text{mod}\ p^{\min(\kappa+1,k-1)})$, or equivalently $nw\equiv \zeta\ (\text{mod}\ p^{\min(\kappa+1,k-1)})$ for some $\zeta\in \boldsymbol{\mu}_{p-1}$. 
    It follows that
    $$
    0\equiv w+1 \equiv  \zeta\bar{n}+1 \equiv (\zeta+n)\bar{n}
    \ (\text{mod}\ p^{\min(\kappa+1,k-h)})
    $$
    Hence $n\equiv -\zeta \ (\text{mod}\ p^{\min(\kappa+1,k-h)})$, and thus
    $$n^{p-1} \equiv 1 \ (\text{mod}\ p^{\min(\kappa+1,k-h)}).$$
    Part {\rm (i)} is proved. 

    Next we assume that $\kappa > k-h/2$ and that $n^{p-1} \equiv 1 \ (\text{mod}\ p^{\min(\kappa+1,k-h)})$. It is plain that $\kappa+1 > k-h$, whence $n^{p-1} \equiv 1 \ (\text{mod}\ p^{k-h})$. We have
    \begin{align*}
    \frac{1}{|\co_\kappa|}  \sum_{\chi\in \co_\kappa} \epsilon_{\chi\eta_1}\epsilon_{\overline{\chi\eta_2}} \chi(n)
    &= \frac{1}{q}\ \sumstar_{w \, (\text{mod}\ q)}  \eta_1(w)
    	\mathbb{E}_{\co_\kappa}[\chi(nw)] c_\eta(w+1)  \\
    &= \frac{1}{q} \sum_{\zeta \in \boldsymbol{\mu}_{p-1}} 
    	\sumstar_{\substack{w \, (\text{mod}\ q) \\ 
        w\equiv \zeta\bar{n} \, (\text{mod}\ p^{\kappa+1}) \\
        w+1\equiv 0 \, (\text{mod}\ p^{k-h}) \\
        }} 
    	\eta_1(w) \mathbb{E}_{\co_\kappa}[\chi(nw)] c_\eta(w+1) .
    \end{align*}
    By Lemma \ref{lem:generalized_Gauss_sum}, we have $|c_\eta(w+1)| \leq p^{k-h/2}$. 
    Since  $|\eta_1(w)| = 1$, $|\mathbb{E}_{\co_\kappa}[\chi(nw)]|\leq 1$ and the number of summations is $O(q/p^{\kappa+1})$ ($p$ is a fixed prime), it follows that
    $$
    \frac{1}{|\co_\kappa|}  \sum_{\chi\in \co_\kappa} \epsilon_{\chi\eta_1}\epsilon_{\overline{\chi\eta_2}} \chi(n)
    \ll p^{-h/2} \frac{q}{p^{\kappa+1}} \ll p^{k-h/2-\kappa}.
    $$
    Part {\rm (ii)} is proved. 
\end{proof}




