\subsection{Roots of unity and the Roth-Ridout theorem}


In this section, we gather some $p$-adic congruence equations that can be treated elementarily or using more powerful results from $p$-adic Diophantine approximation.


Let $p$ be a prime number. The equation $x^{p-1}-1=0$ has $p-1$ roots in $\Z_p$; these roots form the set $\boldsymbol{\mu}_{p-1}$ of $(p-1)^{\text{th}}$ roots of unity in $\overline{\Q}_p$. For each $1\leq j\leq p-1$, there exists $\zeta_j\in \boldsymbol{\mu}_{p-1}$ such that $\zeta_j\equiv j \ (\text{mod}\ p)$ or equivalently $\zeta_j-j\in p\Z_p$. If $x\in\Z$ satisfies $x^{p-1}\equiv 1 \ (\text{mod}\ p^a)$ for some positive integer $a$, then $x \equiv \zeta_j \ (\text{mod}\ p^a)$, or equivalently $x-\zeta_j\in p^a\Z_p$, for exactly one $1\leq j\leq p-1$.

We recall several results from \cite{KMN16} for later use; Lemmas \ref{lem:Roth-Ridout-a} and \ref{lem:Roth-Ridout-b} below are consequences of the Roth-Ridout theorem.

\begin{lem}\label{lem:congruences-prime-power}
   If $m$ and $\alpha\geq 1$ are integers satisfying $m^{p}\equiv 1 \ (\emph{mod}\ p^\alpha)$, then $m\equiv 1 \ (\emph{mod}\ p^{\alpha-1})$.
\end{lem}

\begin{proof}
    This is \cite[Lemma 2.2]{KMN16}.
\end{proof}


\begin{lem}\label{lem:Roth-Ridout-a}
    Suppose that $0<\delta<\tfrac{1}{2}$ and $\beta\in\Z_p$ is algebraic over $\Q$ of degree at least $2$. Then, for all sufficiently large positive integers $\alpha\geq \alpha_0(\beta,\delta)$, there are no nonzero integers $a$ and $b$ such that $|a|,|b|<(p^\alpha)^{1/2-\delta}$ and that
    $$
    a \equiv \beta b \ (\emph{mod}\ p^{\alpha-1}).
    $$
\end{lem}

\begin{proof}
    This is \cite[Lemma 2.4]{KMN16}.
\end{proof}

\begin{rem}
    It is plain that Lemma \ref{lem:Roth-Ridout-a} also holds if we replace the congruence $a \equiv \beta b \ (\text{mod}\ p^{\alpha-1})$ by the congruence $a \equiv \beta b \ (\text{mod}\ p^{\alpha})$.
\end{rem}

\begin{lem}\label{lem:Roth-Ridout-b}
    Suppose that $0<\delta<\tfrac{1}{2}$ and $\alpha\geq \alpha_1(\delta)$ be sufficiently large. Let $\mathcal{A}_\alpha, \mathcal{B}_\alpha \subset \Z$ be intervals of length at most $(p^\alpha)^{1/2-\delta}$. Then there are at most $(p-1)$ pairs $(a,b)\in \mathcal{A}_\alpha\times \mathcal{B}_\alpha$ such that $(ab,p)=1$, $a \not\equiv \pm b \ (\emph{mod}\ p^{\alpha-1})$ and that
    $$
    a^{p-1} \equiv b^{p-1} \ (\emph{mod}\ p^{\alpha-1}).
    $$
\end{lem}

\begin{proof}
    This is \cite[Lemma 2.5]{KMN16}.
\end{proof}

\begin{rem}
    It is plain that Lemma \ref{lem:Roth-Ridout-b} also holds if we replace the congruence $a^{p-1} \equiv b^{p-1} \ (\text{mod}\ p^{\alpha-1})$ by the congruence $a^{p-1} \equiv b^{p-1} \ (\text{mod}\ p^{\alpha})$.
\end{rem}

For $\alpha\in\mathbb{N}$, define
\begin{align}
D_0(A,B; p^\alpha) &= \frac{1}{\sqrt{AB}} 
\sumstar_{\substack{A\le a < 2A,   B\le b < 2B\\ a^{p-1} \equiv b^{p-1} \ (\text{mod}\ p^{\alpha}) \\ a\neq b}} 1 
= \frac{1}{\sqrt{AB}}\sum_{\zeta \in \boldsymbol{\mu}_{p-1}} \
\sumstar_{\substack{A\le a < 2A,  B\le b < 2B\\ a\equiv \zeta b \ (\text{mod}\ p^{\alpha}) \\ a\neq b}} 1 , \label{eq:dyadic-sum-congruence} \\
D_1(A,B; p^\alpha) &= \frac{1}{\sqrt{AB}} 
\sumstar_{\substack{A\le a < 2A,  B\le b < 2B\\ a\equiv \pm b \ (\text{mod}\ p^{\alpha})\\ a\neq b}} 1 , \label{eq:dyadic-sum-congruence-trivial} \\
D_2(A,B; p^\alpha) &= \frac{1}{\sqrt{AB}}
\sum_{\zeta \in \boldsymbol{\mu}_{p-1}\setminus \{\pm 1\}} \
\sumstar_{\substack{A\le a < 2A, B\le b < 2B \\ a\equiv \zeta b \ (\text{mod}\ p^{\alpha})}} 1  \label{eq:dyadic-sum-congruence-RR} .
\end{align}
These are the sums that we need to estimate in the moment computations. Note that $$D_0(A,B; p^\alpha)=D_1(A,B; p^\alpha)+D_2(A,B; p^\alpha).$$
The sums $D_0(A,B; p^\alpha)$ and $D_1(A,B; p^\alpha)$ can be treated elementarily, whereas $D_2(A,B; p^\alpha)$ can be estimated by the Roth-Ridout theorem.

\begin{lem}\label{lem:dyadic-congruence-naive}
    Let $\alpha\in\mathbb{N}$. 
We have
$$
D_0(A,B; p^\alpha) \ll \frac{\sqrt{AB}}{p^\alpha} + \min\left(\sqrt{\frac{A}{B}},\sqrt{\frac{B}{A}}\right) .
$$
In particular, $D_0(A,B; p^\alpha) = O(\sqrt{AB}/p^\alpha + 1)$.
\end{lem}

\begin{proof}
    Without loss of generality, assume that $B\leq A$. For each $B\leq b<2 B$, there are $O(A/p^\alpha+1)$ values of $A\leq a<2A$ with $a\equiv \zeta b\ (\text{mod}\ p^{\alpha})$ for each $\zeta \in \boldsymbol{\mu}_{p-1}$. Then 
$$
D_0(A,B; p^\alpha) \ll \frac{1}{\sqrt{AB}}\Big(\frac{AB}{p^\alpha}+B\Big)
= \frac{\sqrt{AB}}{p^\alpha} + \sqrt{\frac{B}{A}}.$$
The lemma is proved.
\end{proof}

\begin{lem}\label{lem:dyadic-congruence-naive-1}
    Let $\alpha\in\mathbb{N}$. 
We have
$$
D_1(A,B; p^\alpha) \ll \frac{\sqrt{AB}}{p^\alpha}.
$$
\end{lem}

\begin{proof}
    If $A\le a < 2A$ and $B\le b < 2B$ satisfy $a\equiv \pm b \ (\text{mod}\ p^{\alpha})$ and $a\neq b$, then either $a\gg p^{\alpha}$ or $b\gg p^{\alpha}$. Without loss of generality, assume that $a\gg p^{\alpha}$, whence $\sqrt{B/A} \ll \sqrt{AB}/p^\alpha$. By Lemma \ref{lem:dyadic-congruence-naive}, we have 
    $$D_1(A,B; p^\alpha) \leq D_0(A,B; p^\alpha)
    \ll \frac{\sqrt{AB}}{p^\alpha}  + \sqrt{\frac{B}{A}}
    \ll \frac{\sqrt{AB}}{p^\alpha},$$
as claimed.
\end{proof}

We are in a position to derive the main estimates for the number of solutions of the $p$-adic congruence equations that naturally arise from Dirichlet characters in Galois orbit. Although its proof uses arguments that appeared in \cite{KMN16}, Proposition \ref{prop:dyadic-congruence} as formulated below is new.

\begin{prop}\label{prop:dyadic-congruence}
    Suppose that $0<\delta<\tfrac{1}{4}$ and that $\alpha\geq \alpha_2(\delta)$ is a sufficiently large positive integer. 
    \begin{enumerate}
        \item[{\rm (i)}] If $2A < p^{\alpha(1/2-\delta)}$ and $2B < p^{\alpha(1/2-\delta)}$, then 
        $$
        D_0(A,B;p^\alpha)=D_1(A,B;p^\alpha)=D_2(A,B;p^\alpha)=0.
        $$
        \item[{\rm (ii)}] If $2A \geq p^{\alpha(1/2-\delta)}$ and $2B \geq p^{\alpha(1/2-\delta)}$, then 
        $$
        D_0(A,B;p^\alpha) \ll \frac{\sqrt{AB}}{p^{\alpha}} \cdot p^{4\delta\alpha} . 
        $$
        \item[{\rm (iii)}] If $2A \geq p^{\alpha(1/2-\delta)}$ and $2B < p^{\alpha(1/2-\delta)}$, then $D_2(A,B;p^\alpha) \ll \frac{\sqrt{A/B}}{p^{\alpha/2}}$ and
        $$
        D_0(A,B;p^\alpha) \ll \frac{\sqrt{AB}}{p^{\alpha}} + 
        p^{\alpha(-1/4+\delta)} . 
        $$
    \end{enumerate}
    In particular, in all cases we have 
    $$
        D_0(A,B;p^\alpha) \ll \frac{\sqrt{AB}}{p^{\alpha}} \cdot p^{4\delta\alpha} + 
        p^{\alpha(-1/4+\delta)} . 
    $$
\end{prop}

\begin{proof}
    Statement ${\rm (i)}$ is an immediate consequence of Lemma \ref{lem:Roth-Ridout-a}.

    To prove ${\rm (ii)}$, let $\zeta \in \boldsymbol{\mu}_{p-1}\setminus \{\pm 1\}$ and divide the dyadic intervals $A\leq a<2A$ and $B\leq b < 2B$ into sub-intervals of the same length $Q:=p^{\alpha(1/2-2\delta)}$. 
    For each pair of those sub-intervals, the number of pairs $(a,b)$ in this box and satisfying $a\equiv \zeta b\ (\text{mod}\ p^{\alpha})$ is $O(1)$, by the Roth-Ridout theorem (Lemma \ref{lem:Roth-Ridout-b}). The contribution of those terms to the sum gives
    $$
    D_2(A,B;p^\alpha) \ll \frac{1}{\sqrt{AB}} \cdot \frac{AB}{Q^2} \ll \frac{\sqrt{AB}}{p^{\alpha(1-4\delta)}}.
    $$
    This estimate together with Lemma \ref{lem:dyadic-congruence-naive-1} yield ${\rm (ii)}$.

    The proof of ${\rm (iii)}$ is similar. Let $\zeta \in \boldsymbol{\mu}_{p-1}\setminus \{\pm 1\}$ and divide the dyadic interval $A\leq a < 2A$ into sub-intervals of the same length $Q$ as above. For each of those sub-intervals, the number of pairs $(a,b)$ with $a$ in the sub-interval and $B\leq b < 2B$ satisfying $a\equiv \zeta b\ (\text{mod}\ p^{\alpha})$ is $O(1)$, by the Roth-Ridout theorem (Lemma \ref{lem:Roth-Ridout-b}). The contribution of those terms to the sum gives
    $$
    D_2(A,B;p^\alpha) \ll \frac{1}{\sqrt{AB}}  \cdot  \frac{A}{Q} \ll \frac{\sqrt{A/B}}{p^{\alpha(1/2-2\delta)}}.
    $$
    This estimate together with Lemma \ref{lem:dyadic-congruence-naive-1} yield 
    \begin{equation}\label{eq:dyadic-congruence-balanced1}
        D_0(A,B;p^\alpha) \ll \frac{\sqrt{AB}}{p^{\alpha}} + \frac{\sqrt{A/B}}{p^{\alpha/2}} \cdot p^{2\delta\alpha} . 
    \end{equation}

    Let $\lambda>0$ be a parameter to be chosen.
    For the `unbalanced' range 
    $$
    \frac{A}{B}\notin (p^{-\lambda},p^{\lambda}),
    $$
    by assumption we have $\frac{A}{B}\geq p^\lambda$. It follows from Lemma \ref{lem:dyadic-congruence-naive} that 
    \begin{equation}\label{eq:dyadic-congruence-unbalanced}
    D_0(A,B;p^\alpha) \ll \frac{\sqrt{AB}}{p^\alpha} + p^{-\lambda/2}. 
    \end{equation}
    In the `balanced' range 
    $$ p^{-\lambda} < \frac{A}{B} < p^{\lambda},$$ 
    it follows from \eqref{eq:dyadic-congruence-balanced1} that
    \begin{equation}\label{eq:dyadic-congruence-balanced2}
        D_0(A,B;p^\alpha) \ll \frac{\sqrt{AB}}{p^{\alpha}} + p^{(\lambda-\alpha)/2} \cdot p^{2\delta\alpha} . 
    \end{equation}
    On combining \eqref{eq:dyadic-congruence-unbalanced} and \eqref{eq:dyadic-congruence-balanced2} and setting $p^\lambda=p^{\alpha(1/2-2\delta)}$, we conclude ${\rm (iii)}$.
\end{proof}


