\section{Twisted moments}

We set to compute the twisted moments over full Galois orbits and thin Galois orbits.

\subsection{Twisted moments over full Galois orbits}

In this section, we prove Theorem \ref{thm:twisted-moment-full-orbit} together with its consequences (Corollaries \ref{cor:full-orbit-moment} and \ref{cor:full-orbit-nonvanishing}).

\begin{proof}[Proof of Theorem \ref{thm:twisted-moment-full-orbit}]
Let
$$
S(m_1,m_2) 
    = \frac{1}{|\co|}\sum_{\substack{\chi\in\co}}L(\tfrac12,\chi\eta_1)L(\tfrac12,\overline{\chi\eta_2})\chi(m_1)\overline{\chi}(m_2).
$$
By Lemma \ref{lem:afe}, we have 
\begin{equation*}
\label{eq:funceq2ndmol}
S(m_1,m_2)= S^+(m_1,m_2)+ i^{-(\kappa_1+\kappa_2)}S^-(m_1,m_2),   
\end{equation*}
where
\begin{equation}
    \label{eq:funceq2ndmolplus}
S^+(m_1,m_2) =
    \sum_{\substack{n_1,n_2\ge 1}} 
    \frac{\eta_1(n_1)\overline{\eta_2}(n_2)}{\sqrt{n_1n_2}}V\Big(\frac{\pi n_1n_2}{qX}\Big) 
    \mathbb{E}_\co[\chi(m_1n_1\overline{m_2n_2})]  %123
\end{equation}
and 
\begin{equation}
\label{eq:funceq2ndmolminus}
 S^-(m_1,m_2)= 
     \sum_{\substack{n_1,n_2\ge 1}} 
    \frac{\overline{\eta_1}(n_1)\eta_2(n_2)}{\sqrt{n_1n_2}}V\Big(\frac{\pi n_1n_2X}{q}\Big) \frac{1}{|\co|} 
    \sum_{\chi\in \co} \epsilon_{\chi\eta_1} \epsilon_{\overline{\chi}\overline{\eta_2}} 
    \chi(m_1\overline{n_1}\overline{m_2}n_2).
\end{equation}

For $S^+(m_1,m_2)$ we write 
\[
S^+(m_1,m_2)=M(m_1,m_2)+E^+(m_1,m_2),
\]
where $M(m_1,m_2)$ is the contribution of the diagonal terms $m_1n_1=m_2n_2$, and $E^+(m_1,m_2)$ is the contribution of the off-diagonal terms $m_1n_1\ne m_2n_2$.  Write $m_1=gm_1',m_2=gm_2'$, where $(m_1',m_2')=1$. Then
\begin{align}\label{Mformula}
M(m_1,m_2)=\sum_{\substack{n_1,n_2\geq 1\\m_1'n_1=m_2'n_2}}\frac{\eta_1(n_1)\overline{\eta_2}(n_2)}{\sqrt{n_1n_2}}V\Big(\frac{\pi n_1n_2}{qX}\Big)=\frac{\eta_1(m_2')\overline{\eta_2}(m_1')}{\sqrt{m_1'm_2'}}\sum_{n\geq 1}\frac{\eta(n)}{n}V\Big(\frac{\pi m_1'm_2'n^2}{qX}\Big).
\end{align}
By \eqref{formulaV+}, we get that
\begin{align*}
M(m_1,m_2) =&\frac{\eta_1(m_2')\overline{\eta_2}(m_1')}{\sqrt{m_1'm_2'}}\frac{1}{2\pi i}\int_{(1)}\frac{\Gamma\big(\frac{1/2+s+\kappa_1}{2}\big)\Gamma\big(\frac{1/2+s+\kappa_2}{2}\big)}{\Gamma\big(\frac{1/2+\kappa_1}{2}\big)\Gamma\big(\frac{1/2+\kappa_2}{2}\big)}G(s)\Big(\frac{qX}{\pi m_1'm_2'}\Big)^{s}L(1+2s,\eta)\frac{ds}{s}.
\end{align*}
We move the contour to Re$(s)=-1/2+\varepsilon$, crossing a simple pole at $s=0$. Estimating the new integral trivially gives 
\begin{equation}\label{eq:diagonalterms}
M(m_1,m_2) =\frac{\eta_1(m_2')\overline{\eta_2}(m_1')}{\sqrt{m_1'm_2'}}L(1,\eta)+O_\varepsilon(p^{h/2}q^{-1/2+\varepsilon}X^{-1/2}).
\end{equation}

