\begin{equation*}
%\label{eq:dyadicS-} 
\mathcal{E}^-(\vartheta)  \ll_\varepsilon q^\varepsilon p^{-h/2}
\max_{\substack{A\geq 1,B\geq 1 \\  AB\leq q^{1+2\vartheta+\varepsilon} / X }}
D_0(A,B;p^{k-h}) .
\end{equation*}
It follows from Proposition \ref{prop:dyadic-congruence} (with the choice $\delta=\varepsilon$) that
\begin{align}
\mathcal{E}^-(\vartheta)&  \ll_\varepsilon q^\varepsilon p^{-h/2}
\max_{\substack{A\geq 1,B\geq 1 \\  AB\leq q^{1+2\vartheta+\varepsilon} / X }} \frac{\sqrt{AB}}{p^{k-h}}  + p^{-h/4}q^{-1/4+\varepsilon} \nonumber \\
& \ll_\varepsilon 
p^{h/2}q^{-1/2+\vartheta+\varepsilon}X^{-1/2} + p^{-h/4}q^{-1/4+\varepsilon}. 
\end{align}

For all $0<h<k$, it follows from Lemma \ref{lem:dyadic-congruence-naive} that

\begin{align}
\mathcal{E}^-(\vartheta)&  \ll_\varepsilon q^\varepsilon p^{-h/2}
\max_{\substack{A\geq 1,B\geq 1 \\  AB\leq q^{1+2\vartheta+\varepsilon} / X }} \frac{\sqrt{AB}}{p^{k-h}} +  q^\varepsilon p^{-h/2} \nonumber \\
& \ll_\varepsilon 
p^{h/2}q^{-1/2+\vartheta+\varepsilon}X^{-1/2} +  p^{-h/2}q^\varepsilon. \label{eq:boundS-zero}
\end{align}
Assuming further that $h<(1-\varepsilon)k$, we can apply Proposition \ref{prop:dyadic-congruence} (with the choice $\delta=\varepsilon$) to obtain
\begin{equation}
\mathcal{E}^-(\vartheta)  \ll_\varepsilon p^{h/2}q^{-1/2+\vartheta+\varepsilon}X^{-1/2} + p^{-h/4}q^{-1/4+\varepsilon}.
\label{eq:boundS-}
\end{equation}


In view of \eqref{eq:diagonalterms}, \eqref{eq:S+errorterm-condition}, \eqref{eq:boundS-zero} and \eqref{eq:boundS-} we derive that
$$
S(m_1,m_2)=\frac{\eta_1(m_2')\overline{\eta_2}(m_1')}{\sqrt{m_1'm_2'}}L(1,\eta)+E(m_1,m_2),
$$
where
\begin{align*}
\mathcal{E}(\vartheta):=\sum_{m_1,m_2\leq q^\vartheta}\frac{x_{m_1}\overline{x_{m_2}}}{\sqrt{m_1m_2}}E(m_1,m_2)
= \mathcal{E}^+(\vartheta) + \mathcal{E}^-(\vartheta)
\end{align*}
satisfies the following property. We have that for all $0<h<k$, 
\begin{align*}
\mathcal{E}(\vartheta) \ll_\varepsilon q^{-1/2+\vartheta+\varepsilon}X^{1/2}
+ p^{h/2} q^{-1/2+\vartheta+\varepsilon}X^{-1/2}
+ p^{-h/2}q^{\varepsilon} + q^{-1/4+\varepsilon}
\end{align*}
and for $0<h<(1-\varepsilon)k$,
\begin{align*}
\mathcal{E}(\vartheta)\ll_\varepsilon q^{-1/2+\vartheta+\varepsilon}X^{1/2}
+ p^{h/2} q^{-1/2+\vartheta+\varepsilon}X^{-1/2}
+ p^{-h/4}q^{-1/4+\varepsilon}.
\end{align*}
Theorem \ref{thm:twisted-moment-full-orbit} follows by choosing $X=p^{h/2}$.

%With the choice $X=p^{h/2}$, for $(2-4\vartheta)k/3<h<k$ we have
%$$\mathcal{E}(\vartheta)\ll_\varepsilon p^{h/4} q^{-1/2+\vartheta+\varepsilon} + q^{-1/4+\varepsilon},$$
%and for $0<h<2k/3$ we have
%$$\mathcal{E}(\vartheta)\ll_\varepsilon p^{h/4} q^{-1/2+\vartheta+\varepsilon} + p^{h/4}q^{-1/4+\varepsilon}.$$
%Theorem \ref{thm:twisted-moment-full-orbit} is proved.
\end{proof}


% ----------- Corollaries for full Galois orbits -----------

We are in a position to derive two consequences of Theorem \ref{thm:twisted-moment-full-orbit}.

\begin{proof}[Proof of Corollary \ref{cor:full-orbit-moment}]
    This corollary follows immediately from Theorem \ref{thm:twisted-moment-full-orbit} on setting $m_1=m_2=1$.
\end{proof}

\begin{proof}[Proof of Corollary \ref{cor:full-orbit-nonvanishing}]
   This is a consequence of Corollary \ref{cor:full-orbit-moment} and the subconvexity bound for Dirichlet $L$-functions. From Corollary \ref{cor:full-orbit-moment} and  Siegel's Theorem (see, for instance, \cite[Theorem 11.14]{MV07}), it follows that
\begin{align}\label{cor:full-orbit-nonvanishing for1}
&\sum_{\substack{\chi\in\co}}L(\tfrac12,\chi\eta_1)L(\tfrac12,\overline{\chi\eta_2})\gg_\varepsilon q^{1-\varepsilon}.
\end{align}
By the Weyl bound $L(1/2,\chi\eta_1)\ll_\varepsilon q^{1/6+\varepsilon}$ \cite[Theorem 1.1]{PY23}, we also have that the left hand side is 
\begin{align}\label{cor:full-orbit-nonvanishing for2}
\ll_\varepsilon q^{1/3+\varepsilon}\cdot \#\big\{\chi\in\co:L(\tfrac12,\chi\eta_1)L(\tfrac12,\chi\eta_2)\ne0\big\}.
\end{align}
Combining \eqref{cor:full-orbit-nonvanishing for1} and \eqref{cor:full-orbit-nonvanishing for2} we obtain Corollary \ref{cor:full-orbit-nonvanishing}.
\end{proof}



