\subsection{Twisted moments over thin Galois orbits}


In this section, we prove Theorem \ref{thm:twisted-moment-thin-orbit}.
%together with its consequences (Corollaries \ref{cor:thin-orbit-moment} and \ref{cor:thin-orbit-nonvanishing}).

\begin{proof}[Proof of Theorem \ref{thm:twisted-moment-thin-orbit}]

We proceed as in the proof of Theorem \ref{thm:twisted-moment-full-orbit}, with Lemmas \ref{lem:thin-orbit-char-avg} and \ref{lem:averageing_character_twist_chieta1_barchieta2_thin} in place of 
Lemmas \ref{lem:full-orbit-char-avg} and \ref{lem:averageing_character_twist_chieta1_barchieta2} respectively.

    Let
$$
S_\kappa(m_1,m_2) 
    = \frac{1}{|\co_\kappa|}\sum_{\substack{\chi\in\co_\kappa}}L(\tfrac12,\chi\eta_1)L(\tfrac12,\overline{\chi\eta_2})\chi(m_1)\overline{\chi}(m_2).
$$
By Lemma \ref{lem:afe}, we have 
\begin{equation*}
\label{eq:funceq2ndmol-thin}
S_\kappa(m_1,m_2)= S_\kappa^+(m_1,m_2)+ i^{-(\kappa_1+\kappa_2)}S_\kappa^-(m_1,m_2),   
\end{equation*}
where
\begin{equation}
\label{eq:funceq2ndmolplus-thin}
S_\kappa^+(m_1,m_2) =
    \sum_{\substack{n_1,n_2\ge 1}} 
    \frac{\eta_1(n_1)\overline{\eta_2}(n_2)}{\sqrt{n_1n_2}}V\Big(\frac{\pi n_1n_2}{qX}\Big) \mathbb{E}_{\co_\kappa}[\chi(m_1n_1\overline{m_2n_2})]   %123
\end{equation}
and 
\begin{equation}
\label{eq:funceq2ndmolminus-thin}
 S_\kappa^-(m_1,m_2)= 
     \sum_{\substack{n_1,n_2\ge 1}} 
    \frac{\eta_1(\overline{n_1})\eta_2(n_2)}{\sqrt{n_1n_2}}V\Big(\frac{\pi n_1n_2X}{q}\Big) \frac{1}{|\co_\kappa|} 
    \sum_{\chi\in \co_\kappa} \epsilon_{\chi\eta_1} \epsilon_{\overline{\chi}\overline{\eta_2}} 
    \chi(m_1\overline{n_1}\overline{m_2}n_2).
\end{equation}

For $S_\kappa^+(m_1,m_2)$ we write  
\[
S_\kappa^+(m_1,m_2)=M_\kappa(m_1,m_2)+E_\kappa^+(m_1,m_2),
\]
where $M_\kappa(m_1,m_2)$ is the contribution of the diagonal terms $m_1n_1=m_2n_2$, and $E_\kappa^+(m_1,m_2)$ is the contribution of the off-diagonal terms $m_1n_1\ne m_2n_2$.  
The main term $M_\kappa(m_1,m_2)$ can be evaluated asymptotically similarly to the computation of $M(m_1,m_2)$. 
We note that 
$$M_\kappa(m_1,m_2) = M(m_1,m_2),$$ and $M(m_1,m_2)$ is evaluated in \eqref{eq:diagonalterms}. 
We now consider the error term sum
$$
\mathcal{E}^+_\kappa(\vartheta):= 
\sum_{m_1,m_2\leq q^\vartheta}\frac{x_{m_1}\overline{x_{m_2}}}{\sqrt{m_1m_2}}E_\kappa^+(m_1,m_2)
$$
For convenience, put
$$\tilde{\kappa} = \min(\kappa+1,k-1)= \kappa+1.$$
It follows from \eqref{eq:funceq2ndmolplus-thin} and Lemma \ref{lem:thin-orbit-char-avg} that 
$$
\mathcal{E}^+_\kappa(\vartheta)\ll_\varepsilon q^\varepsilon
\max_{\substack{A,B\geq 1\\ 1\leq AB\leq q^{1+2\vartheta+\varepsilon}X}} \
D_0(A,B;p^{\tilde{\kappa}}).
$$
By virtue of Proposition \ref{prop:dyadic-congruence} (with the choice $\delta=\varepsilon$), we deduce that
\begin{equation}\label{eq:S+errorterm-condition-thin}
    \mathcal{E}^+_\kappa(\vartheta)\ll_\varepsilon q^{1/2+\vartheta+\varepsilon}X^{1/2}p^{-\tilde{\kappa}} + p^{-\tilde{\kappa}/4}q^\varepsilon.
\end{equation}


For $S_\kappa^-(m_1,m_2)$, as before there is no main term but only the error term
$$
\mathcal{E}^-_\kappa(\vartheta) := \sum_{m_1,m_2\leq q^\vartheta}\frac{x_{m_1}\overline{x_{m_2}}}{\sqrt{m_1m_2}}S_\kappa^-(m_1,m_2).
$$ 
By \eqref{eq:funceq2ndmolminus-thin}, Lemma \ref{lem:averageing_character_twist_chieta1_barchieta2_thin} (with the assumption $\kappa > k-h/2$) and dyadic decomposition, 
\begin{equation}
\label{eq:dyadicS-thin} 
\mathcal{E}^-_\kappa(\vartheta) \ll_\varepsilon p^{k-\kappa-h/2}q^\varepsilon
\max_{\substack{A,B\geq 1\\ AB\leq q^{1+2\vartheta+\varepsilon}/X}} \
D_0(A,B;p^{k-h}).
\end{equation}

For all $0<h<k$, it follows from Lemma \ref{lem:dyadic-congruence-naive} that 
\begin{equation}\label{eq:boundS-zero-thin}
\mathcal{E}^-_\kappa(\vartheta) \ll_\varepsilon 
p^{h/2-\kappa}q^{1/2+\vartheta+\varepsilon}X^{-1/2} + p^{k-\kappa-h/2}q^\varepsilon.    
\end{equation}
Assuming further that $0<h<(1-\varepsilon)k$, we can apply Proposition \ref{prop:dyadic-congruence}, setting $\delta=\varepsilon$ therein, to obtain
\begin{equation}
\mathcal{E}^-_\kappa(\vartheta) \ll_\varepsilon p^{h/2-\kappa} q^{1/2+\vartheta+\varepsilon}X^{-1/2} + p^{-\kappa+(3k-h)/4}q^{\varepsilon}.
\label{eq:boundS-thin}
\end{equation}

In view of \eqref{eq:S+errorterm-condition-thin}, \eqref{eq:boundS-zero-thin} and \eqref{eq:boundS-thin} we derive that
\[
S_\kappa(m_1,m_2)=\frac{\eta_1(m_2')\overline{\eta_2}(m_1')}{\sqrt{m_1'm_2'}}L(1,\eta)+E_\kappa(m_1,m_2),
\]
where
$$
\mathcal{E}_\kappa(\vartheta) := \sum_{m_1,m_2\leq q^\vartheta}\frac{x_{m_1}\overline{x_{m_2}}}{\sqrt{m_1m_2}}E_\kappa(m_1,m_2) 
= \mathcal{E}^+_\kappa(\vartheta) + \mathcal{E}^-_\kappa(\vartheta)
$$
satisfies the following property. We have that for all $0<h<k$,
$$
\mathcal{E}_\kappa(\vartheta) \ll_\varepsilon 
q^{1/2+\vartheta+\varepsilon}X^{1/2}p^{-\kappa} + p^{-\kappa/4}q^\varepsilon
+ p^{h/2-\kappa} q^{1/2+\vartheta+\varepsilon}X^{-1/2} + p^{k-\kappa-h/2}q^{\varepsilon}
$$
and for $0<h<(1-\varepsilon)k$,
$$
\mathcal{E}_\kappa(\vartheta) \ll_\varepsilon 
q^{1/2+\vartheta+\varepsilon}X^{1/2}p^{-\kappa} + p^{-\kappa/4}q^\varepsilon
+ p^{h/2-\kappa} q^{1/2+\vartheta+\varepsilon}X^{-1/2} + p^{-\kappa+(3k-h)/4}q^{\varepsilon}.
$$
Theorem \ref{thm:twisted-moment-thin-orbit} follows by choosing $X=p^{h/2}$, noting that the latter bound also holds when $(1-\varepsilon)k\leq h < k$.
%With the choice $X=p^{h/2}$, for all $0<h<k$ we have 
%$$\mathcal{E}_\kappa(\vartheta) \ll_\varepsilon p^{h/4-\kappa} q^{1/2+\vartheta+\varepsilon} + p^{-\kappa/4}q^\varepsilon + p^{k-\kappa-h/2}q^{\varepsilon},$$
%and for $0<h<(1-\varepsilon)k$ we have
%$$\mathcal{E}_\kappa(\vartheta) \ll_\varepsilon p^{h/4-\kappa} q^{1/2+\vartheta+\varepsilon} + p^{-\kappa/4}q^\varepsilon + p^{-\kappa+(3k-h)/4}q^{\varepsilon}.$$ 
%Theorem \ref{thm:twisted-moment-thin-orbit} is proved.
\end{proof}


% ----------- Corollaries for thin Galois orbits -----------

%We are in a position to derive consequences of Theorem \ref{thm:twisted-moment-thin-orbit}.

\begin{proof}[Proof of Corollary \ref{cor:thin-orbit-moment}]
    This corollary follows immediately from Theorem \ref{thm:twisted-moment-thin-orbit} on setting $m_1=m_2=1$.
\end{proof}



