\section{Proof of Theorem \ref{mol_ub}}
\label{mol_section}


Using Theorem $2.1$ in \cite{Cha09}, the following lemma immediately follows.
\begin{lem}
\label{lem_log}
Let $\chi$ be a primitive character modulo $q$. Let $\lambda$ be the solution to $e^{-\lambda} = \lambda+\lambda^2/2$. For any $x$ such that $\log x \geq 2$, we have that
\begin{align*}
\log |L(1/2,\chi)| \leq \Re \sum_{n \leq x} \frac{ \Lambda(n) \chi(n) }{n^{\frac{1}{2}+\frac{\lambda}{\log x}} \log n } \frac{ \log(x/n)}{\log x} + \frac{1+\lambda}{2}\cdot  \frac{ \log q}{\log x} + O \Big( \frac{1}{ \log^2x} \Big).
\end{align*} 
\end{lem}

The Euler product mollifier is defined as follows.


We consider the intervals
$$I_0= (1, q^{\beta_0}], \, I_1=(q^{\beta_0}, q^{\beta_1}], \ldots, I_K= (q^{\beta_{K-1}}, q^{\beta_K}],$$ and for $u \leq K$, let
$$P_{I_j}(\chi; u) = \sum_{p \in I_j} \frac{\chi(p) a(p;u)}{\sqrt{p}} ,$$ where
$$a(p;u) = \Big(1 - \frac{\log p}{\beta_u \log q} \Big) \frac{1}{p^{\frac{\lambda}{\beta_u \log q}}}.  $$
We extend $a(p;u)$ to a completely multiplicative function in the first variable. 

For $t \in \mathbb{R}$ and any integer $\ell$, we define
$$E_{\ell}(t) = \sum_{s \leq \ell} \frac{t^s}{s!}.$$
We note that when $\ell$ is even, then $E_{\ell}(t) >0$. We also have that for $t \leq \ell/e^2$, we have
\begin{equation}
e^t \leq (1+e^{-\ell/2})E_{\ell}(t).
\label{ineq_exp}
\end{equation}
We let $\nu(n)$ be the multiplicative function which is defined by $\nu(p^a) = \frac{1}{a!}$ for prime powers, and $\nu_j(n)$ denotes the $j$-fold convolution of $\nu$; namely, $\nu_j(n) = (\nu * \ldots * \nu)(n)$. Note that $\nu_j(p^a) = \frac{j^a}{a!}$.

We define
\begin{equation}
\label{mj}
M_j(\chi ) := E_{\ell_j}(-P_{I_j}(\chi;K)) = \sum_{\substack{p|n \Rightarrow p \in I_j \\ \Omega(n) \leq \ell_j}} \frac{ \chi(n) \lambda(n) a(n;K) \nu(n)}{\sqrt{n}},
\end{equation} and 
\begin{equation}
\label{mollifier}
M(\chi ) = \prod_{j=0}^K M_j(\chi),
\end{equation}
where $\lambda(n)$ denotes the Liouville function.
We have that 
$$M_j(\chi )^v= \sum_{\substack{p |n \Rightarrow p \in I_j \\ \Omega(n) \leq v \ell_j}}\frac{ \chi (n) \lambda(n) a(n;K) \nu_v(n;\ell_j)}{\sqrt{n}} ,$$
where 
$$ \nu_v(n; \ell_j) = \sum_{\substack{ n = n_1 \cdot \ldots \cdot n_v \\ \Omega(n_i) \leq \ell_j}} \nu(n_1) \cdot \ldots \cdot \nu(n_v).$$ 





Let 
$$D_{j,v} (\chi ) = \prod_{r=0}^j  (1+e^{-\ell_r/2}) E_{\ell_r}(v \Re P_{I_r}(\chi ;j)),$$ and 
\begin{equation}
S_{j,v}(\chi ) = \exp \Big( v \Re \sum_{p \leq q^{\beta_j/2}} \frac{ \chi (p^2)b(p;j)}{p} \Big),
\label{sjk}
\end{equation} where
\begin{equation}
b(p;j) = \Big(1 - \frac{2 \log p}{\beta_j \log q} \Big) \frac{1}{p^{\frac{2\lambda}{\beta_j \log q}}}.
\label{bp}
\end{equation}
Note that we have 
$$E_{\ell_r} (v \Re P_{I_r} (\chi ;j)) = \sum_{\Omega(mn) \leq \ell_r} \frac{ (v/2)^{\Omega(mn)} \chi(n)  \overline{\chi} (m) a(mn;j) \nu(n) \nu(m)}{\sqrt{mn}} .$$
For $0 \leq r \leq K$, let 
$$\mathcal{T}_r = \Big\{  \chi \pmod q \text{ primitive}, \max_{r \leq u \leq K} |\Re P_{I_r}(\chi ;u) | \leq \frac{\ell_r}{ve^2} \Big\}.$$
Then we have the following proposition.
\begin{prop}
\label{main_prop}
We either have
$$ \max_{0 \leq u \leq K} \Big| \Re P_{I_0}(\chi ;u)\Big|> \frac{\ell_0}{ve^2},$$ or
\begin{align*}
|L(1/2,\chi )|^v  & \ll \exp \Big(  \frac{v (1+\lambda)}{2 \beta_K } \Big) D_{K,v}(\chi ) S_{K,v}(\chi ) \\
&+ \sum_{\substack{0 \leq j \leq K-1 \\ j < u \leq K}} \exp \Big( \frac{ v(1+\lambda) }{2\beta_j } \Big) D_{j,v} (\chi)S_{j,v}(\chi ) \Big(\frac{ve^2 \Re P_{I_{j+1}}(\chi ;u)}{\ell_{j+1}}  \Big)^{s_{j+1}},
\end{align*}
for any even integers $s_{j+1}$.
\end{prop}
\begin{proof}
The proof is similar to the proof of Proposition $3.3$ in \cite{DFL21}, so we will only sketch the argument, for the sake of completeness. 

We note that for each primitive character $\chi$ modulo $q$, we have one of the following three cases: 
\begin{enumerate}
\item $\chi \notin \mathcal{T}_0$,
\item $\chi \in \mathcal{T}_r$, for each $r \leq K$,
\item There exists some $j <K$ such that $\chi \in \mathcal{T}_r$ for each $r \leq j$, but $\chi \notin \mathcal{T}_{j+1}$.
\end{enumerate}
 Note that the first case above is the first condition in the statement of the Proposition. If the second case is satisfied, then we use Lemma \ref{lem_log} with $x=T^{\beta_K}$ and inequality \eqref{ineq_exp}. Finally, if the third condition is satisfied, there exists $u >j$ 
 such that $|\Re P_{I_{j+1}}(\chi;u)| > \ell_{j+1}/(ve^2)$. We then use Lemma \ref{lem_log} with $x=T^{\beta_j}$, and the conclusion follows.
\end{proof}




We also need the following two key lemmas.
\begin{lem}
\label{technical_lemma}
Suppose that $(v+2) \sum_{r=0}^K \ell_r \beta_r <1$ and that for any $j \leq K-1$,  we have $(v+2) \sum_{r=0}^j \ell_r \beta_r + v \sum_{r=j+1}^{K} \ell_r \beta_r + 2s_{j+1} \beta_{j+1} <1$. Let $0 \leq u \leq K$ in $(1)$ and $j+1 \leq u \leq K$ in $(3)$. Suppose that $\beta_{r+1} = e \beta_r$, for $r=0,\ldots, K-1$. Then for any $\varepsilon >0$, we have 

\begin{align*}
(1) & \sumstar_{\chi \pmod q} |  M(\chi ) |^{2v} \Big( \Re P_{I_0}(\chi ;u)\Big)^{2s_0} \ll q e^{v^2K(1+\varepsilon)} \frac{ (2s_0)!v^{2s_0}\sqrt{s_0}}{(s_0)!2^{s_0}} (\log \log q^{\beta_0})^{2s_0} ,\\ 
(2)& \sumstar_{\chi \pmod q} D_{K,v}(\chi ) ^2 |M(\chi )|^{2v} \ll q \Big(  1 + \frac{1}{2^{\ell_0}} (\log q^{\beta_0})^{16v^2}\Big), \\
 (3) &\sumstar_{\chi \pmod q} D_{j,v}(\chi ) ^2 |M(\chi )|^{2v} (\Re P_{I_{j+1}}(\chi ;u))^{2s_{j+1}}  \ll q e^{v^2(K-j)(1+\varepsilon)} \frac{(2s_{j+1})! v^{2s_{j+1}} \sqrt{s_{j+1}}}{(s_{j+1})! 2^{s_{j+1}}} \Big(\sum_{p \in I_{j+1}} \frac{1}{p} \Big)^{2s_{j+1}}\\
 & \qquad \qquad \qquad \quad \quad \times \Big(  1 + \frac{1}{2^{\ell_0}} (\log q^{\beta_0})^{16v^2}\Big).
\end{align*}
\end{lem}
We also prove the following bound on the contribution of primes square.
\begin{lem}
\label{lemma_squares}
Let $S_{j,v}$ be defined as in \eqref{sjk}. For $0 \leq j \leq K$, we have
$$\sumstar_{\chi \pmod q} S_{j,v}(\chi)^2 \ll q.$$
\end{lem} 

We will now first prove Theorem \ref{mol_ub}, and then proceed to the proofs of the technical lemmas above.


\subsection{Choice of parameters and proof of Theorem \ref{mol_ub}}


We choose 
 \begin{align}
 \label{beta_j}
 \beta_j = \frac{e^j \log \log q}{\log q},
 \end{align}
 for $j \leq K$.  We choose $\beta_K=c$, where $c$ is a small positive constant such that
 \begin{equation}
 \label{condition_c}
  c< \frac{4 (e^{1/4}-1)^4}{e(v+2)^4}.
  \end{equation}
 We further choose for $j \leq K$, 
 \begin{equation}
 s_j = 2 \Big[ \frac{1}{8 \beta_j},\Big], \, \ell_j=[s_j^{3/4}].
 \label{sj}
 \end{equation} 
Note that condition \eqref{condition_c} ensures that the conditions in Lemma \ref{technical_lemma} are satisfied.

Using Proposition \ref{main_prop},  we write
\begin{align}
& \sumstar_{\chi \pmod q}  \Big| L (1/2,\chi ) M(\chi ) \Big|^v \leq \sumstar_{\substack{\chi \pmod q \\ \chi \notin \mathcal{T}_0}}  \Big| L (1/2,\chi ) M(\chi ) \Big|^v  \label{bound1} \\
& + \sumstar_{\chi \pmod q }  \exp \Big(  \frac{v (1+\lambda) }{2 \beta_K } \Big) D_{K,v}(\chi ) S_{K,v}(\chi ) |M(\chi )|^v \label{bound2} \\
&+ \sumstar_{\chi \pmod q}  \sum_{\substack{0 \leq j \leq K-1 \\ j < u \leq K}} \exp \Big( \frac{ v(1+\lambda) }{2\beta_j } \Big) D_{j,v} (\chi) S_{j,v}(\chi) \Big(\frac{ve^2 \Re P_{I_{j+1}}(\chi ;u)}{\ell_{j+1}}  \Big)^{s_{j+1}} |M(\chi )|^v. \label{bound3}
\end{align}
For the first term \eqref{bound1}, we have that for some $0 \leq u \leq K$ ,
\begin{align}
&\sumstar_{\substack{\chi \pmod q \\ \chi \notin \mathcal{T}_0}}  \Big| L (1/2,\chi ) M(\chi ) \Big|^v \leq \sumstar_{\chi \pmod q}  \Big| L (1/2,\chi ) M(\chi ) \Big|^v \Big( \frac{ve^2 \Re P_{I_0}(\chi ;u)}{\ell_0} \Big)^{s_0} \nonumber  \\
& \leq \Big( \sumstar_{\chi \pmod q} \Big|L(1/2,\chi ) \Big|^{2v}\Big)^{1/2}  \Big( \sumstar_{\chi \pmod q} |  M(\chi ) |^{2v} \Big( \frac{ve^2 \Re P_{I_0}(\chi ;u)}{\ell_0} \Big)^{2s_0} \Big)^{1/2}. \label{not_to}
\end{align}
Under GRH,  we have the sharp upper bound of Soundararajan \cite{Sou09} and Harper \cite{Har13} for Dirichlet $L$-functions. 
Applying \cite[Theorem 1]{Sza24} (in the notation therein set $2k=2$, $a_1=a_2=v$, $t_1=t_2=0$) we have that
$$ \sumstar_{\chi \pmod q} \Big|L(1/2,\chi ) \Big|^{2v} \ll q (\log q)^{v^2}.$$
Using equation \eqref{not_to}, Lemma \ref{technical_lemma}, the bound above and Stirling's formula, we have
\begin{align*}
\sumstar_{\substack{\chi \pmod q \\ \chi \notin \mathcal{T}_0}} & \Big| L (1/2,\chi ) M(\chi ) \Big|^v \leq q \exp \Big( - \frac{1}{4} s_0  \log s_0 + s_0 \log (2^{1/2}v^2 e^{3/2})+ \frac{1}{4} \log s_0 \\
&+s_0 \log \log \log q^{\beta_0}+\frac{v^2 K(1+\varepsilon)}{2} \Big) (\log q)^{v^2/2} = o(q),
\end{align*} 
where we used the choices \eqref{beta_j} and \eqref{sj}, as well as the fact that $K \asymp \log \log q$.


For the term \eqref{bound2}, we also have that 
\begin{align*}
 \sumstar_{\chi \pmod q}  & D_{K,v}(\chi ) S_{K,v}(\chi ) |M(\chi ) |^v \leq \Big( \sumstar_{\chi \pmod q} D_{K,v}(\chi ) ^2 |M(\chi )|^{2v} \Big)^{1/2} \\ 
& \times  \Big( \sumstar_{\chi \pmod q} S_{K,v}(\chi )^2 \Big)^{1/2} ,
\end{align*}
and for the term \eqref{bound3}, we have
\begin{align}
& \sumstar_{\chi \pmod q}  D_{j,v} (\chi) S_{j,v}(\chi ) \Big(\frac{ve^2 \Re P_{I_{j+1}}(\chi ;u)}{\ell_{j+1}}  \Big)^{s_{j+1}} |M(\chi ) |^v  \label{sumj} \\
& \leq \Big(  \frac{ve^2}{\ell_{j+1}} \Big)^{s_{j+1}}  \Big( \sumstar_{\chi \pmod q} D_{j,v}(\chi ) ^2 |M(\chi )|^{2v}  (\Re P_{I_{j+1}}(\chi ;u))^{2s_{j+1}}\Big)^{1/2}  \Big( \sumstar_{\chi \pmod q} S_{j,v}(\chi )^2 \Big)^{1/2}. \nonumber 
\end{align}  







We focus on bounding the term \eqref{bound3}; bounding \eqref{bound2} follows similarly. Using \eqref{sumj}, Lemma \ref{technical_lemma} and Stirling's formula, and since 
$$  \sum_{p \in I_{j+1}} \frac{1}{p} = 1+ O \Big(  \frac{1}{\beta_j \log q}\Big) \leq 2,$$
we have that
\begin{align}
& \eqref{bound3}   \ll q  \sum_{\substack{0 \leq j \leq K-1 }} (K-j) \exp \Big( \frac{ v(1+\lambda) }{2\beta_j } \Big) \exp \Big( -\frac{1}{4}s_{j+1} \log s_{j+1} +s_{j+1} \log (2^{3/2} v^2 e^{3/2})  \nonumber  \\
&+\frac{1}{4}\log s_{j+1}+ \frac{v^2(K-j)(1+\varepsilon)}{2} \Big) \ll q \sum_{0 \leq j <K} \exp \Big( \frac{A \log q}{e^j \log \log q} - \frac{\log q}{16e^{j+1}}+ \frac{(j+1) \log q}{16e^{j+1} \log \log q} \nonumber \\
&+ \frac{ (\log q) (\log \log \log q)}{16e^{j+1} \log \log q}  \frac{ \log \log q -(j+1)- \log \log \log q}{4}+ \frac{v^2(K-j)(1+\varepsilon)}{2}+\log(K-j) \Big),
\nonumber 
\end{align}
where $A = \frac{v(1+\lambda)}{2} + \frac{\log 4}{16 e} + \frac{ \log (2^{3/2} v^2 e^{3/2})}{4e}.$
Rearranging the above, we have
\begin{align*}
\eqref{bound3} & \ll q \sum_{0 \leq j <K} \exp \Big(  \frac{1}{16e^{j+1}} \Big( \frac{(j+1) \log q}{\log \log q} - \log q + \frac{16Ae \log q}{\log\log q}+ \frac{( \log q )(\log \log \log q)}{\log \log q} \Big) \\
& + \frac{ \log \log q -(j+1)- \log \log \log q}{4} + \frac{v^2(K-j)(1+\varepsilon)}{2} + \log (K-j)\Big).
\end{align*}

Now using the fact that $K< \log \log q - \log \log \log q + \log d $, and for $d$ small enough, note that we have
\begin{align*}
\eqref{bound3} &\ll q \sum_{0 \leq j <K} \exp \Big(  - \frac{b \log q}{e^{j+1} \log \log q}+ \frac{ \log \log q -(j+1)- \log \log \log q}{4} + \frac{v^2(K-j)(1+\varepsilon)}{2} \\
&+ \log (K-j)\Big),
\end{align*}
for some $b>0$. Bounding $\log(K-j) \leq (K-j)$, we get that the above is
\begin{align*}
\eqref{bound3}& \ll q \sum_{0 \leq j <K}  \exp \Big(  - \frac{b \log q}{e^{j+1} \log \log q}+ \frac{ \log \log q -(j+1)- \log \log \log q}{4} + (K-j) \Big( \frac{v^2(1+\varepsilon)}{2}+1\Big) \Big) \\
& \ll q \exp \Big( \frac{ \log \log q - \log \log \log q}{4} + K \Big( \frac{v^2(1+\varepsilon)}{2}+1\Big) \Big) \\
& \times \int_{0}^{K-1} \exp \Big(- \frac{b \log q}{e^{t+1} \log \log q} - \frac{t}{4} - t \Big(\frac{v^2(1+\varepsilon)}{2}+1\Big) \Big) \, dt.
\end{align*}
With the change of variables $e^{-t} = \frac{ e \log \log q }{b \log q} u$, it follows that
\begin{align*}
\eqref{bound3} & \ll  q \exp \Big( \frac{ \log \log q - \log \log \log q}{4} + K \Big( \frac{v^2(1+\varepsilon)}{2}+1\Big) \Big) \Big( \frac{ \log \log q}{\log q} \Big)^{ \frac{1}{4} + \frac{v^2(1+\varepsilon)}{2}+1} \\
& \times  \int_{ \frac{ b \log q}{e^K \log \log q}}^{\frac{b \log q}{e \log \log q}} \exp(-u) u^{ \frac{1}{4} + \frac{k^2(1+\varepsilon)}{2}} \, du \\
& \leq q \exp \Big( \frac{ \log \log q - \log \log \log q}{4} + K \Big( \frac{v^2(1+\varepsilon)}{2}+1\Big) \Big) \Big( \frac{ \log \log q}{\log q} \Big)^{ \frac{1}{4} + \frac{v^2(1+\varepsilon)}{2}+1}  \Gamma \Big( \frac{5}{4}+ \frac{v^2(1+\varepsilon)}{2} \Big).
\end{align*}
Since $e^K \asymp \log q/\log \log q$, from the above, we get that
\begin{align*}
\eqref{bound3} \ll q.
\end{align*}


\kommentar{$$ \frac{\log \log q}{4} - \frac{j+1}{4} <  \frac{ \varepsilon \log q}{16e^{j+1}},$$ and 
$$   \frac{A \log q}{e^j \log \log q}  + \frac{ (\log q) (\log \log \log q)}{16e^{j+1} \log \log q} - \frac{\log \log \log q}{4} + \frac{k^2(K-j)(1+\varepsilon)}{2}+\log(K-j) <  \frac{ \varepsilon \log q}{16e^{j+1}} .$$
After a relabeling of $\varepsilon$, it follows that 
\begin{align}
\eqref{bdint} \ll q \sum_{0 \leq j <K} \exp \Big(\frac{-(1-\varepsilon) \log q}{16 e^{j+1}} + \frac{(j+1) \log q}{16e^{j+1}\log \log q}  \Big) 
\end{align}
