\subsection{Proof of Lemma \ref{technical_lemma}} We are now ready to begin the proof of the technical Lemma \ref{technical_lemma}.
We start with the second part of the lemma. The term we need to bound is
\begin{align}
\label{to_bd}
\sumstar_{\chi \pmod q} &  \prod_{r=0}^K (1+e^{-\ell_r/2})^2 \mathcal{E}_r (\chi ),
\end{align}
where
\begin{align}
\mathcal{E}_r(\chi ) &= \sum_{\substack{ p | m_{r_1} n_{r_1} m_{r_2} n_{r_2} \Rightarrow p \in I_r \\ \Omega( m_{r_1} n_{r_1}) \leq \ell_r \\ \Omega(m_{r_2} n_{r_2}) \leq \ell_r}} \frac{ (v/2)^{\Omega(m_{r_1}n_{r_1}m_{r_2} n_{r_2})} \chi (n_{r_1} n_{r_2} ) \overline{ \chi}(m_{r_1} m_{r_2}) }{\sqrt{m_{r_1} m_{r_2} n_{r_1} n_{r_2}}} \nonumber  \\
& \times a(m_{r_1} m_{r_2}n_{r_1} n_{r_2};K)  \nu(n_{r_1}) \nu(n_{r_2}) \nu(m_{r_1}) \nu(m_{r_2}) \nonumber \\
& \times \sum_{\substack{p|f_rh_r \Rightarrow p \in I_r \\ \Omega(f_r) \leq v \ell_r \\ \Omega(h_r) \leq v \ell_r}} \frac{\chi(f_r) \overline{\chi}(h_r) \lambda(f_r) \lambda(h_r) a(f_r h_r;K) \nu_v(f_r;\ell_r) \nu_v(h_r;\ell_r) }{\sqrt{f_rh_r}}. \label{epsilonr}
\end{align}
Note that the summands in \eqref{to_bd} are positive, so we bound \eqref{to_bd} by the sum over all characters $\chi$ modulo $q$. Using orthogonality of characters, we only keep the term with $ n_{r_1} n_{r_2} f_r \equiv   m_{r_1} m_{r_2} h_r \pmod q$. Since $\prod_{r=0}^K n_{r_1} n_{r_2} f_r <q$ and $\prod_{r=0}^K m_{r_1} m_{r_2} h_r <q$ (because $ (v+2) \sum_{r=0}^K \beta_r \ell_r <1$), this can happen only when $\prod_{r=0}^K n_{r_1} n_{r_2} f_r=\prod_{r=0}^K m_{r_1} m_{r_2} h_r$, hence when $n_{r_1} n_{r_2} f_r= m_{r_1} m_{r_2} h_r$ for each $r \leq K$. 

Then the term we need to bound is 
\begin{align*}
q \prod_{r=0}^K &E_r := q \prod_{r=0}^K  \sum_{\substack{ p | m_{r_1} n_{r_1} m_{r_2} n_{r_2}f_rh_r  \Rightarrow p \in I_r \\ \Omega( m_{r_1} n_{r_1}) \leq \ell_r \\ \Omega(m_{r_2} n_{r_2}) \leq \ell_r \\\Omega(f_r) \leq v \ell_r \\ \Omega(h_r) \leq v \ell_r \\ n_{r_1} n_{r_2} f_r = m_{r_1} m_{r_2} h_r }} \frac{ (v/2)^{\Omega(m_{r_1}n_{r_1}m_{r_2} n_{r_2})}a(m_{r_1} m_{r_2}n_{r_1} n_{r_2};K)   }{\sqrt{m_{r_1} m_{r_2} n_{r_1} n_{r_2} f_rh_r}} \\
& \times  \nu(n_{r_1}) \nu(n_{r_2}) \nu(m_{r_1}) \nu(m_{r_2}) \lambda(f_r) \lambda(h_r)a(f_r h_r;K)  \nu_v(f_r;\ell_r) \nu_v(h_r;\ell_r) .
\end{align*}

If $\max\{ \Omega(m_{r_1} n_{r_1}), \Omega(m_{r_2} n_{r_2})\} >\ell_r$ or if $\max\{\Omega(f_r),\Omega(h_r)\} >v \ell_r$ then, since $v \geq 1$, we have that $2^{\Omega(m_{r_1} m_{r_2} n_{r_1} n_{r_2} f_r h_r)} \geq 2^{\ell_r}$.  It then follows that 
\begin{align*}
E_r & =  \sum_{\substack{ p | m_{r_1} n_{r_1} m_{r_2} n_{r_2}f_rh_r  \Rightarrow p \in I_r \\ n_{r_1} n_{r_2} f_r= m_{r_1} m_{r_2} h_r  }} \frac{ (v/2)^{\Omega(m_{r_1}n_{r_1}m_{r_2} n_{r_2})}a(m_{r_1} m_{r_2} n_{r_1} n_{r_2};K)  }{\sqrt{m_{r_1} m_{r_2} n_{r_1} n_{r_2} f_rh_r}} \\
& \times  \nu(n_{r_1}) \nu(n_{r_2}) \nu(m_{r_1}) \nu(m_{r_2})\lambda(f_r) \lambda(h_r)  a(f_r h_r;K)  \nu_v(f_r) \nu_v(h_r)  \\
&+ O \Bigg(  \frac{1}{2^{\ell_r}}  \sum_{\substack{ p | m_{r_1} n_{r_1} m_{r_2} n_{r_2}f_rh_r  \Rightarrow p \in I_r \\ n_{r_1} n_{r_2} f_r = m_{r_1} m_{r_2} h_r }} \frac{2^{\Omega(m_{r_1} m_{r_2} n_{r_1} n_{r_2} f_rh_r)} (v/2)^{\Omega(m_{r_1}n_{r_1}m_{r_2} n_{r_2})} }{\sqrt{m_{r_1} m_{r_2} n_{r_1} n_{r_2} f_rh_r}}   \nu(n_{r_1}) \nu(n_{r_2}) \nu(m_{r_1}) \nu(m_{r_2})\\
& \times \nu_v(f_r) \nu_v(h_r) \Bigg),
\end{align*}
where we used the fact that $a(n;K) \leq 1$ for any $n$.
 Now let $M_r=m_{r_1} m_{r_2}$ and $N_r= n_{r_1} n_{r_2}$.  We then rewrite
 \begin{align}
 E_r &= \sum_{\substack{p|M_rN_r f_rh_r \Rightarrow p \in I_r \\ N_rf_r=M_rh_r}}  \frac{ (v/2)^{\Omega(M_rN_r)}a(M_r N_r;K)   }{\sqrt{M_rN_r f_rh_r}} \nu_2(N_r) \nu_2(M_r)  \lambda(f_r) \lambda(h_r) a(f_r h_r;K)  \nonumber  \\
& \times   \nu_v(f_r) \nu_v(h_r) + O \Bigg(  \frac{1}{2^{\ell_r}}  \sum_{\substack{ p | M_rN_rf_rh_r  \Rightarrow p \in I_r \\ N_r f_r = M_r h_r }} \frac{ (2v)^{\Omega( M_rN_rf_rh_r)} }{\sqrt{M_rN_r f_rh_r}}   \Bigg), \label{er}
 \end{align}
where we used the fact that $\nu_2(f) \leq 2^{\Omega(f)}$ and $\nu_v(f) \leq v^{\Omega(f)}$.

Let $A_r=(N_r, M_r)$ and $B_r=(f_r,h_r)$, and we write $N_r= A_r C_r$,  and $M_r=A_rD_r$ with $(C_r,D_r)=1$.  Similarly write $f_r=B_rf_{r1}$ and $h_r=B_rh_{r1}$ with $(f_{r1}, h_{r1})=1$.  Since $N_rf_r=M_rh_r$,  it follows that $f_{r1}=D_r$ and $h_{r1}=C_r$.

The error term in the evaluation of $E_r$ in equation \eqref{er} then becomes 
\begin{align}
\frac{1}{2^{\ell_r}} &\sum_{\substack{p| A_rB_rC_rD_r \Rightarrow p \in I_r \\ (C_r,D_r)=1}} \frac{ (2v)^{\Omega(A_r^2B_r^2C_r^2 D_r^2 )}}{A_rB_rC_rD_r} \leq \frac{1}{2^{\ell_r}} \Big( \sum_{p|A \Rightarrow p \in I_r}\frac{(2v)^{\Omega(A^2)}}{A} \Big)^4 \nonumber  \\
& \leq \frac{1}{2^{\ell_r}}\prod_{p \in I_r} \Big(1 - \frac{4v^2}{p} \Big)^{-4} =
\begin{cases}
O \Big( \frac{1}{2^{\ell_r}} \Big) & \mbox{ if } r \neq 0 \\
O \Big(  \frac{1}{2^{\ell_0}} (\log q^{\beta_0})^{16v^2}\Big) & \mbox{ if } r=0.
\end{cases}
\label{error_er}
\end{align}

We now focus on the main term in \eqref{er}.  We rewrite it as
\begin{align*}
 \sum_{\substack{p| A_rB_rC_rD_r \Rightarrow p \in I_r \\ (C_r,D_r)=1}}  &  \frac{ (v/2)^{\Omega(A^2 C_rD_r)} a(A_r^2B_r^2C_r^2D_r^2 ;K)}{A_rB_rC_rD_r} \nu_2(A_rC_r) \nu_2(A_rD_r)\lambda(C_rD_r) \\
 & \times \nu_v(B_rD_r) \nu_v(B_rC_r) = \prod_{p \in I_r} \Big( 1 + O \Big(\frac{1}{p^2}\Big) \Big).
\end{align*}

Combining the above and equation \eqref{error_er}, it follows that
\begin{equation*}
q \prod_{r=0}^K E_r  \ll q \Big( 1 +\frac{1}{2^{\ell_0}} (\log q^{\beta_0})^{16v^2} \Big),
\end{equation*} which finishes the proof of the second bound in the lemma.

We now focus on the third bound.  We need to bound
\begin{align*}
\sumstar_{\chi \pmod q } \prod_{r=0}^j (1+e^{-\ell_r/2})^2 \mathcal{E}_r(\chi) \prod_{r=j+1}^K \mathcal{E}_r(\chi),
\end{align*}
where if $r \leq j$,  then $\mathcal{E}_r(\chi)$ is given as in the previous case by equation \eqref{epsilonr}.

 If $r=j+1$,  then
\begin{align*}
\mathcal{E}_{r}(\chi) &= \frac{ (2s_{j+1})!}{4^{s_{j+1}}}  \sum_{\substack{p|f_rh_r c_rd_r\Rightarrow p \in I_r \\ \Omega(f_r) \leq v \ell_r \\ \Omega(h_r) \leq v \ell_r \\ \Omega(c_rd_r)=2s_{j+1}}}  \frac{\chi(f_r) \overline{\chi}(h_r) \lambda(f_r) \lambda(h_r) a(f_r h_r;K) \nu_v(f_r;\ell_r) \nu_v(h_r;\ell_r) }{\sqrt{f_rh_r}} \\
& \times \chi(c_r) \overline{\chi(d_r)} a(c_rd_r;u)   \nu(c_r) \nu(d_r).
\end{align*}

If $r \geq j+2$,  then 
\begin{align*}
\mathcal{E}_{r}(\chi) &=  \sum_{\substack{p|f_rh_r \Rightarrow p \in I_r \\ \Omega(f_r) \leq v \ell_r \\ \Omega(h_r) \leq v \ell_r }}  \frac{\chi(f_r) \overline{\chi}(h_r) \lambda(f_r) \lambda(h_r) a(f_r h_r;K) \nu_v(f_r;\ell_r) \nu_v(h_r;\ell_r) }{\sqrt{f_rh_r}}.
\end{align*}
Since all the summands are positive, we extend the sum over primitive characters to a sum over all $\chi \pmod q$,  and use orthogonality of characters. Since
\begin{equation}
(v+2) \sum_{r \leq j} \ell_r \beta_r + 2s_{j+1} \beta_{j+1}+ \sum_{r=j+1}^K v \ell_r \beta_r <1.
\label{cond_sum}
\end{equation}
it follows that we have to bound the following expression
\begin{align*}
q \prod_{r =0}^K E_r,
\end{align*}
where if $r \leq j$, as before, we have that
\begin{align*}
E_r &= \sum_{\substack{ p | m_{r_1} n_{r_1} m_{r_2} n_{r_2}f_rh_r  \Rightarrow p \in I_r \\ \Omega( m_{r_1} n_{r_1}) \leq \ell_r \\ \Omega(m_{r_2} n_{r_2}) \leq \ell_r \\\Omega(f_r) \leq v \ell_r \\ \Omega(h_r) \leq v \ell_r \\ n_{r_1} n_{r_2} f_r = m_{r_1} m_{r_2} h_r }} \frac{ (k/2)^{\Omega(m_{r_1}n_{r_1}m_{r_2} n_{r_2})}a(m_{r_1} m_{r_2}n_{r_1} n_{r_2};K)   }{\sqrt{m_{r_1} m_{r_2} n_{r_1} n_{r_2} f_rh_r}} \\
& \times  \nu(n_{r_1}) \nu(n_{r_2}) \nu(m_{r_1}) \nu(m_{r_2}) \lambda(f_r) \lambda(h_r)a(f_r h_r;K)  \nu_v(f_r;\ell_r) \nu_v(h_r;\ell_r) .
\end{align*}
When $r=j+1$,  
\begin{align*}
E_r &= \frac{ (2s_{r})!}{4^{s_{r}}}  \sum_{\substack{p|f_rh_r c_rd_r\Rightarrow p \in I_r \\ \Omega(f_r) \leq v \ell_r \\ \Omega(h_r) \leq v \ell_r \\ \Omega(c_rd_r)=2s_{r}\\ f_rc_r=h_rd_r}}  \frac{  \lambda(f_r) \lambda(h_r) a(f_r h_r;K) \nu_v(f_r;\ell_r) \nu_v(h_r;\ell_r) a(c_rd_r;u)   \nu(c_r) \nu(d_r)}{\sqrt{f_rh_rc_rd_r}}  ,
\end{align*}
and when $r \geq j+2$,
\begin{equation}
\label{bigr}
E_r =  \sum_{\substack{p|f_rh_r \Rightarrow p \in I_r \\ \Omega(f_r) \leq v \ell_r \\ \Omega(h_r) \leq v \ell_r \\ f_r=h_r}} \frac{\lambda(f_r) \lambda(h_r) a(f_r h_r;K) \nu_v(f_r;\ell_r) \nu_v(h_r;\ell_r) }{\sqrt{f_rh_r}}.
\end{equation}

We deal with the product $\prod_{r=0}^j E_r$ in exactly the same way as before, and it follows that
\begin{equation}
\prod_{r=0}^j E_r \ll 1 +\frac{1}{2^{\ell_0}} (\log q^{\beta_0})^{16v^2}.
\label{er1}
\end{equation}
To bound $E_{r}$ when $r=j+1$,  we get
$$E_r \leq  \frac{ (2s_{r})!}{4^{s_{r}}}  \sum_{\substack{p|f_rh_r c_rd_r\Rightarrow p \in I_r \\ \Omega(f_r) \leq v \ell_r \\ \Omega(h_r) \leq v \ell_r \\ \Omega(c_rd_r)=2s_{r}\\ f_rc_r=h_rd_r}} \frac{ \nu_v(f_r) \nu_v(h_r) \nu(c_r) \nu(d_r)}{\sqrt{f_rh_rc_rd_r}}  .$$
Using a similar change of variables as before,  we write $f_r=B_rf_{r1}, c_r = A_rh_{r1}, h_r=B_rh_{r1}, d_r=A_rf_{r1}$ with $(f_{r1}, h_{r1})=1$.  Then we have
\begin{align*}
E_r \leq \frac{ (2s_{r})!}{4^{s_{r}}}  \sum_{\substack{p |A_rB_rf_{r1}h_{r1} \Rightarrow p \in I_r \\ \Omega(A_rf_{r1}) \leq v\ell_r \\ \Omega(B_rh_{r1})\leq v \ell_r \\ \Omega(A_r^2f_{r1} h_{r1})=2s_r}} \frac{\nu_v(B_rf_{r1}) \nu_v(B_rh_{r1})\nu(A_rf_{r1}) \nu(A_rh_{r1})}{A_rB_rf_{r1}h_{r1}}.
\end{align*}
Now we use the fact that 
$$\nu_v(B_rf_{r1}) \leq d_v(B_rf_{r1}) \leq d_v(B_r) d_v(f_{r1}) \leq d_v(B_r) v^{\Omega(f_{r1})},$$ and a similar inequality holds for $\nu_v(B_rh_{r1})$.  We also use the fact that $\nu(A_rf_{r1}) \leq \nu(A_r) \nu(f_{r1})$ and similarly for $\nu(A_rh_{r1})$. We then get that
\begin{align}
E_r \leq \frac{ (2s_{r})!}{4^{s_{r}}}  \sum_{\substack{p |A_rB_rf_{r1}h_{r1} \Rightarrow p \in I_r \\ \Omega(A_r^2f_{r1} h_{r1})=2s_r}} \frac{d_v(B_r)^2 v^{2s_r-2\Omega(A_r)} \nu(A_r) \nu(f_{r1}) \nu(h_{r1})}{A_rB_rf_{r1}h_{r1}}, \label{er4}
\end{align}
where we also used the fact that $\nu(A_r)^2 \leq \nu(A_r)$.
We first consider the sum over $f_{r1}$.  We have 
\begin{align}
\sum_{\substack{p|f_{r1} \Rightarrow p \in I_r \\ \Omega(f_{r1}) = 2s_r-\Omega(h_{r1})-2\Omega(A_r)}}  \frac{ \nu(f_{r1})}{f_{r1}}  = \frac{1 }{(2s_r-\Omega(h_{r1})-2\Omega(A_r))!}\Big(  \sum_{p \in I_r} \frac{1}{p} \Big)^{2s_r-\Omega(h_{r1}) - 2\Omega(A_r)}.
\label{sumfr1}
\end{align}
%Note that $\sum_{p \in I_r} \frac{1}{p} = 1+o(1)$, where we used the fact that $\beta_{r+1}= e \beta_r$.  
Let $S= \sum_{p \in  I_r} \frac{1}{p}.$ We introduce the sum over $h_{r1}$,  and we have 
\begin{align}
\sum_{\substack{p|h_{r1} \Rightarrow p \in I_r\\\Omega(h_{r1}) \leq 2s_r-2\Omega(A_r)}} &\frac{ \nu(h_{r1})}{(2s_r-\Omega(h_{r1})-2\Omega(A)!h_{r1}S^{\Omega(h_{r1})}} = \sum_{i=0}^{2s_r-2\Omega(A_r)} \frac{1}{(2s_r-2\Omega(A)-i)!i!S^i}  \Big( \sum_{p \in I_r} \frac{1}{p} \Big)^i \nonumber  \\
& = \frac{2^{2s_r-2\Omega(A_r)}}{(2s_r-2\Omega(A_r))!}. \label{sumhr1}
\end{align}
Now we introduce the sum over $A_r$ in \eqref{er4}. Using the above equations,  it follows that
\begin{align*}
\sum_{\substack{p|A_r \Rightarrow p \in I_r \\ \Omega(A_r) \leq s_r}} & \frac{\nu(A_r)}{ (2s_r-2\Omega(A_r))!(2vS)^{2\Omega(A)}A_r} = \sum_{i=0}^{s_r} \frac{1}{ (2s_r-2i)!i!(2vS)^{2i}} S^i   .
\end{align*}
Using Stirling's formula, we get that the above is
\begin{align}
\label{sumar}
\ll \sum_{i=0}^{s_r} \frac{ \sqrt{s_r-i}}{4^{2s_r-2i} i!(s_r-i)!^2 (4v^2S)^i} \ll \frac{\sqrt{s_r}}{4^{2s_r}(s_r)!} \Big( 1+ \frac{4}{v^2S} \Big)^{s_r} \ll \frac{\sqrt{s_r}}{(s_r)! 2^{s_r}},
\end{align}
where we used the fact that $v \geq 1$ and that $S=1+o(1)$ (which follows from the fact that $\beta_{r+1}= e \beta_r$).
We finally introduce the sum over $B_r$ and we have
\begin{equation}
\label{sumbr}
\sum_{p|B_r \Rightarrow p \in I_r} \frac{d_v(B_r)^2}{B_r} \ll \prod_{p \in I_r} \Big(1+\frac{1}{p} \Big)^{v^2} =O(1).
\end{equation}
From equations \eqref{er4}, \eqref{sumfr1}, \eqref{sumhr1}, \eqref{sumar}, \eqref{sumbr} it follows that when $r=j+1$,
\begin{equation}
E_r \leq \frac{(2s_r)! (vS)^{2s_r}\sqrt{s_r}}{(s_r!) 2^{s_r}}.
\label{erj+1}
\end{equation}

Now we consider the contribution from $r \geq j+2$ in equation \eqref{bigr}.  In this case,  we use the fact that $\nu_v(f_r;\ell_r) \leq \nu_v(f_r) \leq v^{\Omega(f_r)}$, and we get that
\begin{align*}
E_r \leq \sum_{p|f_r \Rightarrow p \in I_r} \frac{v^{2\Omega(f_r)}}{f_r} \ll \prod_{p \in I_r} \Big(1+ \frac{v^2}{p}\Big) \leq e^{v^2(1+\varepsilon)},
\end{align*} 
hence
\begin{equation} 
\label{erj+2}
\prod_{r=j+2}^K E_r \ll e^{v^2(K-j)(1+\varepsilon)}.
\end{equation}
Using equations \eqref{er1}, \eqref{erj+1} and \eqref{erj+2}, the conclusion follows for the third bound of the lemma. 

Bounding $(1)$ in Lemma \ref{technical_lemma} is similar, except that in equation \eqref{erj+1} we bound 
$$\Big( \sum_{p \in I_0} \frac{1}{p} \Big)^{2s_0} \ll (\log \log q^{\beta_0})^{2s_0}.$$
\qed

