\subsection{Proof of Lemma \ref{lemma_squares}}
The proof is similar to the proof of Lemma $5.1$ in \cite{DFL21}.  Let
$$F_m(\chi;j) = \sum_{2^m<p\leq 2^{m+1}} \frac{\chi(p^2)b(p;j)}{p},$$
where recall that $b(p;j)$ is given in equation \eqref{bp}. 
For simplicity,  we will denote $F_m(\chi;j)$ by $F_m(\chi)$.  Let
$$\mathcal{F}(m)  = \Big\{  \chi :  |\Re F_m(\chi) |> \frac{1}{2^{m/4}} \text{ but } |\Re F_n(\chi)| \leq \frac{1}{2^{n/4}}, \forall m+1 \leq n \leq \frac{\beta_j \log q}{2 \log 2} \Big\}.$$
Note that the sets $\mathcal{F}(m)$ are disjoint,  and we have
\begin{equation}
 \sumstar_{\chi \pmod q} S_{j,v}(\chi)^2 \leq \sum_{m \leq \frac{\beta_j \log q}{2\log 2}} \sum_{\chi \in \mathcal{F}(m)} S_{j,v}(\chi)^2 + \sum_{\chi \notin \mathcal{F}(m),  \forall m} S_{j,v}(\chi)^2.
 \label{sumsquares}
 \end{equation}
If $\chi \notin \mathcal{F}(m)$ for any $m$, then note that $|\Re F_n(\chi)| \leq \frac{1}{2^{n/4}}$ for all $n \leq \frac{\beta_j \log q}{2 \log 2}$, and hence in this case, 
$$S_{j,v}(\chi)^2 = O(1).$$
If $\chi \in \mathcal{F}(m)$ for some $m \leq \frac{\beta_j \log q}{2 \log 2}$, then 
$$\sum_{\ell=0}^{\frac{\beta_j \log q}{2 \log 2}} \Re F_{\ell}(\chi) \leq \frac{1}{2}+ \sum_{\ell=1}^{m} \frac{1}{\ell}+ \sum_{\ell=m+1}^{\frac{\beta_j \log q}{2\log 2}} \frac{1}{2^{\ell/4}} \leq \frac{1}{2}+\log m+1+ \frac{1}{2^{m/4}(1-2^{-1/4})}.$$
It then follows that
$$S_{j,v}(\chi)^2 \leq \exp \Big(v+2v(\log m+1)+ \frac{2v}{2^{m/4}(1-2^{-1/4})}\Big).$$
If $\chi \in \mathcal{F}(m)$, we also have that $(2^{m/4} \Re F_m(\chi))^4 > 1$, so 
\begin{align}
\label{sum_m}
\sum_{\chi \in \mathcal{F}(m)} S_{j,v}(\chi)^2 \leq \exp \Big(v+2v(\log m+1)+ \frac{2v}{2^{m/4}(1-2^{-1/4})}\Big) \sum_{\chi \pmod q} (2^{m/4} \Re F_m(\chi))^4.
\end{align}
Now we have
\begin{align}
\sum_{\chi \pmod q} (2^{m/4} \Re F_m(\chi))^4 = \frac{4!2^m}{2^4} \sum_{\substack{p|fh \Rightarrow 2^m<p\leq 2^{m+1} \\ \Omega(fh)=4}} \frac{ \chi(f^2) \overline{\chi}(h^2) b(f;j) b(h;j)  \nu(f) \nu(h)}{fh}.
\label{sumchi}
\end{align}
We use orthogonality of characters (because $\beta_j \leq \beta_K$ and $\beta_K$ is small enough) to get that the above is 
\begin{align}
\label{eq4}
\eqref{sumchi} = q\frac{4! 2^m}{2^4} \sum_{\substack{p|f \Rightarrow 2^m<p \leq 2^{m+1} \\ \Omega(f)=2}} \frac{ b(f;j)^2 \nu(f)^2}{f^2} \leq q\frac{4! 2^m}{2^5} \Big( \sum_{2^m<p \leq 2^{m+1}} \frac{1}{p^2}\Big)^2\leq q\frac{4!}{2^{m+5}},
\end{align}
where we used the fact that $|b(f;j)| \leq 1$. 

Now using equations \eqref{sumsquares}, \eqref{sum_m} and \eqref{eq4}, we get that 
\begin{align*}
\sumstar_{\chi \pmod q} S_{j,v}(\chi)^2 & \ll q  \sum_{m \leq \frac{\beta_j \log q}{2 \log 2}} \exp \Big(v+2v(\log m+1)+ \frac{2v}{2^{m/4}(1-2^{-1/4})}\Big) \frac{1}{2^{m}} \\
& \ll q \sum_{m=0}^{\infty} \frac{m^{2v}}{2^m} \ll q,
\end{align*}
where in the last line above we used the fact that for $x<1$, we have
$$ \sum_{m=1}^{\infty} m^v x^m \leq \frac{x v!}{(1-x)^{v+1}}.$$
\qed

