\section{Proof of Theorem \ref{mol_lb}}
\label{lb}


Using Theorem \ref{thm:twisted-moment-full-orbit}, we have that

\begin{align}
& \frac{1}{|\co|} \sum_{\substack{\chi\in\co}}L(\tfrac12,\chi\eta_1)L(\tfrac12,\overline{\chi\eta_2})M(\chi\eta_1)M(\overline{\chi\eta_2}) \nonumber \\
&=  \sum_{\substack{ M= \prod_{j=0}^K m_j, \, N= \prod_{j=0}^K n_j \\ p|m_j n_j \Rightarrow p \in I_j \\ \Omega(m_j)\leq \ell_j, \, \Omega(n_j) \leq \ell_j}} \frac{ a(M;K) a(N;K) \lambda(M) \lambda(N) \nu(M) \nu(N)}{\sqrt{MN}}\nonumber\\
&\qquad\qquad\times \frac{1}{|\co|} \sum_{\substack{\chi\in\co}}L(\tfrac12,\chi\eta_1)L(\tfrac12,\overline{\chi\eta_2})\chi\eta_1(M)\overline{\chi\eta_2}(N) \nonumber \\
&= L(1,\eta)  \prod_{j=0}^K \sum_{\substack{ p |g_j m_j n_j \Rightarrow p \in I_j \\ (m_j,n_j)=1 \\ \Omega(g_j m_j) \leq \ell_j, \, \Omega(g_j n_j) \leq \ell_j}}  \frac{a^2(g_j;K) a(m_j; K) a(n_j;K) \lambda(m_j) \lambda(n_j) \nu(g_j m_j) \nu(g_j n_j) \eta(g_j m_j n_j)}{g_j m_j n_j} \nonumber \\
&\qquad\qquad +O\Big( \sum_{\substack{ M= \prod_{j=0}^K m_j, \, N= \prod_{j=0}^K n_j \\ p|m_j n_j \Rightarrow p \in I_j \\ \Omega(m_j)\leq \ell_j, \, \Omega(n_j) \leq \ell_j}} \frac{ a(M;K) a(N;K) }{\sqrt{MN}} E(M,N) \Big), \label{mol_mom}
\end{align}
with $E(M,N)$ as in Theorem \ref{thm:twisted-moment-full-orbit}, and where recall that $\eta = \eta_1 \overline{\eta_2}$. We write 
\begin{align*}
& \frac{1}{|\co|} \sum_{\substack{\chi\in\co}}L(\tfrac12,\chi\eta_1)L(\tfrac12,\overline{\chi\eta_2})M(\chi\eta_1)M(\overline{\chi\eta_2}) \nonumber \\ 
&=: \mathcal{M}+\mathcal{E},
\end{align*}
where $\mathcal{M}$ corresponds to the main term above and where $\mathcal{E}$ comes from the error term $E(M, N)$. Using Theorem \ref{thm:twisted-moment-full-orbit}, and since 
$$ \max\bigg(\frac{\log M}{\log q}, \frac{\log N}{\log q}\bigg) \leq \sum_{j=0}^K \ell_j \beta_j < 2 \beta_K^{1/4},$$
we have that
$$ \mathcal{E} \ll q^{-1/4+2\beta_K^{1/4}+\varepsilon},$$ 
recalling that 
$\beta_K$ is given in equation \eqref{condition_c} (with $v=4$). Since we can choose $c$ small enough, the error term above is negligible.


We now focus on the main term $\mathcal{M}$ in the expression \eqref{mol_mom}. For $j=0,\ldots, K$, let $T(j)$ denote term corresponding to $I_j$ in the product over $j$. 

For $j \geq 1$, we write
$$T(j) = U(j)-V(j),$$ where 
$$U(j) = \sum_{\substack{ p |g_j m_j n_j \Rightarrow p \in I_j \\ (m_j,n_j)=1 }} \frac{a(g_j;K)^2 a(m_j; K) a(n_j;K) \lambda(m_j) \lambda(n_j) \nu(g_j m_j) \nu(g_j n_j)\eta(g_j m_j n_j)}{g_j m_j n_j},$$
 and where $V_j$ corresponds to the sum over $g_j,m_j,n_j$ where at least one of $\Omega(g_j m_j)$ or $\Omega(g_j n_j)$ is greater than $\ell_j$. 
Note that we have 
\begin{align}
\label{uj}
U(j) &= \prod_{p \in I_j} \Bigg( 1 + \frac{a^2(p;K)  \eta(p)}{p} - \frac{2a(p;K) \eta(p)}{p}  + \sum_{\substack{i+j+k \geq 2 \\ jk=0}} \frac{a(p^{2i+j+k};K) (-1)^{j+k}\eta(p^{i+j+k}) }{(i+j)! (i+k)! p^{i+j+k}} \Bigg).
\end{align} 
 We also have that 
 \begin{align*}
 |T(j)| \geq |U(j)| - \frac{1}{2^{\ell_j}} \sum_{p |g_j m_j n_j \Rightarrow p \in I_j} \frac{2^{\Omega(g_j^2 m_j n_j)} }{g_j m_j n_j},
 \end{align*}
where we used the fact that $a(r;K) \leq 1$ and $\nu(r) \leq 1$, for any integer $r$. From the above it follows that
$$|T(j)| \geq |U(j)| - \frac{1}{2^{\ell_j}} \prod_{p \in I_j} \Big(1-\frac{4}{p} \Big)^{-1} \Big( 1 - \frac{2}{p} \Big)^{-2}.$$
Hence we get that
\begin{align}
\label{prod_tj}
\Big| \prod_{j=1}^K T(j)  \Big| \geq \Big| \prod_{j=1}^K U(j) \Big| \prod_{j=1}^K \Bigg(1 - \frac{1}{2^{\ell_j} |U(j)|} \prod_{p \in I_j} \Big(1-\frac{4}{p} \Big)^{-1} \Big( 1 - \frac{2}{p} \Big)^{-2} \Bigg).
\end{align}

For $j=0$, we use the fact that 
\begin{equation}
 \mathds{1}_{\Omega(b) \leq \ell_j}= \frac{1}{2 \pi i} \oint_{|z|<1} \frac{z^{\Omega(b)}}{(1-z)z^{\ell_j}}  \, \frac{dz}{z}, \label{number_primes}
 \end{equation} and then
\begin{align*}
T(0) = \frac{1}{(2 \pi i)^2}& \oint \oint \\
&\sum_{\substack{ p |g_0 m_0 n_0 \Rightarrow p \in I_0 \\ (m_0,n_0)=1 }} \frac{a^2(g_0;K) a(m_0; K) a(n_0;K) \lambda(m_0) \lambda(n_0) \nu(g_0 m_0) \nu(g_0 n_0) \eta(g_0 m_0 n_0)}{g_0 m_0 n_0}  \\
& \times \frac{z_1^{\Omega(g_0 m_0)} z_2^{\Omega(g_0 n_0)}}{(1-z_1)(1-z_2) (z_1 z_2)^{\ell_0}} \, \frac{dz_1}{z_1} \frac{dz_2}{z_2},
\end{align*}
where we are integrating along circles with $|z_1|, |z_2|<1$; say $|z_1|=|z_2|=1/2$. We have that
\begin{align*}
\sum_{\substack{ p |g_0 m_0 n_0 \Rightarrow p \in I_0 \\ (m_0,n_0)=1 }} & \frac{a^2(g_0;K) a(m_0; K) a(n_0;K) \lambda(m_0) \lambda(n_0) \nu(g_0 m_0) \nu(g_0 n_0) \eta(g_0 m_0 n_0)}{g_0 m_0 n_0}  z_1^{\Omega(g_0 m_0)} z_2^{\Omega(g_0 n_0)} \\
&= \prod_{p \in I_0} \Bigg( 1 + \frac{a^2(p;K) z_1 z_2 \eta(p)}{p} - \frac{a(p;K) z_1 \eta(p)}{p} - \frac{a(p;K) z_2 \eta(p)}{p} \\
&+ \sum_{\substack{i+j+k \geq 2 \\ jk=0}} \frac{a(p^{2i+j+k};K) (-1)^{j+k} \eta(p^{i+j+k}) z_1^{i+j} z_2^{i+k}}{(i+j)! (i+k)! p^{i+j+k}} \Bigg).
\end{align*}
In the integral over $z_1$ we shift the contour of integration to $|z_1|=3$ and encounter a pole at $z_1=1$. We note that the integral over the new contour is bounded by 
\begin{align}
\frac{1}{(3/2)^{\ell_0}} & \prod_{p \in I_0} \Big(  1+ \frac{5}{p} + \sum_{b\geq 2} \frac{3^a}{p^a a!} \sum_{i \leq a} \frac{1}{i! 2^i} + \sum_{b \geq 2} \frac{1}{(2p)^b b!} \sum_{i \leq b} \frac{3^i}{i!}\Big) \nonumber \\
& \leq \frac{1}{(3/2)^{\ell_0}} \prod_{p \in I_0}  \Big(  1+ \frac{5}{p} + 2 \sum_{b\geq 2} \frac{3^b}{p^b b!}  +\frac{e^3}{4} \sum_{b \geq 2} \frac{1}{p^b b!}\Big) \nonumber \\
& \leq \frac{1}{(3/2)^{\ell_0}} \exp \Big( \sum_{p \in I_0}  \frac{5}{p}+ 2 \sum_{b \geq 2} \frac{3^b}{b!} \sum_{p \in I_0} \frac{1}{p^b}+ \frac{e^3}{4} \sum_{b \geq 2} \frac{1}{b!} \sum_{p \in I_0} \frac{1}{p^b}  \Big) \Big) \nonumber \\
& \ll \frac{1}{(3/2)^{\ell_0}} \exp \Big( 5 \log \log q^{\beta_0} + \frac{e^3 \pi^2}{3}+ \frac{e^4 \pi^2}{24} \Big) \nonumber \\
& \ll \exp \Big( - c_0 \frac{(\log q)^{3/4}}{(\log \log q)^{3/4}} \Big),
\label{et_bd}
\end{align}
for some $c_0>0$, where we used the fact that $\ell_0 \asymp (\log q)^{3/4}/(\log \log q)^{3/4}$. We then get that
\begin{align*}
T(0) &= \frac{1}{2 \pi i} \oint \prod_{p \in I_0} \Bigg( 1 + \frac{a^2(p;K)  z_2 \eta(p)}{p} - \frac{a(p;K)  \eta(p)}{p} - \frac{a(p;K) z_2 \eta(p)}{p} \\
&+ \sum_{\substack{i+j+k \geq 2 \\ jk=0}} \frac{a(p^{2i+j+k};K) (-1)^{j+k} \eta(p^{i+j+k})  z_2^{i+k}}{(i+j)! (i+k)! p^{i+j+k}} \Bigg)  \frac{ 1}{(1-z_2) z_2^{\ell_0}} \, \frac{dz_2}{z_2}\\
