\end{align} 
Let
$$\mathcal{B} =L(1,\eta)  \prod_{p \leq q^{\beta_K}} \Bigg( 1 + \frac{a^2(p;K)  \eta(p)}{p} - \frac{2a(p;K)  \eta(p)}{p} + \sum_{\substack{i+j+k \geq 2 \\ jk=0}} \frac{a(p^{2i+j+k};K) (-1)^{j+k} \eta(p^{i+j+k}) }{(i+j)! (i+k)! p^{i+j+k}} \Bigg). $$
Let $E_p$ denote the term corresponding to $i+j+k \geq 2$ in the sum above.
Using \cite[Lemma $8.2$]{GS01} with $y=q^{\beta_K}$ and under GRH, we have that
$$ \log L(1,\eta) = \sum_{n \leq q^{\beta_K}} \frac{\Lambda(n) \eta(n)}{n \log n}  + O \Big(  (\log q)^3 q^{-\beta_K/2}\Big).$$
Hence it follows that
\begin{align*}
\log  &\mathcal{B} = \sum_{p \leq q^{\beta_K}} \frac{\eta(p)}{p} + \sum_{\substack{ p^b \leq q^{\beta_K} \\ b \geq 2}} \frac{\eta(p^b)}{b p^b} + \sum_{5\leq  p \leq q^{\beta_K}} \sum_{b=1}^{\infty} \frac{(-1)^{b+1}}{b}  \Big(\frac{a^2(p;K)  \eta(p)}{p} - \frac{2a(p;K)  \eta(p)}{p} +E_p \Big)^b \\
&+ \sum_{p \in \{2,3\}} \log \Big( 1 + \frac{a^2(p;K)  \eta(p)}{p} - \frac{2a(p;K)  \eta(p)}{p} + \sum_{\substack{i+j+k \geq 2 \\ jk=0}} \frac{a(p^{2i+j+k};K) (-1)^{j+k} \eta(p^{i+j+k}) }{(i+j)! (i+k)! p^{i+j+k}} \Big) \\
&= \sum_{5 \leq p \leq q^{\beta_K}} \frac{(1-a(p;K))^2 \eta(p)}{p} +\sum_{p \in \{2,3\}} \frac{\eta(p)}{p}+ \sum_{\substack{ p^b \leq q^{\beta_K} \\ b \geq 2}} \frac{\eta(p^b)}{b p^b}+ \sum_{5 \leq p \leq q^{\beta_K}} E_p \\
&+\sum_{5 \leq p \leq q^{\beta_K}} \sum_{b\geq 2} \frac{(-1)^{b+1}}{b}  \Big(\frac{a^2(p;K)  \eta(p)}{p} - \frac{2a(p;K)  \eta(p)}{p} +E_p \Big)^b \\
&+\sum_{p \in \{2,3\}} \log \Big( 1 + \frac{a^2(p;K)  \eta(p)}{p} - \frac{2a(p;K)  \eta(p)}{p} + \sum_{\substack{i+j+k \geq 2 \\ jk=0}} \frac{a(p^{2i+j+k};K) (-1)^{j+k} \eta(p^{i+j+k}) }{(i+j)! (i+k)! p^{i+j+k}} \Big) \\
&+   O \Big(  (\log q)^3 q^{-\beta_K/2}\Big).
\end{align*}
Exponentiating, we get that
\begin{align}
|\mathcal{B}| &= \Big(1  + O \Big(  (\log q)^3 q^{-\beta_K/2}\Big)  \Big)\exp \Bigg(  \Re \Big(\sum_{5 \leq p \leq q^{\beta_K}} \frac{(1-a(p;K))^2 \eta(p)}{p} + \sum_{p \in \{2,3\}} \frac{\eta(p)}{p}+\sum_{\substack{ p^b \leq q^{\beta_K} \\ b \geq 2}} \frac{\eta(p^b)}{b p^b} \nonumber \\
&+ \sum_{p \leq q^{\beta_K}} E_p +\sum_{p \leq q^{\beta_K}} \sum_{b=2}^{\infty} \frac{(-1)^{b+1}}{b}  \Big(\frac{a^2(p;K)  \eta(p)}{p} - \frac{2a(p;K)  \eta(p)}{p} +E_p \Big)^b \Big) \Bigg) \nonumber \\
& \times \prod_{p \in \{2,3\}}  \Big| 1 + \frac{a^2(p;K)  \eta(p)}{p} - \frac{2a(p;K)  \eta(p)}{p} + \sum_{\substack{i+j+k \geq 2 \\ jk=0}} \frac{a(p^{2i+j+k};K) (-1)^{j+k} \eta(p^{i+j+k}) }{(i+j)! (i+k)! p^{i+j+k}} \Big|. \label{b_exp}
\end{align}

Now we use the fact that
$$ 1-a(p;K) \leq \frac{(1+\lambda) \log p}{\beta_K \log q},$$ so
\begin{align}
\label{re1}
\Re \Big(\sum_{5 \leq p \leq q^{\beta_K}} \frac{(1-a(p;K))^2 \eta(p)}{p} \Big) \geq - \frac{(1+\lambda)^2}{\beta_K^2 (\log q)^2} \sum_{p \leq q^{\beta_K}} \frac{(\log p)^2}{p} \geq -(1+\lambda)^2.
\end{align}
We also have that 
\begin{align}
\Re \Big( \sum_{\substack{ p^b \leq q^{\beta_K} \\ b \geq 2}} \frac{\eta(p^b)}{b p^b} \Big) \geq -\sum_p \frac{1}{p^2-1},
\label{re2}
\end{align}
and
\begin{align}
\label{re3}
\Re \Big( \sum_{5 \leq p \leq q^{\beta_K}} E_p \Big) \geq -2 \sum_{p>3} \sum_{b \geq 2} \frac{1}{b! p^b} \sum_{i=0}^b \frac{1}{i!} \geq -2 \sum_{p \geq 5} \sum_{b \geq 2} \frac{b+1}{b! p^b} \geq - \sum_{p \geq 5}\frac{6}{p^2-1}.
\end{align} 
Furthermore, we have that 
\begin{align}
\Re & \Big(\sum_{5 \leq p \leq q^{\beta_K}} \sum_{b=2}^{\infty} \frac{(-1)^{b+1}}{b}  \Big(\frac{a^2(p;K)  \eta(p)}{p} - \frac{2a(p;K)  \eta(p)}{p} +E_p \Big)^b \Big) \Big) \nonumber \\
& \geq - \sum_{5 \leq  p \leq q^{\beta_K}} \sum_{b \geq 2} \frac{1}{b} \sum_{r=0}^b \binom{b}{r} \Big( \frac{6}{p^2-1} \Big)^{r} 
 \frac{3^{b-r}}{p^{b-r}} \nonumber \\
 & \geq - \sum_{5 \leq  p \leq q^{\beta_K}} \sum_{b \geq 2}  \frac{3^b}{b p^b} \Big(  1+ \frac{2p}{p^2-1}\Big)^b \geq - \frac{1}{2} \sum_{p \geq 5} \sum_{b \geq 2} \Big(\frac{9}{2p}\Big)^b \geq -\frac{9^2}{4p(2p-9)}.\label{re4}
\end{align}

Note that for $p=2,3$,
$$a(p;K) = 1+ O \Big( \frac{1}{\log q} \Big),$$
so
\begin{align}
\Big| &\frac{a^2(p;K)  \eta(p)}{p} - \frac{2a(p;K)  \eta(p)}{p} + \sum_{\substack{i+j+k \geq 2 \\ jk=0}} \frac{a(p^{2i+j+k};K) (-1)^{j+k} \eta(p^{i+j+k}) }{(i+j)! (i+k)! p^{i+j+k}} \Big| \leq \frac{1+\eps}{p} + \frac{3(1+\eps)}{4p^2} \nonumber \\
&+ \sum_{\substack{i+j+k \geq 3 \\ jk=0}} \frac{1 }{(i+j)! (i+k)! p^{i+j+k}} \leq \frac{1+\eps}{2} + \frac{3(1+\eps)}{16}+ 2 \sum_{b \geq 3} \frac{1}{b!2^b} \sum_{i=0}^b \frac{1}{i!} \nonumber  \\
& \leq \frac{1+\eps}{2} + \frac{3(1+\eps)}{16} + 2 \sum_{b \geq 3} \frac{b+1}{b! 2^b} \leq  \frac{1+\eps}{2} + \frac{3(1+\eps)}{16} + 2 \Big( \frac{1}{12}+ \frac{5}{24\cdot 16} + \frac{6}{5! 2^4} \Big) \nonumber \\
& \leq \frac{86}{96}. \nonumber 
\end{align}
It follows that
\begin{align}
\label{re5}
\Big| 1 + \frac{a^2(p;K)  \eta(p)}{p} - \frac{2a(p;K)  \eta(p)}{p} + \sum_{\substack{i+j+k \geq 2 \\ jk=0}} \frac{a(p^{2i+j+k};K) (-1)^{j+k} \eta(p^{i+j+k}) }{(i+j)! (i+k)! p^{i+j+k}} \Big| \geq \frac{5}{48}.
\end{align}



Now using equations \eqref{b_exp}, \eqref{re1}, \eqref{re2}, \eqref{re3}, \eqref{re4}, \eqref{re5}, it follows that 
\begin{align*}
|\mathcal{B} | & \geq \Big(1  + O \Big(  (\log q)^3 q^{-\beta_K/2}\Big)  \Big) \Big(  \frac{5}{48}\Big)^2 \exp \Big(  - \frac{5}{6}- (1+\lambda)^2 - 7 \sum_p \frac{1}{p^2-1} -\sum_{p \geq 5}  \frac{9^2}{4p(2p-9)}\Big) \\
& \geq \Big(1  + O \Big(  (\log q)^3 q^{-\beta_K/2}\Big)  \Big) \Big(  \frac{5}{48}\Big)^2 \exp \Big(  -\frac{5}{6}- (1+\lambda)^2  - (14+ \tfrac{3}{2} \cdot 9^2) \sum_p \frac{1}{p^2} \Big) \\
& \gg 1.
\end{align*}
Using the above and equation \eqref{intermediary}, we get that
\begin{equation}
|\mathcal{M}| \gg 1.
\end{equation}
This completes the proof of the theorem.


\section{Proof of Theorem \ref{thm:nonvanishing-full-orbit} }

H\"{o}lder's inequality implies that
\begin{align}\label{HI}
&\bigg(\sum_{\substack{\chi\in\co\\L(1/2,\chi\eta_1)L(1/2,\chi\eta_2)\ne0}}1\bigg)^2\bigg(\sum_{\substack{\chi\in\co}}|L(\tfrac12,\chi\eta_1)M(\chi\eta_1)|^4\bigg)\bigg(\sum_{\substack{\chi\in\co}}|L(\tfrac12,\chi\eta_2)M(\chi\eta_2)|^4\bigg)\nonumber\\
&\qquad\qquad\geq \bigg(\sum_{\substack{\chi\in\co}}L(\tfrac12,\chi\eta_1)L(\tfrac12,\overline{\chi\eta_2})M(\chi\eta_1)M(\overline{\chi\eta_2})\bigg)^4.
\end{align}
By positivity,
\begin{align*}  
\sum_{\substack{\chi\in\co}}|L(\tfrac12,\chi\eta_1)M(\chi\eta_1)|^4\leq \sumstar_{\chi(\text{mod}\ q)}|L(\tfrac12,\chi)M(\chi)|^4.
\end{align*} 
Using Theorem \ref{mol_ub} with $v=4$, we have that
$$\sumstar_{\chi(\text{mod}\ q)}|L(\tfrac12,\chi)M(\chi)|^4 \ll q, $$ 
and since $|\co|\asymp q$, we obtain from \eqref{HI} that
\begin{equation}
\label{lbmol}
\frac{1}{|\co|}\sum_{\substack{\chi\in\co\\L(1/2,\chi\eta_1)L(1/2,\chi\eta_2)\ne0}}1\geq \bigg(\frac{1}{|\co|}\,\sum_{\substack{\chi\in\co}}L(\tfrac12,\chi\eta_1)L(\tfrac12,\overline{\chi\eta_2})M(\chi\eta_1)M(\overline{\chi\eta_2})\bigg)^2.
\end{equation}
Using Theorem \ref{mol_lb} finishes the proof.
\qed



