    \end{multlined}\\
    &=S_{k+1}+\sum_{i=1}^{k+1}a^ib^i\sum_{j=1}^{i}(-1)^{j+1}\binom{k+1}{j}\binom{k+1-j}{i-j}S_{k+1-i}.
\intertext{Now using Lemma \ref{ml1} substituting the value of $$\sum_{j=1}^{i}(-1)^{j+1}\binom{k+1}{j}\binom{k+1-j}{i-j}=\binom{k+1}{i},$$ we obtain}
&=S_{k+1}+\sum_{i=1}^{k+1}a^ib^i\binom{k+1}{i}S_{k+1-i}\\
&=\sum_{i=0}^{k+1}a^ib^i\binom{k+1}{i}S_{k+1-i}.
    \end{align*}

