\begin{align*}
        2abS_{1}&=\begin{multlined}[t]
            \sum_{\substack{0\leq a_1 \leq b-1 \\ 0\leq b_1 \leq a-1}} (aa_1+bb_1)^2-2ab\sum_{j=1}^{1}\binom{1}{j}a^{j}b^{j}S_{1-j} \\[2ex]+\sum_{i=2}^{2}(-1)^{i}\binom{2}{i}a^{i}b^{i}\sum_{j=0}^{2-i}\binom{2-i}{j}a^{j}b^{j}S_{2-i-j}-\frac{1}{3}\sum_{j=0}^{2}\binom{3}{j}B_{j}(ab-1)^{3-j}  
         \end{multlined}\\
         &=\sum_{\substack{0\leq a_1 \leq b-1 \\ 0\leq b_1 \leq a-1}} (aa_1+bb_1)^2-2a^2b^2S_{0}+a^2b^2S_{0}-\frac{1}{3}B_0(ab-1)^3-B_1(ab-1)^2\\&\quad\quad-B_2(ab-1).\\
         \intertext{Using Equation \eqref{IBN} substituting the values $B_0, B_1$ and $B_2$, we obtain}
         &=a^2\sum_{\substack{0\leq a_1 \leq b-1 \\ 0\leq b_1 \leq a-1}} a_{1}^2+2ab\sum_{\substack{0\leq a_1 \leq b-1 \\ 0\leq b_1 \leq a-1}} a_{1}b_1+b^2\sum_{\substack{0\leq a_1 \leq b-1 \\ 0\leq b_1 \leq a-1}} b_{1}^2-a^2b^2S_{0}-\frac{1}{3}(ab-1)^3\\&\quad \quad \quad -\frac{1}{2}(ab-1)^2 -\frac{1}{6}(ab-1)\\
         &=a^3\sum_{0\leq a_1 \leq b-1}a_{1}^2+a^2b(a-1)\sum_{0\leq a_1 \leq b-1}a_{1}+b^3\sum_{0\leq b_1 \leq a-1}b_{1}^2-a^2b^2S_{0}\\&\quad\quad\quad-\frac{1}{6}ab(ab-1)(2ab-1)\\
             &=\frac{1}{6}a^3b(b-1)(2b-1)+\frac{1}{2}a^2b^2(a-1)(b-1)+\frac{1}{6}b^3a(a-1)(2a-1)-a^2b^2S_{0}\\ &\quad \quad \quad -\frac{1}{6}ab(ab-1)(2ab-1)\\
              &=\frac{1}{6}a^3b(b-1)(2b-1)+a^2b^2S_0+\frac{1}{6}b^3a(a-1)(2a-1)-a^2b^2S_{0}\\&\quad\quad\quad-\frac{1}{6}ab(ab-1)(2ab-1)\\
         &=\frac{1}{6}a^3b(b-1)(2b-1)+\frac{1}{6}b^3a(a-1)(2a-1)-\frac{1}{6}ab(ab-1)(2ab-1).
          \intertext{That is,}
S_1&=\frac{1}{12}a^2(b-1)(2b-1)+\frac{1}{12}b^2(a-1)(2a-1)-\frac{1}{12}(ab-1)(2ab-1)\\
&=\frac{1}{12}(a-1)(b-1)(2ab-a-b-1).
             \end{align*}
        \end{proof}

\section{Proof of Theorem \ref{DNM1}}
\label{sec2}
 \begin{proof}
   Let $m$ be a number expressed as $ax+by$ for nonnegative integers $x$ and $y$. Without loss of generality, we can assume that $0\leq y <a$. Substituting $b=aq_0+r_0$, we have,
\begin{equation*}
    m=ax+(aq_0+r_0)y.
\end{equation*}
That is, 
\begin{equation}
\label{my}
    m=a(x+q_0y)+r_0y.
\end{equation}
Choose the smallest $0\leq k_m<r_0$ such that $0\leq r_0y-k_ma<a$. Then, Equation \eqref{my} can be written as 
\begin{equation*}
m=a(x+q_0y+k_m)+(r_0y-k_m a).
\end{equation*}

Note that by the division algorithm, there exist unique nonnegative integers $q$ and $r$ such that $m=aq+r$, where $0\leq r<a$. It follows that,
\begin{equation*}
    q=x+q_{0}y+k_{m} \hspace{0.4cm}\text{and} \hspace{0.4cm} r=r_{0}y-k_{m}a.
\end{equation*}
Solving for $x$ gives us
\begin{equation*}
    x=q-\frac{q_{0}r+k_{m}(aq_{0}+r_{0})}{r_{0}}.
\end{equation*}
Since $x\geq 0$, it follows that 
\begin{equation*}
     q\geq\frac{q_{0}r+k_{m}(aq_{0}+r_{0})}{r_{0}}.
\end{equation*}
Substituting $r=m-aq$, we obtain
\begin{equation*}
\begin{split}
 q&\geq \frac{q_{0}(m-aq)+k_{m}(aq_{0}+r_{0})}{r_{0}}\\
 &= \frac{q_{0}m-q_{0}aq+k_{m}(aq_{0}+r_{0})}{r_{0}}.\\
 \end{split}
\end{equation*}
That is,
\begin{equation*}
    q(aq_0+r_0)\geq q_0m+k_m(aq_0+r_0).
    \end{equation*}
    Solving further, we get
    \begin{equation*}
    \begin{split}
     q & \geq  q_{0}\frac{m}{aq_{0}+r_{0}}+k_{m}\\
&= q_{0}\frac{m}{b}+k_{m}.
   \end{split} 
\end{equation*}
    Since $q=\lfloor \frac{m}{a} \rfloor$, we obtain the following inequality:
 \begin{equation*}
   \left\lfloor \frac{m}{a} \right\rfloor \geq q_{0}\frac{m}{b}+k_{m}.
    \end{equation*}

Finally, note that if $r\equiv r_m$ (mod $r_0$) for some $0\leq r_m <r_0$, and since $r=r_0y-k_m a$, it follows that $-k_ma\equiv r_m$ (mod $r_0$). Therefore, $k_m\equiv -a_{r_0}^{-1}r_m$ (mod $r_0$).
Thus, the result holds.

Conversely, let $\lfloor \frac{m}{a}\rfloor \geq q_{0}\frac{m}{b}+k_{m}$, where $k_{m}$ is the same as defined earlier. Note that
\begin{equation*}
    \begin{split}
   \left \lfloor \frac{m}{a} \right\rfloor &\geq q_{0}\frac{m}{b}+k_{m}, \\
     q &\geq q_{0}\frac{m}{aq_{0}+r_{0}}+k_{m}, \\
     q(aq_{0}+r_{0}) &\geq q_{0}m+k_{m}(aq_{0}+r_{0}), \\
     q(aq_{0}+r_{0}) &\geq q_{0}(aq+r)+k_{m}(aq_{0}+r_{0}), \\
     qr_{0} &\geq q_{0}r+k_{m}(aq_{0}+r_{0}), \\
     q &\geq \frac{q_{0}r+k_{m}(aq_{0}+r_{0})}{r_0}.
      \end{split}
\end{equation*}

Further, note that
\begin{equation*}
    \frac{q_{0}r+k_{m}(aq_0+r_0)}{r_0}= \frac{q_{0}(r+k_{m}a)+k_{m}r_0}{r_0}.
\end{equation*}
Since $-ak_{m}\equiv r_m$(mod$r_0$) and $r\equiv r_m$ (mod$r_0$), it follows that $k_{m}a+r$ is divisible by $r_0$. Hence,
$$ \frac{r+k_{m}a}{r_0}, \frac{q_{0}(r+k_{m}a)+k_{m}r_0}{r_0} \in \mathbb{N}.$$
Now rewrite $m$ as follows
\begin{equation*}
\begin{split}
    m&=a\left( q-\frac{q_{0}r+k_{m}(aq_0+r_0)}{r_0}\right)+(aq_{0}+r_{0})\left(\frac{r+k_{m}a}{r_0}\right)\\
    &=a\left( q-\frac{q_{0}r+k_{m}(aq_0+r_0)}{r_0}\right)+b\left(\frac{r+k_{m}a}{r_0}\right)\\
    &=a\left( q-\frac{q_{0}(r+k_{m}a)+k_{m}r_0}{r_0}\right)+b\left(\frac{r+k_{m}a}{r_0}\right).
    \end{split}
\end{equation*}
Now take
\begin{equation*}
    x=\left( q-\frac{q_{0}(r+k_{m}a)+k_{m}r_0}{r_0}\right) \text{and}\ y=\left(\frac{r+k_{m}a}{r_0}\right),
\end{equation*}
we have
$$m=ax+by, \text{ where $x$ and $y$ are nonnegative integers}.$$
\end{proof}   

\section{Concluding Remarks}
In this article, we obtain a formula for calculating the power sum of nonrepresentable numbers in terms of $a$ and $b$, where $\gcd(a,b)=1$. The key result we use is the formula for the number of nonnegative integer solutions of the Diophantine equation $ax+by=n$, where $\gcd(a,b)=1$, given by Binner \cite{D19}. A natural question to ask is whether this result can be generalized to nonrepresentable numbers in terms of three variables $a$, $b$, and $c$, where $\gcd(a,b,c)=1$. In light of our proof technique, one may hope to use the formula for the number of nonnegative integer solutions of the Diophantine equation in three variables $ax+by+cz=n$, where $\gcd(a,b,c)=1$, also given by Binner \cite{D19}.

