\begin{definition}[Definition 5.3, \cite{Colbert}]
    Let $X$ and $Y$ and be posets, and let $g : X \longrightarrow Y $ be a surjective poset map. If $Z$ is a poset and $h : X \longrightarrow Z$ is any poset map, we say $h$ is \emph{compatible} with $g$ if, for each $y \in Y$, the restriction of $h$ to $g^{-1}(y)$ is constant.
\end{definition}
\begin{definition}
[Definition 2.5, \cite{Colbert}]     If $C\subseteq Y$ is a subposet of $Y$, we say that $C$ is a \emph{complete subset} of $Y$ if for all $u,v\in C$, if $u \leq y \leq v$ for some $y \in Y$, then $y \in C$.
\end{definition}
\begin{definition}[Definition 5.4, \cite{Colbert}]
    Let $X$ be a poset. We say that the poset $Y$ is a \emph{gluing} of $X$ with gluing map $g:X
    \longrightarrow Y$ if whenever $h:X\longrightarrow Z$ is compatible with $g$, there exists a unique poset map $\varphi:Y\longrightarrow Z$ such that $\varphi \circ g = h$. Moreover, if $C \subseteq X$ is a complete subset of $X$ such that:
    \begin{enumerate}[(i)]
        \item $g$ is constant on $C$, and
        \item if $g(x) = g(x')$ for distinct $x,x' \in X$, then both $x,x' \in C$,
    \end{enumerate}
    then we say $Y$ is a gluing of $X$ along $C.$
\end{definition}
The following theorem from \cite{Colbert} shows that there is a gluing of a poset along any given complete subset. Moreover, the theorem provides a useful property of gluings along the given complete subset. 

 \begin{theorem}[Theorem 5.7, \cite{Colbert}]\label{theorem about order induced by gluings}
 If $(X,\leq)$ is a poset and $S$ is a complete subset of $X$, then there is a gluing $Y$ of $X$ along $S$. Moreover, if $Z$ is a gluing of $X$ along $S$ via any gluing map $h : X \longrightarrow Z$, then whenever $h(x)\leq_Z h(y)$, either $x\leq_X y$ or there exists $s,t \in S$ such that $x\leq_Xs$ and $t\leq_X y$.
 \end{theorem}

As is the case in \cite{Colbert}, we will primarily focus on gluing along a subset of minimal nodes of our poset. The following definitions and lemmas make this idea precise and show useful properties of height zero gluings. Note that for a poset $X$, any subset of $\min X$ is a complete subset of $X$.
\begin{definition}[Definition 5.9, \cite{Colbert}]
    If $Y$ is a gluing of $X$ along a subset $C \subseteq \min X$, we say that $Y$ is a \emph{height zero gluing} of $X.$
\end{definition}
\begin{lemma}[Lemma 5.10, \cite{Colbert}]\label{gluing preserves dimension}
    If $Y$ is a height zero gluing of a finite poset $X$ along $C$ with gluing map $g$, then the following statements are true:
    \begin{enumerate}
        \item $g(\min X)=\min Y$,
        \item $\dim(X)=\dim(Y)$, and
        \item if $g(x) <_c g(y)$, there exists $x' \in X$ such that $x' <_c y$ and $g(x') = g(x)$.
    \end{enumerate}
\end{lemma}
In Section $\ref{quasi-excellent ring construction}$, we introduce a stronger notion of dimension-preserving saturated embeddings, which we call coheight-preserving saturated embeddings. The idea behind this concept is the following: given a Noetherian ring $R$, there are finitely many minimal prime ideals $\{P_1,\dots,P_n\}$ of $R$ and so we can consider the coheight of $P_i$ for each $i=1,\dots,n$. We translate this idea to posets and we then introduce poset maps that preserve coheight at the minimal nodes. The following definitions are essential for making this coheight-preserving property rigorous, as they provide a poset analogue of the coheight of a minimal prime ideal of a ring.
\begin{definition}
    Let $X$ be a poset of dimension $n \geq 2$, and let $x \in X$. The \emph{up set} of $x$, denoted as $x_X^{\uparrow}$, is the induced poset of $X$ given by $$x_X^{\uparrow}=\{y \in X \mid x \leq y \}$$
    where $y \leq z$ in $x_X^{\uparrow}$ if and only if $y \leq z$ in $X$. When the underlying poset is clear, we simply write $x^{\uparrow}$ to denote the up set of $x$ in $X$.
\end{definition}
\begin{lemma}\label{dimension of gluing poset}
    Let $X$ be a finite poset with a unique maximal node. Suppose $Y$ is a height zero gluing of $X$ along $C$ with gluing map $g$. Let $x_0$ be a minimal node of $X$. Then, $\dim(g(x_0)^{\uparrow}_Y)=\text{max}\{\dim(x_X^{\uparrow})\mid g(x)=g(x_0)\}$
\end{lemma}
\begin{proof}
    Suppose $\dim(g(x_0)_Y^\uparrow)=m$ and $\text{max}\{\dim(x_X^{\uparrow})\mid g(x)=g(x_0)\}=n$. Since $g$ is surjective, there are elements $x_1, \ldots ,x_m$ of $X$ such that $g(x_0)<_cg(x_1)<_c\dots<_c g(x_m)=g(x_M)$ where $x_M$ is the maximal node of $X$. Since $g$ is a height-zero gluing, $x_i<_c x_{i+1}$ for all $i=1,\dots,m-1$. Thus, we focus on $g(x_0)<_cg(x_1)$. By Lemma $\ref{gluing preserves dimension}$, there exists $\mathbf{x} \in X$ such that $\mathbf{x}<_c x_1$ and $g(\mathbf{x})=g(x_0)$. So, $\mathbf{x}<_c x_1<_c\dots<_c x_M$ is a saturated chain of length $m$ in $X$. Hence, $\dim(\mathbf{x}_X^\uparrow) \geq m$ and so $n \geq m$. 

    Now, assume that $\mathbf{x}$ is a minimal node of $X$ such that $g(\mathbf{x})=g(x_0)$ and $\dim(\mathbf{x}_X^\uparrow)=n$. Let $\mathbf{x}<_c x_1<_c\dots<_c x_n= x_M$ be a saturated chain of length $n$ in $X$. We claim that its image in $Y$ under $g$ has length at least $n$. Since $g$ is a poset map, $g(\mathbf{x}) \leq g(x_1) \leq \dots \leq g(x_n) = g(x_M).$ If for some $i = 1,\dots, n-1$, $g(x_i)= g(x_{i+1})$, then by the properties of gluing maps, $x_i,x_{i+1} \in C \subseteq \min X$, which is a contradiction. By the same argument, $g(\mathbf{x}) = g(x_1)$ implies $x_1 \in \min X$, which is also a contradiction. Thus, $g(x_0) = g(\mathbf{x}) < g(x_1) < \dots < g(x_n) = g(x_M).$ Hence, $n \leq m$ and it follows that
\[
g(x_0)_Y^\uparrow= \max\{\dim(x_X^{\uparrow})\mid g(x)=g(x_0)\}.\] \end{proof}   



