We next state two important results from \cite{Colbert}, along with specific commentary about the parts of their proofs that will be useful later. In particular, Theorem \ref{retraction and ring} shows that if $X$ and $Z$ are finite posets, $X$ is a retraction of $Z$, $B$ is a ring satisfying some nice properties and there is a saturated embedding from $X$ to $\Spec(B)$, then one can find a ring $S$ satisfying some nice properties such that there is a saturated embedding from $Z$ to $\Spec(S)$.  Theorem \ref{height zero gluing theorem} is the analogous result for height zero gluings.

\begin{theorem}[Theorem 6.2, \cite{Colbert}]\label{retraction and ring}
    Let $X$ and $Z$ be finite posets, and suppose that $X$ is a retraction of $Z.$ Let $B$ be a reduced local ring containing the rationals with $|B| = |B/M| = c$. Suppose $\psi : X \longrightarrow \spec(B)$ is a saturated embedding such that $\psi(\min X) = \Min(B)$. Then there exists a local ring S such that
     \begin{enumerate}
     \item  $S$ is reduced,
     \item $S$ contains the rationals,
     \item If $N$ is the maximal ideal of $S$, then $|S| = |S/N| = c$,
     \item There is a saturated embedding $\phi : Z \longrightarrow \spec (S)$ such that $\phi(\min Z ) = \Min(S)$.   
 \end{enumerate}
Moreover, if $B$ is quasi-excellent, then so is $S$.
\end{theorem}
\begin{remark}\label{remark about retraction and poset}
Let $X, Z, B$, and $S$ be as in Theorem \ref{retraction and ring}. Then, since $X$ is a retraction of $Z$, we have $X = Z \setminus D_p$, where $p$ is a simple node in $Z$ and $D_p =\{u \in Z : u <_c p\}$. Let $\min X = \{p, x_2, \dots, x_n\}$ and let $D_p = \{q_1, \dots, q_m\}$. Since $\psi(\min X) = \Min(B)$, we may write $\Min(B) = \{\psi(p) := P_1, \psi(x_2) := P_2, \dots, \psi(x_n) := P_n\}$.

The ring $S$ in Theorem \ref{retraction and ring} is constructed by applying Theorem \ref{the growing theorem} to $B$. Explicitly, we have $S = B[[y,z]]/J$ for the ideal $J$ described in Theorem \ref{the growing theorem}. The minimal prime ideals of $S$ are given by $$\Min(S) = \{Q_1/J, \dots, Q_m/J, P_2'/J, \dots, P_n'/J\},$$ where for each $i = 2, \dots, n$ and $j = 1, \dots, m$, $P_i' = (P_i, y, z)$ and $Q_j=(P_1,y+\beta_jz)$ where $\beta_1, \beta_2, \ldots ,\beta_m$ are distinct nonzero rationals. 
% . Furthermore, for each $j = 1, \dots, m$ and each $i = 2, \dots, n$, the inclusion $Q_j/J \subseteq P_i'/J$ holds if and only if $i = 1$, and $P_1'/J$ is a height-one prime ideal of $S$. 
Moreover, the saturated embedding $\phi: Z \longrightarrow \spec(S)$ is explicitly defined by:
   \[
\phi(x) = \begin{cases} 
       (\psi(x), y, z)/J & x \in X, \\
       Q_i/J & x=q_i \in D_p.
   \end{cases}
\]


\end{remark}


\begin{theorem}[Theorem 6.4, \cite{Colbert}]\label{height zero gluing theorem}
    Let $Z$ be a nonempty finite poset, and let $Y$ be a height zero gluing of $Z$. Let $(S, M)$ be a reduced local ring containing $\Q$ such that $S/M$ is uncountable and $|S| = |S/M|$. Suppose $\psi : Z \longrightarrow \spec(S)$ is a saturated embedding such that $\psi(\min Z) = \Min(S)$. Then there exists a reduced local ring $B \subseteq S$ with maximal ideal $B \cap M$ such that:
         \begin{enumerate}
     \item $B$ contains $\Q$,
     \item $\widehat{B}=\widehat{S}$,
     \item $B/(B \cap M )$ is uncountable, $|B| = |B/(B \cap M )|$, and
     \item There is a saturated embedding $\varphi : Y \longrightarrow \spec (B)$ such that $\varphi(\min Y ) = \Min(B)$.   
 \end{enumerate}
Moreover, if $S$ is quasi-excellent, then so is $B$.
\end{theorem}
\begin{remark}\label{remark about properties of height zero gluing}
The ring $B$ in Theorem \ref{height zero gluing theorem} is constructed by applying Theorem \ref{gluing theorem} to a partition of $\Min(S)$ induced by the map $\psi$. More precisely, let $g$ denote the gluing map from $Z$ to $Y$ along $C \subseteq \min Z$. If $C$ is empty, then $B = S$. If $C = \min Z$, we define the partition as $\mathcal{P} = \{\psi(C)\} = \{\psi(\min Z)\}$. Otherwise, we set $\mathcal{P} = \{\psi(C)\} \cup \{\{\psi(x)\} \mid x \in \min Z \setminus C\}$. By applying Theorem \ref{gluing theorem} to this partition, we ensure that the map $ f : \spec(S) \to \spec(B)$ given by $f(P) = P \cap B, $ is surjective and satisfies $f(P)S = P $ for every prime ideal $P$ of $S$ of positive height. Finally, it is shown that the composition $f \circ \psi$ is compatible with $g$. Consequently, $\varphi$ is the unique poset map that satisfies the identity $ f \circ \psi = \varphi \circ g. $

\end{remark}

In \cite{Colbert}, the authors use Theorem \ref{every finite poset reduced to a point}, Theorem \ref{retraction and ring}, and Theorem \ref{height zero gluing theorem} to prove the following result. The goal of Section \ref{quasi-excellent ring construction} in this paper is to prove a stronger form of Theorem \ref{theorem 6.5 in colbert} (see Theorem \ref{local quasi-excellent ring codimension preserving theorem}).

\begin{theorem}[Theorem 6.5, \cite{Colbert}]\label{theorem 6.5 in colbert}
     If $X$ is a finite poset, then there exists a local domain $(B,M)$ and a saturated embedding $\Psi : X \longrightarrow \spec(B)$ such that:
     \begin{enumerate}[(i)]
     \item $B$ contains $\Q,$
     \item $|B| = |B/(B \cap M )|=c$, and
     \item $B$ is quasi-excellent.
     \end{enumerate}
\end{theorem}

\section{Local Quasi-Excellent Ring Construction}\label{quasi-excellent ring construction}

In this section, we generalize Theorem \ref{theorem 6.5 in colbert} in the following way. Let $Y$ be a finite poset with exactly one maximal element. In Theorem \ref{local quasi-excellent ring codimension preserving theorem}, we show that there is a quasi-excellent local ring $S$ and a saturated embedding $\Psi : Y \longrightarrow \Spec(S)$ such that $\Psi(\min Y) = \Min(S)$.  Moreover, if $P$ is a minimal prime ideal of $S$, then there is a minimal element $z$ of $Y$ such that $\Psi(z) = P$ and the coheight of $\Psi(z)$ is the same as the dimension of $z^{\uparrow}_Y$. In other words, there is a one-to-one correspondence between the minimal elements of $Y$ and the minimal prime ideals of $S$ and, for every minimal element $z$ of $Y$, the longest chain from $z$ to the maximal element of $Y$ is the same as the longest chain of prime ideals from $\Psi(z)$ to the maximal ideal of $S$.
 Theorem $\ref{local quasi-excellent ring codimension preserving theorem}$ establishes an important step in proving Theorem~$\ref{main theorem of characterization of embeddings of UFDs}$, the main result of this paper.


Our proof strategy for Theorem \ref{local quasi-excellent ring codimension preserving theorem} is to adjust the construction of the quasi-excellent ring $B$ and the saturated embedding $\Psi: X \longrightarrow \spec(B)$ in Theorem~$\ref{theorem 6.5 in colbert}$ so that $\Psi$ satisfies our additional desired properties. We begin with an important definition.


\begin{definition}
    Let $R$ be a Noetherian ring, and let $D \subseteq \spec(R)$. Let $X$ be a poset and let $\varphi: X \longrightarrow \spec(R)$ be a saturated embedding. We say $\varphi$ is a \emph{coheight-preserving saturated embedding} along $D$ if for every $P \in D$, there is an element $x \in X$ with $\varphi(x)=P$ and $\dim(R/P)=\dim(x_X^{\uparrow})$. 
\end{definition}

\begin{lemma}\label{MinsgotoMins}
Let $R$ be a Noetherian ring, $X$ a finite poset and $D = \Min(R)$.  Suppose $\phi : X \longrightarrow \Spec(R)$ is a coheight-preserving saturated embedding along $D$.  Then $\phi(\min X) = \Min(R)$.
\end{lemma}

\begin{proof}
Suppose $P \in \Min(R)$. Then there exists $x \in X$ with $\phi(x) = P$.  Let $x_0$ be an element of $\min X$ with $x_0 \leq x$. As $\phi$ is a poset map, $\phi(x_0) \subseteq \phi(x) = P$. Since $P$ is a minimal prime ideal of $R$, we have $\phi(x_0) = \phi(x)$ and so since $\phi$ is a poset embedding, $x_0 = x$. It follows that $x \in \min X$ and we have $\Min(R) \subseteq \phi(\min X)$. 

Suppose $y \in \min X$. Then there is a minimal prime ideal $P$ of $R$ such that $P \subseteq \phi(y)$. Now, there exists $x \in X$ with $\phi(x) = P$. Since $\phi$ is a poset embedding and $\phi(x) \subseteq \phi(y)$, we have $x \leq y$. As $y$ is a minimal element of $X$, $x = y$ and so $\phi(y) = \phi(x) = P$. Thus $\phi(\min X) \subseteq \Min(R)$ and the result follows.
\end{proof}

\begin{remark}\label{remark about dimension and codimension preserving}
Let $R$ be a Noetherian ring, $X$ a finite poset and $D = \Min(R)$.  Suppose $\phi : X \longrightarrow \Spec(R)$ is a coheight-preserving saturated embedding along $D$. By Lemma \ref{MinsgotoMins}, $\phi(\min X) = \Min(R)$ and so we can write $\min X = \{x_1,\dots,x_n\}$ and correspondingly $\Min(R) = \{P_1 := \psi(x_1), \dots, P_n := \psi(x_n)\}$. Now,
$$
\dim(R) = \max\{\dim(R/P_1), \dots, \dim(R/P_n)\}.
$$
By the coheight-preserving property, we obtain
$$
\dim(R) = \max\{\dim(x{_1}^{\uparrow}_X), \dots, \dim(x{_n}^{\uparrow}_X)\} = \dim(X),
$$ and it follows that $\phi$ is a dimension-preserving saturated embedding.
\end{remark}

