  We now present two lemmas that are crucial in the proof of Theorem $\ref{local quasi-excellent ring codimension preserving theorem}$.  The first lemma is a generalization of Theorem $\ref{height zero gluing theorem}$ and the second is a generalization of Theorem $\ref{retraction and ring}$. 

\begin{lemma}\label{codimension preserving gluing thm}
    Let $Z$ be a finite poset with a unique maximal element, and let $Y$ be a height zero gluing of $Z$. Let $(S, M)$ be a reduced local ring containing $\Q$ such that $S/M$ is uncountable and $|S| = |S/M|$. Suppose $\psi : Z \longrightarrow \spec(S)$ is a coheight-preserving saturated embedding along $\Min(S)$. Then there exists a reduced local ring $B \subseteq S$ with maximal ideal $B \cap M$ such that:
         \begin{enumerate}
     \item\label{condition 1 codimension preserving gluing thm} $B$ contains $\Q$,
     \item $\widehat{B}=\widehat{S}$,
     \item \label{condition 3 codimension preserving gluing thm}$B/(B \cap M )$ is uncountable, $|B| = |B/(B \cap M )|$, and
     \item there is a coheight-preserving saturated embedding $\phi : Y \longrightarrow \spec (B)$ along $\Min(B)$.
 \end{enumerate}
Moreover, if $S$ is quasi-excellent, then so is $B$.
\end{lemma}
\begin{proof}
 By Theorem \ref{height zero gluing theorem} and Remark $\ref{remark about properties of height zero gluing}$, there exists a reduced local ring $B \subseteq S$ obtained from Theorem \ref{gluing theorem} that satisfies conditions \ref{condition 1 codimension preserving gluing thm}--\ref{condition 3 codimension preserving gluing thm} and satisfies the property that if $S$ is quasi-excellent, then so is $B$. Moreover, there is a saturated embedding $\phi : Y \longrightarrow \spec(B)$ such that the following diagram commutes:
 \begin{equation}\label{commutative diagram height zero gluing}
\begin{tikzcd}
	{{\spec(S)}} && {{\spec(B)}} \\
	\\
	Z && Y
	\arrow["f", from=1-1, to=1-3]
	\arrow["\psi", from=3-1, to=1-1]
	\arrow["g"', from=3-1, to=3-3]
	\arrow["\phi"', from=3-3, to=1-3]
\end{tikzcd}
 \end{equation}
Here, $g$ is the gluing map from $Z$ to $Y$, and the map $f$, defined by $f(P)=P \cap B$, is surjective. It remains to show that $\phi$ is coheight-preserving along $\Min (B)$.


 Fix $\mathfrak{p}_0 \in \Min(B)$ and suppose that $\dim(B/\mathfrak{p}_0)=n$. By Lemma $\ref{lifting chaing from B to S}$, there exists $P_0 \in \Min(S)$ with $\dim(S/P_0) = n$ and $P_0 \cap B=\mathfrak{p}_0$. Since $\psi$ is coheight-preserving along $\Min(S)$, there exists $z_0 \in Z$ with $\psi(z_0)=P_0$ and $\dim(z{_0}_Z^{\uparrow}) = \dim(S/P_0) = n$. By Lemma \ref{MinsgotoMins}, $\psi(\min Z) = \Min(S)$. Since $\psi$ is injective, $z_0$ is a minimal element of $Z$. Define $y_0 = g(z_0)$. We claim that $\phi(y_0) = \mathfrak{p}_0$ and $\dim(y{_0}_Y^{\uparrow}) = \dim(B/\mathfrak{p}_0)$. Suppose $\dim(y{_0}_Y^{\uparrow}) = m$. Because $g$ is surjective, there is a saturated chain in $Y$ of length $m$ given by
 \begin{equation}\label{saturated chain in Y}
   g(z_0)<_c g(x_1)<_c\dots<_cg(z_m)=g(z)
 \end{equation}
 where $z$ is the unique maximal node of $Z$.  By commutativity of diagram (\ref{commutative diagram height zero gluing}), we have $\phi(g(z_0))=f(\psi(z_0))=f(P_0)=P_0 \cap B=\mathfrak{p}_0$, and so $\phi(y_0) = \mathfrak{p}_0$. Since $\phi$ is a saturated embedding, the image of chain ($\ref{saturated chain in Y}$) in $\spec(B)$ is a saturated chain of length $m$ starting at $\mathfrak{p}_0$. Thus, $\dim(B/\mathfrak{p}_0) = n \geq m$. On the other hand, by Lemma $\ref{dimension of gluing poset}$, $\dim(g(z{_0})_Y^{\uparrow})=\text{max}\{\dim(z_Z^{\uparrow})\mid g(z)=g(z_0)\} \geq \dim(z{_0}_Z^{\uparrow})=n$. Thus, $m \geq n$, implying that $m = n$. Hence, $\phi(y_0)=\mathfrak{p}_0$ and $\dim(B/\mathfrak{p}_0) = \dim(y{_0}_Y^{\uparrow})$ as claimed. It follows that $\phi$ is coheight-preserving along $\Min (B)$.
 \end{proof}






\begin{lemma}\label{retraction lemma for quasi-excellent ring}
    Let $X$ and $Z$ be finite posets, and suppose $X$ is a retraction of $Z.$ Let $B$ be a reduced local ring containing the rationals with $|B| = |B/M| = c$. Suppose $\psi : X \longrightarrow \spec(B)$ is a coheight-preserving saturated embedding along $\Min(B)$. Then there exists a local ring S such that
     \begin{enumerate}
     \item\label{condition 1 in retraction codimension preserving}  $S$ is reduced,
     \item $S$ contains the rationals,
     \item\label{condition 3 in retraction codimension preserving} if $N$ is the maximal ideal of $S$, then $|S| = |S/N| = c$, and
     \item there is a coheight-preserving saturated embedding $\phi : Z \longrightarrow \spec (S)$ along $\Min(S)$.   
 \end{enumerate}
Moreover, if $B$ is quasi-excellent, then so is $S$.
\end{lemma}
\begin{proof}
   By Theorem $\ref{retraction and ring}$, there exists a local ring $S$ such that conditions $\ref{condition 1 in retraction codimension preserving}-\ref{condition 3 in retraction codimension preserving}$ are satisfied and a saturated embedding $\phi : Z \longrightarrow \Spec(S)$ such that $\phi(\min Z ) = \Min(S)$. Moreover, if $B$ is quasi-excellent, then so is $S$. It remains to show that $\phi$ is coheight-preserving along $\Min(S)$.


   Since $X$ is a retraction of $Z$, by Definition $\ref{retraction definition}$, $X = Z \setminus D_p$, where $p$ is a simple node in $Z$. If we let $\min X = \{p, x_2, \dots, x_n\}$ and $D_p = \{q_1, \dots, q_m\}$, we can write $\Min(B) = \{\psi(p) := P_1, \psi(x_2) := P_2, \dots, \psi(x_n) := P_n\}$ as $\psi(\min X) = \Min(B)$ by Lemma \ref{MinsgotoMins}. By Remark $\ref{remark about retraction and poset}$, $S = B[[t_1,t_2]]/J$ for some ideal $J$ and $\Min(S) = \{Q_1/J, \dots, Q_m/J, P_2'/J, \dots, P_n'/J\}$, where $P_i' = (P_i, t_1, t_2)$ for each $i = 2, \dots, n$ and $Q_j=(P_1,t_1+\beta_j t_2)$ for each $j=1,\dots, m$ where $\beta_1, \ldots ,\beta_m$ are distinct nonzero rationals. Moreover, the saturated embedding $\phi: Z \longrightarrow \spec(S)$ is explicitly defined by:
   \[
\phi(x) = \begin{cases} 
       (\psi(x), t_1, t_2)/J & x \in X, \\
       Q_i/J & x=q_i \in D_p.
   \end{cases}
\]
Let $P \in \Min(S)$. Our goal is to find an element $z \in Z$ such that $\phi(z) = P$ and $\dim(S/P) = \dim(z_Z^{\uparrow})$. First, assume $P = P_i'/J$ for some $i = 2, \dots, n$. In this case, we have 
$$S/P = (B[[t_1, t_2]]/J)/((P_i, t_1, t_2)/J) \cong B/P_i,$$ 
and so $\dim(S/P) = \dim(B/P_i).$ By assumption, the map $\psi$ is coheight-preserving along $\Min(B)$. So, there exists $x \in X$ with $\psi(x) = P_i$ and $\dim(B/P_i) = \dim(x_X^{\uparrow})$. Because $\psi$ is a saturated embedding, it is injective and so $\psi(x) = P_i = \psi(x_i)$ implies $x = x_i$. Since $x_i \in X$, Remark \ref{posets are isomorphic} ensures that $x{_i}_X^{\uparrow}$ is poset-isomorphic to $x{_i}_Z^{\uparrow}$. Setting $z = x_i$, we obtain $\phi(z) = \phi(x_i) = (\psi(x_i), t_1, t_2)/J = P_i'/J = P$ and $$\dim(S/P) = \dim(B/P_i) = \dim(x{_i}_X^{\uparrow}) = \dim(x{_i}_Z^{\uparrow})=\dim(z_Z^{\uparrow}).$$


Now suppose $P = Q_j/J$ for some $j = 1, \dots, m$. We proceed similarly. Since 
$$S/P=(B[[t_1, t_2]]/J)/((P_1,t_1+\beta_j t_2)/J) \cong B/P_1[[t_1]]$$
we see that $\dim(S/P)= \dim(B/P_1) + 1.$ The coheight-preserving property of $\psi$ and its injectivity on minimal nodes of $X$ imply that $\dim(B/P_1) = \dim(p_X^{\uparrow})$. By choosing $z = q_j$, we see that $\phi(z) = \phi(q_j) = Q_j/J = P$. The key observation is that $p_X^{\uparrow}$ is a retraction of $q{_j}_Z^{\uparrow}$ as $p_X^{\uparrow}=q{_j}_Z^{\uparrow} \setminus \{q_j\}$. Thus, we can use Lemma $\ref{retraction and node naturally poset isomorphic}$ to deduce that $\dim(q{_j}_Z^{\uparrow})=\dim(p_X^{\uparrow})+1$. Therefore,
\[
\dim(S/P) = \dim(B/P_1) + 1 = \dim(p_X^{\uparrow}) + 1 = \dim(q{_j}_Z^{\uparrow})=\dim(z_Z^{\uparrow}).
\] It follows that $\phi$ is coheight-preserving along $\Min(S)$.
\end{proof}


We now have the tools needed to prove the main result of this section.
\begin{theorem}\label{local quasi-excellent ring codimension preserving theorem}
       Let $Y$ be a finite poset with a unique maximal node. Then, there exists a reduced local ring $(S,M)$ and a saturated embedding $\Psi : Y \longrightarrow \spec(S)$ such that:
      \begin{enumerate}
        \item\label{condition 1 B contain sQ} $S$ contains $\Q,$
        \item $|S| = |S/M| = c$,
        \item $S$ is quasi-excellent, and
%        \item $\Psi(\min Y)=\Min(S)$ and,
        \item\label{condition 5 phi is condimension preserving} $\Psi$ is coheight-preserving along $\Min(S)$. 
       \end{enumerate}
\end{theorem}
\begin{proof}
    The proof closely follows the proof of Theorem $\ref{theorem 6.5 in colbert}$. By Theorem $\ref{every finite poset reduced to a point}$, the poset $Y$ reduces to a point. Hence, there exists a reduction sequence $(Y_1,\dots, Y_n = Y)$, where $Y_1$ is a point and each step is either a height zero splitting, a retraction, or simply the identity.

Let $S_1 = \C$, and define $\Psi_1: Y_1 \to \spec(S_1)$ as the poset map that sends the unique element of $Y_1$ to the zero ideal of $S_1$. For $1 \leq i < n$, assume that there is a reduced local ring $(S_i, M_i)$ and a saturated embedding $\Psi_i : Y_i \longrightarrow \Spec(S_i)$  satisfying conditions $\ref{condition 1 B contain sQ}$--$\ref{condition 5 phi is condimension preserving}$ (note that these properties hold for $S_1$ and $\Psi_1$).

We now construct a reduced local ring $(S_{i+1}, M_{i+1})$ and a saturated embedding $\Psi_{i + 1} : Y_{i + 1} \longrightarrow \Spec(S_{i + 1})$ with the same properties. If $Y_{i+1} = Y_i$, set $S_{i+1} = S_i$ and $\Psi_{i+1} = \Psi_i$. If $Y_i$ is a height zero splitting of $Y_{i+1}$—that is, if $Y_{i+1}$ is a height zero gluing of $Y_i$—apply Lemma $\ref{codimension preserving gluing thm}$ with $Y = Y_{i+1}$, $Z = Y_i$, $S = S_i$, and $\psi = \Psi_i$ to obtain $(S_{i+1}, M_{i+1})$ and a saturated embedding $\Psi_{i+1}$ that satisfy the four conditions in Lemma \ref{codimension preserving gluing thm}. Now, $|S_{i + 1}| = |S_{i + 1}/M_{i + 1}| = |\widehat{S_{i + 1}}/M_{i + 1}\widehat{S_{i+ 1}}| = |\widehat{S_{i }}/M_{i }\widehat{S_{i}}| = |S_i/M_i| = c$, and so conditions $\ref{condition 1 B contain sQ}$--$\ref{condition 5 phi is condimension preserving}$ hold.
In the case where $Y_i$ is a retraction of $Y_{i+1}$, use Lemma $\ref{retraction lemma for quasi-excellent ring}$ with $X = Y_i$, $Z = Y_{i+1}$, $B = S_i$, and $\psi = \Psi_i$. This yields a reduced local ring $(S_{i+1}, M_{i+1})$ and a saturated embedding $\Psi_{i+1}$ satisfying conditions $\ref{condition 1 B contain sQ}$--$\ref{condition 5 phi is condimension preserving}$.

Finally, by setting $S := S_n$ and $\Psi := \Psi_n$, we conclude that $\Psi: Y \to \spec(S)$ is a saturated embedding satisfying conditions $\ref{condition 1 B contain sQ}$--$\ref{condition 5 phi is condimension preserving}$.\end{proof}

We end this section with two consequences of Theorem \ref{local quasi-excellent ring codimension preserving theorem}.
\begin{corollary}\label{codimension implies dimension}
    Let $Y$ and $S$ be as in Theorem $\ref{local quasi-excellent ring codimension preserving theorem}$. Then, $\dim(Y)=\dim(S)$.
\end{corollary}
\begin{proof}
    The result follows from Remark $\ref{remark about dimension and codimension preserving}$.\end{proof}


