\subsubsection{The invariant $\mathrm{R}_0(\Lambda V,d)$}
Recall from \cite{R1} that  the second author introduced, in terms of \eqref{Ext Milnor Moore spec} the invariant 
$$\mathrm{R}_0(\Lambda V,d) = sup\{m\; | \; E_{\infty}^{m,*} \neq 0\}.$$
This is given in spirit of Toomer's invariant which in turn is given in terms of \eqref{Milnor Moore spec} by:
 $$e_0(\Lambda V,d) := sup\{m\; | \; E_{\infty}^{m,*} \neq 0\}.$$

An equivalent definition of $\mathrm{R}_0(\Lambda V,d)$ given in \cite[Remark 3.4]{R1}, in terms of the generating class $\Omega$ of $Ext^{*}_{(\Lambda V,d)}(\mathbb{K},(\Lambda V,d))$, is as follows:
$$\mathrm{R}_0(\Lambda V,d) = sup\{m\; | \; \Omega \; \hbox{can be represented by a cocycle in}\; F^m(A)\}.$$

Our first result in this section gives another proof of \cite[Theorem 1]{A-R} which relies on the algorithm defining $f^t$:

\begin{theorem}\label{R-inv}
Let $X$ be a rationally elliptic  CW-complex. Then,  $\mathrm{R}_0(X)=e_0(X)=cat_0(X).$ 
\end{theorem}
\begin{proof}
By hypothesis, $X$ being elliptic, its
Sullivan minimal model $(\Lambda V,d)$    is elliptic hence  $\dim V < \infty$ and $\dim H(\Lambda V,d)<\infty$. In particular $(\Lambda V,d_k)$ is a Gorenstein algebras, that is 
$$Ext^{*,*}_{(\Lambda V,d_k)}(\mathbb{K},(\Lambda V,d_k)) = Ext^{p',q'}_{(\Lambda V,d_k)}(\mathbb{K},(\Lambda V,d_k))$$
 where the unique bi-degree $(p',q')$ derived from the filtration (\ref{filt-Ext-MM spec}) satisfies $p'+q'=N$, the formal dimension of $(\Lambda V,d)$. By the convergent spectral sequence \eqref{Ext Milnor Moore spec}, we have also
 $$Ext^{*,*}_{(\Lambda V,d)}(\mathbb{K},(\Lambda V,d)) = Ext^{p',q'}_{(\Lambda V,d)}(\mathbb{K},(\Lambda V,d)).$$
%, $(\Lambda V,d)$ are both Gorenstein algebras and $\dim H^N(\Lambda V,d)=1$ where $N$ denotes  their common formal dimension (see (\ref{fd})). Thus, 
% the first term $Ext^{*,*}_{(\Lambda V,d_k)}(\mathbb{K},(\Lambda V,d_k))$ and the infinity term $E_{\infty}^{*,*}(A)\cong Ext^{*,*}_{(\Lambda V,d)}(\mathbb{K},(\Lambda V,d))$ of the convergent spectral sequence \eqref{Ext Milnor Moore spec}  are both one dimensional. Consequently, they are both  concentrated in a unique bi-degree $(p',q')$ coming from the filtration (\ref{filt-Ext-MM spec}), with $p'+q' = N$. 
This implies $\mathrm{R}_0(\Lambda V,d) = p' = \mathrm{R}_0(X)$ (cf. \S 6 for more explanation). 

Next,  since the chain evaluation map (\ref{cevmap}):
$$\begin{array}{cccc}
cev: & A=Hom_{(\Lambda V,d)}((\Lambda V \otimes \Lambda sV, D) , (\Lambda V,d)) & \rightarrow  & (\Lambda V,d)\\
     &       f          & \mapsto &   f(1)
\end{array}
$$ 
  preserves the filtrations (\ref{filt-Ext-MM spec}) and (\ref{fil-MM-spec}), in homology, it induces a morphism between the convergent  spectral sequences \eqref{Ext Milnor Moore spec} and  \eqref{Milnor Moore spec}. Hence, the the $E_\infty$ morphism $$E_{\infty}(ev): E_{\infty}^{p',q'}(A)\cong Ext^{p',q'}_{(\Lambda V,d)}(\mathbb{K},(\Lambda V,d)) \rightarrow E_{\infty}^{p',q'}(\Lambda V)\cong H^{p'+q'}(\Lambda V,d)$$
    is indeed an isomorphism (recall that   $\dim H^{N}(\Lambda V,d)=1$). By the above theorem, $L_0(\Lambda V,d) = l_0(\Lambda V,d)$ therefore, by (\ref{e_0}) we obtain 
    %$p'$ is the unique integer $m$ satisfying   $E_{\infty}^{m,N-m}(\Lambda V)\neq 0$. It results that
  %Using once again ellipticity of $(\Lambda V,d)$, we have  $ev_{(\Lambda V,d)}: Ext^{p',q'}_{(\Lambda V,d)}(\mathbb{K},(\Lambda V,d)) \rightarrow H^{p'+q'}(\Lambda V,d)$ is non-zero \cite{Mu94, Mu2}.  Therefore, by identifying $E_{\infty}^{p',q'}(A)$ with  $Ext^{p',q'}_{(\Lambda V,d)}(\mathbb{K},(\Lambda V,d))$ and,  $E_{\infty}^{p',q'}(\Lambda V)$ with  $H^{p'+q'}(\Lambda V,d)$ we obtain an identification between $ev_{(\Lambda V,d)}: Ext^{p',q'}_{(\Lambda V,d)}(\mathbb{K},(\Lambda V,d)) \rightarrow H^{p'+q'}(\Lambda V,d)$ and the infty morphism
   % $E_{\infty}(ev): E_{\infty}^{p',q'}(A) \rightarrow E_{\infty}^{p',q'}(\Lambda V)$. 
    %But, this latter sends $[f^t]$ to $[f^t(1)]$ so that (by identification)
     %$ev_{(\Lambda V,d)}([f^t]) = [f^t(1)]\neq 0$.  
     %being $e_0{(\Lambda V,d)}$ the biggest integer $m$ such that $E_{\infty}^{m,N-m}(\Lambda V)\neq 0$, we obtain 
      $e_0{(\Lambda V,d)} = p'=e_0(X)$ and thus, $\mathrm{R}_0(X)=e_0(X)=cat_0(X).$

\end{proof}

To illustrate, we apply the algorithm to a specific Sullivan model

  \begin{example}\label{exp4.5}
 Let us  reconsider the Sullivan model studied in example \ref{ExampleA} : $(\Lambda x_{2},x_{4},y_{5},y_{7}, d)$, $dx_{2}=dx_{4}=0$, $dy_{5}=x_{2}^{3}-2x_{2}x_{4}$, $dy_{7}=x_{4}^{2}-x_{2}^{2}x_{4}$. Its formal dimension is $N=8$, the top class is $\omega=[x_{2}^{2}x_{4}]$ and its quadratic associated model is $(\Lambda V,d_{2})=\,(\Lambda x_{2},x_{4},y_{5},y_{7},,\, d)$ with $d_{2}x_{2}=d_{2}x_{4}=0$, $d_{2}y_{5}=-2x_{2}x_{4}$, $d_{2}y_{7}=x_{4}^{2}$. Let $V = Span(x_2, x_4, y_5, y_7)$, thus $(\Lambda V,d_2)$ is pure and non-elliptic and $H^{N}(\Lambda V,d_{2})=\mathbb{Q}[x_{2}^{4}]$.

 Recall that,  by using the algorithm described in \S 3, we have also  determined in  Example \ref{ExampleA} (resp. Example \ref{ExampleB}) the generating class $\Omega$ (resp. $\Omega_{2}$) of $Ext^{8}_{(\Lambda V,d)}(\mathbb{K};(\Lambda V,d))$ (resp. $Ext^{(2,6)}_{(\Lambda V,d_{2})}(\mathbb{K};(\Lambda V,d_{2}))$). Now, consider the spectral sequence:
 \begin{center}
 	$Ext^{(2,6)}_{(\Lambda V,d_{2})}(\mathbb{K};(\Lambda V,d_{2}))\implies Ext^{8}_{(\Lambda V,d)}(\mathbb{K};(\Lambda V,d))$.
 \end{center}

 Now we determine $\Omega$ by using the Lechuga-Murillo algorithm. Let denote, as in Example \ref{ExampleA}, $\Omega_2 =[f]$ and  consider (formally) $f(1)=2x_{4}^2$ (we can not put  $f(1)=x_2^4$  since then $ev_{(\Lambda V,d_2)}\not=0$ which contradicts non-ellipticity of $(\Lambda V,d_2)$).

The first step will determine $\xi_{1}$. We  begin by its value on $\Lambda V$. This is given by $\xi_{1}(1)$. Using \cite{B-R}  we can use Remark \ref{rem4.2} above or else, Lechuga-Murillo's algorithm as in  \cite[Theorem 5]{L-M02} even if $(\Lambda V,d_2)$ is not elliptic. In particular,  we have $\xi_{1}(1)\in \Lambda ^3V$.
Moreover, 	$|\xi_1(1)|= |f(1)|=8$ which imposes $\xi_1(1)=\mu x_2^2x_4$ (some $\mu \in \mathbb{K}$), hence $d_2(\xi_1(1))=0$.  Thus, 
$$\xi_1(x_2)=\mu x_2^3x_4,\;  \xi_1(x_4)=\mu x_2^2x_4^2,\;  \xi_1(y_5)=\mu x_2^2x_4y_5,\; \hbox{and}\;  \xi_1(y_7)=\mu x_2^2x_4y_7.$$


  Next we consider $\xi_1$ on $\Lambda (sV)$. Recall that $f$ is given on  $\Lambda (sV)$ by Example \ref{ExampleB} with $(Df)(sV)\in\Lambda^{\geq3}V.$ We recall it for our use: 


  $$f(sx_2)=ax_4y_5+2(a+1)x_2y_7\;(a\in\mathbb{Q}),\quad f(sx_{4})=2x_{4}y_{7},\quad f(sy_{5})=-2y_{5}y_{7}\;\hbox{and}\; f(sy_{7})=0.$$


\begin{itemize}      
\item  For $sx_2$:
\begin{align*}
	(Df)(sx_{2}) &= d(f(sx_{2}))- f(dsx_{2})\\
	&=d(ax_4y_5 + 2(a+1)x_2y_7)- f(x_{2}) \\
	&= ax_4(x_2^3-2x_2x_4) +2(a+1)x_2(x_4^2-x_2^2x_4) -2x_2x_4^2\\
	& = -(a+2)x_2^3x_4.
\end{align*}

Hence, by word length reason, $h_{0}^{0}(sx_{2})= 0$. On the other side,
\begin{align*}
(D_{2}\xi_{1})(sx_{2})&=(d_2\circ \xi_1 - \xi_1 \circ d_2)(sx_2)\\
&=d_2(\xi_1(sx_2))-\xi_1(x_2)=0.
\end{align*}
Therefore, $d_2(\xi_1(sx_2))=\xi_1(x_2)=\mu x_2^3x_4\in\Lambda^{4}V$. Now, since  $d_2(\xi_1(sx_2))\in\Lambda^{3}V$, necessarily $\mu=0$, hence, on one hand, $\xi_1(1)=0$ and consequently, $\xi_1 =0$ on all $\Lambda V$. On the other hand,  $d_2(\xi_1(sx_2))=0$. 

Now, since, $\xi_1(sx_2)\in (\Lambda^2 V)^9$, we have $\xi_1(sx_2) = a'x_4y_5 + b'x_2y_7$ with $-2a' + b'=0$. It follows that
$\xi_1(sx_2) = a'(x_4y_5 + 2x_2y_7)$, where $a'\in \mathbb{Q}$.

For $f^1 = f -\xi_1$, we have :
\begin{align*}
	f^{1}(x_{2})&=f(x_{2})=2x_2x_4^2 \\
	f^{1}(sx_{2})&=f(sx_{2})- \xi_1(sx_2) \\
	&=  ax_4y_5 + 2(a+1)x_2y_7 - a'(x_4y_5 + 2x_2y_7) \\
	& = \alpha x_4y_5 + 2(\alpha +1) x_2y_7\; (\hbox{some}\;  \alpha = a-a' \in \mathbb{Q}).
\end{align*}

\item For $sx_4$:
  \begin{align*}
  (Df)(sx_{4})&=d(f(sx_{4}))-f(dsx_{4})\\
  &=d(f(sx_{4}))-f(x_{4}) \\
  &= d(2x_4y_7)-2x_4^3\\
  &= 2x_{4}^{3}-2x_{2}^{2}x_{4}^{2}-2x_4^3\\
  &= -2x_{2}^{2}x_{4}^{2}
  \end{align*}

Then, as before, $h_{0}^{0}(sx_{4})=D_2(\xi_1)(sx_{4})=0$. On the other side,
\begin{align*}
(D_{2}\xi_{1})(sx_{4})&=(d_2\circ \xi_1-\xi_1\circ d_2)(sx_4)\\
&= d_2(\xi_1(sx_4))-\xi_1(d_2(sx_4))\\
&=d_2(\xi_1(sx_4))-\xi_1(x_4).
\end{align*}
Then $d_2(\xi_1(sx_4))=\xi_1(x_4)= 0$. But, since
 $\xi_1(sx_4)\in (\Lambda^2 V)^{11}$, we have $\xi_1(sx_4)=cx_4y_7$ which leads to $c=0$ and consequently, $\xi_1(sx_4)=0$.

For $f^1 = f -\xi_1$, we get
\begin{align*}
f^{1}(x_{4})&=f(x_{4})=2x_4^3\\f^{1}(sx_{4})&=f(sx_{4})-\xi_{1}(sx_{4})=2x_4y_7.
\end{align*}

\item For $sy_5$:
\begin{align*}
(Df)(sy_{5})&=d(f(sy_{5}))-f(d(sy_{5}))\\
&=d(-2y_5y_7)-f(y_5- sd(y_5))\\ &=-2(x_{2}^{3}-2x_{2}x_{4})y_7+2(x_{4}^{2}-x_{2}^{2}x_{4})y_5- 2x_4^2y_5+f(s(x_2^3-2x_2x_4))\\
%&=-2(x_{2}^{3}-2x_{2}x_{4})y_7+2(x_{4}^{2}-x_{2}^{2}x_{4})y_5- 2x_4^2y_5+x_2^2(a x_4y_5 + 2(a+1) x_2y_7)-2x_2(2x_4y_7)\\
&=2ax_2^3y_7 +(a-2)x_2^2x_4y_5.
\end{align*}

As above, we have  $h_{0}^{0}(sy_{5})=0.$
Once again,  
\begin{align*}
h_0^0(sy_5)&=(D_{2}\xi_{1})(sy_{5})=(d_2\circ \xi_1-\xi_1\circ d_2)(sy_{5})\\
&=d_2(\xi_1(sy_5))-\xi_1(d_2(sy_5))\\
&= d_2(\xi_1(sy_5))-\xi_1(y_5)+\xi_1(s(-2x_2x_4))\\
&= d_2(\xi_1(sy_5))-\xi_1(y_5)-2x_2\xi_1(sx_4)\\
&= d_2(\xi_1(sy_5)).
\end{align*}
Then $d_2(\xi_1(sy_5))=0$. As before, since
 $\xi_1(sy_5)\in (\Lambda^2 V)^{12}$, we have $\xi_1(sy_5)=ey_5y_7$ which leads to $e=0$ and consequently, $\xi_1(sy_5)=0$.

Therefore, for $f^1$:
\begin{align*}
f^1(y_5)&=f(y_5)=2x_4^2y_5\\ 
f^{1}(sy_{5})&=f(sy_5)=-2y_5y_7.
\end{align*}


\item For $sy_7$:
As $df(sy_{7})=0$, we have 
\begin{align*}
(Df)(sy_{7})&=d(f(sy_{7}))-f(dsy_7)\\
&=-f(y_7- sd(y_7))=-f(y_7)+f(sd(y_7))\\
&=-2x_4^2y_7+f(s(x_4^2-x_2^2x_4))\\
&=-2x_4^2y_7+(x_4-x_2^2)f(sx_4)\\
&=-2x_4^2y_7+(x_4-x_2^2)(2x_4y_7)\\
&=-2x_2^2x_4y_7.
\end{align*}

Once again, we obtain
$h_{0}^{0}(sy_{7})=0$. But, 
\begin{align*}
h_{0}^{0}(sy_{7})&=(D_{2}\xi_{1})(sy_{7})= (d_2\circ \xi_1 - \xi_1 \circ d_2)(sy_{7})\\
&=d_2(\xi_1(sy_7))-\xi_1(d_2(sy_7))\\
&=d_2(\xi_1(sy_7))-\xi_1(y_7)+\xi_1(s(d_2y_7)))\\
&=d_2(\xi_1(sy_7))+\xi_1(sx_4^2)\\
&=d_2(\xi_1(sy_7))+x_4\xi_1(sx_4)\\
&=d_2(\xi_1(sy_7)).
\end{align*}


So, $d_2(\xi_1(sy_7))=0$ and consequently, since $\xi_1(sy_7)\in (\Lambda^2 V)^{14}$, we obtain $\xi_{1}(sy_{7})=0$. 

For $f^1$:
\begin{align*}
f^1(y_7)&=f(y_7)-\xi_1(y_7)=2x_4^2y_7\\ f^{1}(sy_{7})&=f(sy_{7})-\xi_1(sy_7)=0.
\end{align*}

\end{itemize}

We must consider $\xi_2$ because, in the expression for $Df|_{sV}$, there are terms in $\Lambda^4 V$.

We determine firstly $\xi_{2}(1)$ which (for the same reason as for $\xi_{1}(1)$) satisfies: \\
	$\left\{
	\begin{array}{l}
		d_2(\xi_2(1))=0 \\
		\xi_2(1)\in\Lambda^4V,\\
		|\xi_2(1)|=8.
	\end{array}
	\right.$
	Then $\xi_2(1)=\beta x_2^4$,\\  so, 
	$\xi_2(x_2)=\beta  x_2^5$, $\xi_2(x_4)=\beta x_2^4x_4$, $\xi_2(y_5)=\beta  x_2^4y_5$ and  $\xi_2(y_7)=\beta  x_2^4y_7$.

Next we consider $\xi_2$ on $\Lambda (sV)$. Recall that $f^1$ is given by 
\begin{align*}
	f^{1}(x_{2})&=f(x_{2})=2x_2x_4^2,\\
	f^{1}(x_{4})&=f(x_{4})=2x_4^3,\\
	f^1(y_5)&=f(y_5)=2x_4^2y_5,\\
	f^1(y_7)&=f(y_7)=2x_4^2y_7,\\
	f^{1}(sx_{2})&=f(sx_{2})-\xi_{1}(sx_2)= \alpha x_4y_5 + 2(\alpha +1) x_2y_7\; (\hbox{some}\;  \alpha = a-a' \in \mathbb{Q}),\\
	f^{1}(sx_{4})&=f(sx_{4})=2x_4y_7,\\
	f^{1}(sy_{5})&=f(sy_5)=-2y_5y_7,\\
	f^{1}(sy_{7})&=f(sy_{7})=0.
\end{align*}

\begin{itemize}
\item  We have $(Df^1)(sx_{2})\in\Lambda^{\geq4}V$ (since $p=2$ and $k=2$), and 
\begin{align*}
	(Df^1)(sx_{2})&=d(f^1(sx_{2}))-f^1(dsx_{2})\\
	&=d(\alpha x_4y_5+2(\alpha +1)x_2y_7)-2x_2x_4^2\\
	&=\alpha x_4(x_{2}^{3}-2x_{2}x_{4})+2(\alpha +1) x_2(x_4^2-x_{2}^2x_{4})-2x_2x_4^2\\
	&=-(\alpha+2)x_2^3x_4.
\end{align*}

 Then  $h_{1}^{1}(sx_{2})= -(\alpha +2) x_2^3x_4$.

\begin{align*}
	(D_{2}\xi_{2})(sx_{2})&=(d_2\circ \xi_2 - \xi_2 \circ d_2)(sx_2)\\
	&=d_2(\xi_2(sx_2))-\xi_2(x_2)=-(\alpha +2) x_2^3x_4.
\end{align*}
Therefore, $d_2(\xi_2(sx_2))=\xi_2(x_2)-(\alpha +2) x_2^3x_4=\beta x_2^5  -(\alpha +2) x_2^3x_4$. 
But, since (i) $x_2^5$ is not a $d_2$-coboundary, (ii)  $d_2(\xi_2(sx_2))\in\Lambda^{4}V$ and (iii) $-(\alpha +2) x_2^3x_4=d_2(\frac{\alpha +2}{2}x_2^2y_5)$, we should have $\beta=0$ and  $\xi_2(sx_2)=\frac{\alpha +2}{2}x_2^2y_5$. In particular, $\xi_2(1) =0$ and therefore, $\xi_2$ is zero on all $\Lambda V$. 

Now, for $f^2 = f^1 -\xi_2 = f- \xi_{1} -\xi_{2}$ as in the algorithm, we deduce from above that
\begin{align*}
	f^{2}(x_{2})&=f(x_{2})=2x_2x_4^2\\
	f^{2}(sx_{2})&=f^1(sx_{2})-\xi_{2}(sx_{2})= (\alpha x_4 - \frac{\alpha +2}{2}x_2^2)y_5 + 2(\alpha +1) x_2y_7.
\end{align*}
\item
\begin{align*}
	(Df^1)(sx_{4})&=d(f^1(sx_{4}))-f^1(dsx_{4})\\
	&=d(f^1(sx_{4}))-f^1(x_{4}) \\
	&=d(2x_4y_7)-2x_4^3\\
	&=2x_{4}^{3}-2x_{2}^{2}x_{4}^{2}-2x_4^3\\
	&=-2x_{2}^{2}x_{4}^{2}.
\end{align*}
Then, $h_{1}^{1}(sx_{4})=D_2(\xi_2)=-2x_{2}^{2}x_{4}^{2}$. On the other side,
\begin{align*}
	(D_{2}\xi_{2})(sx_{4})&=(d_2\circ \xi_2-\xi_2\circ d_2)(sx_4)\\
	&= d_2(\xi_2(sx_4))-\xi_2(d_2(sx_4))\\
	&=d_2(\xi_2(sx_4))-\xi_2(x_4)= d_2(\xi_2(sx_4)).
\end{align*}
Then $d_2(\xi_2(sx_4))=-2x_{2}^{2}x_{4}^{2}= d_2(kx_2x_4y_5 + lx_2^2y_7)$. Thus, $\xi_2(sx_4)=kx_2x_4y_5+lx_2^2y_7$ with $-2k + l = -2$, that is with $l = 2(k-1)$. It follows that $\xi_2(sx_4)= kx_2x_4y_5 + 2(k-1) x_2^2y_7$.

Thus for $f^2 = f^1 -\xi_2$, we get
\begin{align*}
	f^{2}(x_{4})&=f^1(x_{4})-\xi_{2}(x_{4})=2x_4^3\\
	f^{2}(sx_{4})&=f^1(sx_{4})-\xi_{2}(sx_{4})=2x_4y_7-kx_2x_4y_5 - 2(k-1) x_2^2y_7\\
	&=-kx_2x_4y_5+(2x_4-2(k-1)x_2^2)y_7.
\end{align*}



\item \begin{align*}
(Df^1)(sy_{5})&=d(f^1(sy_{5}))-f^1(d(sy_{5}))=d(-2y_5y_7)-f^1(y_5- sd(y_5))\\
&=-2(x_{2}^{3}-2x_{2}x_{4})y_7  + 2(x_{4}^{2}  -x_{2}^{2}x_{4})y_5-2x_4^2y_5+f^1(s(x_2^3-2x_2x_4))\\
%&=-2(x_{2}^{3}-2x_{2}x_{4})y_7+2(x_{4}^{2}-x_{2}^{2}x_{4})y_5- 2x_4^2y_5+ x_2^2(\alpha x_4y_5 + 2(\alpha +1)x_2y_7) -4x_2x_4y_7\\
&=2\alpha x_2^3y_7 + (\alpha -2)x_2^2x_4y_5.
\end{align*}

Then, $h_{1}^{1}(sy_{5})=2\alpha x_2^3y_7 + (\alpha -2)x_2^2x_4y_5.$
Once again,  
\begin{align*}
h_1^1(sy_5)&=(D_{2}\xi_{2})(sy_{5})=(d_2\circ \xi_2-\xi_2\circ d_2)(sy_{5})\\
&=d_2(\xi_2(sy_5))-\xi_2(d_2(sy_5))\\
&= d_2(\xi_2(sy_5))-\xi_2(y_5)+\xi_2(s(-2x_2x_4))\\
&= d_2(\xi_2(sy_5))-2x_2\xi_2(sx_4)\\
&= d_2(\xi_2(sy_5))-2x_2(kx_2x_4y_5 + 2(k-1) x_2^2y_7)\\
&= d_2(\xi_2(sy_5))-2kx_2^2x_4y_5-4(k-1)x_2^3y_7.
\end{align*}
Thus,
\begin{align*}
d_2(\xi_2(sy_5))&= 2kx_2^2x_4y_5+4(k-1)x_2^3y_7+ 2\alpha x_2^3y_7 + (\alpha -2)x_2^2x_4y_5 \\
                &=(2k +\alpha - 2)[x_2^2x_4y_5 + 2x_2^3y_7].
\end{align*}
But $\xi_2(sy_5)\in (\Lambda^3V)^{12}$, hence, it has (uniquely) the form $\xi_2(sy_5)=cx_4^3$ (some $c\in\mathbb{Q}$)  so that $d_2(\xi_2(sy_5))=0$ and consequently, $2k+\alpha-2=0$ i.e. $k=\frac{2-\alpha}{2}$. In particular, actually: 
\begin{align*}
\xi_2(sx_4)= kx_2x_4y_5+2(k-1)x_2^2y_7=\frac{2-\alpha}{2}x_2x_4y_5-\alpha  x_2^2y_7\\
f^{2}(sx_{4})=\frac{\alpha-2}{2}x_2x_4y_5+\alpha x_2^2y_7+2x_4y_7.
\end{align*}
And, 
\begin{align*}
f^2(y_5)&=f^1(y_5)-\xi_2(y_5)=2x_4^2y_5,\\ f^{2}(sy_{5})&=f^1(sy_5)-\xi_2(sy_5)=-2y_5y_7 - cx_4^3 \; (\hbox{some}\;  c\in \mathbb{Q}).
\end{align*}


\item 
\begin{align*}
	(Df^1)(sy_{7})&=d(f^1(sy_{7}))-f^1(dsy_7)\\
	&=-f^1(y_7- sd(y_7))=-2x_4^2y_7+f^1(sd(y_7))\\
	&=-2x_4^2y_7+f^1(s(x_4^2-x_2^2x_4))\\
	&=-2x_4^2y_7+(x_4-x_2^2)f^1(sx_4)\\
	&=-2x_4^2y_7+(x_4-x_2^2)(2x_4y_7)\\
	&=-2x_2^2x_4y_7.
\end{align*}

so that
$h_{1}^{1}(sy_{7})=-2x_2^2x_4y_7$. But, 
\begin{align*}
	h_{1}^{1}(sy_{7})&=(D_{2}\xi_{2})(sy_{7})= (d_2\circ \xi_2 - \xi_2 \circ d_2)(sy_{7})=d_2(\xi_2(sy_7))-\xi_2(d_2(sy_7))\\
	&=d_2(\xi_2(sy_7))-\xi_2(y_7)+\xi_2(s(d_2y_7)))\\
	&=d_2(\xi_2(sy_7))+\xi_2(sx_4^2)\\
