\end{align*}
then
\begin{align*}d_2(\xi_2(sy_7)) &=-2x_2^2x_4y_7- \frac{2-\alpha}{2}x_2x_4^2y_5 + \alpha x_2^2x_4y_7\\
                               &= \frac{\alpha -2}{2}x_2x_4^2y_5 + (\alpha -2)x_2^2x_4y_7 = \frac{2 - \alpha}{2}x_2[ - 2x_2x_4y_7 - x_4^2y_5]\\
                               &=  d_2(\frac{2-\alpha}{2}x_2y_5y_7).
 \end{align*}
 It follows that  $\xi_{2}(sy_{7})=\frac{2-\alpha}{2}x_2y_5y_7$. Thus
\begin{align*}
	f^2(y_7)&=f^1(y_7)-\xi_2(y_7)=2x_4^2y_7,\\ f^{2}(sy_{7})& = f^1(sy_{7})-\xi_2(sy_7)= \frac{\alpha -2}{2}x_2y_5y_7.
