			Df(sw) & =(df-fd)(sw)=df(sw)-f(w-sdw) =df(sw)-f(w-s(b^{2}-2vx))\\
			& =df(sw)-f(w)+bf(sb)-2vf(sx)=df(sw)-f(w)+bf(sb) \\
			& =-abxvw+b^{2}xuw+abxvw-b^{2}xuw =0\\
			& =h_{0}^{0}(sw)=D_{\sigma}\beta_{1}(sw)=(d_{\sigma}\beta_{1}-\beta_{1}d_{\sigma})(sw) =d_{\sigma}\beta_{1}(sw)-\beta_{1}(w)+\beta_{1}(sd_{\sigma}w)\\
			& =d_{\sigma}\beta_{1}(sw)-\beta_{1}(w)+\beta_{1}(s(b^{2})) =d_{\sigma}\beta_{1}(sw)-\beta_{1}(w)+b\beta_{1}(sb)
		\end{align*}
so
	\begin{align*}
	d_{\sigma}\beta_{1}(sw) & = \beta_{1}(w)-b\beta_{1}(sb) =-\alpha b^{2}xuw+\alpha b^{2}xuw=0
	\end{align*}
Then $\beta_{1}(sw)=0$.
	\end{itemize}
We now move on to determine $f^{1}$, notice that
	%$$f^{1}(1)=f(1)-\beta_1(1)=abxv-b^{2}xu-\alpha a^{2}xw+\alpha b^{2}xu.$$ Thus,
	\begin{itemize}


\item	\begin{align*}
f^{1}(1) & =f(1)-\beta_1(1) =abxv-b^{2}xu-\alpha a^{2}xw+\alpha b^{2}xu.\\
f^{1}(a) & =f(a)-\beta_{1}(a) =a^{2}bxv-ab^{2}xu-\alpha a^{3}xw+\alpha ab^{2}xu, \; \hbox{for some}\;  \alpha \in \mathbb{Q}.\\
f^{1}(sa) & =f(sa)-\beta_{1}(sa) =-bxuv+\alpha axuw, \; \hbox{for some}\; \alpha \in \mathbb{Q}
	\end{align*}
We calculate $Df^{1}(sa) $:
	 \begin{align*}
			Df^{1}(sa) & = (df^{1}-f^{1}d)(sa)=df^{1}(sa)-f^{1}(a-sda) =df^{1}(sa)-f^{1}(a) \\
			& =d(-bxuv+\alpha axuw)-a^{2}bxv+ab^{2}xu+\alpha a^{3}xw-\alpha ab^{2}xu \\
			& =-d(bx)uv+bxd(uv)+\alpha d(ax)uw-\alpha axd(uw)-a^{2}bxv+ab^{2}xu+\alpha a^{3}xw-\alpha ab^{2}xu  \\
			%& =a^{2}bxv-bxu(ab-ux)-\alpha a^{3}xw+\alpha axu(b^{2}-2vx)-a^{2}bxv+ab^{2}xu+\alpha a^{3}xw-\alpha ab^{2}xu\\
			&=a^{2}bxv-ab^{2}xu-\alpha a^{3}xw+\alpha ab^{2}xu-a^{2}bxv+ab^{2}xu+\alpha a^{3}xw-\alpha ab^{2}xu =0
		\end{align*}


\item	$f^{1}(b)=f(b)-\beta_{1}(b)=ab^{2}xv-b^{3}xu-\alpha a^{2}bxw+\alpha b^{3}xu$, for some $\alpha \in \mathbb{Q}$.\\
	$f^{1}(sb)=f(sb)-\beta_{1}(sb)=axvw-bxuw+\alpha bxuw$, for some $\alpha \in \mathbb{Q}$.

	We calculate $Df^{1}(sb)$:
 \begin{align*}
			Df^{1}(sb) & = (df^{1}-f^{1}d)(sb)=df^{1}(sb)-f^{1}(b-sdb)\\
			& =df^{1}(sb)-f^{1}(b)+f(s(ax))=df^{1}(sb)-f^{1}(b)+af(sx)) =df^{1}(sb)-f^{1}(b) \\
			& =d(axvw-bxuw+\alpha bxuw)- ab^{2}xv+b^{3}xu+\alpha a^{2}bxw-\alpha b^{3}xu\\
			& =-axd(vw)+bxd(uw)-\alpha bxd(uw)- ab^{2}xv+b^{3}xu+\alpha a^{2}bxw-\alpha b^{3}xu\\
			& =-ax(ab-ux)w+axv(b^{2}-2vx)+a^{2}bxw-bxu(b^{2}-2vx)-\alpha a^{2}bxw\\
			&+\alpha bxu(b^{2}-2vx)- ab^{2}xv+b^{3}xu+\alpha a^{2}bxw-\alpha b^{3}xu\\
			& =-a^{2}bxw+ab^{2}xv+a^{2}bxw-b^{3}xu-\alpha a^{2}bxw+\alpha b^{3}xu- ab^{2}xv+b^{3}xu+\alpha a^{2}bxw\\
			&-\alpha b^{3}xu =0
		\end{align*}


\item	$f^{1}(u)=f(u)-\beta_{1}(u)=-abxuv-\alpha a^{2}xwu=-abxuv+\alpha a^{2}xuw$, for some $\alpha \in \mathbb{Q}$.\\
	$f^{1}(su)=f(su)-\beta_{1}(su)=f(su)=0$.

		We calculate $Df^{1}(su)$:

	\begin{align*}
			Df^{1}(su) & = (df^{1}-f^{1}d)(su)=df^{1}(su)-f^{1}(u-sdu) =df^{1}(su)-f^{1}(u)+af^{1}(sa)\\
			&  =-f^{1}(u)+af^{1}(sa)  =abxuv-\alpha a^{2}xuw+a(-bxuv+\alpha axuw)\\
			& =abxuv-\alpha a^{2}xuw-abxuv+\alpha a^{2}xuw =0
		\end{align*}


\item	$f^{1}(x)=f(x)-\beta_{1}(x)=0$ and $f^{1}(sx)=f(sx)-\beta_{1}(sx)=0$.

We calculate $Df^{1}(sx)$:
 \begin{align*}
			Df^{1}(sx) & =df^{1}(sx)-f^{1}(x)+af^{1}(sx) \\
			& =df^{1}(sx)-f^{1}(x) =0
		\end{align*}
Clearly, $Df^{1}(sx) = 0$:


\item	$f^{1}(v)=f(v)-\beta_{1}(v)=-b^{2}xuv+\alpha a^{2}xvw+\alpha b^{2}xuv$, for some $\alpha \in \mathbb{Q}$.\\
	$f^{1}(sv)=f(sv)-\beta_{1}(sv)=xuvw-\alpha xuvw$, for some $\alpha \in \mathbb{Q}$.

We calculate $Df^{1}(sv)$:
 \begin{align*}
			Df^{1}(sv) & =df^{1}(sv)-f^{1}(v)+f^{1}(sdv) =df^{1}(sv)-f^{1}(v)+f^{1}(s(ab-ux)) \\
			& =df^{1}(sv)-f^{1}(v)+af^{1}(sb)-uf^{1}(sx)= df^{1}(sv)-f^{1}(v)+af^{1}(sb)\\
			& =d(xuvw-\alpha xuvw)+b^{2}xuv-\alpha a^{2}xvw-\alpha b^{2}xuv+a(axvw-bxuw+\alpha bxuw) \\
			& =d(xu)vw+xud(vw)-\alpha d(xu)vw-\alpha xud(vw)+b^{2}xuv-\alpha a^{2}xvw-\alpha b^{2}xuv\\
			&+a^{2}xvw-abxuw+\alpha abxuw\\
			& =-a^{2}xvw+xu(ab-ux)w-xuv(b^{2}-2vx)+\alpha a^{2}xvw-\alpha xu(ab-ux)w\\
			&+\alpha xuv(b^{2}-2vx)\\
			&+b^{2}xuv-\alpha a^{2}xvw-\alpha b^{2}xuv+a^{2}xvw-abxuw+\alpha abxuw\\
			& =-a^{2}xvw+abxuw-b^{2}xuv+\alpha a^{2}xvw-\alpha abxuw+\alpha b^{2}xuv\\
			&+b^{2}xuv-\alpha a^{2}xvw-\alpha b^{2}xuv+a^{2}xvw-abxuw+\alpha abxuw =0
		\end{align*}

\item	$f^{1}(w)=f(w)-\beta_{1}(w)=abxvw-b^{2}xuw+\alpha b^{2}xuw$, for some $\alpha \in \mathbb{Q}$.\\
	$f^{1}(sw)=f(sw)-\beta_{1}(sw)=0$.

	We calculate $Df^{1}(sw)$ :

 \begin{align*}
			Df^{1}(sw) & =df^{1}(sw)-f^{1}(w)+f^{1}(sdw) =-f^{1}(w)+f^{1}(s(b^{2}-2vx))\\
			&=-f^{1}(w)+bf^{1}(sb)-2vf^{1}(sx)\\
			&  = -abxvw+b^{2}xuw-\alpha b^{2}xuw+b(axvw-bxuw+\alpha bxuw)\\
			& = -abxvw+b^{2}xuw-\alpha b^{2}xuw+abxvw-b^{2}xuw+\alpha b^{2}xuw =0
		\end{align*}
	\end{itemize}
	Thus, $f^{1}$ is a generating class of $Ext_{(\Lambda V,d)}(\mathbb{Q},(\Lambda V,d))$.
\end{example}








