\title[Ramified splitting Arithmetic transfer conjectures]{More regular formal moduli spaces and arithmetic transfer conjectures: the ramified quadratic case}

\author{Y. Luo}
\address{University of Wisconsin-Madison, Department of Mathematics, 480 Lincoln Drive, Madison, WI 53706, USA}
\email{yluo237@wisc.edu}
\author{M. Rapoport}
\address{Mathematisches Institut der Universit\"at Bonn, Endenicher Allee 60, 53115 Bonn, Germany}
\email{rapoport@math.uni-bonn.de}

\author{W. Zhang}
\address{Massachusetts Institute of Technology, Department of Mathematics, 77 Massachusetts Avenue, Cambridge, MA 02139, USA}
\email{weizhang@mit.edu}


 \date{\today}



\begin{abstract}For unitary groups associated to a ramified quadratic extension of a $p$-adic field,
we define various regular formal moduli spaces of $p$-divisible groups with parahoric levels, characterize exceptional special divisors on them, and construct correspondences between them. We formulate arithmetic transfer conjectures,
which are variants of the arithmetic fundamental lemma conjecture in this context. We prove the conjectures in the lowest dimensional cases.
\end{abstract}

