\section{Preliminaries}

Throughout the article, $X$ is assumed to be a complex manifold.
Given a holomorphic vector bundle $E\to X$ we let $p\colon \Pk(E)\to X$ denote the projectivization,
so that the fiber above $x$ is the set of all lines\footnote{There is another common convention in the literature, where
the fiber instead is all hyperplanes through the origin.} through the origin in $E_x$.
Then the pullback $p^*E\to \Pk(E)$ has the tautological sub(line)bundle
$L_E\to \Pk(E)$ whose fiber over $(x,[\alpha])\in \Pk(E)$ is the line in $E_x$ determined by
$\alpha$.

If $E$ has a smooth Hermitian metric $h$, then $p^* E$ and hence $L_E$ inherit
smooth Hermitian metrics.
Notice that a local section $s$ of $L_E$ has the form $s=\tilde s(x,\alpha) \alpha$, where
$\tilde s$ is a holomorphic function on $E\setminus 0_E$ which is $-1$-homogeneous in $\alpha$. Thus any local section can be identified with such an $\tilde s$.
The induced norm is
\begin{equation}\label{snorm}
|s|^2_{e^\psi}:=|\tilde s|^2|\alpha|^2_h.
\end{equation}
In a local frame for $L_E$, say $1/\alpha_j$, the section $s$ is represented by the function $\tilde s \alpha_j$, and
from \eqref{snorm} we have that
$$
|s|^2_{e^\psi}=|\tilde s\alpha_j|^2e^{\log(|\alpha|_h^2/|\alpha_j|^2)}.
$$
Thus the metric $e^\psi$ on $L_E$ with respect to the local frame $1/\alpha_j$ is given by
\begin{equation}\label{phiform}
\psi=\log(|\alpha|^2_h/|\alpha_j|^2).
\end{equation}


Note that even though $\log |\alpha|_h^2$ is not well-defined on $\Pk(E)$,
$dd^c \log |\alpha|_h^2$ is a well-defined form on $\Pk(E)$, and if
$s$ is a non-vanishing section of $L_E$, then $dd^c\log|s|_h^2=dd^c\log|\alpha|_h^2$.
Thus, if $c_1(L_E,e^\psi)$ and $s_1(L_E,e^\psi)$ are the first Chern form
and Segre form, respectively, then
$$
-c_1(L_E,e^\psi)=s_1(L_E,e^\psi)=dd^c\log|\alpha|^2_h,
$$
so that
$$
s(L_E,e^\psi)=\frac{1}{c(L_E,e^\psi)}=\frac{1}{1+c_1(L_E,e^\psi)}=\frac{1}{1-s_1(L_E,e^\psi)}=\sum_{\ell=0}^\infty (dd^c\log|\alpha|_h^2)^\ell.
$$
The Segre form of $(E,h)$ is defined as
\begin{equation}\label{segdef}
s(E,h)=p_* s(L_E,e^\psi)=p_*\sum_{\ell=0}^\infty (dd^c\log|\alpha|_h^2)^\ell,
\end{equation}
and it is a smooth form since $p$ is a submersion.
We write $s(E,h) = \sum s_k(E,h)$, where $s_k(E,h)$ has bidegree $(k,k)$.
It turns out that $s_0(E,h)=1$ and thus $s(E,h)-1$ has positive bidegree. We have the Chern form
\begin{equation}\label{cformel}
c(E,h)=\frac{1}{s(E,h)}=\sum_{\ell=0}^\infty (-1)^\ell (s(E,h)-1)^\ell.
\end{equation}
By \cite{Mour} (see also i.e., \cite{Div}), these definitions of $c(E,h)$ and $s(E,h)$ coincide
with the more standard definitions of Chern form defined as the sum of the elementary symmetric
polynomials acting on ($i/2\pi$ times) the curvature tensor $\Theta(h)=D^2$ of $(E,h)$, where
$D$ denotes the Chern connection with respect to $h$, and the Segre form defined as
$s(E,h)=1/c(E,h)$.


\subsection{Qpsh functions with analytic singularities}

Let $Y$ be a complex manifold. Recall that a real valued function $u$ is qpsh (quasi-plurisubharmonic) if locally
$u=v+a$, where $v$ is psh and $a$ is smooth.
As already mentioned, $u$ has analytic singularities if locally
\begin{equation}\label{totem1}
u=c\log|f|^2+ b,
\end{equation}
where $b$ is bounded.

\begin{lma}\label{lemur}
Assume that $W$ is a connected complex manifold. If $\tau\colon W\to Y$ is holomorphic and $u$ is qpsh with (integral)
analytic singularities on $Y$, then $\tau^*u$ is qpsh with (integral) analytic singularities in $W$.
Possibly $\tau^*u$ is identically $-\infty$.
\end{lma}



\begin{lma}\label{proviant}
If $\psi_1$ and $\psi_2$ are qpsh (with integral analytic singularities),
then $\psi_1+\psi_2$ and
$
\log(e^{\psi_1}+e^{\psi_2})
$
are qpsh (with integral analytic singularities).
\end{lma}

Lemma~\ref{lemur} follows directly from the definitions. Lemma~\ref{proviant}
is well-known for psh $\psi_j$ (with integral analytic singularities). It is readily
checked that it also holds for qpsh (with integral analytic singularities), using
the characterization that functions $\psi_j,\ j=1,2,$ are qpsh (with integral
analytic singularities) if and only if locally there is a smooth function $\phi$ such that
$\psi_j':=\psi_j + \phi,\ j=1,2,$ are psh (with integral analytic singularities).

\subsection{A regularization of locally bounded qpsh functions}

In this subsection, we will consider a modification of the standard local regularization
of psh functions through convolution, which will be suitable for approximating \qas\ metrics
with empty unbounded locus.

\begin{prop} \label{prop:locBddQasApproximation}
Let $\psi(x,y)$ be a locally bounded qpsh function on $U \subset \C^n_x \times \C^m_y$,
assume that $\psi$ is smooth as a function of $y$, with $x$ fixed,
and let $v(x,y)$ be a smooth psh function.
Let $\rho_\e(x)=\rho(x/\e)/\e^n$ be a family of radial mollifiers with respect to the variable $x$.
Define
\begin{equation} \label{eq:locBddQasApproximation}
    \psi_\e = \log(e^\psi*_x\rho_\e+A\e e^v),
\end{equation}
where $\psi *_x\rho_\e$ denotes the convolution with respect to $x$.
For any $V \subset\subset U$, $\psi_\e$ is smooth on $V$ for $\e$ small enough,
and if $A \gg 1$, then $\psi_\e$ is increasing in $\e$.
If $\psi = u+g$, where $u$ is psh and $g$ is smooth, and
$dd^c g \geq -B \omega$, where $\omega=dd^c (|x|^2+|y|^2)$, then
$dd^c \psi_\e \geq - B \omega$.
\end{prop}

By decomposing $dd^c \psi_\e = (dd^c (\psi_\e + B(|x|^2+|y|^2)) - B\omega$,
and applying the Bedford-Taylor theory of convergence of Monge-Ampère products
for locally bounded psh functions, one obtains the following convergence.

\begin{cor}
Let $\psi$ and $\psi_\e$ be as in Proposition~\ref{prop:locBddQasApproximation}. Then, for any $k \geq 0$,
\begin{equation}
    (dd^c \psi_\e)^k \to (dd^c \psi)^k.
\end{equation}
\end{cor}

\begin{proof}[Proof of Proposition~\ref{prop:locBddQasApproximation}]
We first prove that if $\psi=u$ is psh, then $\psi_\e$ is also psh.
We begin by assuming that $u$ is also smooth.
In that case, by approximating the convolution by Riemann sums, $u_\e$ may be uniformly approximated by
$u_{\e,N}=\log(\sum_k e^{u_k+\log c_k}+e^{v+\log(A\e)})$, where $c_k$ are positive
constants, and $u_k(x,y)=u(x-x_k,y)$. Since all the functions in the exponents
are psh, $u_{\e,N}$ is also psh, and thus so is $u_\e$.
If $u$ is psh, we may choose a sequence of smooth functions $u_k$ decreasing to $u$,
and then $(u_k)_\e$ decreases to $u_\e$, and hence $u_\e$ is psh.

We consider now the case when $\psi=u+g$, where $g$ is smooth, and show that
$dd^c\psi_\e \geq -B\omega$, or equivalently, that $\psi_\e' = \psi_\e + B(|x|^2+|y|^2)$ is psh.
As above, it suffices to prove the statement assuming that $u$ is smooth.
We may write
$$
    \psi_\e'(x,y) = \log( (e^{\psi} *_x \rho_\e) e^{B(|x|^2+|y|^2)} + e^{v+\log(A\e)+B(|x|^2+|y|^2}),
$$
and as above, $\psi_\e'$ may be uniformly approximated by
$$
    \psi_{\e,N}' = \log(\sum e^{\psi_k + \log c_k+B(|x|^2+|y|^2)} + e^{v+\log(A\e)}).
$$
Since $\psi_k$ is just a translation of $\psi$, and $dd^c(|x|^2+|y|^2)$ is translation invariant,
it follows that all the functions in the exponents are psh, and thus $\psi_{\e,N}'$
is psh, and hence so is $\psi_\e'$.


Note that $\psi_\e$ is smooth as a function of $x$ and $y$.
It remains to prove that it is increasing in $\e$ on $V$, for $A \gg 1$.
To see this, we may fix $y$ and consider everything as a function of $x$.
We write $\psi=u+g$, where $u$ is psh and
$g$ is smooth on $X$. We then decompose $e^{\psi_\epsilon}$ as
$$
e^{\psi_\epsilon}(x) = e^{g(x)}  (e^u \ast \rho_\epsilon)(x) +
\int (e^{g(x-x')}-e^{g(x)}) \rho_\epsilon(x') dV(x') + A\epsilon e^v.
$$
Since $e^u$ is psh, the first term of the right hand side is increasing in $\epsilon$.
It then suffices to prove that the middle term is differentiable in $\epsilon$,
with a derivative less than $A e^v$ to see that the whole expression is increasing in $\epsilon$.
To see this, note that $(d/d\epsilon) \rho_\epsilon(x') = \Ok(1/\epsilon^{n+1})$,
and has support where $|x'| \leq \epsilon$.
Since $|e^{g(x-x')}-e^{g(x)}| \leq C\epsilon$ for $|x'| \leq \epsilon$
(with $C$ depending on the $C^1$-norm of $e^g$), we obtain that
the derivative of the middle term is bounded by a constant, which is smaller than
$A e^v$ on $V$ if $A$ is chosen large enough.
\end{proof}

\section{\qas\ bundles}\label{qgnsec}

Let $E\to X$ be a holomorphic vector bundle.
As already mention in the introduction we have the following definition:


\begin{df}
We say that a real function is \qas\ if it is qpsh with integral analytic singularities.
A singular metric $h$ on $E\to X$ is \qas\ if the function $\alpha\mapsto\log|\alpha|^2_h$ is
\qas\ on the total space $E$.
In that case $(E, h)$ is said to be \qas.
\end{df}

We will often drop the metric from the notation, and simply say that $E$ is a \qas\ bundle.
We will then also often denote the norm simply by $|\alpha|$.

\begin{ex}
If $L$ is a line bundle with metric $e^\psi$, then $L$ is \qas\ precisely if the representation
of $\psi$ in any local frame is \qas.
\end{ex}





\begin{lma}\label{orkan}
Let $E$ be a holomorphic vector bundle on $X$ with a smooth Hermitian metric $h$.
Any point $x_0 \in X$ has a \nbh $U$ such that
$h' = h e^{A|x|^2}$ is Griffiths negative if $A$ is large enough, where
$x$ denotes a local coordinate system near $x_0$.
\end{lma}



\begin{proof}
If we decompose the curvature $\Theta_h$ of $h$ as $\sum \Theta_{jk} dx_j{\wedge}d\bar{x}_k$,
then $h$ is Griffiths negative if $\sum (\Theta_{jk} s, s) v_j \bar{v}_k \leq 0$ for any section $s$ of $E$ and
any tangent vector $v = \sum v_j \frac{\partial}{\partial x_j}$.
Notice that $\Theta_{h'} = \Theta_{h} - A\omega_x$,
where $\omega_x$ is the standard Kähler form on $U \subset \C^N_x$.
By possibly shrinking $U$, we may choose $A$ such that
$|\sum (\Theta_{jk} s, s) v_j \bar{v}_k| \leq A|s|^2 |v|^2$,
which implies that $h'$ is Griffiths negative.
\end{proof}



The statement means that locally there is a negative line bundle $L_A\to U$ such that $E\otimes L_A$ is Griffiths negative.
It is well-known that if $(E,h)$ is Griffiths negative, then $\log|\alpha|^2_h$ is psh on $E$, see, e.g., \cite{BePa}. Thus we have

\begin{cor}\label{sinister}
Any vector bundle with a smooth Hermitian metric is \qas.
\end{cor}




\begin{lma}\label{knepig0}
(i) If $\tau\colon W\to X$ is holomorphic and $E\to X$ is \qas, then $\tau^*E\to W$ is \qas.

\smallskip
\noindent
(ii) If $g\colon E\to F$ is a bundle morphism and $F$ is \qas, then $E$ is \qas\ if equipped with the induced
metric $|\alpha|:=|g(x)\alpha|$.

\smallskip
\noindent
(iii) If $E_j\to X$, $j=1,2$, are \qas, then $E_1\oplus E_2\to X$ is \qas.


\smallskip
\noindent
(iv)
If $E\to X$ has two \qas\ metrics $h_1$ and $h_2$, then $h_1+h_2$ is \qas. That is,
$|\alpha|^2=|\alpha|^2_{h_1}+|\alpha|^2_{h_2}$ is \qas.

\smallskip
\noindent
(v)
If $L$ is a \qas\ line bundle, and $E$ is a \qas\ vector bundle, then $E\otimes L$ is \qas.
\end{lma}

\begin{proof}
If $\tau\colon W\to X$, then $|\tau^*\alpha|^2_{\tau^*h}=\tau^*|\alpha|^2_h$ so (i) follows from
Lemma~\ref{lemur}.
%
To see (ii), consider the holomorphic mapping $E\to F$, $(x,\alpha)\mapsto (x,g(x)\alpha)$. Since the pullback
under a holomorphic mapping preserves the property \qas, (ii) follows.


Locally $E_j=X\times \C_{\alpha_j}^{r_j}$. If $\log |\alpha_j|^2$ is \qas\ on $E_j$, for $j=1,2$,
then so is its pullback to $E_1\oplus E_2$.
Thus $\log|\alpha_j|^2$ is \qas\ on $E_1\oplus E_2$, so that by
Lemma~\ref{proviant},
$\log(|\alpha_1|^2 +|\alpha_2|^2)$ is \qas\ on $E_1\oplus E_2$.
We get (iv) by applying (i) and (iii) to $(E,h_1)$, $(E,h_2)$ and
the mapping
$
E\to E\oplus E; \  \   \alpha\mapsto (\alpha,\alpha).
$
For (v), note that if $e_L$ is a local frame for $L$, and $e^{\psi_L}$ the corresponding representation
of the metric, then
$\log |\alpha \otimes e_L|^2 = \log |\alpha|^2 + \psi_L$, so
(v) follows by Lemma~\ref{proviant}.
\end{proof}

\begin{remark}
We say that a function is $\Q$-\qas\ or $\R$-\qas\ if
it is qpsh with analytic singularities, and the local constants $c$ in \eqref{totem1}
are in $\Q_{\geq 0}$ or $\R_{\geq 0}$, and that a vector bundle is
$\Q$-\qas\ or $\R$-\qas\ if $\alpha \mapsto \log |\alpha|^2$ is of the corresponding class.

Note that Lemma~\ref{lemur} holds for $\Q$-\qas\ and $\R$-\qas\ functions,
and consequently Lemma~\ref{knepig0} (i)-(ii) holds for $\Q$-\qas\ and $\R$-\qas\ metrics.
We also have that Lemma~\ref{proviant} holds for $\Q$-\qas\ functions, but not necessarily
for $\R$-\qas\ functions (since $c_1 \log |f_1|^2 + c_2 \log |f_2|^2$ and $\log (|f_1|^{2c_1}+|f_2|^{2c_2})$ do not necessarily have analytic singularities if $c_1$ and $c_2$ are linearly independent over $\Q$).
%
Consequently, the corresponding version of Lemma~\ref{knepig0} (iii)-(v) holds for $\Q$-\qas\ metrics,
but not necessarily for $\R$-\qas\ metrics.
\end{remark}





\begin{lma}\label{knepig1}
%Assume that
For any $x_0\in X$, there is a \nbh $U\subset X$ and holomorphic $F_k(x,\alpha)=f_k(x)\cdot \alpha$
in $E|_U\simeq U\times \C^r_\alpha$, $k=1,\ldots, m$,
such that
\begin{equation}\label{garn}
\sum_{k=1}^m |F_k(x, \alpha)|\sim |\alpha|_{h(x)}.
\end{equation}
%in $U\times \C^r$.
\end{lma}

\begin{proof}
Assuming say that $x_0 = 0 \in \C^N$ in a local embedding, by the assumption of analytic singularities,
there are holomorphic functions $F_k(x,\alpha)$ in a set $|x|\le c, |\alpha|\le c,\ c > 0$ such that
\eqref{garn} holds. Since $F_k(x,0)=0$ we have that $F_k(x,\alpha)=f_k(x)\cdot \alpha+F'_k$, where
$F'_k$ is $\Ok(|\alpha|_0^2)$ (where $|\alpha|_0^2$ denotes the trivial metric on $\C^r_\alpha$).
We write the tuple as $F=f(x)\cdot\alpha+F'$. For $x\le c$, $|\alpha|=c$ and $|\lambda|\leq 1$, we have
$$
F(x,\lambda \alpha)= \lambda f(x)\cdot\alpha+\Ok(|\lambda|^2).
$$
Thus
$$
|\lambda||\alpha|_{h(x)}\le C|F(x,\lambda \alpha)|\le C| \lambda|| f(x)\cdot\alpha|+C|\lambda|^2,
$$
%so that
%$$
%|\alpha|_{h(x)}\le C|F(x,\lambda \alpha)|\le C| F'(x,\alpha)|+C|\lambda| |F''(x,\alpha)|,
%$$
so that
$$
|\alpha|_{h(x)}\le C| f(x)\cdot \alpha|, \quad |\alpha|=c, \ |x|\le c.
$$
By homogeneity this holds for all $\alpha$. In the same way we get the opposite estimate.
Thus \eqref{garn} holds with $f(x)\cdot\alpha$ instead of $F(x,\alpha)$.
However,
$f(x)\cdot\alpha$ is defined in the whole set $U\times \C^r$ and \eqref{garn} holds there by homogeneity.
%%%
 \end{proof}
Thus at least locally in $x$, $|\cdot|_h^2 $ is comparable with a metric as in Example~\ref{modelex}.



\begin{prop}\label{taubunt}
If $(E,h)$ is \qas, then $(L_E,e^\psi)$ is \qas.
\end{prop}

\begin{proof}
Indeed, by cf.~\eqref{phiform}, $\psi$ is \qas\ on $\Pk(E)$ if
$\log|\alpha|_h^2$ is \qas\ on $E$, or in fact even on $E\setminus 0_E$.
\end{proof}

Notice by the way that $E$ is Griffiths negative, i.e., $\psi$ is psh, if and only if
$e^\psi$ is a negatively curved metric.

\begin{remark}\label{viktig}
Almost all results in this paper only depend on that $L_E$ is \qas.
At a few places, Lemma~\ref{knepig0}~(ii)-(iii) and Lemma~\ref{knepig1},
and the part of Theorem~\ref{main1} that the multiplicities are non-negative,
we need the (possibly) stronger assumption that $E$ is \qas.
The remainder of
the results in the article which are formulated for \qas\ vector bundles $E$ indeed
hold if $L_E$ is assumed to be \qas.

In \cite{LRSW}, the standing assumption is that $E$ is equipped with a metric $h$ such that
the induced metric on $L_E$ is psh with analytic singularities. Note that by
\cite[Proposition~5.4]{LRSW}, this is equivalent to $\log |\alpha|_h^2$
being psh with analytic singularities on $E \setminus 0_E$. The same arguments
yield the corresponding statement when psh is replaced by qpsh, i.e.,
for \qas\ metrics and functions.
For such metrics, similarly to \cite[Proposition~5.2]{LRSW}, one may
show that if the metric on $L_E$ is \qas, then $\log |\alpha|_h^2$ is
in fact qpsh on all of $E$. However we do not know if $\log |\alpha|_h^2$
has analytic singularities over $0_E$, so it is indeed possibly a stronger
assumption that $E$ is \qas.

The results mentioned above where we need to assume that $E$ is \qas\ do not appear
in \cite{LRSW}. However, if $L_E$ has a psh metric with analytic singularities, then
the Lelong numbers of Segre forms are non-negative. Indeed, since the Lelong numbers
do not depend on the choice of reference metric, we may may locally choose a negatively curved
reference metric, and then $s_k(E,h,h_0)$ is a positive $(k,k)$-current, and hence it has
non-negative Lelong numbers.

If the following generalization of Lemma~\ref{orkan} to the case when $L_E$ is \qas\ holds,
then it would imply that $E$ may be equipped with a singular metric $h'$ comparable to $h$
which is such that induced metric on $L_E$ is psh with analytic singularities, and
in particular, $s_k(E,h,h_0)$ would have non-negative Lelong numbers also under this assumption.
The generalization of Lemma~\ref{orkan} is as follows: If $E$ is equipped with a singular
metric $h$ such that $L_E$ is \qas, then $h e^{A|x|^2}$ is a Griffiths negative singular metric
in a neighborhood of $x_0$ for $A$ large enough, i.e., the induced metric on $L_E$ is psh.
We do not know whether it holds.
\end{remark}












\section{Generalized cycles and quasi-cycles}\label{qzsection}


Let $Y$ be a complex manifold or a reduced analytic space.
In \cite{AESWY} was introduced the $\Zk$-module $\GZ(Y)$ of generalized cycles,
which are currents on $Y$, and which is an extension of the module $\Z(Y)$ of analytic cycles,
that is, there is an injective mapping $i\colon \Z(Y)\to \GZ(Y)$, if the elements in
$\Z(Y)$ are identified with their associated Lelong currents.
It was shown that many properties of $\Z(Y)$ such as unique decomposition into irreducible components,
well-defined integer multiplicities at each point etc., hold for $\GZ(Y)$ as well.

Recall that if $Y$ is a reduced analytic space, then smooth forms on $Y$ are
defined in terms of restrictions of smooth forms in local embeddings, cf. e.g.
\cite{ASSmooth}, and currents as the appropriate dual of smooth compactly supported forms.

Let $\QZ(Y)$ be the $\mathbb{Z}$-module of locally finite sums of currents of the form
$\tau_* \gamma$, where $\tau \colon W \to Y$ is a proper holomorphic mapping, $W$ is a complex manifold,
and $\gamma$ is a current on $W$ of the form
\begin{equation} \label{na}
	\gamma=dd^c b_1 \wedge \cdots \wedge dd^c b_p,
\end{equation}
where $e^{b_j}$ are metrics on holomorphic line bundles $L_j$ over $W$
such that $b_j$ are locally bounded and qpsh.
We say that the elements in $\QZ(Y)$ are quasi-cycles on $Y$.


\begin{remark}
If we assume all $b_j$ are smooth we get precisely the module $\GZ(Y)$,
cf.~ \cite[Remark~3.1]{AESWY}, which is thus a submodule of $\QZ(Y)$.
\end{remark}


\begin{remark}
One can just as well consider the corresponding $\Q$-module or $\R$-module that we denote by
$\QZ_\Q(Y)$ and $\QZ_\R(Y)$, respectively. It is natural to refer to the elements as rational
and real quasi-cycles, respectively.
\end{remark}



The product \eqref{na}, defined by Bedford and Taylor, is a closed current of
order $0$. %if all the $b_j$ are qpsh and bounded.
It follows that any $\mu\in\QZ(Y)$ is a closed current of order $0$.
In particular, such currents may be multiplied with characteristic functions $\1_{V}$,
if $V$ is an analytic subset of $W$.
If $\tau \colon Y' \to Y$ is a proper map, and $\mu \in \GGZ(Y')$, then $\tau_* \mu \in \GGZ(Y)$.





\smallskip
Most results in $\GZ(Y)$ from \cite{AESWY} extend to $\QZ(Y)$,
with the same arguments, because of the following
three properties of mixed Monge-Ampère products of the form \eqref{na}:
%






\begin{lma}\label{elbas}
	Let $e^{b_1},\ldots,e^{b_k}$ be metrics on line bundles $L_1,\dots,L_k$ on a
    complex manifold $W$ such that $b_1,\dots,b_k$ are locally bounded qpsh.

\smallskip
\noindent (i)	If $i\colon V\to W$ is an analytic subspace of positive codimension, then
	\begin{equation} \label{eq:BTprop1}
		\1_V dd^c b_1 \wedge \cdots \wedge dd^c b_k = 0.
	\end{equation}

\smallskip
\noindent
(ii)	If $i\colon V \to W$ is as in (ii), then
	\begin{equation} \label{eq:BTprop2}
		dd^c b_1 \wedge \cdots \wedge dd^c b_k \wedge [V] =
		i_*( dd^c i^*b_1 \wedge \cdots \wedge dd^c i^*b_k).
	\end{equation}

\smallskip
\noindent
(iii)	If $W$ is compact and $k=\dim W$, then
	\begin{equation} \label{eq:BTprop3}
		\int_W dd^c b_1 \wedge \cdots \wedge dd^c b_k = \int_W c_1(L_1) \wedge \cdots \wedge c_1(L_k).
	\end{equation}
\end{lma}

Here $c_1(L_j)$ denotes the Chern class of $L_j$, which can be represented by the
first Chern forms associated with any smooth Hermitian metric on $L_j$.



\begin{proof}
%
It is well-known from the theory of Monge-Ampère products due to Bedford-Taylor, \cite{BT},
that such products do not charge pluripolar sets, cf. also, e.g., \cite[Proposition III.3.11]{Dem},
so in particular \eqref{eq:BTprop1} holds.
The equality \eqref{eq:BTprop2} is a local statement and follows by a suitable regularization,
see, \cite[Lemma~3.4]{AWpascal}.
The last equality, \eqref{eq:BTprop3}, is well-known in case all $b_j$ are smooth. Here is
a sketch of an argument in our case.
If $\beta_j$ are smooth metrics, then $b_j-\beta_j$ are global functions.
We prove by induction that \eqref{eq:BTprop3} holds if $b_1,\ldots, b_\ell$ are replaced by $\beta_1,\ldots \beta_{\ell}$ for $1\le \ell\le k$.
Assume it is true for	 $\ell-1$. Then by the commutativity of Monge-Ampère products it is enough to verify, with
$u=b_\ell-\beta_\ell$, that
$$
dd^c (uT)=dd^c b_\ell\w T- dd^c\beta_\ell\w T
$$
if $T$ is any positive closed current. This is a local statement and follows from \cite[Proposition~III.4.9]{Dem} since locally $u=\hat b_\ell-\hat\beta_\ell$,
where $\hat b_\ell$ is psh and bounded, and $\hat\beta_\ell$ is smooth.
Now the induction step follows from Stokes' theorem.
\end{proof}







Using \eqref{eq:BTprop1}, it follows as in \cite[Lemma~3.2]{AESWY} that
if $V \hookrightarrow Y$ is an analytic subspace, and $\mu \in \GGZ(Y)$,
then $\1_V \mu \in \GGZ(Y)$.
Indeed, if
\begin{equation}\label{muform}
\mu = \sum (\tau_j)_* \gamma_j,
\end{equation}
where $\tau_j : W_j \to Y$, then
\begin{equation} \label{eq:restrGGZ}
    \1_V \mu = \sum_{\gamma_j(W_j) \subset V} (\tau_j)_* \gamma_j.
\end{equation}

\begin{prop}\label{tax}
Assume that $i\colon V\to Y$ is an analytic subspace. Then the image of $i_*\colon \QZ(V)\to \QZ(Y)$
is precisely the elements in $\QZ(Y)$ that have Zariski support on $V$.
\end{prop}


The proof is precisely the same as for the analogous statement for $\GZ(Y)$,
\cite[Proposition~3.6]{AESWY}.






\begin{ex}\label{pudel}
If $\mu\in \QZ(Y)$ has support at $x\in Y$, then since it has order $0$ it must be a number times $[x]$. In view of Proposition~\ref{tax}
this number is a finite sum of numbers $\alpha=\int \tau_*\gamma$, where $\tau(W)=\{x\}$. Now
$$
\alpha=\int_Y \tau_*\gamma=\int_W \gamma
$$
which is an intersection number, cf.~\eqref{eq:BTprop3}, and hence an integer.
\end{ex}













\subsection{Monge-Ampère type products as homomorphisms on $\QZ(Y)$} \label{MAhom}

Let $u$ be a \qas\ function on the complex manifold $Y$.
Let $\pi\colon Y'\to Y$ be a modification which principalizes the ideals associated to $\pi^* u$, i.e.,
such that in any local representation \eqref{totem1}, $f$ defines a principal ideal.
Such a modification indeed exists. In the case of integral analytic singularities,
note first that we may always choose $c=1$ in \eqref{totem1}. If we then have two different
such representations with $f$ and $f'$, then $\log(|f'|^2/|f|^2)$ is locally bounded,
i.e., $|f'|\sim |f|$. If we let $\J$ denote the integral closure of the ideal generated by $f$,
we thus obtain a well-defined coherent ideal sheaf on $Y$. By blowing up $\J$
(followed by a resolution of singularities if one wants $Y'$ to be smooth), one obtains
such a modification. For the case when the analytic singularities are rational or real,
see Remark~\ref{Qqas}.

We may thus assume that there is a section $\sigma$ of a holomorphic line bundle $\La\to Y'$
such that if we equip $\La$ with some Hermitian norm, then
%%
\begin{equation}\label{lemur2}
\pi^*u=\log|\sigma|^2+a,
\end{equation}
where $a$ is qpsh and locally bounded.
%%
By the
Poincar\'e-Lelong formula, $dd^c\log|\sigma|^2= [\dv \sigma]-c_1(\La)$ and hence
\begin{equation}\label{kontor}
dd^c\pi^*u=[\dv \sigma]+\nu,
\end{equation}
where $\nu=-c_1(\La)+a$ is a global current on $Y'$ of the type that occurs in \eqref{na}.



\begin{remark}\label{bong}
Note that $\nu$ does not depend on the choice of Hermitian norm on $\La$.
One can in fact incorporate $a$ into the norm on $\La$, i.e., choose a
norm $\|\cdot\|^2$ on $\La$ (with empty unbounded locus) so that
$\pi^*u=\log\|\sigma\|^2$.
\end{remark}




\begin{lma}\label{elbas2}
Assume that $\gamma$ is a product on $W$ as in \eqref{na} and $f$ is a non-trivial holomorphic function.
Then
$(\log|f|^2) \gamma$ has locally finite mass, and
$
dd^c( (\log|f|^2) \gamma)=[\dv f]\w \gamma.
$
If $u_j$ are smooth and decrease to $\log|f|^2$, then $u_j\gamma\to (\log|f|) \gamma$.
\end{lma}



\begin{proof}
The first statement follows from \cite[Theorem III.4.5]{Dem} since locally in $Y'$ all $b_j$ in $\gamma$ are
$b_j=b_j'+a_j$ where $b_j'$ are psh and bounded and $a_j$ are smooth.
%
The second and third one follow from
 \cite[Proposition III.4.9]{Dem}. % by a suitable regularization of $\log|f|^2$.
\end{proof}








\begin{prop}\label{kamaxel}
Let $u$ be a \qas\ function on $Y$ with singular set $Z$. If $\mu\in\QZ(Y)$, then
$u \1_{Y\setminus Z}\mu$ is a measure with locally finite mass and
$$
[dd^c u]\w \mu:= dd^c(u \1_{Y\setminus Z}\mu)
$$
is an element in $\QZ(Y)$.
\end{prop}


\begin{proof}
By linearity we can assume that $\mu=\tau_*\gamma$, \ $\tau\colon W\to Y$. If the image of $\tau$ is contained in $Z$,
then $\1_{Y\setminus Z} \mu=0$. Otherwise $\tau^* u \not\equiv 0$ is \qas\ on $W$ by Lemma~\ref{lemur}. Then
$$
\1_{Y\setminus Z}\mu=\tau_*(\1_{W\setminus \tau^{-1}Z} \gamma)
=\tau_*\gamma=\mu
$$
since $\tau^{-1}Z$ has
positive codimension on $W$, cf.~\eqref{eq:BTprop1}.
In view of the discussion above we may assume, after possibly performing a modification of $W$,
that $\tau^*u=\log|\sigma|^2+a$ on $W$, cf.~\eqref{lemur2}, where $a$ is locally bounded.

Since $u$ is upper semi-continuous there is a sequence $u_j$ of smooth functions that decreases to $u$.
%%
%$$
%u_j \mu=\tau_*( \tau^*u_j \gamma).
%$$
By Lemma~\ref{elbas2}, $\tau^*u_j \gamma$ tends to the locally finite measure $\tau^*u\gamma$. It follows that
$$
u\mu=\lim_j u_j \mu=\lim \tau_*( \tau^*u_j \gamma)=\tau_*(\tau^*u\gamma)
$$
is a locally finite measure. Moreover,
$dd^c( u \mu)=\tau_*( dd^c (\tau^* u \gamma))$
so it is enough to see that $dd^c (\tau^* u \gamma)$ is in $\QZ(W)$.

By \eqref{kontor} on $W$, and Lemma~\ref{elbas2},
\begin{equation}\label{baktankar}
dd^c (\tau^* u \gamma)=[\dv \sigma]\w \gamma+\nu\w\gamma.
\end{equation}
The last term in \eqref{baktankar} is of the form \eqref{na}.
Notice that $[\dv \sigma]$ is a sum of terms
$m_\ell[D_\ell]$, where $m_\ell$ are integers and $D_\ell$ are divisors in $W$.
In view of Lemma~\ref{elbas}~(ii), the first term on the right hand side of \eqref{baktankar} is therefore a finite
sum of terms
$m_\ell (i_{\ell})_*(i_\ell^* \gamma)$, where $i_\ell\colon D_\ell\to W$, and each of them is in $\QZ(W)$.
%
\end{proof}





Recursively we define
\begin{equation}%\label{boxer}
[dd^c u]^0\w \mu=\mu, \quad [dd^c u]^{k+1}\w \mu=[dd^c u]\w [dd^c u]^k\w \mu, \quad k=0,1,2, ....
 \end{equation}
 If we let\footnote{If $u=\log|\sigma|^2$, then $M^u$ is denoted by $M^\sigma$ in, e.g., \cite{AESWY}. We hope this will not cause any confusion.}
 \begin{equation}\label{bajonett}
 \la dd^c u\ra^k\w \mu:=\1_{X\setminus Z} [dd^c u]^k \w\mu, \quad M^u_k\w \mu:= \1_Z [dd^c u]^k \w\mu,
 \end{equation}
 we see that, e.g.,
 \begin{equation}\label{bajontva}
 [dd^c u]^{k+1}\w \mu =dd^c (u \la dd^c u\ra^{k}\w \mu).
 \end{equation}
 %
 Let $M^u=M^u_0+M^u_1+\cdots$. Notice that if $\mu$ has support on $Z$, then $M^u_0\w \mu=\mu$.
%

\begin{ex}\label{fantomen}
With the notation in \eqref{baktankar} in the proof of Proposition~\ref{kamaxel} we have
\begin{equation}\label{fantomen1}
[dd^c\tau^*u]^k\w\gamma=M_k^{\tau^*u}\w\gamma+ \la dd^c \tau^*u\ra^k\w\gamma=
[\dv \sigma]\w \nu^{k-1}\w\gamma+\nu^k\w\gamma.
\end{equation}
\end{ex}





%%
\begin{prop}\label{dragos}
If $\tau\colon Y'\to Y$ is a proper mapping $\mu\in\QZ(Y')$, then
\begin{multline}\label{oxel}
 [dd^c u]^{k}\w \tau_*\mu= \tau_*\big([dd^c \tau^* u]^k\w \mu\big), \quad  \la dd^c u\ra^{k}\w \tau_*\mu= \tau_*\big(\la dd^c \tau^* u\ra^k \w \mu\big), \\
 \quad M_k^u\w \tau_* \mu= \tau_*\big( M_k^{\tau^*u}\w \mu\big), \quad k=0,1,2,\ldots.
\end{multline}
\end{prop}




\begin{proof}
The case $k=0$ is trivial, and by induction
it is enough to consider $k=1$. Then the proposition follows from the equalities $\1_Z \tau_* \mu=\tau_*(\1_{\tau^{-1}Z} \mu)$ and %thus
$$
dd^c( u_j \1_{Y\setminus Z} \tau_*\mu)=\tau_* \big(dd^c (\tau^*u_j \1_{Y'\setminus \tau^{-1}Z} \mu)\big),
$$
where $u_j$ is a sequence of smooth functions as in the proof of Proposition~\ref{kamaxel}.
\end{proof}






\begin{remark} \label{Qqas}
If $u$ is $\mathbb{Q}$-\qas\ or $\mathbb{R}$-\qas, we claim that one may indeed
also in this case find a modification $\pi : Y' \to Y$ such that in the
local representations \eqref{totem1} of $\pi^* u$, the ideal generated by
$f$ is principal. It then follows readily that the results in
this section hold for such $u$ when $\QZ$ is replaced by $\QZ_\Q$ or $\QZ_\R$.

To prove the claim, we first claim that there is a well-defined minimal modification
$\pi'' : Y'' \to Y$, where $Y''$ is normal and such that the ideal generated by $f$ in the local
representation \eqref{totem1} of $\pi^* u$ is principal. Given such a modification,
one obtains $\pi : Y' \to Y$ by possible taking the corresponding reduced space,
and taking a resolution of singularities $\pi' : Y' \to Y''$.

If $u$ is $\Q$-\qas, then one readily verifies that $Y''$ may be defined locally by
blowing up the ideal generated by $f$ in the local representation \eqref{totem1} of $u$
followed by the normalization. Given two representations \eqref{totem1} with
$c,f$ and $c',f'$, they will be such that $|f'| \sim |f|^{c/c'}$, where $c/c' \in \Q$,
and then it follows by the following well-known facts that the above procedure
is well-defined:
If $\J \subset \Ok_Y$ is a coherent ideal, and $\bar{\J}$ denotes its integral closure, and $\Bl^+_\J Y$ denotes the normalization of the blowup of $\J$, then
$\Bl^+_{\J^k} Y = \Bl^+_\J Y = \Bl^+_{\bar{\J}} Y$ for $k \geq 1$.

If $u$ is $\R$-\qas, then given two representations \eqref{totem1} with $c,f$ and $c',f'$,
then if $x \in Z(f)=Z(f')$, the Lelong number $\nu(x,u)$ is a positive integer times $c$ and
an positive integer times $c'$, and hence, $c/c' \in \Q$, and one may reduce to the rational case.
\end{remark}









\subsection{Action of smooth Segre and Chern forms}
Notice that if $L\to X$ is a line bundle with a smooth Hermitian metric $e^\psi$,
then $c_1(L,e^\psi)$ defines an endomorphism $\c_1(L,e^\psi)$ on currents acting as multiplication
by the smooth form $c_1(L,e^\psi)$. Moreover, if
$\mu=\tau_*\gamma$, then $c_1(L,e^\psi)\w \tau_*\gamma=\tau_*(c_1(\tau^*L,\tau^*e^{\psi})\w\gamma)$
and hence $\c_1(L,e^\psi)$ yields an endomorphism on $\QZ(X)$. We also have the endomorphism
$\s_1(L,e^\psi)=-\c_1(L,e^\psi)$.

%
Let $E\to X$ be a Hermitian holomorphic vector bundle. Since $p\colon \Pk(E)\to X$ is a submersion,
there is a well-defined morphism $p^*$ mapping currents on $X$ to currents on $\Pk(E)$ such that
$p_*\xi \w \mu=p_*(\xi\w p^*\mu)$
for smooth forms $\xi$ on $\Pk(E)$.
%

\begin{lma}\label{tomte1}
We have
$$
p^*\colon \QZ(X)\to \QZ(\Pk(E)).
$$
\end{lma}

\begin{proof}
By functoriality
we have the commutative diagram
\begin{equation}\label{dia23}
\begin{array}[c]{cccc}
 \Pk(\tau^*E) &  \stackrel{\tau'}{\longrightarrow}  & \Pk(E) \\
\downarrow \scriptstyle{p'} & &  \downarrow \scriptstyle{p}  \\
W & \stackrel{\tau}{\longrightarrow}  & X.
\end{array}
\end{equation}
If  $\mu=\tau_*\gamma$, thus $p^*\mu=\tau'_* (p')^*\gamma$, which is an element in $\QZ(\Pk(E))$.
%
 \end{proof}

Since $s(E,h)=p_*s(L_E,e^\psi)$,
for any current $\mu$ on $X$,
\begin{equation}\label{toka}
s(E,h)\w \mu= p_* s(L_E,e^\psi)\w \mu=p_*(s(L_E,e^\psi)\w p^*\mu).
\end{equation}
It follows from the lemma that \eqref{toka} defines endomorphisms
\begin{equation}\label{kraka}
\s_k(E,h)\colon \QZ(X)\to \QZ(X), \quad k=0,1,\ldots,
\end{equation}
where
$\s_k(E,h)\w\mu:= p_*(s_1(L_E,e^\psi)^{k+r-1}\w p^*\mu)$.
%
In the same way we have endomorphisms
\begin{equation}\label{kraka1}
\c_k(E,h)\colon \QZ(X)\to \QZ(X), \quad k=0,1, \ldots
\end{equation}
defined by suitable compositions, cf.~\eqref{cformel}.
Since these operators are just multiplication by $s_k(E,h)$ and $c_k(E,h)$, in particular we have that
$\c_0(E,h)=\s_0(E,h)=I$, the identity on $\QZ(X)$.

%






\subsection{The submodule $\QZ_0(Y)$}


Let $0\to S\to E\to Q\to 0$ be a short exact sequence of holomorphic vector bundles over a complex manifold $W$ with the metrics induced by a smooth metric
on $E$. Then, by \cite{BC}, for each component
$\beta=(c(E)-c(S)c(Q))_k$ there is smooth form $v$ on $W$ such that
$dd^c v=\beta$.
%We say that such a $\beta$ is a BC-form.
It follows from \eqref{kraka1} that $\beta$ induces an endomorphism
$\QZ(W)\to \QZ(W)$, \ $\mu\mapsto \beta\w \mu$.
%%

Let $L$ be a holomorphic line bundle over $W$ with two different metrics $e^b$ and $e^{b'}$,
where $b'$ is assumed to be smooth, and $b$ is qpsh and locally bounded. Then $v=b-b'$ is a
locally bounded qpsh function, and thus $e^v$ may be considered as a metric on the trivial line bundle.
Let $\beta:=dd^c b'-dd^c b=dd^c v$. Again we have a mapping $\QZ(W)\to \QZ(W)$, \ $\mu\mapsto \beta\w \mu$.
We say that any of these two forms $\beta$ is a beta form.


\begin{df}
We let $\QZ_0(Y)$ be the submodule of $\QZ(Y)$ generated by all currents of the form
$\tau_*\mu'$, $\tau\colon W\to Y$, where $\mu'$ is in the image of one of the mappings $\beta$ above.
\end{df}

Thus  $\QZ_0(Y)$ is generated by all $\tau_*(\beta\w\gamma)$
where $\beta$ is a beta form and $\gamma$ is a product of the form \eqref{na}.
For each such form there is a locally bounded function $v$ such that
\begin{equation}\label{parasoll}
dd^c \tau_*(v\w\gamma)=\tau_*(\beta\gamma).
\end{equation}





 \begin{remark}
 Since the pullback of a beta form is a beta form, the module $\QZ_0(Y)$ is actually generated by all currents
 $\tau_*\gamma$, where $\gamma$ is as in \eqref{na} but with at least one factor $dd^c b_j$
 'replaced' by a beta form.
\end{remark}




If $\tau\colon Y'\to Y$ is a proper mapping, then $\tau_*\colon \QZ_0(Y')\to \QZ_0(Y)$.
In view of \eqref{eq:restrGGZ}, for any analytic subspace $V\subset Y$ we have that
\begin{equation}\label{stare}
\1_V \colon \QZ_0(Y)\to \QZ_0(Y).
\end{equation}

\begin{remark} \label{remQZ0Support}
Assume that $\mu\in \QZ_0(Y)$, and $\mu$ support on the analytic subspace $V \subset Y$.
It then follows from Proposition~\ref{tax} and \eqref{parasoll} that there is
a current $w$ of order $0$ which is the pushforward of a current on $V$
such that $dd^c w=\mu$.

In particular, if
$\mu\in \QZ_0(Y)$ has support at a point $x$ therefore
\begin{equation}\label{tomat}
\int_X \mu =\int_X dd^c w=0,
\end{equation}
and since $\mu=\alpha [x]$, cf.~Example~\ref{pudel},  $\mu=0$.
\end{remark}





\begin{prop}\label{ekorre}
(i) If $u$ is a \qas\ function on $Y$, then
$$
[dd^c u]^k\colon \QZ_0(Y)\to \QZ_0(Y), \quad k=0,1,2,\ldots.
$$
(ii)
If $u'$ is \qas\ and $u'=u+\Ok(1)$ locally on $Y$, then
$$
[dd^c u]^k-[dd^c u']^k \colon \QZ(Y)\to \QZ_0(Y), \quad k=0,1,2,\ldots.
$$
(iii) The mapping $p^*$ in Lemma~\ref{tomte1} maps $\QZ_0(X)\to \QZ_0(\Pk(E))$. \newline
\end{prop}

\begin{proof}
Recall that if $\mu$ has support in $Z$, then
$[dd^c u]\w \mu=0$. Otherwise, assume that $\mu=\tau_* (\beta\w \gamma)$ where $\gamma$ is product as in \eqref{na}
and $\beta$ is a beta form. As in the proof of Proposition~\ref{kamaxel} we can therefore assume, cf.~\eqref{baktankar},
that
\begin{equation}\label{skunk}
[dd^c u]\w \mu =\tau_*\big([\dv\sigma]\w \beta\w\gamma+\nu\w\beta\w\gamma\big).
\end{equation}
If $i\colon D\to W$, then $i^*(\beta\w \gamma)=i^*\beta\w i^*\gamma$ and thus
$[\dv\sigma]\w \beta\w \gamma$ is in $\QZ_0(W)$.
%that $[dd^c u]\w\mu$ is the push-forward of such forms, since if $i\colon D\to W$, then $i^*(\beta\w \gamma)$ is such a form.
Thus (i) holds for $k=1$ and hence for a general $k$ by induction.


\smallskip
By (i) and a simple induction over $k$ it is enough to prove (ii) for $k=1$. Let us assume that $\mu=\tau_*\gamma$, $\tau\colon W\to Y$.
After a suitable further modification we can assume that $\tau^*u=\log|\sigma|^2+a$ and $\tau^*u'=\log|\sigma'|^2+a'$ in $W$
where $a$ and $a'$ are locally bounded.
The assumption in (ii) implies that $[\dv\sigma']=[\dv\sigma]$.
If $a''$ is some smooth metric on the line bundle corresponding to those divisors, then
$dd^c(a-a')=dd^c(a-a'')-dd^c(a'-a'')=\beta-\beta'$ where both $\beta$ and $\beta'$ are beta forms on $W$.
%
Therefore,
$$
([dd^c u']-[dd^c u])\w\mu= \tau_*(dd^c \tau^*u \w \gamma) -\tau_*(dd^c \tau^*u' \w \gamma)=
\tau_*(\beta\w\gamma)-\tau_*(\beta'\w\gamma)
$$
which is in $\QZ_0(Y)$.




\smallskip
Part (iii) follows from the proof of Lemma~\ref{tomte1}. In fact, if $\mu$ is in $\QZ_0(X)$, then we can assume that
 $\mu=\tau_*(\beta\w\gamma)$ where $\gamma$ is of the form \eqref{na} and $\beta$ is a beta form.
Then $p^*\mu=\tau'_* (p')^*(\beta\w\gamma)$ is in $\QZ_0(\Pk(E))$.
\end{proof}

 \begin{df}
 We define the quotient module $\QB(Y):=\QZ(Y)/\QZ_0(Y)$.
 \end{df}

The definition is analogous with the definition of the quotient module $\Ba(Y)$ of $\GZ(Y)$, see \cite{AESWY}, and there is a
natural mapping
$\mathcal \Ba(Y)\to \QB(Y)$.

%







\subsection{Multiplicities of quasi-cycles}\label{multip}

Let $\xi$ be a tuple of holomorphic functions that defines the maximal ideal at $x\in Y$.
If $\mu\in \QZ(Y)$ and $u=\log|\xi|^2$, then
$M^u\w \mu$
is in $\QZ(Y)$ and has support at $x$. Thus it has the form $\alpha [x]$
for some integer $\alpha$, cf.~Example~\ref{pudel}.
By Proposition~\ref{ekorre}~(ii) and \eqref{tomat} it follows that $\alpha$
is independent of the choice of tuple $\xi$ defining the maximal ideal.
If $\mu$ has bidegree $(k,k)$, for degree reasons, we thus have that
$M^u\w\mu=M^u_{n-k}\w \mu$.


\begin{df}
Let $\mu\in \QZ(Y)$ be a $(k,k)$-current and $x\in Y$. We define
the multiplicity of $\mu$ at $x$, $\mult_x\mu$, as
\begin{equation}\label{kastvind}
\mult_x \mu [x] =\int M^u\w \mu = \int \1_{\{x\}}(dd^c\log|\xi|^2)^{n-k} \w \mu.
\end{equation}
\end{df}


If $\mu\in \QZ_0(Y)$ then $M^u\w\mu\in \QZ_0(Y)$ by Proposition~\ref{ekorre}~(i),
and hence $\mult_x\mu=0$, cf.~\eqref{tomat}. That is,

\begin{prop}\label{gorilla}
The multiplicity $\mult_x\mu$ only depends on the class of $\mu$ in $\QB(Y)$.
\end{prop}



\begin{remark}
If $\mu$ is a positive closed current, it is clear from \eqref{kastvind},
that $\mult_x\mu$ is the Lelong number of $\mu$ at $x$.
\end{remark}





\begin{thm}\label{superman}
Assume that $\mu\in \QZ(Y)$. Then any multiplicities $\mult_x\mu$ is an integer.
If $\mu$ has bidegree $(k,k)$, then there is a unique decomposition
\begin{equation}\label{siu}
\mu=\mu_F+\mu_M,
\end{equation}
where $\mu_F$ is the Lelong current of an analytic cycle on $Y$ and the set where $\mult_x \mu_M$
does not vanish is contained in an analytic set of codimension $\ge k+1$.
\end{thm}

If $\mu'$ defines the same class in $\QB(Y)$, then, cf.~Proposition~\ref{gorilla}, it has the same multiplicities. It follows
from the theorem that
$\mu'_F=\mu_F$. Clearly $\mu'_M$ and $\mu_M$ may differ, but they still have the same multiplicities at
each point. We say that $\mu_F$ is the {\it fixed} part and $\mu_M$ is the {\it moving} part of the class of $\mu$ in $\QB(Y)$.





\begin{proof}
Indeed, it follows from Example~\ref{pudel} that $\mult_x \mu$ is an integer.
Since we know that $\mult_x\mu$ is integer valued, \eqref{siu} follows directly from the
Siu decomposition in case $\mu$ is a positive current.
As in the case with $\mu\in\GZ(Y)$, if $\mu=\tau_*\gamma$, and
$\tau=i\circ\tau'$, where $\tau'\colon W\to Z$ is surjective, then
$\mult_x \tau'_*\gamma=\mult_{i(x)}\tau_*\gamma$. Moreover,
\cite[Lemma~7.3]{Asommar} holds, with the same proof, for $\mu=\tau_*\gamma$ if
$\gamma$ is as in \eqref{na}. In fact, the crucial point that $M^{\tau^*\xi}\w \gamma=0$
if $M^{\tau^*\xi}=M^{\tau^*\xi}\w 1=0$. To see this we can assume that $\xi$ is a tuple of functions
(i.e., a section of a vector bundle with trivial metric) in a \nbh
of $x$. Then $M^{\tau^*\xi}$ is a positive current.
If $b_\ell$ is locally of the form $u_\ell + g_\ell$, where $u_\ell$ is psh, and $g_\ell$ is smooth,
we may take a sequence $b_\ell^j = u_\ell^j + g_\ell$, where each $u_\ell^j$ is psh, and
$u_\ell^j$ decreases to $u_\ell$. Then, by \cite[Proposition III.4.9]{Dem},
$M^{\tau^*\xi}\w \gamma_j\to M^{\tau^*\xi}\w \gamma$. If $M^{\tau^*\xi}=0$, thus
$M^{\tau^*\xi}\w \gamma_j=0$ and hence $M^{\tau^*\xi}\w \gamma=0$.
%
%
%
Now Theorem~\ref{superman} follows precisely as
\cite[Theorem~7.1]{Asommar}.
\end{proof}





\begin{remark} \label{multQ}
It follows that if $\mu\in\QZ_\Q(Y)$, then $\mult_x\mu$ is a rational number.
\end{remark}




\begin{ex}
Assume that $\mu\in\QZ(Y)$ has bidegree $(p,p)$ and has support on an analytic subspace
$V\subset Y$ of pure (co)dimension. Since $\mu$ is a normal current, it follows that
$\mu$ is an analytic cycle a~priori by real coefficients if $\codim V=p$, and $\mu=0$ if $\codim V>p$.
Since the multiplicities are integral we see that it is actually a cycle with integer coefficients, i.e.,
in $\Zc (Y)$. If $\mu$ is in $\QZ_0(Y)$, then all its multiplicities vanish, and hence it is $0$. Thus
$\Zc (Y)$ is indeed a submodule of $\QB(Y)$.
\end{ex}





\section{Regularization of \qas\ metrics on a line bundle}


Let $L\to Y$ be a holomorphic vector bundle, $e^{\psi_0}$ a smooth reference metric on $L$,
and let $\omega = s_1(L,e^{\psi_0})$.
Note that a singular metric $e^\psi$ on $L$ is a \qas\ if and only if the global function
$\psi-\psi_0$ is \qas.
Indeed, given a local trivialization $L \cong X \times \C_\alpha$,
$$
\psi-\psi_0 = \log |\alpha|^2_{e^\psi} - \log |\alpha|^2_{e^{\psi_0}} = \log |1|^2_{e^\psi} - \log |1|^2_{e^{\psi_0}},
$$
so if the metric $e^\psi$ is \qas, then the right-hand side is \qas\ by Lemma~\ref{lemur}.
The other direction follows by writing
$$
\log |\alpha|^2_{e^\psi} = (\psi-\psi_0) + \log |\alpha|^2_{e^{\psi_0}},
$$
and using that $\log |\alpha|^2_{e^{\psi_0}}$ is \qas.

We define the endomorphism
\begin{equation}\label{harry}
[dd^c\psi]_\omega\w\mu=[dd^c(\psi-\psi_0)]\w \mu+\omega\w\mu
\end{equation}
on $\QZ(Y)$.
It follows from Proposition~\ref{kamaxel} that \eqref{harry} indeed maps $\QZ(Y)$ to $\QZ(Y)$.

\begin{remark}
Assume that $L$ is trivial and $\psi_0=0$. Then the notation is consistent if $[dd^c\psi]=[dd^c\psi]_0$.
\end{remark}


\begin{remark}\label{exy}
If $Z=Y$, i.e., $\psi\equiv -\infty$, it is natural to let $[dd^c\psi]_\omega\w\mu=\omega\w\mu$
for all $\mu$.
\end{remark}






\begin{prop}\label{ekorre2}
(i) If $e^\psi$ is a \qas\ metric on $L\to Y$, then $[dd^c\psi]^k_\omega\colon \QZ_0(Y)\to\QZ_0(Y)$.

\smallskip
\noindent
(ii) If $e^{\psi'}$ is another \qas\ metric and $\psi'=\psi+\Ok(1)$ then
$[dd^c\psi']^k_\omega-[dd^c\psi]^k_\omega\colon \QZ(Y)\to\QZ_0(Y)$.

\smallskip
\noindent
(iii) If $\tau\colon Y'\to Y$ is a proper mapping and $\mu=\tau_*\mu'$, then
 \begin{equation}\label{harry2}
[dd^c\psi]_\omega\w\mu=\tau_*\big( [dd^c \tau^*\psi]_{\tau^*\omega}\w \mu'\big).
\end{equation}
\end{prop}


\begin{proof}
The case $k=1$ of (i) follows directly from \eqref{harry}, Proposition~\ref{ekorre}~(i),
and the fact that multiplication by $\omega$ maps $\QZ_0(Y)$ into itself.
The general
case follows by trivial induction.
Part (ii) follows direct from Proposition~\ref{ekorre}~(ii) applied to $u'=\psi'-\psi_0$
and $u=\psi-\psi_0$.
Part (iii) follows from Proposition~\ref{dragos}.
\end{proof}









Although $[dd^c\psi]_\omega$ seems to be the fundamental endomorphism, it is sometimes useful to express it
in terms of $[dd^c\psi]$ which is well-defined although $\psi$ is only a metric, not a global function.
Let $Z$ be the unbounded locus of $e^\psi$, and let $\omega=dd^c\psi_0$.
If $\mu=\1_{Y\setminus Z}\mu$, then \eqref{harry} is
$$[dd^c(\psi-\psi_0)]\w\mu+\omega\w\mu=:[dd^c\psi] \w \mu,$$
and if $\mu=\1_Z\mu$, then it is just $\omega\w\mu$.
Therefore, %It is therefore natural to write
\begin{equation}\label{harry1}
[dd^c\psi]_\omega\w\mu= [dd^c\psi]\w\1_{Y\setminus Z}\mu+\omega\w\1_Z \mu,
\end{equation}
which coincides with how the corresponding operator is defined in \cite{LRSW}.
We also have endomorphisms
$$
 \la dd^c \psi\ra^k\w \mu=\1_{Y\setminus Z} [dd^c\psi]^k\w\mu,   \quad  M^\psi_k\w\mu =\1_{Z} [dd^c\psi]^k\w\mu;
 $$
on $\QZ(Y)$.
It is readily verified by induction that
\begin{equation}\label{kusin2}
[dd^c \psi]^k_{\omega}\w\mu= \la dd^c \psi\ra^k\w \mu+\sum_{\ell=0}^k \omega^{k-\ell}\w M^{\psi}_\ell\w\mu, \quad k=0,1,2,\ldots.
 \end{equation}










\begin{thm}\label{kusin}
Let $\chi_j$ be a sequence of smooth bounded from below convex increasing functions on $\R$, which decrease
to the identity function as $j \to \infty$.
Let $e^\psi$ be a \qas\ metric on $L\to Y$, $\psi_0$ a smooth metric, and let
$\psi_j=\chi_j\circ(\psi-\psi_0) + \psi_0$.
If $\omega=dd^c\psi_0$, then for each $\mu\in\QZ(Y)$,
\begin{equation}\label{troll3}
(dd^c \psi_j )^k\w \mu \to [dd^c \psi]^k_{\omega}\w\mu, \quad j\to \infty,  \quad k=0,1,2,\ldots.
\end{equation}
\end{thm}

Since $\psi-\psi_0$ is a global function, the left hand side in \eqref{troll3} is well-defined.
The smoothness assumption on $\chi_j$ is not necessary, but for simplicity we restrict to this case, since we
will only apply the theorem to $\chi_\e(t)=\log(e^t+\e)$.

The theorem is known when $\mu$ is $1$, however expressed with the right hand side in \eqref{kusin2}.
In \cite{AWW} it is proved for a more general class of (q)psh functions. Here we will rely on the presentation in \cite{Bl} and
show that the proof given there works even when acting on a quasi-cycle $\mu$.



\begin{proof}
Since the statement is local, we can restrict to an open subset where we have a global frame element, and hence
that $\psi$ and $\psi_0$ are fixed functions. For simplicity we let $Y$ denote this open set.

We first consider the case when $\psi_0=0$.  %
If $\mu$ has support
on $Z$, then both sides of \eqref{troll3} are equal to $\omega^k \mu$.
%
Thus we can assume that $\mu=\tau^*\gamma$, where $\tau\colon W\to Y$, $\gamma$ is a product as in \eqref{na}
and $\tau^{-1} Z$ has positive codimension in $W$.
After possibly another modification we may assume that
$\tau^*\psi= \log|\sigma|^2 + a$,
where $\sigma$ is a section of a Hermitian line bundle $\L\to W$ and $a$ is qpsh and locally bounded.
We claim that %
\begin{equation}\label{viking}
(dd^c \chi_j\circ \tau^*\psi)^k \w \gamma\to [dd^c\tau^*\psi]^k\w \gamma.
\end{equation}
 %
Following \cite{Bl} there are unique convex increasing functions $\gamma_j$ such that $\gamma_j(-1)=\chi_j(-1)$ and
 $
\gamma'_j= (\chi'_j)^k.
$
It follows that also $\gamma_j(t)$ decreases to $t$. A direct computation yields
$$
(dd^c (\chi_j\circ\tau^*\psi))^k\w \gamma=dd^c( (\gamma_j\circ\tau^*\psi) \nu^{k-1}\w\gamma),
$$
where $\nu = dd^c a - c_1(\L)$.
Since $\gamma_j\circ\tau^*\psi \to \tau^*\psi$ in $L^1$ with respect to the (total variation of the) measure $\nu^{k-1}\w\gamma$, we see that
by definition,
$$
(dd^c \chi_j\circ\tau^*\psi)^k\w \gamma\to dd^c (\tau^*\psi \nu^{k-1}\w\gamma)=([\dv\sigma]+\nu)\w \nu^{k-1}\w\gamma =
[dd^c \tau^*\psi]^k\w\gamma;
$$
Here the last equality follows from Example~\ref{fantomen} and $\nu=dd^c a-c_1(\L)$.
Thus \eqref{viking} holds. Applying $\tau_*$ and using
Proposition~\ref{dragos}, now \eqref{troll3} follows for $\psi_0=0$.
 \smallskip


%
Let us now assume that $\psi_0$ is an arbitrary smooth function.
Using the case $\psi_0=0$, %we have
\begin{multline}\label{trull}
(dd^c \psi_j)^k\w\mu=\sum_{\ell=0}^k {k \choose\ell} \omega^{k-\ell} \w(dd^c \chi_j\circ(\psi-\psi_0))^\ell\w\mu\to \\
\sum_{\ell=0}^k {k\choose \ell} \omega^{k-\ell} \w [dd^c(\psi-\psi_0)]^\ell \w\mu = ([dd^c(\psi-\psi_0)]+\omega)^{k}\w\mu,
\end{multline}
where the last power is composition of the endomorphism $\mu\mapsto ([dd^c(\psi-\psi_0)]+\omega)\w\mu$ on $\QZ(Y)$.
%
Now \eqref{troll3} follows from \eqref{harry} and \eqref{trull}.
\end{proof}















\section{Segre forms and endomorphisms of \qas\ bundles}\label{segreendo}

Assume that $(E,h)$ is a \qas\ bundle over $X$. If $e^\psi$ denotes the induced
metric on $L_E$, then $\psi=\log |\alpha|^2_h$ is \qas, i.e., for any local frame
$a$ of $L_E$, i.e., the well-defined function $\log|\alpha a|^2$ is \qas.
Note that on the set where $\alpha_j \neq 0$ we may take $a=1/\alpha_j$.

Let $h_0$ be a smooth reference metric on $E$, let $e^{\psi_0}$ denote
the induced metric on $L_E$, and $\omega = dd^c \psi_0$.
We thus have that
$$
    s(L,e^{\psi_0}) = \sum_{\ell=0}^\infty\omega^\ell=\frac{1}{1-\omega}.
$$
If $Z'\subset\Pk(E)$ denotes the set where $\psi$ is not locally bounded,
then we have outside of $Z'$ that $s_1(L_E,e^\psi)=dd^c\psi$.
Recall, cf.~\eqref{harry} and \eqref{harry1}, that
\begin{equation}\label{smart1}
[dd^c \psi]_\omega\w \mu= dd^c (\psi \1_{X\setminus Z'}\mu)+\omega\w \1_{Z'} \mu
\end{equation}
defines an endomorphism on $\QZ(\Pk(E))$.
%In view of
%
In view of Lemma~\ref{tomte1} and Proposition~\ref{ekorre}~(iii)
the following definition makes sense.
%
%

\begin{df}\label{kontur}
Given a \qas\ bundle $(E,h)$ over $X$ we have the Segre endomorphisms
 $\QZ(X)\to \QZ(X)$ and $\QZ_0(X)\to \QZ_0(X)$ of degree $k$,
defined by the formula
\begin{equation}\label{torrfoder}
\s_k(E,h,h_0)\w \mu=%p_*([dd^c\psi]_\omega^{k+r-1}) \w \mu=
p_*( [dd^c\psi]_\omega^{k+r-1}\w p^*\mu),
\end{equation}
and $\s(E,h,h_0) := \sum_k \s_k(E,h,h_0)$.
 \end{df}

If $h$ is smooth, $[dd^c \psi]_\omega$ is just multiplication with the smooth
form $dd^c \psi$, so $\s_k(E,h,h_0)$ is just multiplication by the smooth form
$s_k(E,h)$, see \eqref{toka}.

\smallskip

We define the Segre form
%\footnote{Although it is not a smooth form when the metric is singular, we keep the notion 'Segre form'.}
as $s(E,h,h_0)=\s(E,h,h_0) 1$ on $X$, so that
\begin{equation}\label{segre0}
s(E,h,h_0):=p_* \sum_{k=0}^\infty p_* [dd^c\psi]^k_\omega.
\end{equation}
%
Note that if $L$ is a line bundle, then $p_L : \P(L) \to X$ is the identity.
Hence,
\begin{equation}\label{segreL}
s(E,h,h_0):= p_* s(L_E,e^\psi,e^{\psi_0}).
\end{equation}





%

\begin{remark} \label{remLRSWcomparison}
The definition of $s(E,h,h_0)$ and $\s(E,h,h_0)$ here coincides with the definition in
\cite{LRSW} except that in those articles
is used the convention that $\Pk(E)_x$ denotes the hyperplanes in $E_x$ so one has to make
some necessary adaptions. Indeed, in \cite{LRSW}, the main results are formulated
for singular metrics $h$ which are \emph{positively} curved, in contrast to the
negatively curved metrics we consider here. This difference is however essentially
artificial. For a singular metric $h$, there is an induced dual metric $h^*$ on the dual
bundle $E^*$, see e.g., \cite[Lemma~3.1]{LRRS}. By definition, a singular metric $h$ on $E$ is
Griffiths positive if $h^*$ is Griffiths negative.
%
The definition of Segre form in \cite{LRSW} is such that if $h$ is a Griffiths positive
singular metric on $E$, then it holds just as in the smooth case that
$$
   s_k(E,h,h_0) = (-1)^k s_k(E^*,h^*,h_0^*),
$$
where now the left-hand side is the Segre form defined in \cite{LRSW}, and the right-hand
side is the Segre form defined in this article.
\end{remark}

Below, we will sometimes drop $h$ and $h_0$ from the notation of the Segre forms and operators,
and consider $E$ to be a \qas\ bundle, i.e., equipped with a \qas\ metric $h$, and furthermore
a smooth reference metric $h_0$.

\smallskip


By \eqref{kusin2}, with $Y=\Pk(E)$ and $Z=Z'$, we have
\begin{multline}\label{rakning}
\sum_{k=0}^\infty	 [dd^c \psi]^k_\omega \w\mu
	 =\sum_{k=0}^\infty \la dd^c \psi\ra^k	\w \mu
+\sum_{\ell=0}^\infty \sum_{k=\ell}^\infty M^\psi_\ell\w (dd^c\psi_0)^{k-\ell}\w\mu=\\
%
%
\left(\sum_{k=0}^\infty \la dd^c \psi\ra^k + s(L_E,e^{\psi_0})\w M^\psi\right)\w\mu.
\end{multline}
%
Thus
\begin{equation}\label{segre}
\s(E,h,h_0)\w\mu=\sum_{\ell=0}^\infty p_* (\la dd^c\psi\ra^\ell\w p^*\mu) + p_*\big(s(L_E,e^{\psi_0})\w M^\psi \w p^*\mu\big).
%
\end{equation}

\smallskip


We may decompose $\s_k(E,h,h_0) \w \mu$ as
$$
    \s_k'(E,h,h_0)\w \mu + M^{E,h,h_0} \w \mu := \1_{X\setminus Z} \s_k(E,h,h_0) \w \mu + \1_Z \s_k(E,h,h_0) \w \mu.
$$
By \eqref{segre}, it follows that
$$
s_k'(E,h,h_0)\w \mu = p_* (\la dd^c\psi\ra^\ell\w p^*\mu) \text{ and }
M^{E,h,h_0}_k \w \mu = s(L_E,e^{\psi_0})\w M^\psi \w p^*\mu.
$$
In particular, it follows that $s'(E,h,h_0)$ is actually independent of $h_0$,
and may hence be denoted simply by $s'(E,h)$.


\smallskip






\begin{ex}\label{favvis0}
Let $(E,h_0)$ and $(F,h_F)$ be Hermitian vector bundles over $X$,
and let $g\colon E\to F$ be a holomorphic morphism.
Let $h$ be the singular metric on $E$ defined by
$|\alpha|_h := |g\alpha|_{h_F}$.
Recall the representation $\psi=\log|\alpha|_h^2/|\alpha_j|^2$ of the induced metric
on $L_E$, \eqref{phiform}.  In \cite{Asommar}, the corresponding representation
is denoted by $\log|\alpha|^2_\circ$. It follows from \eqref{segre},
with $\mu=1$, that the definition given in \cite[Example~9.2]{Asommar} of $s(E)$ coincides with
\eqref{segre0}.
\end{ex}



\begin{prop}\label{mainLocBdd}
Assume that $E\to X$ is a holomorphic vector bundle equipped with a locally bounded \qas\ metric
$h$. The Segre endomorphism induced by $h$ on $\QZ(X)$ is independent of the choice of
reference metric, and may thus be denoted by $\s(E,h)$.

Locally, there exists a sequence of smooth metrics $h_\epsilon$
decreasing to $h$ when $\epsilon \to 0$ such that
$$s(E,h_\e) \w \mu \to \s(E,h) \w \mu, \quad \e\to 0, \quad \mu \in \QZ(X).$$

If $h$ is of the form $h_1 \oplus h_2$, then $h_\e = (h_1)_\e \oplus (h_2)_\e$, where
$(\ )_\e$ denotes such a regularization of the corresponding metric.
\end{prop}

In case $h$ is Griffiths negative, then such a regularization may be obtained
from \cite[Proposition~3.1]{BePa} by representing $h$ as a matrix in a given
trivialization of $E$, and letting $h_\e = h \ast \rho_\e$, where $\ast$ denotes
the convolution with respect to a choice of local coordinates $x$, and $\rho_\e(x)$
is a family of radial mollifiers, and it will follow by the Bedford-Taylor theory and
the definition of $\s(E,h)$ that the corresponding currents converge.
If $h$ is just \qas, then one may instead take
\begin{equation} \label{hEpsLocBddDef}
    h_\e = h\circ \rho_\e + A \e I,
\end{equation}
where $A$ is chosen to be a large enough constant to make $h_\e$ decreasing in $\e$
when $\e \to 0$, and $I$ denotes the identity matrix.

\begin{proof}
As remarked above, $s'(E,h,h_0)$ is independent of the choice of reference metric
$h_0$. If $Z=\emptyset$, then $s(E,h,h_0)=s'(E,h,h_0)$, and hence $s(E,h,h_0)$
is also independent of $h_0$.

Fix a trivialization of $E$, and a local coordinate system $x$ on $X$ such that locally,
$E \cong \C^r_\alpha \times \C^n_x$. Define $h_\e$ by \eqref{hEpsLocBddDef}.
Note that $h_\e$ depends on both the trivialization of $E$ and the local coordinate system on $X$.
It is readily verified that a convolution of positive definite matrices is positive definite,
and the entries are smooth, so $h_\e$ indeed defines locally a smooth metric on $E$.

To prove the convergence result, assume that we are on the subset where $\alpha_j\neq 0$.
With respect to the frame induced by $\alpha/\alpha_j$ of $L_E$, the
metric $e^{\psi_\e}$ induced by $h_\e$ is represented by the function
$\psi_\e = \log |\alpha/\alpha_j|_{h_\e(x)}$.
Then
$\psi_\e$ is exactly of the form \eqref{eq:locBddQasApproximation} with
$\psi = \log |\alpha/\alpha_j|^2_{h(x)}$,
and $v = \log(|\alpha/\alpha_j|^2)$.
By Proposition~\ref{prop:locBddQasApproximation}, if $A$ is chosen large enough,
$\psi_\e$ may locally be decomposed as $u_\e + g$, where $u_\e$ and $g$ are
smooth and $u_\e$ decrease pointwise to a locally bounded function $u$.
It then follows by the Bedford-Taylor theory that
$$
    s(L_E,e^{\psi_\e}) \w \pi^* \mu = \sum_k (dd^c \psi_\e)^{k+r-1} \w p^* \mu
    \to \sum_k (dd^c \psi)^{k+r-1} \w p^* \mu.
$$
Taking the pushforward to $X$ finishes the proof of the convergence.

The statement about the case when $h = h_1\oplus h_2$ follows readily by noting that a
convolution preserves a direct sum.
\end{proof}

\begin{proof}[Proof of Proposition~\ref{propEmptyUnboundedLocus}]
Proposition~\ref{propEmptyUnboundedLocus} follows immediately from
Proposition~\ref{mainLocBdd} by taking $\mu=1$.
\end{proof}

Here is our main theorem on the Segre endomorphism $\s(E)$.

\begin{thm}\label{main11}
Assume that $E\to X$ is a holomorphic vector bundle equipped with a \qas\ metric $h$ and a smooth reference metric $h_0$, and let $Z$ be the unbounded locus of $h$.
Let $\s(E,h,h_0)$ be the associated Segre endomorphism on $\QZ(X)$.

\smallskip

\smallskip
\noindent
(i) If $h_\e$ is the metric defined by \eqref{regular1},
then
\begin{equation}\label{polo1}
\s(E,h_\e)\w \mu \to \s(E,h,h_0) \w\mu, \quad \e\to 0, \quad \mu\in \QZ(X).
\end{equation}

\smallskip
\noindent
(ii) The endomorphisms $\s_k(E,h,h_0)$ vanish for $k<0$ and $\s_0(E,h,h_0)=I$, the identity mapping.

\smallskip
\noindent
(iii) If $\tau\colon X'\to X$ is a proper mapping,
then $\tau^*h$ is \qas\
and,
\begin{equation}\label{sformel1}
\tau_*( \s(\tau^*E,\tau^*h,\tau^* h_0)\w\mu)=\s(E,h,h_0)\w \tau_*\mu, \quad \mu\in\QZ(X').
%\pi_* s(\pi^*E)=s(E).
\end{equation}





\smallskip
\noindent
(iv) For any $\mu\in \QZ(X)$ there is a current $w$ on $X$ such that
\begin{equation}\label{main2222}
(\s(E,h,h_0)- \s(E,h_0))\w\mu = dd^c w.
\end{equation}








\smallskip
\noindent (v)
If $E'\to X$ is another holomorphic vector bundle, equipped with a smooth metric $h'$,
then
\begin{equation}\label{main32}
\s(E'\oplus E,h'\oplus h,h'\oplus h_0)\w\mu= s(E',h')\w \s(E,h,h_0)\w\mu, \quad \mu\in\QZ(X).
\end{equation}



\smallskip
\noindent
(vi)
For each $k$, $\s_k(E,h,h_0)$ yields a well-defined endomorphism on $\QB(X)$,
independent of $h_0$, and
if $h'$ is a \qas\ metric on $E$ comparable to $h$, then
$\s_k(E,h',h_0)$ yields the same endomorphism as $\s_k(E,h,h_0)$ on $\QB(X)$.
%

\smallskip
\noindent
(vii)
Assume that $E_1$ and $E_2$ are \qas\ bundles, and let $Z_{E_j}$
denotes the unbounded locus of $Z_{E_j}$.
For any $k,\ell$, there is a normal current $w$,
which is the push-forward of a current on $Z_{E_1} \cap Z_{E_2}$ such that
$$
    (\s_k(E_1)\w\s_\ell(E_2)- \s_\ell(E_2)\wedge\s_k(E_1)) \wedge \mu = dd^c w.
$$
 \end{thm}


\begin{remark} \label{remMain11}
\noindent (i) If $h_0$ and $h_0'$ are two smooth reference metrics, then by the
first part of (vi), $(\s(E,h,h_0)\w \mu - \s(E,h,h_0')) \w \mu$ belongs to $\QZ_0(X)$.
Since $\s(E,h,h_0)$ and $\s(E,h,h_0')$ coincide outside of $Z$,
it follows by Remark~\ref{remQZ0Support} that there is a current $w$, which is
the pushforward of a current on $Z$ such that
\begin{equation}
\big(\s_k(E,h,h_0) - \s_k(E,h,h_0')) \w \mu = dd^c w.
\end{equation}
In particular, if $\mu$ has bidegree $(q,q)$, then $w$ has bidegree $(k+q-1,k+q-1)$,
and hence it vanishes if $k+q\leq \codim Z$.

\noindent (ii)
Note that if $\mu$ has bidegree $(q,q)$, then the current $w$ in (vii) has bidegree
$(k+\ell+q-1,k+\ell+q-1)$. Since $w$ is the push-forward of a current on $Z$,
if $k+\ell+q \leq \codim Z$, then $w$ vanishes.
\end{remark}


\begin{proof}
Notice that if $\chi_\e(t)=\log(e^t+\e)$, then
$$
\psi_\e:=\log(|\alpha|_h^2+\e|\alpha|^2_{h_0})=\log(|\alpha|_h^2/|\alpha|^2_{h_0}+\e)+\log|\alpha|^2_{h_0}=\log(e^{\psi-\psi_0}+\e)+\psi_0 = \chi_\epsilon\circ (\psi-\psi_0) + \psi_0,
$$
so it follows from Theorem~\ref{kusin} that
\begin{equation*}
(dd^c \psi_\e)^k\w p^*\mu\to [dd^c\psi]^k_\omega\w p^*\mu.
\end{equation*}
Applying $p_*$ we get \eqref{polo1} and hence (i) is proved.

%
Now (ii) follows since it holds when the metric is smooth, and hence also when it
is locally bounded \qas\ by Proposition~\ref{mainLocBdd}.



Notice that a holomorphic map $\tau \colon X'\to X$ induces a holomorphic map
$\tau\colon \Pk(\tau^*E)\to \Pk(E)$.
Part (iii) now follows from the definition \eqref{torrfoder} and
Proposition~\ref{ekorre2}~(iii).



\smallskip
In (iv) we can assume that $\mu=\tau_*\gamma$ where $\gamma$ is a product as in \eqref{na}
on $W$ and $\tau\colon W\to X$. In view of (iii) and by changing notation we have to prove
(iv) on $X$ but with $\mu= \gamma$.

If the metric on $E$ is identically $0$, i.e., $Z'=\Pk(E)$, then
$\s(E,h,h_0)=\s(E,h_0)$ and then the statement is trivial.
%
Let us thus assume that $Z'$ is not equal to $\Pk(E)$.
It may very well happen anyhow that $Z=X$.
Notice that $p^*\gamma$ is a product as in \eqref{na} on $\Pk(E)$.
Let $\psi$ and $\psi_0$ be as above.
Then $\psi-\psi_0$ is a global function on $\Pk(E)$ and, cf.~Proposition~\ref{kamaxel},
\begin{equation}\label{svin}
w'=\frac{\psi-\psi_0}{(1-dd^c\psi_0)(1-\la dd^c\psi\ra)}\w p^*\gamma
\end{equation}
is a locally finite measure. In view of \eqref{bajonett} and \eqref{bajontva} we have
\begin{equation}\label{stare11}
\1_{\Pk(E)\setminus Z'} dd^c w'= \left(\frac{1}{1-\la dd^c\psi \ra}-\frac{1}{1-dd^c\psi_0}\right) \w p^*\gamma
\end{equation}
and
\begin{equation}\label{stare12}
\1_{Z'} dd^c w'=\frac{1}{1-dd^c\psi_0}\1_{Z'} dd^c\psi \frac{1}{1-dd^c\psi} \w p^*\gamma=
s(L_E,e^{\psi_0})\w \sum_{\ell=1}^\infty M^\psi_\ell \w p^*\gamma.
\end{equation}
Notice that $Z'$ has positive codimension so that $M^\psi_0\w p^*\gamma=\1_{Z'} p^*\gamma=0$.
%
Letting $w=p_*w'$  we conclude from \eqref{segre}, \eqref{stare11} and \eqref{stare12} that
$
dd^c w=(\s(E,h,h_0)-\s(E,h_0))\wedge \mu.
$
Thus (iv) is proved.


\smallskip
To prove (v), consider the metric
$h_\e'' := (h'\oplus h) + \e(h' \oplus h_0)$,
which has empty unbounded locus. By Proposition~\ref{mainLocBdd}, we may locally find
smooth metrics $h_{\e,\e'}$
such that $\s(E,h_{\e,\e'}) \to \s(E,h_\e'')$ when $\e' \to 0$ and
$h_{\e,\e'} = ((1+\e)h')_{\e'} \oplus (h+\e h_0)_{\e'}$, where $(\ )_{\e'}$ denotes
the regularization given by Proposition~\ref{mainLocBdd} for the corresponding metric.
For each $\e' > 0$ we have
\begin{equation*}
s(E,h_{\e,\e'})=s(E,((1+\e)h')_{\e'})\w s(E,(h_\e)_{\e'}).
\end{equation*}
Multiplying this equality of smooth forms with $\mu$
and letting $\e' \to 0$, it follows that
\begin{equation}\label{struts}
\s(E,h_\e)\w \mu =s(E,(1+\e)h')\w s(E,h_\e)\w\mu.
\end{equation}
By (i) the left hand side tends to $\s(E'\oplus E,h'\oplus h,h'\oplus h_0)\w\mu$.
%
Notice that $s(E,(1+\e)h') = s(E,h')$. The right hand side of \eqref{struts} is therefore equal to
${s(E,h')\w s(E,h_\e)\w\mu}$ that tends to
$s(E,h')\w \s(E,h,h_0)\w\mu$ by (i).

\smallskip
Let $h_0'$ denote another smooth reference metric.
By \eqref{segre} we see that $\s(E,h,h_0')-\s(E,h,h_0)$ is the image under $p_*$ of
$(s(L_E,e^{\psi_0'})-s(L_E,e^{\psi_0}))\w M^\psi$, which belongs to
$\QZ_0(\Pk(E))$. Now the first statement follows.
The second one follows from
Proposition~\ref{ekorre2}~(ii) and \eqref{torrfoder}.

It remains to prove (vii).
By \eqref{segreL}, it suffices to prove the result when $(E_1,E_2,k,\ell)$ is replaced
by $(L_{E_1},L_{E_2},k+\rank E_1 -1,\ell+\rank E_2 -1)$.
We may thus simply assume that $\rank E_1 = \rank E_2 = 1$. In that case,
$\s_k = \s_1^k$, so
$$
\big(\s_k(E_1) \w \s_\ell(E_2) - \s_\ell(E_2) \w \s_k(E_1)\big) \w \mu
= (\s_1(E_1)^k \w \s_1(E_2)^\ell - \s_1(E_2)^\ell \w \s_1(E_1)^k) \w \mu.
$$
We may rewrite the right-hand side as a sum of terms of the form
$$
\mathbf{S}^+ \w \big( \s_1(E_1) \w \s_1(E_2) - \s_1(E_2) \w \s_1(E_1)\big) \w \mathbf{S}^- \w \mu,
$$
where $\mathbf{S}^+$ and $\mathbf{S}^-$ are products of $\s_1(E_1)$ and $\s_1(E_2)$.
Let $Z = Z_{E_1} \cap Z_{E_2}$. It suffices to prove that each such
term is of the form $dd^c w$, where $w$ is a current that is the
push-forward of a current on $Z$.
Since $\mathbf{S}^- \w \mu$ is in $\QZ$, we obtain by Lemma~\ref{s1comm} below a current
$w_0$, which is the push-forward of a current on $Z$ such that
$$\big(\s_1(E_1) \w \s_1(E_2) - \s_1(E_2) \w \s_1(E_1)\big) \w \mathbf{S}^- \w \mu
= dd^c w_0,
$$
where $w_0$ is current that is the push-forward of a current on $Z$.
Note that $w_0$ has support on $Z$, and both $\s_1(E_1)$ and $\s_1(E_2)$ act by multiplication
with a closed smooth form on currents in $\QZ$ with support on $Z$,
and hence $\mathbf{S}^+$ acts as multiplication with a closed smooth form $S^+_0$,
so we may take $w = S^+_0 \w w_0$.
\end{proof}

\begin{lma} \label{s1comm}
If $E_1,E_2$ are \qas\ line bundles, $Z=Z_{E_1} \cap Z_{E_2}$ denote the intersection
of the unbounded loci of $E_1$ and $E_2$. For any $\mu \in \QZ(X)$, there exists a current $w$,
which is the push-forward of a current on $Z$ such that
$$(\s_1(E_1) \w \s_1(E_2) - \s_1(E_2) \w \s_1(E_1)) \w \mu
= dd^c w,
$$

\end{lma}

\begin{proof}
By assuming that $\mu = \tau_* \gamma$, $\tau : W \to X$, and where $\gamma$ is of the form \eqref{na}, we may
assume by \eqref{sformel1}, after replacing $X$ by $W$, that $\mu$ is of the form \eqref{na}.
Let $\psi_j$ denote the metric on $E_j$, for $j=1,2$, and let $\omega_j$ denote the first Segre form of the smooth reference metric on $E_j$.
Either some of $\psi_j \equiv -\infty$,
say it is the case for $\psi_1$. Then $\s_1(E_1)$ acts by multiplication with the smooth form $\omega_1$,
which commutes with $\s_1(E_2)$, and we may take $w_0 = 0$.
Hence, we may assume that $\psi_j \not\equiv -\infty$.

As in the beginning of Section~\ref{MAhom}, we may perform a principalization of the singularities
of $\psi_j$, and after a decomposition, we may assume that
$$
dd^c \psi_j = [D_j] + [W_j] + \omega_j',
$$
where $D_j,W_j$ are divisors for $j=1,2$, $|D_1|=|D_2|$,
and $W_1,W_2,D_1$ intersect pairwise properly.

A calculation yields that
\begin{multline*}
(\s_1(E_1) \w \s_1(E_2) - \s_1(E_2) \w \s_1(E_1)) \w \mu
 \\
= (([D_1] + [W_1] + \omega_1') \wedge ([W_2] + \omega_2') + \omega_1 \wedge [D_2] -
([D_2] + [W_2] + \omega_2') \wedge ([W_1] + \omega_1') + \omega_2 \wedge [D_1])\w \mu
\\
= ([D_1] \w ([W_2]+\omega_2'-\omega_2) - [D_2] \w ([W_1]+\omega_1'-\omega_1))\w \mu.
\end{multline*}
We may choose \qas\ metrics $h_j$ on $\Ok(D_j)$ such that
$\omega_j - [W_j] - \omega_j' = s_1(\Ok(D_j),h_j)$, where the unbounded locus
of $h_j$ equals $|W_j|$.
Decompose $[D_j] = \sum d_{j,k} [D^k]$ for irreducible divisors $D_k$, and choose smooth reference metrics
on each $\Ok(D^k)$ with corresponding first Segre forms $\omega_{D^k}$. Then there is a \qas\ function
$u_j$ such that
$$
dd^c u_j = [W_j] + \omega_j' + \sum_k d_{j,k} \omega_{D_k} - \omega_j,
$$
and the set where $u_j$ is not locally bounded equals $|W_j|$.
We may then take
$$
w = (u_1 [D_2] - u_2 [D_1]) \wedge \mu,
$$
cf. the proof of Lemma~\ref{elbas2}.
Note that indeed $w$ is the push-forward of a current of order $0$ on $|D_1|=|D_2|=Z$.
\end{proof}

\begin{proof}[Proof of Theorem~\ref{main1}]
Items (i) to (v) are
covered by Theorem~\ref{main11} with $\mu=1$.

The decomposition \eqref{siu0} holds since $M^{E,h,h_0}$ is in $\QZ(X)$.
The statement about the codimension of the non-vanishing multiplicities of
$s_k'$ and $N_k$ follows from Theorem~\ref{superman}.
From Theorem~\ref{main11}~(vi) we know that $s(E,h,h_0)$ and $s(E,h',h_0')$ in (vii) are in the same
class in $\QB(X)$. Hence $M^{E,h,h_0}$ and $M^{E,h',h_0'}$ are as well by \eqref{stare}.
By Proposition~\ref{gorilla} they therefore have the same multiplicities.

We now prove that these numbers are positive. First assume that $\psi$ is psh.
In a small open \nbh $\U$ of a given point on $X$, $E=\U\times \C^r_\alpha$, and therefore
$p^{-1}\U=\U\times\Pk(\C^r_\alpha)$. Assume we choose a trivial metric $h_0$ on $E$,
which implies that $\omega_\alpha = s_1(L_E,h_0)$ is positive. Assume now that $\psi$ is psh.
In particular this holds if the metric is inherited from a morphism $g\colon E\to F$ and $F$
has a trivial metric, since then $\psi=\log|g(x)\alpha|^2$, which is psh.
In that case, $s(L_E,e^\psi,e^{\psi_0})$ will be a positive current, and hence, so will
$s(E,h,h_0) = p_*(s(L_E,e^\psi,e^{\psi_0}))$. Furthermore, all components in the decomposition
$s(E,h,h_0) = s'(E,h) + S^{E,h} + N^{E,h,h_0}$ will be positive as well, and in particular,
all their components will have non-negative Lelong numbers.

By Lemma~\ref{knepig1} any \qas\ metric $h$ on $E$ is locally equivalent to a psh metric as above,
and therefore all the concerned currents for $E$ with the metric $h$ have non-negative multiplicities.
\end{proof}

\begin{remark}\label{knepig2}
The reference to Lemma~\ref{knepig1} in last argument means that for the positivity of
the multiplicities in part (vi), we need $E$ to be \qas\ and not only that $L_E$ is \qas,
cf. Remark~\ref{viktig}. The remainder of the theorem holds assuming only that $L_E$ is \qas.
\end{remark}

\begin{remark} \label{mainQqasRcas}
Almost all of Theorem~\ref{main1} and Theorem~\ref{main11} has natural extensions
to $\Q$-\qas\ or $\R$-\qas\ metrics. Indeed, if $h$ is $\Q$-\qas\ or $\R$-\qas,
it follows readily that $\s(E)$ yields an endomorphism of $\QZ_\Q(X)$ or $\QZ_\R(X)$,
cf. Remark~\ref{Qqas}.
In that case, the multiplicities referred to in the version of Theorem~\ref{main1} would
be non-negative rational or real numbers, cf. Remark~\ref{multQ}.
\end{remark}

\begin{ex}\label{grit}
With the notation in the proof of Lemma~\ref{tomte1},
i.e., with $\mu=\tau_*\gamma$, we have
\begin{equation}\label{skrot}
\s_k(E,h,h_0)\w \mu=\Pi_*(([dd^c(\tau')^*\psi]_{(\tau')^*\omega}^{k+r-1}\w (p')^*\gamma),
\end{equation}
where the product on the right takes place on $\Pk(\tau^*E)$ and $\Pi=p\circ \tau'=\tau\circ p'$.
The order of the factors in the product on $\Pk(\tau^*E)$ is important in general.
To see \eqref{skrot} just notice that
$$
p_*( [dd^c\psi]_\omega^{k+r-1}) \w \tau'_* (p')^*\gamma)=p_*\tau'_*( [dd^c\psi]_\omega^{k+r-1}) \w (p')^*\gamma),
$$
and this holds because $\Gamma= (p')^*\gamma$ is a product as in \eqref{na} and from \eqref{harry2} therefore
$$
[dd^c\psi]^{k+r-1}_\omega \w \tau'_*\Gamma=\tau'_*\big([dd^c(\tau')^*\psi]^{k+r-1}_{(\tau')^*\omega} \w \Gamma\big).
$$

Notice that
$$
\Pk(\tau^* E)=\Pk(E)\times_X W.
$$
Consider now \eqref{dia23} with $W=\Pk(E)$ and $\tau=p$. Then we get the fiber diagram
\begin{equation}\label{dia24}
\begin{array}[c]{cccc}
Y &  \stackrel{\pi_1}{\longrightarrow}  & \Pk(E_1) \\
\downarrow \scriptstyle{\pi_2} & &  \downarrow \scriptstyle{p_1}  \\
\Pk(E_2) & \stackrel{p_2 }{\longrightarrow}  & X
\end{array}
\end{equation}
with
\begin{equation}%\label{boxer}
Y=\Pk(E_1)\times_{X} \Pk(E_2), \quad
%
\Pi=p_1\circ\pi_1=p_1\circ \pi_2\colon Y\to X,
\end{equation}
where $E_1$ and $E_2$ are distinct copies of $E \to X$.
It follows from \eqref{torrfoder} that
\begin{multline*}%\label{viktig}
\s_{\ell_2}(E,h,h_0)\w s_{\ell_1}(E,h,h_0)=\Pi_*\big( [dd^c\pi_2^* \psi_2]^{\ell_2 +r-1}_{\pi_2^*\omega_2}\w  [dd^c\pi_1^*\psi_1]^{\ell_1 +r-1}_{\pi_1^*\omega_1}\big)=\\
(p_2)_*( [dd^c\psi_2]^{\ell_2 +r-1}_{\omega_2}\w (\pi_2)_* [dd^c\pi_1^* \psi_1]^{\ell_1 +r-1}_{\pi_1^*\omega_1})=
(p_2)_*( [dd^c\psi_2]^{\ell_2 +r-1}_{\omega_2}\w p_2^*s_{\ell_1}(E,h,h_0)),
\end{multline*}
where $e^{\psi_j}$ and $e^{\psi_{j,0}}$ denote the metrics on $L_{E_j}$ induced by $h$ and $h_0$, and $\omega_j=s_1(L_{E_j},e^{\psi_{j,0}})$.
%
Consider now $\mu = \tau_* \gamma$, where $\tau : W \to X$ and $\gamma \in \QZ(W)$.
We may just as well consider $E_1, \ldots, E_k$ to be $k$ copies of $E\to X$,
$Y = W \times_X \Pk(E_1)\times_X\cdots \times_X\Pk(E_k)$,
$\pi_j\colon Y\to \Pk(E_j)$ and $\pi_0\colon Y\to W$ the natural projections.
Then, similarly to above,
\begin{equation}\label{2kryss}
\s_{\ell_k}(E,h,h_0)\w\cdots \w\s_{\ell_1}(E,h,h_0)\w \mu=\Pi_*([dd^c\pi_k^*\psi_k]_{\pi_k^*\omega_k}^{\ell_k+r-1}\w
\cdots\w [dd^c\pi_1^* \psi_1]_{\pi_1^*\omega_1}^{\ell_1+r-1}\w \pi_0^*\gamma\big).
\end{equation}
In particular, our definition of product of Segre forms coincides with the product defined in
\cite[Section~6.1]{LRSW}, cf. also Remark~\ref{remLRSWcomparison}.
\end{ex}

\begin{prop} \label{prop:locBddSegreProducts}
Assume that $h$ is a \qas\ metric on $E$ with empty unbounded locus.
Let $h_\e$ be the local regularization of $h$ from Proposition~\ref{mainLocBdd}.
If $\mu$ is in $\QZ$, then
$$
    s_{\ell_k}(E,h_\e)\w\cdots \w s_{\ell_1}(E,h_\e)\w \mu
    \to \s_{\ell_k}(E,h)\w\cdots \w\s_{\ell_1}(E,h)\w \mu.
$$
\end{prop}

\begin{proof}
Using notation from the previous example,
and arguing as in the beginning of the proof of Proposition~\ref{mainLocBdd}, it follows that
if $\mu$ is in $\QZ$, then
\begin{equation*}
\s_{\ell_k}(E,h)\w\cdots \w\s_{\ell_1}(E,h)\w \mu=\Pi_*((dd^c\pi_k^*\psi_k)^{\ell_k+r-1}\w
\cdots\w (dd^c\pi_1^* \psi_1)^{\ell_1+r-1}\w \pi_0^*\gamma\big).
\end{equation*}
Let $e^{\psi_{j,\e}}$ denote the metrics corresponding to $h_\e$.
Then,
$$
s_{\ell_k}(E,h_\e)\w\cdots \w s_{\ell_1}(E,h_\e)\w \mu=\Pi_*((dd^c\pi_k^*\psi_{k,\e})^{\ell_k+r-1}\w
\cdots\w (dd^c\pi_1^* \psi_{1,\e})^{\ell_1+r-1}\w \pi_0^*\gamma\big).
$$
Letting $\e \to 0$ yields the desired statement, just as in the proof of Proposition~\ref{mainLocBdd},
see, e.g., \cite[Theorem III.3.7]{Dem}.
\end{proof}


\section{Chern forms of \qas\ bundles}\label{csection}

Let $(E,h)$ be a \qas\ bundle, $h_0$ a smooth reference metric, and let
$\hat \s(E,h,h_0)=\s(E,h,h_0)-I$.
In this section, we will mostly drop $h$ and $h_0$ from the notation.
In view of Theorem~\ref{main11}~(ii), $\hat \s(E):=\s(E)-I=\s_1(E)+\s_2(E)+\cdots$
is an endomorphism on $\QZ(X)$ of positive bidegree.
Let $\hat \s(E)^k$ the composition of it $k$ times.
We define the Chern endomorphism
\begin{equation}\label{cherndef}
\c(E,h,h_0):=\sum_{k=0}^\infty (-1)^k \hat \s(E,h,h_0)^k =I -\hat \s(E,h,h_0)+ \hat \s(E,h,h_0)^2+\cdots.
\end{equation}
Just as for the Segre form, the Chern endomorphism yields a Chern form
$c(E,h,h_0) := \c(E,h,h_0) 1 \in \QZ(X)$. If $h$ is smooth, then $c(E,h,h_0)$
equals the usual Chern form of $h$, cf.~\eqref{cformel}.





\begin{prop}\label{main2prop}
Let $E\to X$ be an \qas\ bundle. Then

\smallskip
\noindent
(i) $\c(E)\w\s(E)=\s(E)\w\c(E)=I$.

\smallskip
\noindent
The statements in Proposition~\ref{mainLocBdd} and (ii) to (vi) of Theorem~\ref{main11}
hold if $\s(E)$ is replaced by $\c(E)$.
\end{prop}

\begin{proof}
%
Clearly $\s(E)$ and $\hat \s(E)$ commute, and hence the computation
$$
\s(E)\w\c(E)=(I+\hat\s(E))\sum_{k=0}^\infty(-1)^k \hat \s(E)^k=I,
$$
is legitimate, so that $\s(E)\w\c(E)=\c(E)\w\s(E)=I$. The other equality in (i) follows in the same way.
%%

\smallskip
The corresponding version of Proposition~\ref{mainLocBdd} with $\s(E)$ replaced
by $\c(E)$ follows from Proposition~\ref{mainLocBdd} and Proposition~\ref{prop:locBddSegreProducts}.

\smallskip
It remains to prove the corresponding statements of Theorem~\ref{main11} when
$\s(E)$ is replaced by $\c(E)$.
Part (ii) is obvious, and part (iii) for $\c(E)$ follows from (iii) for $\s(E)$.

To see (iv), notice that $\s(E,h,h_0)-\s(E,h_0)=\hat\s(E,h,h_0)-\hat\s(E,h_0)$ and that $\hat\s(E,h,h_0)$ and $\hat\s(E,h_0)$ commute.
By Theorem~\ref{main11}~(iv), for each $k$, there are $w_k$ such that
$$
dd^c w_k=(\s(E,h,h_0)-\s(E,h_0))\w \sum_{j=0}^{k-1} \hat\s(E,h,h_0)^j \w \hat\s(E,h_0)^{k-1-j}\w\mu.
$$
If $w=-w_1+w_2-\cdots$, then $dd^c w=(s(E,h,h_0)-s(E,h_0))\w\mu$.

We get (v) for $\c$ from the statement for $\s$ by a formal computation. For instance, by (i)
and (v) for $\s$, $I=\s(E'\oplus E)\w\c(E'\oplus E) =s(E')\w \s(E)\w \c(E'\oplus E)$.
Multiplying by $\c(E)$ and $\c(E')$ from the left we get
$\c(E')\w \c(E)=
\c(E'\oplus E)$.
Finally, we get (vi) for $\c$ by repeated use of (vi) for $\s$.
\end{proof}



We do not know if in general, $c_k(E)=0$ for $k>\rank E$, as it is in the smooth case.



\subsection{Chern forms for \qas\ metrics with empty unbounded locus}

Let us now assume that $h$ is a \qas\ metric with empty unbounded locus $Z$.
If $Y$ is as in the end of Example~\ref{grit}, then just as in the proof of
Proposition~\ref{prop:locBddSegreProducts}, one has a well-defined operator
\begin{equation}\label{karm}
\s_{\ell_k}(E,h) \w \cdots \w \s_{\ell_1}(E,h) 1=\Pi_*\big( (dd^c\pi_k^*\psi_k)^{\ell_k+r-1}\w\cdots\w \pi_1^*(dd^c\psi_1)^{\ell_1+r-1}\big),
\end{equation}
which is commuting in the factors, since it is the direct image of a Bedford-Taylor
product on $\Pk(E)\times_X\cdots\times_X \Pk(E)$.
In particular, one may define products of currents like
$s_{\ell_k}(E,h) \w \cdots \w s_{\ell_1}(E,h)$.
Therefore, there is a well-defined current
$$
c(E,h)=\frac{1}{s(E,h)}=1+(s_1(E,h)^2-s_2(E,h))+\cdots
$$
just as is in the smooth case. If $h_\e$ is the regularization from Proposition~\ref{mainLocBdd},
then by Proposition~\ref{prop:locBddSegreProducts}, $c(E,h) = \lim c(E,h_\epsilon)$.
In particular,
\begin{equation}
c_k(E,h)=0, \quad k>\rank E,
\end{equation}
since it holds for $c_k(E,h_\e)$.

\medskip

We do not know whether it holds for a general \qas\ metric $h$, i.e., when $h$ is
not assumed to be locally bounded, that $c_k(E,h,h_0) = 0$ for $k > \rank E$.

\subsection{An alternative endomorphism}

As will be discussed in the final section, there does not appear to exist a canonical choice of Segre or Chern
forms associated to a \qas\ metric, except for in low degrees. In this subsection, we study another choice of
an extension of a Segre form as an endomorphism of $\QZ(X)$, which in turn leads to a different choice of Chern form.
This Chern form is the one which appears in \cite{Asommar}.

Assume that $E$ is equipped with a \qas\ metric $h$, and a reference metric $h_0$.
In this section, we will mostly drop $h,h_0$ from the notation of $s(E,h,h_0)$,
and we will let $E_0$ denote the bundle $E$ equipped with the metric $h_0$,
and hence write $s(E_0) := s(E,h_0)$.

Let us introduce the endomorphism
\begin{equation}\label{szdef}
\s(E,Z)\w\mu=\s(E)\w \1_{X\setminus Z}\mu+\s(E_0)\w \1_Z \mu, \quad \mu\in \QZ(X).
\end{equation}
If $Z=X$, then it is just $\s(E_0)$ so it is of interest only when $Z$ has positive codimension,
which we will assume from now on. Note that if we let $s(E,Z) := \s(E,Z) 1$, then
\begin{equation} \label{eq:sEZ}
   s(E,Z) = s(E)
\end{equation}
since $\1_Z 1 = 0$ and $\1_{X\setminus Z} 1 = 1$ as long as $Z$ has positive codimension.

\begin{prop}
Let $E\to X$ be an \qas\ bundle and $\mu\in \QZ(X)$.


 \smallskip
\noindent
(i)
\begin{equation} \label{eq:sEZ2}
  (\s(E,Z)-\s(E)) \wedge \mu = (\s(E)-\s(E_0)) \wedge \1_Z \mu.
\end{equation}

(ii)
There is a current $w$, which is the pushforward of a current on $Z$, such that
\begin{equation} \label{eq:sEZ3}
    (\s(E,Z)-\s(E)) \wedge \mu = dd^c w.
\end{equation}
\end{prop}

\begin{proof}
The equation in (i) follows readily by definition of $\s(E,Z)$.

To prove (ii), note first that since $\1_Z \mu$ is in $\QZ(X)$ and has support on $Z$,
by Proposition~\ref{tax}, there is a current $\mu_Z \in \QZ(Z)$ such that $\1_Z \mu = i_* \mu_Z$, where $i : Z \to X$ denotes the inclusion.
By Theorem~\ref{main11} (iv), there is $w' \in \QZ(Z)$ such that
$$
    (\s(i^*E)-\s(i^* E_0)) \wedge \mu_Z = dd^c w'.
$$
To be precise, we have formulated Theorem~\ref{main11} only for a complex manifold, but
when want to apply it here on $Z$ which might be singular, i.e., a reduced analytic space.
However, one may note either that the same result holds on reduced analytic spaces,
with the same proof, or one might reduce to the case of manifolds by taking a resolution
of singularities $\tau \colon Z' \to Z$, finding the appropriate current on $Z'$
and taking the push-forward to $Z$.
Hence, \eqref{eq:sEZ3} follows by (i) together with Theorem~\ref{main11} (iii) by taking $w = i_* w'$.
\end{proof}

It follows from \eqref{szdef} that $\s_0(E,Z)\w\mu=\mu$ so that $\s_0(E,Z)=I$, the identity on
$\QZ(X)$.
%
%
We can thus define
\begin{equation}\label{hatdef}
\c(E,Z)\w\mu=\sum_{k=0}^\infty (-1)^k \hat \s(E,Z)^k\w\mu,
\end{equation}
where $\hat \s(X,Z)=\s(X,Z)-I$.



\begin{prop}\label{main22}
Let $E\to X$ be an \qas\ bundle and $\mu\in \QZ(X)$.

 \smallskip
\noindent
(i)
 \begin{equation}\label{baka}
\c(E,Z)\w\s(E,Z)=\s(E,Z)\w\c(E,Z)=\I.
\end{equation}


\smallskip
\noindent
(ii) For each $\mu\in\QZ(X)$ there is a current $w$, which is the pushforward of a current
on $Z$, such that
$$
dd^c w=\big(\c(E,Z)-\c(E)\big)\w\mu.
$$


\smallskip
\noindent
(iii) If $Z$ has positive codimension in $X$, then, if $\c'(E):= \1_{X\setminus Z}\c(E)$,
\begin{equation}\label{sommarform}
\c(E,Z)=\big(\c'(E) - \c(E_0) \w M^E\w \c'(E)\big)\w \1_{X\setminus Z}\mu+\c(E_0)\w\1_Z\mu.
\end{equation}
%%
\end{prop}

By definition both $c(E)$ and $c(E,Z)$ are equal to the usual Chern form in $X\setminus Z$
if the metric on $E$ is smooth there.
%
However, in general is $c(E,Z)\neq c(E)$ across $Z$, see Example~\ref{chernex}.
%%%


%

\begin{remark}
In view of (iii),  $c(E,Z)$ is precisely the Chern form that appeared in \cite{Asommar} in case
the metric on $E$ is obtained  from $F$ via a generically injective $g\colon E\to F$,
  cf.~Example~\ref{favvis0}
\end{remark}
%



\begin{proof}[Proof of Proposition~\ref{main22}]
Part (i) follows in the same way as (i) in Proposition~\ref{main2prop}.

\smallskip
We may decompose
$$
    \hat\s(E)^k-\hat\s(E,Z)^k = \sum_{\ell=0}^{k-1} \s(E,Z)^{k-\ell-1} \w (\s(E)-\s(E,Z)) \w \s(E)^\ell.
$$
By \eqref{eq:sEZ3}, for each $\ell$, there exists $w_\ell$, which is the push-forward of
a current on $Z$, such that
$$
    (\s(E)-\s(E,Z)) \w \s(E)^\ell \w \mu = dd^c w_\ell.
$$
Since $w_\ell$ has support on $Z$,
$$
    \s(E,Z)^{k-\ell-1} \w (\s(E)-\s(E,Z)) \w \s(E)^\ell \w \mu = s(E_0)^{k-\ell-1} \w dd^c w_\ell
    = dd^c ( s(E_0)^{k-\ell-1} w_\ell),
$$
so we may take
$$
    w = \sum s(E_0)^{k-\ell-1} \w w_\ell
$$
to prove (ii).

\smallskip
For (iii), recall that
$
M^E \w \mu:=\1_Z \s(E)\w\mu$ and $\s'(E)\w\mu=\1_{X\setminus Z}\s(E)\w\mu.
$
We will prove by induction that
\begin{equation}\label{snuva}
\hat \s(E,Z)^k=\hat \s'(E)^k+\sum_{\ell=0}^{k-1}\hat \s(E_0)^\ell \w M^E \w \hat \s'(E)^{k-1-\ell}, \quad k=1,2, \ldots,
\end{equation}
when acting on $\1_{X\setminus Z} \mu$.
By definition it holds for $k=1$. Assume that it holds for $k$. When applying $\s(E)\w \1_{X\setminus Z}+\s(E_0)\w \1_Z$
to the right hand side of \eqref{snuva} the first mapping only acts on the first term and gives
$\hat \s(E)\w \hat \s'(E)^k= \hat \s'(E)^{k+1}+ M^E \w \hat \s'(E)^k$. The second mapping neglects the first term
and just gives another factor $s(E_0)$ on the terms in the sum. Thus \eqref{snuva} holds.
Thus
\begin{multline*}
\c(E,Z)=I+\sum_{k=1}^\infty (-1)^k\Big(\hat \s'(E)^k+\sum_{\ell=0}^{k-1}\hat \s(E_0)^\ell \w M^E \w\hat \s'(E)^{k-1-\ell}\Big)=\\
\c'(E)+\sum_{\ell=0}^\infty \sum_{k=\ell+1}^\infty (-1)^k\hat \s(E_0)^\ell \w M^E \w \hat \s'(E)^{k-1-\ell}=\\
\c'(E)-\sum_{\ell=0}^\infty (-1)^\ell \s(E_0)^\ell \w M^E \w \hat \c'(E)=\c'(E)-\c(E_0) \w M^E \w \c'(E).
\end{multline*}
The action on $\1_Z\mu$ is just $\hat \s(E_0)^k \w\1_Z\mu$. Thus (iii) follows.
\end{proof}

\begin{remark}
One can check directly that $c(E,Z)=\c(E,Z) 1$ is cohomologous with $c(E_0)$. In fact, accepting that the operations are legitimate
we have, if
$$dd^c u= s(E)-s(E_0)=M^E+s'(E)-s(E_0),$$
that
$$
-dd^c (c(E_0) \w u \w c'(E))=- c(E_0)\w(s(E)-s(E_0))\w c'(E)= c'(E)-c(E_0)\w M^E\w c'(E)-c(E_0).
$$
\end{remark}


\section{Examples and remarks}

In this final section, we discuss to which extent there is a canonical choice of $s(E,h)$
(and other characteristic forms, i.e., Chern forms $c(E,h)$) when $h$ is a \qas\ metric.
In case the unbounded locus $Z$ of $h$ is empty, there seems to be a canonical choice of
Segre form $s(E,h)$, given, e.g., by Segre forms $s(E,h_\e)$ of appropriate decreasing
regularizations $h_\e$ of $h$ as $\e \to 0$, cf. Proposition~\ref{mainLocBdd}.
When $Z \neq \emptyset$, the form $s(E,h,h_0)$ will typically depend on $h_0$,
see \cite[Example~8.2]{LRRS}. In particular, it follows by Theorem~\ref{main1} (i)
that limits $s(E,h_\e)$ as $\e \to 0$ might depend on the sequence $h_\e$, even
when $h_\e$ is a sequence of Griffiths negative smooth metrics decreasing to $h$.
Hence, there is in general no canonical choice of a Segre form $s(E,h)$
depending only on $h$.

To be a bit more precise, it follows from our results that in low enough degrees,
there is a natural canonical choice of $s_k(E,h)$.
Let $Z$ denote the set where $h$ is not locally bounded, and let $p = \codim Z$.
As long as $k \leq p$, $s_k(E,h,h_0)$ is independent of $h_0$ by Remark~\ref{remMain11} (i).
On the other hand, \cite[Example~8.2]{LRRS} mentioned above shows that $s_k(E,h,h_0)$ might depend
on $h_0$ for any $k > p$.

In case $k < p$, any definition of $s_k(E,h)$ as a closed current of order
$0$ is in fact uniquely determined by its restriction to $X\setminus Z$.
Indeed, because the difference between two such choices is a normal $(k,k)$-current
with support on an analytic subset of codimension $ > k$, it must vanish,
cf. e.g., \cite[Corollary III.2.11]{Dem}.
In particular, $s_k(E,h) = s_k'(E,h)$, which coincides with the currents considered by Xia
(for more general classes of metrics), \cite{Xia}, based on using the non-pluripolar Monge-Ampère product.

In the case when $k=p$, one may by Theorem~\ref{main1} and Proposition~\ref{mainLocBdd}
find locally an appropriate decreasing sequence of
smooth metrics $h_\e$ such that $s_p(E,h_\e) \to s_p(E,h)$, independent of the choice of
such a sequence. If the metric $h$ is furthermore Griffiths
negative, then by \cite{LRRS}, $s_k(E,h)$ may be obtained as $\lim_{\e \to 0} s_k(E,h_\e)$
for any sequence of smooth Griffiths negative metrics $h_\e$ decreasing to $h$ as $\e \to 0$
for any $k \leq p$.

\smallskip

Similar statements as above will hold also for products
$$
s_{k_t}(E,h) \wedge \dots \wedge s_{k_1}(E,h) :=
\s_{k_t}(E,h) \wedge \dots \wedge \s_{k_1}(E,h) 1,
$$
depending on how $k=k_1+\dots+k_t$ compares to $p$. Such a product is furthermore robust
in the sense that it is commutative in the factors provided $k \leq p$, which follows
from Theorem~\ref{main11} (vii), cf. Remark~\ref{remMain11} (ii).
Similarly, it follows by Proposition~\ref{main22} (ii) that replacing any
$s_{k_j}(E)$ by $s_{k_j}(E,Z)$ does not change the resulting current provided $k \leq p$.
In particular, $c_k(E) = c_k(E,Z)$ for $k \leq p$. For $k > p$, we will see below
that such an equality does typically not hold.

\subsection{Difference between $c_k(E)$ and $c_k(E,Z)$}

\begin{ex}
In general $c(E,Z)$ and $c(E)$ are different. The simplest example is when $Z=X$ and $Z'\neq Z$. Then in general
$s(E)$ may have a residue term, whereas $s(E,Z)=\omega$ and hence $c(E,Z)=c(E_0)$.
\end{ex}



 \begin{ex}\label{chernex}
Let $g$ be the $2\times 2$-diagonal matrix, with entries $x_1$ and $x_2$,
considered as a morphism between the trivial bundles $E=X\times \C^2_\alpha=F$,
and $F$ is equipped with the trivial metric.
With the trivial metric on $E$ as reference metric $h_0$ and the singular metric $h$ induced by $g$,
we have
\begin{equation}
   s_1(E) = [x_1 = 0] + [x_2 = 0].
\end{equation}
This follows by direct computation, or, e.g., from \cite[Proposition~11.1]{Asommar}.
From \cite[Example~11.2]{Asommar} we have that $s_2(E)=[x_1=x_2=0]$.

Let us now compute $c(E)$ and $c(E,Z)$ for the same \qas\ bundle $E$.
% or by direct computation.
To begin with $c_1(E)=c_1(E,Z)=-s_1(E)=-( [x_1 = 0] + [x_2 = 0])$.
%
A calculation yields that
\begin{equation}
\s_1(E)^2 = \s_1(E)\w ([x_1 = 0] + [x_2 = 0])= 2[x_1=x_2=0].
\end{equation}
For instance, if $\tau \colon \C\to \C^2$, $t\mapsto(t, 0)$, then $\s_1(\tau^*E)=[t=0]$.
Hence, by Theorem~\ref{main11}~(iii),
$\s_1(E)\w[x_2=0]= \tau_*(s_1(\tau^*E))=\tau_*[t=0]=[x_1=x_2=0]$.
%
From \cite[Example~11.2]{Asommar} we have that $s_2(E)=[x_1=x_2=0]$. Thus
$$
c_2(E)=s_1(E)^2-s_2(E)=[x_1=x_2=0].
$$
%
Since $Z=\{ x_1x_2 = 0 \}$, and $s_1(E) = s_1(E,Z)$
has support on $Z$, cf. above and \eqref{eq:sEZ},
$$
s_1(E,Z)^2=\s_1(E,Z)\w  ([x_1 = 0] + [x_2 = 0])= 0,
$$
since $\s_1(E_0) = 0$.
We conclude that
$$
c_2(E,Z)=-[x_1=x_2=0],
$$
which we notice is different from $c_2(E)$.
\end{ex}





