\section{Proofs of theoretical results} \label{s:p}
We begin with a general remark that addresses properties that will be useful in
subsequent arguments.

\begin{remark} \label{rem:early} We will find it useful to consider a variety
	of partial sum processes, over a variety of slightly modified random variables.
	For their definition, recall the definition of the set
	$\Lambda_t$ in \eqref{eq_def_Lambda_t} and the fact, proved in
	Lemma \ref{lem_p_t} below,  that for any $\varepsilon>0$,
	we have $p_{m^{D_1}} \lesssim m^{-D_2}$,  where
	\begin{align} \label{x1}
		p_{m^{D_1}}:= \mathbb{P}\bigg( \bigcup_{t=1}^{m^{D_1}} \Lambda_t^c\bigg).
	\end{align}
	Here, $D_1, D_2$ can be arbitrarily large. Define
	\begin{align} \label{e:defYt}
		Y_t:=&n^{2/3}  \big( \lambda_t\mathbb{I}\{\Lambda_t\} - b_t\big),\quad b_{t} := \frac{\mathbb{I}\{\Lambda_t\}\mathbb{E}[\lambda_t\mathbb{I}\{\Lambda_t\}]}{\mathbb{P}\{\Lambda_t\}} = \frac{\mathbb{I}\{\Lambda_t\}\mathbb{E}[\lambda_1\mathbb{I}\{\Lambda_1\}]}{\mathbb{P}\{\Lambda_1\}} .
	\end{align}
	The last identity above  holds under the null hypothesis.
	Now recall the definition of $b^{(n)}$ in \eqref{eq_def_b_n}.
	As a consequence of \eqref{x1}, it follows that
	\[
	n^{2/3}(\lambda_t-b^{(n)})=Y_t \qquad \forall \ 1 \le t \le m^{D_1}
	\]
	with probability converging to $1$.
	We call this the \textbf{early replacement property}. In particular, it entails
	\begin{align}\label{e:defPm'}
		P_m(x) = P_m'(x), \qquad
		P_m'(x):= \frac{1}{\sqrt{m \tau_n}}\sum_{t=1}^{\lfloor mx\rfloor}Y_t,
	\end{align}
	simultaneously for all $x \in [0,\lfloor m^{D_1-1}\rfloor ]$ and for any $D_1$ with probability decaying as $ m^{-D_2}$. In turn, this entails directly that
	\begin{align}\label{e:earlrep}
		\pi(\{P_m(x): x \in [0,\lfloor m^{D_1-1}\rfloor ]\},\{P_m'(x): x \in [0,m^{D_1-1}]\}) \lesssim m^{-D_2}.
	\end{align}
\end{remark}


\subsection{Proof of Theorem \ref{lem_3}} \label{ss:p-Gauss}
\textbf{Preliminaries} Throughout this proof, we will encounter a number
of  constants that for technical reasons have to be chosen sufficiently
close to $0$. We will denote them by $\varepsilon, \varepsilon_1, \varepsilon_2,\ldots$.
Often,  these numbers depend on each other and we make this clear,
when we introduce them for the first time. Recall, e.g. the number $\varepsilon>0$
from the definition of the event $\Lambda_t$ in \eqref{eq_def_Lambda_t}.
Using Assumption \ref{ass_2}, we have
\[
n^\varepsilon \lesssim m^{\varepsilon_1}, \qquad \textnormal{where} \quad \varepsilon_1 = \varepsilon_1(\varepsilon).
\]
A property of these small constants,
say $\varepsilon_K = \varepsilon_K(\varepsilon, \varepsilon_1,\ldots,\varepsilon_{K-1})$
will be that if all of the parameters they depend on are sufficiently small,
they can be made arbitrarily small themselves, or mathematically:
For any $\delta_1>0$ there exists a $\delta_2>0$, s.t. $\varepsilon_K$
can be chosen to be $\varepsilon_K<\delta_1$ if $\varepsilon, \varepsilon_1,\ldots,
\varepsilon_{K-1}<\delta_2$. We see this for $\varepsilon_1$,
which by Assumption \ref{ass_2} can be chosen as any value
$\varepsilon_1 \ge \varepsilon/\theta$.
Throughout the first part of this proof, we will consider a constant
\[
T = T_m \asymp m^{1/2-\rho}
\]
for some $\rho \in (0,1/2)$ that  is eventually chosen to depend on all of
the $\varepsilon$-numbers and can be arbitrarily small, for sufficiently
small $\varepsilon$s. Without loss of generality, we assume
that $T$ is such that always $Tm \in \mathbb{N}$.

\textbf{Variables and processes}  Recall the definition of the process $P_m'$ in
\eqref{e:defPm'}. For most of this proof we will study the process $P_m'$, and
only later make the connection to $P_m$.
We notice that random variables $Y_t$
defined in  \eqref{e:defYt} are measurable transforms
of the original time series $(\mathbf{W}_{n,t},
\mathbf{x}_{n,t},s_t)_{t \in \mathbb{Z}}$,  and hence $\phi$-mixing
with coefficients satisfying Assumption \ref{ass_3}, part iii).
We also notice that $Y_t$ is bounded. To see this, a small calculation is sufficient,
where in the first step, we add and subtract $2 \sigma \mathbb{I}\{\Lambda_t\}$,
in the second step use the definition of $\Lambda_t$, given in \eqref{eq_def_Lambda_t}, in the third step use that eventually $\mathbb{P}(\Lambda_t) \ge p_{Tm}\ge 2/3$ for sufficiently large $n$ (again Lemma \ref{lem_p_t}) and in the final step exploit the relation $n \lesssim m^{\varepsilon_1}$, giving us
\begin{align} \label{e:bYt}
	|Y_t| \le n^{2/3}|\lambda_t-2\sigma|\mathbb{I}\{\Lambda_t\}
	+ \frac{\mathbb{I}\{\Lambda_t\}\mathbb{E}[n^{2/3}|\lambda_t-2\sigma|\mathbb{I}\{\Lambda_t\}]}{\mathbb{P}\{\Lambda_t\}} \le n^\varepsilon + \frac{n^\varepsilon}{\mathbb{P}\{\Lambda_t\}} \le 3 n^\varepsilon\lesssim m^{\varepsilon_1}.
\end{align}
Moreover, it is clear that $\mathbb{E}Y_t=0$.
In the following, we define the variances
\begin{align} \label{eq_def_tau}
	\tau_{k,n}=\mathbb{E}\bigg(\frac{1}{\sqrt{k}}\sum_{t=1}^k Y_t \bigg)^2 \qquad \tau^{(n)}:= \sum_{t \in \mathbb{Z}}\mathbb{E}[Y_t Y_0].
\end{align}
From \eqref{eq_def_tau}, we get that the normalizing constant
$\tau_n$ can be written as as $\tau_n :=\tau_{Tm,n}$.
Both variances are finite. For $\tau_{k,n}$ this is clear,
since the variables $Y_t$ are bounded and for $ \tau^{(n)}$ this
boundedness, together with the decay of the mixing coefficients in
Assumption \ref{ass_3}, part i) implies that $ \tau^{(n)}<\infty$.
To be precise, we have
\begin{align} \label{e:intau(n)}
	\sum_{t \in \mathbb{Z}}|\mathbb{E}[Y_t Y_0]| \le \sum_{t \in \mathbb{Z}} 4 \phi(t) m^{2\varepsilon_1} \lesssim m^{2\varepsilon_1} \sum_{t \in \mathbb{Z}}  \phi(t),
\end{align}
where we have used \eqref{e:bYt} and an inequality for centered
mixing random variables $X,Y$ with mixing coefficient $\phi(X,Y)$:
If $X,Y$ are bounded by constants $C_X, C_Y$, then
$|\mathbb{E}[XY]| \le 4 \phi(X,Y) C_XC_Y$
(see Lemma 3.9 in \cite{dehling:mikosch:sorensen:2002}).
Next, we define the modified partial sum process (with $\lfloor Tm x \rfloor$ summands)
\begin{align} \label{e:defP''}
	P_m''(x) = \sqrt{m/(Tm)} \,\,P_m'(xT), \qquad x \in [0,1].
\end{align}
We also introduce the rescaled version $P_m''(v_m(x))$, where
\[
v_m(x):= \frac{1}{Tm }\min\{1 \le k \le Tm: k \tau_{k,n} \ge x Tm \tau_{Tm,n}\}.
\]
The function $v_m$ transforms the partial sum process and accounts for the evolving
variance $\tau_{k,n}$ along $k$ - if all $\tau_{k,n}$ (for all $k$) where equal,
it would reduce to the identity. Therefore, handling $v_m(x)$ involves showing
that the variances $\tau_{k,n}$  are (for all $k$ not too small) close to
a fixed value $\tau^{(n)}$ and we provide more details below.
Finally, we define the linearized version $(P_m'')^{lin}$  of $P_m''$
that linearly interpolates the points
\[
\left\{ \left( (k/(Tm)), P_m'' (k / (Tm) ) \right) : k=1,\ldots, Tm \right\}.
\]

We will now verify  three statements, where $c_T = o(T^{-1/2})$ is a sequence
of positive numbers, and then conclude the proof using them.
\begin{enumerate}[label=\alph*)]
	\item \label{part_a}
	$ \pi(\{P_m''(x): x \in [0,1]\}, \{P_m''(v_m(x)): x \in [0,1]\})=\mathcal{O}(c_T) $.
	\item \label{part_b}
	$\pi(\{P_m''(v_m(x)): x \in [0,1]\}, \{B(x): x \in [0,1]\})=\mathcal{O}(c_T)$.
	\item \label{part_c}
	$ \pi(\{P_m''(x): x \in [0,1]\}, \{(P_m'')^{lin}(x): x \in [0,1]\})=\mathcal{O}(c_T) $.
\end{enumerate}


\textbf{Proof of \ref{part_a}} We decompose the index set $[0,1]$ of the processes involved into $x \le m^{-1/2+\varepsilon_3}$ and $x>m^{-1/2+\varepsilon_3}$, where $\varepsilon_3$ is a sufficiently small number. First, we notice that $v_m(x) \ge m^{-1/2+\varepsilon_3}$ for all $x>m^{-1/2+\varepsilon_3}$. For this purpose, notice that $v_m$
is monotonically increasing and recall the defining inequality in $v_m(x)$. Here, consider the choice $k=m^{1/2+\varepsilon_3}$ and $x=m^{-1/2+\varepsilon_3}$. Then we get
\begin{align} \label{e:kineq}
	k \tau_{k,n} \ge x \,Tm \,\tau_{Tm,n} \quad \Leftrightarrow \quad m\ge Tm \,\frac{\tau_{Tm,n} }{\tau_{k,n}}.
\end{align}
A consequence of our below derivation in   \eqref{e:defam} is that $\tau_{Tm,n}/\tau_{k,n}=1+o(1)$. Since $T \to \infty$ as $m \to \infty$, it follows that the above inequality \eqref{e:kineq} is never satisfied for all sufficiently large $m$. Consequently, $v_m(x) \ge k/(Tm )$ and we conclude that $v_m(x) \ge m^{-1/2+\varepsilon_3}.$\\
Now, we begin the comparison of $v_m(x)$ and $x$ for values
$x \ge m^{-1/2+\varepsilon_3}$. Therefore, we notice that by definition of $v_m$ and the inequality $v_m(x) \ge m^{-1/2+\varepsilon_3}$
\begin{align*}
	& |v_m(x) - \lfloor x Tm\rfloor/( Tm ) | \le \bigg|v_m(x) -  \frac{x \tau_{Tm,n}}{\tau_{v_m(x)Tm,n}}\bigg| +
	\bigg|\frac{x \tau_{Tm,n}}{\tau_{v_m(x)Tm,n}} - \frac{\lfloor x Tm  \rfloor}{ Tm } \bigg|\\
	\le & \frac{1}{ Tm } + \bigg|\frac{x \tau_{Tm,n}}{\tau_{v_m(x)Tm,n}} - \frac{\lfloor x  Tm  \rfloor}{Tm } \bigg| \le \frac{2}{ Tm } + \bigg|\frac{x \tau_{Tm,n}}{\tau_{v_m(x)Tm,n}} - x \bigg| \\
	\le &\frac{2}{Tm } + \sup_{m^{-1/2+\varepsilon_3} \le x \le 1 }\Big|\frac{\tau_{Tm,n}}{\tau_{\lfloor Tm x\rfloor ,n}}-1\Big|.
\end{align*}
Now, we use Lemma \ref{lem_var} for $k \ge m^{1/2+\varepsilon_3}$, which yields
\begin{align}\nonumber
	& \sup_{m^{-1/2+\varepsilon_3} \le x \le 1 }\bigg| \frac{\tau_{Tm,n}}{\tau_{\lfloor Tm x\rfloor ,n}} - 1\bigg| \le \sup_{k \ge m^{1/2+\varepsilon_3}}\frac{ |\tau_{Tm,n}-\tau_{k,n}|}{\tau_{k,n}}
	\\[0.5ex]
	\le & \sup_{k \ge m^{1/2+\varepsilon_3}}\frac{ |\tau_{Tm,n}- \tau^{(n)}|+|\tau^{(n)}-\tau_{k,n}|}{\tau^{(n)}-|\tau^{(n)}-\tau_{k,n}|} \nonumber
	\\[0.5ex]
	\lesssim &\sup_{k \ge m^{1/2+\varepsilon_3}}\frac{n^{2\varepsilon}k^{-1+\varepsilon_2}}{\tau^{(n)} + \mathcal{O}(n^{2\varepsilon}k^{-1+\varepsilon_2} )} \lesssim m^{(-1+\varepsilon_2)
		(1/2+\varepsilon_3)+
		2\varepsilon_1 } =:a_m.\label{e:defam}
\end{align}
In the first inequality, we have used that $\lfloor Tm x \rfloor \ge m^{1/2+\varepsilon_3}$. In the second step, we have used for the numerator that $\tau^{(n)}\lesssim n^{2\varepsilon}$ (see   \eqref{e:intau(n)}) and the concentration of variances from Lemma \ref{lem_var} ($\varepsilon_2$ is the constant $\eta$ in that lemma and can be made arbitrarily small). We have used the latter result again for the denominator, to replace $\tau_{k,n}$ by $\tau^{(n)}$.
In the third step, we can again treat numerator and denominator separately: For the denominator, we have used that $\tau^{(n)}$ is bounded away from $0$ (Assumption \ref{ass_3}, part ii)). So, the entire denominator is bounded away from $0$, since for small enough $\varepsilon, \varepsilon_1,\varepsilon_2,\varepsilon_3$ and $k\ge m^{1/2+\varepsilon_3}$
\[
n^{2\varepsilon}k^{-1+\varepsilon_2} \lesssim m^{2\varepsilon_1} m^{-(1-\varepsilon_2)(1/2+\varepsilon_3)} =o(1).
\]
For the numerator we also use the above inequality
\[
n^{2\varepsilon}k^{-1+\varepsilon_2} \lesssim m^{2\varepsilon_1} m^{-(1-\varepsilon_2)(1/2+\varepsilon_3)}=a_m,
\]
yielding the desired result. Thus, our above arguments establish for some large enough constant $C_v>0$ and for all $m$ sufficiently large that
\begin{align} \label{e:bv_m}
	\sup_{m^{-1/2+\varepsilon_3}\le x \le 1}|v_m(x) - \lfloor x Tm \rfloor/(Tm ) |  \le C_v a_m.
\end{align}
In the following, we will not always mention the requirement of $m$ being "large enough", to shorten our arguments.
Now, we have to introduce three constants: First let $q_0>2$ be a constant that later has to be chosen sufficiently large and consider values of $q>q_0$. It follows that
uniformly for $x>m^{-1/2+\varepsilon_3}$ that
\begin{align} \label{e:Pnb1}
	&  \{\mathbb{E} \sup_{x>m^{-1/2+\varepsilon_3}}|P_m''(x)- P_m''(v_m(x))|^q\}^{1/q}\le\bigg\{\mathbb{E} \sup_{|k-j| \le  C_v ( Tm ) a_m } \bigg|\frac{1}{\sqrt{ Tm}}\sum_{t=j+1}^k Y_t \bigg|^q \bigg\}^{1/q}\\
	\lesssim & ((Tm)^2 a_m)^{1/ q} \sup_{|k-j| \le  C_v ( Tm ) a_m }\bigg\{\mathbb{E}  \bigg|\frac{1}{\sqrt{ Tm}}\sum_{t=j+1}^k Y_t \bigg|^{q} \bigg\}^{1/q} \nonumber\\
	\lesssim  &\frac{m^{\varepsilon_4}(Tm)^{2/q_0}  a_m^{1/q_0} (Tm a_m)^{1/2}}{(Tm)^{1/2}} = a_m^{1/2} \{m^{\varepsilon_4}(Tm)^{2/q_0}  a_m^{1/q_0} \}\lesssim m^{\varepsilon_5} a_m^{1/2}.\nonumber
\end{align}
In the first inequality, we have used the definition of the partial sum process $P_m''$ (see   \eqref{e:defP''}), the fact that by construction $P_m''(x) = P_m''(\lfloor x Tm \rfloor/(Tm))$ and the inequality \eqref{e:bv_m}.
In the second inequality, we have used Lemma 2.2.2. from \cite{vaart:wellner:1996}, which is a standard way of bounding the expectation of the maximum of random variables. In the third inequality, we have used Theorem 1 in \cite{yoshihara:1978}, which is an inequality for mixing random variables. Its application is rather simple, because the random variables involved $Y_t$, are uniformly bounded by $3 n^\varepsilon \lesssim m^{\varepsilon_1}$. Moreover, we have exploited that $ q >q_0$ and that $(Tm)^{2}  a_m \to \infty$, which implies together that eventually $[(Tm)^{2}  a_m]^{1/ q} \le [(Tm)^{2}  a_m]^{1/ q_0}$.
Finally, for the last inequality, we have used that for $q_0$ large enough, that $m^{\varepsilon_4}(Tm)^{2/q_0}  a_m^{1/q_0} \lesssim m^{\varepsilon_5}$ with a value of $\varepsilon_5 = \varepsilon_5(\varepsilon_1,\ldots,\varepsilon_4, q_0)$ that can be made arbitrarily small. Making $\varepsilon_1,\ldots,\varepsilon_5$ sufficiently small, we get
get $m^{\varepsilon_5} a_m^{1/2} = m^{-1/2+\varepsilon_6}$ and we can choose   $\varepsilon_6= \varepsilon_6(\varepsilon_1,\ldots,\varepsilon_5)$ as small as we want (to see this recall the definition of $a_m$ in  \eqref{e:defam}).
\\
Next, we consider
$|P_m''(x)- P_m''(v_m(x))| $ for $x \le m^{-1/2+\varepsilon_3}$. Recalling \eqref{e:bv_m}, we get by plugging in $x = m^{-1/2+\varepsilon_3}$
that
\[
v_m(m^{-1/2+\varepsilon_3}) \le m^{-1/2+\varepsilon_3} + C_v a_m \le 2m^{-1/2+\varepsilon_3}
\]
for all $m$ sufficiently large, such that
$C_v a_m \le m^{-1/2+\varepsilon_3}$ (this holds eventually for a sufficiently small choice of $\varepsilon_2$). This means, that we can use the following inequality
\begin{align*}
	\sup_{0 \le x \le  m^{-1/2+\varepsilon_3}}|P_m''(x)- P_m''(v_m(x))| \le 2 \sup_{0 \le  x \le  2 m^{-1/2+\varepsilon_3}}|P_m''(x)|.
\end{align*}
We can now combine Theorem 3.1 in \cite{moricz:serfling:stout:1982} (a maximum inequality for partial sums) with Theorem 1 in \cite{yoshihara:1978} (a moment bound for sums of mixing variables; such a bound is required for the application of \cite{moricz:serfling:stout:1982}) and we obtain
\[
\mathbb{E}[\sup_{0 \le x \le 2 m^{-1/2 + \varepsilon_3}}|P_m''(x)|^q]^{1/q} \lesssim n^{\varepsilon}  m^{-1/4+\varepsilon_3}.
\]
We can further upper bound the right side, using that $T\asymp m^{1/2-\rho}$ and that $n^\varepsilon \lesssim m^{\varepsilon_1}$,
yielding
\[
n^{\varepsilon}  m^{-1/4+\varepsilon_3} \lesssim \frac{m^{\varepsilon_1 +\varepsilon_3 +(1/2-\rho)/2-1/4}}{T^{1/2}
} = \frac{m^{\varepsilon_1+\varepsilon_3 -\rho/2}}{T^{1/2}}
=\frac{m^{-\varepsilon_7}}{T^{1/2}},
\]
where $\varepsilon_7 := -(\varepsilon_1+\varepsilon_3 -\rho/2$). Notice that $\varepsilon_7$ can be chosen to be positive by making $\varepsilon_1$ and $\varepsilon_3$ sufficiently small compared to $\rho$. We now combine this bound with \eqref{e:Pnb1},
where we notice that the right-hand - side can be upper bounded by
\[
m^{\varepsilon_5}a_m^{1/2} = m^{\varepsilon_5 +(-1+\varepsilon_2)
	(1/2+\varepsilon_3)+
	2\varepsilon_1 } \lesssim m^{-\varepsilon_8-(1/2-\rho)/2} \lesssim \frac{m^{-\varepsilon_8}}{T^{1/2}},
\]
for some $\varepsilon_8= \varepsilon_8(\varepsilon,\varepsilon_1,\ldots,\varepsilon_5)$, which can be made arbitrarily small.
So, we obtain
\begin{align*}
	\{\mathbb{E} \sup_{x \in [0,1]}|P_m''(x)- P_m''(v_m(x))|^q\}^{1/q}\lesssim \frac{m^{-\min(\varepsilon_7, \varepsilon_8)}}{T^{1/2}}
\end{align*}
for  any $q>q_0$. Now, we may increase $q$ further so that
\[
\frac{q \min(\varepsilon_7,\varepsilon_8)}{2}>\frac{1}{2}-\rho-\frac{\varepsilon}{2}
\]
holds. We recall that the $\varepsilon$s do not depend on $q$
and hence such an enlargement is possible (some $\varepsilon$s depend on $q_0$, which is merely a lower bound for $q$).
Then, this gives us the following result:
\begin{align*}
	& \mathbb{P}( \sup_{x \in [0,1]}|P_m''(x)- P_m''(v_m(x))|>T^{-1/2}m^{-\min(\varepsilon_7,\varepsilon_8)/2}) \\
	\le & \frac{\mathbb{E} \sup_{x \in [0,1]}|P_m''(x)- P_m''(v_m(x))|^q}{T^{-q/2}m^{-q\min(\varepsilon_7,\varepsilon_8)/2}} \lesssim m^{-q\min(\varepsilon_7,\varepsilon_8)/2} \lesssim T^{-1/2}m^{-\min(\varepsilon_7,\varepsilon_8)/2}.
\end{align*}
Setting
\begin{align} \label{e:defc}
	c_T := T^{-1/2}m^{-\min(\varepsilon_7,\varepsilon_8)/2}
\end{align}
completes the verification of  claim  \ref{part_a}.



\textbf{Proof of \ref{part_b}} Our argument rests on Theorem 2.3 in
\cite{hafouta:2023}. In that theorem, various constants appear and we will
explain how they need to be chosen in our context. We will therefore go through
the constants in the results of \cite{hafouta:2023}, using the notation of that paper.
We only make one adjustment regarding notation of the cited results:
The sample size in named paper is denoted by $n$. Since, we want to avoid
confusion with the $n$ from our work, we denote the sample size in the results of
\cite{hafouta:2023}  by $N$,  and notice that in our context we have to choose
$N= Tm$. Then, the variance $\sigma_N^2$ in that paper, is
\begin{align} \label{eq_def_sigma_N}
	\sigma_N^2 := Tm\tau_{Tm,n}.
\end{align}
Next, we need to consider the constant $A_N$ introduced in Section 2.1.1 of the cited paper, which is defined as
\begin{align} \label{eq_def_A_N}
	A_N = 18r_N(1+K_{2,N}).
\end{align}
Here, $K_{p,N} := \{\mathbb{E}|Y_t|^p\}^{1/p}$ and we get from \eqref{e:bYt}
\begin{align} \label{a0}
	K_{p,N} \le K_{\infty,N} := \mathbb{E}\sup_\omega |Y_t(\omega)|  \le 3n^{\varepsilon} \lesssim m^{\varepsilon_1}.
\end{align}
Next, $r_N$ defined in that paper is a quantity depending on the mixing coefficients. It is defined rather implicitly, and hence we only define an  upper bound $\tilde r_N$ for it here. We define $\tilde r_N$ as the smallest number $x$, such that $\tilde \Gamma_{n,m}(x) \le (8  K_{\infty,N})^{-1}$, where
\[
\tilde \Gamma_{n,m}(x) := \sum_{k >x} \phi(k)^{1/p-1/q},
\]
for some  $p>q>2$. The numbers $p,q$ here are user-determined (and $q$ has nothing to do with the letter $q$ from part \ref{part_a} of this proof).
We choose both $q$ and $p$ as very large numbers, with $q>>p$, to be precisely  determined later. Since  $\phi(k) \le C a^{-k}$ is exponentially decaying (from Assumption \ref{ass_3}), it follows that, for any fixed $q>p>2$, the function $\tilde \Gamma_{n,m}(x) $ is exponentially decaying. Moreover, we have for some large enough constant $C_1$
\[
(8 C_1 m^{\varepsilon_1})^{-1}\le  (8  n^\varepsilon)^{-1} \le (8  K_{\infty,N})^{-1}.
\]
Combining these insights, we obtain that for any $\varepsilon_9>0$, no matter how small, that we have eventually
$\tilde r_N \lesssim m^{\varepsilon_9}$.
As a consequence, we have for $A_N$ defined in \eqref{eq_def_A_N}
\begin{align} \label{a1}
	A_N \lesssim \tilde r_N (1+K_{\infty,N})   \lesssim m^{\varepsilon_1+\varepsilon_9}.
\end{align}
The next constant in Theorem 2.3 of \cite{hafouta:2023} is $\beta_N$. This constant is implicitly defined as well and we do not repeat its definition here. Rather, we directly proceed to an upper bound, which is discussed in Section 2.2 of the same paper.
There, we see that
\begin{align} \label{a2}
	\beta_N \lesssim q (1+K_{\infty,N}) \lesssim q (1+m^{\varepsilon_1})
	\lesssim m^{\varepsilon_1}.
\end{align}
Now, we can move to the Theorem 2.3 in the paper again and choose
$l_N \asymp \sigma_N$, which  entails
\begin{align*}
	&\pi(\{P_m''(v_m(x)): x \in [0,1]\}, \{B(x): x \in [0,1]\})\\
	\lesssim &(1+K_{q,N})A_N \beta_N\bigg(\sigma_N^{\frac{-p-2}{2p}}
	|\log( \sigma_N)|^{\frac{3}{4}} + \mathfrak{q}_N^{\frac{p}{2p+4}}
	|\log \mathfrak{q}_N|^{\frac{1}{2}}\bigg) =: (1+K_{q,N})A_N \beta_NB_N,
\end{align*}
where $\mathfrak{q}_N := l_N^{\frac{1}{2}} \sigma^{-1}_N + l_N
\sigma_N^{-2(1-2/p)} + l_N^{-1/2}$,
and $B_N$ in the final equation is defined in the obvious way.
If we make $p$ big enough, we get that
\[
\mathfrak{q}_N \lesssim \sigma_N^{-1/2+\varepsilon_{11}},
\]
where $\varepsilon_{11}$ only depends on $p$ and can be made arbitrarily small.
Now, for $p$ large enough, we get for some small $\varepsilon_{12}
=\varepsilon_{12}(\varepsilon_{11})$ that
\begin{align} \label{a3}
	B_N \lesssim \sigma_N^{-(1/2-\varepsilon_{12})} \lesssim (Tm)^{-(1/4-\varepsilon_{12}/2)},
\end{align}
where we used the definition of $\sigma_N$ in \eqref{eq_def_sigma_N} and the fact that $\tau_{Tm,m}$ is bounded away from $0$ (similarly to \eqref{part_a}).
By our above considerations in \eqref{a0}, \eqref{a1}, \eqref{a2} and \eqref{a3}, we get
\[
(1+K_{q,N})A_N \beta_NB_N \lesssim m^{\varepsilon_{13}} (Tm)^{-(1/4-\varepsilon_{12}/2)}.
\]
Making $\varepsilon_{12}, \varepsilon_{13}$ sufficiently small and using that $T\asymp m^{1/2-\rho}$ entails that the right side is of size
$\lesssim T^{-3/4}$. Recalling the definition $c_T = T^{-1/2}m^{-\min(\varepsilon_7,\varepsilon_8)/2}$ in \eqref{e:defc}, we get for small enough $\varepsilon_7,\varepsilon_8$ that
$T^{-3/4}\lesssim  c_T$, and we have shown the desired result in   \ref{part_b}.\\

\textbf{Proof of \ref{part_c}} This part is the easiest of the entire proof.
By definition of $(P_m'')^{lin}$,
\[
\sup_{x \in [0,1]}|(P_m'')^{lin}(x)-P_m''(x)|
\le \sup_t \frac{Y_t}{\sqrt{Tm \tau_n}}
\lesssim
\frac{m^{\varepsilon_1}}{(Tm)^{1/2}} \le c_T,
\]
where we used \eqref{e:bYt} and again the fact that $\tau_n$ is bounded away from $0$ (see proof of part \ref{part_a}).
Since this result is deterministic, in particular the bound from \ref{part_c} follows.

\textbf{Concluding argument} We can now proceed to the final step of the proof.
Using the triangle inequality for the Prokhorov metric, we conclude from \ref{part_a} and \ref{part_b} that
\begin{align*}
	& \pi(\{P_m''(x): x \in [0,1]\}, \{B(x): x \in [0,1]\})=\mathcal{O}(c_T).
\end{align*}
Together with \ref{part_c} and again the triangle inequality, we get
\[
\pi(\{(P_m'')^{lin}(x): x \in [0,1]\}, \{B(x): x \in [0,1]\})=\mathcal{O}(c_T).
\]
Now, since both $(P_m'')^{lin}$ and $ B$ live on the Banach space $\mathcal{C}([0,1])$, we can (after possibly changing the probability space) create a coupling such that
\begin{align} \label{e:approx1}
	\mathbb{P}(\sup_{x \in [0,1]}|(P_m'')^{lin}(x)-B(x)|>c_T)<c_T,
\end{align}
where we recall $c_T = o (T^{-1/2})$. The existence- of the named coupling is a
consequence of Lemma \ref{lem:huber} stated in Subsection \ref{ss:au}.
On that probability space, we can use $(P_m'')^{lin}$ to create the variables $Y_1, Y_2,\ldots$ as increments of the process and therewith also construct the non-linearized partial sum process $P_m''$.
We have deterministically $Y_t \lesssim n^\varepsilon$ for all $t$,
which implies by the same reasoning as in part \ref{part_c} of the proof that
\begin{align} \label{e:approx2}
	\sup_{x \in [0,1]}|(P_m'')^{lin}(x) - P_m''(x)|
	\lesssim \frac{m^{\varepsilon_1}}{(Tm)^{1/2}} \lesssim c_T.
\end{align}
Now, rescaling the process, we can consider $P_m'(x) = \sqrt{T} \,\,P_m''(x/T)$ on this probability space, too,  and we can define the scaled version of the Brownian motion  $\tilde B (x):=\sqrt{T}B(x/T)$.
Combining the results in \eqref{e:approx1} and \eqref{e:approx2}, we obtain for some large enough constant $C_0>0$ that
\[
\mathbb{P}\left (\sup_{x \in [0,T]}|P_m'(x)-\tilde B (x)|>C_0 \sqrt{T} c_T \right )<c_T.
\]
Since $C_0 \sqrt{T} c_T=o(1)$, it follows again by
Lemma \ref{lem:huber} (the reverse direction) that
\[
\pi(P_m', \tilde B) =o(1),
\]
this time on the space $\mathcal{C}([0,T])$.
This is a statement about the distributions of $P_m'$ and $\tilde B$ and it in particular holds for $P_m'$ on our original probability space. But then,
since $P_m' = P_m$ with probability going to $1$ (see the early replacement property in Remark \ref{rem:early}) and it follows that
\[
\pi(P_m, \tilde B) \le \pi(P_m',  P_m) + \pi(P_m', \tilde B) =o(1).
\]
Now, let $P_m^{lin}$ be the version of $P_m$ that linearly interpolates the points $\{(k/m, P_m(k/m): k=1,\ldots,Tm\}$. Then, we can show in a final step
\[
\sup_{x \in [0,T]} |P_m^{lin}(x)-P_m(x)| \le \max_t\frac{n^{2/3}|\lambda_t-b_t|}{\sqrt{m\tau_n}}\lesssim \max_t\frac{n^{2/3}|\lambda_t-b_t|}{\sqrt{m}}=\max_t\frac{|Y_t|}{\sqrt{m}}+o_P(1) = o_P(1).
\]
The equality $n^{2/3}|\lambda_t-b_t| = Y_t+o_P(1)$ is a consequence of the early replacement property (see Remark \ref{rem:early}). We have then used from \eqref{e:bYt} that deterministically $|Y_t| \le n^\epsilon \lesssim m^{\epsilon_1}=o(\sqrt{m})$.
Accordingly, by an application of Lemma \ref{lem:huber},
we obtain for some sufficiently slowly decaying null sequence
null-sequence $(d_m)_{m \in \mathbb{N}}$ that $\pi(P_m^{lin}, P_m) = \mathcal{O}(d_m)$. After possibly making the decay of $d_m$ even slower, we also have $\pi( \tilde B, P_m) = \mathcal{O}(d_m)$ (from our above derivations we know their distance goes to $0$). Then with the triangle inequality the implication
\[
\pi(P_m^{lin}, P_m),  \,\pi( \tilde B, P_m) = \mathcal{O}(d_m) \quad \Rightarrow \quad \pi(P_m^{lin}, \tilde B) = \mathcal{O}(d_m).
\]
Since both of the processes $P_m^{lin}, \tilde B$ exist on the separable space $\mathcal{C}([0,T])$ we can apply
Lemma \ref{lem:huber}  (implication ii) $\Rightarrow$ i)). It states that
we can redefine the processes on an appropriate probability space, such that
\[
\mathbb{P}(\sup_{x \in [0,T]}|P_m^{lin}(x)- \tilde B(x)| \le d_m) \ge 1-d_m.
\]
On this space, we can construct from the increments of $P_m^{lin}$ a version of $P_m$ and
\begin{align} \label{e:PPlin}
	\sup_{x \in [0,T]} |P_m^{lin}(x)-P_m(x)| \le \max_t\frac{n^{2/3}|\lambda_t-b_t|}{\sqrt{m\tau_n}}\le d_m
\end{align}
is still satisfied. Thus, we get the desired result
\[
\mathbb{P}(\sup_{x \in [0,T]}|P_m(x)- \tilde B(x)| \le d_m)>1-d_m.
\]
This concludes the proof of Theorem \ref{lem_3}.



\subsection{Proof of Lemma \ref{lem_4}}\label{ss:p-l3}
Recall the definitions of $\Gamma_{n,m}(k)$ and $Y_t$ in \eqref{e:def:gam}
and \eqref{e:defYt}, respectively.
Using the early replacement property in Remark \ref{rem:early}, we get with probability going to $1$ that
\[
\sup_{m^{1+\zeta}\le k \le m^L} \Gamma_{n,m}(k) = \sup_{m^{1+\zeta}\le k \le m^L} \frac{D_m'(k)}{V_m/\sqrt{\tau_n}},
\]
where
\begin{align*}
	D_m'(k):=&\frac{\sqrt{m}}{ \sqrt{\tau_n}\,\,(m+k)}
	\bigg(\sum_{t=m+1}^{m+k}Y_t-\frac{k}{m}\sum_{t=1}^m Y_t\bigg) \\
	=& \frac{\sqrt{m}}{\sqrt{\tau_n} \,\,(m+k)}
	\sum_{t=m+1}^{m+k}Y_t-\frac{k}{\sqrt{\tau_n}(m+k)\sqrt{m}}\sum_{t=1}^m Y_t
	=:  D_{1,m}'(k)-D_{2,m}'(k).
\end{align*}
Here, $D_{1,m}', D_{2,m}'$ are defined in the obvious way. We will now demonstrate that
\begin{align}\label{e:bD1m}
	\sup_{m^{1+\zeta}\le k \le m^L} |D_{1,m}'(k)|=o_P(1).
\end{align}
As a preparatory step, we let $\zeta':= \zeta/(2(1+\zeta))$ and
note that $(1+\zeta)(1/2-\zeta') = 1/2$. Then, we find the following
upper bounds for $k\ge m^{1+\zeta}$:
\begin{align*}
	m+k & = (m+k)^{1/2+\zeta'} (m+k)^{1/2-\zeta'} \ge (m+k)^{1/2+\zeta'} k^{1/2-\zeta'} \ge (m+k)^{1/2+\zeta'} m^{(1+\zeta)(1/2-\zeta')} \\
	&  = (m+k)^{1/2+\zeta'} \sqrt{m}
	.
\end{align*}
Using these insights, we get
\begin{align*}
	& \sup_{m^{1+\zeta}\le k \le m^L} |D_{1,m}'(k)| = \sup_{m^{1+\zeta}\le k \le m^L}\bigg|\frac{\sqrt{m}}{\sqrt{\tau_n} \,\,(m+k)}
	\sum_{t=m+1}^{m+k}Y_t\bigg|
	\\
	\lesssim  &
	\sup_{m^{1+\zeta}\le k \le m^L}\bigg|\frac{\sqrt{m}}{(m+k)^{1/2+\zeta'}\sqrt{m}}\sum_{t=m+1}^{m+k}Y_t\bigg| =
	\sup_{m^{1+\zeta}\le k \le m^L}\bigg|\frac{1}{(m+k)^{1/2+\zeta'}}\sum_{t=m+1}^{m+k}Y_t\bigg| \\
	\le &   \frac{n^\varepsilon}{m^{\zeta'/2}} \sup_{1\le k \le m^L}\bigg|\frac{1}{(m+k)^{1/2+\zeta'/2}}\sum_{t=m+1}^{m+k}\frac{Y_t}{n^\varepsilon}\bigg|
	\le  \frac{n^\varepsilon}{m^{\zeta'/2}} \sup_{k \ge 1}\bigg|\frac{1}{k^{1/2+\zeta'/2}}\sum_{t=1}^{k}\frac{Y_{t+m}}{n^\varepsilon}\bigg| \\
	\overset{d}{=} & \frac{n^\varepsilon}{m^{\zeta'/2}} \sup_{k \ge 1}\bigg|\frac{1}{k^{1/2+\zeta'/2}}\sum_{t=1}^{k}\frac{Y_{t}}{n^\varepsilon}\bigg| ,
\end{align*}
where we used Assumption \ref{ass_2}  for the second-to-last inequality, and the last equality holds because of stationary of the $Y_t$.
Now, the fact that
\[
\sup_{k \ge 1} \frac{1}{k^{1/2+\zeta'/2}} \bigg|\sum_{t=1}^k \frac{Y_t}{n^\varepsilon}\bigg| = \mathcal{O}_P(1)
\]
follows exactly as in the proof of Lemma C.1 of \cite{kutta:jach:kokoszka:2024} and is therefore not repeated here. Since we can make $\varepsilon$ arbitrarily small, we may assume that $\varepsilon<\zeta'/(2\theta)$ and we have
\[
\frac{n^\varepsilon}{m^{\zeta'/2}}  \asymp m^{\varepsilon\theta-\zeta'/2}=o(1).
\]
This shows that \eqref{e:bD1m} holds.

Now, $V_m/\sqrt{\tau_n}$
converges in distribution to an a.s. positive random variable. To see this, notice that $V_m/\sqrt{\tau_m}$ is a continuous transform of the partial sum process $\{P_m(x): x \in [0,1]\}$ and hence, it follows by the continuous mapping theorem that
\begin{align} \label{e:Vmas}
	V_m/\sqrt{\tau_n}=\int_0^1 |P_m(x)-\frac{\lfloor xm\rfloor}{m}P_m(1)|
	dx \overset{d}{\to} \int_0^1 |B(x)-xB(1)|dx.
\end{align}
Combining this with \eqref{e:bD1m} yields
\begin{align} \label{e:Dpres1}
	\sup_{m^{1+\zeta}\le k \le m^L} \Gamma_{n,m}(k)
	= \sup_{m^{1+\zeta}\le k \le m^L} \frac{D_{m}'(k)}{V_m/\sqrt{\tau_n}}+o_P(1)=\sup_{m^{1+\zeta}\le k \le m^L} \frac{-D_{2,m}'(k)}{V_m/\sqrt{\tau_n}}+o_P(1).
\end{align}
Now, using the early replacement property in reverse
(replacing $Y_t$ by $n^{2/3}(\lambda_t-b^{(n)})$ for all $1 \le t \le m^L$,
which is possible probability going to $1$; see Remark \ref{rem:early}), we obtain
\begin{align} \label{e:D2m}
	D_{2,m}'(k) =  \frac{kn^{2/3}}{\sqrt{\tau_n}(m+k)\sqrt{m}}\sum_{t=1}^m [\lambda_t-b^{(n)}] = \frac{k}{m+k}P_m(1)  = P_m(1)+o_P(1).
\end{align}
The above remainder $o_P(1)$ is independent of $k$ and thus the asymptotic equality is uniform over all $k \ge m^L$.
This shows the desired result
\begin{align} \label{e:Gamear}
	\sup_{m^{1+\zeta}\le k \le m^L} \Gamma_{n,m}(k)
	= \sup_{m^{1+\zeta}\le k \le m^L} \frac{-P_m(1)}{V_m/\sqrt{\tau_n}}+o_P(1),
\end{align}
uniformly over all $k$ between $m^{1+\zeta}$ and $m^{L}$.
Next, we consider values of $k>m^L$. Since we can freely choose $L>0$,
we choose it large enough such that
\[
\frac{L}{3}-\frac{1}{2}-2\theta>0.
\]
Similarly as before, we decompose
\begin{align*}
	\Gamma_{n,m}(k) = &\frac{D_m''(k)}{V_m/\sqrt{\tau_n}},\qquad \textnormal{where}\quad D_m'' :=D_{1,m}'' - D_{2,m}'', \quad \textnormal{and}\\
	D_{1,m}''(k):= &\frac{\sqrt{m}}{\sqrt{\tau_n} \,\,(m+k)}
	\sum_{t=m+1}^{m+k}Y_t', \qquad Y_t':= n^{2/3}\big( \lambda_t - \mathbb{E}[\lambda_t]\big), \\
	D_{2,m}''(k):= &
	\frac{k}{\sqrt{\tau_n}(m+k)\sqrt{m}}\sum_{t=1}^m Y_t'.
\end{align*}
Combining Lemma \ref{lem:exp} in Subsection \ref{ss:au} and Remark \ref{rem:early},
we get  $ D_{2,m}''(k) =  D_{2,m}'(k)+o(1)$,
uniformly over $k$,  and we have analyzed $ D_{2,m}'$
in the first part of this proof already (see \eqref{e:D2m}).
Thus, we turn to the analysis of $D_{1,m}''$.
Recall $\tau^{(n)}$  defined in \eqref{e:def:tau^n}.
By Lemma \ref{lem_var} in Subsection \ref{ss:au},
$\tau_n = \tau^{(n)}+o_P(1)$ and
$\tau^{(n)}$  is bounded away from $0$
by Assumption \ref{ass_3}, which implies that $\tau_n$
(defined in \eqref{e:def:tau_n}) is bounded away from $0$.
Next,
recall that we consider $k>m^L$ and that $n\asymp m^\theta$. This implies
\begin{align*}
	\frac{\sqrt{m}}{\sqrt{\tau_n} \,\,(m+k)} \lesssim \frac{\sqrt{m}}{m+k} \le \frac{\sqrt{m}}{(m+k)^{2/3}k^{1/3}} \le \frac{m^{-L/3+1/2}}{(m+k)^{2/3}} \lesssim  \frac{m^{-L/3+1/2+(5/3)\theta}}{(m+k)^{2/3}n^{5/3}}.
\end{align*}
Accordingly, we have
\begin{align*}
	\sup_{k>m^L}|D_{1,m}''(k)| \lesssim m^{-L/3+1/2+(5/3)\theta}  \cdot \sup_{k>m^L}\bigg|\frac{1}{(m+k)^{2/3}}\sum_{t=m+1}^{m+k}\frac{Y_t'}{n^{5/3}}\bigg|.
\end{align*}
The first factor on the right  tends to $0$, by our choice of $L$. The supremum can once more be upper bounded by
\begin{align} \label{e:Dpres2}
	\sup_{k>m^L}\bigg|\frac{1}{k^{2/3}}\sum_{t=m+1}^{m+k}\frac{Y_t'}{n^{5/3}}\bigg| \overset{d}{=}
	\sup_{k> m^L  }\bigg|\frac{1}{k^{2/3}}\sum_{t=1}^{k}\frac{Y_t'}{n^{5/3}}\bigg|
	\leq \sup_{1 \le k <\infty}\bigg|\frac{1}{k^{2/3}}\sum_{t=1}^{k}\frac{Y_t'}{n^{5/3}}\bigg|=\mathcal{O}_P(1).
\end{align}
Here, the $\mathcal{O}_P(1)$ rate follows again as in the proof of Lemma C.1 of \cite{kutta:jach:kokoszka:2024}. This approach relies on the fact that $\mathbb{E}|Y_t'/n^{5/3}|^q \le C_q<\infty$, where $C_q>0$ is fixed and only depends on $q$ (the proof of this result uses similar techniques as the proof of
Lemma \ref{lem:exp} and is omitted).  Again using the fact that
$V_m/\sqrt{\tau_n}$ converges weakly to an
a.s. positive random variable (see eq. \eqref{e:Vmas}),
we obtain
\[
\sup_{ k > m^L} \Gamma_{n,m}(k)= \sup_{ k > m^L} \frac{D_{m}''(k)}{V_m/\sqrt{\tau_n}}+o_P(1)=\sup_{k >m^L} \frac{-D_{2,m}'(k)}{V_m/\sqrt{\tau_n}}+o_P(1).
\]
As we have seen in \eqref{e:D2m}, it holds that uniformly in $k$ that $D_{2,m}'(k) = P_m(1)+o_P(1)$ and hence we get
\begin{align} \label{e:Gamlat}
	\sup_{ k > m^L} \Gamma_{n,m}(k) = \sup_{k \ge m^L} \frac{-P_m(1)}{V_m/\sqrt{\tau_n}}+o_P(1).
\end{align}
Thus, combining \eqref{e:Gamear} and \eqref{e:Gamlat}, we  have established that
\[
\sup_{k \ge m^{1+\zeta}} \Gamma_{n,m}(k) = \sup_{k \ge m^{1+\zeta}} \frac{-P_m(1)}{V_m/\sqrt{\tau_n}}+o_P(1),
\]
which proves the Lemma.


\subsection{Proof of Theorem \ref{theomain}} \label{ss:p-main}
We combine Theorem \ref{lem_3} and Lemma \ref{lem_4} for this proof.
First, we decompose
\[
\sup_{k \ge 1}\Gamma_{n,m}(k) = \max \bigg\{ \sup_{1 \le k \le m^{5/4}}\Gamma_{n,m}(k), \sup_{k> m^{5/4}}\Gamma_{n,m}(k) \bigg\}.
\]
Using Lemma \ref{lem_4}, we have
\[
\sup_{k> m^{5/4}}\Gamma_{n,m}(k) = \frac{-P_m(1)}{V_m/\sqrt{\tau_n}}+o_P(1).
\]
Next, using the definition of $\Gamma_{n,m}(k)$ in \eqref{e:def:gam} and of the partial sum process $P_m$ in \eqref{e:def:Pm}, we have
\begin{align*}
	&\sup_{1 \le k \le  m^{5/4}}\Gamma_{n,m}(k) = \sup_{\substack{x = \frac{k}{m}, \\ k = 1, \ldots, \lfloor m^{5/4} \rfloor}}
	\frac{
		P_m(1 + x) - (x + 1) P_m(1)
	}{
		(1 + x) V_m / \sqrt{\tau_n}
	} \\
	=& \sup_{0 \le x \le m^{1/4}}
	\frac{
		P_m(1 + x) - (\lfloor xm \rfloor/m + 1) P_m(1)
	}{
		(1 + \lfloor xm \rfloor/m) V_m / \sqrt{\tau_n}.
	}
\end{align*}
Now, we move to the coupling from Theorem \ref{lem_3}. Consider the coupling of $(P_m, B_m)$ created in this lemma on a probability space $(\Omega_m, \mathcal{A}_m, \mathbb{P}_m)$. We can take the infinite product of these probability spaces and call it $(\Omega, \mathcal{A}, \mathbb{P})$.
Then we can write on this probability space
\[
\sup_{0 \le x \le m^{1/4}}|P_m(x)-B_m(x)|=o_P(1),
\]
where $(P_m)_m$ is a sequence of variables, distributed as our partial sum process with training sample size $m$ and $B_m$ a sequence of standard Brownian motions.
It then follows by the above approximation that
\begin{align*}
	&\sup_{0 \le x \le m^{1/4}} \frac{(P_m(1+x)-(\lfloor xm \rfloor/m+ 1) P_m(1))}{(1+\lfloor xm \rfloor/m)V_m/\sqrt{\tau_n}}\\
	= &\sup_{0 \le x  \le m^{1/4}} \frac{B_m(1+x)-(x+1)B_m(1)}{(1+x) \cdot \int_0^1 |B_m(s)-s B_m(1)|ds} +o_P(1)=:L_{1,M}+o_P(1)
\end{align*}
and
\[
\frac{-P_m(1)}{V_m/\sqrt{\tau_n}}= \frac{-B_m(1)}{\int_0^1 |B_m(s)-s B_m(1)|ds}+o_P(1)=:L_{2,M}+o_P(1) .
\]
Here, we have used that formally
\[
V_m /\sqrt{\tau_n}= \int_0^1 |P_m(s)-\lfloor sm\rfloor/m P_m(1)|ds.
\]
Now, to finish the proof, we have to study the distribution of $\max\{L_{1,m}, L_{2,m}\}$.
To this end, it is convenient to replace $B_m$ by a fixed Brownian motion $B$, giving us $\max\{L^B_{1,m}, L^B_{2,m}\}$ (now the distribution only depends on $m$ through the supremum). Using monotone convergence of the test statistic, it follows directly that pathwise
\[
L^B_{1,m}=\sup_{0 \le x  \le m^{1/4}} \frac{B(1+x)-(x+1)B(1)}{(1+x) \cdot \int_0^1 |B(s)-sB(1)|ds} \to \sup_{0 \le x  <\infty} \frac{B(1+x)-(x+1)B(1)}{(1+x) \cdot \int_0^1 |B(s)-sB(1)|ds} =L.
\]
Moreover, we have
\[
\lim_{x \to \infty}\frac{B(1+x)-(x+1)B(1)}{(1+x) \cdot \int_0^1 |B(s)-sB(1)|ds} = \frac{-B(1)}{\int_0^1 |B(s)-sB(1)|ds} = \lim_{m \to \infty} L_{2,m}^B,
\]
which shows the desired result that
$\max\{L^B_{1,m}, L^B_{2,m}\} \overset{d}{\to} L$.



\subsection{Proof of Corollary \ref{cor_test}} \label{ss:p-cor}
We only prove the second part, since the first part
(level control under the null hypothesis) is directly implied by
Theorem \ref{theomain}. In the proof, we will use the fact that by Lemma \ref{lem_var} we have that
\[
\tau_n = \tau^{(n)}+o(1)
\]
and that
\[
0<\tau^{(n)} \lesssim n^{2\epsilon}
\]
(see \eqref{e:intau(n)}). Notice that a condition of said lemma is that data are generated under the null-hypothesis. This is always true for the training sample, where ex hypothesi there exists no detectable signal. The definition of $\tau^{(n)}$ is to be udnerstood accordingly (an infinite series for hypothetical data generated under the null).
\\
Now, we consider the case $k^* \asymp m$ and without loss of generality assume that $k^* \ge m$. All other cases work exactly analogously and focusing on this specific case merely simplifies the presentation of the result. We have that
\begin{align}
	\sup_{k \ge 1} \Gamma_{n,m}(k) \ge  \Gamma_{n,m}(2k^*) = \frac{D_m(2k^*)/\sqrt{\tau_n}}{V_m/\sqrt{\tau_n}}.
\end{align}
We first briefly discuss the denominator. From the proof of Theorem \ref{theomain}, we have seen that $V_m/\sqrt{\tau_n} $ converges to a non-degenerate, a.s. positive random variable and hence
\[
(V_m/\sqrt{\tau_n})^{-1} = \mathcal{O}_P(1)
\]
(again, notice that the distribution of $V_m$ is the same under the null hypothesis and alternative because it only depends on the training sample).
We can hence focus our analysis on the numerator $D_m(2k^*)/\sqrt{\tau_n}$ and we begin by decomposing $D_m(2k^*)$
as follows
\begin{align} \nonumber
	D_m(2k^*)=  & \frac{n^{2/3}\sqrt{m}}{ \,\,m+2k^*}
	\bigg(\sum_{t=m+1}^{m+2k^*}\lambda_t-\frac{2k^*}{m}\sum_{t=1}^m\lambda_t\bigg)\\ = &\bigg\{ \frac{n^{2/3}\sqrt{m}}{ \,\,m+2k^*}
	\bigg(\sum_{t=m+1}^{m+k^*}\{\lambda_t-2\sigma\}-\frac{2k^*}{m}\sum_{t=1}^m\{\lambda_t-2\sigma\}\bigg)\bigg\}\nonumber\\
	& + \bigg\{ \frac{n^{2/3}\sqrt{m}}{ \,\,m+2k^*}
	\bigg(\sum_{t=m+k^*+1}^{m+2k^*}\Big\{\lambda_t-\Big(s_t + \frac{\sigma^2}{s_t} \Big)\Big\}\bigg)\bigg\}\nonumber\\
	& + \bigg\{\frac{n^{2/3}\sqrt{m}}{ \,\,m+2k^*}
	\bigg(\sum_{t=m+k^*+1}^{m+2k^*}\Big(s_t + \frac{\sigma^2}{s_t} \Big)-k^*(2\sigma)\bigg)\bigg\}=:R_1+R_2+R_3.\nonumber
\end{align}
The terms $R_1, R_2, R_3$ on the right are defined in the obvious way. The study of $R_1, R_2$ is related. For $R_1$, one uses the concentration result in Lemma \ref{lem_rmt} \ref{lem_rigidity}) and hence, we focus on the more challenging term $R_2$. For this analysis, we use the following fact that will be validated at the end of this proof. For any small enough constant $\chi>0$
\begin{align} \label{e:id:knowles}
	\mathbb{P}\bigg(\Big|\lambda_t -\Big(s_t + \frac{\sigma^2}{s_t} \Big)\Big|<n^{-1/2+\chi} \Big|\forall t=m+k^*+1,\ldots,m+2k^* \bigg)=1-o(1).
\end{align}
On this event, we have that
\begin{align*}
	R_2 \le \frac{n^{2/3}\sqrt{m}}{ \,\,m+k^*} n^{-1/2+\chi}k^* \asymp m^{1/2}n^{1/6+\chi}.
\end{align*}
Using the fact that $1/\sqrt{\tau_n}$ is bounded away from $0$, we get $R_2/\sqrt{\tau_n}=\mathcal{O}_P(m^{1/2}n^{1/6+\chi})$.\\
Finally, we turn to $R_3$, the dominating term. Recall that the probability measure $\mathbb{P}^{(2)}$ (supercritical signal under the alternative hypothesis) has support inside $(\sigma,\infty)$. The support is closed and hence its leftmost endpoint $x_*$ satisfies
\begin{align}
	\label{eq_lower_bound_x_star}
	x_* > \sigma + \eta
\end{align}
for some $\eta >0.$
Note that $s_t + \sigma^2 / s_t$ denotes the (random) approximate of $\lambda_t$ in the supercritical case (Lemma \ref{lem:pizzo}), while, in the subcritical case,  $\lambda_t$ approaches $2\sigma$ (Lemma \ref{lem_rmt} \ref{lem_tw}).
Thus, $R_3$ essentially consists of the difference of these two limits, and our task is to show that they are well-separated under our assumptions. To this end, consider the function $g(x)= x + \sigma^2 / x - 2 \sigma, ~x \geq \sigma.$ Then, it holds $g(\sigma)=0$, and g is monotonically increasing for $x \geq \sigma$.  Thus, using also \eqref{eq_lower_bound_x_star}, we obtain, for some $\eta' > 0$,
\begin{align*}
	s_t + \frac{\sigma^2}{s_t} - 2 \sigma = g(s_t) \geq \eta' \quad \textnormal{almost surely}.
\end{align*}
Consequently, we get the almost sure lower bound
\begin{align*}
	R_3 \ge \frac{n^{2/3}\sqrt{m}}{ \,\,m+k^*} (k^* \eta')\asymp n^{2/3}m^{1/2}.
\end{align*}
Since $\tau_n = \tau^{(n)}+o(1)$ and $\tau^{(n)} \lesssim n^{2\epsilon}$ (see beginning of this proof), we have that almost surely
\[
n^{2/3-\epsilon}m^{1/2}\lesssim R_3/\sqrt{\tau_n}.
\]
For all sufficiently small $\epsilon$ and $\chi$ (which occurs in the bound of $R_2$), we have that with probability going to $1$
\[
R_1/\sqrt{\tau_n}+R_2/\sqrt{\tau_n}\lesssim n^{2/3-\epsilon}m^{1/2} =o( R_3/\sqrt{\tau_n}).
\]
Since $ R_3/\sqrt{\tau_n} \to \infty$ as $m \to \infty$, we obtain
\begin{align*}
	\frac{D_m(2k^*)/\sqrt{\tau_n}}{V_m/\sqrt{\tau_n}} \ge \frac{R_3/\sqrt{\tau_n}}{V_m/\sqrt{\tau_n}}+o\bigg(\frac{R_3/\sqrt{\tau_n}}{V_m/\sqrt{\tau_n}}\bigg)\overset{P}{\to} \infty.
\end{align*}
Thus, it is left to show that \eqref{e:id:knowles} holds. For this result to hold, we use the union bound and get the upper bound 
\begin{align*}
	& \mathbb{P}\bigg(\Big|\lambda_t -\Big(s_t + \frac{\sigma^2}{s_t} \Big)\Big|<n^{-1/2+\chi} \Big|\forall t=m+k^*+1,\ldots,m+2k^* \bigg)
	\\ & \leq
	k^*  \mathbb{P}\bigg(\Big|\lambda_1 -\Big(s_1 + \frac{\sigma^2}{s_1} \Big)\Big|\ge n^{-1/2+\chi} \bigg) \\ & \asymp m \mathbb{P}\bigg(\Big|\lambda_1 -\Big(s_1 + \frac{\sigma^2}{s_1} \Big)\Big|\ge n^{-1/2+\chi} \bigg) =: m \mathbb{P}_m,
\end{align*}
where we used that we study the case $k^*\asymp m$.
We claim that $m \mathbb{P}_m$ converges to $0$. To see this, define the conditional probability
\[
f_m(s_1, \mathbf{x}_1):=\mathbb{P}\bigg(\Big|\lambda_1 -\Big(s_1 + \frac{\sigma^2}{s_1} \Big)\Big|\ge n^{-1/2+\chi} \Big| (s_1, \mathbf{x}_1)\bigg)
\]
and rewrite
\begin{align*}
	& m \mathbb{P}_m  = m\int_{f_m(s_1, \mathbf{x}_1)<1/m^2}  f_m(s_1, \mathbf{x}_1) + m \int_{f_m(s_1, \mathbf{x}_1) \ge 1/m^2}  f_m(s_1, \mathbf{x}_1) \\
	\le &  1/m + m \int_{f_m(s_1, \mathbf{x}_1) \ge 1/m^2}  f_m(s_1, \mathbf{x}_1).
\end{align*}
Now suppose on the contrary that $m \mathbb{P}_m$ does not converge to $0$. If this were so, there must be a sequence of values $(s_1, \mathbf{x}_1)$ (indexed in $n$ and thus $m$), such that $f_m(s_1, \mathbf{x}_1)>1/m^2 \ge n^{-c}$ for some constant $c>0$. This, however, is at odds with the Theorem 3.4 of \cite{knowles:yin:2014} which states that for any sequence  $(s_1, \mathbf{x}_1)$ (indexed in $n$) we have faster than polynomial decay of $f_m(s_1, \mathbf{x}_1)$ eventually. Consequently  $m \mathbb{P}_m\to 0$ is established.
Thus \eqref{e:id:knowles} holds, and the proof concludes.

\subsection{Proofs of Lemmas \ref{lem_rmt} and \ref{lem:pizzo}}
\label{ss:proof_rmt}

\noindent {\sc Proof of Lemma \ref{lem_rmt}:}
For the sake of notational convenience, we omit the index $1$ throughout this proof, writing $\bfx_1 = \bfx$, $s_1 =s$ and $\bfW_1 = \bfW.$
To begin with, we want to show that the diagonalization $\diag (s, 0, \ldots, 0)$ of the rank-one matrix $s \bfx \bfx^\top$ satisfies the regularity assumptions of \cite{Lee2015}, who consider the fluctuations and eigenvalue rigidity of a Wigner matrix under an diagonal deformation. We will then use universality results from \cite{Knowles2017} to allow for general rank-one perturbations.

Note that \cite{Lee2015} consider the random matrix $\mathbf{H} = \lambda_0 \mathbf{V} + \frac{1}{\sqrt{n}} \bfW,$ where $\bfW$ is a Wigner matrix with variance $1$ and $\mathbf{V}$ is a diagonal matrix. To align this definition with our framework \eqref{eq_def_M}, we set $\lambda_0 = 1$ and $\mathbf{V}=\diag(s/\sigma,0,\ldots,0) \in \R^{n\times n}$ such that $\sigma \mathbf{H} \stackrel{\mathcal{D}}{=} \diag(s,0, \ldots, 0) + \frac{1}{\sqrt{n}} \bfW$. By noting that, if the results of \cite{Lee2015} are valid for $\mathbf{H}$, they can also applied to the scaled matrix $\sigma \mathbf{H}$, we want to show that $\mathbf{H}$ satisfies Assumptions 2.1 and 2.2 of the aforementioned work.

For this purpose, denote $\lambda = \frac{s}{\sigma}$. Then the random variable $\lambda$ has a compact support in $[0,1)$. Since $s \sim \PR^{(1)}$, we may choose $0 \leq \lambda_l \leq \lambda_r < 1 $ independent of $n$ such that the support of $\lambda$ is contained in $[\lambda_l, \lambda_r]$.
Moreover, let
\begin{align*}
	F^{\mathbf{V}} = \frac{1}{n} \delta_\lambda + \frac{n-1}{n} \delta_0
\end{align*}
denote the (random) empirical spectral distribution of $\mathbf{V}.$ Then, the weak limit of $F^{\mathbf{V}}$, the so-called limiting spectral distribution of $\mathbf{V}$, is given by the point-mass distribution $\delta_0$ in the origin almost surely. It is straightforward to see that Assumption 2.1 and (2.5) of Assumption 2.2 in \cite{Lee2015} are satisfied. In order to verify (2.6) of Assumption 2.2 in the aforementioned work, it remains to show that
\begin{align}\label{eq_aim_schnelli}
	\inf_{x\in [\lambda_l,\lambda_r]} \int \frac{1}{(v-x)^2} dF^{\mathbf{V}} (v) \geq 1+\varepsilon
\end{align}
for sufficiently large $n$ and for some $\varepsilon>0$ with probability $1$. Note that the left-hand side of \eqref{eq_aim_schnelli} might be infinite for some $x$. In this case, this choice of $x$ may be neglected for showing the condition \eqref{eq_aim_schnelli}.
Using the definition of $F^{\mathbf{V}},$ we have almost surely
\begin{align*}
	\int \frac{1}{(v-x)^2} dF^{\mathbf{V}} (v) = \frac{1}{n} \frac{1}{(x-\lambda)^2} +  \frac{n-1}{n} \frac{1}{x^2} \geq \frac{n-1}{n} \frac{1}{\lambda_r}.
\end{align*}
Since $\lambda_r < 1 $ is fixed with respect to $n$, we find some constant $\varepsilon>0$ such that $(n-1)/( n \lambda_r) \geq 1 + \varepsilon$ for all large $n$.  Thus, we conclude that \eqref{eq_aim_schnelli} holds true.


In summary, we have shown the Assumptions 2.1 and 2.2 of \cite{Lee2015} are satisfied for $\mathbf{H}.$
The eigenvalue rigidity in part \ref{lem_rigidity} follows by combining  \cite[Lemma 4.3]{Lee2015} with the universality result \cite[Theorem 12.4]{Knowles2017}.
The Tracy-Widom fluctuation in part \ref{lem_tw} follow from \cite[Theorem 2.1]{Lee2015} and the universality result \cite[Theorem 12.5]{Knowles2017}.


\medskip


\noindent{\sc Proof of Lemma \ref{lem:pizzo}:}
According to Theorem 1.1 in \cite{pizzo_et_al_2013},
it holds for any (deterministic) sequence $(\mathbf{x}^{(n)})_n$ with $\mathbf{x}^{(n)} \in \mathbb{R}^n$ a vector of unit length, and $s \in [0,\sigma)$ fixed with respect to $n$ that
\[
r_n := \lambda\Big(s  \cdot \bfx^{(n)}(\bfx^{(n)})^\top + \bfW/\sqrt{n}\Big) -\Big(s+\frac{\sigma^2}{s}\Big)\overset{\mathbb{P}}{\to}0,
\]
where $\lambda(\mathbf{A})$ denotes the largest eigenvalue of a symmetric matrix $\mathbf{A}.$
We will show that this result is actually uniform over the $\mathbf{x}^{(n)}$ in the following sense: Let $S^{(n)} \subset \mathbb{R}^n$ be the Euclidean unit sphere, then for any $c>0$
\begin{align}
	\label{z1}
	\limsup_n \sup_{\mathbf{x}^{(n)} \in S^n} \mathbb{P}(|r_n|>c)=0.
\end{align}
If this were not so, and the right side was equal to some $\eta>0$, it would immediately follow that we could select a sequence $(\mathbf{x}^{(n,\star)})_n$ such that
\[
\limsup_n\mathbb{P}\bigg(\Big|\lambda\Big(s  \cdot \bfx^{(n,\star)}(\bfx^{(n,\star)})^\top+\bfW/\sqrt{n}\Big)  -\Big(s+\frac{\sigma^2}{s} \Big)\Big|>c\bigg) \ge \eta/2,
\]
contradicting the original theorem. \\
Next, consider our setup, where both $s, \mathbf{x}$ are random. In this case, we get
\begin{align*}
	&\mathbb{P}\bigg(\Big|\lambda\Big(s  \cdot \bfx\bfx^\top+ \bfW/\sqrt{n}\Big)-\Big(s+\frac{\sigma^2}{s} \Big) \Big|>c\bigg)\\
	= &\mathbb{E}\bigg[\mathbb{P}\bigg(\Big|\lambda\Big(s  \cdot \bfx\bfx^\top + \bfW/\sqrt{n}\Big) -\Big(s+\frac{\sigma^2}{s} \Big)\Big|>c \Big| s, \mathbf{x}\bigg)\bigg]\\
	\le & \mathbb{E}\bigg[\sup_{\bfx \in S^{(n)}}\mathbb{P}\bigg(\Big|\lambda\Big(s  \cdot \bfx\bfx^\top + \bfW/\sqrt{n}\Big) -\Big(s+\frac{\sigma^2}{s} \Big)\Big|>c\Big| s \Bigg)\bigg] =: \mathbb{E}[f_n(s)].
\end{align*}
Now, for any fixed $s'<\sigma$, it follows from \eqref{z1} that $f_n(s') \to 0$. This convergence is pointwise and $f_n$ is dominated by the constant $1$-function. Accordingly, by the dominated convergence theorem, we have
\[
\lim_{n \to \infty}\mathbb{E}[f_n(s)] = \lim_{n \to \infty}\int f_n(t) d\mathbb{P}^s(t) = \int \lim_{n \to \infty}f_n(t) d\mathbb{P}^s(t)=0.
\]

\subsection{Auxiliary lemmas} \label{ss:au}
Recall the definition of the Prokhorov metric $\pi$ in
\eqref{eq_def_prokhorov_metric}.

\begin{lemma}[Theorem 2.13 \cite{huber:ronchetti:2009}] \label{lem:huber}
	Let $X,Y$ be two random variable on a separable metric space $(\mathcal{M},d)$.
	Then the following statements are equivalent:
	\begin{itemize}
		\item[i)] $\pi(X,Y)\le  \delta$.
		\item[ii)] There exists a vector $(\tilde X,\tilde Y)$,  s.t. $\mathcal{L}(\tilde X)
		= \mathcal{L}(\tilde X)$, $\mathcal{L}(\tilde Y) = \mathcal{L}(Y)$ defined on some suitable probability space, s.t.  $\mathbb{P}(d(\tilde X,\tilde Y)\le \delta)\ge 1-\delta$.
	\end{itemize}
	The implication from i) to ii) also holds without the assumption of separability.
\end{lemma}

\begin{lemma}
	\label{lem_p_t}
	Consider any numbers $D_1, D_2>0$ (arbitrarily large) and any $\varepsilon>0$ (arbitrarily small) and let $A_m \asymp m^{D_1}$ with $A_m \in \mathbb{N}$ for all $m$. Then, it holds for the probability
	\[
	p_{A_m}:= \mathbb{P}\bigg( \bigcup_{t=1}^{A_m} \Lambda_t^c\bigg), \qquad \textnormal{that} \qquad p_{A_m} \lesssim m^{-D_2}.
	\]
	Here the event $\Lambda_t$ is defined in \eqref{eq_def_Lambda_t} and depends on the constant $\varepsilon$.
\end{lemma}

\begin{proof}
	The proof is a simple consequence of Lemma \ref{lem_rmt} part \ref{lem_rigidity}  together with Assumption \ref{ass_2}, which states that $m^\theta\asymp n$. In said lemma, choose $D= (D_1+D_2)/\theta$. This implies (together with stationarity of the time series) that
	\begin{align*}
		p_{A_m} \le \sum_{t=1}^{A_m} \mathbb{P}(\Lambda_t^c) \le A_m \mathbb{P}(\Lambda_1^c) \lesssim A_m n^{-D} \asymp A_m m^{-D\theta }.
	\end{align*}
	Now, using the fact that $A_m \lesssim m^{D_1}$, we get
	\[
	A_m m^{-D\theta } \lesssim m^{D_1-D\theta } = m^{D_1-(D_1+D_2)} = m^{-D_2}.
	\]
	This concludes the proof.
\end{proof}


\begin{lemma} \label{lem:exp}
	Suppose that Assumptions \ref{ass_wigner}, \ref{ass_2} and \ref{ass_3} hold. Then, it follows that
	\[
	\mathbb{E}[\lambda_t] = \mathbb{E}[\lambda_t|\Lambda_t]+Rem,
	\]
	where the remainder satisfies $Rem = \mathcal{O}(m^{-D})$ for any $D>0$ and is independent of $t$.
\end{lemma}
\begin{proof}
	We notice that $\lambda_t = \lambda_t\mathbb{I}\{\Lambda_t\}$ except on a set with probability $\lesssim m^{-D_2}$ (see Lemma \ref{lem_p_t} above), where $D_2$ can be chosen arbitrarily large. Thus, we get
	\[
	\mathbb{E}[\lambda_t] = \mathbb{E}[\lambda_t\mathbb{I}\{\Lambda_t\}] +\mathbb{E}[\lambda_t\mathbb{I}\{\Lambda_t^c\}].
	\]
	Let us now consider $\mathbb{E}[\lambda_t\mathbb{I}\{\Lambda_t^c\}]$, where we observe the upper bound
	\begin{align*}
		\mathbb{E}[\lambda_t\mathbb{I}\{\Lambda_t^c\}] \le \left( \mathbb{E}[\lambda_t^2] \right) ^{1/2} \mathbb{P}\{\Lambda_t^c\}^{1/2} \lesssim \left( \mathbb{E}[\lambda_t^2] \right) ^{1/2}  m^{-D_2/2}.
	\end{align*}
	Since $\lambda_t$ it the biggest eigenvalue of $\mathbf{M}_t$, it is upper bounded by 
	its spectral norm $\|\mathbf{M}_t\|_2$. We thus obtain
	\begin{align*}
		\mathbb{E}[\lambda_t^2] \le \sum_{i,j}   4\mathbb{E}[|(s \cdot \bfx\bfx^\top)_{i,j}|^2 + w_{i,j}^2] \lesssim n^2 \lesssim m^{2/\theta},
	\end{align*}
	where we used Assumption \ref{ass_2} for the last estimate.
	Thus, choosing $D_2$ large enough, we get that $\mathbb{E}[\lambda_t\mathbb{I}\{\Lambda_t^c\}]$ decays at an (arbitrarily fast) polynomial rate in $m$. Using a similar argument, we get that
	\[
	\mathbb{E}[\lambda_t\mathbb{I}\{\Lambda_t\}] = \mathbb{E}[\lambda_t|\Lambda_t]+Rem,
	\]
	where the remainder $Rem$ is decaying at an arbitrarily fast polynomial rate.
\end{proof}

We conclude this section with a Lemma on the convergence of the long-run variance.
Recall the definitions of $\tau_{k,n}$ and $\tau^{(n)}$ in \eqref{eq_def_tau} and the parameter $\varepsilon$ from \eqref{eq_def_Lambda_t}.
\begin{lemma} \label{lem_var}
	Under the conditions of Theorem \ref{lem_3}, it holds for any fixed $\eta \in (0,1)$ and for some universal constant $C=C(\eta)>0$ that
	\[
	|\tau_{k,n}-\tau^{(n)}| \le C n^{2\varepsilon} k^{-(1-\eta)}.
	\]
\end{lemma}


\begin{proof}
	Let $\eta \in (0,1)$ be some constant.  Using stationarity, we can rewrite
	\begin{align*}
		\tau_{k,n} = \sum_{|h|<k}(1-|h|/k)\mathbb{E}[Y_0Y_t] = \tau^{(n)} + \mathcal{O}\Big(  \sum_{|h|<k^\eta} (|h|/k)|\mathbb{E}[Y_0Y_t]|\Big) +  \mathcal{O}\Big(  \sum_{|h|\ge k^\eta} |\mathbb{E}[Y_0Y_t]|\Big).
	\end{align*}
	Since $\mathbb{E}Y_t^2 = \mathcal{O}(n^{2\varepsilon})$  by \eqref{e:bYt}, it follows for the second term on the right that
	\begin{align*}
		\sum_{|h|<k^{\eta}} (|h|/k)|\mathbb{E}[Y_0Y_t]| \lesssim k^{-1+\eta} n^{2\varepsilon}.
	\end{align*}
	Next, using the mixing property of the time series, we obtain with the mixing inequality from \cite{dehling:mikosch:sorensen:2002} (  (3.17)) for bounded variables that
	\[
	|\mathbb{E}[Y_0Y_t]| \lesssim n^{2\varepsilon} \phi(t).
	\]
	Since $\phi(t) \lesssim a^{t}$ for $a \in (0,1)$ (see Assumption \ref{ass_3}, part i)) we obtain for the other term
	\begin{align*}
		\sum_{|h|\ge k^\eta} |\mathbb{E}[Y_0Y_t]| \lesssim n^{2\varepsilon} \sum_{|h|\ge k^\eta} a^{t} \lesssim  n^{2\varepsilon} k^{-1+\eta}.
	\end{align*}
	This concludes the proof of Lemma \ref{lem_var}.
\end{proof}


