\section{Asymptotic equivalence of $H_S$ and $H_M$}

Using Eq.s~\ref{eq:ShannonCEcounts}~and~\ref{eq:CEMicro}, we have
\begin{align}
N\times H_S(\bm{w}\vert \bm{V}) &= \sum_{\bm{s}}n_{\bm{s}}\log n_{\bm{s}} - \sum_{r,\bm{s}}n_{r,\bm{s}}\log n_{r,\bm{s}}, \\
N\times H_M(\bm{w}\vert \bm{V}) &= \sum_{\bm{s}}\log n_{\bm{s}}! - \sum_{r,\bm{s}}\log n_{r,\bm{s}}!,
\end{align}
where we have omitted superscripts for brevity. In the limit $n_{r,\bm{s}}\gg 1$ for all $r,\bm{s}$, we can use the Stirling approximations
\begin{align}
\log (n_{r,\bm{s}}!) &\approx n_{r,\bm{s}}\log n_{r,\bm{s}}-n_{r,\bm{s}}/\ln(2),\\
\log (n_{\bm{s}}!) &\approx n_{\bm{s}}\log n_{\bm{s}}-n_{\bm{s}}/\ln(2),
\end{align}
giving
\begin{align}
N\times H_M(\bm{w}\vert \bm{V}) &\approx 
\sum_{\bm{s}}[n_{\bm{s}}\log n_{\bm{s}}-n_{\bm{s}}/\ln(2)] - \sum_{r,\bm{s}}[n_{r,\bm{s}}\log n_{r,\bm{s}}-n_{r,\bm{s}}/\ln(2)]\\
&=\sum_{\bm{s}}n_{\bm{s}}\log n_{\bm{s}} - N/\ln(2) - \sum_{r,\bm{s}}n_{r,\bm{s}}\log n_{r,\bm{s}} + N/\ln(2)\\
&= N\times H_S(\bm{w}\vert \bm{V}),
\end{align}
and thus $H_S\approx H_M$ in this regime.

\section{Asymptotic scaling of conditional entropy correction $\log\Omega/N$}

From Eq.~\ref{eq:Omega}, we have
\begin{align}
\frac{\log \Omega}{N} &= \frac{1}{N}\sum_{\bm{s}}\log{n^{(\bm{V})}_{\bm{s}}+C-1\choose C-1}\\
&\leq \frac{1}{N}\sum_{\bm{s}}\log \frac{(n^{(\bm{V})}_{\bm{s}}+C-1)^{(C-1)}}{(C-1)!}\\
&\leq \frac{1}{N}\sum_{\bm{s}}(C-1)\log (N+C-1)\\
&\leq \frac{\log (N+C-1)}{N}(C-1)C^k,
\end{align}
where $k$ is the dimension (i.e. lag in the transfer entropy calculation) of the time series $\bm{V}$. In the limit $N\to\infty$ with $C$ fixed, this expression vanishes and $H_C\approx H_M \approx H_S$.

\section{Non-positivity of transfer entropy correction $\Delta$}

The correction to the transfer entropy in Eq.~\ref{eq:correction} is given by
\begin{align}\label{eq:corrmultiset}
\Delta^{(k,l)}_{\bm{x}\to \bm{y}} = \frac{1}{N}\log \frac{\prod\limits_{\bm{r}}\bigbinom{n^{(\bm{Y}^{(-l)})}_{\bm{r}}+C-1}{C-1}}{\prod\limits_{\bm{r},\bm{s}}\bigbinom{n^{(\bm{Y}^{(-l)},\bm{X}^{(-k)})}_{\bm{r},\bm{s}}+C-1}{C-1}}
= \frac{1}{N}\log \prod\limits_{\bm{r}}\frac{\multiset{C}{n^{(\bm{Y}^{(-l)})}_{\bm{r}}}}{\prod\limits_{\bm{s}}\multiset{C}{n^{(\bm{Y}^{(-l)},\bm{X}^{(-k)})}_{\bm{r},\bm{s}}}},
\end{align}
where
\begin{align}
\multiset{n}{k} = {n+k-1\choose k}    
\end{align}
is the multiset coefficient counting the number of unique ways to construct a multiset of $k$ elements with draws from set of $n$ elements with replacement. In \cite{felippe2024network} it was shown that multiset coefficients satisfy 
\begin{align}
\multiset{n}{k}\multiset{n}{l} \geq \multiset{n}{k+l},  
\end{align}
for any $n,k,l$. This inequality implies that
\begin{align}
\multiset{C}{n^{(\bm{Y}^{(-l)})}_{\bm{r}}} \leq \prod\limits_{\bm{s}}\multiset{C}{n^{(\bm{Y}^{(-l)},\bm{X}^{(-k)})}_{\bm{r},\bm{s}}},    
\end{align}
since 
\begin{align}
\sum_{\bm{s}}n^{(\bm{Y}^{(-l)},\bm{X}^{(-k)})}_{\bm{r},\bm{s}} = n^{(\bm{Y}^{(-l)})}_{\bm{r}}.    
\end{align}
Thus, we have
\begin{align}
\Delta^{(k,l)}_{\bm{x}\to \bm{y}}
 = \frac{1}{N}\sum_{\bm{r}}\log \frac{\multiset{C}{n^{(\bm{Y}^{(-l)})}_{\bm{r}}}}{\prod\limits_{\bm{s}}\multiset{C}{n^{(\bm{Y}^{(-l)},\bm{X}^{(-k)})}_{\bm{r},\bm{s}}}}
 \leq \frac{1}{N}\sum_{\bm{r}}\log \frac{\prod\limits_{\bm{s}}\multiset{C}{n^{(\bm{Y}^{(-l)},\bm{X}^{(-k)})}_{\bm{r},\bm{s}}}}{\prod\limits_{\bm{s}}\multiset{C}{n^{(\bm{Y}^{(-l)},\bm{X}^{(-k)})}_{\bm{r},\bm{s}}}}
 =\frac{1}{N}\sum_{\bm{r}}\log(1) = 0,
\end{align}
and the correction is bounded above by zero. Hence the proposed transfer entropy measure is a ``reduced'' version of the standard transfer entropy.

\section{Positive bias of the standard transfer entropy}
Since it is strictly non-negative, any statistical fluctuations must push the standard transfer entropy of Eq.~\ref{eq:TE-mostgeneral} towards values greater than zero for uncorrelated time series, for which we would ideally return zero to indicate a lack of forecasting capability of $\bm{y}$ from $\bm{x}$. We refer to this as the ``positive bias'' of the transfer entropy, and here try to understand how it behaves analytically.

For completely uncorrelated time series, the true underlying probability of each outcome $(q,\bm{r},\bm{s})$ is $1/C^{k+l+1}$. Thus, under a maximum entropy assumption the contingency table $\bm{n}$ will be distributed like a multinomial distribution with uniform bin probabilities $1/C^{k+l+1}$. The expected value of the transfer entropy under this null model is  
\begin{align}
\expec{\mathcal{T}^{(k,l)}_{\bm{x}\to\bm{y}}} &= 
\expec{H_S(\bm{y}^{(+1)}\vert \bm{Y}^{(-l)})} - \expec{H_S(\bm{y}^{(+1)}\vert \bm{Z}^{(-k,-l)})}\\
&=\expec{H_{q,\bm{r}}} + \expec{H_{\bm{r},\bm{s}}} -\expec{H_{\bm{r}}} - \expec{H_{q,\bm{r},\bm{s}}}, 
\end{align}
where
\begin{align}
\expec{H_{\bm{a}}} &= -\left\langle\sum_{\bm{a}}\frac{n_{\bm{a}}}{N}\log \frac{n_{\bm{a}}}{N}\right\rangle \\
&=\frac{1}{N}\left\langle\sum_{\bm{a}}n_{\bm{a}}\log N - n_{\bm{a}}\log n_{\bm{a}}\right\rangle \\
&=\log N - \frac{1}{N}\left\langle\sum_{\bm{a}}n_{\bm{a}}\log n_{\bm{a}}\right\rangle \\
&=\log N - \frac{\abs{\mathcal{X}(\bm{a})}}{N}\left\langle n_{\bm{a}}\log n_{\bm{a}}\right\rangle
\end{align}
is the expected Shannon entropy of counts indexed by $\bm{a}$ when the multi-way contingency table $\bm{n}$ of all joint counts is distributed as a uniform multinomial, and $\abs{\mathcal{X}(\bm{a})}$ is the size of $\bm{a}$'s support. This holds since when the full multi-way contingency table entries $\{n_{q,\bm{r},\bm{s}}\}$ are uniform-multinomially distributed, all of the table marginals are also uniform-multinomially distributed over the corresponding new smaller dimension. Now, the marginal distribution of $n_{\bm{a}}$ is a Binomial with $N$ trials and success probability $1/\abs{\mathcal{X}(\bm{a})}$, so the desired expectation is given by
\begin{align}
\left\langle n_{\bm{a}}\log n_{\bm{a}}\right\rangle
 = \sum_{k=0}^{N}{N\choose k}\left(\frac{1}{\abs{\mathcal{X}(\bm{a})}}\right)^{k}\left(1-\frac{1}{\abs{\mathcal{X}(\bm{a})}}\right)^{N-k}k\log k,
\end{align}
which unfortunately is intractable. However, if we approximate the binomial distribution as a Normal distribution in the limit of large $N$ and fixed $\abs{\mathcal{X}(\bm{a})}$, we have that the expectation is approximately
\begin{align}
\left\langle n_{\bm{a}}\log n_{\bm{a}}\right\rangle
 &\approx \mathbb{E}_{x\sim \mathcal{N}(\mu,\sigma^2)}[x\log x],
\end{align}
where 
\begin{align}
\mu &= \frac{N}{\abs{\mathcal{X}(\bm{a})}},\\
\sigma^2 &= \frac{N}{\abs{\mathcal{X}(\bm{a})}}\left(1-\frac{1}{\abs{\mathcal{X}(\bm{a})}}\right).
\end{align}
This is also intractable but admits a simple solution if we expand $x\log x$ via Taylor expansion about the maximum, thus 
\begin{align}
\mathbb{E}[x\log x] &\approx \mathbb{E}\left[\mu \log \mu + (1+\log \mu)(x-\mu) + \frac{1}{2\mu}(x-\mu)^2 \right] \\
&= \mu \log \mu + \frac{\sigma^2}{2\mu}\\
&= \frac{N}{\abs{\mathcal{X}(\bm{a})}} \log \frac{N}{\abs{\mathcal{X}(\bm{a})}} + \frac{1}{2}\left(1-\frac{1}{\abs{\mathcal{X}(\bm{a})}}\right).
\end{align}
We thus have
\begin{align}
\expec{H_{\bm{a}}} = \log \abs{\mathcal{X}(\bm{a})} - \frac{\abs{\mathcal{X}(\bm{a})}}{2N}\left(1-\frac{1}{\abs{\mathcal{X}(\bm{a})}}\right).    
\end{align}
Subbing this in to our expression for the expected transfer entropy and replacing the $\abs{\mathcal{X}(\bm{a})}$ terms appropriately, we have
\begin{align}
\expec{\mathcal{T}^{(k,l)}_{\bm{x}\to\bm{y}}} 
&=\expec{H_{q,\bm{r}}} + \expec{H_{\bm{r},\bm{s}}} -\expec{H_{\bm{r}}} - \expec{H_{q,\bm{r},\bm{s}}}\\
&\approx \frac{C^l}{2N}\left(1-\frac{1}{C^l}\right)
+ \frac{C^{k+l+1}}{2N}\left(1-\frac{1}{C^{k+l+1}}\right)
- \frac{C^{l+1}}{2N}\left(1-\frac{1}{C^{l+1}}\right)
- \frac{C^{k+l}}{2N}\left(1-\frac{1}{C^{k+l}}\right)\\
&= \frac{C^l(C^k-1)(C-1)}{2N}\\
&\sim \frac{C^{k+l+1}}{N}.
\end{align}

Looking at this result, we can see that the positive bias of the standard transfer entropy will become greater as: (1) the cardinality $C$ increases; (2) the number of timesteps $T$ decreases; or (3) the lags $k,l$ increase. This is consistent with the results seen in Fig.~\ref{fig:main-heat} and Fig.~\ref{fig:cross-section-main}. All of these factors lead to sparser bin counts, which intuitively should result in less reliable estimation. However, in the same regime of uniformity, the reduced transfer entropy gives a downward adjustment of 
\begin{align}
\Delta^{(k,l)}_{\bm{x}\to \bm{y}}
 = \frac{1}{N}\sum_{\bm{r}}\log \frac{\multiset{C}{n^{(\bm{Y}^{(-l)})}_{\bm{r}}}}{\prod\limits_{\bm{s}}\multiset{C}{n^{(\bm{Y}^{(-l)},\bm{X}^{(-k)})}_{\bm{r},\bm{s}}}}
 \sim \frac{C^l}{N}\log \frac{\multiset{C}{N/C^l}}{\multiset{C}{N/C^{k+l}}^{C^{k}}}
 \sim O\left(\frac{C^{k+l+1}\log N}{N}\right).
\end{align}
Thus, the reduced transfer entropy helps to correct the positive bias of the standard transfer entropy. This is also consistent with what is observed in our numerical experiments.

\section{Bounds on transfer entropies}

From Eq.~\ref{eq:TE-mostgeneral}, we find
\begin{align}
\mathcal{T}^{(k,l)}_{\bm{x}\to\bm{y}} &= 
H_S(\bm{y}^{(+1)}\vert \bm{Y}^{(-l)}) - H_S(\bm{y}^{(+1)}\vert \bm{Z}^{(-k,-l)}) \leq H_S(\bm{y}^{(+1)}\vert \bm{Y}^{(-l)}),
\end{align}
since the conditional entropies are both non-negative. Thus, $H_S(\bm{X}^{(-k)}\vert \bm{Y}^{(-l)})$ is an upper bound on $\mathcal{T}^{(k,l)}_{\bm{x}\to\bm{y}}$ over all time series $\bm{x}$. Similarly, for the reduced transfer entropy we have
\begin{align}
\mathcal{R}^{(k,l)}_{\bm{x}\to\bm{y}} &= 
\Delta^{(k,l)}_{\bm{x}\to \bm{y}} + \frac{1}{N}\log \frac{\prod\limits_{q,\bm{r},\bm{s}}n^{(+1,{-}l,{-}k)}_{q,\bm{r},\bm{s}}!\prod\limits_{\bm{r}}n^{({-}l)}_{\bm{r}}!}{\prod\limits_{q,\bm{r}}n^{({+}1,-l)}_{q,\bm{r}}!\prod\limits_{\bm{r},\bm{s}}n^{({-}l,{-}k)}_{\bm{r},\bm{s}}!}\\
&\leq \Delta^{(k,l)}_{\bm{x}\to \bm{y}} + \frac{1}{N}\log \frac{\prod\limits_{\bm{r},\bm{s}}n^{({-}l,{-}k)}_{\bm{r},\bm{s}}!\prod\limits_{\bm{r}}n^{({-}l)}_{\bm{r}}!}{\prod\limits_{q,\bm{r}}n^{({+}1,-l)}_{q,\bm{r}}!\prod\limits_{\bm{r},\bm{s}}n^{({-}l,{-}k)}_{\bm{r},\bm{s}}!}\\
&= \Delta^{(k,l)}_{\bm{x}\to \bm{y}} + \frac{1}{N}\log \frac{\prod\limits_{\bm{r}}n^{({-}l)}_{\bm{r}}!}{\prod\limits_{q,\bm{r}}n^{({+}1,-l)}_{q,\bm{r}}!}\\
&= \Delta^{(k,l)}_{\bm{x}\to \bm{y}} + H_M(\bm{y}^{(+1)}\vert \bm{Y}^{(-l)}),
\end{align}
giving $\Delta^{(k,l)}_{\bm{x}\to \bm{y}} + H_M(\bm{y}^{(+1)}\vert \bm{Y}^{(-l)})$ as an upper bound on $\mathcal{R}^{(k,l)}_{\bm{x}\to\bm{y}}$. Both of these upper bounds are saturated when
\begin{align}\label{eq:uppersaturated}
n^{({-}l,{-}k)}_{\bm{r},\bm{s}}  
 = n^{(+1,{-}l,{-}k)}_{q,\bm{r},\bm{s}} 
\end{align}
for all $\bm{r},\bm{s}$ and some $q$ fixed by $\bm{r},\bm{s}$. In other words, this upper bound is saturated when we are completely certain about the value $y_{t+1}=q$ when $\bm{x}^{(-k)}_t=\bm{s}$ and $\bm{y}^{(-l)}_t=\bm{r}$ are both known, meaning that $\bm{x}^{(-k)}_t$ maximally reduces the uncertainty about $y_{t+1}$ given the information provided by $\bm{y}^{(-l)}_t$.  

For lower bounds, the standard transfer entropy satisfies $\mathcal{T}^{(k,l)}_{\bm{x}\to\bm{y}}\geq 0$, as conditioning always reduces entropy \cite{cover1991elements}. Meanwhile, for the reduced transfer entropy we have
\begin{align}
\mathcal{R}^{(k,l)}_{\bm{x}\to\bm{y}} &= 
\Delta^{(k,l)}_{\bm{x}\to \bm{y}} + H_M(\bm{y}^{(+1)}\vert \bm{Y}^{(-l)})-H_M(\bm{y}^{(+1)}\vert \bm{Y}^{(-l)},\bm{X}^{(-k)}). 
\end{align}
The term $H_M(\bm{y}^{(+1)}\vert \bm{Y}^{(-l)})$ counts ($1/N$ times the logarithm of) the number of valid configurations of $\bm{y}^{(+1)}$ given the constraints provided by $\bm{Y}^{(-l)}$ and the contingency table $\bm{n}^{(\bm{y}^{(+1)},\bm{Y}^{(-l)})}$. Meanwhile, the term $H_M(\bm{y}^{(+1)}\vert \bm{Y}^{(-l)},\bm{X}^{(-k)})$ counts ($1/N$ times the logarithm of) the number of valid configurations of $\bm{y}^{(+1)}$ given the constraints provided by $\bm{Y}^{(-l)}$, $\bm{X}^{(-k)}$, and the contingency table $\bm{n}^{(\bm{y}^{(+1)},\bm{Y}^{(-l)},\bm{X}^{(-k)})}$. There must be at least as many valid configurations of $\bm{y}^{(+1)}$ under the first set of constraints as the second, since any valid configuration of $\bm{y}^{(+1)}$ under the second set of constraints is also valid under the first set of constraints. This is the combinatorial equivalent to conditioning always reducing entropy. Therefore, we have
\begin{align}
H_M(\bm{y}^{(+1)}\vert \bm{Y}^{(-l)}) \geq  H_M(\bm{y}^{(+1)}\vert \bm{Y}^{(-l)},\bm{X}^{(-k)})    
\end{align}
and so 
\begin{align}
\mathcal{R}^{(k,l)}_{\bm{x}\to\bm{y}} = 
\Delta^{(k,l)}_{\bm{x}\to \bm{y}} + H_M(\bm{y}^{(+1)}\vert \bm{Y}^{(-l)}) -  H_M(\bm{y}^{(+1)}\vert \bm{Y}^{(-l)},\bm{X}^{(-k)})
\geq \Delta^{(k,l)}_{\bm{x}\to \bm{y}}.
\end{align}
Thus, $\Delta^{(k,l)}_{\bm{x}\to \bm{y}}$ is a lower bound for $\mathcal{R}^{(k,l)}_{\bm{x}\to\bm{y}}$. Both of these lower bounds are saturated when 
\begin{align}\label{eq:lowersaturated}
n^{({-}l)}_{\bm{r}} = n^{({-}l,{-}k)}_{\bm{r},\bm{s}}
\end{align}
for all $\bm{r}$ and some $\bm{s}$ fixed by $\bm{r}$. In other words, this lower bound is saturated when we are completely certain about the value of $\bm{x}_t^{(-k)}=\bm{s}$ when $\bm{y}_t^{(-l)}=\bm{r}$ is known, or equivalently when $\bm{x}_t^{(-k)}$ and $\bm{y}_t^{(-l)}$ provide redundant information as they are identical up to relabelings of symbols.

Although it is a valid upper bound, $\Delta^{(k,l)}_{\bm{x}\to \bm{y}} + H_M(\bm{X}^{(-k)}\vert \bm{Y}^{(-l)})$ may be negative or zero for $\mathcal{R}^{(k,l)}_{\bm{x}\to\bm{y}}\leq 0$, in which case it does not provide a suitable normalization for $\hat{\mathcal{R}}^{(k,l)}_{\bm{x}\to\bm{y}}$ as it does not allow us to uniquely determine the sign of $\mathcal{R}$ from its normalized value. Therefore, when $\mathcal{R}^{(k,l)}_{\bm{x}\to\bm{y}}\leq 0$, we can use the alternative upper bound $-\Delta^{(k,l)}_{\bm{x}\to \bm{y}}\geq 0$, so that the minimum reduced transfer entropy is found at $\mathcal{R}^{(k,l)}_{\bm{x}\to\bm{y}}=\Delta^{(k,l)}_{\bm{x}\to \bm{y}}$ with a normalized value of $\hat{\mathcal{R}}^{(k,l)}_{\bm{x}\to\bm{y}}=-1$ in Eq.~\ref{eq:normTEreduced}. $-\Delta^{(k,l)}_{\bm{x}\to \bm{y}}$ provides a valid normalization for $\mathcal{R}\leq 0$ since in this case we have
\begin{align}
\abs{\mathcal{R}^{(k,l)}_{\bm{x}\to\bm{y}}} = -\mathcal{R}^{(k,l)}_{\bm{x}\to\bm{y}}=  -\Delta^{(k,l)}_{\bm{x}\to \bm{y}} -[ H_M(\bm{y}^{(+1)}\vert \bm{Y}^{(-l)}) -  H_M(\bm{y}^{(+1)}\vert \bm{Y}^{(-l)},\bm{X}^{(-k)})]
\leq -\Delta^{(k,l)}_{\bm{x}\to \bm{y}}.
\end{align}
The final step follows from $H_M(\bm{y}^{(+1)}\vert \bm{Y}^{(-l)}) \geq  H_M(\bm{y}^{(+1)}\vert \bm{Y}^{(-l)},\bm{X}^{(-k)})$.


\section{Finite-size deviation between $H_S$ and $H_M$}

As shown, the Shannon conditional entropy $H_S$ (Eq.~\ref{eq:ShannonCEcounts}) and the microcanonical conditional entropy $H_M$ (Eq.~\ref{eq:CEMicro}) are equivalent when $n_{r,\bm{s}}\gg 1$ for all $r,\bm{s}$. However, as discussed, we are often not in this count-rich regime in practice. Therefore, $H_S$ and $H_M$ may differ considerably. Outside of the count-rich regime, we must take higher order terms in the Stirling approximation
\begin{align}
\log n! \approx n\log n-n/\ln(2)+\frac{1}{2}\log(2\pi n),    
\end{align}
giving
\begin{align}
N\times (H_M-H_S) &= \sum_{\bm{s}}[\log n_{\bm{s}}! - n_{\bm{s}}\log n_{\bm{s}}]
+ \sum_{r,\bm{s}}[n_{r,\bm{s}}\log n_{r,\bm{s}}-\log n_{r,\bm{s}}!]\\
&\approx \frac{1}{2}\sum_{\bm{s}}\log (2\pi n_{\bm{s}})
- \frac{1}{2}\sum_{r,\bm{s}}\log (2\pi n_{r,\bm{s}}).
\end{align}
This suggests that the discrepancy between $H_S$ and $H_M$ vanishes when $n_{\bm{s}}=n_{r,\bm{s}}$ for all $\bm{s}$ and some single $r$ for each $\bm{s}$. But this is simply when $H_S=H_M=0$ are both minimized. 

On the other hand, if we are in the regime with
\begin{align}
n_{r,\bm{s}}=\frac{n_{\bm{s}}}{\abs{\mathcal{X}(r)}},    
\end{align}
this will be the regime in which the conditional entropies are maximized, since we learn nothing about $r$ by knowing $\bm{s}$ when $n_{r,\bm{s}}=n_{r',\bm{s}}$ for all $r,r',\bm{s}$. In this case, we have
\begin{align}
N\times (H_M-H_S) &\approx \frac{1}{2}\sum_{\bm{s}}\log (2\pi n_{\bm{s}})
- \frac{1}{2}\sum_{r,\bm{s}}\log (2\pi n_{\bm{s}}/\abs{\mathcal{X}(r)}).
\end{align}
This can be simplified further when the counts $n_{\bm{s}}=N/\abs{\mathcal{X}(\bm{s})}$ are equal, giving
\begin{align}
N\times (H_M-H_S) &\approx \frac{1}{2}\sum_{\bm{s}}\log (2\pi N/\abs{\mathcal{X}(\bm{s})})
- \frac{1}{2}\sum_{r,\bm{s}}\log (2\pi N/\abs{\mathcal{X}(\bm{s})}/\abs{\mathcal{X}(r)})\\
&=\frac{\abs{\mathcal{X}(\bm{s})}}{2}\log \frac{2\pi N}{\abs{\mathcal{X}(\bm{s})}} - \frac{\abs{\mathcal{X}(r)}\abs{\mathcal{X}(\bm{s})}}{2}\log \frac{2\pi N}{\abs{\mathcal{X}(r)}\abs{\mathcal{X}(\bm{s})}}\\
&=\frac{\abs{\mathcal{X}(\bm{s})}}{2}\log \frac{2\pi N}{\abs{\mathcal{X}(\bm{s})}}[1-\abs{\mathcal{X}(r)}]
+ \frac{\abs{\mathcal{X}(r)}\abs{\mathcal{X}(\bm{s})}}{2}\log \abs{\mathcal{X}(r)}.
\end{align}
This expression suggests that, as $N$ grows with $\abs{\mathcal{X}(r)},\abs{\mathcal{X}(\bm{s})}$ fixed, we have multiple distinct regimes:
\begin{enumerate}
    \item For $N \lesssim \abs{\mathcal{X}(r)}\abs{\mathcal{X}(\bm{s})}$, $H_M$ exceeds $H_S$, with a considerable discrepancy of at least $\frac{\abs{\mathcal{X}(r)}\abs{\mathcal{X}(\bm{s})}}{2}\log \abs{\mathcal{X}(r)}$ when $N\lesssim \abs{\mathcal{X}(\bm{s})}$
    \item For $N \gtrsim \abs{\mathcal{X}(r)}\abs{\mathcal{X}(\bm{s})}$, we have that $H_S$ exceeds $H_M$. 
\end{enumerate}
Thus, the difference between $H_S$ and $H_M$ is not consistent for finite data and may impact the transfer entropy differently depending on count sparsity. This is a further reason to use  the reduced measure, as it is adapted specifically to the finite-size case as it does not utilize Stirling's approximation. 


