\begin{section}{Bilinear equations and N-soliton solution for the MCmSP equation}
\label{sec_MCmSP}

In this section, we describe the bilinear form and the hodograph transformation of the MCmSP equation
\begin{eqnarray}
\fl{u^{(i)}_{xt}=u^{(i)}+\left(\sum_{1\leq j < k \leq n} c_{jk}u^{(j)}u^{(k)}u^{(i)}_{x}\right)_{x}-\left(\sum_ {1 \leq j < k \leq n} c_{jk}u^{(j)}_{x}u^{(k)}_{x}\right)u^{(i)},} \nonumber\\
\hspace{90mm} i=1,2,\cdots n,
\end{eqnarray}
and construct its N-soliton solution.
First, by rewriting the MCmSP equation into the conservation
law form
\begin{eqnarray}
\left(\frac{1}{\rho}\right)_{t}-\left(\frac{F}{\rho}\right)_{x}=0,\label{m-conservationlaw}
\end{eqnarray}
\begin{eqnarray}
\rho=\left(1+\sum_{1\leq j < k\leq n}c_{jk}u^{(j)}_{x}u^{(k)}_{x}\right)^{-1},\qquad F=\sum_{1\leq j < k\leq n}c_{jk}u^{(j)}u^{(k)},\label{m-conservationlaw2}
\end{eqnarray}
the hodograph transformation
\begin{eqnarray}
dX=\frac{1}{\rho}dx+\frac{F}{\rho}dt,\qquad dT=dt,\label{m-hodograph}
\end{eqnarray}
is determined. From the  hodograph transformation (\ref{m-hodograph}), we obtain the derivative law
\begin{eqnarray}
\frac{\partial }{\partial X}=\rho \frac{\partial }{\partial x},\qquad\frac{\partial }{\partial T}=\frac{\partial }{\partial t}-F\frac{\partial }{\partial x}.\label{m-derivativelaw}
\end{eqnarray}
Next, transforming the MCmSP equation into
\begin{eqnarray}
\fl{\partial_{x}\left(\partial_{t}-\sum_{1\leq j < k \leq n}c_{jk}u^{(j)}u^{(k)}\partial_{x}\right)u^{(i)}=u^{(i)}\left(2-\left(1+\sum_{1 \leq j < k \leq n}c_{jk}u^{(j)}_{x}u^{(k)}_{x}\right)\right),}\nonumber\\
\label{7}
\end{eqnarray}
and applying the derivative law (\ref{m-derivativelaw}) and (\ref{m-conservationlaw2}) to (\ref{7}), we obtain
\begin{eqnarray}
u^{(i)}_{XT}=u^{(i)}\left(2\rho-1\right).
\end{eqnarray}
Furthermore, applying the derivative law (\ref{m-derivativelaw}) to the conservation law (\ref{m-conservationlaw}), we then have
\begin{eqnarray}
 \rho_{T}+\left(\displaystyle\sum_{1\leq j < k\leq n}c_{jk}u^{(j)}u^{(k)}\right)_{X}=0.\label{m-conservationlaw3}
 \end{eqnarray}
The equation (\ref{m-conservationlaw3}) is the conservation law for $X$ and $T$, where $\rho$ is the conservation density and $\sum_{1\leq j < k\leq n}c_{jk}u^{(j)}u^{(k)}$ is the flux.

Therefore,  the MCmSP equation (\ref{MCmSP}) is transformed into the multi-component coupled integrable dispersionless  (MCCID) equations
\begin{eqnarray}
\left\{
\begin{array}{ll}
u^{(i)}_{XT}=u^{(i)}\left(2\rho-1\right),\\
 \rho_{T}+\left(\displaystyle\sum_{1\leq j < k\leq n}c_{jk}u^{(j)}u^{(k)}\right)_{X}=0,
\end{array}
\right.
\label{m-dispersionless}
\end{eqnarray}
by the hodograph transformation (\ref{m-hodograph}).

Introducing the dependent variable transformation
\begin{eqnarray}
u^{(i)}=\frac{g^{(i)}}{f}\quad(i=1,2,\cdots n),\qquad\rho=1-({\rm log}f)_{XT},\label{m-dependenttransformation}
\end{eqnarray}
the MCCID equations (\ref{m-dispersionless}) lead to
\begin{eqnarray}
\left\{
\begin{array}{ll}
D_{X}D_{T}f\cdot g^{(i)}=fg^{(i)},\\
 D_{T}^{2}f\cdot f=2\displaystyle\sum_{1\leq j < k\leq n}c_{jk}g^{(j)}g^{(k)},
\end{array}
\right.
\label{MCmSPbilinear}
\end{eqnarray}
where $D_{X}$ and $D_{T}$ are the Hirota's D-operators which are defined as
\begin{eqnarray}
\fl{D_{X}^{m}D_{T}^{n}f(X,T)\cdot g(X,T)=\left(\frac{\partial}{\partial X}-\frac{\partial}{\partial X^{\prime}}\right)^{m} \left(\frac{\partial}{\partial T}-\frac{\partial}{\partial T^{\prime}}\right)^{n} f(X,T) g(X^{\prime},T^{\prime})|_{X=X^{\prime},T=T^{\prime}}.}\nonumber
 \end{eqnarray}


%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
% Def Pfaffian
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%

\begin{Def}
Let $A$ be a $2N \times 2N$ antisymmetric matrix defined by
\begin{eqnarray}
A=(a_{i,j})_{1\leq i,j \leq 2N},\nonumber
\end{eqnarray}
where $a_{i,j}=-a_{j,i}$ for $i,j=1,2,\cdots 2N$. The Pfaffian of $A$ is defined by
\begin{eqnarray}
{\rm Pf}(A)&=&{\rm Pf}(a_{i,j})_{1\leq i,j \leq 2N}={\rm Pf}(1,2,\dots 2N)\nonumber\\
&=&\sum_{i_{1}<i_{2}<\cdots< i_{N} \atop i_{1}<j_{1}<i_{2}<j_{2}<\cdots<i_{N}<j_{N}}{\rm sgn}  (\pi) a_{i_{1}, j_{1}}a_{i_{2}, j_{2}}\cdots a_{i_{N}, j_{N}},\nonumber
\end{eqnarray}
where
$\pi=\left(
    \begin{array}{ccccc}
    1 & 2 & \cdots & 2N-1 &2N \\
    i_{1} & j_{1} & \cdots & i_{N} & j_{N}  \\
       \end{array}
    \right)
$
is a permutation of $\{1,2,\cdots ,2N-1,2N\}$.

The Pfaffian is defined by the following expansion rule
\begin{eqnarray}
\fl{{\rm Pf}(1, 2, \cdots , 2N) =\sum_{i=2}^{2N}(-1)^{i}{\rm Pf}(1,i){\rm Pf}(2,3,\cdots, i-1, i+1, \cdots, 2N-1, 2N).}\nonumber
\end{eqnarray}
For an antisymmetric matrix $A$, we have $[{\rm Pf}(A)]^2={\rm det}(A)$.
\end{Def}



%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
% Lemma 2.1
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%

\begin{lem}
The bilinear equations (\ref{MCmSPbilinear}) have the following Pfaffian solution:
\begin{eqnarray}
\fl{f={\rm Pf}(a_{1},\cdots,a_{2N},b_{1},\cdots,b_{2N}), \qquad g^{(i)}={\rm Pf}(d_{0},B_{i},a_{1},\cdots,a_{2N},b_{1},\cdots,b_{2N}),}
\label{MCmSP_f}
\end{eqnarray}
where $i=1,2,\cdots,n$ and the elements of the Pfaffians are defined as
\begin{eqnarray}
{\rm Pf}(a_{j},a_{k})=\frac{p_{j}-p_{k}}{p_{j}+p_{k}}e^{\xi_{j}+\xi_{k}},\qquad {\rm Pf}(a_{j},b_{k})=\delta_{j,k},
\label{pf1}
\end{eqnarray}
\begin{eqnarray}
{\rm Pf}(b_{j},b_{k})=\frac{c_{\mu\nu}}{p_{j}^{-2}-p_{k}^{-2}}\quad(b_{j}\in B_{\mu},b_{k}\in B_{\nu} ),
\end{eqnarray}
\begin{eqnarray}
{\rm Pf}(d_{l},a_{k})=p_{k}^{l}e^{\xi_{k}},\qquad
{\rm Pf}(b_{j},B_{\mu})=
\left\{
\begin{array}{ll}
1 & (b_{j}\in B_{\mu}) \\
0 & (b_{j}\notin B_{\mu})
\end{array}
\right..
\label{pf2}
\end{eqnarray}
Here, $j,k =1,2,\cdots 2N$,\quad$\mu,\nu=1,2,\cdots n,\quad\xi_{j}=p_{j}X+p_{j}^{-1}T+\xi_{i0}$ and $l$ is an integer. A class of set $B_{\mu}(\mu=1,2,\cdots,n) $ satisfies the following conditions
\begin{eqnarray}
B_{\mu}\cap B_{\nu}=\varnothing\,\,{\rm if}\,\, \mu\neq\nu,\qquad\cup_{\mu=1}^{n}B_{\mu}=\{b_{1},b_{2},\cdots,b_{2N}\}.
\end{eqnarray}
The elements of the Pfaffians not defined above are defined as zero.
\end{lem}

%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
% Lemma 2.1  Proof
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
\begin{proof}
At first, we prove that the solutions (\ref{MCmSP_f}) satisfy the first equation of the bilinear equation (\ref{MCmSPbilinear}).
As
\begin{eqnarray}
\frac{\partial}{\partial X}{\rm Pf}(a_{j},a_{k})=(p_{j}-p_{k})e^{\xi_{j}+\xi_{k}}={\rm Pf}(d_{0},d_{1},a_{j},a_{k}),\nonumber\\
\frac{\partial}{\partial T}{\rm Pf}(a_{j},a_{k})=(p_{k}^{-1}-p_{j}^{-1})e^{\xi_{j}+\xi_{k}}={\rm Pf}(d_{-1},d_{0},a_{j},a_{k}),\nonumber\\
\frac{\partial^{2}}{\partial T^{2}}{\rm Pf}(a_{j},a_{k})=(p_{k}^{-2}-p_{j}^{-2})e^{\xi_{j}+\xi_{k}}={\rm Pf}(d_{-2},d_{0},a_{j},a_{k}),\nonumber\\
\frac{\partial^{2}}{\partial X \partial T}{\rm Pf}(a_{j},a_{k})=(p_{j}p_{k}^{-1}-p_{k}p_{j}^{-1})e^{\xi_{j}+\xi_{k}}={\rm Pf}(d_{-1},d_{1},a_{j},a_{k}),\nonumber
\end{eqnarray}

we have
\begin{eqnarray}
\frac{\partial f}{\partial X}={\rm Pf}(d_{0},d_{1},\cdots),\qquad
\frac{\partial f}{\partial T}={\rm Pf}(d_{-1},d_{0},\cdots),\nonumber\\
\frac{\partial^{2} f}{\partial T^{2}}={\rm Pf}(d_{-2},d_{0},\cdots),\qquad
\frac{\partial^{2} f}{\partial X\partial T}={\rm Pf}(d_{-1},d_{1},\cdots).\nonumber
\end{eqnarray}
Here, ${\rm Pf}(d_{i},d_{j},a_{1},\cdots a_{2N},b_{1},\cdots b_{2N})$ is denoted as ${\rm Pf}(d_{i},d_{j},\cdots )$.


Furthermore,
\begin{eqnarray}
\fl{\frac{\partial g^{(i)}}{\partial X}=\frac{\partial}{\partial X}\left[\sum_{j=1}^{2N}(-1)^{j}{\rm Pf}(d_{0},a_{j}){\rm Pf}(B_{i},\cdots,\hat{a}_{j},\cdots)\right]}\nonumber\\
\fl{=\sum_{j=1}^{2N}(-1)^{j}\left[(\partial_{X}{\rm Pf}(d_{0},a_{j})){\rm Pf}(B_{i},\cdots,\hat{a}_{j},\cdots)+{\rm Pf}(d_{0},a_{j})\partial_{X}{\rm Pf}(B_{i},\cdots,\hat{a}_{j},\cdots)\right]}\nonumber\\
\fl{=\sum_{j=1}^{2N}(-1)^{j}\left[{\rm Pf}(d_{1},a_{j}){\rm Pf}(B_{i},\cdots,\hat{a}_{j},\cdots)+{\rm Pf}(d_{0},a_{j}){\rm Pf}(d_{0},d_{1},B_{i},\cdots,\hat{a}_{j},\cdots)\right]}\nonumber\\
\fl{={\rm Pf}(d_{1},B_{i},\cdots)+{\rm Pf}(d_{0},d_{0},d_{1},B_{i}\cdots)}\nonumber\\
\fl{={\rm Pf}(d_{1},B_{i},\cdots).}\nonumber
\end{eqnarray}
Similarly, we have
\begin{eqnarray}
\fl{\frac{\partial g^{(i)}}{\partial T}=\frac{\partial}{\partial T}\left[\sum_{j=1}^{2N}(-1)^{j}{\rm Pf}(d_{0},a_{j}){\rm Pf}(B_{i},\cdots,\hat{a}_{j},\cdots)\right]}\nonumber\\
\fl{=\sum_{j=1}^{2N}(-1)^{j}\left[(\partial_{T}{\rm Pf}(d_{0},a_{j})){\rm Pf}(B_{i},\cdots,\hat{a}_{j},\cdots)+{\rm Pf}(d_{0},a_{j})\partial_{T}{\rm Pf}(B_{i},\cdots,\hat{a}_{j},\cdots)\right]}\nonumber\\
\fl{=\sum_{j=1}^{2N}(-1)^{j}\left[{\rm Pf}(d_{-1},a_{j}){\rm Pf}(B_{i},\cdots,\hat{a}_{j},\cdots)+{\rm Pf}(d_{0},a_{j}){\rm Pf}(d_{-1},d_{0},B_{i},\cdots,\hat{a}_{j},\cdots)\right]}\nonumber\\
\fl{={\rm Pf}(d_{-1},B_{i},\cdots)+{\rm Pf}(d_{0},d_{-1},d_{0},B_{i},\cdots)}\nonumber\\
\fl{={\rm Pf}(d_{-1},B_{i},\cdots)}\nonumber,\\
\fl{\frac{\partial^{2}g^{(i)}}{\partial X\partial T}=\frac{\partial}{\partial X}\left[\sum_{j=1}^{2N}(-1)^{j}{\rm Pf}(d_{-1},a_{j}){\rm Pf}(B_{i},\cdots,\hat{a}_{j},\cdots)\right]}\nonumber\\
\fl{=\sum_{j=1}^{2N}(-1)^{j}\left[(\partial_{X}{\rm Pf}(d_{-1},a_{j})){\rm Pf}(B_{i},\cdots,\hat{a}_{j},\cdots)+{\rm Pf}(d_{-1},a_{j})\partial_{X}{\rm Pf}(B_{i},\cdots,\hat{a}_{j},\cdots)\right]}\nonumber\\
\fl{=\sum_{j=1}^{2N}(-1)^{j}\left[{\rm Pf}(d_{0},a_{j}){\rm Pf}(B_{i},\cdots,\hat{a}_{j},\cdots)+{\rm Pf}(d_{-1},a_{j}){\rm Pf}(d_{0},d_{1},B_{i},\cdots,\hat{a}_{j},\cdots)\right]}\nonumber\\
\fl{={\rm Pf}(d_{0},B_{i},\cdots)+{\rm Pf}(d_{-1},d_{0},d_{1},B_{i},\cdots)}\nonumber\\
\fl{={\rm Pf}(d_{0},B_{i},\cdots)+{\rm Pf}(d_{-1},B_{i},d_{0},d_{1}\cdots).}\nonumber
\end{eqnarray}

An algebraic identity of Pfaffian\cite{Hirotabook}
\begin{eqnarray}
\fl{{\rm Pf}(d_{-1},B_{i},d_{0},d_{1},\cdots){\rm Pf}(\cdots)={\rm Pf}(d_{-1},d_{0},\cdots){\rm Pf}(d_{1},B_{i},\cdots)}\nonumber\\
-{\rm Pf}(d_{-1},d_{1},\cdots){\rm Pf}(d_{0},B_{i},\cdots)+{\rm Pf}(d_{-1},B_{i},\cdots){\rm Pf}(d_{0},d_{1},\cdots)\nonumber
\end{eqnarray}
leads to
\begin{eqnarray}
(\partial_{X}\partial_{T} g^{(i)}-g^{(i)})\times f=\partial_{T} f \times \partial_{X} g^{(i)}-\partial_{X}\partial_{T} f \times g^{(i)}+\partial_{T} g^{(i)} \times \partial_{X} f ,\nonumber
\end{eqnarray}
which is the first equation of the bilinear equations (\ref{MCmSPbilinear}).

Next, we prove that the solutions (\ref{MCmSP_f}) satisfy the second equation of the bilinear equation (\ref{MCmSPbilinear}).
The right-hand side of the second equation of the bilinear equation (\ref{MCmSPbilinear}) leads to
\begin{eqnarray}
\fl{2\sum_{1\leq \mu < \nu \leq n}c_{\mu \nu}g^{(\mu)}g^{(\nu)}=\sum_{1\leq \mu , \nu \leq n}c_{\mu \nu}{\rm Pf}(d_{0},B_{\mu},\cdots){\rm Pf}(d_{0},B_{\nu},\cdots)}\nonumber\\
\fl{=\sum_{1\leq \mu , \nu \leq n}c_{\mu \nu}\sum_{j,k}^{2N}(-1)^{j+k}{\rm Pf}(B_{\mu},b_{j}){\rm Pf}(d_{0},\cdots,\hat{b}_{j},\cdots){\rm Pf}(B_{\nu},b_{k}){\rm Pf}(d_{0},\cdots,\hat{b}_{k},\cdots)}\nonumber\\
\fl{=\sum_{j,k}^{2N}(-1)^{j+k}\sum_{1\leq \mu , \nu \leq n}c_{\mu \nu}{\rm Pf}(B_{\mu},b_{j}){\rm Pf}(B_{\nu},b_{k}){\rm Pf}(d_{0},\cdots,\hat{b}_{j},\cdots){\rm Pf}(d_{0},\cdots,\hat{b}_{k},\cdots)}\nonumber\\
\fl{=\sum_{j,k}^{2N}(-1)^{j+k}(p_{j}^{-2}-p_{k}^{-2}){\rm Pf}(b_{j},b_{k}){\rm Pf}(d_{0},\cdots,\hat{b}_{j},\cdots){\rm Pf}(d_{0},\cdots,\hat{b}_{k},\cdots).}\label{1.3.18}
\end{eqnarray}
Now, expanding ${\rm Pf}(b_{j},d_{0},\cdots)$ which is trivially zero ${\rm Pfaffian}$, we obtain

\begin{eqnarray}
\label{1.3.24}
\sum_{k=1}^{2N}(-1)^{j+k}{\rm Pf}(b_{j},b_{k}){\rm Pf}(d_{0},\cdots,\hat{b}_{k},\cdots)={\rm Pf}(d_{0},\cdots,\hat{a}_{j},\cdots),\nonumber
\end{eqnarray}
which leads to
\begin{eqnarray}
&&\sum_{j,k}^{2N}(-1)^{j+k}p_{j}^{-2}{\rm Pf}(b_{j},b_{k}){\rm Pf}(d_{0},\cdots,\hat{b}_{j},\cdots){\rm Pf}(d_{0},\cdots,\hat{b}_{k},\cdots)\nonumber\\
&=&\sum_{j}^{2N}p_{j}^{-2}{\rm Pf}(d_{0},\cdots,\hat{a}_{j},\cdots){\rm Pf}(d_{0},\cdots,\hat{b}_{j},\cdots).\label{1.3.25}
\end{eqnarray}
Similarly, we have
\begin{eqnarray}
&&-\sum_{j,k}^{2N}(-1)^{j+k}p_{k}^{-2}{\rm Pf}(b_{j},b_{k}){\rm Pf}(d_{0},\cdots,\hat{b}_{j},\cdots){\rm Pf}(d_{0},\cdots,\hat{b}_{k},\cdots)\nonumber\\
&=&\sum_{k}^{2N}p_{k}^{-2}{\rm Pf}(d_{0},\cdots,\hat{a}_{k},\cdots){\rm Pf}(d_{0},\cdots,\hat{b}_{k},\cdots).\label{1.3.26}
\end{eqnarray}
Substituting (\ref{1.3.25}) and (\ref{1.3.26}) into (\ref{1.3.18}), we then have
\begin{eqnarray}
\label{1.3.27}
\sum_{1\leq \mu < \nu \leq n}c_{\mu \nu}g^{(\mu)}g^{(\nu)}=\sum_{j}^{2N}p_{j}^{-2}{\rm Pf}(d_{0},\cdots,\hat{a}_{j},\cdots){\rm Pf}(d_{0},\cdots,\hat{b}_{j},\cdots).
\end{eqnarray}

Next, the following equation gives
\begin{eqnarray}
\fl{\frac{\partial^{2}f}{\partial T^{2}}\times 0-\frac{\partial f}{\partial T}\frac{\partial f}{\partial T}={\rm Pf}(d_{-2},d_{0},\cdots){\rm Pf}(d_{0},d_{0},\cdots)-{\rm Pf}(d_{-1},d_{0},\cdots){\rm Pf}(d_{-1},d_{0},\cdots)}\nonumber\\
\fl{=\sum_{j=1}^{2N}(-1)^{j}{\rm Pf}(d_{-2},a_{j}){\rm Pf}(d_{0},\cdots,\hat{a}_{j},\cdots)\sum_{k=1}^{2N}(-1)^{k}{\rm Pf}(d_{0},a_{k}){\rm Pf}(d_{0},\cdots,\hat{a}_{k},\cdots)}\nonumber\\
\fl{\qquad-\sum_{j=1}^{2N}(-1)^{j}{\rm Pf}(d_{-1},a_{j}){\rm Pf}(d_{0},\cdots,\hat{a}_{j},\cdots)\sum_{k=1}^{2N}(-1)^{k}{\rm Pf}(d_{-1},a_{k}){\rm Pf}(d_{0},\cdots,\hat{a}_{k},\cdots)}\nonumber\\
\fl{=\sum_{j,k=1}^{2N}(-1)^{j+k}[{\rm Pf}(d_{-2},a_{j}){\rm Pf}(d_{0},a_{k})-{\rm Pf}(d_{-1},a_{j}){\rm Pf}(d_{-1},a_{k})]}\nonumber\\
\fl{\qquad\times{\rm Pf}(d_{0},\cdots,\hat{a}_{j},\cdots){\rm Pf}(d_{0},\cdots,\hat{a}_{k},\cdots)}\nonumber\\
\fl{=\sum_{j,k=1}^{2N}(-1)^{j+k+1}(p_{j}^{-2}+p_{j}^{-1}p_{k}^{-1}){\rm Pf}(a_{j},a_{k}){\rm Pf}(d_{0},\cdots,\hat{a}_{j},\cdots){\rm Pf}(d_{0},\cdots,\hat{a}_{k},\cdots)}.
\label{A55}
\end{eqnarray}
Since
\begin{eqnarray}
\fl{\quad\sum_{j,k=1}^{2N}(-1)^{j+k+1}p_{j}^{-1}p_{k}^{-1}{\rm Pf}(a_{j},a_{k}){\rm Pf}(d_{0},\cdots,\hat{a}_{j},\cdots){\rm Pf}(d_{0},\cdots,\hat{a}_{k},\cdots)}\nonumber\\
\fl{=\sum_{k,j=1}^{2N}(-1)^{k+j+1}p_{k}^{-1}p_{j}^{-1}{\rm Pf}(a_{k},a_{j}){\rm Pf}(d_{0},\cdots,\hat{a}_{k},\cdots){\rm Pf}(d_{0},\cdots,\hat{a}_{j},\cdots)}\nonumber\\
\fl{=-\sum_{j,k=1}^{2N}(-1)^{j+k+1}p_{j}^{-1}p_{k}^{-1}{\rm Pf}(a_{j},a_{k}){\rm Pf}(d_{0},\cdots,\hat{a}_{j},\cdots){\rm Pf}(d_{0},\cdots,\hat{a}_{k},\cdots),}
\end{eqnarray}
we obtain
\begin{eqnarray}
\fl{\sum_{j,k=1}^{2N}(-1)^{j+k+1}p_{j}^{-1}p_{k}^{-1}{\rm Pf}(a_{j},a_{k}){\rm Pf}(d_{0},\cdots,\hat{a}_{j},\cdots){\rm Pf}(d_{0},\cdots,\hat{a}_{k},\cdots)=0.}
\label{A66}
\end{eqnarray}
Substituting (\ref{A66}) into (\ref{A55}), it follows
\begin{eqnarray}
\fl{-\frac{\partial f}{\partial T}\frac{\partial f}{\partial T}=\sum_{j,k=1}^{2N}(-1)^{j+k+1}p_{j}^{-2}{\rm Pf}(a_{j},a_{k}){\rm Pf}(d_{0},\cdots,\hat{a}_{j},\cdots){\rm Pf}(d_{0},\cdots,\hat{a}_{k},\cdots)}\nonumber\\
\fl{=\sum_{j=1}^{2N}(-1)^{j+1}p_{j}^{-2}{\rm Pf}(d_{0},\cdots,\hat{a}_{j},\cdots)\left[\sum_{k=1}^{2N}(-1)^{k}{\rm Pf}(a_{j},a_{k}){\rm Pf}(d_{0},\cdots,\hat{a}_{k},\cdots)\right].}\label{A77}
\end{eqnarray}
Now, expanding ${\rm Pf}(a_{j},d_{0},\cdots)$ which is trivially zero ${\rm Pfaffian}$, we obtain
\begin{eqnarray}
\fl{\sum_{k=1}^{2N}(-1)^{k}{\rm Pf}(a_{j},a_{k}){\rm Pf}(d_{0},\cdots,\hat{a}_{k},\cdots)={\rm Pf}(d_{0},a_{j}){\rm Pf}(\cdots)+(-1)^{j+1}{\rm Pf}(d_{0},\cdots,\hat{b}_{j},\cdots).}\nonumber\\
\label{A88}
\end{eqnarray}
Substituting (\ref{A88}) into (\ref{A77}), we have
\begin{eqnarray}
\fl{-\frac{\partial f}{\partial T}\frac{\partial f}{\partial T}=\sum_{j=1}^{2N}(-1)^{j+1}p_{j}^{-2}{\rm Pf}(d_{0},\cdots,\hat{a}_{j},\cdots)\left[{\rm Pf}(d_{0},a_{j}){\rm Pf(\cdots)}+(-1)^{j+1}{\rm Pf}(d_{0},\cdots,\hat{b}_{j},\cdots)\right]}\nonumber\\
\fl{=\sum_{j=1}^{2N}(-1)^{j+1}p_{j}^{-2}{\rm Pf}(d_{0},a_{j}){\rm Pf}(d_{0},\cdots,\hat{a}_{j},\cdots){\rm Pf(\cdots)}}\nonumber\\
\fl{\qquad+\sum_{j=1}^{2N}p_{j}^{-2}{\rm Pf}(d_{0},\cdots,\hat{a}_{j},\cdots){\rm Pf}(d_{0},\cdots,\hat{b}_{j},\cdots)}\nonumber\\
\fl{=-\sum_{j=1}^{2N}(-1)^{j}p_{j}^{-2}{\rm Pf}(d_{0},a_{j}){\rm Pf}(d_{0},\cdots,\hat{a}_{j},\cdots){\rm Pf(\cdots)}}\nonumber\\
\fl{\qquad+\sum_{j=1}^{2N}p_{j}^{-2}{\rm Pf}(d_{0},\cdots,\hat{a}_{j},\cdots){\rm Pf}(d_{0},\cdots,\hat{b}_{j},\cdots)}\nonumber\\
\fl{=-\sum_{j=1}^{2N}(-1)^{j}{\rm Pf}(d_{-2},a_{j}){\rm Pf}(d_{0},\cdots,\hat{a}_{j},\cdots){\rm Pf(\cdots)}}\nonumber\\
\fl{\qquad+\sum_{j=1}^{2N}p_{j}^{-2}{\rm Pf}(d_{0},\cdots,\hat{a}_{j},\cdots){\rm Pf}(d_{0},\cdots,\hat{b}_{j},\cdots)}\nonumber\\
\fl{=-{\rm Pf}(d_{-2},d_{0},\cdots){\rm Pf}(\cdots)+\sum_{j=1}^{2N}p_{j}^{-2}{\rm Pf}(d_{0},\cdots,\hat{a}_{j},\cdots){\rm Pf}(d_{0},\cdots,\hat{b}_{j},\cdots)}\nonumber\\
\fl{=-\frac{\partial^{2} f}{\partial T^{2}}f+\displaystyle\sum_{1\leq \mu < \nu\leq n}c_{\mu\nu}g^{(\mu)}g^{(\nu)}}.\nonumber
\end{eqnarray}
The last calculation used (\ref{1.3.27}).
Therefore, we arrive at
\begin{eqnarray}
\frac{\partial^{2}f}{\partial T^{2}}f-\frac{\partial f}{\partial T}\frac{\partial f}{\partial T}=\sum_{1\leq \mu < \nu\leq n}c_{\mu\nu}g^{(\mu)}g^{(\nu)},\nonumber
\end{eqnarray}
which is the second equation of the bilinear equations (\ref{MCmSPbilinear}).
\end{proof}
\end{section}

