\begin{section}{A self-adaptive moving mesh scheme for the MCmSP equation}
\label{sec_disMCmSP}
A semi-discrete analogue of bilinear equations (\ref{MCmSPbilinear}) is
\begin{eqnarray}
\left\{
\begin{array}{ll}
  \displaystyle\frac{1}{a}D_{T}(g_{l+1}^{(i)}\cdot f_{l}-g_{l}^{(i)}\cdot f_{l+1})=g_{l+1}^{(i)}f_{l}+g_{l}^{(i)}f_{l+1},\qquad i=1,2,\cdots,n,\\
  D_{T}^{2}f_{l}\cdot f_{l}=2\displaystyle\sum_{1\leq j < k \leq n}c_{jk}g_{l}^{(j)}g_{l}^{(k)},
\end{array}
\right.
\label{disbilinear}
\end{eqnarray}
where $2a$ is the parameter related to a discrete interval.
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
% Lemma 3.1
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%

\begin{lem}
The bilinear equations (\ref{disbilinear}) have the following Pfaffian solution:
\begin{eqnarray}
\fl{f_{l}={\rm Pf}(a_{1},\cdots,a_{2N},b_{1},\cdots,b_{2N})_{l},\qquad g_{l}^{(i)}={\rm Pf}(d_{0},B_{i},a_{1},\cdots,a_{2N},b_{1},\cdots,b_{2N})_{l},}
\label{dis_f_MCmSP}
\end{eqnarray}
where $i=1,2,\cdots ,n$ and the elements of the Pfaffians are defined as
\begin{eqnarray}
{\rm Pf}(a_{j},a_{k})_{l}=\frac{p_{j}-p_{k}}{p_{j}+p_{k}}\phi_{j}^{(0)}(l)\phi_{k}^{(0)}(l),\qquad{\rm Pf}(a_{j},b_{k})_{l}=\delta_{j,k},
\label{dmpf1}
\end{eqnarray}
\begin{eqnarray}
{\rm Pf}(b_{j},b_{k})_{l}=\frac{c_{\mu\nu}}{p_{j}^{-2}-p_{k}^{-2}}\quad(b_{j}\in B_{\mu},b_{k}\in B_{\nu} ),
\end{eqnarray}
\begin{eqnarray}
{\rm Pf}(d_{m},a_{j})_{l}=\phi_{j}^{(m)}(l),\qquad{\rm Pf}(d^{l},a_{j})_{l}=\phi_{j}^{(0)}(l+1),\\
{\rm Pf}(b_{k},B_{\mu})_{l}=
\left\{
\begin{array}{ll}
 1 & (b_{k}\in B_{\mu}),\\
 0 & (b_{k}\notin B_{\mu}),
\end{array}
\right.\\
{\rm Pf}(d_{0},d^{l})_{l}=1,\qquad{\rm Pf}(d_{-1},d^{l})_{l}=-a,
\label{dmpf2}
\end{eqnarray}
where
\begin{eqnarray}
\phi_{j}^{(n)}(l)=p_{j}^{n}\left(\frac{1+ap_{j}}{1-ap_{j}}\right)^{l}e^{p_{j}^{-1}T+\xi_{i0}},
\end{eqnarray}
and it satisfies the following equation
\begin{eqnarray}
\frac{\phi_{j}^{(n)}(l+1)-\phi_{j}^{(n)}(l)}{a}=\phi_{j}^{(n+1)}(l+1)+\phi_{j}^{(n+1)}(l).
\end{eqnarray}
\end{lem}
The elements of the Pfaffians not defined above are defined as zero.

%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
% Lemma 3.1 Proof.
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
\begin{proof}
First, we show the solutions (\ref{dis_f_MCmSP}) satisfy the first equation of the bilinear equations (\ref{disbilinear}). Since
\begin{eqnarray}
\fl{\frac{\partial}{\partial T}{\rm Pf}(a_{j},a_{k})_{l}=\phi_{j}^{(0)}(l)\phi_{k}^{(-1)}(l)-\phi_{j}^{(-1)}(l)\phi_{k}^{(0)}(l)={\rm Pf}(d_{0},a_{j})_{l}{\rm Pf}(d_{-1},a_{k})_{l}-{\rm Pf}(d_{-1},a_{j})_{l}{\rm Pf}(d_{0},a_{k})_{l}}\nonumber\\
\fl{={\rm Pf}(d_{-1},d_{0})_{l}{\rm Pf}(a_{j},a_{k})_{l}-{\rm Pf}(d_{-1},a_{j})_{l}{\rm Pf}(d_{0},a_{k})_{l}+{\rm Pf}(d_{-1},a_{k})_{l}{\rm Pf}(d_{0},a_{j})_{l}}\nonumber\\
\fl{={\rm Pf}(d_{-1},d_{0},a_{j},a_{k})_{l},}\nonumber\\
\fl{{\rm Pf}(a_{j},a_{k})_{l+1}={\rm Pf}(a_{j},a_{k})_{l}+\phi_{j}^{(0)}(l+1)\phi_{k}^{(0)}(l)-\phi_{j}^{(0)}(l)\phi_{k}^{(0)}(l+1)}\nonumber\\
\fl{={\rm Pf}(d_{0},d^{l})_{l}{\rm Pf}(a_{j},a_{k})_{l}-{\rm Pf}(d_{0},a_{j})_{l}{\rm Pf}(d^{l},a_{k})_{l}+{\rm Pf}(d_{0},a_{k})_{l}{\rm Pf}(d^{l},a_{j})_{l}}\nonumber\\
\fl{={\rm Pf}(d_{0},d^{l},a_{j},a_{k})_{l},}\nonumber\\
\fl{(\partial_{T}-a){\rm Pf}(a_{j},a_{k})_{l+1}=\partial_{T}{\rm Pf}(a_{j},a_{k})_{l+1}-a{\rm Pf}(a_{j},a_{k})_{l+1}}\nonumber\\
\fl{=\phi_{j}^{(0)}(l+1)\phi_{k}^{(-1)}(l+1)-\phi_{j}^{(-1)}(l+1)\phi_{k}^{(0)}(l+1)}\nonumber\\
\fl{\qquad-a\left({\rm Pf}(a_{j},a_{k})_{l}+\phi_{j}^{(0)}(l+1)\phi_{k}^{(0)}(l)-\phi_{j}^{(0)}(l)\phi_{k}^{(0)}(l+1)\right)}\nonumber\\
\fl{=-a{\rm Pf}(a_{j},a_{k})_{l}+\phi_{j}^{(0)}(l+1)\left(\phi_{k}^{(-1)}(l+1)-a\phi_{k}^{(0)}(l)\right)-\phi_{k}^{(0)}(l+1)\left(\phi_{j}^{(-1)}(l+1)-a\phi_{j}^{(0)}(l)\right)}\nonumber\\
\fl{=-a{\rm Pf}(a_{j},a_{k})_{l}+\phi_{j}^{(0)}(l+1)\left(a\phi_{k}^{(0)}(l+1)+\phi_{k}^{(-1)}(l)\right)-\phi_{k}^{(0)}(l+1)\left(a\phi_{j}^{(0)}(l+1)+\phi_{j}^{(-1)}(l)\right)}\nonumber\\
\fl{=-a{\rm Pf}(a_{j},a_{k})_{l}+\phi_{j}^{(0)}(l+1)\phi_{k}^{(-1)}(l)-\phi_{j}^{(-1)}(l)\phi_{k}^{(0)}(l+1)}\nonumber\\
\fl{={\rm Pf}(d_{-1},d^{l})_{l}{\rm Pf}(a_{j},a_{k})_{l}-{\rm Pf}(d_{-1},a_{j})_{l}{\rm Pf}(d^{l},a_{k})_{l}+{\rm Pf}(d_{-1},a_{k})_{l}{\rm Pf}(d^{l},a_{j})_{l}}\nonumber\\
\fl{={\rm Pf}(d_{-1},d^{l},a_{j},a_{k})_{l},}\nonumber
\end{eqnarray}
we obtain
\begin{eqnarray}
\partial_{T}f_{l}={\rm Pf}(d_{-1},d_{0},\cdots)_{l},\quad f_{l+1}={\rm Pf}(d_{0},d^{l},\cdots)_{l},\quad (\partial_{T}-a)f_{l+1}={\rm Pf}(d_{-1},d^{l},\cdots)_{l}.\nonumber
\end{eqnarray}
Furthermore, we have
\begin{eqnarray}
\fl{\partial_{T}g_{l}^{(\mu)}=\partial_{T}\left(\sum_{j=1}^{2N}(-1)^{j}{\rm Pf}(d_{0},a_{j})_{l}{\rm Pf}(B_{\mu},\cdots,\hat{a}_{j},\cdots)_{l}\right)}\nonumber\\
\fl{=\sum_{j=1}^{2N}(-1)^{j}\left((\partial_{T}{\rm Pf}(d_{0},a_{j})_{l}){\rm Pf}(B_{\mu},\cdots,\hat{a}_{j},\cdots)_{l}+{\rm Pf}(d_{0},a_{j})_{l}\partial_{T}{\rm Pf}(B_{\mu},\cdots,\hat{a}_{j},\cdots)_{l}\right)}\nonumber\\
\fl{=\sum_{j=1}^{2N}(-1)^{j}({\rm Pf}(d_{-1},a_{j})_{l}){\rm Pf}(B_{\mu},\cdots,\hat{a}_{j},\cdots)_{l}+{\rm Pf}(d_{0},a_{j})_{l}{\rm Pf}(B_{\mu},d_{-1},d_{0},\cdots,\hat{a}_{j},\cdots)_{l})}\nonumber\\
\fl{={\rm Pf}(d_{-1},B_{\mu},\cdots)_{l}+{\rm Pf}(d_{0},B_{\mu},d_{-1},d_{0},\cdots)_{l}}\nonumber\\
\fl{={\rm Pf}(d_{-1},B_{\mu},\cdots)_{l},}\nonumber\\
\fl{g_{l+1}^{(\mu)}=\sum_{j=1}^{2N}(-1)^{j}{\rm Pf}(d_{0},a_{j})_{l+1}{\rm Pf}(B_{\mu},\cdots,\hat{a}_{j},\cdots)_{l+1}}\nonumber\\
\fl{=\sum_{j=1}^{2N}(-1)^{j}{\rm Pf}(d^{l},a_{j})_{l}{\rm Pf}(B_{\mu},d_{0},d^{l},\cdots,\hat{a}_{j},\cdots)_{l}}\nonumber\\
\fl{={\rm Pf}(d^{l},B_{\mu},\cdots)_{l},}\nonumber
\end{eqnarray}
by expanding Pf$(d^{l},B_{\mu},d_{0},d^{l}\cdots)$ which is trivially zero Pfaffian.
The simple expression of $(\partial_{T}-a)g_{l+1}^{(\mu)}$ is obtained as follows:
\begin{eqnarray}
\fl{(\partial_{T}-a)g_{l+1}^{(\mu)}=\sum_{j=1}^{2N}(-1)^{j}(\partial_{T}-a){\rm Pf}(d^{l},a_{j})_{l}{\rm Pf}(B_{\mu},\cdots,\hat{a}_{j},\cdots)_{l}}\nonumber\\
\fl{\qquad+\sum_{j=1}^{2N}(-1)^{j}{\rm Pf}(d^{l},a_{j})_{l}\partial_{T}{\rm Pf}(B_{\mu},\cdots,\hat{a}_{j},\cdots)_{l}}\nonumber\\
\fl{=\sum_{j=1}^{2N}(-1)^{j}({\rm Pf}(d_{-1},a_{j})_{l}+a{\rm Pf}(d_{0},a_{j})_{l}){\rm Pf}(B_{\mu},\cdots,\hat{a}_{j},\cdots)_{l}}\nonumber\\
\fl{\qquad+\sum_{j=1}^{2N}(-1)^{j}{\rm Pf}(d^{l},a_{j})_{l}{\rm Pf}(d_{-1},d_{0},B_{\mu},\cdots,\hat{a}_{j},\cdots)_{l}}\nonumber\\
\fl{={\rm Pf}(d_{-1},B_{\mu},\cdots)_{l}+a {\rm Pf}(d_{0},B_{\mu},\cdots)_{l}+\sum_{j=1}^{2N}(-1)^{j}{\rm Pf}(d^{l},a_{j})_{l}{\rm Pf}(d_{-1},d_{0},B_{\mu},\cdots,\hat{a}_{j},\cdots)_{l}}\nonumber\\
\fl{={\rm Pf}(d^{l},d_{-1},d_{0},B_{\mu},\cdots)_{l}={\rm Pf}(d_{-1},B_{\mu},d_{0},d^{l},\cdots)_{l}.}\nonumber
\end{eqnarray}


An algebraic identity of {\rm Pfaffian}\cite{Hirotabook}
\begin{eqnarray}
\fl{{\rm Pf}(d_{-1},B_{\mu},d_{0},d^{l},\cdots)_{l}{\rm Pf}(\cdots)_{l}={\rm Pf}(d_{-1},d_{0},\cdots)_{l}{\rm Pf}(d^{l},B_{\mu},\cdots)_{l}}\nonumber\\
-{\rm Pf}(d_{-1},d^{l},\cdots)_{l}{\rm Pf}(d_{0},B_{\mu},\cdots)_{l}+{\rm Pf}(d_{-1},B_{\mu},\cdots)_{l}{\rm Pf}(d_{0},d^{l},\cdots)_{l},\nonumber
\end{eqnarray}
gives
\begin{eqnarray}
(\partial_{T}-a)g_{l+1}^{(\mu)}\times f_{l}=g_{l+1}^{(\mu)}\times \partial_{T}f_{l}-(\partial_{T}-a)f_{l+1}\times g_{l}^{(\mu)}+\partial_{T}g_{l}^{(\mu)}\times f_{l+1},\nonumber
\end{eqnarray}
which is the first equation of the bilinear equations (\ref{disbilinear}). The second equation of the bilinear equations (\ref{disbilinear}) can be proved as in the continuous case.

\end{proof}

%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
% Lemma 3.2
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%

\begin{lem}
A semi-discrete analogue of the MCCID equations (\ref{m-dispersionless})
\begin{eqnarray}
\left\{
\begin{array}{ll}
  \displaystyle\frac{d}{dT}(u_{l+1}^{(i)}-u_{l}^{(i)})=a(2\rho_{l}-1)(u_{l+1}^{(i)}+u_{l}^{(i)}),\\
  \displaystyle\frac{d}{dT}\rho_{l}=-\displaystyle\frac{1}{2a}\sum_{1\leq j < k \leq n}c_{jk}(u_{l+1}^{(j)}u_{l+1}^{(k)}-u_{l}^{(j)}u_{l}^{(k)}),
\end{array}
\right.
\label{m-semidisdispersionless}
\end{eqnarray}
is obtained from the bilinear equations (\ref{disbilinear}) through the dependent variable transformation
\begin{eqnarray}
u_{l}^{(i)}=\frac{g_{l}^{(i)}}{f_{l}},\qquad
\rho_{l}=1-\frac{1}{2a}\left(\log{\frac{f_{l+1}}{f_{l}}}\right)_{T}.
\label{disdependenttransformation}
\end{eqnarray}

\end{lem}


\begin{proof}
At first, dividing both sides of the first equation of the bilinear equations (\ref{disbilinear}) by $f_{l+1}f_{l}$, we have
\begin{eqnarray}
\left(\frac{g_{l+1}^{(i)}}{f_{l+1}}-\frac{g_{l}^{(i)}}{f_{l}}\right)_{T}=\left(a-\left(\log{\frac{f_{l+1}}{f_{l}}}\right)_{T}\right)\left(\frac{g_{l+1}^{(i)}}{f_{l+1}}+\frac{g_{l}^{(i)}}{f_{l}}\right).
\end{eqnarray}
It follows
\begin{eqnarray}
\frac{d}{dT}(u_{l+1}^{(i)}-u_{l}^{(i)})=a(2\rho_{l}-1)(u_{l+1}^{(i)}+u_{l}^{(i)}),
\end{eqnarray}
by the dependent variable transformation (\ref{disdependenttransformation}).


Next, from the dependent variable transformation (\ref{disdependenttransformation}), the second equation of the bilinear equations (\ref{disbilinear}) is rewritten as
\begin{eqnarray}
(\log{f_{l}})_{TT}=\sum_{1\leq j < k\leq n}c_{jk}u_{l}^{(j)}u_{l}^{(k)}.\label{33}
\end{eqnarray}
By (\ref{33}) and the dependent variable transformation (\ref{disdependenttransformation}), we obtain
 \begin{eqnarray}
\frac{d}{dT}\rho_{l}=-\frac{1}{2a}\sum_{1\leq j < k \leq n}c_{jk}(u_{l+1}^{(j)}u_{l+1}^{(k)}-u_{l}^{(j)}u_{l}^{(k)}).
\end{eqnarray}



\end{proof}

%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
% Lemma 3.3
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%

\begin{lem}
A semi-discrete analogue of the MCmSP equation is of the form:
\begin{eqnarray}
\left\{
\begin{array}{ll}
  \displaystyle\frac{d} {dT}(u_{l+1}^{(i)}-u_{l}^{(i)})= (\delta_{l}-a)(u_{l+1}^{(i)}+u_{l}^{(i)}),\\
  \\
 \displaystyle\frac{d\delta_{l}}{dT}=-\displaystyle\sum_{1\leq j < k\leq n}c_{jk}(u_{l+1}^{(j)}u_{l+1}^{(k)}-u_{l}^{(j)}u_{l}^{(k)}),\\
  x_{l}=x_{0}+ \displaystyle\sum_{m=0}^{l-1}\delta_{m},\quad t=T.
\end{array}
\right.
\label{semidisMCmSP}
\end{eqnarray}
Here, $u_{l}^{(i)}$ is the value at $x_{l}$.
\end{lem}

\begin{proof}
From the derivative law (\ref{m-derivativelaw}), we obtain
\begin{eqnarray}
\frac{\partial x}{\partial X}=\rho.\label{6.19}
\end{eqnarray}
Integrating (\ref{6.19}) with respect to $X$, we have the integral form of the hodograph transformation (\ref{m-hodograph})
\begin{eqnarray}
x=\int\rho(X,T)dX=x_{0}+\int_{0}^{X}\rho(\bar{X},T)d\bar{X},
\label{999}
\end{eqnarray}
where $x_{0}$ is a constant of integration determined from the left-hand edge $(x=x_{0})$.
Now, we discretize (\ref{999}), we then have the discrete hodograph transformation
\begin{eqnarray}
x_{l}=x_{0}+\sum_{m=0}^{l-1}2a\rho_{m},
\label{dishodographMCmSP}
\end{eqnarray}
where $ \rho_{l}\equiv\rho(X_{l},T)$.


Introducing a mesh interval
\begin{eqnarray}
\delta_{l}:=x_{l+1}-x_{l},
\end{eqnarray}
we obtain
\begin{eqnarray}
\delta_{l}=2a\rho_{l},\label{meshintMCmSP}
\end{eqnarray}
by substituting the discrete hodograph transformation (\ref{dishodographMCmSP}).
Substituting  (\ref{meshintMCmSP}) into the semi-discrete MCCID equations (\ref{m-semidisdispersionless}), we have a semi-discrete analogue of the MCmSP equation (\ref{semidisMCmSP}).
\end{proof}

%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
%% Remark 3.4
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
\begin{rem}
Equation (\ref{dishodographMCmSP}) is the summation form of the discrete hodograph transformation:
\begin{eqnarray}
\Delta x_{l}=\rho_{l}\Delta X_{l}-\sum_{1\leq j < k\leq n}c_{jk}u_{l}^{(j)}u_{l}^{(k)}dT,\quad dt=dT.
\label{ddishodographMCmSP}
\end{eqnarray}
Equation (\ref{ddishodographMCmSP}) is obtained from the second equation of  (\ref{m-semidisdispersionless}) which is the discrete version of the conservation law (\ref{m-conservationlaw3}).
From the  discrete hodograph transformation (\ref{ddishodographMCmSP}), we have
\begin{eqnarray}
\frac{\Delta x_{l}}{\Delta X_{l}}=\rho_{l},
\end{eqnarray}
and it follows the summation form of the discrete hodograph transformation (\ref{dishodographMCmSP}).
\end{rem}

%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
%% Remark 3.5
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%

\begin{rem}
Equation (\ref{semidisMCmSP}) is also a self-adaptive moving mesh scheme for the MCmSP equation, but they are not applicable to non-zero or periodic boundary conditions with non-zero values near the boundary when used as a numerical scheme.
\end{rem}

%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
% Theorem 3.6
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%

\begin{thm}
A self-adaptive moving mesh scheme for the MCmSP equation under general boundary conditions is
\begin{eqnarray}
\left\{
\begin{array}{ll}
\displaystyle\frac{d}{dT}(u_{l+1}^{(i)}-u_{l}^{(i)})=(\delta_{l}-a)(u_{l+1}^{(i)}+u_{l}^{(i)}), \\
\\
\displaystyle\frac{d x_{l}}{d T}=-\displaystyle\sum_{1\leq j < k \leq n}c_{jk}u_{l}^{(j)}u_{l}^{(k)}.
\end{array}
\right.
\label{selfMCmSP}
\end{eqnarray}
Here, $u_{l}^{(i)}$ is the value at $x_{l}$.
\end{thm}

\begin{proof}
From the derivative law (\ref{m-derivativelaw}), we have the evolution equation for $x$
\begin{eqnarray}
\frac{\partial x}{\partial T}=-\displaystyle\sum_{1\leq j < k \leq n}c_{j,k}u^{(j)}u^{(k)}.
\label{6.27}
\end{eqnarray}
Equation (\ref{6.27}) shows that $x$ doesn't move when $u^{(j)}$ or $u^{(k)}$ is zero, but $x$ moves when $u^{(j)}$ and $u^{(k)}$ are non-zero.
This means that $x_{0}$ moves in the same way as $x$. Therefore, $x_{0}$ is a function with respect to $T$ and (\ref{999}) can be rewritten as
\begin{eqnarray}
x=x_{0}(T)+\int_{0}^{X} \rho(\bar{X},T)d\bar{X}.\label{semidis-hod-SP}
\end{eqnarray}
Differentiating the integral form of the hodograph transformation (\ref{semidis-hod-SP}) with respect to $T$, we obtain
\begin{eqnarray}
\fl{\frac{\partial x}{\partial T}=\frac{\partial x_{0}(T)}{\partial T}+\frac{\partial}{\partial T}\int_{0}^{X}\rho(\bar{X},T)d\bar{X}}\nonumber\\
\fl{=\frac{\partial x_{0}(T)}{\partial T}-\int_{0}^{X}\frac{\partial}{\partial \bar{X}}\left(\sum_{1\leq j < k\leq n}c_{jk}u^{(j)}(\bar{X},T)u^{(k)}(\bar{X},T)\right)d\bar{X}}\nonumber\\
\fl{=\frac{\partial x_{0}(T)}{\partial T}-\left[\displaystyle{\sum_{1\leq j < k \leq n}}c_{jk}u^{(j)}(X,T)u^{(k)}(X,T)-\displaystyle{\sum_{1\leq j < k \leq n}}c_{jk}u^{(j)}(0,T)u^{(k)}(0,T)\right].}\nonumber\\
\label{6.28}
\end{eqnarray}
The calculation from the first to the second line uses the conservation law (\ref{m-conservationlaw3}).
From (\ref{6.27}) and (\ref{6.28}), we obtain the evolution equation for the edge point $x_{0}$:
\begin{eqnarray}
\frac{\partial x_{0}(T)}{\partial T}=-\displaystyle{\sum_{1\leq j < k \leq n}}c_{jk}u^{(j)}(0,T)u^{(k)}(0,T).
\label{mSP_const}
\end{eqnarray}
We call (\ref{mSP_const}) the consistency condition with the hodograph transformation.

Next, we consider the discrete case.
Differentiating the summation form of the discrete hodograph transformation (\ref{dishodographMCmSP}) with respect to $T$ and using the second equation of (\ref{m-semidisdispersionless}), we obtain
\begin{eqnarray}
\frac{d x_{l}}{d T}&=&\frac{d x_{0}(T)}{d T}+\frac{d}{d T}\sum_{m=0}^{l-1}2a\rho_{m}=\frac{d x_{0}(T)}{d T}+\sum_{m=0}^{l-1}2a\frac{d \rho_{m}}{d T}\nonumber\\
&=&\frac{d x_{0}(T)}{d T}-\sum_{m=0}^{l-1}\sum_{1\leq j < k \leq n}c_{jk}(u_{m+1}^{(j)}u_{m+1}^{(k)}-u_{m}^{(j)}u_{m}^{(k)})\nonumber\\
&=&\frac{d x_{0}(T)}{d T}+\sum_{1\leq j < k \leq n}c_{jk}(-u_{l}^{(j)}u_{l}^{(k)}+u_{0}^{(j)}u_{0}^{(k)}).
\label{43}
\end{eqnarray}
Equation (\ref{43}) corresponds to (\ref{6.28}) in the continuous case.
As in the continuous case, we obtain the consistency condition, i.e., the evolution equation for the edge point $x_{0}$ :
\begin{eqnarray}
\frac{dx_{0}(T)}{d T}=-\displaystyle{\sum_{1\leq j < k \leq n}}c_{jk}u_{0}^{(j)}u_{0}^{(k)}.
\label{mSP_disconst}
\end{eqnarray}
Rewriting  the second equation of (\ref{semidisMCmSP}) as
 \begin{eqnarray}
\frac{d}{d T} (x_{l+1}-x_{l})=-\sum_{1\leq j < k \leq n}c_{jk}(u_{l+1}^{(j)}u_{l+1}^{(k)}-u_{l}^{(j)}u_{l}^{(k)}),
\end{eqnarray}
and referring to the consistency condition (\ref{mSP_disconst}), it then follows that
\begin{eqnarray}
\frac{d x_{l}}{d T}=-\sum_{1\leq j < k \leq n}c_{jk}u_{l}^{(j)}u_{l}^{(k)}.
\end{eqnarray}
\end{proof}

%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
%% Remark 3.7
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
\begin{rem}
 The integral form of the hodograph transformation (\ref{999}) and the summation form of the discrete hodograph transformation (\ref{dishodographMCmSP}) can be expressed by the $\tau$-function as
 \begin{eqnarray}
 x=X-(\log{f})_{T},
 \end{eqnarray}
 \begin{eqnarray}
 x_{l}=2al-(\log{f_{l}})_{T}.
  \end{eqnarray}
 See Appendix A for details.
\end{rem}

%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
% MCmSP 連続極限
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%

Dividing the first equation of (\ref{selfMCmSP}) by $\delta_{l}$, one arrives at
\begin{eqnarray}
\frac{(u_{l+1}^{(i)}-u_{l}^{(i)})_{T}}{\delta_{l}}=\left(1-\frac{a}{\delta_{l}}\right)(u_{l+1}^{(i)}+u_{l}^{(i)}).
\label{6.36}
\end{eqnarray}
In the continuous limit $a\rightarrow0\,\,(\delta_{l}\rightarrow0)$ for (\ref{6.36}), we obtain
\begin{eqnarray}
u^{(i)}_{Tx}=\left(2-\left(1+\sum_{1 \leq j < k \leq n}c_{jk}u^{(j)}_{x}u^{(k)}_{x}\right)\right)u^{(i)}
\end{eqnarray}
since
\begin{eqnarray}
\frac{a}{\delta_{l}}=\frac{1}{2\rho_{l}}\rightarrow \frac{1}{2}\left(1+\sum_{1 \leq j < k \leq n}c_{jk}u^{(j)}_{x}u^{(k)}_{x}\right).
\end{eqnarray}
The equation (\ref{6.36}) converges to the MCmSP equation
\begin{eqnarray}
\fl{\partial_{x}\left(\partial_{t}-\sum_{1\leq j<k \leq n}c_{jk}u^{(j)}u^{(k)}\partial_{x}\right)u^{(i)}=u^{(i)}\left(2-\left(1+\sum_{1 \leq j < k \leq n}c_{jk}u^{(j)}_{x}u^{(k)}_{x}\right)\right)},\nonumber
\end{eqnarray}
because of
\begin{eqnarray}
\frac{d}{dT}&=&\frac{dx_{l}}{dT}\frac{d}{d x_{l}}+\frac{d}{dt}\rightarrow-\sum_{1\leq j < k \leq n}c_{jk}u^{(j)}u^{(k)} \partial_{x}+\partial_{t}\quad  {\rm for}\quad a\rightarrow 0.
\end{eqnarray}




\end{section}

