\begin{section}{Bilinear equations and N-soliton solution for the MCSP equation}
\label{sec_MCSP}
In this section, we describe the bilinear form and the hodograph transformation of the MCSP equation
\begin{eqnarray}
u^{(i)}_{xt}=u^{(i)}+\frac{1}{2}\left(\sum_{1\leq j<k \leq n} c_{jk}u^{(j)}u^{(k)}u^{(i)}_{x}\right)_{x}, \qquad i=1,2,\cdots n, \label{MCSP5}
\end{eqnarray}
 and construct its N-soliton solution following the previous study by Feng et al. \cite{semidis-MCSP}.
At the beginning, by rewriting the MCSP equation into the conservation law form
\begin{eqnarray}
\left(\frac{1}{\rho}\right)_{t}-\left(\frac{F}{2\rho}\right)_{x}=0,\label{conservationlaw}
\end{eqnarray}
\begin{eqnarray}
\rho=\left(1+\sum_{1\leq j<k\leq n}c_{jk}u^{(j)}_{x}u^{(k)}_{x}\right)^{-\frac{1}{2}},\qquad F=\sum_{1\leq j<k\leq n}c_{jk}u^{(j)}u^{(k)},\label{conservationlaw2}
\end{eqnarray}
the hodograph transformation
\begin{eqnarray}
dX=\frac{1}{\rho} dx+\frac{F}{2\rho}dt,\qquad dT=dt,\label{hodograph}
\end{eqnarray}
is determined. From the  hodograph transformation (\ref{hodograph}), we obtain the derivative law
\begin{eqnarray}
\frac{\partial}{\partial X}=\rho \frac{\partial}{\partial x},\qquad\frac{\partial}{\partial T}=\frac{\partial }{\partial t}-\frac{F}{2}\frac{\partial }{\partial x}.\label{derivativelaw}
\end{eqnarray}
Next, transforming the MCSP equation into
\begin{eqnarray}
\partial_{x}\left(\partial_{t}-\frac{1}{2}\sum_{1\leq j<k \leq n}c_{jk}u^{(j)}u^{(k)}\partial_{x}\right)u^{(i)}=u^{(i)},\label{6}
\end{eqnarray}
 and applying the the derivative law (\ref{derivativelaw}) and (\ref{conservationlaw2}) to (\ref{6}), we obtain
 \begin{eqnarray}
 u^{(i)}_{XT}=u^{(i)}\rho.
 \end{eqnarray}
Furthermore, applying the derivative law (\ref{derivativelaw})  to the conservation law (\ref{conservationlaw}), we then have
 \begin{eqnarray}
\rho_{T}+\frac{1}{2}\left(\sum_{1\leq j<k\leq n}c_{jk}u^{(j)}u^{(k)}\right)_{X}=0.\label{conservationlawXT}
 \end{eqnarray}
The equation (\ref{conservationlawXT}) is the conservation law for $X$ and $T$, where $\rho$ is the conservation density and $\frac{1}{2}\sum_{1\leq j<k\leq n}c_{jk}u^{(j)}u^{(k)}$ is the flux.

Therefore, the MCSP equation (\ref{MCSP}) is transformed into the MCCID equations
\begin{eqnarray}
\left\{
\begin{array}{ll}
 u^{(i)}_{XT}=u^{(i)}\rho,\\
   \rho_{T}+\displaystyle\frac{1}{2}\left(\displaystyle\sum_{1\leq j<k\leq n}c_{jk}u^{(j)}u^{(k)}\right)_{X}=0,
 \end{array}
\right.
\label{dispersionlessMCSP}
\end{eqnarray}
 by the hodograph transformation (\ref{hodograph}).

Introducing the dependent variable transformation
\begin{eqnarray}
u^{(i)}=\frac{g^{(i)}}{f}\quad(i=1,2,\cdots n),\qquad\rho=1-2({\rm log}f)_{XT},\label{dependenttransformation}
\end{eqnarray}
 the MCCID equations
 (\ref{dispersionlessMCSP}) lead to
\begin{eqnarray}
\left\{
\begin{array}{ll}
D_{X}D_{T}f\cdot g^{(i)}=fg^{(i)},\\
  D_{T}^{2}f\cdot f=\displaystyle\frac{1}{2}\displaystyle\sum_{1\leq j<k\leq n}c_{jk}g^{(j)}g^{(k)}.
\end{array}
\right.
\label{bilinearMCSP}
\end{eqnarray}


%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
%%Lemma 5.1
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%

\begin{lem}
(Feng-Maruno-Ohta \cite{semidis-MCSP}). The bilinear equations (\ref{bilinearMCSP}) have the following Pfaffian solution:
\begin{eqnarray}
\fl{f={\rm Pf}(a_{1},\cdots,a_{2N},b_{1},\cdots,b_{2N}),\qquad g^{(i)}={\rm Pf}(d_{0},B_{i},a_{1},\cdots,a_{2N},b_{1},\cdots,b_{2N}),}
\end{eqnarray}
where $i=1,2,\cdots,n$ and the elements of the Pfaffians are defined as
\begin{eqnarray}
{\rm Pf}(a_{j},a_{k})=\frac{p_{j}-p_{k}}{p_{j}+p_{k}}e^{\xi_{j}+\xi_{k}},\qquad
{\rm Pf}(a_{j},b_{k})=\delta_{j,k},\label{pfMCSP1}
\end{eqnarray}
\begin{eqnarray}
{\rm Pf}(b_{j},b_{k})=\frac{1}{4}\frac{c_{\mu\nu}}{p_{j}^{-2}-p_{k}^{-2}}\quad(b_{j}\in B_{\mu},b_{k}\in B_{\nu} ),
\end{eqnarray}
\begin{eqnarray}
{\rm Pf}(d_{l},a_{k})=p_{k}^{l}e^{\xi_{k}},
\qquad
{\rm Pf}(b_{j},B_{\mu})=
\left\{
\begin{array}{ll}
1 & (b_{j}\in B_{\mu}) \\
0 & (b_{j}\notin B_{\mu})
\end{array}
\right..
\label{pfMCSP2}
\end{eqnarray}
Here, $j,k =1,2,\cdots 2N$,\quad$\mu,\nu=1,2,\cdots n,\quad\xi_{j}=p_{j}X+p_{j}^{-1}T+\xi_{i0}$ and $l$ is an integer. A class of set $B_{\mu}(\mu=1,2,\cdots,n) $ satisfies the following conditions
\begin{eqnarray}
B_{\mu}\cap B_{\nu}=\varnothing\,\,{\rm if}\,\, \mu\neq\nu,\qquad\cup_{\mu=1}^{n}B_{\mu}=\{b_{1},b_{2},\cdots,b_{2N}\}.
\end{eqnarray}
The elements of the Pfaffians not defined above are defined as zero.
\end{lem}

\begin{proof}
See \cite{semidis-MCSP}.
\end{proof}
\end{section}

