\begin{section}{A self-adaptive moving mesh scheme for the MCSP equation}
\label{sec_disMCSP}
We proposed a semi-discrete analogue of bilinear equations (\ref{bilinearMCSP})
\begin{eqnarray}
\left\{
\begin{array}{ll}
  \displaystyle\frac{1}{a}D_{T}(g_{l+1}^{(i)}\cdot f_{l}-g_{l}^{(i)}\cdot f_{l+1})=g_{l+1}^{(i)}f_{l}+g_{l}^{(i)}f_{l+1}\quad,i=1,2,\cdots,n,\\
  D_{T}^{2}f_{l}\cdot f_{l}=\displaystyle\frac{1}{2}\displaystyle\sum_{1\leq j<k\leq n}c_{jk}g_{l}^{(j)}g_{l}^{(k)},
\end{array}
\right.
\label{disbilinearMCSP}
\end{eqnarray}
in \cite{semidis-MCSP}. Here, 2a is the parameter related to a discrete interval.


%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
%% Lemma 6.1
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%

\begin{lem}
(Feng-Maruno-Ohta \cite{semidis-MCSP}). The bilinear equations (\ref{disbilinearMCSP}) have the following Pfaffian solution:
\begin{eqnarray}
\fl{f_{l}={\rm Pf}(a_{1},\cdots,a_{2N},b_{1},\cdots,b_{2N})_{l},\qquad g_{l}^{(i)}={\rm Pf}(d_{0},B_{i},a_{1},\cdots,a_{2N},b_{1},\cdots,b_{2N})_{l},}
\label{dis_g_MCSP}
\label{dis_f_MCSP}
\end{eqnarray}
where $i=1,2,\cdots,n$ and the elements of the Pfaffians are defined as
\begin{eqnarray}
{\rm Pf}(a_{j},a_{k})_{l}=\frac{p_{j}-p_{k}}{p_{j}+p_{k}}\phi_{j}^{(0)}(l)\phi_{k}^{(0)}(l),\qquad{\rm Pf}(a_{j},b_{k})_{l}=\delta_{j,k},
\label{dpfMCSP1}
\end{eqnarray}
\begin{eqnarray}
{\rm Pf}(b_{j},b_{k})_{l}=\frac{1}{4}\frac{c_{\mu\nu}}{p_{j}^{-2}-p_{k}^{-2}}\quad(b_{j}\in B_{\mu},b_{k}\in B_{\nu} ),
\end{eqnarray}
\begin{eqnarray}
{\rm Pf}(d_{l},a_{j})_{l}=\phi_{j}^{(l)}(l),\qquad{\rm Pf}(d^{l},a_{j})_{l}=\phi_{j}^{(0)}(l+1),
\end{eqnarray}
\begin{eqnarray}
{\rm Pf}(b_{k},B_{\mu})_{l}=
\left\{
\begin{array}{ll}
 1 & (b_{k}\in B_{\mu}),\\
 0 & (b_{k}\notin B_{\mu}) ,
\end{array}
\right.
\end{eqnarray}
\begin{eqnarray}
{\rm Pf}(d_{0},d^{l})_{l}=1,\qquad{\rm Pf}(d_{-1},d^{l})_{l}=-a,
\label{dpfMCSP2}
\end{eqnarray}
where
\begin{eqnarray}
\phi_{j}^{(n)}(l)=p_{j}^{n}\left(\frac{1+ap_{j}}{1-ap_{j}}\right)^{l}e^{p_{j}^{-1}T+\xi_{j0}},
\end{eqnarray}
and it satisfies the following equation
\begin{eqnarray}
\frac{\phi_{j}^{(n)}(l+1)-\phi_{j}^{(n)}(l)}{a}=\phi_{j}^{(n+1)}(l+1)+\phi_{j}^{(n+1)}(l).
\end{eqnarray}
\end{lem}
The elements of the Pfaffians not defined above are defined as zero.
\begin{proof}
See \cite{semidis-MCSP}.
\end{proof}

%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
%% Lemma 6.2
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%

\begin{lem}
A semi-discrete analogue of the MCCID equations (\ref{dispersionlessMCSP})
\begin{eqnarray}
\left\{
\begin{array}{ll}
  \displaystyle\frac{d}{dT}(u_{l+1}^{(i)}-u_{l}^{(i)})=a\rho_{l}(u_{l+1}^{(i)}+u_{l}^{(i)}),\\
  \displaystyle\frac{d}{dT}\rho_{l}=-\displaystyle\frac{1}{2a}\left(\displaystyle\frac{1}{2}\sum_{1\leq j<k\leq n}c_{jk}(u_{l+1}^{(j)}u_{l+1}^{(k)}-u_{l}^{(j)}u_{l}^{(k)})\right),
\end{array}
\right.
\label{semidisdispersionlessMCSP}
\end{eqnarray}
is obtained from the bilinear equations (\ref{disbilinearMCSP}) through the dependent variable transformation
\begin{eqnarray}
u_{l}^{(i)}=\frac{g_{l}^{(i)}}{f_{l}},\qquad
\rho_{l}=1-\frac{1}{a}\left(\log{\frac{f_{l+1}}{f_{l}}}\right)_{T}.
\label{disdependenttransformationMCSP}
\end{eqnarray}

\end{lem}


\begin{proof}
At first, dividing both sides of the first equation of the bilinear equations (\ref{disbilinearMCSP}) by $f_{l+1}f_{l}$, we obtain
\begin{eqnarray}
\left(\frac{g_{l+1}^{(i)}}{f_{l+1}}-\frac{g_{l}^{(i)}}{f_{l}}\right)_{T}=\left(a-\left(\log{\frac{f_{l+1}}{f_{l}}}\right)_{T}\right)\left(\frac{g_{l+1}^{(i)}}{f_{l+1}}+\frac{g_{l}^{(i)}}{f_{l}}\right).
\end{eqnarray}
It follows
\begin{eqnarray}
\frac{d}{dT}(u_{l+1}^{(i)}-u_{l}^{(i)})=a\rho_{l}(u_{l+1}^{(i)}+u_{l}^{(i)}),
\end{eqnarray}
by the dependent variable transformation (\ref{disdependenttransformationMCSP}).

Next, from the dependent variable transformation (\ref{disdependenttransformationMCSP}), the second equation of the bilinear equations (\ref{disbilinearMCSP}) is rewritten as
\begin{eqnarray}
(\log{f_{l}})_{TT}=\frac{1}{4}\sum_{1\leq j<k\leq n}c_{jk}u_{l}^{(j)}u_{l}^{(k)}.\label{aux1MCSP}
\end{eqnarray}
By (\ref{aux1MCSP}) and the dependent variable transformation (\ref{disdependenttransformationMCSP}), we obtain
\begin{eqnarray}
\frac{d}{dT}\rho_{l}=-\frac{1}{2a}\left(\frac{1}{2}\sum_{1\leq j<k\leq n}c_{jk}(u_{l+1}^{(j)}u_{l+1}^{(k)}-u_{l}^{(j)}u_{l}^{(k)})\right).
\end{eqnarray}
\end{proof}

%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
%% Lemma 6.3
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%

\begin{lem}
\label{6.3}
A semi-discrete analogue of the MCSP equation is of the form:
\begin{eqnarray}
\left\{
\begin{array}{ll}
  \displaystyle\frac{d} {dT}(u_{l+1}^{(i)}-u_{l}^{(i)})= \displaystyle\frac{\delta_{l}}{2}(u_{l+1}^{(i)}+u_{l}^{(i)}),\\
  \\
 \displaystyle\frac{d\delta_{l}}{dT}=-\displaystyle\frac{1}{2}\sum_{1\leq j<k \leq n}c_{jk}(u_{l+1}^{(j)}u_{l+1}^{(k)}-u_{l}^{(j)}u_{l}^{(k)}),\\
 x_{l}=x_{0}+ \displaystyle\sum_{m=0}^{l-1}\delta_{m},\quad t=T.
\end{array}
\right.
\label{semidisMCSP}
\end{eqnarray}
Here, $u_{l}^{(i)}$ is the value at $x_{l}$.
\end{lem}

\begin{proof}
From the derivative law (\ref{derivativelaw}), we obtain
\begin{eqnarray}
\frac{\partial x}{\partial X}=\rho.\label{3.19}
\end{eqnarray}
Integrating (\ref{3.19}) with respect to $X$, we have the integral form of the hodograph transformation (\ref{hodograph})
\begin{eqnarray}
x=\int\rho(X,T)dX=x_{0}+\int_{0}^{X}\rho(\bar{X},T)d\bar{X},
\label{9}
\end{eqnarray}
where $x_{0}$ is a constant of integration determined from the left-hand edge $(x=x_{0})$.
Now, we discretize (\ref{9}), we then have the discrete hodograph transformation
\begin{eqnarray}
x_{l}=x_{0}+\sum_{m=0}^{l-1}2a\rho_{m},
\label{dishodographMCSP}
\end{eqnarray}
where $ \rho_{l}\equiv\rho(X_{l},T)$.


Introducing a mesh interval
\begin{eqnarray}
\delta_{l}:=x_{l+1}-x_{l},
\end{eqnarray}
we obtain
\begin{eqnarray}
\delta_{l}=2a\rho_{l},\label{meshintMCSP}
\end{eqnarray}
by substituting the discrete hodograph transformation (\ref{dishodographMCSP}).
Substituting  (\ref{meshintMCSP}) into the semi-discrete MCCID equations (\ref{semidisdispersionlessMCSP}), we have a semi-discrete analogue of the MCSP equation (\ref{semidisMCSP})
\end{proof}

%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
%% Remark 6.4
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
\begin{rem}
Equation (\ref{dishodographMCSP}) is the summation form of the discrete hodograph transformation:
\begin{eqnarray}
\Delta x_{l}=\rho_{l}\Delta X_{l}-\frac{1}{2}\sum_{1\leq j<k\leq n}c_{jk}u_{l}^{(j)}u_{l}^{(k)}dT,\quad dt=dT.
\label{ddishodographMCSP}
\end{eqnarray}
Equation (\ref{ddishodographMCSP}) is obtained from the second equation of  (\ref{semidisdispersionlessMCSP}) which is the discrete version of the conservation law (\ref{conservationlawXT}).
From the  discrete hodograph transformation (\ref{ddishodographMCSP}), we have
\begin{eqnarray}
\frac{\Delta x_{l}}{\Delta X_{l}}=\rho_{l},
\end{eqnarray}
and it follows the summation form of the discrete hodograph transformation (\ref{dishodographMCSP}).
\end{rem}



%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
%  Theorem 6.5
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%

\begin{thm}
A self-adaptive moving mesh scheme for the MCSP equation under general boundary conditions is
\begin{eqnarray}
\left\{
\begin{array}{ll}
\displaystyle\frac{d}{dT}(u_{l+1}^{(i)}-u_{l}^{(i)})=\displaystyle\frac{\delta_{l}}{2}(u_{l+1}^{(i)}+u_{l}^{(i)}), \\
\\
\displaystyle\frac{d x_{l}}{d T}=-\displaystyle\frac{1}{2}\sum_{1\leq j<k \leq n}c_{jk}u_{l}^{(j)}u_{l}^{(k)}.
\end{array}
\right.
\label{3.24}
\end{eqnarray}
Here, $u_{l}^{(i)}$ is the value at $x_{l}$.
\end{thm}

%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
% Theorem 6.5 Proof
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
\begin{proof}
From the derivative law (\ref{derivativelaw}), we have the evolution equation for $x$
\begin{eqnarray}
\frac{\partial x}{\partial T}=-\frac{1}{2}\displaystyle{\sum_{1\leq j < k \leq n}c_{jk}u^{(j)}u^{(k)}}.
\label{SP_evol}
\end{eqnarray}
The equation (\ref{SP_evol}) shows that $x_{0}$ is a function with respect to $T$ as well as  $x$, and (\ref{9}) can be rewritten as
\begin{eqnarray}
x=x_{0}(T)+\int_{0}^{X}\rho(\bar{X},T)d\bar{X}.
\label{9999}
\end{eqnarray}
Differentiating the integral form of the hodograph transformation (\ref{9999}) with respect to $T$, we have
\begin{eqnarray}
\fl{\frac{\partial x}{\partial T}=\frac{\partial x_{0}(T)}{\partial T}+\frac{\partial}{\partial T}\int_{0}^{X}\rho(\bar{X},T)d\bar{X}}\nonumber\\
\fl{=\frac{\partial x_{0}(T)}{\partial T}-\int_{0}^{X}\frac{\partial}{\partial \bar{X}}\left(\frac{1}{2}\sum_{1\leq j<k\leq n}c_{jk}u^{(j)}(\bar{X},T)u^{(k)}(\bar{X},T)\right)d\bar{X}}\nonumber\\
\fl{=\frac{\partial x_{0}(T)}{\partial T}-\frac{1}{2}\left[\displaystyle{\sum_{1\leq j <k \leq n}}c_{jk}u^{(j)}(X,T)u^{(k)}(X,T)-\displaystyle{\sum_{1\leq j<k \leq n}}c_{jk}u^{(j)}(0,T)u^{(k)}(0,T)\right].}
\label{0.26}
\end{eqnarray}
The calculation from the first to the second line uses the conservation law (\ref{conservationlawXT}).
From (\ref{SP_evol}) and (\ref{0.26}), we obtain the evolution equation for the edge point $x_{0}$:
\begin{eqnarray}
\frac{\partial x_{0}(T)}{\partial T}=-\frac{1}{2}\displaystyle{\sum_{1\leq j < k \leq n}}c_{jk}u^{(j)}(0,T)u^{(k)}(0,T).
\label{SP_const}
\end{eqnarray}
We call (\ref{SP_const}) the consistency condition with the hodograph transformation.

Next, we consider the discrete case. Differentiating the summation form of the discrete hodograph transformation (\ref{dishodographMCSP}) with respect to $T$ and using the second equation of  (\ref{semidisdispersionlessMCSP}), we obtain
\begin{eqnarray}
\frac{d x_{l}}{d T}&=&\frac{d x_{0}(T)}{d T}+\frac{d}{d T}\sum_{m=0}^{l-1}2a\rho_{m}=\frac{d x_{0}(T)}{d T}+\sum_{m=0}^{l-1}2a\frac{d \rho_{m}}{d T}\nonumber\\
&=&\frac{d x_{0}(T)}{d T}-\sum_{m=0}^{l-1}\frac{1}{2}\sum_{1\leq j<k \leq n}c_{jk}(u_{m+1}^{(j)}u_{m+1}^{(k)}-u_{m}^{(j)}u_{m}^{(k)})\nonumber\\
&=&\frac{d x_{0}(T)}{d T}+\frac{1}{2}\sum_{1\leq j<k \leq n}c_{jk}(-u_{l}^{(j)}u_{l}^{(k)}+u_{0}^{(j)}u_{0}^{(k)}).
\label{23}
\end{eqnarray}
Equation (\ref{23}) corresponds to (\ref{0.26}) in the continuous case. As in the continuous case, we obtain the consistency condition, i.e., the evolution equation for the edge point $x_{0}$:
\begin{eqnarray}
\frac{dx_{0}(T)}{dT}=-\frac{1}{2}\displaystyle{\sum_{1\leq j < k \leq n}}c_{jk}u_{0}^{(j)}u_{0}^{(k)}.
\label{disSP_const}
\end{eqnarray}
Rewriting  the second equation of (\ref{semidisMCSP}) as
 \begin{eqnarray}
 \displaystyle\frac{d}{dT}(x_{l+1}-x_{l})=-\displaystyle\frac{1}{2}\sum_{1\leq j<k \leq n}c_{jk}(u_{l+1}^{(j)}u_{l+1}^{(k)}-u_{l}^{(j)}u_{l}^{(k)}),
 \end{eqnarray}
and referring to the consistency condition (\ref{disSP_const}), it then follows that
\begin{eqnarray}
\frac{d x_{l}}{d T}=-\frac{1}{2}\sum_{1\leq j<k \leq n}c_{jk}u_{l}^{(j)}u_{l}^{(k)}.
\end{eqnarray}
\end{proof}

