%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
%   連続極限
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
Dividing the first equation of (\ref{3.24}) by $\delta_{l}$, one arrives at
\begin{eqnarray}
\frac{(u_{l+1}^{(i)}-u_{l}^{(i)})_{T}}{\delta_{l}}=\frac{u_{l+1}^{(i)}+u_{l}^{(i)}}{2}.\label{3.38}
\end{eqnarray}
In the continuous limit $a\rightarrow0\,\,(\delta_{l}\rightarrow0)$ for (\ref{3.38}), we obtain
\begin{eqnarray}
u^{(i)}_{Tx}=u^{(i)}.
\end{eqnarray}
Since
\begin{eqnarray}
\frac{d}{dT}=\frac{dx_{l}}{dT}\frac{d}{dx_{l}}+\frac{d}{dt}\rightarrow-\frac{1}{2}\sum_{1\leq j < k \leq n}c_{jk}u^{(j)}u^{(k)} \partial_{x}+\partial_{t}\quad\rm{for}\quad a\rightarrow 0,
\end{eqnarray}
equation (\ref{3.38}) converges to
\begin{eqnarray}
\partial_{x}\left(\partial_{t}-\frac{1}{2}\sum_{1\leq j<k \leq n}c_{jk}u^{(j)}u^{(k)}\partial_{x}\right)u^{(i)}=u^{(i)},
\end{eqnarray}
which is exactly the MCSP equation.
\end{section}
