\section*{Appendix A}
 \renewcommand{\theequation}{A.\arabic{equation}}
 \setcounter{section}{0}
From the second equation of the dependent variable transformation (\ref{m-dependenttransformation}), we have
\begin{eqnarray}
x&=&\int \rho(X,T)dX=x_{0}(T)+\int_{0}^{X}\rho(\bar{X},T)d\bar{X}\nonumber\\
&=&x_{0}(T)+\int_{0}^{X}\left(1-(\log{f(\bar{X},T)})_{\bar{X}T}\right)d\bar{X}\nonumber\\
&=&x_{0}(T)+X-(\log{f(X,T)})_{T}+(\log{f(0,T)})_{T}.
\label{B1}
\end{eqnarray}
Differentiating (\ref{B1}) with respect to $T$, one obtains
\begin{eqnarray}
\frac{\partial x}{\partial T}&=&\frac{\partial x_{0}(T)}{\partial T}-(\log{f(X,T)})_{TT}+(\log{f(0,T)})_{TT}.
\end{eqnarray}
Considering the consistency with the hodograph transformation, it follows that
\begin{eqnarray}
\frac{\partial x_{0}}{\partial T}=-(\log{f(0,T)})_{TT}.
\end{eqnarray}
Taking $x_{0}(T)$ for $x_{0}(T)=-(\log{f(0,T)})_{T}$, we obtain $x=X-(\log{f(X,T)})_{T}$.


Next, we consider the discrete case in the same way.  From the second equation of the dependent variable transformation (\ref{disdependenttransformation}), we obtain
\begin{eqnarray}
x_{l}&=&x_{0}(T)+\sum_{m=0}^{l-1}2a\rho_{m}=x_{0}(T)+\sum_{m=0}^{l-1}2a\left(1-\frac{1}{2a}\left(\log{\frac{f_{m+1}}{f_{m}}}\right)_{T}\right)\nonumber\\
&=&x_{0}(T)+2al-(\log{f_{l}})_{T}+(\log{f_{0}})_{T}.
\label{B5}
\end{eqnarray}
Differentiating (\ref{B5}) with respect to $T$, one obtains
\begin{eqnarray}
\frac{dx_{l}}{dT}&=&\frac{dx_{0}(T)}{dT}-(\log{f_{l}})_{TT}+(\log{f_{0}})_{TT}.
\label{B6}
\end{eqnarray}
Considering the consistency with the hodograph transformation, it follows that
\begin{eqnarray}
\frac{dx_{0}}{dT}=-(\log{f_{0}})_{TT}.
\end{eqnarray}
Taking $x_{0}(T)$ for $x_{0}(T)=-(\log{f_{0}})_{T},$ we obtain $x_{l}=2al-(\log{f_{l}})_{T}$.


\section*{Appendix B}
 \renewcommand{\theequation}{B.\arabic{equation}}
 \setcounter{section}{0}
From the second equation of the dependent variable transformation (\ref{dependenttransformation}), we have
\begin{eqnarray}
x&=&\int \rho(X,T)dX=x_{0}(T)+\int_{0}^{X}\rho(\bar{X},T)d\bar{X}\nonumber\\
&=&x_{0}(T)+\int_{0}^{X}\left(1-2(\log{f(\bar{X},T)})_{\bar{X}T}\right)d\bar{X}\nonumber\\
&=&x_{0}(T)+X-2(\log{f(X,T)})_{T}+2(\log{f(0,T)})_{T}.
\label{A1}
\end{eqnarray}
Differentiating (\ref{A1}) with respect to $T$, one obtains
\begin{eqnarray}
\frac{\partial x}{\partial T}&=&\frac{\partial x_{0}(T)}{\partial T}-2(\log{f(X,T)})_{TT}+2(\log{f(0,T)})_{TT}.
\end{eqnarray}
Considering the consistency with the hodograph transformation, it follows that
\begin{eqnarray}
\frac{\partial x_{0}}{\partial T}=-2(\log{f(0,T)})_{TT}.
\end{eqnarray}
Taking $x_{0}(T)$ for $x_{0}(T)=-2(\log{f(0,T)})_{T}$, we have $x=X-2(\log{f(X,T)})_{T}$.



Next, we consider the discrete case in the same way.  From the second equation of the dependent variable transformation (\ref{disdependenttransformationMCSP}), we obtain
\begin{eqnarray}
x_{l}&=&x_{0}(T)+\sum_{m=0}^{l-1}2a\rho_{m}=x_{0}(T)+\sum_{m=0}^{l-1}2a\left(1-\frac{1}{a}\left(\log{\frac{f_{m+1}}{f_{m}}}\right)_{T}\right)\nonumber\\
&=&x_{0}(T)+2al-2(\log{f_{l}})_{T}+2(\log{f_{0}})_{T}.
\label{A5}
\end{eqnarray}
Differentiating (\ref{A5}) with respect to $T$, one obtain
\begin{eqnarray}
\frac{dx_{l}}{dT}&=&\frac{dx_{0}(T)}{dT}-2(\log{f_{l}})_{TT}+2(\log{f_{0}})_{TT}.
\label{A6}
\end{eqnarray}
Considering the consistency with the hodograph transformation, it follows that
\begin{eqnarray}
\frac{dx_{0}}{dT}=-2(\log{f_{0}})_{TT}.
\end{eqnarray}
Taking $x_{0}(T)$ for $x_{0}(T)=-2(\log{f_{0}})_{T}$, we obtain $x_{l}=2al-2(\log{f_{l}})_{T}$.



