\section{Lattice Gauge Theory}
\label{app:kin}
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%



In this appendix, we review some fundamental formulas of lattice gauge theory to establish the notation used in the main text and to elaborate on specific results referenced therein.

In this work, we took the convention that, for each oriented edge on the lattice, carrying an Hilbert space $\H_e=L^2(G)$, the commuting left and right unitary actions of $G$ are $U(h)\ket{g}=\ket{hg}$ and $V(h)\ket{g}=\ket{gh^{-1}}$. We recall that the link variable $\hat{g}$ is a quantum operator valued in a representation $\rho$ of $G$. From this, we have the actions:
\begin{align}
    U(h)\hat{g}U^\dagger(h)= \rho(h^{-1})\hat{g}\quad \text{and} \quad V(h)\hat{g}V^\dagger(h)=\hat{g}\rho(h)\,.
\end{align}
So $\hat{g}$ itself transforms in the representation space $\mathbf{V}_\rho^L\otimes\l\mathbf{V}_\rho^R\r^*$ under the action of gauge transformations. These act independently at each of the bulk vertices $v\in\mathcal{V}_{\rm b}:=\mathcal{V}\setminus\left(\mathcal{V}\cap\mathcal{B}\right)$, in our convention as \eqref{eq:gaugetransfconv} (opposite of \cite{VanAcoleyen:2015ccp}):
\be
U_v(h)=\bigotimes_{e\in\mathcal{E}_v^{\rm in}}U_e(h)\bigotimes_{e'\in\mathcal{E}_v^{\rm out}}V_e(h)\,, 
\ee
where $\mathcal{E}_v^{\rm in/out}$ denote the sets of in- and outgoing edges at $v$. Bulk link variables thus transform as 
\be
\hat{g}_e\mapsto U_{v_i}(h_i)U_{v_f}(h_f)\hat{g}_e U_{v_f}^\dag(h_f)U^\dag_{v_i}(h_i)=V_e(h_i)U_e(h_f)\hat{g}_e U_e^\dag(h_f)V_e^\dag(h_i)=\rho(h^{-1}_f)\hat{g}_e\rho(h_i)\,.
\ee

Defining the generators of the left and right actions as
\begin{align}
    U(h)=e^{-i\theta^a \hat{L}^a} \quad \text{and} \quad V(h)=e^{+i\theta^a \hat{R}^a}\,,\quad \text{for}\quad h=e^{i\theta^a T^a}\,.
\end{align}
We remark that $\hat{L}^a$ and $\hat{R}^a$ are both quantum operators but do not live in the Lie algebra $\mathfrak{g}$.
Expanding to linear order, we get the Hilbert space commutators
\begin{align}
\label{eq:RL_G_commutators}
    [\hat{L}^a, \hat{g}]=T^a_\rho \hat{g}\quad \text{and}\quad [\hat{R}^a,\hat{g}]=\hat{g}T^a_\rho\,,
\end{align}
where $T^a_\rho$ are the generators of $\mathfrak{g}$ in representation $\rho$ and matrix indices are implicitly contracted. The Hilbert space brackets for the two sets of generators are defined by
\begin{align}\label{commutators}
    [\hat{L}^a,\hat{L}^b]=-i f^{abc}\hat{L}^c\,,\quad[\hat{R}^a,\hat{R}^b]=i f^{abc}\hat{R}^c\,,\quad [\hat{L}^a,\hat{R}^b]=0\,.
\end{align}
where $f_{abc}$ are the structure constants of $\mathfrak{g}$.
Under group multiplication, the generators transform in the adjoint representation
\begin{align}
    U(h)\hat{L}^aU(h)^\dagger=D(h^{-1})^{ab}\hat{L}^b\quad \text{and}\quad V(h)\hat{R}^aV(h)^\dagger=D(h^{-1})^{ab}\hat{R}^b\,, 
\end{align}
where $D$ denotes the adjoint representation of $G$. 
The generators transform under independent actions of $G_L$ and $G_R$, respectively. If we have an oriented edge, with associated Hilbert space, we can obtain the same equivalent description by ‘‘inverting the arrow" mapping:
$\hat g \to \hat g^\dagger$ and $\hat L^i \leftrightarrow \hat R^i$.

Finally, we introduce the following notation for the generators of gauge transformation at node $v$, such that $U_v(h)=e^{-i\theta^a \mathfrak{G}_v^{\,a}}$,  for $h=e^{i\theta^a T^a}$. From \eqref{eq:gaugetransfconv} we get 
\be
\label{eq:Gauss_Law_generators}
\mathfrak{G}_v^{\,a} = \sum_{e\in\mathcal{E}_v}(\mathfrak{G}_e^v)^a\,,
\q \wth \q
(\mathfrak{G}_e^v)^a =\left \{ 
\begin{array}{rl}
  L_e^a   & \text{if}\;\;e\in\mathcal{E}_v^{\rm in} \\[5pt]
  -R_e^a   & \text{if}\;\;e\in\mathcal{E}_v^{\rm out}
\end{array}
\right.
\ee
These are the operators entering the Gauss law $\mathfrak{G}_v^{\,a}=0$, $\forall v\in \cV_b$.


A central role is played by the Peter–Weyl theorem, which states that for any compact group $G$:
\begin{align}
    L^2(G)\cong \bigoplus_{[r]}\mathcal{H}_r\otimes\mathcal{H}_{r^*}\,,
\end{align}
where $[r]$ labels isomorphism classes of irreducible representations of $G$ and $r^*$ denotes the dual of $r$. This means that there is a natural (dual) basis for $L^2(G)$ respecting this decomposition
\begin{align}
    L^2(G) = \text{span}_\mathbb{C}\{\ket{r,i,j}|\, r\in\{[r]\},\,i,j=1,...,d_r\}\,,\quad \text{where}\quad d_r=\text{dim}(\mathcal{H}_r)\,.
\end{align}
with the relation to the group basis given by
\begin{align}
    \ket{r,i,j} = \sqrt{\frac{d_r}{{\rm Vol}(G)}}\int_G dg \, (\rho^r(g))^i_j \ket{g}\,,
\end{align}
where $\rho^r$ is  is the matrix representative of $g$ in irrep $r$. The action of the generators on the dual basis follows from
\begin{align}
    U(h)\ket{r,i,j}=(\rho^r(h))^i_k\ket{r,k,j}\quad \text{and}\quad V(h)\ket{r,i,j}=(\rho^{r^*}(h))^j_k\ket{r,i,k}\,,
\end{align}
by expanding to linear order
\begin{align}
    \hat{L}^a\ket{r,i,j}=-(T^a_r)^i_k\ket{r,k,j}\quad \text{and}\quad \hat{R}^a\ket{r,i,j}=-(T^a_r)^k_j\ket{r,i,k}\,,
\end{align}
where we used the fact that $(T^a_{r^*})^i_j=-(T^a_r)^j_i$ for any $(r,r^*)$ dual pair. 

This allows us to show that the left and right electric fields are not independent, but are related by the link operator, which carries a color charge. To see this, define the link operator in the adjoint representation
\begin{align}
    \hat{g}_\text{Adj}:=\int [dg] D(g) \ket{g}\bra{g}\,.
\end{align}
We now consider the action of the composite operator $(\hat{g}_\text{Adj})^{ab}\hat{L}^b$ on the dual basis $\ket{r,i,j}$ of $L^2(G)$
\begin{align}
    (\hat{g}_\text{Adj})^{ab}\hat{L}^b\ket{r,i,j}&=-(\hat{g}_\text{Adj})^{ab}(T^b_r)^i_k\ket{r,k,j}\\
    &=-(\hat{g}_\text{Adj})^{ab}(T^b_r)^i_k \sqrt{\frac{d_r}{{\rm Vol}(G)}}\int_G dg \, (\rho^r(g))^k_j \ket{g}\\
    &=-\sqrt{\frac{d_r}{{\rm Vol}(G)}}\int_G dg\,(\rho^r(g))^k_j \underbrace{(T^b_r)^i_k D(g)^{ab}}_{\l\rho^r(g)T^a_r\rho^r(g^{-1})\r^i_k}\ket{g}\\
    &=-\sqrt{\frac{d_r}{{\rm Vol}(G)}}\int_G dg\,\l\rho^r(g)T^a_r\r^i_j\ket{g}\\
    &=-(T^a_r)^k_j\sqrt{\frac{d_r}{{\rm Vol}(G)}}\int_G dg\,(\rho^r(g))^i_k\ket{g}\\
    &=-(T^a_r)^k_j\ket{r,i,k} = \hat{R}^a\ket{r,i,j}\,\quad\forall r,i,j\,.
\end{align}
In going from the third to the fourth line, we made use of the adjoint action of a group on its Lie algebra. In conclusion, we have
\begin{align}\label{eq:l=r}
    \hat{R}^a=(\hat{g}_\text{Adj})^{ab}\hat{L}^b \overset{\dagger}{\iff} \hat{R}^a = \hat{L}^b (\hat{g}_\text{Adj})^{ab}\,.
\end{align}

The left and right Casimir quantum operators are defined as
\begin{align}
    \hat{C}_L:=\hat{L}^a\hat{L}^a \quad \text{and} \quad \hat{C}_R:=\hat{R}^a\hat{R}^a\,,
\end{align}
while the Lie algebra Casimir is given by $C_\rho:=T^a_\rho T^a_\rho$ in the $\rho$ representation. From \eqref{eq:l=r} it immediately follows that $\hat{C}_L=\hat{C}_R$.
We have the following Hilbert space brackets
\begin{align}
    [\hat{C}_L,\hat{g}]=\hat{L}^aT^a_\rho\hat{g}+T^a_\rho\hat{g}\hat{L}^a\quad \text{and} \quad [\hat{C}_R,\hat{g}]=\hat{R}^a\hat{g}T^a_\rho+\hat{g}T^a_\rho\hat{R}^a
\end{align}



The link color charge operator is given by 
\begin{align}
    \hat{E}^a := \hat{L}^a-\hat{R}^a\,.
\end{align}


\section{Kinematical refactorization into a QRF Wilson line basis}\label{app_kinrefactor}

We briefly discuss how to compose the electric fields of two consecutive edges in the unitary refactorization, fundamental in defining Wilson lines frame (see Fig. \ref{fig:Wilson_line_reparam}). For this, 
consider two consecutive edges, oriented in the same direction. Following the arrows, we have e.g. $g_1$ as the first one and then $g_2$. We define the cumulative variables as $g_{v_1} =g_1$, $g_{v_2}=g_2 g_1$,  corresponding to path-ordered products (the first operator applied is $g_1$). For a sequence of edges stopping at node $n$ we would similarily define $g_{v_n} = g_n \dots g_1$, so that $g_n = g_{v_n} g_{v_{n-1}}^{-1}$ and $g_{v_1} = g_1$. We introduce the unitary map: 
\be
\mathfrak{U}: \H_1 \otimes \H_2 \to \H_{v_1} \otimes \H_{v_2}\,,\q\q \ket{g_1}_1 \ket{g_2}_2 \mapsto  \ket{g_1}_{v_1} \ket{g_2 g_1}_{v_2}\,,
\ee
which induces the transformation of wavefunctions $\psi_{12} (g_1, g_2)\mapsto\psi_{v_1v_2} (g_1, g_2 g_1)$ and of group operators
\be
 \mathfrak{U}^\dagger \hat g_{v_1} \mathfrak{U} = \hat g_1\,,\q\q \mathfrak{U}^\dagger \hat g_{v_2} \mathfrak{U} = \hat g_2 \hat g_1\,.
\ee
More explicitly,
\be
 \mathfrak{U} (\Id_{v_1} \otimes \hat g_{v_2})_{ij} \mathfrak{U}^\dagger =  (\hat g_1)_{kj} \otimes (\hat g_2)_{ik} 
\ee


We now examine how the exponentiated electric field operators (left and right actions) transform under 
$\mathfrak{U}$.
  \begin{itemize}
\item Right action on edge 1:
\be
 \mathfrak{U}\, V_1(h) \mathfrak{U}^\dagger \ket{g_{v_1}, g_{v_2}}  &= \mathfrak{U}\, V_1(h) \ket{g_{v_1}}_1 \ket{ g_{v_2} g_{v_1}^{-1}}_2 \notag\\
 &= \mathfrak{U}\, \ket{g_{v_1} h^{-1}}_1 \ket{g_{v_2} g_{v_1}^{-1}}_2 = \ket{ g_{v_1} h^{-1} , g_{v_2} h^{-1}} = V_{v_1}(h) \otimes V_{v_2}(h) \ket{ g_{v_1}, g_{v_2}}
\ee
\item Right action on edge 2:
\be
 \mathfrak{U}\, V_2(h) \mathfrak{U}^\dagger \ket{g_{v_1}, g_{v_2}}  &= \mathfrak{U}\, V_2(h) \ket{g_{v_1}}_1 \ket{ g_{v_2} g_{v_1}^{-1}}_2 \notag\\
 &= \mathfrak{U}\, \ket{g_{v_1}}_1 \ket{ g_{v_2} g_{v_1}^{-1} h^{-1}}_2 = \ket{g_{v_1}, g_{v_2} g_{v_1}^{-1} h^{-1} g_{v_1}}
\ee
This transformation is not a simple tensor product of actions on the $\H_{v_i}$'s.
\item Left action on edge 1:
\be
 \mathfrak{U}\, U_1(h) \mathfrak{U}^\dagger \ket{g_{v_1}, g_{v_2}}  &= \mathfrak{U}\, U_1(h) \ket{g_{v_1}}_1 \ket{g_{W} g_{v_1}^{-1} }_2 \notag\\
 &= \mathfrak{U}\, \ket{ h g_{v_1} }_1 \ket{ g_{v_2} g_{v_1}^{-1}}_2 = \ket{h g_{v_1}, g_{v_2}  g_{v_1}^{-1} h g_{v_1}}
\ee
Again, this is not a factorized action on the $\H_{v_i}$'s.
\item Left action on edge 2:
\be
 \mathfrak{U}\, U_2(h) \mathfrak{U}^\dagger \ket{g_{v_1}, g_{v_2}}  &= \mathfrak{U}\, U_2(h) \ket{g_{v_1}}_1 \ket{g_{v_2} g_{v_1}^{-1}}_2 \notag\\
 &= \mathfrak{U}\, \ket{ g_{v_1}}_1 \ket{h g_{W} g_{v_1}^{-1} }_2 = \ket{g_{v_1}, h g_{v_2}}  = U_{v_2}(h) \ket{g_{v_1}, g_{v_2}}
\ee
\end{itemize}
From the above, only $V_1$ and $U_2$ yield simple, factorized expressions under $\mathfrak{U}$. In particular the first one corresponds to a large gauge transformation, acting on all terms. The last one is a gauge transformations at the endpoint $v_2$ (eventually belonging to $\p \Sigma$). Under this small gauge transformation, the Wilson line is nicely covariant. Finally, at the intermediate node $v_1$, the relevant gauge transformation corresponds to the combined action (cf.~Eq.~\eqref{eq:gaugetransfconv} $V_2(h)\otimes U_1(h)$, which under $\mathfrak{U}$ becomes:
\be
\mathfrak{U}\,\left( V_2(h)\otimes U_1(h) \right)\mathfrak{U}^\dagger = U_{v_1}(h)\otimes \Id_{v_2}
\ee
We propose using the combinations $R_1$, $L_2$ and $L_1 - R_2$  as the effective electric field operators to be dressed. These have well-defined, local transformations under the kinematical unitary map and align with natural interpretations as generators of local gauge transformations, for the left vector fields acting on the Hilbert spaces $H_{v_i}$, and large gauge transformation (frame reorientations) for the joint action of right multiplications on all $v_i$'s factors. By contrast, attempting to study $L_1$ and $R_2$ individually would unnecessarily complicate the analysis due to their non-factorizing action.



