\section*{Appendix}
\subsection*{Appendix.A. Interim Results}\label{Appendix.A}
Let $\Gamma_3(\alpha,2)$ where $0<\alpha\leq\frac{1}{3}$ be the middle $-\alpha$ Cantor set defined by two affine maps. Here, its nested representation is given by $\Gamma_3(\alpha,2)=\cap_{n=0}^{+\infty}I_n(\alpha)$ where $I_0(\alpha)=[0,1]$ and $I_n(\alpha)$ is defined recursively  by  removing $2^{n-1}$ middle open intervals each of the length $\alpha^n$ from  $I_{n-1}(\alpha)$ $(n\in\mathbb{N}).$ We have the following interim results:
\begin{enumerate}
\item \textbf{Family Name} By construction, the Lebesgue measure is given by $\lambda(\Gamma_3(\alpha,2))=1-\sum_{n=1}^{+\infty}2^{n-1}\alpha^n=\frac{1-3\alpha}{1-2\alpha} (0<\alpha\leq\frac{1}{3}).$ Hence, we augment the "Thick Family" with $0<\alpha<\frac{1}{3}$ with the "Thin case" $\alpha=\frac{1}{3};$ and, call it the "Augmented Thick Family" with $0<\alpha\leq\frac{1}{3}.$ 

\item \textbf{2q-Ary Expansion} When $0<\alpha=\frac{p}{q}\leq\frac{1}{3}, p,q\in\mathbb{N}, (p,q)=1$, by above construction, the equality $\frac{p}{q}=\frac{2p}{2q}$, and mathematical induction, a straightforward verification shows the following 2q-Ary expansion: $$\Gamma_3(\alpha,2)=\{ x\in [0,1] | x=\sum_{n=1}^{+\infty}\frac{a_n}{(2q)^n} \ , \ a_n=0,1,\cdots,q-p-1,q+p,\cdots,2q-1\}.$$
This representation facilitates the n-Aray expansion for cases with even $q.$ Furthermore, the middle-third Cantor set has the  secondary 6-Ary expansion as $C=\{ x\in [0,1] | x=\sum_{n=1}^{+\infty}\frac{a_n}{6^n} \ , \ a_n=0,1,4,5\}.$   

\item \textbf{Proof of Theorem \ref{thm3}} We prove the Theorem in  steps (a)-(e). 
\begin{enumerate}
\item 
\textbf{Notation}
Given above recursive construction it follows that,   $\Gamma_3(\alpha,2)=\cap_{n=0}^{+\infty}I_n(\alpha)$ where $I_n(\alpha)=\cup_{k=1}^{2^n} I_{n,k}(\alpha)$ and $I_{n,k}(\alpha)=[a_{n,k}(\alpha), b_{n,k}(\alpha)], (1\leq k\leq 2^n, n\in\mathbb{N}_{0}).$
\item
\begin{lem}\label{lemA.1}
$\lambda(I_{n,k}(\alpha))=\frac{(2\alpha)^{n+1}+2(1-3\alpha)}{2^{n+1}(1-2\alpha)}: \ \ (1\leq k\leq 2^n, n\in\mathbb{N}_{0}).$
\end{lem}
\textbf{Proof.}  The case for $n=0$ is trivial. Let $n\in\mathbb{N}$ and $J_{n,k}(\alpha)$ be the middle open interval of length $\alpha^n$ removed from $I_{n-1,k}(\alpha)$ in the nested construction process i.e. $I_{n-1,k}(\alpha)=I_{n,2k-1}(\alpha)\cup J_{n,k}(\alpha)\cup I_{n,2k}(\alpha).$ Then, given, $\lambda(I_{n,2k-1}(\alpha))=\lambda(I_{n,2k}(\alpha))$ we have: $\lambda(I_{n-1,k}(\alpha))=2\lambda(I_{n,k}(\alpha))+\alpha^n.$ Consequently, we have a first order recursive relation:
$$\lambda(I_{n,k}(\alpha))=\frac{1}{2} \lambda(I_{n-1,k}(\alpha))-\frac{\alpha^n}{2}, \lambda(I_{0,1}(\alpha))=1.$$
Finally, the assertion follows by mathematical induction on $n\in\mathbb{N}$. $\Box$
\item 
\begin{lem}\label{lemA.2}
Let $\Delta_{n,k}(\alpha)=\lambda(I_{n,k}(\alpha))+\alpha^n \ \ (1\leq k\leq 2^n, n\in\mathbb{N}_{0}).$ Then, $$\Delta_{n,k}(\alpha)=\frac{(1-3\alpha)+(1-\alpha)(2\alpha)^n}{(1-2\alpha)2^n} \ \ (1\leq k\leq 2^n, n\in\mathbb{N}_{0}).$$   
\end{lem}
\textbf{Proof.} This is straightforward result from Lemma \ref{lemA.1}. $\Box$
\item 
\begin{lem}\label{lemA.3}
Let $a_{n,k}(\alpha), b_{n,k}(\alpha), (1\leq k\leq 2^n , n\in\mathbb{N}_0)$ be defined as in above recursive construction. Then:
\begin{eqnarray}
a_{0,1}(\alpha)&=&0, \nonumber\\
a_{n,k}(\alpha)&=&1_{odd}(k)\Big(a_{n-1,\frac{k+1}{2}}(\alpha) \Big)+1_{even}(k)\Big( a_{n-1,\frac{k}{2}}(\alpha)+\Delta_{n,k}(\alpha)\Big), \nonumber\\
b_{0,1}(\alpha)&=&1, \nonumber\\
b_{n,k}(\alpha)&=&1_{odd}(k)\Big(b_{n-1,\frac{k+1}{2}}(\alpha)-\Delta_{n,k}(\alpha)\Big)+1_{even}(k)\Big( b_{n-1,\frac{k}{2}}(\alpha) \Big),\nonumber\\
&&(1\leq k\leq 2^n , n\in\mathbb{N}_0). \nonumber 
\end{eqnarray}
\end{lem}
\textbf{Proof.} This is straightforward result from  definition of $\Delta_{n,k}(\alpha)$ in Lemma \ref{lemA.2}, and comparing the end points of closed intervals in the following equations:
\begin{eqnarray}
[a_{n-1,k}(\alpha),b_{n-1,k}(\alpha)]&=&I_{n-1,k}(\alpha)=I_{n,2k-1}(\alpha)\cup J_{n,k}(\alpha)\cup I_{n,2k}(\alpha)\nonumber\\
&=& [a_{n,2k-1}(\alpha),b_{n,2k-1}(\alpha)]
\cup
(b_{n,2k-1}(\alpha),a_{n,2k}(\alpha))
\cup
[a_{n,2k}(\alpha),b_{n,2k}(\alpha)],\nonumber\\
&&(1\leq k\leq 2^n , n\in\mathbb{N}_0).\nonumber
\end{eqnarray}
$\Box$
\item \textbf{Completion} Finally, by considering $0<\alpha=\frac{p}{q}\leq\frac{1}{3}$ in Lemma \ref{lemA.2} and substituting corresponding $\Delta_{n,k}$ in the equations presented in Lemma \ref{lemA.3}, the proof for the Theorem \ref{thm3} is completed. $\Box$   
\end{enumerate}
\end{enumerate}
\subsection*{Appendix.B. R Software Code}\label{Appendix.B}
The following function in R software code produces the end points of the intervals of the recursive representation of "Augmented Thick Family" $\Gamma_3(\frac{p}{q},2)$ for given pair $(n,k): 1\leq k\leq 2^n, n\in\mathbb{N}.$ It presents two examples of calculations one for the thin Cantor set and another for the thick Cantor set:

\begin{verbatim}
## ========================================================================================
##  Recursive evaluator for lower endpoint a_{n,k}(p/q)
## ========================================================================================
a_nk <- local({
  ## simple memorization (saves repeated work)
  cache <- new.env(parent = emptyenv())
  f <- function(n, k, p, q) {
    if (n == 0L) {                     # base level
      if (k != 1L) stop("For n = 0 you must take k = 1")
      return(0)
    }
    if (k < 1 || k > 2^n)
      stop("k must satisfy 1 <= k <= 2^n")
    ## build a unique key for memorisation
    key <- paste(n, k, p, q, sep = "-")
    if (exists(key, envir = cache, inherits = FALSE))
      return(cache[[key]])
    r <- p / q                         # the ratio p/q
    ## recursive step
    if (k %% 2L == 1L) {               # k is odd
      val <- f(n - 1L, (k + 1L) / 2L, p, q)
    } else {                           # k is even
      prev <- f(n - 1L, k / 2L, p, q)
      term <- ((1 - 3 * r) + (1 - r) * (2 * r)^n) /((1 - 2 * r) * 2^n)
      val <- prev + term
    }
    cache[[key]] <- val                # store and return
    val
  }
  f
})

## ========================================================================================
##  Recursive evaluator for upper endpoint  b_{n,k}(p/q)
## ========================================================================================

b_nk <- local({
  cache <- new.env(parent = emptyenv())  #memorization
  f <- function(n, k, p, q) {
    if (n == 0L) {                  # base case
      if (k != 1L) stop("For n = 0 you must take k = 1")
      return(1)
    }
    if (k < 1L || k > 2L^n)
      stop("k must satisfy 1 <= k <= 2^n")
    key <- paste(n, k, p, q, sep = "-")
    if (exists(key, envir = cache, inherits = FALSE))
      return(cache[[key]])
    r    <- p / q
    term <- ((1 - 3 * r) + (1 - r) * (2 * r)^n) /((1 - 2 * r) * 2^n)
    ## recursive step
    if (k %% 2L) {                               # k  is odd
      val <- f(n - 1L, (k + 1L) %/% 2L, p, q) - term
    } else {                                     # k is even
      val <- f(n - 1L, k %/% 2L, p, q)
    }
    cache[[key]] <- val
    val
  }
  f
})

## ========================================================================================
##  Intervals Endpoints Calculator  
## ========================================================================================
EndpointCalculator <- function(n, p, q) {
  ## ---------- base‑level endpoints ----------
  a0 <- a_nk(0L, 1L, p, q)
  b0 <- b_nk(0L, 1L, p, q)
  ## keep the original “too‑large” denominator
  denom <- q^(n + 1L)
  ## ---------- level‑n endpoints ----------
  res1 <- sapply(1:2^n, function(k) a_nk(n, k, p, q))
  res2 <- sapply(1:2^n, function(k) b_nk(n, k, p, q))
  num1 <- c(a0 * denom, round(res1 * denom))
  num2 <- c(b0 * denom, round(res2 * denom))
  ## ---------- LABELS (divide out one factor of q) ----------
  display_denom <- denom / q   #  q^(n+1) / q  ->  q^n
  col_labs       <- paste0("k=", 0:2^n)
  fractions1     <- paste0(num1 / q, "/", display_denom)
  fractions2     <- paste0(num2 / q, "/", display_denom)
  ## ---------- NEW ROW ----------
  combo <- paste0("[", fractions1, ",", fractions2, "]")
  out1   <- rbind("a_(n,k)(α)"              = fractions1,
                 "b_(n,k)(α)"              = fractions2,
                 "[a_(n,k)(α),b_(n,k)(α)]" = combo)
  colnames(out1) <- col_labs
  out2<-t(out1)
  return(out2)
}

## ========================================================================================
##  Examples
## ========================================================================================
## Example (1) : Thin Cantor Set
EndpointCalculator(n=2, p=1, q=3)
#      a_(n,k)(α) b_(n,k)(α) [a_(n,k)(α),b_(n,k)(α)]
# k=0 "0/9"      "9/9"      "[0/9,9/9]"            
# k=1 "0/9"      "1/9"      "[0/9,1/9]"            
# k=2 "2/9"      "3/9"      "[2/9,3/9]"            
# k=3 "6/9"      "7/9"      "[6/9,7/9]"            
# k=4 "8/9"      "9/9"      "[8/9,9/9]" 

## Example (2) : Thick Cantor Set
EndpointCalculator(n=2, p=1, q=4)
#      a_(n,k)(α) b_(n,k)(α) [a_(n,k)(α),b_(n,k)(α)]
# k=0 "0/16"     "16/16"    "[0/16,16/16]"         
# k=1 "0/16"     "2.5/16"   "[0/16,2.5/16]"        
# k=2 "3.5/16"   "6/16"     "[3.5/16,6/16]"        
# k=3 "10/16"    "12.5/16"  "[10/16,12.5/16]"      
# k=4 "13.5/16"  "16/16"    "[13.5/16,16/16]"  
\end{verbatim}


