    \title[Cond. for Large-Sample Majorization in Terms of $\alpha$-$z$ Rel. Entropies]{Conditions for Large-Sample Majorization of Pairs of Flat States in Terms of $\alpha$-$z$ Relative Entropies}

    \author{Frits Verhagen\textsuperscript{1}, Marco Tomamichel\textsuperscript{1,2}\\
        and Erkka Haapasalo\textsuperscript{1}}
	\address{1. Centre for Quantum  Technologies,  National University of Singapore\\
