    and 
    \begin{equation}\label{eq:DT}
        \hat{D}^\T(\rho\|\sigma):=-\log\left(\max_{i=1,\ldots,n}|\braket{\alpha_i}{\beta_i}|^{2}\right). 
    \end{equation}
    When $\alpha\in(0,1)$, the $\hat{D}_{\alpha,z}$ coincide with the $\alpha$-$z$ relative entropies $D_{\alpha,z}$ as in \eqref{eq:alphazdivergence}, when evaluated on pairs of states in $\mc F$, except for a different prefactor in front of the $\log$ for technical reasons. Since the $D_{\alpha,z}$ satisfy DPI for $\alpha\in(0,1)$, $z\geq\max\{\alpha,1-\alpha\}$, the same holds for $\hat{D}_{\alpha,z}$, where  we use the continuity of $\hat{D}_{\alpha,z}$ in $\alpha$ to establish the DPI when $\alpha=0,1$. $\hat{D}^\T$ is the point-wise limit $z\rightarrow\infty$ of $\hat{D}_{\alpha,z}$, for any $\alpha\in[0,1]$ as one may rather easily verify. As a consequence, also $\hat{D}^\T$ satisfies DPI. 

    A result by Uhlmann \cite{Uhlmann1985} states that a pair of pure states $(\ketbrar{\alpha},\ketbrar{\beta})$ majorizes another pair of pure states $(\ketbrar{\alpha'},\ketbrar{\beta'})$ if and only if $|\braket{\alpha}{\beta}|\leq|\braket{\alpha'}{\beta'}|$. Note that in the expressions \eqref{eq:alphazexplicit} and \eqref{eq:DT}, the fidelity between pure states $|\braket{\alpha_i}{\beta_i}|$ also makes an appearance. 

    To state our remaining results, we introduce the following two additional properties for a pair of states $(\rho,\sigma)\in\mc F$: 
    \begin{equation}\label{eq:pu1}
        |\braket{\alpha_i}{\beta_i}|<1\quad\forall\;i\in\{1,\ldots,n\}, 
    \end{equation}
    and
    \begin{equation}\label{eq:pu2}
        \exists\;i\in\{1,\ldots,n\}\ \text{s.t.}\ \braket{\alpha_i}{\beta_i}=0\ \text{and}\ \ket{\alpha_i},\ket{\beta_i}\neq0.  
    \end{equation}
    Note that \eqref{eq:pu1} means that $\rho$ and $\sigma$ are non-parallel.

    The following Theorem gives sufficient and almost necessary conditions for exact large-sample and catalytic majorization. This result is established at the end of Section \ref{sec:spectrum}.  

    \begin{theorem}\label{thm:LS}
        Let $(\rho,\sigma)$, $(\rho',\sigma')$ be two pairs of states in $\mc F$, where additionally $(\rho,\sigma)$ satisfies \eqref{eq:pu2}. If 
        \begin{align}
            \label{eq:LScondition1}&\hat{D}_{\alpha,z}(\rho\|\sigma)>\hat{D}_{\alpha,z}(\rho'\|\sigma')\ \text{when}\ \alpha\in[0,1],\ z\geq\max\{\alpha,1-\alpha\}, &\\
            \label{eq:LScondition2}&\hat{D}^\mathbb{T}(\rho\|\sigma)>\hat{D}^\mathbb{T}(\rho'\|\sigma'), 
        \end{align}            
        then $(\rho,\sigma)$ majorizes $(\rho',\sigma')$ both in the large-sample setting and in the catalytic setting, with a pair of catalyst states in $\mc F$. For the catalytic result, $(\rho,\sigma)$ does not need to satisfy \eqref{eq:pu2}. 

        Conversely, if $(\rho,\sigma)$ majorizes $(\rho',\sigma')$ in large samples or catalytically, then the above inequalities \eqref{eq:LScondition1} and \eqref{eq:LScondition2} hold non-strictly. 
    \end{theorem}

    Theorem \ref{thm:approximateC} on asymptotic catalytic majorization presented in the Introduction can be extended to the following result that also gives conditions for asymptotic large-sample majorization. The proof can be found in Section \ref{sec:approximate}. 

    \begin{theorem}\label{thm:approximateLS}
        Let $(\rho,\sigma)$, $(\rho',\sigma')$ be two pairs of states in $\mc F$, where $\rho$ and $\sigma$ satisfy \eqref{eq:pu1} and $\rho'$, $\sigma'$ do not commute. Consider the following statements: 
        \begin{enumerate}[(i)]
            \item $\hat{D}_{\alpha,z}(\rho\|\sigma)\geq \hat{D}_{\alpha,z}(\rho'\|\sigma')$ when $\alpha\in(0,1)$, $z>\max\{\alpha,1-\alpha\}$. 
            \item For each $\varepsilon>0$, there exist a state $\rho'_\varepsilon$ such that $F(\rho'_\varepsilon,\rho')\geq1-\varepsilon$, and a quantum channel $\mc{C}_{\varepsilon,n}$ for $n$ large enough such that $\mc{C}_{\varepsilon,n}(\rho^{\otimes n})=(\rho'_\varepsilon)^{\otimes n}$ and $\mc{C}_{\varepsilon,n}(\sigma^{\otimes n})=(\sigma')^{\otimes n}$. 
            \item For each $\varepsilon>0$, there exist a state $\rho'_\varepsilon$ such that $F(\rho'_\varepsilon,\rho')\geq1-\varepsilon$, a quantum channel $\mc C_\varepsilon$, and a catalyzer pair $(\tau_\varepsilon$, $\omega_\varepsilon)\in\mc F$ such that 
            \begin{equation}
                \mc C_\varepsilon(\rho\otimes\tau_\varepsilon)=\rho'_\varepsilon\otimes\tau_\varepsilon\quad\text{and}\quad \mc C_\varepsilon(\sigma\otimes\omega_\varepsilon)=\sigma'\otimes\omega_\varepsilon. 
            \end{equation}
            Statements (i) and (iii) are equivalent. If $(\rho,\sigma)$ furthermore satisfies \eqref{eq:pu2}, then (i), (ii) and (iii) are equivalent. 
        \end{enumerate}        
    \end{theorem}

    It might be possible to relax the assumption \eqref{eq:pu2} in Theorems \ref{thm:LS} and \ref{thm:approximateLS}, but this requires the study of a slightly different semiring. We will address this issue later in the Discussion. Note that, for the results on large-sample majorization, Theorem \ref{thm:approximateLS} requires $(\rho,\sigma)$ to satisfy both \eqref{eq:pu1} and \eqref{eq:pu2}, while Theorem \ref{thm:LS} only explicitly requires \eqref{eq:pu2}. However, \eqref{eq:pu1} is automatically satisfied for $(\rho,\sigma)$ in Theorem \ref{thm:LS} since the strict inequality \eqref{eq:LScondition2} implies \eqref{eq:pu1}. 

    We say that, given pairs $(\rho,\sigma)$ and $(\rho',\sigma')$, $r\geq0$ is an {\it achievable conversion rate} if $r\leq\liminf_{n\to\infty}m_n/n$ where $(m_n)_n$ is a sequence of natural numbers such that $\big(\rho^{\otimes n},\sigma^{\otimes n}\big)$ majorizes $\big((\rho')^{\otimes m_n},(\sigma')^{\otimes m_n}\big)$ for large enough $n\in\N$. The {\it optimal conversion rate} $r\big((\rho,\sigma)\to(\rho',\sigma')\big)$, namely the supremum of all the achievable conversion rates, is given by the following result, which is shown in Section \ref{sec:rate}.  

    \begin{theorem}\label{thm:rates}
        For pairs $(\rho,\sigma)$ and $(\rho',\sigma')$ of states in $\mc F$, the optimal conversion rate from $(\rho, \sigma)$ to $(\rho', \sigma')$ is %$r\big((\rho,\sigma)\to(\rho',\sigma')\big)$ equals 
        \begin{align}
        &r\big((\rho,\sigma)\to(\rho',\sigma')\big) \notag\\
        &\quad=\inf\left\{\,\frac{D_{\alpha,z}(\rho\|\sigma)}{D_{\alpha,z}(\rho'\|\sigma')}\,\middle|\,\alpha\in(0,1),z>\max\{\alpha,1-\alpha\}\,\right\}&\label{eq:rate1}\\
        &\quad=\min\left\{\,\frac{\hat{D}_{\alpha,z}(\rho\|\sigma)}{\hat{D}_{\alpha,z}(\rho'\|\sigma')}\,\middle|\,\alpha\in[0,1],z\geq\max\{\alpha,1-\alpha\}\,\right\}\cup\left\{\frac{\hat{D}^\T(\rho\|\sigma)}{\hat{D}^\T(\rho'\|\sigma')}\right\}.&\label{eq:rate2} 
        \end{align}
    \end{theorem}

    %We will actually subsequently prove that the optimal rate is a {\it minimum} over $\mathbb{D}(\rho\|\sigma)/\mathbb{D}(\rho'\|\sigma')$ where $\mathbb{D}$ is within the set $\hat{D}_{\alpha,z}$ for $0\leq\alpha\leq 1$ and $z\geq\{\alpha,1-\alpha\}$ and $\hat{D}^\T$. 
    The additional relative entropies $\hat{D}_{\alpha,z}$ for $\alpha=0,1$ and the limit point $\hat{D}^\T$ make the set of relative entropies appearing in \eqref{eq:rate2} compact in the topology of pointwise convergence \cite[Proposition 8.5]{fritz2022}. This is why in \eqref{eq:rate2} we are able to take the minimum, instead of taking the infimum when using the original definition of the $\alpha$-$z$ relative entropies $D_{\alpha,z}$ in \eqref{eq:rate1}. 

