    \end{equation}
    for $m\in\N$ large enough 

    We are finally able to show that the above $(A,B)$ is a power universal. For this, consider pairs $(A_1,B_1),(A_2,B_2)\in V_{\rm e.o.}$ such that $(A_1,B_1)\succeq(A_2,B_2)$ or $(A_2,B_2)\succeq(A_1,B_1)$. This clearly means especially that $\tr[A_1]=\tr[A_2]$ and $\tr[B_1]=\tr[B_2]$. Define $A':=\tr[A_2]^{-1}A_2$ and $B':=\tr[B_2]^{-1}B_2$. Since we have already proven that, for $m\in\N$ large enough, we have \eqref{eq:apu2}, we now have
    \begin{align}
    (A_1,B_1)\boxtimes(A,B)^{\boxtimes m}&=(A_1\otimes A^{\otimes m},B_1\otimes B^{\otimes m})\\
    &\succeq\big(\tr[A_1]A^{\otimes m},\tr[B_1]B^{\otimes m}\big)\\
