    \end{proof}

    \subsection{Finding the monotone homomorphisms and derivations}\label{sec:spectrum}
    We fix a monotone homomorphism $\Phi:V_{*}\rightarrow\K$, where $V_{*}\in\{V_{\rm m.r.},V_{\rm e.o.}\}$ and $\K\in\{\R_+,\R_+^{\rm op},\T\R_+,\T\R_+^{\rm op}\}$. Since $\Phi$ reduces to one of the known homomorphisms studied previously when restricted to classical pairs, we may associate to it the parameter $\alpha$ and character $C$ in the temperate case, or the parameter $\beta$ in the tropical case, as derived in \cite{farooq2024,verhagen2024} and explained in more detail later. In the following calculations and proofs we will repeatedly use vectors
    \begin{equation}\label{eq:anglevectors}
    |\psi(\theta)\rangle:=\cos{\theta}\,|0\rangle+\sin{\theta}\,|1\rangle\in\C^2,\qquad\theta\in[0,2\pi),
    \end{equation}
    where $\{|0\rangle,|1\rangle\}$ is some fixed orthonormal basis of $\C^2$. The next Proposition shows that a new parameter $z$ appears due to the quantum nature of the states. 

    % One can show that any pair of $2$-dimensional projectors of rank $1$ is equivalent to the following pair: 
    % \begin{equation}\label{eq:canonical}
    %     \left(\left(\begin{array}{cc}
    %         1&0\\
    %         0&0\end{array}\right),\left(\begin{array}{cc}
    %         \cos^2\theta&\cos\theta\sin\theta\\
    %         \cos\theta\sin\theta&\sin^2\theta\end{array}\right)\right), 
    % \end{equation}
    % for some $\theta\in[0,\pi/2]$. The angle $\theta$ is the angle between the $1$-dimensional projection subspaces of the projectors and $\cos^2\theta$ is the fidelity $|\braket{\alpha}{\beta}|^2$. The problem of identifying all monotones now reduces to finding the value a monotone takes on pairs like the above, and furthermore this value only depends on $\theta$. 

    \begin{proposition}\label{prop:z}
        Let $\Phi:V_{*}\rightarrow\K$ be a nondegenerate monotone homomorphism, where $V_{*}\in\{V_{\rm m.r.},V_{\rm e.o.}\}$ and $\K\in\{\R_+,\R_+^{\rm op},\T\R_+,\T\R_+^{\rm op}\}$. There exists $z\in\R$ such that 
        \begin{equation}
            \Phi(\ketbrar{\alpha},\ketbrar{\beta})=|\braket{\alpha}{\beta}|^{2z}
        \end{equation}
        for all normalized $\ket{\alpha},\ket{\beta}\in\Hil$ such that $\braket{\alpha}{\beta}\neq0$, and $\Hil$ is a Hilbert space. 
    \end{proposition}

    \begin{proof}
        Fix orthonormal vectors $\ket{e_1}$ and $\ket{e_2}$ that span the subspace $\mc M$ where $\ket{\alpha}$ and $\ket{\beta}$ reside. For any $\ket{\alpha^\perp}\in\mc M$ perpendicular to $\ket{\alpha}$ we have 
        \begin{equation}
            |\braket{\alpha}{\beta}|^2+|\braket{\alpha^\perp}{\beta}|^2=1. 
        \end{equation}
        Hence 
        \begin{equation}
            |\braket{\alpha}{\beta}|=\cos\theta,\quad|\braket{\alpha^\perp}{\beta}|=\sin\theta,
        \end{equation}
        for some $\theta\in[0,\pi/2]$. By multiplying with an appropriate phase, we may choose $\ket{\alpha^\perp}$ such that 
        \begin{equation}
            \braket{\alpha}{\beta}\braket{\beta}{\alpha^\perp}=\cos\theta\sin\theta. 
        \end{equation}
        Via the unitary operation defined by $\ket{\alpha}\mapsto\ket{e_1},\ket{\alpha^\perp}\mapsto\ket{e_2}$, the pair $(\ketbra{\alpha}{\alpha},\ketbra{\beta}{\beta})$ is equivalent to the pair 
    \begin{equation}\label{eq:pairstandardform}
        (\ketbra{e_1}{e_1},\cos^2\theta\ketbra{e_1}{e_1}+\cos\theta\sin\theta\ketbra{e_1}{e_2}+\cos\theta\sin\theta\ketbra{e_2}{e_1}+\sin^2\theta\ketbra{e_2}{e_2}). 
    \end{equation}
    From this, we see that $\Phi(\ketbrar{\alpha},\ketbrar{\beta})$ only depends on the fidelity $\cos^2\theta=|\braket{\alpha}{\beta}|^2$. Therefore, we can define $\varphi:(0,1]\rightarrow\R$, 
    \begin{equation}
        \varphi(x):=\Phi(\ketbrar{\alpha},\ketbrar{\beta}), 
    \end{equation}
    where $\ket{\alpha},\ket{\beta}$ are any vectors such that $|\braket{\alpha}{\beta}|^2=x$. Note that 
    \begin{equation}
        (\ketbrar{\alpha_1},\ketbrar{\beta_1})\boxtimes(\ketbrar{\alpha_2},\ketbrar{\beta_2})=(\ket{\alpha_1}\otimes\ket{\alpha_2}\bra{\alpha_1}\otimes\bra{\alpha_2},\ket{\beta_1}\otimes\ket{\beta_2}\bra{\beta_1}\otimes\bra{\beta_2}) 
    \end{equation}
    and 
    \begin{equation}
        |(\bra{\alpha_1}\otimes\bra{\alpha_2})(\ket{\beta_1}\otimes\ket{\beta_2})|^2=|\braket{\alpha_1}{\beta_1}|^2|\braket{\alpha_2}{\beta_2}|^2. 
    \end{equation}
    Thus, by multiplicativity of $\Phi$, the function $\phi$ is multiplicative as well, i.e. 
    \begin{equation}
        \phi(xy)=\phi(x)\phi(y)\text{ for all }x,y\in(0,1]. 
    \end{equation}    
    %Write $\ket{\psi(\theta)}:=\cos\theta\ket{0}+\sin\theta\ket{1}$ for any $\theta\in[0,2\pi]$ for a fixed orthonormal basis $\{\ket{0},\ket{1}\}\subset\C^2$.
    Using Proposition \ref{propo:Uhlmann}, for any $\ket{\alpha},\ket{\beta}$ such that 
    \begin{equation}
        |\braket{\alpha}{\beta}|^2\geq\frac{1}{2}=|\braket{0}{\psi(\pi/4)}|^2, 
    \end{equation}
    where $|\psi(\pi/4)\rangle$ is defined as in \eqref{eq:anglevectors}, we have 
    \begin{equation}
        (\,1\;\;1\,)\preceq(\,\ketbrar{\alpha}\;\;\ketbrar{\beta}\,)\preceq(\,\ketbrar{0}\;\;\ketbrar{\psi(\pi/4)}\,). 
    \end{equation}
    Hence for all $x\in[1/2,1]$, we have $\varphi(x)\leq1$ if $\K=\R_+^{\rm op},\T\R_+^{\rm op}$, and $\varphi(x)\leq\varphi(1/2)$ if $\K=\R_+,\T\R_+$. Therefore, $\varphi$ is bounded from above on a set of positive measure, which establishes that $\varphi$ is a regular solution of the multiplicative version of Cauchy's Functional Equation \cite[Chapter 3, Proposition 6]{Aczel1989}: there exists $z\in\R$ such that $\varphi(x)=x^z$ or $\varphi$ vanishes everywhere. The latter case yields a degenerate homomorphism.      
    \end{proof}

    Using the additivity and multiplicativity of $\Phi$ in the temperate cases, we can decompose $\Phi(A,B)$, where $(A,B)\in S_*$ as follows: 
    \begin{equation}\label{eq:decompositiontemperate}
        \Phi(A,B)=\sum_{i=1}^n\Phi(p_i\ q_i)\Phi(\ketbrar{\alpha_i},\ketbrar{\beta_i}), 
    \end{equation}
    and similarly for the tropical case: 
    \begin{equation}\label{eq:decompositiontropical}
        \Phi(A,B)=\max_{i=1,\ldots,n}\Phi(p_i\ q_i)\Phi(\ketbrar{\alpha_i},\ketbrar{\beta_i}). 
    \end{equation}
    Note that if $\ket{\alpha_i},\ket{\beta_i}$ are orthogonal, then $(\ketbrar{\alpha_i}\ \ketbrar{\beta_i})$ is not part of the semiring $S_*$. However, with abuse of notation, we may take $\Phi(\ketbrar{\alpha_i},\ketbrar{\beta_i})=0$, which is allowed according to results established in \cite{verhagen2024}. Since all of the terms in the summation above are known by the previous Proposition and results from \cite{farooq2024,verhagen2024}, the value of $\Phi(A,B)$ for any $(A,B)\in S_*$ is also known. 

    In the following, we will exclude certain ranges that the $\alpha$ and $z$ parameters may be in by providing counterexamples to the monotonicity property. Some calculations will apply to both $V_{\rm m.r.}$ and $V_{\rm e.o.}$, and some to only the former, which is a larger set. We will extensively use the following facts established in \cite{farooq2024,verhagen2024} when we evaluate $\Phi$ on a commuting pair, i.e.,\ a pair $(A,B)$ such as in \eqref{eq:Vpair2} where the component spaces $\hil_i\simeq\C$: When $\mb K=\R_+^{\rm op}$, there is $\alpha\in[0,1]$ such that
    \begin{equation}\label{eq:clform}
    \Phi(A,B)=\left\{\begin{array}{ll}
    \sum_{i=1}^n p_i^\alpha q_i^{1-\alpha},&0<\alpha<1,\\
    \sum_{i:p_i>0} q_i,&\alpha=0,\\
    \sum_{i:q_i>0} p_i,&\alpha=1.
    \end{array}\right.
    \end{equation}
    The two latter cases above correspond to the character $C=\{1,2\}$, i.e. only those $i$ for which $p_i>0$ and $q_i>0$ are summed over. Additionally, for $\alpha=0$ and $C=\{2\}$ there is a degenerate monotone homomorphism similar as the second one above, but where we sum over all $i=1,\ldots,n$. Similarly, for $\alpha=1$ and $C=\{1\}$ there is a degenerate monotone homomorphism similar to the third one above where we sum over all $i=1,\ldots,n$. When $\mb K=\R_+$, there is $\alpha\leq 0$ or $\alpha\geq 1$ such that, when $\alpha\notin\{0,1\}$, the form of $\Phi$ restricted to a classical $(A,B)$ has the same form as in the first line of \eqref{eq:clform}, and when $\alpha\in\{0,1\}$ we only have the above degenerate options. When $\mb K=\T\R_+^{\rm op}$, the only form $\Phi$ can take on a classical pair $(A,B)$ is the highly degenerate $\Phi(A,B)=1$ when $[(A,B)]\neq 0$ and $\Phi(0,0)=0$. However, as follows from \eqref{eq:decompositiontropical}, in our semiring, the new parameter $z$ makes the extension of this homomorphism unique and nondegenerate. When $\mb K=\T\R_+$, we know that there is $\beta\neq0$ such that, for the above classical pair $(A,B)$,
    \begin{equation}
    \Phi(A,B)=\max_{1\leq i\leq n}\left(\frac{p_i}{q_i}\right)^\beta.
    \end{equation}
    Note that we need all the entries $p_i$ and $q_i$ to be non-zero for this formula and, indeed, if $q_i=0$ for some $i$ such that $p_i>0$, we cannot define this homomorphism in the classical case. We will show later that this classical homomorphism has no extension in $S_{\rm e.o.}$.

    Considering the quantum channel arising from the PVM by measuring in the $\ket{0},\ket{1}$ basis, we have the following majorization relation for all $\theta\in[0,\pi/2]$: 
    \begin{equation}
    \label{eq:alphazrelationship1}
        \left(\,\ketbrar{\psi(\pi/4)},\ketbrar{\psi(\theta)}\,\right)\succeq\left(\begin{array}{cc}
            1/2&\cos^2\theta\\
            1/2&\sin^2\theta
        \end{array}\right), 
    \end{equation}
    where $|\psi(\theta)\rangle$ are defined as in \eqref{eq:anglevectors}. Note that the RHS is not in $V_{\rm e.o.}$ when $\theta=0,\pi/2$. 

    Let us consider the case $\mb K=\R_+^{\rm op}$ first and assume that $\Phi$ is associated to the parameter $\alpha\in[0,1]$ when restricted to a classical pair. Due to Proposition \ref{propo:Uhlmann}, we immediately see that the parameter $z$ established above must be non-negative now. It follows by monotonicity that 
    \begin{equation}
    \label{eq:alphazrelationship2}
        (\cos(\theta-\pi/4))^{2z}\leq\frac{1}{2^\alpha}[(\cos\theta)^{2-2\alpha}+(\sin\theta)^{2-2\alpha}], 
    \end{equation}
    for all $\theta\in(0,\pi/2)$. By switching around the two states in the pair on the LHS of \eqref{eq:alphazrelationship1}, we have similarly
    \begin{equation}
    \label{eq:alphazrelationship3}
        (\cos(\theta-\pi/4))^{2z}\leq\frac{1}{2^{1-\alpha}}[(\cos\theta)^{2\alpha}+(\sin\theta)^{2\alpha}]. 
    \end{equation}    
    Assume $\alpha\neq0,1$. Taking the limit $\theta\rightarrow\pi/2$ in \eqref{eq:alphazrelationship2} we find $\frac{1}{2^z}\leq\frac{1}{2^\alpha}$, which is equivalent to $z\geq\alpha$. Analogously, taking the limit $\theta\rightarrow\pi/2$ in \eqref{eq:alphazrelationship3} we find $z\geq1-\alpha$. Hence $z\geq\max\{\alpha,1-\alpha\}$. The remaining cases $\alpha=0,1$ will be considered for the semiring $S_{\rm m.r.}$ later on. 

    For $\K=\R_+$: We know that $\alpha\leq0$ or $\alpha\geq1$, and $z\leq0$. Now \eqref{eq:alphazrelationship2}, \eqref{eq:alphazrelationship3} hold with the inequality reversed. Assume $\alpha>1$. Taking the limit $\theta\rightarrow\pi/2$ in \eqref{eq:alphazrelationship2} we find that the LHS converges to $\frac{1}{2^z}$, and the RHS diverges to positive infinity, leading to a contradiction. Analogously, when $\alpha<0$, taking the limit $\theta\rightarrow\pi/2$ in \eqref{eq:alphazrelationship3} leads to a contradiction. The remaining cases $\alpha=0,1$ will be considered for the semiring $S_{\rm m.r.}$ later on.  

    For $\K=\T\R_+$: We know that $z\leq0$. Now \eqref{eq:alphazrelationship1} implies 
    \begin{equation}
    \label{eq:TR+}
        (\cos(\theta-\pi/4))^{2z}\geq\frac{1}{2^\beta}\max\{(\cos\theta)^{-2\beta},(\sin\theta)^{-2\beta}\}. 
    \end{equation}
    Assume $\beta>0$. Then for $\theta$ restricted to the smaller interval $[\pi/4,\pi/2)$ 
    \begin{equation}
        (\cos(\theta-\pi/4))^{2z}\geq\frac{1}{2^\beta}(\cos\theta)^{-2\beta}. 
    \end{equation}
    In the limit $\theta\rightarrow\pi/2$ the LHS converges to $\frac{1}{2^z}$ and the RHS diverges to positive infinity, leading to a contradiction. When $\beta<0$, an analogous argument where we switch around the two states on the LHS of \eqref{eq:alphazrelationship1} leads to a contradiction. Hence $\beta=0$. In the case of the semiring $S_{\rm m.r.}$, we will show next that the remaining case $\beta=0$ leads to a degenerate homomorphism. 

    We now only consider the set $V_{\rm m.r.}$ and set $\alpha=0$ for the temperate cases and $\beta=0$ for the tropical cases. Since the calculations for $\alpha=1$ are analogous, we will omit these. A preparation channel establishes the following majorization relation: 
    \begin{equation}
        \left(\begin{array}{cc}
            1/2&1/2\\
            1/2&0\\
            0&1/2
        \end{array}\right)\succeq\left(\begin{array}{cc}
            1/2&1/2\\
            1/2\ketbrar{0}&1/2\ketbrar{\psi(\pi/4)}
        \end{array}\right). 
    \end{equation}
    Recall the representation \eqref{eq:matrixform} of the elements of the semiring. Hence for $\R_+$, we have the inequality 
    \begin{equation}
    \label{eq:zrelationship1}
        \left\{\begin{array}{ll}
            1&\text{if }C=\{2\}\\
            1/2&\text{if }C=\{1,2\}
        \end{array}\right.\geq\frac{1}{2}+\frac{1}{2}\frac{1}{2^z}, 
    \end{equation}
    where $C$ is the character of $\Phi$, and for $\T\R_+$ the inequality 
    \begin{equation}
    \label{eq:zrelationship2}
        1\geq\max\left\{1,\frac{1}{2^z}\right\}, 
    \end{equation}
    with the reversed inequalities in the oppositely ordered semirings. 

    For $\R_+$: We know $z\leq0$. Then \eqref{eq:zrelationship1} implies that $z=0$ when $C=\{2\}$ and leads to a contradiction when $C=\{1,2\}$. The former case gives us the degenerate homomorphism $\Phi^{(2)}(A,B):=\Tr[B]$ (and analogously $\Phi^{(1)}(A,B):=\Tr[A]$ when $\alpha=1$). 

    For $\R_+^{\rm op}$: We know $z\geq0$. Then \eqref{eq:zrelationship1} with the inequality reversed implies that $z=0$ when $C=\{2\}$. When $C=\{1,2\}$, it does not lead to a contradiction. Then, a majorization relation analogous to \eqref{eq:alphazrelationship1} with the two states on the LHS switched around and $\theta=\pi/2$ gives $\frac{1}{2^z}\leq\frac{1}{2}$. Hence $z\geq1$. This is just the ``regular" $\alpha$-$z$-homomorphism. 

    For $\T\R_+$: We know $z\leq0$, and together with \eqref{eq:zrelationship2} this implies $z=0$. Hence we get the degenerate homomorphism that is equal to $1$ everywhere. 

    Let $\Delta:S_{\rm m.r.}\rightarrow\R$ be a monotone derivation at $\Phi^{(2)}$. We will show that $\Delta$, up to interchangeability, vanishes everywhere, and the same conclusion will hold for any derivation at $\Phi^{(1)}$. Since all monotone derivations, up to interchangeability, in the classical minimal restrictions semiring vanish everywhere and $\Delta$ reduces to one of these when restricted to this semiring, we deduce that $\Delta$ vanishes on all classical pairs. Then, using monotonicity and the Leibniz rule, the majorization relations 
    \begin{equation}
        (\Tr[A],\Tr[B])\preceq(A,B),\quad(A,B)\boxplus(1\,1)\preceq\left(\begin{array}{cc}
            1&1\\
            \Tr[A]&0\\
            0&\Tr[B]
        \end{array}\right), 
    \end{equation}    
    for any $(A,B)\in S_{\rm m.r.}$ imply that $\Delta$ vanishes on $S_{\rm m.r.}$. 

    The previous calculations and the decompositions \eqref{eq:decompositiontemperate}, \eqref{eq:decompositiontropical} now give a full characterization of the nondegenerate monotone homomorphisms and derivations of $S_{\rm m.r.}$. For $\K=\R_+$ and $\K=\T\R_+$, there are no nondegenerate monotone homomorphisms. For $\K=\R_+^{\rm op}$ they are 
    \begin{equation}\label{eq:temperate}
        \Phi_{\alpha,z}(A,B):=\sum_{i=1}^n(p_i)^\alpha(q_i)^{1-\alpha}|\braket{\alpha_i}{\beta_i}|^{2z}=\Tr\left[B^{\frac{\alpha-1}{2z}}A^{\frac{\alpha}{z}}B^{\frac{\alpha-1}{2z}}\right], 
    \end{equation}
    for all $\alpha\in[0,1]$ and $z\geq\max\{\alpha,1-\alpha\}$. For $\K=\T\R_+^{\rm op}$, there is only one, namely 
    \begin{equation}\label{eq:tropical}
        \Phi^\T(A,B):=\max_{i=1,\ldots,n}|\braket{\alpha_i}{\beta_i}|^{2}=\|({\rm supp}\,A)({\rm supp}\,B)\|_\infty^2, 
    \end{equation}
    where $\|\cdot\|_\infty$ is the operator norm and, e.g.,\ ${\rm supp}\,A$ is the support projection of the positive semidefinite $A$. Furthermore, there are no derivations at the degenerate homomorphisms. 

    For the semiring $S_{\rm e.o.}$ we do not have a complete picture: we know that all monotone homomorphisms associated with $S_{\rm m.r.}$ discussed above are also associated with $S_{\rm e.o.}$, but there might be more. Namely, it is still an open question whether $S_{\rm e.o.}$ has monotone homomorphisms of the same form as \eqref{eq:temperate} for the parameters $\alpha=0,1$ and $z\leq1$. Additionally, there might exist monotone derivations at $\alpha=0,1$ and $z=0$. 

    The homomorphisms of $S_{\rm m.r.}$ given by \eqref{eq:temperate} and \eqref{eq:tropical} give rise to the relative entropies defined in \eqref{eq:alphazexplicit}, \eqref{eq:DT}. Note that the sign of the prefactors in front of the $\log$ ensure that DPI is satisfied. The exact form of the prefactors furthermore ensure that $\hat D^\T$ is indeed the pointwise limit $z\rightarrow\infty$ of any of the $\hat{D}_{\alpha,z}$. Since DPI is known to be satisfied for the $\alpha$-$z$ relative entropies (and hence also for our version with a different prefactor) when $\alpha\in(0,1)$ and $z\geq\max\{\alpha,1-\alpha\}$, the pointwise limits $\hat D^\T$ and $\hat D_{\alpha,z}$ for $\alpha=0,1$, $z\geq1$ also satisfy DPI. Finally, since these relative entropies satisfy DPI, the homomorphisms that they are associated with are monotone. 

    Let us collect our observations from this section into the following proposition:

    \begin{proposition}\label{prop:monhom}
    The non-degenerate monotone homomorphisms $\Phi:S_{\rm m.r.}\to\mb K\in\{\R_+,\R_+^{\rm op},\T\R_+,\T\R_+^{\rm op}\}$ are exactly the following:
    \begin{itemize}
    \item $\mb K=\R_+^{\rm op}$: $\Phi$ are exactly those of \eqref{eq:temperate} with $\alpha\in[0,1]$ and $z\geq\max\{\alpha,1-\alpha\}$.
    \item $\mb K=\T\R_+^{\rm op}$: $\Phi$ is the homomorphism of \eqref{eq:tropical}.
    \item $\mb K\in\{\R_+,\T\R_+\}$: There are no non-degenerate monotone homomorphisms.
    \end{itemize}
    Moreover, there are no monotone derivations on $S_{\rm m.r.}$.
    \end{proposition}

