\section{Introduction}
%{\color{blue} Think about title. Remove word ``discrimination'' and replace with ``asymptotic hypothesis testing."}
%Marius's Idea: Even in type III von Neumann Algebras, Strong Converse is a Commutative Business
%Note in new 1st sentence that real problem is to distinguish two states
Connections between hypothesis testing and entropy have presented since the beginnings of information theory as a field \cite{chernoff_measure_1952, blahut_hypothesis_1974, han_strong_1989, csiszar_generalized_1995}. The quantum version has also attracted much attention \cite{hiai_proper_1991, hayashi_optimal_2002, hayashi_error_2007, audenaert_discriminating_2007, jaksic_quantum_2012, buscemi_information-theoretic_2019}. Recall the hypothesis testing problem for state discrimination: given some number of copies of an unknown state $\omega$ with the promise that $\omega \in \{\rho, \eta\}$, one may construct tests, two-outcome measurements to distinguish $\omega$. 

We may interpret a state $\rho$ (within finite dimension, a density) as a functional on observables - within finite dimension, $\rho(T) = \tr(\rho T)$ for a state $\rho$ and observable $T$. However, the expression $\rho(T)$ remains meaningful even in infinite-dimensional von Neumann algebras without a finite trace. More specifically , we consider a setting in which one is given many copies of a quantum state. The set of $n$-copy tests in a von Neumann algebra $\N$ is denoted by $\TT_n := \{T_n | 0 \leq T_n \leq 1\} \subset \N^{\otimes n}$. As a two-outcome POVM, the outcome probabilities are given on normal states by $\omega^{\otimes n} \mapsto (\omega^{\otimes n}(T_n), 1 - \omega^{\otimes n}(T_n))$. Given $n$ copies of an unknown state that is either $\rho$ or $\eta$, the error probability of the first kind or type I error probability is given by
\[ \alpha_n(T_n) := \rho^{\otimes n} (\id^{\otimes n} - T_n) \pl, \]
representing the probability that the state is mistakenly identified as $\rho$ when it is actually $\eta$. The error probability of the second kind or type II error probability is given by
\[ \beta_n(T_n) := \eta^{\otimes n} (T_n) \pl, \]
representing the probability that the state is mistakenly identified as $\eta$ when it is actually $\rho$. %{\color{blue} Mention hypothesis testing in title, state discrimination around here - making one error small and letting the other be determined.}
The $n$th minimum type I error probability of Hoeffding type is defined \cite{hiai_quantum_2023} as
\[ \alpha_{e^{-n r}}^*(\rho^{\otimes n} \| \eta^{\otimes n}) := \min_{0 \leq T_n \leq 1} \big \{ \rho^{\otimes n}(\id - T_n) : \eta^{\otimes n}(T_n) \leq e^{- n r} \big \} \pl, \]
where the minimum is taken in all tests in $\M^{\bar{\otimes} n}$ with $\eta^{\otimes n}(T_n) \leq e^{- n r}$. Correspondingly,
\begin{equation} \label{eq:1minusalpha}
    1 - \alpha_{e^{-n r}}^*(\rho^{\otimes n} \| \eta^{\otimes n}) = \max_{0 \leq T_n \leq 1} \big \{ \rho^{\otimes n}(T_n) : \eta^{\otimes n}(T_n) \leq e^{- n r} \big \}
\end{equation}
is the $n$th maximum type I success probability. To interpret the Hoeffding error/success probabilities, note that one can always avoid the possibility of one kind of error, trivally by always guessing one state or the other. With many copies, one may soften this restriction to require merely that the probability of a type II error decreases exponentially with the number of copies. In the many-copy limit or Shannon regime, the probability of the type I error may converge to zero while the probability of a type II error approaches a fixed value. The parameter $r$ in \eqref{eq:1minusalpha} bounds the rate at which errors of the second kind are required to decrease, while the value of the left-hand side given the best possible type I error probability.. A closely related quantity is
%\[  B(\rho,\eta) \pl := \pl 
% \big\{(R,r)\big | \exists_{n_0} \forall_{n\gl n_0} \exists_{0\le T_n\le 1,T_n\in N^{\ten_n}}\pl:\pl
% \eta^{\ten_n}(T_n)\kl e^{-rn} \mbox{ and } \rho^{\ten_n}(T_n) \gl e^{-Rn}\big \}  \pl ,\]
 %and {\color{blue} there is probably an error in defining $B_r$, see Equation (43) in ``Quantum Hypothesis Testing and the Operational Interpretation of the Quantum Rényi Relative Entropies''}
%\[ B_r(\rho\|\eta) \pl :=\pl  \sup\{R | \forall_{r'<r} \pl, \pl (R,r')\in B(\rho\|\eta)\} \pl. \]
\begin{align} \label{eq:Br}
    B_r(\rho \| \eta) := \inf \Big \{ R | \exists \{T_n\}_{n=1}^\infty, 0 \leq T_n \leq 1
    , \limsup_{n \rightarrow \infty} \eta^{\otimes n} (T_n) \leq e^{- r n}, 
      \liminf_{n \rightarrow \infty} \rho^{\otimes n} (T_n) \geq e^{-R n} \} \pl,
    %B_r(\rho \| \eta) := \inf \Big \{ & R | \exists_{n_0} \exists \{T_n\}_{n=1}^\infty, 0 \leq T_n \leq 1
    %| \forall_{n\gl n_0} \eta^{\otimes n} (T_n) \leq e^{- r n}, 
    %   \rho^{\otimes n} (T_n) \geq e^{-R n} \} \pl ,
\end{align}
which was defined in \cite[Equation (43)]{mosonyi_quantum_2015} and denoted ``$B_e^*(r)$'' therein. $B_r(\rho \| \eta)$ is described as a strong converse exponent - it is the rate by which the type I error probability converges exponentially to 1 when the type II error probability is forced to be too small. Within the finite-dimensional setting, it was observed that
\begin{equation} \label{eq:bralpha}
    \begin{split}
    B_r(\rho\|\eta) %& = - \lim_{n \rightarrow \infty} \frac{1}{n}
        %\log \max_{0 \leq T_n \leq 1} \big \{ \rho^{\otimes n}(T_n) : \eta^{\otimes n}(T_n) \leq e^{- n r} \big \}
    & = - \lim_{n \rightarrow \infty} \frac{1}{n} \log \Big \{ 1 - \alpha_{e^{-nr}}^* (\rho^{\otimes n} \| \eta^{\otimes n}) \Big \} \pl.
    \end{split}
\end{equation}
In general von Neumann algebras, it is no longer trivial that the limit exists. We confirm this inequality generalizes as Proposition \ref{prop:Br-alpha}.

The sandwiched R\'enyi relative entropy \cite{wilde_strong_2014, muller-lennert_quantum_2013} is given by
\[ D_\alpha^*(\rho \| \eta) = \| \rho^* \rho \|_{L^{1/2}_\alpha(\eta)} \pl, \]
where the norm is in the Kosaki $L_\alpha^{1/2}$ space weighted by $\eta$ \cite{kosaki_applications_1984, gao_capacity_2018}. The Hoeffding anti-divergence with respect to the sandwiched R\'enyi relative entropy is given for a pair of states $\rho, \eta$ by
\begin{equation} \label{eq:Hr}
    H_r^*(\rho \| \eta) = \sup_{\alpha > 1} \frac{\alpha - 1}{\alpha} \Big \{ r - D_\alpha^*(\rho \| \eta) \Big \}  \pl.
\end{equation}
The main result of this paper is then:
\begin{theorem} \label{thm:main}
    For any $r \in \RR^+$ and states $\rho, \eta \in \M_*$ on any von Neumann algebra $\M$ such that $a \rho \leq \eta$ for some $a > 0$,
    \[B_r(\rho\|\eta) = H_r^*(\rho \| \eta) \pl. \]
\end{theorem}
The finite-dimensional case of Theorem \ref{thm:main} was shown by Mosonyi and Ogawa as \cite[Theorem 4.10]{mosonyi_quantum_2015}. Mosonyi presented an infinite-dimensional generalization in \cite{mosonyi_strong_2023} for trace class or density operators. Hyperfinite von Neumann algebras are limits of finite-dimensional matrix algebras. The hyperfinite case of \ref{thm:main} was shown by Mosonyi and Hiai as \cite[Theorem 3.9]{hiai_quantum_2023}. These follow classical results of Han and Kobayashi \cite{han_strong_1989} and Csisz\'ar \cite{csiszar_generalized_1995}. A later work \cite{cheng_strong_2024} showed an improved, simplified version of one direction of the inequality (in this work, \ref{lem:converse}), that $B_r(\rho \| \eta) \geq H_r^*(\rho \| \eta)$. The majority of the current work is on showing the other direction. It had remained open to generalize the original \cite[Theorem 4.10]{mosonyi_quantum_2015} to non-hyperfinite type III.

A primary implication of Theorem \ref{thm:main} is an operational interpretation of the sandwiched relative R\'enyi entropies beyond the setting of matrix algebras or their limits. This is highlighted via Corollary \ref{cor:cutoff}, showing equivalence to the generalized cutoff rates as in \cite{csiszar_generalized_1995}. A motivating issue for earlier works was that despite their good mathematical properties, the sandwiched R\'enyi entropies initially lacked a correspondence to an operational task in information theory. Hence a major theme of \cite{mosonyi_quantum_2015} and of follow-up works \cite{mosonyi_strong_2023, hiai_quantum_2023} is that via strong converse rates and cutoff rates in hypothesis testing, the sandwiched relative R\'enyi entropies are indeed operational. A major application of quantum information theory today is to quantum field theory and related areas of fundamental physics \cite{witten_aps_2018}. Though many of these settings are hyperfinite, non-hyperfiniteness appears to be a fundamental distinction and meaningful in the theory of computation and quantum correlations \cite{ji_mip*re_2022}. An wider, analogous question is if and where the hyperfinite vs. non-hyperfinite distinction appears in information theory. In this particular case, we show that it does not.

A broader intuition from our methods combines the continuity properties of $H_r^*$ with the monotonicity properties of $B_r$ to obtain desired results. The Haagerup reduction used herein approximates general von Neumann algebras not by finite-dimensional matrices, but by infinite-dimensional algebras that still have a finite trace. Although $B_r$ is not obviously continuous, we note as Lemma \ref{lem:bdp} that it obeys a sort of reverse data processing. Therefore, successive approximations in smaller algebras only increase this quantity.

\section{Background}
Here we briefly recall the notation of von Neumann algebras and Kosaki spaces as well as the relative entropy and generalized divergences. For more detail, we refer the reader to Mosonyi and Hiai's recent work in hyperfinite algebras \cite{hiai_quantum_2023}. One may also see earlier references on von Neumann algebra types \cite{araki_classification_1968} and their physical interpretations \cite{witten_aps_2018}. In particular, we recall that a von Neumann algbera of type $II$ or $III$ is infinite-dimensional and not necessarily approximated by finite-dimensional matrix algebras \cite{ji_mip*re_2022}. An algebra of type $II_1$ does have a finite trace, despite not necessarily being a limit of matrix algebras. An algebra of type $III$ lacks any notion of a finite trace, although some quantum information notions such as relative entropies are still well-defined and well-behaved. 


We first recall the crossed product:
\begin{definition}
Let $G$ be a locally compact abelian group equipped with Haar measure $dg$, and
$\hat G$ its dual group equipped with Haar measure $d\hat g$. We choose
$dg$ and $d\hat g$ so that the Fourier inversion theorem holds. Let
$\alpha$ be a continuous automorphic representation of $G$ on
$\M$. The crossed product $\M \rtimes_\alpha G$ is the von Neumann
algebra on $L_2(G, H)$ generated by the operators $\pi_\alpha(x)$,
$x\in \M$ and $\lambda(g)$, $g\in G$, which are defined by
 $$\big(\pi_{\alpha} (x) \xi \big) (h)=\alpha^{-1}_{h}(x)
 \xi (h),\quad
 \big(\lambda(g) \xi\big) (h) = \xi (h-g), \quad  \xi\in L_2(G, H),\;
 h\in G.$$
\end{definition}
In particular, $\M \rtimes_\alpha \RR$ is of type $II_\infty$ even if $\M$ was of type $III$. As it has a semifinite trace, $\M \rtimes_\alpha \RR$ supports the Haagerup $L_p$ spaces as analogues of the finite-dimensional Schatten classes. For a faithful state $\eta$, by $L_p^{1/2}(\eta)$ we denote the Kosaki $L_p$, the completion of $\N$ with norm
\[ \| \eta^{1/2} X \eta^{1/2} \|_{L_p^{1/2}(\eta)} = \| \eta^{ 1/2p} X \eta^{1/2p} \|_{L_p} \pl,  \pl X\in \N \]
where $L_p$ is the associated Haagerup $L_p$ space \cite{kosaki_applications_1984, haagerup_reduction_2010} (or $L_p(N,tr)$ if $\N$ admits a normal faithful trace $tr$). In von Neumann algebras with finite trace, we may take the usual trace and Schatten norms. In von Neumann algebras that lack even a semifinite trace, the Kosaki $L_p$ and Haagerup norms are still valid and allow us to extend the definitions of relative entropies and related quantities \cite{gao_capacity_2018, junge_multivariate_2022}. Following \cite{furuya_monotonic_2023}, we recall a generalized, parameterized, pre-logarithm $f$-divergence
\begin{equation}
    Q^f_r(\rho \| \eta) := \| \eta^{1/2} f(\Delta_{\rho | \eta}^{1/r})^{1/2*} f(\Delta_{\rho | \eta}^{1/r})^{1/2} \eta^{1/2}  \|_{L^{1/2}_r(\eta)} \pl. % = \| f(\Delta_{\rho | \eta}^{1/r})^{1/2}  \|_{L^{1}_{2 r}(\eta)} \pl.
\end{equation}
The corresponding entropy expression is
\[ D^f_r(\rho \| \eta) := - 2 r \ln Q^f_r(\rho \| \eta) \pl. \]
In finite dimension, the density matrix is naturally and trivially identified with a corresponding quantum state. In a semifinite von Neumann algebra $\M$, one may also associate via an intervible mapping a state $\rho \in \M_*$ with a density operator $d_\rho$ for which $\tr(d_\rho X) = \rho(X)$ for all $X$. In semifinite von Neumann algebras, recall the function
 \[ g_{\rho,\eta}(z) := d_{\rho}^{z} d_{\eta}^{-z} \pl, \]
where $d_\rho$ and $d_\eta$ are respectively the densities corresponding to states $\rho$ and $\eta$. % This function commutes with the modular automorphism group with respect to $\eta$, so it belongs to $\pi(\M) \cong \M$ in the crossed product.
The generalized $f$-divergence may equivalently be expressed as
\begin{equation} \label{eq:semifinitefdiverge}
    Q^f_r(\rho \| \eta) = \| f(g_{\rho | \eta}^{1/r})^{1/2*} f(g_{\rho | \eta}^{1/r})^{1/2}  \|_{L^{1/2}_r(\eta)} \pl.
\end{equation}
Since the trace is necessarily infinite on all elements of a type III von Neumann algebra, the usual notion of Shannon or von Neumann entropy is never finite. The quantum relative entropy and generalized $f$-divergences, however, naturally generalize the notion of entropy to general von Neumann algebras.

%In particular, the norm part of the generalized R\'enyi relative entropy of \cite[Equation 83]{lashkari_monotonic_2023} equals $Q_{x \mapsto x^{q / 2 r}, r}$ with for each $q > 0$.
Within $f$-divergences, our focus is on divergences of the form $Q_{x \mapsto x^{q}, r}$. Cases of interest include $q = r = p$, yielding the sandwiched relative R\'enyi $p$-entropies, and $r = 1, q = 1/p$, yielding the Petz-R\'enyi relative $p$-entropies. In either of these cases, $g_{\rho | \eta}^{q / 2 r *}$ is a holomorphic function of $p \in [1, \infty)$ assuming Equation \eqref{eq:ordassump}. Hence $g_{\rho | \eta}^{q / 2 r *} g_{\rho | \eta}^{q / 2 r}$ is holomorphic in $p$. This work primarily uses the sandwiched relative entropies.
\begin{rem} \label{rem:sandwich}
Although the modular operator is not assured to be holomorphic in type $III$, the sandwiched R\'enyi entropy $D_\alpha^*$ arises from setting
\begin{equation}
    Q^*_{p} =  \| \eta^{1/2} \Delta_{\rho | \eta}^{1/2*} \Delta_{\rho | \eta}^{1/2} \eta^{1/2} \|_{L^{1/2}_p(\eta)} \pl.
\end{equation}
Here we may interpret $\Delta_{\rho | \eta}^{1/2} \eta^{1/2} = \Delta_{\rho | \eta}^{1/2} (\eta^{1/2})$ and $\Delta_{\rho | \eta}^{1/2*}$ as applying to the $\eta^{1/2}$ on its left side. The sandwiched relative R\'enyi entropy is known to obey a data processing inequality \cite{jencova_renyi_2018}. Furthermore, both $Q_\alpha^*(\rho \| \eta)$ and $D_\alpha^*(\rho \| \eta)$ are monotonically non-decreasing in $\alpha$ for every pair of states $\rho$ and $\eta$. When $\rho \leq C \eta$, there exists a $\nu$ for which $\rho^{1/2} = \nu \eta^{1/2}$. One may thereby also write the sandwiched relative entropy as $\| \eta^{1/2} \nu^* \nu \eta^{1/2}\|_{L^{1/2}_p(\eta)}$. In these expressions, the $p$-dependence is relegated to the norm weighting, which is analaytic for $p \in (0,\infty)$.
\end{rem}
The generalized Hoeffding anti-divergence is defined for $r \in \RR$ by
\begin{equation} \label{eq:hoeffding1}
    H_r^f (\rho \| \eta) := \sup_{\alpha > 1} \frac{\alpha - 1}{\alpha} \Big \{ r - D_\alpha^f(\rho \| \eta) \Big \} \pl.
\end{equation}
% https://link-springer-com.proxyiub.uits.iu.edu/article/10.1007/s00220-014-2248-x p1626 or 10/32
\begin{rem} \label{rem:hoeffdingequiv}
    The Hoeffding anti-divergence with respect to the Sandwiched relative entropy, which we denote $H^*_r$, is given equivalently by
    \[ H^*_r(\rho \| \eta) = \sup_{\alpha > 1} \frac{\alpha-1}{\alpha} r - \ln Q^*_\alpha (\rho \| \eta) \pl.\]
\end{rem}
\noindent A hyperfinite von Neumann algebra contains an ascending sequence of finite dimensional subalgebras with union that is dense in the original algebra. While hyperfinite factors have many important applications in operator algebras, mathematical physics, and quantum field theory \cite{araki_classification_1968, witten_aps_2018}, evidence has emerged that hyperfinite von Neumann algebras cannot always approximate general von Neumann algebras \cite{ji_mip*re_2022}. We recall a Theorem of Mosonyi and Hiai \cite[Theorem 3.9]{hiai_quantum_2023} showing the desired result in hyperfinite von Neumann algebras:
\begin{theorem}[Mosonyi-Hiai] \label{thm:origres}
    Assume that $\M$ is an injective (hyperfinite) von Neumann algebra. Let $\rho, \eta \in \M_*^+$ be states such that $D_{\alpha_0}^*(\rho \| \eta) < +\infty$ for some $\alpha_0 > 1$. Then
    \[ \lim_{n \rightarrow \infty} - \frac{1}{n} \log \Big \{ 1 - \alpha_{e^{-nr}}^* (\rho^{\otimes n} \| \eta^{\otimes n}) \Big \} = H_r^*(\rho \| \eta) \pl. \]
\end{theorem}
\noindent This connection to the Holevo type I error probability yields an operational interpretation of the sandwiched R\'enyi entropies as strong converse rates in hypothesis testing. The main goal of the current manuscript is to remove the requirement of injectivity or hyperfiniteness.
