\subsection{Informational Redundancy}
Consider two tests about a binary outcome \(B\), both using data \(\{D^n\}\), of natural filtration \(\{\mathcal{F}_n\}\), based on respective measure-pair \({Q}_B\) and \(\hat{Q}_B\), 
resulting in respective LR process \(\{L^{b\overline{b}}_n\}\) and \(\{\hat{L}^{b\overline{b}}_n\}\), driving the respective belief processes \(\{\pi^b_n\}\) and \(\{\hat{\pi}^b_n\}\) via (\ref{br1}), given respective \emph{a priori} belief \({\pi}^b_{0}\in(0,1)\) and  \(\hat{\pi}^b_0\in(0,1)\).

\begin{definition}\label{d1}
    A standard sequential test, with LR process \(\{\hat{L}^{b\overline{b}}_n\}\) and inferential beliefs \(\{\hat{\pi}^b_n\}\), is said to be {informationally redundant} to another, with \(\{{L}^{b\overline{b}}_n\}\) and \(\{{\pi}^b_n\}\), whenever: 1) \(\exists C>0\) finite such that \(\forall n\in\mathbb{N}\), \(Q_B|_{\mathcal{F}_n}\)-a.s. and \(\hat{Q}_{B}|_{\mathcal{F}_n}\)-a.s.,\begin{align}
\label{speed}&|\log [\hat{L}^{b\overline{b}}_n/{L}^{b\overline{b}}_n]|\equiv|\hat{l}^{b\overline{b}}_n-{l}^{b\overline{b}}_n|<C;
    \end{align}2) there is a continuous function \(h_n:(0,1)\mapsto(0,1)\) at each \(n\in\mathbb{N}\) such that:
    \begin{equation}\label{g}
\hat{\pi}^b_n=h_n({\pi}^b_{n});\end{equation}3) the mapping above is time-homogeneous: \(\forall n\in\mathbb{N}\), \(h_n=h\) and \(\hat{\pi}^b_n=h({\pi}^b_{n})\).
\end{definition}

\begin{remark}\label{adjacent}
        Condition (\ref{speed}) means 'adjacency' in the course of \(B\)-detection, condition (\ref{g}), measurability of \(\hat{\pi}^b_n\) to the \(\sigma\)-algebra \(\mathcal{F}^{\pi}_n\) generated by \(\pi^b_n\), and time-homogeneity, \(\hat{\pi}^b_n=\hat{\pi}^b_{n'}\) whenever \(\pi^b_n=\pi^b_{n'}\). Note the redundancy between tests with identical LRs but differing a priori beliefs% \(\hat{\pi}^b_0\not={\pi}^b_0\)
        : \(O[\hat{\pi}^b_n]=c_0\cdot O[{\pi}^b_n]\), \(\forall n\in\mathbb{N}\), with \(c_0:=O[\hat{\pi}^b_0]/O[{\pi}^b_0]\) ((\ref{br1})); it turns out to be the only form of redundancy possible.
         \end{remark}

\section{Result}\label{lemmasec}

\begin{lemma}\label{l1}
    No regular inference about a binary outcome can be informationally redundant to another without being identical to it up to an {a priori} factor.
\end{lemma}

\begin{proof}
    Consider two such processes in odds terms ((\ref{br1})), \(\{O[{\pi}^b_{n}]\}\) and \(\{O[\hat{\pi}^b_n]\}\), with \(O[{\pi}^b_{0}]=\alpha%\in(0,\infty)
    \) and \(O[\hat{\pi}^b_0]=\hat{\alpha}%\in(0,\infty)
    \), based on data \(\{D^n\}\) on \((\mathbf{V}^{\mathbb{N}}, \{\mathcal{F}_n\})\) under respective measure-pairs \({Q}_B\) and \(\hat{Q}_B\), with respective LR processes \(\{L^{b\overline{b}}_n\}\) and \(\{\hat{L}^{b\overline{b}}_n\}\). Let there be a continuous map \(g_n:\mathbb{R}^+\mapsto\mathbb{R}^+\) at each \(n\in\mathbb{N}\) with \(O[\hat{\pi}^b_{n}]=g_n\big(O[{\pi}^b_{n}]
\big)\).

\emph{Part I.} Random variable \(L^{b\overline{b}}_{m}\), %\(O[\hat{\pi}^b_m]\) \(O[{\pi}^b_n]\), \(O[\hat{\pi}^b_n]\)
\(L^{b\overline{b}}_{n|m}\) and \({\hat{L}^{b\overline{b}}_{n|m}}\), \(n>m\ge1\), are related via (\ref{br1}):\begin{equation}
    \label{sep'}
%g_n\big(O[\pi^b_n]\big)=O[\hat{\pi}^b_{0}]\hat{L}^{b\overline{b}}_n=
\hat{L}^{b\overline{b}}_{n|m}\equiv O[\hat{\pi}^b_m]^{-1}O[\hat{\pi}^b_n]=%\hat{L}^{b\overline{b}}_{n}O[\hat{\pi}^b_{m}]\hat{L}^{b\overline{b}}_{n|m}=
g_m\big(\alpha L^{b\overline{b}}_{m}\big)^{-1}g_n\big(\alpha L^{b\overline{b}}_{m}L^{b\overline{b}}_{n|m}\big).
\end{equation}This must hold \(\forall n>m\ge1\) on some open neighbourhood \(I\subset\mathbb{R}^+\) of \(1\), given continuity and Property-\ref{technical} of Section \ref{st}. That is, for any \(\alpha\in\mathbb{R}^+\) fixed, \(\forall x, y\in I\),\begin{equation}\label{sep''}
\hat{y}=
g_m(\alpha x)^{-1}g_n(\alpha xy),\end{equation}where \(\hat{y}\in {Range}[\hat{L}^{b\overline{b}}_{n|m}]^{extn}\) (the range of \(\hat{L}^{b\overline{b}}_{n|m}\), 
extended by continuation). Then, %if and when , the above reveals:%at any \(n>m\ge1\),
\begin{equation}\label{LL}\hat{y}= g_m(\alpha)^{-1}g_n(\alpha y),\text{ }\forall y\in I\text{ and }x=1.\end{equation}On the other hand, by (\ref{sep''}) and (\ref{LL}), we also have:%at any \(n>m\ge1\),
\begin{equation}\label{LL'}
g_n(\alpha)^{-1}g_n(\alpha x)=g_{m}(\alpha)^{-1}g_{m}(\alpha x),\text{ }\forall x\in I\text{ and }y=1.
    \end{equation}That is, given (\ref{sep''}-\ref{LL'}), continuous real function \(g_{n,\alpha}(\cdot):=g_n(\alpha \cdot)\), \(n\in\mathbb{N}\), satisfies:
\begin{equation}\label{prefxy}
    g_{n,\alpha}(xy)= g_{n,\alpha}^{-1}(1)g_{n,\alpha}(x)g_{n,\alpha}(y),\text{ }\forall x,y\in I.
\end{equation}By arbitrary scaling and so the identification of any real open interval with \(\mathbb{R}^+\), it is equivalent to the functional equation below, a version of Cauchy Equation:\begin{equation}\label{fxy}
f_n(XY)=f_n(1)^{-1}f_n(X)f_n({Y}),\text{ }\forall X,{Y}\in(0,\infty),
    \end{equation}with real continuous solutions \(f_n(\cdot)=(\cdot)^{\gamma_n}c_n\) only, for any \(c_n\in(0,\infty)\) and real \(\gamma_n\). Further, by (\ref{LL'}), \(\gamma_n=\gamma_{m}=:\gamma\) for any \(n>m\ge1\).

    \emph{Part II.} Condition (\ref{speed}) rules out \(\gamma\not=1\) for regular tests; so \(O[\hat{\pi}^b_n]=c_nO[{\pi}^b_{n}]\), \(\hat{L}^{b\overline{b}}_{n}=\frac{c_n}{c_0}L^{b\overline{b}}_{n}\), \(\forall n\in\mathbb{N}\), with \(c_0=\frac{\hat{\alpha}}{\alpha}\), \(\lim_{n\to\infty}c_n<\infty\) and \(\{c_n\}\) \emph{independent} to \(\{{\pi}^b_{n}\}\).

