\end{align}where \(\mathbf{E}_{Q_B}[\cdot|\cdot]\) %and \(\mathbf{Var}_{Q_B}[\cdot|\cdot]\) 
denotes conditional expectations. %The log-LR process as such has its up-to-date expectation at any point equal its up-to-date variance up to a factor of \(\pm\frac{1}{2}\)%, under either \(Q_b\) or \(Q_{\overline{b}}\).
The above shows how i.i.d data ensure \(B\)-detection ((\ref{resolving})). Under \emph{small and independent increments}, log-LR processes are \emph{random walks}, to which Property-\ref{technical} applies, at least asymptotically. %:\begin{align}\label{norm}&\Delta l^{b\overline{b}}_{j+1}(B):=l^{b\overline{b}}_{j+1}(B)-l^{b\overline{b}}_j(B)={(-1)^{\mathbf{1}_{\{B=\overline{b}\}}}}\frac{(\sigma^l_{j})^2}{2} + \sigma^l_{j}\cdot \epsilon_{j+1},\text{ }j=0,1,2,...,%\\\label{norm'}&l^{b\overline{b}}_n(B)\backsim \mathcal{N}\bigg({(-1)^{\mathbf{1}_{\{B=\overline{b}\}}}}\frac{(\sigma^l_{[n]})^2}{2},\text{ }\sigma^l_{[n]}\bigg),\text{ }n=1,2,3...,\end{align}where \((\sigma^l_{[n]})^2:=\sum_{j=0}^{n-1}(\sigma^l_{j})^2\) %is its cumulative variance, and \(\{\epsilon_{j+1}\}\), i.i.d standard Normals \(\backsim\mathcal{N}(0,1)\).%Their exponentiation then yields the dynamics of inferential odds (\ref{br1}), and in turn, of inferential beliefs \(\{\pi^b_n\}\), via Ito-Taylor expansion:\begin{equation}\label{w'-dis}\frac{\Delta\pi^b_{j+1}(B)}{(\sigma^\pi_j)^{2}}= \big(\mathbf{1}_{\{B=b\}}-\pi^b_j(B)\big)(\sigma^l_j)^2+\sigma^l_j\cdot \epsilon_{j+1},\text{ }j=0,1,2,...,\end{equation}with \(\Delta\pi^b_{j+1}:=\pi^b_{j+1}-\pi^b_{j}\) and \((\sigma^\pi_j)^2:=\pi^b_j\pi^{\overline{b}}_j\), all adapted to \(\{\mathcal{F}_{j}\}\).
\begin{enumerate}

\item{\label{takinglimit}\emph{Passing to Continuous Time.} Taking small-increment to its limit under usual conditions, continuous-time log-LR processes are well-known given independent increments: they are L\'evy in general, and Wiener if continuous. For i.i.d data, they are homogeneous, with a fixed \emph{signal-to-noise} \(\sigma^l\): \begin{equation}\label{w}dl^{b\overline{b}}_\tau(B)=(-1)^{\mathbf{1}_{\{B=\overline{b}\}}}\frac{(\sigma^l)^2}{2}d\tau + \sigma^l dw_\tau,\end{equation}where \(\{w_\tau\}\) is a standard Wiener process. Time-varying data and signal-to-noise obtain under some absolutely continuous \emph{clock-change}\textsuperscript{\citenum{clk}} \(t\mapsto \tau(t)\), so that \(\{l^{b\overline{b}}_t\}:=\{l^{b\overline{b}}_{\tau(t)}\}\) reads: in terms of some standard Wiener process \(\{w_t\}\),%with \(\mu^{l,b}_t(B):=\),
\begin{align}\label{w'}&dl^{b\overline{b}}_t(B)=(-1)^{\mathbf{1}_{\{B=\overline{b}\}}}\frac{(\sigma^{l}_t)^2}{2}%\mu^{l,b}_t(B)
dt + \sigma^{l}_tdw_t;%\\\label{rawdrift}  &\frac{d\pi^b_{t}(B)}{(\sigma^\pi_t)^{2}}= \big(\mathbf{1}_{\{B=b\}}-\pi^b_t(B)\big)(\sigma^l_t)^2dt+\sigma^l_tdw_t.
\end{align}the associated inferential belief process \(\{\pi^b_t\}\) is its Ito process via (\ref{br1}).
}
\item{\label{contim'}\emph{Regular Inference.} It resolves uncertainties \emph{predictably}, i.e. continuously if in continuous time. %In discrete time, this requires the moment of resolution to be disclosed beforehand or set at infinity.
This ordinarily puts off resolutions to infinity.
Clock-change allows {finite-time} resolutions via compactification, bringing resolution forward to some \(T_{\mathcal{B}}\le\infty\), into which the log-LR processes diverge while inferential beliefs remain finite and continuous (see (\ref{br1})).}

\item\label{ito}\emph{Redundancy and Ito's Lemma.}
Any 2-differentiable time-homogeneous redundancy map \(g\) between two regular log-LR processes of the form (\ref{w'}) with shared data (i.e. Wiener noise \(\{w_t\}\)), must, by Ito's Lemma, satisfy:\begin{equation}\label{ito1}g''= -(-1)^{\mathbf{1}_{\{B=b\}}}(g'-1)g'.\end{equation}
If \(B=b\), %wherever \(g'\not=0\), \(g'=g'(0)e^{-g(0)}e^{g-\mathbf{Id}}\),\(g'e^{-g}=g'(0)e^{-g(0)}e^{-\mathbf{Id}}\) and so %:\begin{equation}
    then \(g=g(0)-\log[g'(0)e^{-\mathbf{Id}}+1-g'(0)]\);
%\end{equation}
 being resolving and so \(\lim_{t\to T_{\mathcal{B}}}\hat{l}^{b\overline{b}}_t=\infty\) require \(g'(0)=1\). If \(B=\overline{b}\), then \(\lim_{t\to T_{\mathcal{B}}}\hat{l}^{b\overline{b}}_t=-\infty\), but \(g=g(0)+\log[g'(0)e^{\mathbf{Id}}+1-g'(0)]\) and so \(g'(0)=1\) also.

\item{\label{tails}\emph{Adjacency.} Given any two log-LR processes \(\{l^{b\overline{b}}_t\}\) and \(\{\hat{l}^{b\overline{b}}_t\}\), with respective defining measure-pairs \(\{Q_b, Q_{\overline{b}}\}\) and \(\{\hat{Q}_{b}, \hat{Q}_{\overline{b}}\}\) such that \(\hat{Q}_{B}\sim Q_B\), then:\begin{equation}\label{logtrick}\hat{l}^{b\overline{b}}_t-l^{b\overline{b}}_t\equiv\log{\frac{\hat{Q}_{b}|_{t}}{Q_b|_{t}}}-\log{\frac{\hat{Q}_{\overline{b}}|_{t}}{Q_{\overline{b}|_{t}}}},\text{ }t\in\mathbb{N} \text{ or }\in\mathbb{R}^+,\end{equation}with the RHS convergent under equivalence (Radon-Nikodym Theorem). %This holds in continuous time also as \(t\to T_{\mathcal{B}}\le\infty\).
}
\end{enumerate}



