\section{Homological primes}
\label{sec:hom-prim}
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%

Throughout, let $\bK$ be a rigidly-compactly generated monoidal triangulated category with compact part $\bK^c$. 


\bde{serre-prime}
\cite[Definition 6.1]{Vashaw-Yakimov}
A {\em{Serre prime}} in an abelian monoidal category $\bC$ is a Serre ideal $\bS$ of $\bC$ (recall \deref{subcatsMod}(b)) such that if $A \otimes \bC \otimes B \subseteq \bS$, for any $A$ or $B$ in $\bC$, then $A$ or $B$ is in $\bS$.
\ede
The case of biexect tensor product was considered in \cite{Vashaw-Yakimov}. Here, by the nature of $\moddash{\bK^c}$, we consider the more general case 
of a right exact tenor product in each argument. 

Denote the Serre monoidal spectrum $\Spc (\moddash{\bK^c})$ to the topological space consisting of Serre prime ideals of $\moddash{\bK^c}$ with the topology where closed sets are defined to be arbitrary intersections of the base of closed sets
\begin{equation}
\label{wtVh}
\widetilde{V}^{\h}(A):=\{\bS \in \Spc(\moddash{\bK^c}) : \hat A \not \in \bS\}
\end{equation}
for $A \in \bK^c$.

\ble{inv-im}
Let $\bS$ be a Serre prime of $\moddash{\bK^c}$. Then $\h^{-1}(\bS)$ is a prime ideal of $\bK$, i.e., an element of $\Spc \bK^c$.
\ele

\begin{proof}
Suppose $A \otimes \bK^c \otimes B \subseteq \h^{-1}(\bS)$, in other words, $\hat A \otimes \hat C \otimes \hat B \subseteq \bS$ for any object $C \in \bK^c$. Let $F \in \moddash{\bK^c}$. Pick $D \in \bK$ with $\hat D \twoheadrightarrow F$ in $\moddash{\bK^c}$. By \leref{yoneda-tensor}(c) we have 
\[
\hat A \otimes \hat D \otimes \hat B \twoheadrightarrow \hat A \otimes F \otimes \hat B.
\]
Since the left hand side is in $\bS$, and $\bS$ is a Serre subcategory, the right hand side is in $\bS$ as well. It follows that $\hat A \otimes \moddash{\bK^c} \otimes \hat B \subseteq \bS$. Since $\bS$ is prime, either $A$ or $B$ is in $\h^{-1}(\bS)$. 
\end{proof}

\leref{inv-im} produces the map
\begin{equation}
\label{eq:phi}
\widetilde{\phi} : \Spc(\moddash{\bK^c}) \to \Spc \bK^c, \quad \widetilde{\phi}(\bS) := \h^{-1}(\bS). 
\end{equation}

The foundational definition in this paper is the following.

\bde{homol-prime}
A {\em{homological prime}} for $\bK^c$ is a Serre prime ideal $\bS$ of $\moddash{\bK^c}$ which is maximal in the fiber of $\widetilde{\phi}(\bS)$ under the map \eqref{eq:phi}. 

In explicit terms, a Serre prime ideal $\bS$ of $\moddash{\bK^c}$ is a homological prime if it is a maximal element (with respect to inclusion) in the collection of Serre primes, $\widetilde{\phi}^{-1}( \widetilde{\phi}(\bS))$, of $\moddash{\bK^c}$. 
\ede

\bre{homol-prime-equiv}
    Equivalently, a homological prime may be defined as a Serre ideal $\bS$ such that $\bS$ is maximal in the fiber of $\widetilde{\phi}(\bS)$, and $\widetilde{\phi}(\bS) \in \Spc \bK^c$. This follows at once from the fact that the Yoneda embedding $\h : \bK^c \hookrightarrow \moddash{\bK^c}$
is a monoidal functor, \leref{yoneda-tensor}(b).
\ere

In the case that $\bK$ is braided, it is a well-known result that all homological primes are maximal in $\moddash{\bK^c}$. We have the following more involved version of this fact in the noncommutative situation. 

\ble{homol-prime-max}
Let $\bS$ be a homological prime in $\moddash{\bK^c}$. If $A$ is an object which is central in $\bK$ with $\hat A \not \in \bS$, then $\langle \bS, \hat A \rangle = \moddash{\bK^c}$.
\ele

\begin{proof}
    Consider the kernel $F$ of the coevaluation map corresponding to $A$ in $\bK^c$:
    \[
    0 \to F \to \hat \unit \to \hat A \otimes \hat A^*.
    \]
    Since the map $A \to A \otimes A^* \otimes A$ is the inclusion of a direct summand, one has that $\hat A \to \hat A \otimes \hat A^* \otimes \hat A$ is injective, hence $F \otimes \hat A \cong 0$. Since $\hat A$ tensor-commutes with all objects of $\bK^c$, we have $F \otimes \hat B \otimes \hat A \cong 0$ for all objects $B \in \bK^c$. Since each $G \in \moddash{\bK^c}$ is the quotient of some $\hat B$, for $B \in \bK^c$, and since the tensor product in $\moddash{\bK^c}$ is right-exact, we have $F \otimes \moddash{\bK^c} \otimes \hat A = \{0\}.$ Since $\bS$ is a Serre prime that does not contain $\hat A$, we have that $F \in \bS$. But since $\bS' = \langle \hat A, \bS\rangle$ is a Serre subcategory containing $F$ and $\hat A$, it contains $\hat \unit$. Therefore, $\bS' = \moddash{\bK^c}$. 
\end{proof}


Under certain conditions, the definition of homological primes coincides 
with the maximal Serre ideals. 

\bth{thick-max} If $\bK$ satisfies the Central Generation Hypothesis from the introduction, then the collection of homological primes of $\bK$ coincides with the collection of maximal Serre ideals in $\moddash{\bK^c}$.
\eth

\begin{proof}
Suppose all thick ideals of $\bK^c$ are centrally generated, and let $\bS$ be a homological prime in $\moddash{\bK^c}$. Set $\bP := \widetilde{\phi}(\bS)$. Suppose $F \in \moddash{\bK^c}$ and $F \not \in \bS$. Then $\langle F, \bS \rangle$ contains $\hat A$ for some $A \in \bK^c$ with $A \not \in \bP$. Since all thick ideals of $\bK$ are centrally generated, there exists $A' \in \bK^c$ with $A'$ central and $\langle A \rangle = \langle A' \rangle$. It follows that since $\hat A \in \langle F, \bS \rangle$, we also have $\hat A' \in \langle F, \bS \rangle$. By \leref{homol-prime-max}, $\langle \hat A', \bS \rangle = \moddash{\bK^c}$, and hence $\langle F, \bS \rangle = \moddash{\bK^c}$, i.e., $\bS$ is a maximal Serre ideal in $\moddash{\bK^c}$. 

For the other direction, if $\bS$ is a maximal Serre ideal of $\moddash{\bK^c}$, by \leref{inv-im}, $\widetilde{\phi}(\bS):=\bP$ is a prime ideal in $\bK$. It is certainly clear that since $\bS$ is maximal, it is also maximal in the fiber of $\widetilde{\phi}(\bS)$.
\end{proof} 

\bde{hom-spec} Define the {\em{homological spectrum}}, $\Spch \bK^c$, 
of the compact part $\bK^c$ of a rigidly-compactly generated monoidal triangulated category $\bK$ to be the collection of homological primes of $\moddash{\bK^c}$. The closed sets of the topology are defined to be arbitrary intersections of the base of closed sets
\begin{equation}
\label{Vh}
V^{\h}(A):=\{\bS \in \Spch \bK^c : \hat A \not \in \bS\}
\end{equation}
for $A \in \bK^c$. In other words, $\Spch \bK^c$ is the subsets of the Serre monoidal spectrum $\Spc(\moddash{\bK^c})$ with the induced topology. 
\ede

\section{Support maps}\label{S:supportmap}

The following proposition is an improvement of \cite[Theorem 3.14]{Vashaw-Yakimov}.

\bpr{cont-ideal-avoid-mult}
Let $\bI$ be a Serre ideal in $\moddash{\bK^c}$ and $\bM$ an nc-multiplicative subset of $\bK^c$: that is, $\bM$ satisfies the property that if $A$ and $B$ are in $\bM$, then there exists $C$ in $\bK^c$ with $A \otimes C \otimes B \in \bM$. Suppose that $\bI \cap \h(\bM) = \varnothing$. Then there exists a prime Serre ideal $\bS$ of $\moddash{\bK^c}$ maximal with respect to the property that $\bS$ contains the ideal $\bI$ and intersects $\h(\bM)$ trivially.
\epr

\begin{proof}
By Zorn's lemma, there exists a Serre ideal $\bS$ which is maximal among those containing $\bI$ and intersecting $\h(\bM)$ trivially. It remains to show that $\bS$ is prime. Suppose $F \otimes \moddash{\bK^c} \otimes G \subseteq \bS$ for some $F, G \in \moddash{\bK^c}$, and suppose for the sake of contradiction that $F$ and $G$ are not in $\bS$. By the maximality assumption on $\bS$, the Serre ideal $\langle \bS, F\rangle$ contains an object $\hat A$ for some $A \in \bM$, and likewise $\langle \bS, G\rangle$ contains an object $\hat B$ for some $B \in \bM$. One can directly verify that $\hat A \otimes \moddash{\bK^c} \otimes \hat B \subseteq \bS$. But since $\bM$ is an nc-multiplicative subset, there exists some object $C \in \bK^c$ such that $A \otimes C \otimes B \in \bM$, and hence $\hat A \otimes \hat C \otimes \hat B \in \h(\bM) \cap \bS.$ This is a contradiction. 
\end{proof}

The Serre monoidal spectrum $\Spc (\moddash{\bK^c})$ and the homological spectrum $\Spch \bK^c$ give rise to a homological support map for $\bK^c$ that has the tensor product property.

\bpr{Serre-sup} 
The map $\widetilde{V}^{\h} : \bK^c \to \Spc (\moddash{\bK^c})$ given by \eqref{wtVh} is a support map satisfying the tensor product property. In particular, the map $V^{\h} : \bK^c \to \Spch \bK^c$ given by \eqref{Vh} is a support map satisfying the tensor product property.
\epr

\begin{proof} \prref{cont-ideal-avoid-mult} implies that $\widetilde{V}^{\h}$ satisfies condition (i) in \deref{sup}. 
Condition (ii) can be directly verified. Condition (iii) 
holds because every Serre ideal of $\moddash{\bK^c}$ is 
invariant under the suspension functor \eqref{Susp}. 
$\widetilde{V}^{\h}$ satisfies condition (iv) because
the Yoneda embedding is a homological functor. 

Finally, one need to verify that $\widetilde{V}^{\h} : \bK^c \to \Spch \bK^c$ satisfies the tensor product property. For $A, B \in \bK^c$ and $\bS \in \Spc(\moddash{\bK^c})$, 
\begin{align*}
&\bS \notin \bigcup_{C \in \bK^c} \widetilde{V}^{\h} (A   \otimes C \otimes B) \; \; \Leftrightarrow \; \; 
\hat{A} \otimes \hat{C} \otimes \hat{B} \in \bS,\ \forall C \in \bK^c \; \; \Leftrightarrow 
\\ &\hat{A} \otimes \moddash{\bK^c} \otimes \hat{B} \subseteq \bS \; \; \Leftrightarrow \; \; \hat{A} \in \bS \; \mbox{or} \; \hat{B} \in \bS \; \; \Leftrightarrow \; \; 
\bS \notin \sigma (A) \cap \sigma(B),
\end{align*}
where we used that the Yoneda embedding is a monoidal functor 
(\leref{yoneda-tensor}(b)) and the fact that every object in $\moddash{\bK^c}$ is a quotient of an object in the image of the Yoneda functor. 

The map $V^{\h} : \bK^c \to \Spch \bK^c$ is a restriction of the support map $\widetilde{V}^{\h} : \bK^c \to \Spc (\moddash{\bK^c})$,
\begin{equation}
    \label{Vrestr}
V^{\h}(A) = \widetilde{V}^{\h}(A) \cap \Spch \bK^c,
\end{equation}
and by \reref{restr}, it has the stated properties. 
\end{proof}

The previous result permits us to state the following definition. 

\bde{homological-sup} We will call $V^{\h} : \bK^c \to \Spch \bK^c$ the {\em{homological support map}} 
of $\bK^c$. 
\ede

The remainder of this section will be devoted to formulating the Nerves of Steel Conjecture. 

\ble{ideals-inj}
The map from thick ideals of $\bK^c$ to Serre ideals of $\moddash{\bK^c}$ defined by sending a thick ideal $\bI$ to the Serre closure $\langle \h(\bI) \rangle$ of $\h(\bI)$ in $\moddash{\bK^c}$ is an injective map. In other words, if $A \not \in \bI$ in $\bK$, then $\hat A \not \in \langle \h(\bI) \rangle$ in $\moddash{\bK^c}$. 
\ele

\begin{proof}
%Since $\bI$ is a thick ideal of $\bK^c$, the Verdier quotient $\bK^c/ \bI$ is a monoidal triangulated category. 
By \leref{yoneda-tensor}(d), $\moddash{(\bK^c/\bI)} \cong \moddash{\bK^c}/ \langle \h(\bI) \rangle$. If $A \not \in \bI$, then the image of $\hat A$ in $\moddash{\bK^c/\bI}$ is nonzero, and so, $\hat A \not \in \langle \h(\bI)\rangle$. 

%We now show that $\moddash{\bK/\bI}$ and $\moddash{\bK^c}/\langle \h(\bI) \rangle$ coincide. By pulling back along the quotient $\bK \to \bK/\bI$, one obtains a functor $\moddash{\bK/\bI} \to \moddash{\bK^c}$.
\end{proof}

The restriction
\[
\phi := \widetilde{\phi}|_{\Spch \bK^c} : \Spch \bK^c \to \Spc \bK^c
\]
will be called the homological comparison map, recall \eqref{eq:phi}.

By \prref{Serre-sup}, the map $\widetilde{V}^{\h} : \bK^c \to \Spc (\moddash{\bK^c})$ and the homological support map $V^{\h} : \bK^c \to \Spc (\moddash{\bK^c})$ are support maps (in the sense of \deref{sup}) that have the tensor product property. Therefore, they should be linked to the Balmer support as in \prref{univ}. The following proposition tells us that this is done via the maps $\widetilde{\phi}$ and $\phi$, respectively.

\bpr{surj}
\hfill
\begin{enumerate}
\item[(a)] For all $A \in \bK^c$, 
\begin{equation}
\label{wtphiV}
\widetilde{\phi}^{-1}(V^B(A)) = \widetilde{V}^{\h}(A),
\end{equation}
and as a consequence,
\begin{equation}
\label{phiV}
\phi^{-1}(V^B(A)) = V^{\h}(A),
\end{equation}
recall the Balmer support \eqref{Balmer-sup}.
\item[(b)] The map $\widetilde{\phi}: \Spc(\moddash{\bK^c}) \to \Spc \bK$ is a continuous map, and as a consequence, so is the map $\phi: \Spc^{\h}\bK \to \Spc \bK$. 
\item[(c)] The map $\phi: \Spc^{\h}\bK \to \Spc \bK$ surjective. 
\end{enumerate}
\epr

\begin{proof} First we prove \eqref{wtphiV}. For all $A \in \bK^c$, 
\begin{align*}
\widetilde{\phi}^{-1}(V^B(A))&=\{ \bS \in \Spc(\moddash{\bK^c}) : A \not \in \phi(\bS)\}\\
&=\{ \bS \in \Spch(\moddash{\bK^c}) : \hat A \not \in \bS\}\\
&=\widetilde{V}^{\h}(A). 
\end{align*}
Equation~ \eqref{phiV} follows from \eqref{Vrestr} and \eqref{wtphiV}. This proves part (a). 

Part (b) follows from part (a) since the topologies of 
$\Spc( \moddash{\bK^c})$ and $\Spch \bK^c$ are given in terms 
of bases consisting of $\widetilde{V}^{\h}(A)$ and $V^{\h}(A)$ for $A \in \bK^c$. 

For part (c), let $\bP \in \Spc \bK$. To construct a homological prime $\bS$ with $\phi(\bS)=\bP$, we employ \prref{cont-ideal-avoid-mult}, taking $\bI = \langle \h(\bP) \rangle$ and $\bM=\bK \backslash \bP.$ The fact that $\bI$ and $\h(\bM)$ are disjoint follows from \leref{ideals-inj}.
\end{proof}

The developed framework for homological spectra of (the compact parts) of rigidly-compactly generated monoidal categories leads us to a point where we can formulate an extension of 
Balmer's Nerves of Steel Conjecture \cite{Balmer2020c}.

\bcj{nerves} [{\em{Nerves of Steel Conjecture}}] For every rigidly-compactly generated monoidal category $\bK$, the map 
\[
\phi : \Spch \bK^c \to \Spc \bK^c
\]
is a homeomorphism.
\ecj
The remaining part of this paper is devoted to developing methods towards the proof of the conjecture. 

\bre{nerves-bijection}
Note that by \prref{surj} (b) and (c), a subset $S$ of $\Spc \bK^c$ is closed if and only if $\phi^{-1}(S)$ is closed in $\Spch \bK^c$, and so the homological comparison map $\phi$ is a quotient map, hence a homeomorphism if and only if it is bijective. Since it is already proven to be surjective, to prove Nerves of Steel it suffices to show that $\phi$ is injective. 
\ere

%%%%%%%%%%%%%%%%%%%%%%%%%%5
\section{Pure-injectives}
\label{6}
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
Recall that in the category $\bK$, an object $A$ is called {\it pure-injective} if every morphism $f: A \to B$ such that $\hat f: \hat A \to \hat B$ is injective splits in $\bK$. The critical observation which emphasizes the importance of pure-injectives in the study of compactly generated triangulated categories is the following result of Krause \cite[Theorem 1.8, Corollary 1.9]{Krause2000} (which does not require any monoidal or tensor structure on $\bK$):

\bth{Krause-pureinj}
Let $\bK$ be a compactly generated triangulated category. Then the restricted Yoneda functor $\h$ gives a bijection between pure-injective objects of $\bK$ and injective objects of $\Moddash{\bK^c}$. Additionally, if $B$ is a pure-injective of $\bK$, there is an isomorphism
\[
\Hom_{\bK}(A,B) \cong \Hom_{\Moddash{\bK^c}} (\hat A, \hat B)
\]
for any $A \in \bK$.
\eth

For the remainder of this section, fix a rigidly-compactly generated monoidal triangulated category $\bK$, and a Serre ideal $\bS \subseteq \moddash{\bK^c}$. We will denote $\bA:=\Moddash{\bK^c}$, so that $\bA^{\fp}\cong \moddash{\bK^c}$, \eqref{eq:modMod}. Set  
\[
\overrightarrow{\bS} :=\{ F \in \bA : \text{ if } f: G \to F \text{ with } G \in \bA^{\fp}, \text{ then } f \text{ factors through }\bS\}.
\]
By \cite[Lemma 4.1]{Crawley-Boevey1994}, the subcategory $\overrightarrow{\bS}$ is the unique minimal localizing subcategory containing $\bS$, 
recall \deref{subcatsMod}(c). Since $\bS$ is a Serre ideal, $\overrightarrow{\bS}$ is also a Serre ideal of 
$\Moddash{\bK^c}$, since every object of $\overrightarrow{\bS}$ is a colimit of objects in $\bS$, and the tensor product on $\bA$ commutes with colimits.

We denote $\overline{\bA}:=\bA/\overrightarrow{\bS}$, the Gabriel--Serre quotient of $\bA$ by $\overrightarrow{\bS}$. The quotient functor
\[
Q: \bA \to \overline{\bA}
\]
admits a right adjoint
\[
R: \overline{\bA} \to \bA
\]
which is left exact, preserves injectives, and satisfies $QR \cong \Id_{\overline{\bA}}$ by \cite[Theorem 2.8]{Krause1997}. 

\bde{homol-res}
When $\bS$ is a Serre prime, the functor $Q \circ \h : \bK \to \overline{\bA}$ 
(and by abuse of notation, the abelian category $\overline{\bA}$)
will be called the {\em{noncommutative homological residue field}} associated to $\bS$. 
\ede

\bnota{bar-from-k}
We will denote the image of $F \in \bA$ under $Q$ by $\overline{F}$, and likewise denote the image of $A \in \bK$ under $Q \circ \h$ by $\overline{A}$. 
\enota



The quotient category $\overline{\bA}$ inherits a monoidal product from $\bA$ such that the quotient functor $Q$ is monoidal, by a similar argument to \cite[Appendix A]{BKS2019}:

\bpr{quot-mon}
Let $\bA$ and $\overline{\bA}$ as above. Then $\overline{\bA}$ is a monoidal category, where we define $\overline{F} \otimes \overline{G} := \overline{F \otimes G}$ for all $F, G \in \bA$.
\epr

\begin{proof}
    To prove that this monoidal product is well-defined, we must verify that if 
    \[
    0 \to F_1 \to F_2 \to F_3 \to 0
    \]
    is a short exact sequence in $\bA$ with $F_1 \in \overrightarrow{\bS}$ then $\overline{F_2 \otimes G} \cong \overline{F_3 \otimes G}$, and similarly for the roles of $1$ and $3$ reversed; and then likewise by tensoring $G$ on the right. The right and left cases are symmetric, but the cases where $1$ and $3$ are reversed are not, since the tensor product on $\bA$ is right exact, but not left exact. We have an exact sequence
    \[
    \Tor_1(F_3, G) \to F_1 \otimes G \to F_2 \otimes G \to F_3 \otimes G \to 0.
    \]
    On one hand, if $F_1 \in \overrightarrow{\bS}$, then $F_1 \otimes G$ is in $\overrightarrow{S}$ by its tensor ideal property, hence $\overline{F_2 \otimes G} \cong \overline{F_3 \otimes G}$. On the other hand, assume instead that $F_3 \in \overrightarrow{\bS}$. We must show that $\Tor_1(F_3,G) \in \overrightarrow{\bS}$. Indeed, since all objects in $\bA$ are colimits of objects in $\h(\bK^c)$ (cf. \eqref{eq:colimM}), we can find objects $\{A_i\}_{i \in I}$ and $\{B_j\}_{j\in J}$ of $\bK^c$ with an exact sequence of the form 
    \[
    \coprod_{i \in I} \widehat{A}_i \to \coprod_{j \in J} \widehat{B}_j \to G \to 0.
    \]
    Then $\Tor_1(F_3,G)$ is computed via the cohomology of the complex
    \[
    F_3 \otimes \coprod_{i \in I} \widehat{A}_i \to F_3 \otimes 
    \coprod_{j \in J} \widehat{B}_j \to 0,
    \]
    all the terms of which are in $\overrightarrow{\bS}$. Since $\overrightarrow{\bS}$ is a Serre subcategory of $\Moddash{\bK^c}$, $\Tor_1(F_3,G) \in \overrightarrow{\bS}$, which completes the proof of the proposition.
\end{proof}

The next theorem will be important for the development of theory because it shows that one can realize injective objects of $\overline{\bA}$ as images of pure injectives. 

\bth{pure-injs-in-abar}
Every injective object of the noncommutative homological residue field $\overline{\bA}$ is equal to $\overline{E}$ for some pure-injective $E \in \bK$, and there is an isomorphism
\[
\Hom_{\bK}(A,E) \cong \Hom_{\overline{\bA}}(\overline{A}, \overline{E})
\]
for all $A \in \bK$.
\eth

\begin{proof}
The proof proceeds similarly to \cite[Corollary 2.18]{BKS2019}; we include the details for the ease of the reader. Given an injective object of $\overline{\bA}$, we can form the pure-injective $E$ by first applying $R$ and then applying \thref{Krause-pureinj}. For the isomorphism of hom sets, compute
\begin{align*}
    \Hom_{\bK}(A,E) & \cong \Hom_{\bA} (\hat A, \hat E)\\
    &\cong \Hom_{\bA}(\hat A, R(\overline{E}))\\
    &\cong \Hom_{\overline{\bA}} (\overline{A}, \overline{E}).
\end{align*}
The first isomorphism is by \thref{Krause-pureinj}, the second by the definition of $\hat E$, and the third by the adjunction between $Q$ and $R$. 
\end{proof}


Since $\bA$ is a Grothendieck category, the noncommutative homological residue field $\overline{\bA}$ is also a Grothendieck category, and each such category has injective envelopes \cite[Theorem 6.25]{Freyd}.

\bnota{pure-inj-s}
We will denote the injective envelope of $\overline{\unit}$ in $\overline{\bA}$ by $\overline{E_{\bS}},$ and the unique pure-injective which corresponds to $\overline{E_{\bS}}$ in $\bK$ by \thref{pure-injs-in-abar} will be denoted $E_{\bS}$.
\enota

In the remainder of this section, since $\bS$ is fixed, we will denote \[
E:=E_{\bS}.
\]
Our main goal will be showing that the localizing category $\overrightarrow{\bS}$ is equal to the kernel of the functor $\hat{E} \otimes -$ in $\Moddash{\bK^c}$. 

We begin by proving a noncommutative version of \cite[Proposition 3.3]{BKS2019}. Note that by \thref{pure-injs-in-abar} we have a distinguished triangle
\[
A \xrightarrow{f} \unit \xrightarrow{g} E \to \Sigma A
\]
such that $\overline{g}: \overline{\unit} \to \overline{E}$ is the injective envelope for $\overline{\unit}$ in $\overline{\bA}$. 

\ble{f-inj-properties-in-k}
Let $f$ and $g$ be as above. Then
\begin{enumerate}
    \item[(a)] if $h: B \to \unit$ in $\bK$ satisfies $\overline{h}=0$, then there exists $i: B \to A$ such that $h=fi$;
    \item[(b)] $f \otimes \id_E$ and $\id_E \otimes f$ are both 0;
    \item[(c)] if $h: B \to C$ is a morphism in $\bK$ such that $C \in \bK^c$ and $\overline{h}=0$, then $h \otimes \id_E$ and $\id_E \otimes h$ are both 0.
\end{enumerate}
\ele

\begin{proof} (a) By the extension axiom for triangulated categories, it is enough to show that $gh=0$, via the morphism of triangles
\begin{center}
    \begin{tikzcd}
A \arrow[r, "f"]                                    & \unit \arrow[r, "g"]       & E \arrow[r]                & \Sigma A \\
B \arrow[r, "\id_B"] \arrow[u, "\exists i", dashed] & B \arrow[u, "h"] \arrow[r] & 0 \arrow[u, "0"] \arrow[r] & \Sigma B
\end{tikzcd} 
\end{center}
    Now note that $\overline{gh} = \overline{g} \overline{h} =0$, since $\overline{h}$ is 0 by assumption; but by the isomorphism $\Hom_{\bK}(B,E) \cong \Hom_{\overline{\bA}}(\overline{B}, \overline{E})$ from \thref{pure-injs-in-abar}, this implies that $gh=0$, which proves (a). 

    (b) Since $\h$ is a homological functor, and since the quotient functor $\bA \to \overline{\bA}$ is exact, the sequence
    \[
    \overline{A} \xrightarrow{\overline{f}} \overline{\unit} \xrightarrow{\overline{g}} \overline{E}
    \]
    is exact in $\overline{\bA}$. Since $\overline{g}$, by assumption, is the map of the unit into its injective envelope, it is an injective map and $\overline{f}$ is 0. This applies immediately that $\overline{f \otimes \id_E},$ which is identified with $\overline{f} \otimes \id_{\overline{E}}$, is 0 as a morphism $ \overline{A} \otimes \overline{E} \to \overline{E}$. Again using the isomorphism from \thref{pure-injs-in-abar}, this implies $f \otimes \id_E =0$. The argument that $\id_E \otimes f =0$ follows in the same way.

    (c) One has 
    \[
    h':= C^* \otimes B \xrightarrow{\id_{C^*} \otimes h} C^* \otimes C \xrightarrow{\ev_C} \unit
    \]
    is a morphism whose target is $\unit$, and satisfies $\overline{h'}=0$. By (a) $h'$ factors through $f$, and hence by (b), $h' \otimes \id_E$ and $\id_E \otimes h'$ are 0. Now just note that by the defining equations for duals, $h$ is equal to
    \[
    B \xrightarrow{\coev_C \otimes \id_B} C \otimes C^* \otimes B \xrightarrow{\id_C \otimes h'} C.
    \]
    Hence, $h \otimes \id_E$ factors through $\id_C \otimes h' \otimes \id_E=0$, and so $h \otimes \id_E=0$. 

    On the other hand, define \[     h'':=B \otimes {^* C} \xrightarrow{h \otimes \id_{{^* C}}} C \otimes {^*C} \xrightarrow{\ev_{{^*C}} }\unit      \] 
    using the right dual ${^*C}$ of $C$. We have that $\overline{h''}=0$, hence $h''$ factors through $f$, and so $h'' \otimes \id_E$ and $\id_E \otimes h''=0$. Again using the duality conditions, we can write $h$ as
    \[
    B \xrightarrow{\id_B \otimes \coev_{{^*C}}} B \otimes {^* C} \otimes C \xrightarrow{h'' \otimes \id_C} C.
    \] Since $\id_E \otimes h''=0$, it follows that $\id_E \otimes h=0$, and (c) as follows. 
\end{proof}

\bth{S-is-KerE} One has equalities of the following localizing subcategories in $\bA$: 
\[
\ker(\hat E \otimes -) = \overrightarrow{\bS} = \ker(- \otimes \hat E).
\]
\eth

\begin{proof}
    The proof is similar to \cite[Theorem 3.5]{BKS2019}, with a few necessary modifications. First, suppose that $F \in \bA$ satisfies $\hat E \otimes F = 0$. Recall that since every object of $\bA$ is a colimit of objects from $\h(\bK^c)$, we can take objects $\{A_i\}_{i \in I}$ and $\{B_j\}_{j\in J}$ of $\bK^c$ together with maps forming an exact sequence \[
    \coprod_{i \in I} \hat A_i \to \coprod_{j \in J} \hat B_j \to F \to 0.
    \]
    Denote the coproduct of the $A_i$'s by $A$ and the coproduct of the $B_j$'s by $B$, so that we have maps $f: A \to B$, $g: \hat B \to F$ such that 
    \[
    \hat A \xrightarrow{\hat{f}} \hat B \xrightarrow{g} F \to 0
    \]
    is exact in $\bA$. 

    Since 
    \[
    \hat A \xrightarrow{\hat f} \hat B \xrightarrow{\hat h} \hat C
    \]
    is also exact, for $C=\cone(f)$, it follows that $F$ is the image of $\hat h$. Since tensor product with $\hat E$ is exact, the image of $\id_{\hat E} \otimes \hat h =  \hat E \otimes F \cong 0$, and so $\id_{\hat E} \otimes \hat h = 0$. In particular, the image in $\overline{\bA}$ also vanishes: $\id_{\overline{E}} \otimes \overline{h}=0$. 

    Recall that $\overline{E}$ is the injective envelope of $\overline{\unit}$ in $\overline{\bA}$, say via 
    \[
    i: \overline{\unit} \to \overline{E}.
    \]
    There exists a commutative diagram
    \[
    \begin{tikzcd}
\overline{\unit} \otimes \overline{B} \arrow[d, "i \otimes \id_{\overline{B}}"'] \arrow[r, "\id_{\overline{\unit}} \otimes \overline{h}"] & \overline{\unit} \otimes \overline{C} \arrow[d, "i \otimes \id_{\overline{C}}"] \\
\overline{E} \otimes \overline{B} \arrow[r, "\id_{\overline{E}} \otimes \overline{h} = 0"']                                               & \overline{E} \otimes \overline{C}                                              
\end{tikzcd}
    \]
where the map $i \otimes \id_{\overline{C}}$ is injective, since $\overline{C}$ is flat and $i$ is injective; this immediately implies that $\id_{\overline{\unit}} \otimes \overline{h} =0$. It follows that $\overline{h} = 0$, and since $\overline{F}$ is the image of $\overline{h}$, 
$\overline{F} \cong 0$, that is, $F \in \overrightarrow{\bS}$. This shows that $\ker(\hat E \otimes -) \subseteq \overrightarrow{\bS}$; the argument that $\ker(- \otimes \hat E) \subseteq \overrightarrow{\bS}$ is symmetric.

Next, we show $\overrightarrow{\bS} \subseteq \ker(\hat E \otimes -) \cap \ker(- \otimes \hat E).$ Note that $\hat E$ is flat, and so $\ker(\hat E \otimes -)$ is a localizing subcategory of $\bA$. Since $\overrightarrow{\bS}$ is generated as a localizing subcategory by $\bS$, it follows that $\overrightarrow{\bS} \subseteq \ker(\hat E \otimes -)$ if and only if $\bS \subseteq \ker(\hat E \otimes -)$. Let $F \in \bS.$ As before, we can find a morphism $f: A \to B$ in $\bK^c$ such that $F$ is the image of $\hat{f}$. But since the quotient functor $\bA \to \overline{\bA}$ is exact, the image of $\overline{f}$ is $\overline{F}$, and $\overline{F} \cong 0$ in $\overline{\bA}$ (using the assumption that $F \in \bS$). It follows that $\overline{f}: \overline{A} \to \overline{B}$ is equal to $0$. By \leref{f-inj-properties-in-k}(c), using the fact that $B$ is compact, we can conclude that $f \otimes \id_E=0=\id_E \otimes f$. Since $F$ is the image of $\hat{f}$, it immediately follows that $F \otimes \hat E\cong 0 \cong \hat E \otimes F$, showing that $F \in \ker(\hat E \otimes -) \cap \ker(- \otimes \hat E)$.

We have now shown that 
\[
\ker(\hat E \otimes -) \cup \ker(- \otimes \hat E) \subseteq \overrightarrow{\bS} \subseteq \ker(\hat E \otimes -) \cap \ker(- \otimes \hat E).
\]
The claim of the theorem follows.
\end{proof}

%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
\section{Stratification vs Nerves of Steel}
\label{7}
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%5%%

In this section, we connect the Nerves of Steel Conjecture to the stratification of $\bK$ via the Balmer--Favi support. Recall the construction of extended supports inspired by Benson--Iyengar--Krause \cite{BIK2008} and Balmer--Favi \cite{Balmer-Favi}, which was fully realized in the noncommutative case in \cite{CaiVashaw}. 
The {\em{extended support}} is a map which assigns to each object of $\bK$ a subset of $\Spc \bK^c$, such that if $A$ is compact the subset is the Balmer support of $A$, which satisfies typical properties of support. Moreover, 
the extended support is defined using the Rickard idempotent functors $L_{\bI}$ and $\Gamma_{\bI}$, which are triangulated functors $\bK \to \bK$, associated to a thick subcategory $\bI$ of $\bK$; see e.g.,~ \cite[Section 3]{CaiVashaw} for background on these functors. Critically, for any object $A \in \bK$, there is a distinguished triangle
\begin{equation}
\label{rickard-tri}
    \Gamma_{\bI} A \to A \to L_{\bI} A \to \Sigma \Gamma_{\bI} A.
\end{equation}
The object $\Gamma_{\bI} A$ is in $\Loc(\bI)$ and the object $L_{\bI} (A)$ is in $\Loc(\bI)^{\perp}$, that is, it admits no maps from any objects of $\Loc(\bI)$; and if 
\[
B \to A \to C \to \Sigma B
\]
is another triangle with $B \in \Loc(\bI)$ and $C \in \Loc(\bI)^{\perp}$, then there are unique isomorphisms $B \cong \Gamma_{\bI}(A)$ and $C \cong L_{\bI}(A)$. Using this universal property, one can verify that 
\[
\Gamma_{\bI}(A) \cong \Gamma_{\bI}(\unit) \otimes A\cong A \otimes \Gamma_{\bI}(\unit), \quad L_{\bI}(A) \cong L_{\bI}(\unit) \otimes A\cong A \otimes L_{\bI}(\unit). 
\]


Recall that given any specialization-closed subset $S$ of $\Spc \bK^c$, 
one has a thick ideal
\[
\Theta^B(S):=\{ A \in \bK^c : V^B(A) \subseteq S\}.
\]
For ease of notation, denote
\[
\Gamma_{S}:=\Gamma_{\Theta^B(S)}, \quad L_{S} := L_{\Theta^B(S)}
\]
for any specialization-closed subset $S$ of $\Spc \bK^c$. Now define for any $\bP$ in $\Spc \bK^c$ the functor
\[
\Gamma_{\bP} :=\Gamma_{\mc{V}(\bP)} L_{\mc{Z}(\bP)} \cong L_{\mc{Z}(\bP)} \Gamma_{\mc{V}(\bP)},
\]
where $\mc{V}(\bP)$ and $\mc{Z}(\bP)$ are the subsets
\[
\mc{V}(\bP) := \overline{\{ \bP\}}, \quad \mc{Z}(\bP) := \{ \bQ \in \Spc \bK^c : \bP \not \in \mc{V}(\bQ)\}.
\]
The extended support, as defined in \cite{CaiVashaw} and which we will refer to throughout the remainder of the paper as the {\em{Balmer--Favi support}}, is defined as
\begin{equation}
\label{BFsupport}
V^{BF}(A) := \{ \bP \in \Spc \bK^c : \Gamma_{\bP} A \not \cong 0 \}
\end{equation}
for any $A \in \bK$. Note that if $A$ is compact, the Balmer--Favi support recovers the Balmer support, that is, $V^B(A) = V^{BF}(A)$, see \cite[Proposition 3.8]{CaiVashaw}.


Let $\bL$ be a localizing ideal of $\bK$ and $S$ be a subset of $\Spc \bK^c$. We denote 
\[
\Phi^{BF}(\bL):= \bigcup_{A \in \bL} V^{BF}(A)
\]
and 
\[
\Theta^{BF}(S) :=\{A \in \bK : V^{BF}(A) \subseteq S\}.
\]

\bde{strat} The topological space $\Spc \bK^c$ {\it{stratifies}} $\bK$ if the maps $\Phi^{BF}$ and $\Theta^{BF}$ define an order-preserving bijection between localizing $\otimes$-ideals of $\bK$ and subsets of $\Spc \bK^c$.
\ede


The next theorem is an explicit description of the Balmer--Favi support of all pure-injective objects representing arbitrary Serre primes of $\moddash{\bK^c}$. Our result is new even in the symmetric case and is a far-reaching extension of \cite[Lemma 3.7]{BHS2023}.

\bth{supp-pureinj-2}
Suppose $\Spc \bK^c$ is Noetherian. Let $\bS$ be a Serre prime of $\moddash{\bK^c}$ with corresponding pure-injective 
\[
E:=E_{\bS} \in \bK,
\]
which satisfies $\overrightarrow{\bS} = \ker (\hat{E} \otimes -).$ Then the Balmer--Favi support for $E$ is equal to 
\[
V^{BF}(E)=\{ \phi(\bS') : \bS' \in \Spch(\bK^c) \; \text{ with } \; \bS' \supseteq \bS \}.
\]
In other words, the Balmer--Favi support of $E$ consists 
of the primes of $\bK^c$ living over $\bS$, recall the terminology in the introduction.
\eth

\begin{proof} Set $\bP:=\phi(\bS).$
We use throughout the proof that $\bQ$ is in $V^{BF}(E)$ if and only if $\Gamma_{\bQ} E \not \cong 0$, which is true if and only if $\widehat{\Gamma_{\bQ} \unit} \not \in \overrightarrow{\bS}$.
The proof will consist of the following steps.
\begin{enumerate}
    \item $\bP$ is in the Balmer--Favi support of $E$;
        \item If there exists $\bS' \in \Spch(\bK^c)$ with $\bS \subseteq \bS'$, then $\bQ:=\phi(\bS')$ is in the Balmer--Favi support of $E$;
    \item If $\bQ$ is in the Balmer--Favi support of $E$, then $\bQ$ contains $\bP$;
    \item If $\bQ$ is in the Balmer--Favi support of $E$, then there exists $\bS'$ in $\Spch(\bK^c)$ containing $\bS$ such that $\bQ = \phi(\bS')$. 
\end{enumerate}


For (1), note that $\bP \in V^{BF}(E)$, i.e.,~ that $\Gamma_{\bP} E \not \cong 0,$ or equivalently that $\widehat{\Gamma_{\bP} \unit} \not \in \overrightarrow{\bS}$. We first claim that $L_{\mc{Z}(\bP)} E \cong E$, that is, that $E $ is in $\Loc(\Theta^B(\mc{Z}(\bP)))^{\perp}$. Indeed, if $A$ is compact then $A \in \Theta^B(\mc{Z}(\bP))$ if and only if $V^B(A) \subseteq \mc{Z}(\bP)$ (that is, $\bP \not \in V^B(A)$, i.e.,~ $A \in \bP$). We know in this case that $A \otimes E \cong 0$, and likewise $A^* \otimes E \cong 0$; since $A$ is compact, this implies
\[
\Hom_{\bK}(A,E) \cong \Hom_{\bK}(\unit, A^* \otimes E) \cong \Hom_{\bK}(\unit,0) \cong 0.
\]
Hence, $E$ is indeed in $\Loc(\Theta^B(\mc{Z}(\bP)))^{\perp}$, and so $L_{\mc{Z}(\bP)} E \cong E$. 

To conclude that $\Gamma_{\bP} E \not \cong 0$, it remains to show that $\Gamma_{\mc{V}(\bP)} E \not \cong 0$. Recall that $\Gamma_{\mc{V}(\bP)} E \cong 0$ if and only if $E \in \Loc(\Theta^B(\mc{V}(\bP)))^{\perp}$. This will hold if and only if $E \otimes A \cong 0$ for all $A \in \Theta^B(\mc{V}(\bP))$. To contradict this, take $B$ to be a compact object with $V^{BF}(B)=\mc{V}(\bP)$; such a $B$ exists by \thref{thm-bij}, using the fact that $\Spc \bK^c$ is Noetherian. Then certainly $B \in \Theta^B(\mc{V}(P))$, and additionally $B \not \in \bP$. But since $B \not \in \bP$, one also has $\hat B \not \in \bS$, and so $E \otimes B \not \cong 0$. Therefore, $E$ is not in $\Loc(\Theta^B(\mc{V}(\bP)))^{\perp}$, and (1) follows.  

Now assume the situation of (2). Set $E'$ to be the pure-injective corresponding to $\bS'$. Suppose $\bQ$ were not in $V^{BF}(E)$. This would mean by definition that $\Gamma_{\bQ}\unit \otimes E \cong 0$, hence that $\Gamma_\bQ 
 \unit $ is in $\overrightarrow{\bS}$. However, $\Gamma_{\bQ}\unit$ would be in $\overrightarrow{\bS'}$, and hence $\Gamma_{\bQ} \unit \otimes E'$ would also be 0. This would then contradict (1) applied to $E'$, since $\bQ$ must be in the support of $E'$. 


For (3), suppose that $\bQ$ is a prime ideal which does not contain $\bP$. We need only show that $\Gamma_{\mc{V}(\bQ)} \unit \in \Loc(\bP)$. But indeed, $\Gamma_{\mc{V}(\bQ)} \unit$ is in $\Loc(\Theta^B(\mc{V}(\bQ)))$, so it suffices to prove that $\Theta^B(\mc{V}(\bQ)) \subseteq \bP$. By definition, $\Theta^B(\mc{V}(\bQ))$ is the thick ideal consisting of compact objects $A$ with $V^B(A) \subseteq \mc{V}(\bQ) = \overline{\{\bQ\}}$. Since $\bP \not \subseteq \bQ$, we have $\bP \not \in \overline{\{\bQ\}}$; hence if $A \in \Theta^B(\mc{V}(\bQ))$, $\bP \not \in V^B(A)$, i.e.,~ $A \in \bP$. This completes the proof of claim (3).

Finally, for (4), suppose $\bQ \in V^{BF}(E)$ and $\bQ \not = \bP$. By (3), we know that $\bQ$ strictly contains $\bP$. Consider 
\[
\bM:=\{ \hat A \in \moddash{\bK^c} : A \in \bK^c \backslash \bQ\},
\]
and consider
\[
\bS':=\langle \bS, \hat{A} : A \in \bQ\rangle.
\]
One can readily verify that $\bM$ is an nc-multiplicative subset, using the prime condition. \prref{cont-ideal-avoid-mult} can be used to produce a Serre prime $\bS''$ which is maximal with respect to the property that $\bS''$ contains $\bS'$, and intersects $\bM$ trivially. If one can do this, it is clear by construction that $\phi(\bS'')=\bQ$, and that $\bS'' \in \Spch(\bK^c)$. 

To apply \prref{cont-ideal-avoid-mult}, we simply need to verify that $\bM$ and $\bS'$ are disjoint. Suppose for the sake of contradiction that there is an object $C \in \bK^c \backslash \bQ$, such that $\hat C \in \bS'$. Consider the Serre ideal $\overline{\bS'} = \{ \overline{F} : F \in \bS'\} = \langle \overline{A} \in \overline{\bA} : A \in \bQ \rangle$ 
of the noncommutative homological residue field
$\overline{\bA}$. 
Note that for any object $\overline{F}$ of $\overline{\bS}'$, we have $\overline{\Gamma_{\bQ} \unit} \otimes \overline{F} \cong 0$, since $\Gamma_{\bQ} \unit \otimes A \cong 0$ for all $A \in \bQ$; since $\Gamma_{\bQ} \unit $ is idempotent, $\overline{\Gamma_{\bQ}\unit}$ cannot be in the localizing category generated by $\overline{\bS}'$. In particular, this means that $\widehat{\Gamma_{\bQ}\unit}$ cannot be in $\overrightarrow{\bS'}$. But indeed, $\Gamma_{\bQ} \unit$ is in $\Loc(\langle C \rangle)$: $\Loc(\langle C \rangle)$ is a tensor ideal, $\Gamma_{\mc{V}(\bQ)} \unit$ is in $\Loc(\Theta^B(\mc{V}(\bQ)))$, and $\Theta^B(\mc{V}(\bQ)) \subseteq \langle C \rangle$ by the assumption that $\bQ \in V^B(C)$. However, if $\Gamma_{\bQ} \unit$ is in $\Loc(\langle C \rangle)$, then it follows that $\widehat{\Gamma_{\bQ} \unit } \in \overrightarrow{\bS'}$, which is a contradiction. It follows that $\bS'$ is indeed disjoint from $\bM$, and we are done. 
\end{proof}

Theorems \ref{tthick-max} and \ref{tsupp-pureinj-2} imply the following corollary. 

\bco{supp-pureinj} Assume that $\Spc \bK^c$ is Noetherian.
\begin{enumerate}
\item[(a)] If $\bS$ is a maximal Serre ideal of $\moddash{\bK^c}$ with corresponding pure-injective $E_{\bS} \in \bK$,
then the Balmer--Favi support of $E_{\bS}$ is $\{\phi(\bS)\}$. 
\item[(b)] If all Serre primes in $\Spch(\bK^c)$ are maximal, then $\bK$ satisfies the Uniformity Hypothesis.
\item[(c)] In particular, if $\bK$ satisfies the Central Generation Hypothesis, then it satisfies the Uniformity Hypothesis.
\end{enumerate}
\eco

We will need the following tensor product property for pure-injectives to state the main result of this section; this tensor product property is likely of independent interest, since the tensor product property in monoidal triangulated categories has received significant attention in recent years.

\bpr{tpp-pureinj}
Suppose $\bK$ is stratified by $\Spc \bK^c$ and that $\Spc \bK^c$ is Noetherian. Let $\bS$ and $\bS'$ be two Serre ideals of $\moddash{\bK^c}$ with corresponding pure-injectives $E$ and $E'$. Then
\[V^{BF}(E' \otimes E) = V^{BF}(E) \cap V^{BF}(E').\]
\epr

\begin{proof}
    The containment $V^{BF}(E' \otimes E) \subseteq V^{BF}(E) \cap V^{BF}(E')$ holds by \cite[Proposition 3.8]{CaiVashaw}. For the reverse containment, suppose that $\bP \in V^{BF}(E) \cap V^{BF}(E'),$ that is, $\Gamma_{\bP} \unit \otimes E \not \cong 0$ and $\Gamma_{\bP} \unit \otimes E' \not \cong 0$. We must show that $\Gamma_{\bP} \unit \otimes E' \otimes E \not \cong 0$. Recall that $\Gamma_{\bP} \unit$ tensor-commutes with all objects of $\bK$ (see \cite[Lemma 3.2]{CaiVashaw}). By stratification, using the fact that $V^{BF}(\Gamma_{\bP} \unit) = \{\bP\}$ (\cite[Lemma 4.2, Lemma 4.3]{CaiVashaw}), it follows that $\Gamma_{\bP} \unit \in \Loc(E)$. By an analogous argument to \cite[Lemma 3.1.2]{NVY1}, it follows that
    \[
    \Gamma_{\bP} \unit \otimes E' \in \Loc(E \otimes A \otimes E' : A \in \bK).
    \]
    But since $\Gamma_{\bP} \unit \otimes \Gamma_{\bP} \unit \otimes E' \cong \Gamma_{\bP} \unit \otimes E' \not \cong 0$, it follows that there must be $A \in \bK$ such that $\Gamma_{\bP} \unit \otimes E \otimes A \otimes E' \not \cong 0.$ Using the fact that $\Gamma_{\bP} \unit$ commutes with all objects and the fact that $\ker(E \otimes -)=\ker(- \otimes E)$ from \thref{S-is-KerE}, it follows that $\Gamma_{\bP} \unit \otimes E' \otimes E \not \cong 0$, so we are done.
\end{proof}

\bco{max-loc-contain}
Suppose $\bK$ is stratified by $\Spc \bK^c$ and that $\Spc \bK^c$ is Noetherian. Let $\bS \in \Spch \bK^c$ with pure-injective $E$, and let $\bS'$ be a Serre prime in $\moddash{\bK^c}$ with pure-injective $E'$. Suppose $E \in \Loc(E')$. Then $\bS' \subseteq \bS$. 
\eco

\begin{proof}
    By \prref{tpp-pureinj}, $V^{BF}(E \otimes E')= V^{BF}(E).$ Set $\bS'':=\ker(\hat E \otimes \hat E' \otimes -)^{\fp}.$ By the stratification assumption, $\phi(\bS'')=\phi(\bS)$, since $E \otimes E'$ and $E$ generate the same localizing ideal of $\bK$. Note that from their definitions
    \[
    \overrightarrow{\bS''} \supseteq \overrightarrow{\bS} \cup \overrightarrow{\bS'},
    \]
    using the fact that $\ker(\hat E \otimes -) = \ker(- \otimes \hat E)$ from \thref{S-is-KerE}. But since $\bS \in \Spch(\bK^c)$ and is therefore maximal in the fiber of $\phi(\bS)$, it then follows that $\bS = \bS'',$ and consequently that $\bS' \subseteq \bS$.
\end{proof}


\bth{strat-nos}
    Suppose $\bK$ is stratified by $\Spc \bK^c$, satisfies the Uniformity Hypothesis from the introduction, and that $\Spc \bK^c$ is Noetherian.
    Then $\bK^c$ satisfies the Nerves of Steel Conjecture.
\eth

\begin{proof}
    Suppose $\bS$ and $\bS'$ are two Serre ideals maximal in the fiber of $\bP \in \Spc \bK^c$. Let $E$ and $E'$ be the pure-injectives corresponding to $\bS$ and $\bS'$, respectively. By \thref{supp-pureinj-2}, the Balmer--Favi support of $E$ consists precisely of the primes which live over $\bS$; by assumption, this is equal to the set of primes that live over $\bS'$, that is, the Balmer--Favi support of $E'$. By the stratification assumption, since the Balmer--Favi supports of $E$ and $E'$ coincide, we have $\Loc(E)=\Loc(E')$. This immediately implies by \coref{max-loc-contain} that 
    \[
    \overrightarrow{\bS} = \ker( \hat E \otimes -) = \ker(\hat E' \otimes -) = \overrightarrow{\bS'}.
    \]
    Hence, $\bP$ has a unique homological prime in its fiber, and so $\phi$ is a bijection.
\end{proof}

The following corollary generalizes \cite[Theorem 4.17]{BHS2023} from the symmetric case to the case where $\bK^c$ satisfies the central generation condition. It follows directly from 
\thref{strat-nos} and \coref{supp-pureinj}.

\bco{nos-central} Suppose $\bK$ is stratified by $\bK^c$, satisfies the Central Generation Hypothesis and
$\Spc \bK^c$ is Noetherian. Then the Nerves of Steel Conjecture holds for $\bK$.
\eco

%\begin{proof} The corollary follows from \thref{strat-nos} and \leref{thick-max}, since if $\bP \in \Spc \bK^c$ and $\bS \in \phi^{-1}(\bP)$, then since $\bS$ is maximal $\bP$ is the only prime living over $\bS$.
%\end{proof}
