We conclude this section with two observations about the
Boltzmann-on-multisets distribution, namely that it is stable under
reversal and that it can be obtained as image distribution from a
uniform distribution on sequences (microstates). In order to express
this we need the functoriality of both $\Dst$ and $\natMlt$.


\begin{lemma}
\label{BoltzmannMltLem}
Fix numbers $N \geq 1$ and $K\geq 0$.
\begin{enumerate}
\item \label{BoltzmannMltLemRev} The Boltzmann-on-multisets
  distribution~\eqref{BoltzmannMltEqn} is stable under reversal as
  expressed by the following commuting diagram, using the revert
  isomorphism from Lemma~\ref{RevertLem}.
\[ \xymatrix@R-0.8pc@C+1pc{
\{0,1,\ldots,(N\minnetje 1)\cdot K\}\ar[d]_-{\revert_{(N-1)\cdot K}}^-{\cong}
   \ar[rr]^-{\boltzmannmlt[N, K]} & &
   \Dst\Big(\natMlt[K](\finset{N})\Big)
   \ar[d]^-{\Dst\natMlt(\revert_{N-1})}_-{\cong}
\\
\{0,1,\ldots,(N\minnetje 1)\cdot K\}\ar[rr]^-{\boltzmannmlt[N, K]} & &
   \Dst\Big(\natMlt[K](\finset{N})\Big)
} \]
%% \[ \begin{array}{rcl}
%% \Dst\natMlt(\revert_{N-1})\Big(\boltzmannmlt[N, K](i)\Big) 
%% & = &
%% \boltzmannmlt[N,K]\Big((N\minnetje 1)\cdot K - i\Big).
%% \end{array} \]

\item \label{BoltzmannMltLemIm} For a number $0 \leq i \leq
  (N\minnetje 1)\cdot K$, consider the set of sequences $S$ defined
  below, as in~\eqref{NnomialSeqEqn}, with the uniform distribution
  $\unif$ on it.
\[ \begin{array}{rclcrcl}
S
& \coloneqq &
\bigsetin{v}{\finset{N}^{K}}{\som(v) = i}
& \qquad\qquad &
\unif
& \coloneqq &
\displaystyle\sum_{v\in S} \, \frac{1}{C_{N}(K,i)}\,\bigket{v}.
\end{array} \]

\noindent Then: $\Dst(\acc)(\unif) = \boltzmannmlt[N,K](i)$.
\end{enumerate}
\end{lemma}


\begin{myproof}
\begin{enumerate}
\item We use the closure of $N$-nomials under reversal from
Proposition~\ref{NnomialMltProp}~\eqref{NnomialMltPropRev}, and also
the commutation of $\revert$ with sums~\eqref{RevertSumDiag},
where we wrote $\Revert_{N-1}(\varphi) = \natMlt(\revert_{N-1})(\varphi)$.
\[ \begin{array}[b]{rcl}
\lefteqn{\Dst\natMlt(\revert_{N-1})\Big(\boltzmannmlt[N,K](i)\Big)}
\\[0.2em]
& \smash{\stackrel{\eqref{BoltzmannMltEqn}}{=}} &
\displaystyle\sum_{\varphi\in\natMlt[K](\finset{N}), \, \som(\varphi) = i} \,
   \frac{\coefm{\varphi}}{C_{N}(K,i)}\,\bigket{\natMlt(\revert_{N-1})(\varphi)}
\\[+1em]
& = &
\displaystyle\sum_{\varphi\in\natMlt[K](\finset{N}), \, 
   \som(\natMlt(\revert_{N-1})(\varphi)) = i} \,
   \frac{\coefm{\natMlt(\revert_{K})(\varphi)}}{C_{N}(K,i)}\,\bigket{\varphi}
\\[+1em]
& = &
\displaystyle\sum_{\varphi\in\natMlt[K](\finset{N}), \, \som(\varphi) = (N-1)\cdot K - i} \,
   \frac{\coefm{\varphi}}{C_{N}(K, (N\minnetje 1)\cdot K - i)}\,\bigket{\varphi}
\\[+1.2em]
& = &
\boltzmannmlt[N,K]\Big((N\minnetje 1)\cdot K - i\Big)
\hspace*{\arraycolsep}=\hspace*{\arraycolsep}
\boltzmannmlt[N,K]\Big(\revert_{(N\minnetje 1)\cdot K}(i)\Big).
\end{array} \]

\item Since:
\[ \begin{array}[b]{rcl}
\Dst(\acc)(\unif)
& = &
\displaystyle\sum_{v\in S} \, \frac{1}{C_{N}(K,i)} \, \bigket{\acc(v)}
\\
& = &
\displaystyle\sum_{\varphi\in\natMlt[K,i](\finset{N})} \;
   \sum_{v\in\acc^{-1}(\varphi)} \, \frac{1}{C_{N}(K,i)} \, \bigket{\acc(v)}
\\[+1em]
& = &
\displaystyle\sum_{\varphi\in\natMlt[K,i](\finset{N})} \;
   \sum_{v\in\acc^{-1}(\varphi)} \, \frac{1}{C_{N}(K,i)} \, \bigket{\varphi}
\\[+1em]
& = &
\displaystyle\sum_{\varphi\in\natMlt[K,i](\finset{N})} \,
   \frac{\coefm{\varphi}}{C_{N}(K,i)} \, \bigket{\varphi}
   \qquad \mbox{by Lemma~\ref{MltLem}~\eqref{MltLemAcc}}
\\[+0.8em]
& = &
\boltzmannmlt[N,K](i)
\end{array} \eqno{\square} \]

\end{enumerate}
\end{myproof}


