\section{The Boltzmann distribution on numbers}\label{BoltzmannNumSec}

We now transform the Boltzmann-on-multisets distribution
$\boltzmannmlt$ into a `Boltzmann-on-numbers' distribution
$\boltzmannnum$. In physical terms, it describes the spread of
particles over the various energy levels $\{0,\ldots,N\minnetje
1\}$. There is a systematic way to do this transformation, via
frequentist learning $\flrn$ from~\eqref{FlrnEqn}. The triangle below
defines $\boltzmannnum$ as composition of two functions.
\begin{equation}
\label{BoltzmannNumDiag}
\vcenter{\xymatrix@R-1pc{
& & \Dst\Big(\natMlt[K](\finset{N})\Big)\ar[dd]^-{\flrn_{*}}
\\
\big\{0,\ldots,(N\minnetje 1)\cdot K\big\}
   \ar@/^3ex/[urr]^-{\boltzmannmlt[N,K]}
   \ar@/_3ex/[drr]_-{\boltzmannnum[N,K]} & &
\\
& & \Dst\big(\finset{N}\big)\rlap{$\;= \Dst\big(\{0,\ldots,N\minnetje 1\}\big)$}
}}\hspace*{5em}
\end{equation}

\noindent The diagram contains the pushforward $\flrn_{*} \colon
\Dst\big(\natMlt[K](X)\big) \rightarrow \Dst(X)$ of the frequentist
learning channel $\flrn \colon \natMlt[K](X) \rightarrow \Dst(X)$, as
introduced in~\eqref{PushEqn}. As a consequence,
$\boltzmannnum[N,K](i)$ gives the energy for a randomly chosen
particle.

The next definition gives both an abstract and a concrete formulation
of the Boltz\-mann-on-numbers distribution, so the above triangle serves
only as background information.


\begin{definition}
\label{BoltzmannNumDef}
For numbers $N,K\geq 1$ and $0\leq i\leq (N\minnetje 1)\cdot K$ we
define the Boltzmann-on-numbers distribution as:
\begin{equation}
\label{BoltzmannNumEqn}
\begin{array}{rcl}
\boltzmannnum[N, K](i)
& \coloneqq &
\flrn_{*}\Big(\boltzmannmlt[N, K](i)\Big)
\\[+0.6em]
& = &
\displaystyle\sum_{0\leq j < N} \, 
   \sum_{\varphi\in\natMlt[K,i](\finset{N})} \,
   \frac{\coefm{\varphi}\cdot \varphi(j)}{C_{N}(K,i) \cdot K}
   \,\bigket{j}.
\end{array}
\end{equation}

\noindent A subtle point is that if $i < N$, then we can limit the sum
over $j$ to $j \leq i$, since if $\som(\varphi) = i$, then $\varphi(j)
= 0$ for $j > i$. We can make this explicit by letting $j$ range over
$0 \leq j < \min(N, i+1)$. The next section concentrates on this
special case $i < N$.
\end{definition}


We double-check that the probabilities in~\eqref{BoltzmannNumEqn} add
up to one:
\[ \begin{array}{rcl}
\displaystyle \sum_{0\leq j < N} \, 
   \sum_{\varphi\in\natMlt[K,i](\finset{N})} \,
   \frac{\coefm{\varphi}\cdot \varphi(j)}{C_{N}(K,i) \cdot K}
& = &
\displaystyle 
   \sum_{\varphi\in\natMlt[K,i](\finset{N})} \,
   \frac{\coefm{\varphi}\cdot \sum_{0\leq j < N}\varphi(j)}{C_{N}(K,i) \cdot K}
\\[+1em]
& = &
\displaystyle \sum_{\varphi\in\natMlt[K,i](\finset{N})} \,
   \frac{\coefm{\varphi}\cdot \|\varphi\|}{C_{N}(K,i) \cdot K}
\\[+1em]
& = &
\displaystyle \sum_{\varphi\in\natMlt[K,i](\finset{N})} \,
   \frac{\coefm{\varphi}}{C_{N}(K,i)}
\hspace*{\arraycolsep}\smash{\stackrel{\eqref{NnomialMltEqn}}{=}}\hspace*{\arraycolsep}
1.
\end{array} \]



\begin{example}
\label{PhysicsNumEx}
In the context of Example~\ref{PhysicsMltEx}, the associated
Boltzmann-on-numbers distribution will be computed in two ways.
First we shall use the formulation via the extension
$\flrn_*$ of frequentist learning --- as used in the
middle of~\eqref{BoltzmannNumEqn} --- to illustrate how this works.
\[ \begin{array}{rcl}
\lefteqn{\boltzmannnum[4, 4](3)}
\\
& \smash{\stackrel{\eqref{BoltzmannNumEqn}}{=}} &
\flrn_{*}\Big(\boltzmannmlt[4, 4](3)\Big)
\\
& \smash{\stackrel{\eqref{BoltzmannMltEisberg}}{=}} &
\flrn_{*}\Big(\frac{1}{5}\Bigket{3\ket{0} + 1\ket{3}} + 
   \frac{3}{5}\Bigket{2\ket{0} + 1\ket{1} + 1\ket{2}} +
   \frac{1}{5}\Bigket{1\ket{0} + 3\ket{1}}\Big)
\\[+0.2em]
& \smash{\stackrel{\eqref{PushEqn}}{=}} &
\frac{1}{5}\cdot\flrn\Big(3\ket{0} + 1\ket{3}\Big) + 
   \frac{3}{5}\cdot \flrn\Big(2\ket{0} + 1\ket{1} + 1\ket{2}\Big) +
   \frac{1}{5}\cdot \flrn\Big(1\ket{0} + 3\ket{1}\Big)
\\[+0.2em]
& = &
\frac{1}{5}\cdot\Big(\frac{3}{4}\ket{0} + \frac{1}{4}\ket{3}\Big) + 
   \frac{3}{5}\cdot \Big(\frac{1}{2}\ket{0} + 
      \frac{1}{4}\ket{1} + \frac{1}{4}\ket{2}\Big) +
   \frac{1}{5}\cdot \Big(\frac{1}{4}\ket{0} + \frac{3}{4}\ket{1}\Big)
\\[+0.2em]
& = &
\Big(\frac{1}{5}\cdot\frac{3}{4} + 
   \frac{3}{5}\cdot \frac{1}{2} + 
   \frac{1}{5}\cdot \frac{1}{4}\Big)\ket{0} +
\Big(\frac{3}{5}\cdot \frac{1}{4} + 
   \frac{1}{5}\cdot \frac{3}{4}\Big)\ket{1} +
\frac{3}{5}\cdot \frac{1}{4}\ket{2} + 
\frac{1}{5}\cdot \frac{1}{4}\ket{3}
\\[+0.2em]
& = &
\frac{1}{2}\bigket{0} + \frac{3}{10}\bigket{1} + 
   \frac{3}{20}\bigket{2} + \frac{1}{20}\bigket{3}.
\end{array} \]

\noindent We also elaborate the formulation on the
right-hand-side of~\eqref{BoltzmannNumEqn}.
\[ \begin{array}{rcl}
\lefteqn{\boltzmannnum[4, 4](3)}
\\
& \smash{\stackrel{\eqref{BoltzmannNumEqn}}{=}} &
\displaystyle\sum_{0\leq j < 4} \, 
   \sum_{\varphi\in\natMlt[4,3](\finset{4})} \,
   \frac{\coefm{\varphi}\cdot \varphi(j)}{C_{N}(K,i) \cdot K}
   \,\bigket{j}
\\[+1.4em]
& = &
\displaystyle\frac{4\cdot 3 + 12\cdot 2 + 4\cdot 1}{4\cdot 20}\bigket{0}
   + \frac{12\cdot 1 + 4\cdot 3}{4\cdot 20}\bigket{1}
   + \frac{12\cdot 1}{4\cdot 20}\bigket{2}
   + \frac{4\cdot 1}{4\cdot 20}\bigket{3}
   + \frac{0}{4\cdot 20}\bigket{4}
\\[+0.6em]
& = &
\frac{1}{2}\bigket{0} + \frac{3}{10}\bigket{1} + 
   \frac{3}{20}\bigket{2} + \frac{1}{20}\bigket{3}.
\end{array} \]

\noindent The calculations in the second line, matching the table in
Example~\ref{PhysicsMltEx}, are performed concretely
in~\cite[Appendix~C]{EisbergR85}, but without a general formula, as
in~\eqref{BoltzmannNumEqn}.
\end{example}


