We continue with basic properties of the Boltzmann-on-numbers
distribution. The first point describes the symmetry that is clearly
visible in Figure~\ref{BoltzmannNumIterFig}.


\begin{lemma}
\label{BoltzmannNumLem}
Fix numbers $N,K\geq 1$ and $0\leq i\leq (N\minnetje 1)\cdot K$.
\begin{enumerate}
\item \label{BoltzmannNumLemRevNum} The Boltzmann-on-numbers 
distribution is stable under reversal.
\[ \xymatrix@R-0.8pc@C+1pc{
\{0,1,\ldots,(N\minnetje 1)\cdot K\}\ar[d]_-{\revert_{(N-1)\cdot K}}^-{\cong}
   \ar[rr]^-{\boltzmannnum[N, K]} & &
   \Dst\big(\finset{N}\big)
   \ar[d]^-{\Dst(\revert_{N-1})}_-{\cong}
\\
\{0,1,\ldots,(N\minnetje 1)\cdot K\}\ar[rr]^-{\boltzmannnum[N, K]} & &
   \Dst\big(\finset{N}\big)
} \]
%% \[ \begin{array}{rcl}
%% \Dst(\revert_{N-1})\Big(\boltzmannnum[N, K](i)\Big)
%% & = &
%% \boltzmannnum[N, K]\Big((N\minnetje 1)\cdot K - i\Big).
%% \end{array} \]

\item \label{BoltzmannNumLemMean} The mean of the Boltzmann-on-numbers 
distribution is $\frac{i}{K}$, independently of $N$:
\[ \begin{array}{rcl}
\mean\Big(\boltzmannnum[N, K](i)\Big)
& = &
\displaystyle\frac{i}{K}.
\end{array} \]
\end{enumerate}
\end{lemma}


\begin{myproof}
\begin{enumerate}
\item An abstract way to prove the statement, in the style of category
  theory, is to show first that the following `naturality' diagram
  commutes, and then use
  Lemma~\ref{BoltzmannMltLem}~\eqref{BoltzmannMltLemRev}.
\[ \vcenter{\xymatrix@R-0.8pc{
\Dst\Big(\natMlt[K](\finset{N})\Big)
   \ar[rr]^-{\flrn_*}\ar[d]_-{\Dst\natMlt(\revert_{N-1})}^-{\cong} 
   & &
   \Dst\big(\finset{N}\big)\ar[d]^-{\Dst(\revert_{N-1})}_-{\cong}
\\
\Dst\Big(\natMlt[K](\finset{N})\Big)\ar[rr]^-{\flrn_*} & &
   \Dst\big(\finset{N}\big)
}} \]

\noindent Alternatively, one can reason more concretely, like in the
proof of Lemma~\ref{BoltzmannMltLem}~\eqref{BoltzmannMltLemRev}:
\[ \begin{array}{rcl}
\lefteqn{\Dst(\revert_{N-1})\Big(\boltzmannnum[N, K](i)\Big)}
\\[+0.2em]
& \smash{\stackrel{\eqref{BoltzmannNumEqn}}{=}} &
\displaystyle\sum_{0\leq j < N} \, 
   \sum_{\varphi\in\natMlt[K](\finset{N}), \, \som(\varphi) = i} \,
   \frac{\coefm{\varphi}\cdot \varphi(j)}{C_{N}(K,i) \cdot K}
   \,\bigket{\revert_{N-1}(j)}
\\[+1em]
& = &
\displaystyle\sum_{0\leq j < N} \, 
   \sum_{\varphi\in\natMlt[K](\finset{N}), \, 
   \som(\natMlt(\revert_{N-1}(\varphi))) = i} \,
\\[+1.4em]
& & \hspace*{10em}\displaystyle
   \frac{\coefm{\natMlt(\revert_{N-1}(\varphi)}\cdot 
   \natMlt(\revert_{N-1}(\varphi))(j)}{C_{N}(K,i) \cdot K}
   \,\bigket{\revert_{N-1}(j)}
\\[+1em]
& = &
\displaystyle\sum_{0\leq j < N} \, 
   \sum_{\varphi\in\natMlt[K](\finset{N}), \, 
   \som(\varphi) = (N-1)\cdot K - i} \,
   \frac{\coefm{\varphi}\cdot 
   \varphi(\revert_{N-1}(j))}{K \cdot C_{N}(K,(N\minnetje 1)\cdot K - i)}
   \,\bigket{\revert_{N-1}(j)}
\\[+1em]
& = &
\displaystyle\sum_{0\leq j < N} \, 
   \sum_{\varphi\in\natMlt[K](\finset{N}), \, 
   \som(\varphi) = (N-1)\cdot K - i} \, \frac{\coefm{\varphi}\cdot 
   \varphi(j)}{K \cdot C_{N}(K,(N\minnetje 1)\cdot K - i)}
   \,\bigket{j}
\\[+1.2em]
& = &
\boltzmannnum[N, K]\Big((N\minnetje 1)\cdot K - i\Big).
\end{array} \]

\item We recall that the mean of a distribution
  $\omega\in\Dst(\finset{N})$ is defined as: $\mean(\omega) \coloneqq
  \sum_{j} \omega(j)\cdot j$.  This is applied to the
  Boltzmann-on-numbers distribution~\eqref{BoltzmannNumEqn}:
\[ \begin{array}[b]{rcl}
\mean\Big(\boltzmannnum[N, K](i)\Big)
& = &
\displaystyle\sum_{0\leq j < N} \, 
   \sum_{\varphi\in\natMlt[K,i](\finset{N})} \,
   \frac{\coefm{\varphi}\cdot \varphi(j)}{C_{N}(K,i) \cdot K}\cdot j
\\[+1.2em]
& = &
\displaystyle \sum_{\varphi\in\natMlt[K,i](\finset{N})} \,
   \frac{\coefm{\varphi}\cdot \sum_{0\leq j< N}\varphi(j) \cdot j}
   {C_{N}(K,i) \cdot K}
\\[+1.0em]
& = &
\displaystyle \sum_{\varphi\in\natMlt[K,i](\finset{N})} \,
   \frac{\coefm{\varphi}\cdot \som(\varphi)}{C_{N}(K,i) \cdot K}
\\[+1.0em]
& = &
\displaystyle \sum_{\varphi\in\natMlt[K,i](\finset{N})} \,
   \frac{\coefm{\varphi}\cdot i}{C_{N}(K,i) \cdot K}
\\[+1.4em]
& \smash{\stackrel{\eqref{NnomialMltEqn}}{=}} &
\displaystyle \frac{C_{N}(K,i) \cdot i}{C_{N}(K,i) \cdot K}
\hspace*{\arraycolsep}=\hspace*{\arraycolsep}
\frac{i}{K}.
\end{array} \eqno{\square} \]
\end{enumerate}
\end{myproof}



We conclude this section with two alternative formulations of the
Boltzmann-on-numbers distributions. The second point below show that
this distribution can be obtained directly from the uniform
distribution on sequences (microstates), without considering any
multisets (macrostates).



\begin{proposition}
\label{BoltzmannNumAltProp}
let $N\geq 1$ and $K\geq 0$ with $0\leq i \leq (N\minnetje 1)\cdot K$.
\begin{enumerate}
\item \label{BoltzmannNumAltPropNom} The Boltzmann-on-numbers
  distribution can be expressed purely in terms of $N$-nomials:
\begin{equation}
\label{BoltzmannNumAltPropNomEqn}
\begin{array}{rcl}
\boltzmannnum[N,K](i)
& = &
\displaystyle\sum_{0\leq j < \min(N,i+1)} \, \frac{C_{N}(K-1, i-j)}{C_{N}(K,i)}
   \,\bigket{j}.
\end{array}
\end{equation}

\item \label{BoltzmannNumAltPropProj} Recall the set $S\subseteq
  \finset{N}^{K}$ with the uniform distribution distribution
  $\unif\in\Dst(S)$ from
  Lemma~\ref{BoltzmannMltLem}~\eqref{BoltzmannMltLemIm}. For any $0
  \leq n < N$ let $\pi_{n} \colon \finset{N}^{K} \rightarrow
  \finset{N}$ be the $n$-th projection from a sequence: $\pi_{n}(v) =
  v_{n}$. Then, for each $n$,
\[ \begin{array}{rcl}
\Dst\big(\pi_{n}\big)(\unif)
& = &
\boltzmannnum[N,K](i).
\end{array} \]

