\section{The Boltzmann distribution on energy levels}\label{BoltzmannEneSec}

As we briefly discussed above, physicists see the Boltzmann-on-numbers
distribution $\boltzmannnum[N, K](i)$ as a distribution on energy
levels $\{0,\ldots,N\minnetje 1\} = \finset{N}$, arising from $K$
particles with total energy $i$. The pictures that they look at
typically have shapes as in the top row of
Figure~\ref{BoltzmannNumIterFig}. They see the number $N$ of energy
levels as a number that can go to infinity, in order to get an
approximation of a continuous distribution, see
Subsection~\ref{BoltzmannApproxSubsec} for an impression. Here the
focus is not such approximation, but on the precise form of the
relevant discrete probability distributions.  So far we used a
constraint on the number $i$ of the form $0 \leq i \leq (N\minnetje
1)\cdot K$. It turns out that the constructions that we used so far
can be simplified when we assume $i < N$. This is a crucial
observation, elaborated in the theorem below.  The assumption $i < N$
makes sense, when $N$ is seen as a number that can become arbitrarily
big.


\begin{theorem}
\label{BelowThm}
Consider numbers $N,K \geq 1$.
\begin{enumerate}
\item \label{BelowThmSum} For $0 \leq n \leq N$,
\[ \begin{array}{rcl}
\displaystyle \sum_{0\leq i < n} \, C_{N}(K,i)
& = &
\displaystyle\frac{n}{K}\cdot\bibinom{K}{n}.
\end{array} \]

\noindent The right-hand-side does not depend on $N$, intuitively because
if $\som(\vec{m})$ equals $i$, for $\vec{m} \in \finset{N}^{K}$ where
$i \leq n < N$, then the number $N$ is big enough to so that the
requirement $m_{j} \in \finset{N}$ does not impose any restriction.

\item \label{BelowThmNomial} When $i < N$, there is a simple formula
for the $N$-nomial, namely:
\[ \begin{array}{rcl}
C_{N}(K,i)
& = &
\displaystyle\bibinom{K}{i}.
\end{array} \]
\end{enumerate}
\end{theorem}


\begin{myproof}
\begin{enumerate}
\item By induction on $K\geq 1$. First,
\[ \begin{array}{rcl}
\displaystyle \sum_{0\leq i\leq n} \, C_{N}(1,i)
\hspace*{\arraycolsep}\smash{\stackrel{\eqref{NnomialSeqEqn}}{=}}\hspace*{\arraycolsep}
\sum_{0\leq i\leq n} \, 
   \Bigsetsize{\bigsetin{\vec{n}}{\finset{N}^{1}}{\som(\vec{n}) = i}}
& = &
\displaystyle \sum_{0\leq i\leq n} \, 1
\\
& = &
n
\hspace*{\arraycolsep}=\hspace*{\arraycolsep}
\displaystyle\frac{n}{1}\cdot\bibinom{1}{n}.
\end{array} \]

\noindent Next we use that we sum over $i < n \leq N$ in the first
line below. When we count sequences of length $K\plusje 1$ with sum $i
< n$, then all elements of the sequence fit in the set $\finset{N} =
\{0,\ldots,N\minnetje 1\}$; hence we can express the number
$C_{N}(K\plusje 1, i)$ of sequences of length $K\plusje 1$ as sum of
numbers of sequences of length $K$.
\[ \begin{array}{rcl}
\displaystyle \sum_{0\leq i < n} \, C_{N}\big(K+1,i\big)
& = &
\displaystyle \sum_{0\leq i < n} \, \sum_{0\leq j \leq i} C_{N}\big(K,i-j\big)
\\[+1em]
& = &
\displaystyle \sum_{0\leq i < n} \, \sum_{0\leq j \leq i} C_{N}\big(K,j\big)
\\[+1.2em]
& \smash{\stackrel{\textrm{(IH)}}{=}} &
\displaystyle \displaystyle \sum_{0\leq i < n} \, 
   \frac{i+1}{K}\cdot\bibinom{K}{i+1}
\\[+1em]
& = &
\displaystyle \displaystyle \sum_{0\leq i < n} \, 
   \frac{i+1}{K}\cdot\frac{(K+i)!}{(K-1)!\cdot (i+1)!}
\\[+1em]
& = &
\displaystyle \displaystyle \sum_{1\leq i < n} \, \bibinom{K+1}{i}
\\[+1.2em]
& = &
\displaystyle\bibinom{n}{K+1} \qquad 
   \mbox{by Lemma~\ref{ChooseSumLem}~\eqref{ChooseSumLemZero}}
\\[+0.8em]
& = &
\displaystyle\frac{(K+n)!}{(n-1)!\cdot (K+1)!}
\hspace*{\arraycolsep}=\hspace*{\arraycolsep}
\frac{n}{K+1}\cdot\bibinom{K+1}{n}.
\end{array} \]

\item By the previous item, for $i < N$, so that $i\plusje 1 \leq N$,
\[ \hspace*{-0.6em}\begin{array}[b]{rcl}
C_{N}(K,i)
& = &
\displaystyle \left(\sum_{0\leq j < i+1} \, C_{N}\big(K,j\big)\right)
  - \left(\sum_{0\leq j < i} \, C_{N}\big(K,j\big)\right)
\\[+1.4em]
& = &
\displaystyle\frac{i+1}{K}\cdot\bibinom{K}{i+1} -
   \frac{i}{K}\cdot\bibinom{K}{i}
\\[+1em]
& = &
\displaystyle\frac{(K+i)!}{K!\cdot i!} - \frac{(K+i-1)!}{K!\cdot (i-1)!}
\\[+1em]
& = &
\displaystyle\frac{(K+i-1)!}{K!\cdot (i-1)!} \cdot 
   \left(\frac{K+i}{i} - 1\right)
\hspace*{\arraycolsep}=\hspace*{\arraycolsep}
\displaystyle\frac{(K+i-1)!}{(K-1)!\cdot i!}
\hspace*{\arraycolsep}=\hspace*{\arraycolsep}
\displaystyle\bibinom{K}{i}\!.
\end{array} \eqno{\square} \]
\end{enumerate}
\end{myproof}


We finally define the Boltzmann-on-energy distribution, as a a
distribution on energy levels, via the simplifications from the
previous theorem. To emphasise that we consider the number $i$ as the
total energy we shall now rename it to $e$.


\begin{definition}
\label{BoltzmannEneDef}
Let natural numbers $E \geq 1$ and $K \geq 2$ be given, where $K$
stands for the number of particles and $E$ for the maximal / total
energy. We define the Boltzmann-on-energy function $\boltzmannene[E]
\colon \setin{K}{\NNO}{K\geq 2} \rightarrow \Dst\big(\{0,\ldots,
E\}\big)$ as:
\begin{equation}
\label{BoltzmannEneEqn}
\begin{array}{rcl}
\boltzmannene[E](K)
\hspace*{\arraycolsep}\coloneqq\hspace*{\arraycolsep}
\boltzmannnum\big[E\plusje 1, K\big](E)
& = &
\displaystyle\sum_{0\leq j \leq E} \, 
      \frac{\big(\binom{K-1}{E-j}\big)}{\big(\binom{K}{E}\big)}\,\bigket{j}.
\end{array}
\end{equation}
\end{definition}


Notice that in the Boltzmann-on-numbers distribution in the middle
of~\eqref{BoltzmannEneEqn} we use $N = E+1$ and $i = E$, so that
condition $i < N$ from Theorem~\ref{BelowThm} holds by construction.
This justifies the simple form at the right-hand-side
of~\eqref{BoltzmannEneEqn}, via
Proposition~\ref{BoltzmannNumAltProp}~\eqref{BoltzmannNumAltPropNom}
and Theorem~\ref{BelowThm}~\eqref{BelowThmNomial}:
\[ \begin{array}[b]{rcl}
\boltzmannene[E](K)
\hspace*{\arraycolsep}=\hspace*{\arraycolsep}
\boltzmannnum\big[E\plusje 1, K\big](E)
& \smash{\stackrel{\eqref{BoltzmannNumAltPropNomEqn}}{=}} &
\displaystyle\sum_{0\leq j < \min(E+1,E+1)} \, \frac{C_{N}(K-1, E-j)}{C_{N}(K,E)}
   \,\bigket{j}.
\\[+1.2em]
& = &
\displaystyle\sum_{0\leq j \leq E} \, 
      \frac{\big(\binom{K-1}{E-j}\big)}{\big(\binom{K}{E}\big)}\,\bigket{j}.
\end{array} \]


\noindent Figure~\ref{BoltzmannEneIterFig} gives a systematic
description of these Boltzmann-on-energy distributions. But we also
(re-)elaborate our running example.


