\begin{proposition}
\label{BoltzmannEneProp}
Let $E\geq 1$ and $K \geq 2$.
\begin{enumerate}
\item \label{BoltzmannEnePropUnif} For $K=2$ particles the
  Boltzmann-on-energy distribution is uniform, of the form:
\[ \begin{array}{rcl}
\boltzmannene[E](2)
& = &
\displaystyle\sum_{0\leq j\leq E} \, \frac{1}{E+1} \, \bigket{j}.
\end{array} \]

\item \label{BoltzmannEnePropMean} The mean of the Boltzmann-on-energy
  distribution is given by:
\[ \begin{array}{rcl}
\mean\Big(\boltzmannene[E](K)\Big)
& = &
\displaystyle\frac{E}{K}.
\end{array} \]

\item \label{BoltzmannEnePropVar} And its variance is:
\[ \begin{array}{rcl}
\Var\Big(\boltzmannene[E](K)\Big)
& = &
\displaystyle\frac{E\cdot (E+K)\cdot (K-1)}{K^{2}\cdot (K+1)}.
\end{array} \]
\end{enumerate}
\end{proposition}



\begin{myproof}
\begin{enumerate}
\item For each $0\leq j\leq e$ one has:
\[ \begin{array}{rcccccl}
\boltzmannene[E](2)(j)
& = &
\displaystyle\frac{\big(\binom{2-1}{E-j}\big)}{\big(\binom{2}{E}\big)}
& = &
\displaystyle\frac{\frac{(E-j)!}{0!\cdot (E-j)!}}
   {\frac{(e+1)!}{1!\cdot e!}}
& = &
\displaystyle\frac{1}{E+1}.
\end{array} \]

\item The equation about the mean is obtained from
  Lemma~\ref{BoltzmannNumLem}~\eqref{BoltzmannNumLemMean}, since:
\[ \begin{array}{rcccl}
\mean\Big(\boltzmannene[E](K)\Big)
& \smash{\stackrel{\eqref{BoltzmannEneEqn}}{=}} &
\mean\Big(\boltzmannnum\big[E\plusje 1, K\big](E)\Big)
& = &
\displaystyle\frac{E}{K}.
\end{array} \]

\item Proving the variance equation is more work. We first
show that:
\[ \begin{array}{rcl}
\displaystyle\sum_{0\leq j \leq E} \, 
   \frac{\big(\binom{K-1}{E-j}\big)}{\big(\binom{K}{E}\big)} \cdot j^{2}
& = &
\displaystyle\frac{E\cdot (K-1+2E)}{K\cdot (K+1)}.
\end{array} \eqno{(*)} \]

\noindent Indeed:
\[ \hspace*{-0.5em}\begin{array}{rcl}
\lefteqn{\displaystyle\sum_{0\leq j \leq E} \, 
   \frac{\big(\binom{K-1}{E-j}\big)}{\big(\binom{K}{E}\big)} \cdot j^{2}}
\\[+0.6em]
& = &
\displaystyle\frac{1}{\big(\binom{K}{E}\big)} \cdot
   \sum_{0\leq j \leq E} \, \bibinom{K-1}{j} \cdot (E-j)^{2}
\\[+1.2em]
& = &
\displaystyle\frac{1}{\big(\binom{K}{E}\big)} \cdot \left[\,
   E^{2} \cdot \sum_{0\leq j \leq E} \, \bibinom{K-1}{j} -
   2E \cdot \sum_{0\leq j \leq E} \, \bibinom{K-1}{j} \cdot j \right.
\\
& & \hspace*{8em} + \; \displaystyle \left.
   \sum_{0\leq j \leq E} \, \bibinom{K-1}{j} \cdot j^{2} \, \right]
\\[+1.2em]
& = &
\displaystyle\frac{1}{\big(\binom{K}{E}\big)} \cdot \left[\,
   E^{2} \cdot \bibinom{E+1}{K-1} 
   - 2E\cdot (K\minnetje 1) \cdot \bibinom{E}{K} \right.
\\
& & \hspace*{8em} + \; \displaystyle \left.
   K\cdot (K\minnetje 1) \cdot \bibinom{E-1}{K+1} +
   (K\minnetje 1)\cdot \bibinom{E}{K} \, \right]
\\[+1.4em]
& = &
\displaystyle\frac{(K\minnetje 1)!\cdot E!}{(K\plusje E \minnetje 1)!} \cdot
   \left[\, E^{2}\cdot\frac{(K\plusje E \minnetje 1)!}
      {E!\cdot (K\minnetje 1)!}
   - (2E\minnetje 1)\cdot (K\minnetje 1) \cdot 
     \frac{(K\plusje E \minnetje 1)!}{(E\minnetje 1)!\cdot K!} \right.
\\[+0.8em]
& & \hspace*{8em} \displaystyle \left.
   +\; K\cdot (K\minnetje 1) \cdot 
     \frac{(K\plusje E \minnetje 1)!}{(E\minnetje 2)!\cdot (K\plusje 1)!}
   \,\right]
\\[+0.6em]
& = &
\displaystyle E^{2} 
   - \frac{E\cdot (2E \minnetje 1) \cdot (K \minnetje 1)}{K}
   + \frac{(K\minnetje 1)\cdot E \cdot (E \minnetje 1)}{K + 1}
\\[+0.8em]
& = &
\displaystyle\frac{E^{2}\cdot K^{2} \plusje E^{2}\cdot K \minnetje 2E\cdot K^{2}
   \plusje 2E^{2} \plusje E\cdot K^{2} \minnetje E \plusje E^{2} \cdot K^{2} 
   \minnetje E \cdot K^{2} \minnetje E^{2} \cdot K \plusje E \cdot K}
   {K\cdot (K+1)}
\\[+0.8em]
& = &
\displaystyle\frac{2E^{2} - E + E\cdot K}{K\cdot (K+1)}
\hspace*{\arraycolsep}=\hspace*{\arraycolsep}
\frac{E\cdot (K-1+2E)}{K\cdot (K+1)}.
\end{array} \]

\noindent Now we come to variance itself, using the description of the mean:
\[ \begin{array}[b]{rcl}
\Var\Big(\boltzmannene[E](K)\Big)
& = &
\displaystyle\sum_{0\leq j \leq E} \, 
   \frac{\big(\binom{K-1}{E-j}\big)}{\big(\binom{K}{E}\big)} \cdot j^{2} \;-\;
   \left(\sum_{0\leq j \leq E} \, 
   \frac{\big(\binom{K-1}{E-j}\big)}{\big(\binom{K}{E}\big)} \cdot j\right)^{2}
\\[+1.2em]
& \smash{\stackrel{(*)}{=}} &
\displaystyle\frac{E\cdot (K-1+2E)}{K\cdot (K+1)} - 
   \left(\frac{E}{K}\right)^{2}
\\[+0.8em]
& = &
\displaystyle\frac{e\cdot (K-1+2e) \cdot K - e^{2}\cdot (K+1)}{K^{2}\cdot (K+1)}
\\[+0.8em]
& = &
\displaystyle\frac{E\cdot (E+K)\cdot (K-1)}{K^{2}\cdot (K+1)}.
\end{array} \eqno{\square} \]
\end{enumerate}
\end{myproof}


\section{Final observations}\label{ObservationSec}

Having seen precise derivations of various discrete Boltzmann
distributions we lean back for some broader observations.  The style
of section is a bit less thorough and part of it may be elaborated
further in future publications.

\subsection{Approximations of the discrete Boltzmann 
   distributions}\label{BoltzmannApproxSubsec}

What is called the discrete or continuous Boltzmann distribution in
statistical mechanics is an approximation of what we have described
as the Boltzmann-on-energy distribution. We briefly sketch how this
can work, in several ways.

For total energy $E$ with $K$ particles the Boltzmann-on-energy
distribution $\boltzmannene[E](K)$ has mean $\mu \coloneqq \frac{E}{K}$,
see Proposition~\ref{BoltzmannEneProp}~\eqref{BoltzmannEnePropMean}.
We can look at the ratio between two successive probabilities, at
$j$ and at $j\plusje 1$. This gives, when we substitute $E = K\cdot \mu$,
\[ \begin{array}{rcl}
\displaystyle\frac{\boltzmannene[E](K)(j\plusje 1)}{\boltzmannene[E](K)(j)}
\hspace*{\arraycolsep}\smash{\stackrel{\eqref{BoltzmannEneEqn}}{=}}\hspace*{\arraycolsep}
\displaystyle\frac{\big(\binom{K-1}{E-(j+1)}\big)}{\big(\binom{K-1}{E-j}\big)}
& = &
\displaystyle\frac{(K+E-j-3)! \cdot (E-j)!}{(K+E-j-2)! \cdot (E-j-1)!}
\\[+1em]
& = &
\displaystyle\frac{E-j}{K+E-j-2}
\\[+0.8em]
& = &
\displaystyle\frac{K\cdot \mu-j}{K+K\cdot \mu-j-2}
  \;\xrightarrow{\quad K\rightarrow\infty\quad} \frac{\mu}{\mu+1}.
\end{array} \]

\noindent This suggests that we can use as approximation of the
Boltzmann-on-energy distribution, in presence of many particles, the
normalisation of:
\begin{equation}
\label{DiscIterApprox}
\sum_{0\leq j \leq E} \, \left(\frac{\mu}{\mu+1}\right)^{j}\,\bigket{j}
\end{equation}

\noindent Distributions with a constant ratio between successive
probabilities typically occur for (normalisations of) distributions
of the form $\sum_{j} e^{-b\cdot j} \ket{j}$, for a suitable constant
$b$. Indeed, the associated ratio is:
\[ \begin{array}{rcccl}
\displaystyle\frac{e^{-b\cdot (j+1)}}{e^{-b\cdot j}}
& = &
e^{-b\cdot (j+1) + b\cdot j}
& = &
e^{-b}.
\end{array} \]

\noindent In our Boltzmann-on-energy situation we can solve $e^{-b} =
\frac{\mu}{\mu + 1}$ and get:
\[ \begin{array}{rcccccccl}
b
& = &
\displaystyle -\ln\left(\frac{\mu}{\mu+1}\right)
& = &
\displaystyle \ln\left(\frac{\mu+1}{\mu}\right)
& = &
\displaystyle \ln\left(1 + \frac{1}{\mu}\right)
& \approx &
\displaystyle\frac{1}{\mu}.
\end{array} \]

\noindent The latter approximation is common for small
$\frac{1}{\mu}$, that is, for large $\mu$. We thus get as alternative
discrete approximation of the Boltzmann-on-energy distribution, the
normalisation of:
\begin{equation}
\label{DiscExpApprox}
\sum_{0\leq j \leq E} \, e^{-\frac{j}{\mu}}\,\bigket{j}
\end{equation}

The principle of maximum entropy introduced in~\cite{Jaynes57} is used
in statistical mechanics to derive the equilibrium distributions. We
sketch how this works in the current situation, with $N$ energy levels
and a given mean $\mu$. The aim is to find the distribution $\omega$
on $\{0,\ldots,E\}$ with $\mean(\omega) = \mu$ and maximum entropty
$-\sum_{i} \omega(i) \cdot \ln\big(\omega(i)\big)$. This can be done
via Lagrange's multiplier method, as described for a dice
in~\cite[Example~5.3]{DillB10}. We give an impression of how this
works.

Take as function:
\[ \begin{array}{rcl}
H\big(\vec{r}, \alpha, \beta\big)
& \coloneqq &
\displaystyle-\sum_{0\leq j \leq E} r_{j}\cdot\ln(r_{j}) - 
   \alpha\cdot\left(1 - \sum_{0\leq j \leq E} r_{j}\right) -
   \beta\cdot\left(\mu - \sum_{0\leq j \leq E} r_{j}\cdot j\right).
\end{array} \]

\auxproof{
The partial derivatives are:
\[ \begin{array}{rcl}
\displaystyle\frac{\partial H}{\partial r_{j}}\big(\vec{r}, \alpha, \beta\big)
& = &
-\ln(r_{j}) - 1 + \alpha + \beta\cdot j
\\[+1em]
\displaystyle\frac{\partial H}{\partial \alpha}\big(\vec{r}, \alpha, \beta\big)
& = &
\displaystyle 1 - \sum_{0\leq j \leq E} r_{j}
\\[+1em]
\displaystyle\frac{\partial H}{\partial \beta}\big(\vec{r}, \alpha, \beta\big)
& = &
\displaystyle 1 - \sum_{0\leq j \leq E} r_{j}\cdot j.
\end{array} \]
}

\noindent Taking partial derivatives and setting them to zero yields,
when we abbreviate $x = e^{\beta}$.
\[ \begin{array}{rcl}
1
& = &
\displaystyle \sum_{0\leq j \leq E}\, r_{j}
\hspace*{\arraycolsep}=\hspace*{\arraycolsep}
\displaystyle \sum_{0\leq j \leq E}\, e^{-1 + \alpha + \beta\cdot j}
\hspace*{\arraycolsep}=\hspace*{\arraycolsep}
\displaystyle \sum_{0\leq j \leq E}\, \frac{(e^{\beta})^{i}}{e^{1-\alpha}}
\hspace*{\arraycolsep}=\hspace*{\arraycolsep}
\displaystyle \sum_{0\leq j \leq E}\, \frac{x^{i}}{e^{1-\alpha}}
\\[+1em]
\mu
& = &
\displaystyle \sum_{0\leq j \leq E}\, r_{j}\cdot j
\hspace*{\arraycolsep}=\hspace*{\arraycolsep}
\displaystyle \sum_{0\leq j \leq E}\, e^{-1 + \alpha + \beta\cdot j}\cdot j
\hspace*{\arraycolsep}=\hspace*{\arraycolsep}
\displaystyle \sum_{0\leq j \leq E}\, \frac{(e^{\beta})^{j}\cdot j}{e^{1-\alpha}}
\hspace*{\arraycolsep}=\hspace*{\arraycolsep}
\displaystyle \sum_{0\leq j \leq E}\, \frac{x^{j} \cdot j}{e^{1-\alpha}}.
\end{array} \]

\noindent Subtracting the second line from $\mu$ times the first one,
and then multiplying with $e^{1-\alpha}$ yields a polynomial equation
of order $E$, namely:
\[ \begin{array}{rcl}
0
& = &
\displaystyle \sum_{0\leq j \leq E}\, x^{j} \cdot (i - \mu).
\end{array} \]

\noindent An approximate solution $s>0$ can be found, for instance via
the \pythoninline{nroots} function in \Python's \pythoninline{sympy}
library. We then get a distribution on $\{0,\ldots,E\}$ with mean
$\mu$ and with maximal entropy, as normalisation of:
\begin{equation}
\label{MaxEntropy}
\begin{array}{rcl}
\displaystyle\sum_{0\leq j \leq E} \, s^{j}\,\bigket{j}
& = &
\displaystyle\sum_{0\leq j \leq E} \, e^{-b\cdot j}\,\bigket{j}
   \quad\mbox{ for } b = -\ln(s).
\end{array} 
\end{equation}

\noindent Finally, the formulations~\eqref{DiscExpApprox}
(and~\eqref{MaxEntropy}) lead to a continuous approximation as
exponential with rate $\frac{1}{\mu}$, with probability densitiy
function (pdf) on $\pR$ given by:
\begin{equation}
\label{ContExpApprox}
\begin{array}{rcl}
j 
& \longmapsto &
\frac{1}{\mu} \cdot e^{-\frac{j}{\mu}}
\end{array}
\end{equation}

\noindent Figure~\ref{ApproxFig} gives an impression of these four
approximations~\eqref{DiscIterApprox} -- \eqref{ContExpApprox}. When
we look at the KL-divergences between the Boltzmann-on-energy
distribution and the three (discrete)
approximations~\eqref{DiscIterApprox} -- \eqref{MaxEntropy}, then the
last one performs slightly better --- in this example.

