def boltzmann_on_multiple_multisets(N, E, sizes, frac=False):
    """ levels, sizes and total_energies are natural multisets on
    the same space, where total_energies <= (L-1) * sizes, where L is
    the size of levels. """
    zero = zero_frac if frac else 0
    points = [ remove_singleton_tuple(x) for x in sizes.sp.iter_discrete() ]
    K = sizes.size_as_nat()
    out_sp = list_parallel_product( 
        [ multiset_space(sizes(x))(range_sp(N)) for x in points ])
    out_points = [ ms for ms in out_sp.iter_discrete() ]
    nom = nomial(N,K,E)
    probs = []
    for p in range(len(out_points)):
        ms = out_points[p]
        if sum([ ms[i].expectation() for i in range(len(points)) ]) == E:
            coefs = list_multiplication( 
                [ ms[i].coefficient() for i in range(len(points)) ])
            if frac:
                probs += [ Frac(coefs, nom) ]
            else:
                probs += [ coefs / nom ]
        else:
            probs += [ zero ]
    return DState(probs, out_sp, frac=frac)


