\title{Bordered contact invariants and half Giroux torsion}

\author{Hyunki Min}
\author{Konstantinos Varvarezos}

\address{Department of Mathematics \\ University of California \\ 520 Portola Plaza\\ Los Angeles, CA, United States, 90095}
\email{hkmin27@math.ucla.edu}
