then it has a period that is parallel to $a$-axis.
Such a periodic Sturmian lattice falls outside our 
interest in aperiodic lattices. From now on we assume the regularity:

\begin{definition}
\label{def:regular-SL}
A Sturmian lattice $\mathfrak{A}\cup \mathfrak{B}\cup \mathfrak{C}$ is \emph{regular} if
\begin{align*}
\bigl|(a(i+1) - a(i)) - (a(i'+1) - a(i'))\bigr|&\le 1,\\
\bigl|(b(j+1) - b(j)) - (b(j'+1) - b(j'))\bigr|&\le 1,\\
\bigl|(c(k+1) - c(k)) - (c(k'+1) - c(k'))\bigr|&\le 1
\end{align*}
hold for any integers $i, j, k, i', j', k'\in \Z$.
\end{definition}

\begin{prop}
For a Sturmian lattice $\mathfrak{A}\cup \mathfrak{B}\cup \mathfrak{C}$, the followings are equivalent:
\begin{enumerate}
\item
Lattice $\mathfrak{A}\cup \mathfrak{B}\cup \mathfrak{C}$ is regular.
\item
There exists $\kappa\ge1$ with
\begin{align*}
a(i+1)-a(i)&\in\{\kappa, \kappa+1\},\\
b(j+1)-b(j)&\in\{\kappa, \kappa+1\},\\
c(k+1)-c(k)&\in\{\kappa, \kappa+1\}
\end{align*}
for any integers $i, j, k$.
\end{enumerate}
\end{prop}

We call $\kappa\ge 1$ defined here the \emph{minimum width} of the regular Sturmian lattice.

\begin{proof}
$(2)\Rightarrow (1)$ is trivial.
Conversely, we assume (1) and set
\[
\kappa = \inf_{i, j, k\in \Z}
\bigl\{ a(i+1)-a(i),\ b(j+1)-b(j),\ c(k+1)-c(k)\bigr\}.
\]
to be the infimum of all gaps in a Sturmian lattice.
Notice that every gap may take a value in $\kappa + \Z_{\ge 0}$ by Propositions~\ref{prop:mutually-balanced}~and~\ref{prop:2-balanced}.
We may assume that $a(i+1) - a(i) = \kappa$ without loss of generality.
We claim that no gaps with width $\ge \kappa + 2$ must appear.
If one of them appears in $a$-direction, then it contradicts the regularity.
In the case for $b$- or $c$-direction, it violates Proposition~\ref{prop:mutually-balanced}. 
\end{proof}

Let $\A=\{0,1\}$ be the set of letters. Denote by $\A^*$ the monoid generated by $\A$ by concatenation with the identity $\lambda$: the empty word. 
Let $\A^{\Z}$ be the set of bi-infinite words generated by $\A$.
For $x=a_1a_2\cdots a_{\ell}\in \A^*$, 
denote by $|x|=\ell$ the length of a word, and $|w|_1$ be the number of occurrences of $1$ in $w$, which is called a \emph{height} of $w$. 
A word $u\in \A^*$ is a \emph{factor} of $w\in \A^*\cup \A^{\Z}$ if
$u$ appears as a subword of $w$, and we denote by $u\prec w$ (or $w\succ u$).
A word $w\in \A^*\cup \A^{\Z}$
is called \emph{$C$-balanced} if for all $u,v\prec w$ with $|u|=|v|$, we have 
\[
-C\le |u|_1-|v|_1 \le C.
\]
For a word $w=\cdots w_{-1}w_0w_1\cdots \in \A^{\Z}$, we denote by $w_{[a,b]}=w_{a}w_{a+1}\cdots w_b$, $w_{[-\infty,b]}= \cdots w_{b-1}w_b$ and
$w_{[a,\infty]}= w_{a}w_{a+1}\cdots$.
If $w\in \A^{\Z}$ is $C$-balanced, then it is plain to see that
there exists a limit
\[
\lim_{N\to \infty} \frac{\bigl|w_{[-N,N]}\bigr|_1}{2N+1}
\]
which is called the \emph{slope} of $w$.

A word $w\in \A^{\Z}$ is \emph{positive periodic}, if there exist $u\in \A^*$ and
$\ell\in \Z$
that
\[
w= w_{[-\infty,\ell]} uuu\cdots=
w_{[-\infty,\ell]} u^{\infty}.
\]
Similarly it is \emph{negative periodic} if 
\[
w= \cdots uuu w_{[\ell,\infty]}={}^{\infty}u w_{[\ell,\infty]}.
\]
A word $w\in \A^{\Z}$ is \emph{periodic} if there exists $u\in \A^*$ and
\[
w=\cdots uuu \cdots ={}^{\infty}u^{\infty}=u^{\Z}.
\]
By \cite[Lemma~6.2.2]{Fogg}, for a $1$-balanced word $w\in \A^{\Z}$, positive periodic implies negative periodic and vice versa.

A word $w=\cdots w_{-1}w_0w_1\cdots \in \A^{\Z}$ is \emph{lower mechanical} if there exists $\alpha, \rho\in \R$ that
%\emph{Sturmian}
%if there exists an irrational $\alpha$ 
%and $\rho\in \R$ that 
\[
w_n = \floor{(n+1)\alpha + \rho} - \floor{n\alpha + \rho}
\]
for all $n\in \Z$.
Similarly it is \emph{upper mechanical} if
\[
w_n = \ceil{(n+1)\alpha + \rho} - \ceil{n\alpha + \rho}
\]
for all $n\in \Z$.
A word $w$ is \emph{mechanical} if it is upper mechanical or lower mechanical, and $w$ is \emph{Sturmian} if it is a mechanical word with an irrational $\alpha$.
The theorem of Morse--Hedlund reads 
that a word $w\in \A^{\Z}$ is Sturmian if and only if
it is a $1$-balanced and not positive periodic. See \cite[Chapter~6]{Fogg}.

\begin{definition}
\label{def:SL-01}
For a regular Sturmian lattice, we define the bi-infinite words $(a_i), (b_j), (c_k)\in\A^\Z$ as follows:
\begin{align*}
a_i&= \begin{cases} 
0 & \text{if } a(i+1)-a(i)=\kappa,\\
1 & \text{if } a(i+1)-a(i)=\kappa+1,
\end{cases}\\
b_j&= \begin{cases}
0 & \text{if } b(j+1)-b(j)=\kappa,\\
1 & \text{if } b(j+1)-b(j)=\kappa+1,
\end{cases}\\
c_k&= \begin{cases}
0 & \text{if } c(k+1)-c(k)=\kappa,\\
1 & \text{if } c(k+1)-c(k)=\kappa+1.
\end{cases}
\end{align*}
\end{definition}

There is a relationship between the height of a factor in one direction and the spacing of the corresponding lines:
\begin{equation}
\label{Sp}
|a_{i}a_{i+1}\cdots a_{i+n-1}|_1 = \bigl(a(i+n)-a(i)\bigr) - n\kappa,
\end{equation}
and similarly for the other directions.

We say $x,y\in \A^{\Z}$ are {\it mutually balanced} if for any $u\prec x, v\prec y$ with $|u|=|v|$, we have
\[
-1\le |u|_1-|v|_1\le 1.
\]
One can easily see that if two $C$-balanced words $x, y\in \A^\Z$ are mutually balanced, then each slope of $x$ and $y$ coincide.

\begin{prop}
\label{prop:mutually-balanced2}
Any two of the bi-infinite words $(a_i), (b_j), (c_k)\in \A^\Z$ are mutually balanced.
\end{prop}

\begin{proof}
The proof is essentially the same as that of Proposition~\ref{prop:mutually-balanced}.
For example, to see that $(a_{i})$ and $(b_{j})$ are mutually balanced, it suffices to show that for any $i, j\in \Z$ and $n\in \N$,\[
-1\le
\abs{a_{[i, i+n-1]}}_{1} -
\abs{b_{[j, j+n-1]}}_{1}\le 1,
\]which is equivalent with\[
\bigl|(a(i+n) - a(i)) - (b(j+n) - b(j))\bigr|\in \{0, 1\}
\]by \eqref{Sp}.
We may apply (SL-2) to $(i+n, j, k), (i, j+n, k)\in V$.
\end{proof}

\begin{prop}
\label{prop:strictly-2-balanced}
Each of the bi-infinite words $(a_i), (b_j), (c_k)\in \A^\Z$ is $2$-balanced.  
Moreover, 
for bi-infinite words $(a_{i}), (b_{j}), (c_{k})\in \A^{\Z}$, 
if in one direction it is $2$-balanced but not $1$-balanced, then the bi-infinite words in the other two directions must be $1$-balanced periodic words.
\end{prop}

\begin{proof}
%By Proposition~\ref{mutually-balanced}, for all $n\in\mathbb{N}$ and for all $i,j,k\in\mathbb{Z}$, 
%\begin{align*}
%\left| (a(i+n)-a(i)) - (b(k+n)-b(k)) \right| &\le 1,\\[1ex]
%\left| (a(j+n)-a(j)) - (b(k+n)-b(k)) \right| &\le 1,\\[1ex]
%\therefore\quad \left| (a(i+n)-a(i)) - (a(j+n)-a(j)) \right| &\le 2.
%\end{align*}
%An analogous argument holds for the other directions.
To see the $2$-balancedness, we may use Proposition~\ref{prop:mutually-balanced2} and follow the discussion for Proposition~\ref{prop:2-balanced}.
%
The latter statement can be proved in essentially the same way as Proposition~\ref{prop:two-diff}.
%Furthermore, 
If for some $n\in\N$ and for some $i, i'\in\Z$ we have 
\[
\abs{a_{[i,i+n-1]}}_{1} -
\abs{a_{[i',i'+n-1]}}_{1} = 2,
\]
then for every $j\in \Z$ it follows that
\[
\abs{b_{[j,j+n-1]}}_{1} =
\abs{a_{[i,i+n-1]}}_{1} - 1 =
\abs{a_{[i',i'+n-1]}}_{1} + 1 = \text{constant}
\]
by Proposition~\ref{prop:mutually-balanced2}.
%Similarly, for every $k\in \Z$
%\[
%\abs{c_{[k,k+n-1]}}_{1} =
%\abs{a_{[i,i+n-1]}}_{1} - 1 =
%\abs{a_{[i',i'+n-1]}}_{1} + 1 = \text{constant}.
%\]
Thus, $(b_j)$ (similarly, and $(c_k)$) must be both periodic words.
\end{proof}

\begin{prop}\label{limit}
%For the bi-infinite words $(a_i), (b_j), (c_k)\in \A^\mathbb{Z}$, the slopes of the words tend to a limit as the word length increases indefinitely, and all three converge to the same value.
For the bi-infinite words $(a_i), (b_j), (c_k)\in \A^\mathbb{Z}$, the limits
\begin{align*}
\alpha_{a}&= \lim_{N\to \infty}
\frac{\abs{a_{[-N,N]}}_{1}}{2N + 1},&
\alpha_{b}&= \lim_{N\to \infty}
\frac{\abs{b_{[-N,N]}}_{1}}{2N + 1},&
\alpha_{c}&= \lim_{N\to \infty}
\frac{\abs{c_{[-N,N]}}_{1}}{2N + 1}
\end{align*}
exist, and all three converge to the same value $\alpha = \alpha_{a} = \alpha_{b} = \alpha_{c}$.
\end{prop}

\begin{proof}
The existence of each limit follows from Proposition~\ref{prop:strictly-2-balanced}, and the mutual balancedness (Proposition~\ref{prop:mutually-balanced2}) forces the limits to coincide.
\end{proof}

We call the common limit $\alpha\in [0, 1]$ defined here the \emph{slope} of the regular Sturmian lattice. 
By definition, $\alpha$ coincides with the natural density
\[
\lim_{N\to \infty}
\frac{1}{2N + 1}
\Card\bigl\{i\in [-N, N]\bigm| a(i+1) - a(i) = \kappa + 1\bigr\}
\]
of the wide corridors in each direction, and $1 - \alpha$ is of the narrow corridors.
We can then calculate the average of all corridor widths as
\[
(1 - \alpha)\kappa + \alpha(\kappa + 1) = \kappa + \alpha.
\]
We call the inverse $q:= 1 / (\kappa + \alpha)\in (0, 1]$ the \emph{frequency} of the regular Sturmian lattice, which is the average number of straight lines that appear per length one.

Next result gives a way to construct a Sturmian lattice.

\begin{prop}
\label{Construction}
If two bi-infinite words $(b_j),(c_k) \in \A^{\Z}$ are mutually balanced,
then there exists $(a_i)\in \A^{\Z}$ that 
% for any $\kappa\ge 1$, the associated lines $a=a(i)$, $b=b(j)$, $c=c(k)$ gives a Sturmian lattice. 
for any $\kappa\ge 1$, the associated lines $a=a(i)$, $b=b(j)$, $c=c(k)$ give a Sturmian lattice. 
\end{prop}

The same statements hold for the pair $(a_i),(b_j)\in \A^{\Z}$
and also $(a_i),(c_k)\in \A^{\Z}$ as well by symmetry.

\begin{proof}
%Without loss of generality, $b=b(0)$ and $c=c(0)$ intersects at $(0,0)$.
%Then $b=-b(n)$ and $c=c(n)$
%has an intersection of two lines
%\[
%y=-\sqrt{3}x + 2b(n),\ y=\sqrt{3}x -2c(n),
%\]
%i.e, 
%\[
%(x,y)=\left(\frac{c(n)+b(n)}{\sqrt{3}}, b(n)-c(n) \right).
%\]
Without loss of generality, we may assume $b(0) = c(0) = 0$.
Then two lines $b = b(n)$ and $c = c(-n)$ intersect at $\bigl(a, b(n), c(-n)\bigr)$ where
\[
a = -b(n) - c(-n).
\]
Since $b(n)=n\kappa + \abs{b_{[0,n-1]}}_1$ and $c(-n)= -n \kappa - \abs{c_{[-n+1,0]}}_1$,
we have
\[
a = \abs{c_{[-n+1,0]}}_1 - \abs{b_{[0,n-1]}}_1 \in \{-1,0,1\}
\]
by mutual balancedness.
If there exists $n$ with $\abs{c_{[-n+1,0]}}_1 - \abs{b_{[0,n-1]}}_1 = 1$, then
$\abs{c_{[-m+1,0]}}_1 - \abs{b_{[0,m-1]}}_1\in \{0,1\}$ holds for all $m\in \Z$.
Indeed, if we can find some $n'$ with  $\abs{c_{[-n'+1,0]}}_1 - \abs{b_{[0,n'-1]}}_1 = -1$
and $n' < n$ then
\[
\abs{c_{[-n+1,-n']}}_1 - \abs{b_{[n',n-1]}}_1 = 2
\]
shows that $(b_j)$ and $(c_k)$ are not mutually balanced. The case
$n < n'$ is similar. 
In this case, we can
set $a(0)=1/2$. 
On the contrary
if 
 there exists $n$ with $\abs{c_{[-n+1,0]}}_1 - \abs{b_{[0,n-1]}}_1 = -1$, then
$\abs{c_{[-m+1,0]}}_1 - \abs{b_{[0,m-1]}}_1\in \{-1,0\}$ holds for all $m\in \Z$.
Thus we set $a(0)=-1/2$.
If $\abs{c_{[-m+1,0]}}_1 - \abs{b_{[0,m-1]}}_1 = 0$ for all $m\in \Z$, then
we may have a choice to choose $a(0) = 1/2$ or $-1/2$.
The logic works for all intersections of $b = b(j)$ and $c = c(k)$,
and we can determine the values of $a(i)$ for $i = -j-k$ and
we obtain
\[
a(i)+b(j)+c(k) = \pm \frac{1}{2}
\]
as the axiom (SL-2).
\end{proof}

The choices of $a(i)$ occur if and only if there exists $\rho \in \Z$ such that $b(-\rho - k)=c(k)$ for all $k\in \Z$,
that is, $\mathfrak{B}$ and $\mathfrak{C}$ are congruent under a $2\pi/3$-rotation about some point of intersection. 
Switching from $a(\rho)=1/2$ to $a(\rho)=-1/2$ gives the change of word
$a_{\rho-1}a_{\rho}$ in $(a_i)$; $10 \mapsto 01$.

A word $x\in \A^*$ is \emph{central} if the words $0x0$, $0x1$, $1x0$, and $1x1$ are all 1-balanced, see \cite[Proposition 2.2.34]{Lothaire:02}.
Note that a central $x$ is a palindrome and 
the words $0x1$ (resp.\ $1x0$) is called
the \emph{lower} (resp.\ \emph{upper}) \emph{Christoffel word}.
For an irreducible fraction $p/q\in (0,1)$, 
the lower Christoffel word is explicitly written as
$$
\left(
\left\lfloor \frac {p(i+1)}q \right\rfloor -\left\lfloor \frac {pi}q \right\rfloor\right)_{i=0,1,\dots,q-1}.
$$
The upper Christoffel word is obtained in the same manner by replacing
$\lfloor{\cdots}\rfloor$ with $\lceil{\cdots}\rceil$.
The bi-infinite words $(x10)^{\Z}$ and $(x01)^{\Z}$ are $1$-balanced of a
rational slope $\alpha=p/q$. 
By abuse of notation, we call this $\alpha$ the \emph{slope} 
of the central word.

A $1$-balanced word of a rational slope is both
positive periodic and negative periodic. Moreover we have

\begin{lem}
\label{Rational}
If a word $w\in \A^{\Z}$ is $1$-balanced of a rational slope $\alpha$, 
then there exists a central word $c$ of slope $\alpha$ and
$w$ must be one of the following three forms:
\begin{enumerate}
\item $^{\infty}(c10) c (01c)^{\infty}$,
\item $^{\infty}(c01) c (10c)^{\infty}$,
\item $(c01)^{\Z}$.
\end{enumerate}
\end{lem}

\begin{proof}
This may be a well known fact and could be deduced 
from \cite[Chapter~2]{Lothaire:02}, or 
\cite[Chapter 6]{Fogg}.
We give a brief proof. 
\cite[Proposition 5.5]{Akiyama-Kaneko:21},
reads that the $1$-balanced word of rational slope eventually
falls into $$\{0^{\Z}, 1^{\Z}, \cdots 000 1 000\cdots, \cdots 111 0 111\cdots\}$$ 
by the map $\phi$ which decreases run lengths of the fixed letter by one, i.e.,
$$
\phi( \cdots 10^{u(-1)} 1 0 ^{u(0)} 1 0^{u(1)}1 \cdots)
=\cdots 10^{u(-1)-1} 1 0 ^{u(0)-1} 1 0^{u(1)-1}1 \cdots
$$
or
$$
\phi( \cdots 01^{u(-1)} 0 1^{u(0)} 0 1^{u(1)}0\cdots)
=\cdots 01^{u(-1)-1} 0 1 ^{u(0)-1} 0 1^{u(1)-1}0\cdots.
$$
Taking successive inverse images of $\phi$, we obtain this result. 
Here we used the fact that
$(c01)^{\Z}$ and $(c10)^{\Z}$ are shift equivalent. One can deduce this fact by using the decomposition of central words $c=p01q$ by two central words $p,q$, see \cite[Corollary 2.2.9]{Lothaire:02} and 
also \cite[Appendix]{Akiyama-Kaneko:21}. 
\end{proof}

\begin{thm}[Structure of Sturmian lattices]
\label{Main0}
A regular Sturmian lattice determined by $(a_i),(b_j),(c_k)\in \A^\Z$ with 
width~$\kappa$ and slope~$\alpha$ have one of the following forms:

\begin{description}
\item[\boldmath The case $\alpha\notin\Q$]
All three words are Sturmian words of irrational slope~$\alpha$.
The sequences $(b_j)$ and $(c_k)$ determine the third $(a_i)$ almost uniquely. The exception
happens at most one index $i$, and this occurs 
only when there exists $\rho\in \Z$ that $b(-\rho-k) = c(k)$ for all $k\in \Z$.

\item[\boldmath The case $\alpha\in\Q$]
All three words are $1$-balanced and belong to the same case of Lemma~\ref{Rational} except in the following case.
Two words of the three, say, 
$(b_j)$ and $(c_k)$ are of shape~(3). In this exception, 
the third word $(a_i)$ has the form
\[
\cdots cw_{-1}cw_0 c w_1 \cdots
\]
with any choices of $w_i\in \{01,10\}$.
This word is $2$-balanced but not necessary $1$-balanced.
\end{description}
\end{thm}

\begin{proof}
If
$\alpha$ is irrational, then
the statement follows from Proposition~\ref{Construction}.
Indeed, by Proposition~\ref{prop:strictly-2-balanced} all three  
 $(a_i),(b_j),(c_k)$
must be non-periodic and $1$-balanced. 
Therefore they are bi-infinite Sturmian words 
by Morse--Hedlund Theorem, see \cite{Lothaire:02, Fogg}. 
Thus 
they share the same slope and the same language, i.e, 
for any $n\in \N$, the set of
subwords of length $n$ are identical among $(a_i)$, $(b_j)$, $(c_k)$.
Thus any two sequences of the three are mutually balanced and 
Proposition~\ref{Construction} applies. 
From $(b_j)$, $(c_k)$ 
we obtain $(a_i)$ and the exceptional index $i$ occurs 
at most once 
since $\alpha$ is irrational.

When $\alpha$ is rational, Propositions~\ref{prop:mutually-balanced}~and~\ref{prop:strictly-2-balanced} show
that at least two of $(a_i)$, $(b_j)$, $(c_k)$ are mutually balanced and both $1$-balanced %periodic
with rational slope $\alpha>0$.
Without loss of generality, we may assume that
%two of the words, say, 
each $(b_j)$ and $(c_k)$ takes one of the forms in Lemma~\ref{Rational}.
If $(b_j)$ and $(c_k)$ are of the forms (1) and (2) respectively, then they cannot be mutually balanced, but all 
remaining choices are possible.
If both $(b_j)$ and $(c_k)$ are of the shape~(3), then 
they are periodic with period $|c| + 2$.
%we may assume that both are of the form $(c01)^{\Z}$. For example,
%if $(b_i)=(c01)^{\Z}$ and $(c_k)=(c10)^{\Z}$, then 
%rotating by $\pi/2$ gives this view.
Applying Proposition~\ref{Construction}, we find 
periodic points that we can choose $a_i$, and one can see that $(a_i)$ has the form
\[
\cdots d_{-1}w_{-1}d_{0}w_{0}d_{1}w_{1}\cdots
\]
with any choices of $w_{i}\in \{01, 10\}$ and for some $d_{i}$ with $|d_{i}| = |c|$.
Recalling that $(a_i)$ and $(b_j) = (0c1)^{\Z}$
are mutually balanced, and $(0c1)^{\Z}$
and $(1c0)^{\Z}$ are shift equivalent, four pairs of subwords 
\begin{align*}
&(0d_{i}0, 0c1),&
&(0d_{i}0, 1c0),&
&(1d_{i}1, 0c1),&
&(1d_{i}1, 1c0)
\end{align*}
of $(a_i)$ and $(b_i)$ are $1$-balanced. The same is valid 
for any two subwords of the same length from these pairs.
We claim that $d_i=c$.
Indeed if $d_i\neq c$
then there exists $w,u,v$ that $d_i=w0u$ and $c=w1v$, or $d_i=w1u$ and $c=w0v$.
However $1w1$ and $0w0$ are not $1$-balanced and 
we get a contradiction.
The claim is proved.
If both $(b_j)$ and $(c_k)$ are of the shape~(1), then 
$(a_i)$ is 
determined but for one index where we can choose $\pm 1/2$ as
in Proposition~\ref{Construction}. 
In $(a_i)$, switching $01\mapsto 10$
is possible as long as $(a_i)$ is of the form (1) or (2), but case (2) does not happen.
If $(b_j)$ and $(c_k)$ are of the forms (1) and (3) respectively,
then $(a_i)$ is uniquely determined. Then
$(a_i)$ cannot be of the form (1) or (2) because of the above discussion.
Thus $(a_i)$ is of the form (3). This case fall into the 1-st case.
In this way, Proposition~\ref{Construction} and the remark after it
finish the proof. 
\end{proof}

\begin{cor}
\label{Sturm}
For any tiling by Smith Turtle, 
its Ammann Bars form a Sturmian lattice of slope $(-1 + \sqrt{5})/2$ or $(3 - \sqrt{5})/2$.
\end{cor}

\begin{proof}
In \cite{Akiyama-Araki:23}, it is shown that its Ammann Bars 
in Figure \ref{SL} form a Strumian lattice in our definition. 
Further it is also proved that 
the possible pair $(q, \kappa)$ of frequency and minimum width is one of $\bigl((5 - \sqrt{5})/10, 3\bigr)$ and $\bigl((5 + \sqrt{5})/10, 1\bigr)$.
By calculating $\alpha = 1/q - \kappa$ in each case, we obtain the desired values.
\end{proof}

Theorem~\ref{Main0} is theoretically satisfactory but
does not give an immediate picture
of a Sturmian lattice.
Using Sturmian words $(b_j)$, $(c_k)$, 
Proposition~\ref{Construction}
gives a way to compute $(a_i)$ and then we obtain a Sturmian lattice indirectly.

\begin{definition}
\label{def:regular}
A regular Sturmian lattice $\mathfrak{A}\cup \mathfrak{B}\cup \mathfrak{C}$ is \emph{mechanical} if $(a_{i})$, $(b_{j})$, and $(c_{k})$ are all mechanical words.
\end{definition}

Let us restrict our scope to the realization of a Sturmian lattice in a handy way: using
mechanical words. 
For $\kappa\ge 1$ and 
$\alpha\in [0, 1]$, we put
\begin{equation}
\label{Mechanical}
\begin{aligned}
a(i)&= a^{\mathrm{ceil}}(i) =
i \kappa + \lceil i\alpha + \rho_0 \rceil - \frac{1}{2},\\
b(j)&= b^{\mathrm{floor}}(j) =
j \kappa + \lfloor j\alpha + \rho_1 \rfloor + \frac{1}{2},\\
c(k)&= c^{\mathrm{floor}}(k) =
k \kappa + \lfloor k\alpha + \rho_2 \rfloor + \frac{1}{2}.
\end{aligned}
\end{equation}
% Clearly corresponding $(a_i),(b_j),(c_k)$ are mechanical words of slope $\alpha$ and intercepts $\rho_i$ ($i=0,1,2$).
The corresponding sequences $(a_i),(b_j),(c_k)$ are mechanical words with slope $\alpha$ and intercepts $\rho_i$ ($i=0,1,2$).
We wish to characterize the \emph{intercept vector} $\bm{\rho} = (\rho_{0}, \rho_{1}, \rho_{2})\in \R^{3}$ that gives a mechanical Sturmian lattice.
We denote by $\SL(\kappa, \alpha\mid \bm{\rho})$ the collection of lines (that is not necessarily a Sturmian lattice) given by \eqref{Mechanical}.

\begin{rem}
\label{rem:up-to-null-set}
Let us compare these two functions
\begin{align*}
f^{\mathrm{ceil}}(n)
&= n\kappa + \lceil n\alpha+\rho\rceil - \frac12,&
f^{\mathrm{floor}}(n)
&= n\kappa + \lfloor n\alpha+\rho\rfloor + \frac12
\end{align*}
in \eqref{Mechanical}.
Since $\lceil x \rceil - 1/2 = \lfloor x \rfloor + 1/2$ for $x\in \R\setminus \Z$, one checks $f^{\mathrm{ceil}}(n) = f^{\mathrm{floor}}(n)$ whenever $n\alpha + \rho\notin \Z$.
This means that $(a_{i})$, $(b_{j})$, and $(c_{k})$ are invariant under the choice of upper or lower form for almost all $\bm{\rho}\in \R^{3}$.
%
When we try to give a mechanical Sturmian lattice, 
there are $2^{3} = 8$ possibilities to choose upper or lower mechanical word in each direction, and that the formulation~\eqref{Mechanical} is one of the 
choices.
We will discuss which choice is appropriate for a Sturmian lattice in Remark~\ref{rem:six-possibilities}.
\end{rem}

