For the moment, we wish to avoid the exceptional cases 
that $f^{\mathrm{ceil}}\ne f^{\mathrm{floor}}$.

\begin{definition}
\label{def:continuous-SL}
A collection $\SL(\kappa, \alpha\mid \bm{\rho})$ of lines is \emph{discontinuous} in the $a$-direction (resp.\ $b$- and $c$-direction) if there exists $n\in \Z$ with $n\alpha + \rho_{0}\in \Z$ (resp.\ $n\alpha + \rho_{1}\in \Z$ and $n\alpha + \rho_{2}\in \Z$).
We say $\SL(\kappa, \alpha\mid \bm{\rho})$ is \emph{continuous} if it is not discontinuous in any direction.
\end{definition}

We first characterize $\bm{\rho}\in \R^{3}$ that gives a continuous Sturmian lattice.
For those, we need not worry about the difference between functions $f^{\mathrm{ceil}}$ and $f^{\mathrm{floor}}$, and it is helpful to use 
the rounding function to $\Z + 1/2$, instead of the ceil or floor function.
Define
\[
\round{x}:= \ceil{x} - \frac{1}{2} =
\floor{x} + \frac{1}{2}\in \Z + \frac{1}{2}
\]
for $x\in \R\setminus \Z$ (equivalently, $\round{x} = R + 1/2$ if $x\in (R, R+1)$ with $R\in \Z$).

\begin{prop}
\label{prop:discontinuous-SL}
For a collection $\SL(\kappa, \alpha\mid \bm{\rho})$ of lines, the following are equivalent:
\begin{enumerate}
\item
Collection $\SL(\kappa, \alpha\mid \bm{\rho})$ is discontinuous in the $a$-direction.
\item
The intercept $\rho_{0}$ lies in $\Z + \alpha\Z$.
\end{enumerate}
\end{prop}

\begin{lem}
\label{3Floor}
Let $\rho_0,\rho_1,\rho_2 \in \R$. Then
\[
\round{x + \rho_0} + \round{y + \rho_1} + \round{-x-y+\rho_2}\in \left\{\frac{1}{2},-\frac{1}{2}\right\}
\]
for almost all $(x, y)\in \R^{2}$ holds if and only if
\[
\rho_0 + \rho_1 + \rho_2=0. 
\]
\end{lem}

\begin{proof}
Since
\[
f(x,y) = \round{x+\rho_0} + \round{y+\rho_1} + \round{-x-y+\rho_2}
\]
is periodic with respect to $x$ and $y$ of period one, 
we may assume $x,y\in [0,1)$.
Moreover, the set of values of $f$ is 
invariant under the transformation $(\rho_{0}, \rho_{1}, \rho_{2})\mapsto (\rho_{0}', \rho_{1}', \rho_{2}')$ with $\rho_{0} + \rho_{1} + \rho_{2} = \rho_{0}' + \rho_{1}' + \rho_{2}'$, and it is sufficient to discuss for $\rho_{0}, \rho_{1}\in [0, 1)$.
We have
\[
\round{x+\rho_0} + \round{y+\rho_1}
=\begin{cases} 
1 & \text{if }x < 1-\rho_0\text{ and }y < 1-\rho_1\\
3 & \text{if }x > 1-\rho_0\text{ and }y > 1-\rho_1\\
2 & \text{otherwise}\\
\end{cases}
\]
and
\[
\round{-x-y+\rho_2} =
\begin{cases}
R+1/2 & \text{if }     x+y < r\\
R-1/2 & \text{if }r < x+y < 1+r\\
R-3/2 & \text{if }    x+y > 1+r
\end{cases}
\]
for $R\in \Z$ and $r\in [0, 1)$ with $R + r = \rho_{2}$.
See Figure~\ref{fig:lem3floor}.
Since 
$\round{x+\rho_0} + \round{y+\rho_1}$ takes three values $\{1,2,3\}$ 
in any ball centered at $(1-\rho_0, 1-\rho_1)$, 
if the line $x+y=r$ does not pass through the point
$(1-\rho_0, 1-\rho_1)$, then $f(x,y)$ must take at least three values. 
On the other hand, if it passes through $(1-\rho_0,1-\rho_1)$, then the values of $f$ are in $\{R + 3/2, R + 5/2\}$.
Thus $f(x, y)\in \{0, -1\}$ holds if and only if both
\begin{align*}
(1 - \rho_{0}) + (1 - \rho_{1})&= r,&
R&= -2
\end{align*}
hold, and we have $\rho_{0} + \rho_{1} + \rho_{2} = 0$ as required.
\end{proof}

