\begin{prop}
\label{prop:superSL-1D}
Define
\begin{align*}
f(m)&= m\kappa + \round{m\alpha + \rho}\\
\intertext{for $m\in \Z$ and}
F(n)&= -\kappa\left(
n\kappa_{1} + \round{n\alpha_{1} + \frac{\rho}{\alpha}}
\right)
\end{align*}
for $n\in \Z$.
Then for any $n\in \Z$, there exists unique $m = m(n)\in \Z$ with
\begin{equation}
\label{eq:superSL-1D}
f(m) - F(n) = F(n) - f(m-1) = \frac{\kappa + 1}{2}.
\end{equation}
Moreover, this map $n\mapsto m(n)$ is bijective between $\Z$ and\[
M:= \{m\in \Z\mid f(m) - f(m-1) = \kappa + 1\}.
\]
\end{prop}

The function $F$ has another form\[
F(n) = -n - \kappa
\round{\frac{n + \rho}{\alpha}}
\]since $\kappa_{1} = \kappa^{-1} + a_{1}$ and $\alpha_{1} = \alpha^{-1} - a_{1}$.

\begin{proof}
To make it explicit that the functions $f$ and $F$ depend on $\kappa$, we write them as $f_{\kappa}$ and $F_{\kappa}$, respectively.

First we verify that $m(n)$ is independent of $\kappa$, i.e., we claim that
\[
f_{\kappa}(n) - F_{\kappa}(m) = \pm\frac{\kappa + 1}{2}\iff
f_{\kappa'}(n) - F_{\kappa'}(m) = \pm\frac{\kappa' + 1}{2}
\]
for $(n, m)\in \Z^{2}$ and $\kappa, \kappa'\in [1, \infty)$.
Since
\begin{align*}
f_{\kappa}(m) - f_{\kappa'}(m)&=
(\kappa - \kappa')m\\
\intertext{and}
F_{\kappa}(n) - F_{\kappa'}(n)&=
-(\kappa - \kappa')\round{\frac{n + \rho}{\alpha}},
\end{align*}
we have
\[
\bigl(f_{\kappa}(n) - F_{\kappa}(m)\bigr) - \bigl(f_{\kappa'}(n) - F_{\kappa'}(m)\bigr) = (\kappa - \kappa')C
\]
where
\[
C:= m + \round{\frac{n + \rho}{\alpha}}\in \frac{1}{2} + \Z
\]
is a constant independent of $\kappa$, so that
\[
f_{\kappa}(n) - F_{\kappa}(m) - C\kappa =
f_{\kappa'}(n) - F_{\kappa'}(m) - C\kappa'.
\]
Choosing $C = \pm1/2$ shows our claim (this discussion also yields that
\[
f(m) - F(n) = \frac{\kappa + 1}{2}
\]
holds only if $C = 1/2$).

Our discussion above says that we may assume $\kappa = 1$ without loss of generality.
% (as long as we do not consider the inverse transformation $\sigma^{-1}$, we may set $\kappa = 1$).（混乱を避けるため）
Specifically, we treat
\begin{align*}
f(m)&= f_{1}(m) =
m + \round{m\alpha + \rho},&
F(n)&= F_{1}(n) =
-n - \round{\frac{n + \rho}{\alpha}}.
\end{align*}
Note that for $(m, n)\in \Z^{2}$, \eqref{eq:superSL-1D} holds if and only if
\begin{equation}
\label{eq:superSL-1D-equiv}
f(m - 1) + 1 = F(n) = f(m) - 1
\end{equation}
holds.
Since $f$ is strictly increasing, $m(n)$ is unique if exists.
For the existence, we claim that $(m(n), n)\in \Z^{2}$ satisfies \eqref{eq:superSL-1D} where\[
m(n) - 1 <
-\round{\frac{n + \rho}{\alpha}} <
m(n).
\]By inequality\[
-\frac{n + \rho}{\alpha} - 1 < m(n) - 1 <
-\frac{n + \rho}{\alpha} < m(n) <
-\frac{n + \rho}{\alpha} + 1
\]and our setting $\alpha\in (0, 1)$, we have
\begin{equation}
\label{eq:mn-monotonicity}
-n - 1 < (m(n) - 1)\alpha + \rho <
-n < m(n)\alpha + \rho < -n + 1.
\end{equation}
This implies that\[
\round{(m(n) - 1)\alpha + \rho} + \frac{1}{2} = -n =
\round{m(n)\alpha + \rho} - \frac{1}{2}.
\]By adding \[
m(n) - \frac{1}{2} =
-\round{\frac{n + \rho}{\alpha}} =
m(n) - \frac{1}{2}
\] to each side, we have\[
f(m(n) - 1) + 1 = F(n) = f(m(n)) - 1.
\]

It remains to show that $n\mapsto m(n)$ is bijective.
The injectivity is clear since $n\mapsto m(n)\alpha + \rho$ is strictly decreasing by \eqref{eq:mn-monotonicity}.
For surjectivity, suppose that there exists $m\in M$ that is not equal to $m(n)$ for any $n\in \Z$.
Then we have $C\ne 1/2$ since the map $m\mapsto m + \round{(n + \rho)/\alpha}$ is injective and 
\[
m(n) + \round{\frac{n + \rho}{\alpha}} = \frac{1}{2}.
\]
This implies $f(m) - F(n)\ne (\kappa + 1)/2$ so that $m\notin M$, a contradiction.
\end{proof}

Using the upper form $f^{\mathrm{ceil}}$, we have \[
F^{\mathrm{ceil}}(n) = -\kappa\left(
n\kappa_{1} + \ceil{n\alpha_{1} + \frac{\rho}{\alpha}} - \frac{1}{2}
\right),
\]and the lower form $f^{\mathrm{floor}}$, we have \[
F^{\mathrm{floor}}(n) = -\kappa\left(
n\kappa_{1} + \floor{n\alpha_{1} + \frac{\rho}{\alpha}} + \frac{1}{2}
\right).
\]

\begin{cor}
\label{cor:superSL-2D}
The set $-\kappa\SL^{1}(\kappa, \alpha\mid \bm{\rho})$ coincides with the collection of middle lines of wide corridors in the original lattice $\SL(\kappa, \alpha\mid \bm{\rho})$ as shown in Figure~\ref{fig:superSL}.
\end{cor}

We say this map $\sigma\colon \SL(\kappa, \alpha\mid \bm{\rho})\mapsto -\kappa\SL(\kappa_{1}, \alpha_{1}\mid \bm{\rho}_{1})$ the \emph{SL substitution}.

A Sturmian word of a purely periodic slope 
$\alpha=[\overline{a_{1},a_{2},\dots, a_{k}}]$, i.e., 
the reduced quadratic irrational 
in the sense of Gauss is of special interest.
It is a fixed point of a certain 
substitution (see \cite[Theorem~2.3.25]{Fogg}) 
whose expansion constant is the dominant eigenvalue $>1$ of
$$
\begin{pmatrix}
0& 1\\
1& a_1
\end{pmatrix}
\begin{pmatrix}
0& 1\\
1& a_{2}
\end{pmatrix}
\cdots
\begin{pmatrix}
0& 1\\
1& a_{k}
\end{pmatrix}.
$$
This expansion constant is a unit 
of the integer ring of the quadratic field $\Q(\alpha)$.
The self-similar structure of Sturmian words gives rise to the 
self-similar structure of Sturmian lattice
and the
expansion constant coincides with
$$
\prod_{j=1}^{k} [a_{j};\overline{a_{k+j-1},a_{k+j-2},\dots, a_{j}}]
$$
under the 
choice 
$\kappa=[a_{k};\overline{a_{k-1},a_{k-2},\dots, a_{1},a_{k}}]$.
The expansion constant of Sturmian Lattice 
of a general
quadratic slope 
$\alpha=[a_1,a_2,\dots, a_{n},\overline{a_{n+1},a_{n+2},\dots, a_{n+k}}]$
is determined by the purely periodic part 
$[\overline{a_{n+1},a_{n+2},\dots, a_{n+k}}]$.

%This is the expansion constant when we iterate 
%the $k$-fold SL substitution.

\begin{rem}
\label{rem:SL-scalar-ignore}
By Corollary~\ref{cor:superSL-2D}, we do not care the difference in scalar multiplication.
For this reason, we write $\sigma\bigl(\SL(\kappa, \alpha\mid \bm{\rho})\bigr) = \SL(\kappa_{1}, \alpha_{1}\mid \bm{\rho}_{1})$ to identify them.
\end{rem}

While it is natural to assume the irrationality of $\kappa$ and $\alpha$ to identify the parameter space $X$ with the set of bi-infinite sequences $\N^{\Z}$, it is also useful to study this system on its closure \[
\overline{X} = [1, \infty]\times [0, 1] =
\bigl\{(\kappa, \alpha)\bigm|
\kappa\in [1, \infty], \alpha\in [0, 1]\bigr\}
\] of $X$.
For a better understanding of Sturmian lattices in $\overline{X}$, we introduce the limit of a sequence of Sturmian lattices.
Notice that the canonical map $\overline{X}\ni (\kappa, \alpha)\mapsto \SL(\kappa, \alpha\mid \bm{\rho})$ is not injective (consider $\SL(\kappa, 1\mid \bm{\rho}) = \SL(\kappa + 1, 0\mid \bm{\rho})$).

\begin{definition}
\label{def:SL-limit}
Let \[
(\SL_{n} = \mathfrak{A}^{(n)}\cup \mathfrak{B}^{(n)}\cup \mathfrak{C}^{(n)})_{n\ge 1}
\] be a sequence of Sturmian lattices and let \[
\SL_{\infty} = \mathfrak{A}\cup \mathfrak{B}\cup \mathfrak{C}.
\] We say that $(\SL_{n})$ \emph{converges} to $\SL_{\infty}$ if there exists a sequence $(r_{n})$ in $\R$ with
\begin{align*}
\lim_{n\to \infty} r_{n}a^{(n)}(i)&= a(i),&
\lim_{n\to \infty} r_{n}b^{(n)}(j)&= b(j)&
\lim_{n\to \infty} r_{n}c^{(n)}(k)&= c(k)
\end{align*}
for all $i, j, k\in \Z$.
\end{definition}

The scalar multiplication in Definition~\ref{def:SL-limit} comes from Remark~\ref{rem:SL-scalar-ignore}.

\begin{ex}
The map $\SL(\kappa, \alpha\mid \bm{\rho})$ is trivially continuous with respect to $\kappa\in [1, \infty)$ and $\bm{\rho}\in \R^{3}\setminus D$, except for countably many discontinuities in \[
D = \bigl\{\bm{\rho} = (\rho_{0}, \rho_{1}, \rho_{2})\in \R^{3}\bigm| \rho_{i}\in \Z + \alpha\Z \text{ for some }i\in \{0, 1, 2\}\bigr\}.
\]For the case $(0, 0, 0)\in D$, we can also express all the six possibilities in Remark~\ref{rem:six-possibilities} by taking one-sided limit as $\rho_{i}\to \pm0$ for each index $i$, even though we use only the representation~\eqref{Mechanical}.
\end{ex}

For $\kappa = \infty$, it seems natural to define $\SL(\infty, \alpha\mid \bm{\rho})$ as $\lim_{\kappa\to \infty}\SL(\kappa, \alpha\mid \bm{\rho})$.
For the formulation in \eqref{Mechanical}, one can see that \[
a(i) = i\kappa + \ceil{\alpha i + \rho_{0}} - \frac{1}{2} = O(\kappa)
\] as $\kappa\to \infty$ (similarly, $b(j) = O(\kappa)$ and $c(k) = O(\kappa)$), so it is natural to consider the limits
\begin{align*}
\lim_{\kappa\to \infty} \frac{a(i)}{\kappa}&= i,&
\lim_{\kappa\to \infty} \frac{b(j)}{\kappa}&= j,&
\lim_{\kappa\to \infty} \frac{c(k)}{\kappa}&= k,
\end{align*}
and we use this fact to define $\SL(\infty, \alpha\mid \bm{\rho})$.

\begin{definition}
\label{def:SL-kappa-infty}
We define $\SL(\infty, \alpha\mid \bm{\rho})$ to be the triangular lattice with two-color corridors.
For $a$-direction, if $a_{i} = \ceil{(i+1)\alpha + \rho_{0}} - \ceil{i\alpha + \rho_{0}} = 1$ (resp.\ $0$), then we call the corridor between $a(i)$ and $a(i+1)$ \emph{wide} (resp.\ \emph{narrow}).
For other directions, we also define them similarly.
\end{definition}

We also give a few remarks for $\kappa\in \Q$ or $\alpha\in \Q$, with finite continued fractions.
Notice that the continued fraction expansion of $\alpha\in [0, 1)\cap \Q$ is not unique.
In this paper, we select the form \[
\alpha = [a_{1}, \dots, a_{n}, \infty] =
\frac{1}{a_{1} +
\cfrac{1}{\ddots +
\cfrac{1}{a_{n} +
\cfrac{1}{\infty}}}}
\] with $a_{n}\ne 1$, and we formally interpret $1/\infty$ as zero.

\begin{rem}
\label{rem:superSL-rational}
If $\alpha = [a_{1}, \dots, a_{n}, \infty]\in [0, 1)\cap \Q$, then we obtain $\sigma^{n}(\kappa, \alpha) = (\kappa_{n}, 0)$, which provides the Sturmian lattice $\SL(\kappa_{n}, 0\mid \bm{\rho}_{n})$ consisting of families of equally spaced parallel lines in three directions.
Also note that we do not define $\SL^{1}(\kappa, 0)$.

If $\kappa = [a_{0}; a_{-1}, \dots, a_{-n+1}, \infty]\in [1, \infty)\cap \Q$, then we formally obtain $\sigma^{-n}(\kappa, \alpha) = (\infty, \alpha_{-n})$, which provides the triangular 
lattice $\SL(\infty, \alpha_{-n}\mid \bm{\rho}_{-n})$.
This is useful to analyze Sturmian lattices for $\kappa\in \N$ since $\kappa_{-1} = \infty$.
See also \S\ref{sec:ex3}.
\end{rem}

\section{Bounded Displacement equivalence}
\label{BD}
% A set $X$ in $\R^d$ is {\it relatively dense} if there exists $R>0$ such that 
A set $X \subset \R^d$ is said to be {\it relatively dense} if there exists $R>0$ such that 
%for any $x\in \R^d$, $\overline{B(R,x)}\cap X\neq \emptyset$ where
for any $x\in \R^d$, $\overline{B(x,R)}\cap X\neq \emptyset$ where
\[
%B(R,x):= \{y\in \R^{d}\mid \abs{x - y} < R\}.
B(x,R):= \{y\in \R^{d}\mid \abs{x - y} < R\}.
\] 
% A set $X$ in $\R^d$ is {\it uniformly discrete} if there exists $r>0$ such that for any $x\in \R^d$, $\Card(B(r,x)\cap X)\le 1$. A set $X\subset \R^d$ is a {\it Delone set} if it is relatively dense and uniformly discrete.
A set $X \subset \R^d$ is said to be {\it uniformly discrete} if there exists $r>0$ such that for any $x\in \R^d$, $\Card(B(x,r)\cap X)\le 1$. A set $X\subset \R^d$ is a {\it Delone set} if it is relatively dense and uniformly discrete.
Let $X$ be a Delone set. 
% By definition it is clear that for any $x\in \R^d$ 
It follows directly from the definition that for any $x\in \R^d$ 
\[
0 < \liminf_{R\to \infty}
\frac{\Card(B(x,R)\cap X)}{\mu(B(x,R))} 
\le \limsup_{R\to \infty}
\frac{\Card(B(x,R)\cap X)}{\mu(B(x,R))} < \infty
\]
where $\mu$ is the $d$-dimensional Lebesgue measure.
If there exists $\delta=\delta(X)$ with
\[
\delta = \lim_{R\to \infty}
\frac{\Card(B(x,R)\cap X)}{\mu(B(x,R))},
\]
then it is called the \emph{natural density} of $X$.
Two Delone sets $X$ and $Y$ are said to be \emph{bounded displacement equivalent} (abbreviated as BD equivalent) if there exists $r>0$ and a bijection $\phi\colon X\to Y$ such that
\[
\bigl|\phi(x)-x\bigr| \le r.
\]
This defines an equivalence relation on the set of Delone sets and we denote by 
$X \BDsim Y$, and we call the associated map $\phi$ a \emph{BD bijection}.
Note that
$X \BDsim Y$ implies $\delta(X)=\delta(Y)$.
A Delone set $X$ is {\it uniformly spread}
if $X\BDsim \delta^{-1/d} \Z^d$. 
The characterization of uniformly spread sets is an important problem.
The case $d=1$ is easy.

\begin{prop}
\label{Onedim}
For $d=1$, a Delone set $X\subset \R$ is uniformly spread if and only if there exists $\delta>0$ and a positive constant $C$ such that for any $m\in \Z$, we have
\begin{equation}
\label{BR}
-C < \Card\bigl(X\cap [0,m]\bigr) - \delta |m| < C.
\end{equation}
In this case, $X\BDsim \delta^{-1} \Z$ holds.
\end{prop}

Here $[0, m]$ is the closed 
interval between $0$ and $m$ regardless of the sign of $m\in \Z$.

\begin{proof}
If $X\BDsim \delta^{-1} \Z$, 
% then we have $X = \{x_j\in \R\mid j\in \Z\}$ and
then $X = \{x_j\in \R\mid j\in \Z\}$ and
\begin{equation}
\label{eq:onedim-proof}
-r\le x_j-\delta^{-1}j \le r.
\end{equation}
For integer $m > 0$, we have
\begin{align*}
\Card\bigl(X\cap [0,m]\bigr)&\le
\Card\bigl(\delta^{-1}\Z\cap [-r, m+r]\bigr)\\&\le
\ceil{(m + 2r)\delta}\\&\le
\ceil{m\delta} + \ceil{2r\delta}\\&\le
m\delta + \ceil{2r\delta} + 1
\end{align*}
and similarly
\[
\Card\bigl(X\cap [0,m]\bigr)\ge
%\Card\bigl(\delta^{-1}\Z\cap [r, m-r]\bigr)\ge
%\floor{(m - 2r)\delta}\ge
%\floor{m\delta} + \floor{-2r\delta}\ge
m\delta - \ceil{2r\delta} - 1.
\]
Thus we obtain \eqref{BR} with $C =  \ceil{2r\delta} + 1$. 
The case $m<0$ is similar.

Conversely we assume \eqref{BR}. We wish to list the elements of $X$ in the increasing order $X=\{\cdots < x_{-1}< x_0<x_1 < \cdots \}$ so that \eqref{eq:onedim-proof}.
By \eqref{BR}, if 
$m\ge C/\delta$ then $X \cap [0,m]\neq \emptyset$. Thus we can take $x_0$
with $|x_0|\le C/\delta + 1$.
Assume that $x_k$ is defined for $0\le k< k_0$ and satisfies
$\abs{x_k - \delta^{-1}k}\le C/\delta + 1$. 
If $m\ge (k_0 + C)/\delta$ then $\Card\bigl(X \cap [0,m]\bigr)\ge k_0 + 1$
and
\[
X' = \bigl(X\cap [0, m]\bigr)\setminus \{x_0,\dots, x_{k_0-1}\}\neq \emptyset.
\]
Thus we define $x_{k_0}$ by the
minimum element of $X'$. Since if we take 
$m < (k_0 - C)/\delta$ then $\Card(X \cap [0,m]) < k_0$, 
we see
\[
\floor{\frac{k_0-C}{\delta}} < x_{k_0} \le 
\ceil{\frac{k_0+C}{\delta}}.
\]
We continue in this way to define
the index of the elements of $X$ in both positive and negative directions.
% By construction, it is clear that
It follows from the construction that
\[
\abs{x_j - \delta^{-1}j}\le \frac{C}{\delta} + 1
\]
% for any $j\in \Z$, which shows that $X\BDsim \delta^{-1} \Z$.
for any $j\in \Z$, and hence $X\BDsim \delta^{-1} \Z$.
\end{proof}


The bounded displacement equivalence for $d=2$ is pretty
non-trivial
and studied by Laczkovich~\cite{Laczkovich:90} 
in connection to the classical problem of ``squaring a circle''.
%The case $d\ge 2$ is further discussed in \cite{Laczkovich:92}. 
Let $e_1=(1,0)$ and $e_2=(0,1)$ and $P=[0,1)\times [0,1)$.
%Given a lattice $\L=e_1 \Z + e_2 \Z$ 
%of $\R^2$ and its fundamantal paralellogram 
%$$
%P=\{ x e_1+y e_2 \ |\ x\in [0,1), y\in [0,1) \}.
%$$
Denote by $\H$ the collection of any
finite union of squares of the form
$P+ i e_1+ j e_2$ ($i, j\in \Z$).
Laczkovich~\cite{Laczkovich:90} gave a criterion that a Delone 
set is uniformly spread in $\R^2$.

\begin{prop}[\cite{Laczkovich:90} Lemma 3.6, \cite{Laczkovich:92} Lemma 2.3]
\label{Lac}
For a Delone set $X\subset \R^{2}$, if 
there exists $C>0$ that for any $H\in \H$ we have
\begin{equation}
\label{LC}
\bigl|\Card(X \cap H) - \delta(X) \mu (H)\bigr| < C p(H)
\end{equation}
holds then $X \BDsim \delta^{-1/2} \Z^2$.
\end{prop}

Here $\mu$ is the 2-dimensional Lebesgue measure (i.e., volume) and $p$
is the 1-dimensional Lebesgue measure of the boundary (i.e., the perimeter).
Note that one can change the lattice $\Z^2$ to any unimodular lattice,
since the condition \eqref{LC} is invariant 
under the action of unimodular matrix, up to the choice of the constant $C$.
The proof relies on the M.~Hall's infinite version of marriage theorem.
See \cite{Laczkovich:92} for the corresponding result for $d\ge 3$.

\begin{cor}
If two Delone sets $X$ and $Y$ satisfy the condition \eqref{LC}, then 
$\delta(X)=\delta(Y)$ implies $X \BDsim Y$.
\end{cor}

The condition \eqref{LC} is not additive.
Even when $H_1\cap H_2=\emptyset$, two inequalities
\[
\bigl|\Card(X \cap H_1)- \delta(X) \mu (H_1)\bigr| < C p(H_1)
\]
and 
\[
\bigl|\Card(X \cap H_2) - \delta(X) \mu (H_2)\bigr| < C p(H_2)
\]
do not immediately imply
\[
\bigl|\Card(X \cap (H_1\cup H_2)) - \delta(X) \mu (H_1 \cup H_2)\bigr| < C 
p(H_1\cup H_2),
\]
since $p(H_1\cup H_2)$ is less than $p(H_1)+p(H_2)$
when $H_1$ and $H_2$ share their boundaries. 
This is a 
difficulty to apply this criterion. Hereafter we show that this condition is naturally satisfied in our setting related to Sturmian Lattices.

We start with an easy but important case.
If $X, Y\subset \R$ satisfy \eqref{BD} with 
natural densities $\delta_1$ and $\delta_2$, then we have
\begin{align*}
X&\BDsim \delta_1^{-1}\Z,&
Y&\BDsim \delta_2^{-1}\Z
\end{align*}
with the common constant $C>0$. 
Then we obviously obtain
\begin{equation}
\label{ProductForm}
X \times Y \BDsim \delta_1^{-1}\Z \times \delta_2^{-1}\Z
\end{equation}
with the constant $2C$. 
To see the power of Proposition~\ref{Lac}, 
we prove that 
\[
\delta_1^{-1}\Z \times \delta_2^{-1}\Z \BDsim
(\delta_1 \delta_2)^{-1/2} \Z^2
\]
as an example. Without loss of generality, it is sufficient to show that
\begin{equation}
\label{Target}
\delta_1^{-1}\Z \times \Z \BDsim
(\delta_1)^{-1/2} \Z^2
\end{equation}
by applying similitude. 
There exists $C_1$ that 
\[
\Bigl|\Card\left((\delta_1^{-1}\Z \times \{y\})\cap ([m,n]\times \{y\})\right)-\delta_1 |n-m|\Bigr| < C_1
\]
holds for all $y\in \Z$ and all $m,n\in \Z$.
For any $H\in \H$, the strip $H_y=H\cap (\R\times [y,y+1))$ is decomposed into disjoint connected components
\[
H_y = H_{y,1} \sqcup H_{y,2} \sqcup \dots \sqcup H_{y,s(y)}.
\]
Figure~\ref{fig:Laczkovich} helps us understand this setting.
Then
\[
\bigl|\Card\bigl(H_{y,i} \cap (\delta_1^{-1}\Z \times \Z)\bigr)- \delta_1 \mu(H_{y,i})\bigr| < C_1.
\]
Therefore
\[
\bigl|\Card\bigl(H_y \cap (\delta_1^{-1}\Z \times \Z)\bigr)- \delta_1 \mu(H_y)\bigr| < C_1 s(y)
\]
and we obtain
\[
\bigl|\Card\bigl(H \cap (\delta_1^{-1}\Z \times \Z)\bigr)- \delta_1 \mu(H)\bigr| < C_1 \sum_{y}s(y).
\]
Since $\sum_{y}s(y)$ gives the total length of the left boundaries of $H$, we see $2\sum_{y}s(y) < p(H)$. 
Thus \eqref{LC} holds and we obtain \eqref{Target}. The proof works 
in the same way for any lattice in $\R^2$ of density $\delta$, and it is
bounded displacement equivalent to $\delta^{-1/2}\Z^2$.

