\begin{prop}
\label{prop:existence-sub}
Let $X\subset \R^{2}$ be uniformly spread Delone and let $\delta\in (0, 1)$.
Then there exists a uniformly spread Delone subset $Y\subset X$ with natural density $\delta = \delta(Y)$.
\end{prop}

\begin{proof}
We may assume $X = \Z^{2}$ without loss of generality, and let
\[
Y = \bigl\{\phi(i,j) = \bigl(\lfloor{\delta^{-1/2}i}\rfloor, \lfloor{\delta^{-1/2}j}\rfloor\bigr)\in \Z^{2}\bigm| i, j\in \Z\bigr\}.
\]
Since $\bigl|\floor{x} - x\bigr|\le 1$ for $x\in \R$, we have
\[
\bigl|\phi(i,j) - \delta^{-1/2}(i, j)\bigr|\le \sqrt{2},
\]
which shows $Y\BDsim \delta^{-1/2}\Z^{2}$.
\end{proof}

\begin{cor}
\label{cor:BD-correspondence}
Let $X, Y\subset \R^{2}$ be uniformly spread Delone sets with natural densities $\delta_{1} = \delta(X)$ and $\delta_{2} = \delta(Y)$.
Then $\delta_{1}/\delta_{2} = p/q\in \mathbb{Q}$ implies the existence of countable partitions
\begin{align*}
X&= \bigsqcup_{k\ge 1}X_{k},&
Y&= \bigsqcup_{k\ge 1}Y_{k}
\end{align*}
of $X$ and $Y$, which satisfy that $\Card(X_{k}) = p$, $\Card(Y_{k}) = q$ for each $k$, and that $X_{k}\vee Y_{k}$ is uniformly bounded.
\end{cor}

\begin{proof}
Since there is a bijection $\phi\colon X\to \delta_1^{-1/2}\Z^2$ that induces $X\BDsim \delta_1^{-1/2}\Z^2$, 
a disjoint union
\[
\Z^2=\bigsqcup_{i,j\in \Z} \bigl(\{p i,p i+1,\dots, p i+p-1\}\times \{j\} \bigr)
\]
gives rises to 
\[
X_{i,j}=\phi^{-1} \left(\delta_1^{-1/2}\bigl(
\{p i,p i+1,\dots, p i+p-1\}\times \{j\} \bigr)\right) 
\]
and the subset
\[
X(p)=\phi^{-1}\left(\delta_1^{-1/2} (
p \Z \times \Z) \right)
\]
with the natural density 
$\delta(X(p))=\delta_1/p$. Similarly we define
$Y_{i,j}$ and $Y(q)$. Since $X(p)$, $Y(q)$
are uniformly spread and $\delta(X(p))=\delta(Y(q))$ we have
\[
X(p)\BDsim Y(q).
\]
By construction, each $X_{i,j}\vee Y_{i,j}$ is uniformly bounded.
\end{proof}

%Corollary~\ref{cor:BD-correspondence} may hold without assuming that $X$ and $Y$ are bounded displacement equivalent to lattices. 
We call this partition the \emph{bounded displacement correspondence} (abbreviated as BD correspondence).

\section{Voronoi cells}
\label{Voronoi}
A regular Sturmian lattice with widths $\{\kappa, \kappa+1\}$ and slope $\alpha\in [0, 1]$ is denoted by $\SL(\kappa, \alpha)$.
To construct our aperiodic tile sets, we prepare Voronoi cells of 
$\SL(\kappa, \alpha)$. This idea leads us to three prototiles that we know the
natural densities of corresponding Delone sets.

Recall that each element $(i, j, k)$ in the set \[
V_{0}:= V = \{(i, j, k)\in \Z^{3}\mid i + j + k = 0\}
\]gives a tiny triangle with height $1/2$.
We observe the size of regular triangles given by triple $(i, j, k)$ in \[
V_{1}:= \{(i, j, k)\in \Z^{3}\mid i + j + k = \pm 1\}.
\]

\begin{prop}
\label{prop:ST}
For any $(i, j, k)\in V_{1}$,\[
\bigl|a(i) + b(j) + c(k)\bigr|\in \left\{\kappa - \frac{1}{2}, \kappa + \frac{1}{2}, \kappa + \frac{3}{2}\right\}.
\]
\end{prop}

\begin{proof}
In the case $i + j + k = 1$, we have
\begin{align*}
a(i) + b(j) + c(k)&=
\bigl(a(i) + b(j) + c(k-1)\bigr) + \bigl(c(k) - c(k-1)\bigr)\\&\in
\left\{\pm\frac{1}{2}\right\} +
\{\kappa, \kappa + 1\} =
\left\{\kappa - \frac{1}{2}, \kappa + \frac{1}{2}, \kappa + \frac{3}{2}\right\}
\end{align*}
since $(i, j, k-1)\in V_{0}$.
Similarly, in the case $i + j + k = -1$ we have\[
a(i) + b(j) + c(k)\in
\left\{\pm\frac{1}{2}\right\} -
\{\kappa, \kappa + 1\} =
\left\{-\kappa - \frac{3}{2}, -\kappa - \frac{1}{2}, -\kappa + \frac{1}{2}\right\}
\]as claimed.
\end{proof}

\begin{definition}
\label{def:Sturmian-triangles}
For $(i, j, k)\in V_{0}\cup V_{1}$, the \emph{Sturmian triangle} $\ST(i, j, k)$ is a regular triangle surrounded by three lines\[
a = a(i),\ b = b(j),\ c = c(k).
\]If $(i, j, k)\in V_{0}$, then $\ST(i, j, k)$ is said to be \emph{tiny} (in this case $\bigl|a(i) + b(j) + c(k)\bigr| = 1/2$ automatically holds by (SL-2)).
If $(i, j, k)\in V_{1}$ and $\bigl|a(i) + b(j) + c(k)\bigr|$ takes value $\kappa - 1/2$ (resp.\ $\kappa + 1/2$ and $\kappa + 3/2$), then $\ST(i, j, k)$ is \emph{small} (resp.\ \emph{medium} and \emph{large}).
See Figures~\ref{fig:ST-tiling}~and~\ref{fig:ST-tile}.
\end{definition}

