\begin{prop}
\label{prop:VC-shape}
For $(i, j, k)\in V_{1}$ and ${*}\in \{a, b, c\}$, the
convex $4$-gon $\VC_{*}(i, j, k)$ is a parallelogram.
Moreover, there are some constant $C > 0$ such that each side has length either $C\kappa$ or $C(\kappa + 1)$.
\end{prop}

\begin{proof}
To see that $\VC_{*}(i, j, k)$ is a parallelogram, it suffices to show for $\VC_{a}(i, j, k)$ with $i + j + k = -1$ by symmetry.
One can verify that
\begin{alignat*}{3}
&G(i, j, k),& &G(i, j+1, k)&&\in \ell_{1} = \bigl\{(i, t, k)\in \R^{2}\bigm| t\in \R\bigr\},\\
&G(i, j, k+1),\quad& &G(i, j+1, k+1)&&\in \ell_{2} = \bigl\{(i, t, k+1)\in \R^{2}\bigm| t\in \R\bigr\},\\
&G(i, j, k),& &G(i, j, k+1)&&\in \ell_{3} = \bigl\{(i, j, t)\in \R^{2}\bigm| t\in \R\bigr\},\\
&G(i, j+1, k),& &G(i, j+1, k+1)&&\in \ell_{4} = \bigl\{(i, j+1, t)\in \R^{2}\bigm| t\in \R\bigr\}.
\end{alignat*}
Since $\ell_{1}$ and $\ell_{2}$ are parallel and so are $\ell_{3}$ and $\ell_{4}$, $\VC_{a}(i, j, k)$ is a parallelogram.

We next calculate the distance $d$ between $G(i, j, k)$ and $G(i+1, j, k)$.
Since both two points are on the line $\{(t, j, k)\in \R^{2}\mid t\in \R\}$, we have
\begin{align*}
d&= \left|
\frac{2a(i+1) - b(j) - c(k)}{3} -
\frac{2a(i) - b(j) - c(k)}{3}
\right|\\&=
\frac{2}{3}\bigl|a(i+1) - a(i)\bigr|\in
\left\{\frac{2}{3}\kappa, \frac{2}{3}(\kappa + 1)\right\}.
\end{align*}
By letting $C = 2/3$, the proof is finished.
\end{proof}

%We are ready to define the ``Voronoi cells''.
We denote by \[
\mathcal{VC} =
\mathcal{VC}(\kappa, \alpha):= \bigl\{\VC_{*}(i, j, k)\subset \R^{2}\bigm| {*}\in \{a, b, c\}\text{, }(i, j, k)\in V_{1}\bigr\}
\] the tiling by parallelograms $\VC_{*}(i, j, k)$ with respect to $\Isom(\R^{2})$.
We often call it the \emph{Voronoi tiling} (see Figure~\ref{fig:Voronoi-tiling}(a)).

\begin{rem}
\label{rem:Voronoi-name}
Removing all tiny triangles from a given Sturmian Lattice, we obtain a set of disjoint edges. Our set $\mathcal{VC}$ is the Voronoi diagram of $\R^2$ generated by the set of these edges, i.e., a classification of points in $\R^2$ by the nearest edge.
\end{rem}


