For (2), the situation boils down to the case~(b).
We provide a specific algorithm for finding $\AA = \{T_{1}, T_{2}\}\subset \Delta$ with $\TA\cap \TVC = \{\TVC(\alpha)\}$ for given quadratic $\alpha\in (0, 1)$.
From now on we also call such $\AA$ \emph{aperiodic} with respect to $\alpha$ although $\AA$ is a set of equivalent classes of tiles, since we can obtain an aperiodic tile set from $\AA$ by constructing BD correspondences.

For $T_{i} = [x_{i} : y_{i} : z_{i}]\in \Delta$ ($i = 1, 2$), $T_{1}$ is \emph{orthogonal} to $T_{2}$ if
\[
x_{1}x_{2} + y_{1}y_{2} + z_{1}z_{2} = 0
\]
holds, and we denote by $T_{1}\perp T_{2}$.
We also naturally define orthogonality between elements of $\Delta$ and $\R^{3}$.

The following proposition is useful for finding $\AA$.

\begin{prop}
\label{prop:Voronoi-formula}
Let $\alpha\in (0, 1)$ be a quadratic irrational number with the minimal monic polynomial
\[
f(\alpha):= \alpha^{2} + u\alpha + v = 0
\]
over $\Q$, and let
\[
\bm{n}(\alpha):= \begin{pmatrix}
v, & \dfrac{u}{2} + v, & u + v + 1
\end{pmatrix}\in \Q^{3}.
\]
Then for
\[
\AA = \bigl\{T_{i} = [x_{i} : y_{i} : z_{i}]\in \Delta \bigm| i\in \{1, 2\}\bigr\}
\]
with $x_{i}, y_{i}, z_{i}\in \Q_{\ge 0}$, the following are equivalent as long as $\TA\cap \TVC\ne \emptyset$.
\begin{enumerate}
\item
$\TVC(\alpha)\in \TA\cap \TVC$.
\item
Each $T_{i}$ is orthogonal to $\bm{n}(\alpha)$.
\end{enumerate}
\end{prop}

An element of $\AA$ is \emph{proper} if $\AA$ satisfies either (1) or (2) (and thus both).

\begin{proof}
First notice that one can characterize a vector $\bm{n}(\alpha)$ (up to scalar multiplication) as follows:
\begin{equation}
\label{eq:n-characterization}
\bm{n}(\alpha)\in \Q^{3}\text{ orthogonal to }\TVC(\alpha) = \begin{pmatrix}
(1 - \alpha)^{2}\\
2\alpha(1 - \alpha)\\
\alpha^{2}
\end{pmatrix}.
\end{equation}
Indeed, suppose $\bm{n} = (n_{1}, n_{2}, n_{3})\in \Q^{3}$ is orthogonal to $\TVC(\alpha)$, i.e.,\[
n_{1}(1 - \alpha)^{2} +
n_{2}\cdot 2\alpha(1 - \alpha) +
n_{3}\alpha^{2} = 0
\]and we have\[
(n_{1} - 2n_{2} + n_{3})\alpha^{2} +
2(n_{2} - n_{1})\alpha + n_{1} = 0.
\]Our assumption $\alpha\notin \Q$ implies that $n_{1} - 2n_{2} + n_{3}\ne 0$, and now we may assume $n_{1} - 2n_{2} + n_{3} = 1$.
By the uniqueness of minimal polynomial, we obtain that
\begin{align*}
u&= 2(n_{2} - n_{1}),&
v&= n_{1},
\end{align*}
and hence $n_{1} = v$, $n_{2} = u/2 + v$ and $n_{3} = 2n_{2} - n_{1} + 1 = u + v + 1$ as required.

For $\AA = \{T_{1}, T_{2}\}$, we define the $2$-dimensional subspace $\Pi(\AA) = \operatorname{span}\{T_{1}, T_{2}\}$ of $\R^{3}$.
Then one can see that (1) and (2) are equivalent to
\begin{enumerate}
\renewcommand{\labelenumi}{(\arabic{enumi})$'$}
\item
$\TVC(\alpha)\in \Pi(\AA)$, and
\item
$\bm{n}(\alpha)\in \Pi(\AA)^{\perp}$,
\end{enumerate}
respectively.
$(2)'\Rightarrow (1)'$ is clear since $\TVC(\alpha)$ is orthogonal to $\bm{n}(\alpha)$.
Conversely, suppose $(1)'$.
Then both $\bm{n}(\alpha)$ and $\bm{n} = T_{1}\times T_{2}$ in $\Q^{3}$ are orthogonal to $\TVC(\alpha)$.
By characterization \eqref{eq:n-characterization} of $\bm{n}(\alpha)$, they must coincide up to scalar multiplication.
It follows that $\bm{n}(\alpha)\propto \bm{n}\in \Pi(\AA)^{\perp}$ as required.
\end{proof}

We naturally identify Voronoi cells $S$, $M$, and $L$ with elements
\begin{align*}
S&= [1:0:0],&
M&= [0:1:0],&
L&= [0:0:1]
\end{align*}
in $\Delta$, and write
\[
xS + yM + zL:= [x : y : z]\in \Delta.
\]
We define map $\varphi\colon \Delta\to \R$ by
\[
\varphi(xS + yM + zL):=
xv + y\left(\frac{u}{2} + v\right) + z(u + v + 1).
\]
Even though $\varphi$ is not well-defined, it does not matter since we only focus on whether the value of $\varphi$ is zero or not.
For convenience, we also write
\[
\varphi(S) : \varphi(M) : \varphi(L) =
v : \left(\frac{u}{2} + v\right) : (u + v + 1).
\]

Define
\[
\AA(\alpha):= \{xS + yM + zL\in \Delta\mid
x, y, z\in \Z_{\ge 0}\text{ and }\varphi(xS + yM + zL) = 0\}.
\]
By definition $\bm{n}(\alpha)\perp \AA(\alpha)$ so that $\AA(\alpha)$ coincides with the set of proper tiles.

We finish the discussion for Theorem~\ref{thm:Voronoi-aperiodic}(2), we will see the strength of Proposition~\ref{prop:Voronoi-formula} to obtain $\AA$.

\begin{proof}[Proof of  Theorem~\ref{thm:Voronoi-aperiodic}(2).]
Let $\alpha\in (0, 1)$ be a quadratic irrational number.
We claim that at least two of $\varphi(S)$, $\varphi(M)$, $\varphi(L)$ have opposite signs.
Assume that all $\varphi(S)$, $\varphi(M)$, $\varphi(L)$ are have the same signs.
By Proposition~\ref{prop:Voronoi-formula}, vector $\bm{n}(\alpha)$ is orthogonal to $\TVC(\alpha) = [\delta_{S} : \delta_{M} : \delta_{L}]$, i.e.,
\[
\varphi(S)\delta_{S} + \varphi(M)\delta_{M} + \varphi(L)\delta_{L} = 0.
\]
Since $\alpha\in (0, 1)$, we have $\delta_{S}, \delta_{M}, \delta_{L} > 0$, and hence $\varphi(S) = \varphi(M) = \varphi(L) = 0$ is the only possibility.
However, since $f$ does not have rational roots, we obtain $\varphi(S) = v = f(0)\ne 0$ and $\varphi(L) = u + v + 1 = f(1)\ne 0$, which is a contradiction.

Thus there exists $A, B\in \{S, M, L\}$ with $a = \varphi(A) > 0 > \varphi(B) = -b$.
Take a patch-tile $T_{1} = bA + aB$, which satisfies that 
\[
\varphi(T_{1}) = b\varphi(A) + a\varphi(B) = 0.
\]
Let $C\in \{S, M, L\}\setminus \{A, B\}$ be the other cell.
We define patch-tile $T_{2}$ by
\[
T_{2} = \begin{cases}
C & \text{if }\varphi(C) = 0\\
cB + bC & \text{if }\varphi(C) = c > 0\\
cA + aC & \text{if }\varphi(C) =-c < 0
\end{cases}.
\]
We claim that $\TVC(\alpha)\in \TA$ for $\TA = \{T_{1}, T_{2}\}$.
By changing the labels, we may assume that 
\begin{align*}
T_{1}&= x_{1}A + y_{1}B,&
T_{2}&= x_{2}A + z_{2}C
\end{align*}
with $x_{1}, y_{1}, z_{2}\in \Q_{> 0}$, $x_{2}\in \Q_{\ge 0}$, and $x_{1} + y_{1} = x_{2} + z_{2} = 1$.
Then
\[
\TVC(\alpha) = [\delta_{S} : \delta_{M} : \delta_{L}] =
\left[
* : \frac{\delta_{M}}{y_{1}}y_{1} : \frac{\delta_{L}}{z_{2}}z_{2}
\right] =
\TA\left(\frac{\delta_{M}}{y_{1}}, \frac{\delta_{L}}{z_{2}}\right)\in \TA
\]
as claimed.
\end{proof}

We verify that this method is consistent with Sturmian substitution, i.e., the properness does not depend on the level of super Sturmian lattice.
Let $\alpha\in (0, 1)\setminus \Q$ be quadratic with \[
f(\alpha) = \alpha^{2} + u\alpha + v = 0,
\] and let $\alpha_{1} = \alpha^{-1} - \floor{\alpha^{-1}}$ with \[
f_{1}(\alpha_{1}) = \alpha_{1}^{2} + u_{1}\alpha_{1} + v_{1} = 0,
\]where $u, v, u_{1}, v_{1}\in \Q$.
We denote the Voronoi cells with respect to slopes $\alpha$ and $\alpha_{1}$ by $\{S, M, L\}$, $\{S_{1}, M_{1}, L_{1}\}$, respectively.
Then we can regard each $S_{1}$, $M_{1}$, and $L_{1}$ as a patch-tile of $\{S, M, L\}$.

\begin{prop}
\label{prop:proper-equiv}
A patch-tile $T = x_{1}S_{1} + y_{1}M_{1} + z_{1}L_{1}$ is proper with respect to slope $\alpha_{1}$ if and only if $T = xS + yM + zL$ is proper with respect to $\alpha$.
\end{prop}

A patch-tile $T$ is \emph{proper} with respect to slope $\alpha$ (resp.\ $\alpha_{1}$) if $T$ is proper as a patch-tile of $\{S, M, L\}$ (resp.\ $\{S_{1}, M_{1}, L_{1}\}$).

\begin{proof}
Let $a = \floor{\alpha^{-1}}$.
Then we can describe specifically each
\begin{align*}
S_{1}&= (a - 1)^{2}S + (2a - 2)M + L,\\
M_{1}&= a(a - 1)S + (2a - 1)M + L,\\
L_{1}&= a^{2}S + 2aM + L
\end{align*}
as a patch-tile of $\{S, M, L\}$ shown in  Figure~\ref{fig:superVC}.
This can also be written as \[
\begin{pmatrix}
S_{1} & M_{1} & L_{1}
\end{pmatrix} = \begin{pmatrix}
S & M & L
\end{pmatrix}A(a)
\] where \[
A(a):= \begin{pmatrix}
(a - 1)^{2} & a(a - 1) & a^{2}\\
2a - 2 & 2a - 1 & 2a\\
1 & 1 & 1
\end{pmatrix}
\] is a regular matrix with $\det A(a) = -1$.
In particular, we have \[
\begin{pmatrix}
x\\ y\\ z
\end{pmatrix} = A(a)\begin{pmatrix}
x_{1}\\ y_{1}\\ z_{1}
\end{pmatrix}
\] since $x_{1}S_{1} + y_{1}M_{1} + z_{1}L_{1} = xS + yM + zL$.

