\section{Proof of Proposition~\ref{prop:ND-result}}
\label{CalcND}

In this section, we describe the details of the necessary calculations for the natural densities of $\mathcal{S}$, $\mathcal{M}$, and $\mathcal{L}$.
Recall that we wish to show
\begin{align*}
\delta(\mathcal{S})&= (1 - \alpha)^{2},&
\delta(\mathcal{M})&= 2\alpha(1 - \alpha),&
\delta(\mathcal{L})&= \alpha^{2}.
\end{align*}
The discussion also yields immidiately that they are both uniformly spread.

To see this, we focus on $a$-direction.
Let \[
\mathcal{VC}_{a}:= \bigl\{\VC_{a}(i, j, k)\subset \R^{2}\bigm| (i, j, k)\in V_{1}\bigr\}
\]and
\begin{align*}
\mathcal{S}_{a}&:= \mathcal{S}\cap \mathcal{VC}_{a},&
\mathcal{M}_{a}&:= \mathcal{M}\cap \mathcal{VC}_{a},&
\mathcal{L}_{a}&:= \mathcal{L}\cap \mathcal{VC}_{a}.
\end{align*}
Respectively, $\delta(\mathcal{S})$, $\delta(\mathcal{M})$, and $\delta(\mathcal{L})$ are equal to relative natural densities
\begin{align*}
&\frac{\delta(\mathcal{S}_{a})}
{\delta(\mathcal{VC}_{a})},&
&\frac{\delta(\mathcal{M}_{a})}
{\delta(\mathcal{VC}_{a})},&
&\frac{\delta(\mathcal{L}_{a})}
{\delta(\mathcal{VC}_{a})}
\end{align*}
by symmetry.
%Indeed, for small cells, we obtain
%\[
%\frac{\delta(\mathcal{S}_{a})}
%{\delta(\mathcal{VC}_{a})} =
%\frac{\delta(\mathcal{S}_{b})}
%{\delta(\mathcal{VC}_{b})} =
%\frac{\delta(\mathcal{S}_{c})}
%{\delta(\mathcal{VC}_{c})}
%\]
%by symmetry, which follows that
%\begin{align*}
%\delta(\mathcal{S})&=
%\delta(\mathcal{S}_{a}) +
%\delta(\mathcal{S}_{b}) +
%\delta(\mathcal{S}_{c})\\&=
%\frac{\delta(\mathcal{S}_{a})}
%{\delta(\mathcal{VC}_{a})}\cdot
%\delta(\mathcal{VC}_{a}) +
%\frac{\delta(\mathcal{S}_{b})}
%{\delta(\mathcal{VC}_{b})}\cdot
%\delta(\mathcal{VC}_{b}) +
%\frac{\delta(\mathcal{S}_{c})}
%{\delta(\mathcal{VC}_{c})}\cdot
%\delta(\mathcal{VC}_{c})\\&=
%\frac{\delta(\mathcal{S}_{a})}
%{\delta(\mathcal{VC}_{a})}\bigl(
%\delta(\mathcal{VC}_{a}) +
%\delta(\mathcal{VC}_{b}) +
%\delta(\mathcal{VC}_{c})
%\bigr)\\&=
%\frac{\delta(\mathcal{S}_{a})}
%{\delta(\mathcal{VC}_{a})}.
%\end{align*}

Our discussion has two steps:
\begin{enumerate}
\item
A bijection $\varphi_{L}\colon \mathcal{G}_{L}\to \mathcal{L}_{a}$ induces $\mathcal{G}_{L}\BDsim \mathcal{L}_{a}$.
\item
A bijection $\psi_{L}\colon \mathcal{G}_{L}\to \Z^{2}$ shows that $\mathcal{G}_{L}$ is uniformly spread.
\end{enumerate}
Once these steps are complete, the computation of the natural density of Voronoi cells boils down to that of lattices.
This formulates the correspondence between small (resp.\ large) hexagonal units and intersections of two narrow (resp.\ wide) corridors.

We define map $\varphi\colon \mathcal{G}\to \mathcal{VC}_{a}$ by
\[
\varphi(G(i,j,k)) = \VC_{a}(i,j,k).
\]
Note that $\varphi\colon \mathcal{G}\to \mathcal{VC}_{a}$ is $2$-to-$1$ surjective, and that restrictions $\mathcal{G}_{\pm}\to \mathcal{VC}_{a}$ of $\varphi$ induce BD equivalences $\mathcal{G}_{\pm}\BDsim \mathcal{VC}_{a}$.

\begin{prop}
\label{prop:ST-VC}
If a Sturmian triangle $G\in \mathcal{G}$ is small (resp.\ large), then the Voronoi cell $\varphi(G)\in \mathcal{VC}_{a}$ is also small (resp.\ large).
\end{prop}

\begin{proof}
Let $G(i, j, k)\in \mathcal{G}_{-}$ be large.
By the proof of Proposition~\ref{prop:VC-shape}, we have
\[
a(i) + b(j) + c(k) = -\kappa - \frac{3}{2}.
\]
Recalling axiom (SL-2), one can also see that
\[
a(i) + b(j+1) + c(k) = \pm\frac{1}{2}
\]
holds for $(i, j+1, k)\in V_{0}$, and hence
\[
b(i+1) - b(i)\in \{\kappa + 1, \kappa + 2\}.
\]
Since the Sturmian lattice is regular, we have $b(i+1) - b(i) = \kappa + 1$.
Similarly, $c(k+1) - c(k) = \kappa + 1$ also holds.
These mean that each side of Voronoi cell
\[
\VC_{a}(i, j, k) = \Conv\bigl(
G(i, j, k), G(i, j+1, k), G(i, j+1, k+1), G(i, j, k+1)
\bigr)
\]
has length $C(\kappa + 1)$, proving $\VC_{a}(i, j, k)$ is large.
Similarly, $G\in \mathcal{G}_{+}\cap \mathcal{G}_{L}$ implies $\varphi(G)\in \mathcal{L}_{a}$.

In another case $G\in \mathcal{G}_{S}$, the regularity of Sturmian lattice also forces each side of $\varphi(G)$ to have length $C\kappa$, proving $\varphi(G)\in \mathcal{S}_{a}$.
\end{proof}

Proposition~\ref{prop:ST-VC} says that the restrictions
\begin{align*}
\varphi_{S}\colon \mathcal{G}_{S}&\to \mathcal{S}_{a},&
\varphi_{L}\colon \mathcal{G}_{L}&\to \mathcal{L}_{a}
\end{align*}
of $\varphi$ are well-defined.
We claim that these are bijective.

\begin{prop}
\label{prop:VC-ST}
The maps $\varphi_{S}$ and $\varphi_{L}$ are bijective.
\end{prop}

\begin{proof}
To prove for $\varphi_{L}$, we wish to construct the inverse map $\mathcal{L}_{a}\to \mathcal{G}_{L}$.

Let $L = \VC_{a}(i, j, k)\in \mathcal{L}_{a}$ and assume $i + j + k = -1$ without loss of generality.
By the proof of Proposition~\ref{prop:VC-shape}, $\VC_{a}(i, j, k)$ is large if and only if \[
b(j+1) - b(j) = c(k+1) - c(k) = \kappa + 1.
\]Recall that $\varphi\colon \mathcal{G}\to \mathcal{VC}_{a}$ is $2$-to-$1$, and the pre-image $\varphi^{-1}(L)$ of $L$ is \[
\varphi^{-1}(L) = \{G(i,j,k), G(i, j+1, k+1)\}.
\]We claim that one of them is large and the other is medium.
To show this, one can see that \[
\bigl(a(i) + b(j+1) + c(k+1)\bigr) -
\bigl(a(i) + b(j) + c(k)\bigr) = 2\kappa + 2.
\]Since $i + (j+1) + (k+1) = 1$ and $i + j + k = -1$, we also have \[
a(i) + b(j+1) + c(k+1),\ 
-\bigl(a(i) + b(j) + c(k)\bigr)\in
\left\{\kappa - \frac{1}{2}, \kappa + \frac{1}{2}, \kappa + \frac{3}{2}\right\}\\
\]by the proof of Proposition~\ref{prop:ST}.
Thus, either
\begin{align*}
\bigl|a(i) + b(j+1) + c(k+1)\bigr|&=
\kappa + \frac{1}{2},&
\bigl|a(i) + b(j) + c(k)\bigr|&=
\kappa + \frac{3}{2}\\
\intertext{or}
\bigl|a(i) + b(j+1) + c(k+1)\bigr|&=
\kappa + \frac{3}{2},&
\bigl|a(i) + b(j) + c(k)\bigr|&=
\kappa + \frac{1}{2}
\end{align*}
must hold.
In the former case
\begin{align*}
G(i,j+1,k+1)&\in \mathcal{G}_{M},&
G(i,j,k)&\in \mathcal{G}_{L}.\\
\intertext{In the latter case}
G(i,j+1,k+1)&\in \mathcal{G}_{L},&
G(i,j,k)&\in \mathcal{G}_{M}.
\end{align*}
Thus $\varphi^{-1}(L)\cap \mathcal{G}_{L}$ contains a single element, which means that $\varphi_{L}\colon \mathcal{G}_{L}\to \mathcal{L}_{a}$ is bijective.
The proof for $\varphi_{S}$ is analogous.
\end{proof}

Proposition~\ref{prop:VC-ST} also states that the hexagonal unit at $G_{S}$ (resp.\ $G_{L}$) is a regular hexagon with side length $C\kappa$ (resp.\ $C(\kappa + 1)$).
We call them a \emph{small} (resp.\ \emph{large}) \emph{hexagonal unit}.

We next define map $\psi\colon \mathcal{G}\to \Z^{2}$ by
\[
\psi(G(i, j, k)) = (j, k),
\]
which is $2$-to-$1$ surjective.
The restrictions $\psi\colon \mathcal{G}_{\pm}\to \Z^{2}$ are bijective, and each of these naturally deduces that $\mathcal{G}_{\pm}$ are uniformly spread (in a similar view to Remark~\ref{rem:approx-trigonal}).
Similarly, $\mathcal{G}_{S}$ and $\mathcal{G}_{L}$ are also uniformly spread.

\begin{prop}
\label{prop:ST-ZZ}
The maps $\psi_{S}$ and $\psi_{L}$ are injective, and the images are
\begin{align*}
\psi_{S}(\mathcal{G}_{S})&= \{(j, k)\in \Z^{2}\mid b_{j} = c_{k} = 0\},&
\psi_{L}(\mathcal{G}_{L})&= \{(j, k)\in \Z^{2}\mid b_{j} = c_{k} = 1\}.
\end{align*}
\end{prop}

\begin{proof}
This is trivial by Proposition~\ref{prop:VC-ST}.
The claim follows for $\psi_{L}$ since
\begin{align*}
G = G(i, j, k)\in \mathcal{G}_{L}&\iff
\varphi_{L}(G) = \VC_{a}(i, j, k)\in \mathcal{L}_{a}\\&\iff
b_{j} = c_{k} = 1.
\end{align*}
The proof for $\psi_{S}$ is analogous.
\end{proof}

Since both $\varphi_{+}\colon \mathcal{G}_{+}\to \mathcal{VC}_{a}$ and $\varphi_{L}\colon \mathcal{G}_{L}\to \mathcal{L}_{a}$ are BD bijections (in particular, they preserve natural densities), we have
\[
\delta(\mathcal{L}) =
\frac{\delta(\mathcal{L}_{a})}
{\delta(\mathcal{VC}_{a})} =
\frac{\delta(\varphi_{L}^{-1}(\mathcal{L}_{a}))}
{\delta(\varphi_{+}^{-1}(\mathcal{VC}_{a}))} =
\frac{\delta(\mathcal{G}_{L})}
{\delta(\mathcal{G}_{+})}.
\]
By Proposition~\ref{prop:ST-ZZ}, we obtain
\[
\frac{\delta(\mathcal{G}_{L})}
{\delta(\mathcal{G}_{+})} =
\lim_{N\to \infty}\left(
\frac{\abs{b_{[-N,N]}}_{1}}
{\abs{b_{[-N,N]}}}\cdot 
\frac{\abs{c_{[-N,N]}}_{1}}
{\abs{c_{[-N,N]}}}\right) = \alpha^{2},
\]
and similarly 
\[
\delta(\mathcal{S}) =
\frac{\delta(\mathcal{S}_{a})}
{\delta(\mathcal{VC}_{a})} =
\frac{\delta(\mathcal{G}_{S})}
{\delta(\mathcal{G}_{+})} =
(1 - \alpha)^{2}.
\]
Since $\mathcal{VC} = \mathcal{S}\vee \mathcal{M}\vee \mathcal{L}$ and our setting $\delta(\mathcal{VC}) = 1$, we have
\[
\delta(\mathcal{M}) =
1 - \alpha^{2} - (1 - \alpha)^{2} =
2\alpha(1 - \alpha),
\]
which concludes a proof for the natural densities of Voronoi cells.

Finally we check that $\mathcal{S}$, $\mathcal{M}$, and $\mathcal{L}$ are all uniformly spread by Proposition~\ref{prop:add-sub}.
Indeed, since $\mathcal{VC}_{*}\BDsim \mathcal{G}_{+}$, $\mathcal{S}_{*}\BDsim \mathcal{G}_{S}$, and $\mathcal{L}_{*}\BDsim \mathcal{G}_{L}$ are all uniformly spread, so are
\begin{align*}
\mathcal{VC}&= \mathcal{VC}_{a}\vee \mathcal{VC}_{b}\vee \mathcal{VC}_{c},&
\mathcal{S}&= \mathcal{S}_{a}\vee \mathcal{S}_{b}\vee \mathcal{S}_{c},&
\mathcal{L}&= \mathcal{L}_{a}\vee \mathcal{L}_{b}\vee \mathcal{L}_{c}.
\end{align*}
These also imply that $\mathcal{M} =
\mathcal{VC}\setminus (\mathcal{S}\vee \mathcal{L})$ is uniformly spread.

\begin{rem}
\label{rem:difficulty-M}
Since $\mathcal{G}_{L}\BDsim \mathcal{L}_{a}$ and $\mathcal{G}_{S}\BDsim \mathcal{S}_{a}$, we also have $\mathcal{G}_{M}\BDsim \mathcal{M}_{a}$.
However, we cannot obtain an associated bijection $\varphi_{M}\colon \mathcal{G}_{M}\to \mathcal{M}_{a}$ only by restricting $\varphi$, in contrast to the cases for $\varphi_{S}$ and $\varphi_{L}$.
\end{rem}

