\section{An example: the quantum brachistochrone}\label{S7}
In this section we will apply the general method developed in the previous section to the optimal control of the quantum brachistrochrone problem. The Lagrangian for the quantum brachistochrone problem is \cite{carlini2005quantum, koike2022quantum} \footnote{Our Lagrangian differs from those of \cite{carlini2005quantum, koike2022quantum}, in which the authors use the Fubini--Study 
metric to define the infinitesimal line element $ds$. However, this 
makes no difference to the values of the optimal control, or to the optimal
trajectories.}
\begin{equation}\label{Q_L}
	L = 1 + \Lambda\biggl(\frac{\mathrm{Tr}\tilde{H}^2}{2}-\omega^2 \biggl) - i \braket{\phi|\dot{\psi}} + \braket{\phi|H|\psi} + i \braket{\dot{\psi}|\phi} +\braket{\psi|H|\phi},
\end{equation}
where $\Lambda$ is a constant Lagrange multiplier that enforces the energy upper bound of the control via the constraint $\frac{\mathrm{Tr}\tilde{H}^2}{2}-\omega^2$, and $\bra{\phi}$ is a dynamical Lagrange multiplier which enforces the dynamical constraint coming from the Schr\"{o}dinger's equation, $i\ket{\dot{\psi}}=H\ket{\psi}$. The operator $\tilde{H}=H-\frac{\mathrm{Tr}H}{n}$ is the traceless part of the Hamiltonian $H$.

The canonical momenta following from the Lagrangian (\ref{Q_L}) are
\begin{align}
	\bra{P} = \frac{\partial L}{\partial\dot{\ket{\psi}}} = -i\bra{\phi}&;\qquad
	\ket{P} = \frac{\partial L}{\partial\dot{\bra{\psi}}} = i\ket{\phi}; \\
	\bra{\pi} = \frac{\partial L}{\partial \dot{\ket{\phi}}} = 0 &;\qquad
	\ket{\pi} = \frac{\partial L}{\partial\dot{\bra{\phi}}} = 0; \\
	P_H = \frac{\partial L}{\partial\ket{\dot{H}}} = 0;  ~~~~~~ &P_\Lambda = \frac{\partial L}{\partial\ket{\dot{\Lambda}}} = 0.
\end{align}

Thus, we have the primary constraints
\begin{align}
	\label{qp1}
	\chi^{\ket{\psi}} = \bra{P} + i\bra{\phi}\approx 0;~~~ &\chi^{\bra{\psi}} = \ket{P} - i\ket{\phi}\approx 0; \\
	\chi^{\ket{\phi}} = \bra{\pi}\approx 0;~~~ &\chi^{\bra{\phi}} = \ket{\pi} \approx 0;\\
	\label{qp3}
	\chi^{H} = P_H \approx 0 ;~~~ &\chi^{\Lambda} = P_\Lambda \approx 0.
\end{align}
The canonical Hamiltonian can be obtained by the Legendre transformation
\begin{equation}
	\begin{split}
		H_c =  \ket{\dot{\psi}} \bra{P}+ \ket{P} \bra{\dot{\psi}} +  \ket{\dot{\phi}}\bra{\pi}+\ket{\pi} \bra{\dot{\phi}} + P_H \dot{H} +P_\Lambda \dot{\Lambda} - L\\
		=-1-\Lambda \biggl(\frac{Tr\tilde{H}^2}{2}-\omega^2 \biggl) -\braket{\phi|H|\psi}-\braket{\psi|H|\phi}.
	\end{split}
\end{equation}
Similarly, the primary Hamiltonian is given by
\begin{equation}
	\begin{split}
		H_p 
		=-1-\Lambda \biggl(\frac{Tr\tilde{H}^2}{2}-\omega^2 \biggl) -\braket{\phi|H|\psi}-\braket{\psi|H|\phi} &+ \lambda^{\ket{\psi}}\Bigl(\bra{P}+i\bra{\phi}\Bigl)+\lambda^{\bra{\psi}}\Bigl(\ket{P}-i\ket{\phi}\Bigl)\\
		&+\lambda^{\ket{\phi}} \bra{\pi} +\lambda^{\bra{\phi}} \ket{\pi}+\lambda^{H} P_H + \lambda^{\Lambda} P_\Lambda.
	\end{split}
\end{equation}
The consistency of the primary constraints over time yields
\begin{align}
	\label{z1}
	&\dot{\chi}^{\ket{\psi}} = \Bigl\{\chi^{\ket{\psi}}  , H_p \Bigl\} = \bra{\phi}H  + i \lambda^{\bra{\phi}}\neq 0 \implies \lambda^{\bra{\phi}} = i \bra{\phi}H; \\
	\label{z2}
	&\dot{\chi}^{\bra{\psi}} = \Bigl\{\chi^{\bra{\psi}}  , H_p \Bigl\} =  H\ket{\phi} - i \lambda^{\ket{\phi}}\neq 0 \implies \lambda^{\ket{\phi}} = -iH\ket{\phi} ;\\
	\label{z3}
	&\dot{\chi}^{\ket{\phi}} = \Bigl\{\chi^{\ket{\phi}} , H_p \Bigl\}= \bra{\psi}H+i \lambda^{\bra{\psi}} \neq 0 \implies \lambda^{\bra{\psi}} = i \bra{\psi}H;\\
	\label{z4}
	&\dot{\chi}^{\bra{\phi}} = \Bigl\{\chi^{\bra{\phi}} , H_p \Bigl\}= H\ket{\psi}-i \lambda^{\ket{\psi}} \neq 0 \implies \lambda^{\ket{\psi}} = -i H\ket{\psi};\\
	\label{z5}
	&\dot{\chi}^{H} = \Bigl\{P_H , H_p \Bigl\} = \ket{\psi}\bra{\phi}+\ket{\phi}\bra{\psi} + \Lambda\tilde{H} \neq 0;\\
	\label{z6}
	&\dot{\chi}^{\Lambda} = \Bigl\{P_{\Lambda}, H_p\Bigl\} = \frac{\mathrm{Tr}\tilde{H}^2}{2}-\omega^2 \neq 0.
\end{align}
Eqs.\ (\ref{z5}) and (\ref{z6}) give the following secondary constraints:
\begin{align}
	\label{qs1}
	&\chi^{\Lambda^{\prime}} = \frac{\mathrm{Tr}\tilde{H}^2}{2}-\omega^2  \approx 0; \\
	\label{qs2}
	&\chi^{H^\prime} = \ket{\psi}\bra{\phi}+\ket{\phi}\bra{\psi} + \Lambda\tilde{H} \approx 0,
\end{align}
whose consistency entails
\begin{align}
	&\dot{\chi}^{\Lambda^{\prime}}=\Bigl\{\chi^{\Lambda^{\prime}}, H_p\Bigl\}= \lambda^H \tilde{H} \neq 0 \implies \lambda^H = 0, ~~~\hbox{since} ~~\tilde{H}\neq 0;\\
	&\dot{\chi}^{H^\prime} =\Bigl\{\chi^{H^\prime}, H_p\Bigl\}= \lambda^H \Lambda (1-\frac{1}{n}) + \lambda^{\Lambda} \tilde{H} \neq 0 \implies \lambda^\Lambda = 0,~~~\hbox{since}~~ \lambda^H = 0.
\end{align}
Thus, all the new Lagrange multipliers are fixed with all the constraints being preserved over time. 

The Poisson brackets between the constraints (both primary and secondary) follow from eqs.\ (\ref{qp1}--\ref{qp3}) and (\ref{qs1}--\ref{qs2}):
\begin{equation}
	\begin{split}
		&\Bigl\{\chi^{\ket{\psi}}, \chi^{H^{\prime}}\Bigl\} = -\bra{\phi};~~~ \Bigl\{\chi^{\bra{\psi}}, \chi^{H^{\prime}}\Bigl\} = -\ket{\phi}; \\
		&\Bigl\{\chi^{\ket{\phi}},\chi^{H^{\prime}}\Bigl\} = -\bra{\psi};~~~\Bigl\{\chi^{\bra{\phi}}, \chi^{H^{\prime}}\Bigl\} = -\ket{\psi};\\
		&\Bigl\{\chi^{\Lambda^{\prime}}, \chi^{H}\Bigl\} = \tilde{H}; ~~~ ~~~~~\Bigl\{\chi^{\Lambda}, \chi^{H^{\prime}}\Bigl\} = -\tilde{H}.
	\end{split}
\end{equation}
Thus, all the constraints are second-class. We relabel them as
\begin{align}
	\label{zeta1}
	&\zeta_1 = \bra{P} + i\bra{\phi}\approx 0;\\
	&\zeta_2 = \ket{P} - i\ket{\phi}\approx 0;\\
	&\zeta_3 = \bra{\pi}\approx 0;\\
	&\zeta_4 = \ket{\pi}\approx 0;\\
	&\zeta_5 = P_H\approx 0;\\
	&\zeta_6 = P_\Lambda\approx 0;\\
	\label{zeta7}
	&\zeta_7 =  \ket{\psi}\bra{\phi}+\ket{\phi}\bra{\psi} + \Lambda\tilde{H} \approx 0;\\
	\label{zeta8}
	&\zeta_8 = \frac{\mathrm{Tr}\tilde{H}^2}{2}-\omega^2  \approx 0.
\end{align}
The matrix of the Poisson brackets amongst all the second-class constraints is given by
\[ D_{\alpha \beta} =
\begin{pmatrix}
	0 &0 &0 &i &0 &0 &-\bra{\phi}  &0 \\
	0 &0 &-i &0 &0 &0 &-\ket{\phi}  &0 \\
	0 &i &0 &0 &0 &0 &-\bra{\psi}  &0 \\
	-i &0 &0 &0 &0 &0 &-\ket{\psi}  &0 \\
	0 &0 &0 &0 &0 &0 &-\Lambda(1-\frac{1}{n})  &-\tilde{H} \\
	0 &0 &0 &0 &0 &0 &-\tilde{H}  &0 \\
	\bra{\phi} &\ket{\phi} &\bra{\psi} &\ket{\psi} &\Lambda(1-\frac{1}{n}) &\tilde{H} &0  &0 \\
	0 &0 &0 &0 &\tilde{H} &0 &0  &0 \\
\end{pmatrix},
\]
and its inverse matrix

\[ D_{\alpha \beta}^{-1} =
\begin{pmatrix}
	0 &0 &0 &-\frac{1}{i} &0 &\frac{\ket{\psi}}{i\tilde{H}} &0  &0 \\
	0 &0 &\frac{1}{i} &0 &0 &-\frac{\bra{\psi}}{i\tilde{H}} &0  &0 \\
	0 &-\frac{1}{i} &0 &0 &0 &\frac{\ket{\phi}}{i\tilde{H}} &0  &0 \\
	\frac{1}{i} &0 &0 &0 &0 &-\frac{\bra{\phi}}{i\tilde{H}} &0  &0 \\
	0 &0 &0 &0 &0 &0 &0  &\frac{1}{\tilde{H}} \\
	-\frac{\ket{\psi}}{i\tilde{H}} &\frac{\bra{\psi}}{i\tilde{H}} &-\frac{\ket{\phi}}{i\tilde{H}} &\frac{\bra{\phi}}{i\tilde{H}} &0 &0 &\frac{1}{\tilde{H}}  &-\frac{\Lambda(1-\frac{1}{n})}{\tilde{H}^{2}} \\
	0 &0 &0 &0 &0 &-\frac{1}{\tilde{H}} &0  &0 \\
	0 &0 &0 &0 &-\frac{1}{\tilde{H}} &\frac{\Lambda(1-\frac{1}{n})}{\tilde{H}^{2}} &0  &0 \\
\end{pmatrix}.
\]
Now, on the constrained subspace, the conditions eqs.\ (\ref{zeta1}--\ref{zeta8}) hold strongly, i.e., 
\begin{align}
	\label{zee7}
	&\zeta_7 =  \ket{\psi}\bra{\phi}+\ket{\phi}\bra{\psi} + \Lambda\tilde{H} = 0;\\
	\label{zee8}
	&\zeta_8 = \frac{\mathrm{Tr}\tilde{H}^2}{2}-\omega^2  = 0.
\end{align}
The equations of motion for $\ket{\psi}$ and $\ket{\phi}$ can then be obtained by 
\begin{equation}
	\begin{split}
		\label{psi}
		\ket{\dot{\psi}} &= \bigl\{\ket{\psi}, H_c \bigl\} - \bigl\{\ket{\psi},\zeta_{\alpha} \bigl\} D^{-1}_{\alpha\beta} \bigl\{\zeta_{\beta},H_c \bigl\}
		= \frac{H\ket{\psi}}{i}  - \frac{\ket{\psi}}{i\tilde{H}} \biggl(\frac{\mathrm{Tr}\tilde{H}^2}{2}-\omega^2\biggl) \\
		&= \frac{H\ket{\psi}}{i};
	\end{split}
\end{equation}
\begin{equation}
	\label{phi}
	\begin{split}
		\ket{\dot{\phi}} &= \bigl\{\ket{\phi}, H_c \bigl\} - \bigl\{\ket{\phi},\zeta_{\alpha} \bigl\} D^{-1}_{\alpha\beta} \bigl\{\zeta_{\beta},H_c \bigl\}
		= \frac{H\ket{\phi}}{i}  - \frac{\ket{\phi}}{i\tilde{H}} \biggl(\frac{\mathrm{Tr}\tilde{H}^2}{2}-\omega^2\biggl) \\
		&= \frac{H\ket{\phi}}{i},
	\end{split}
\end{equation}
where in the last step of eqs.\ (\ref{psi}) and (\ref{phi}), we eliminate the last term using the second class constraint eq.\ (\ref{zee8}). These equations of motion are seen to be in agreement with \cite{koike2022quantum}.

Now we can use eq.\ (\ref{zee7}) to find the optimal value of the control with the help of eqs.\ (\ref{zee8}--\ref{phi}). Taking the trace of eq.\ (\ref{zee7}),
\begin{equation}
	\label{im}
	\braket{\psi|\phi}^{\star} = -\braket{\psi|\phi}, \hbox{ since Tr} \tilde{H} = 0.
\end{equation} 
The expectation value of eq.\ ({\ref{zee7}}) with respect to $\ket{\psi}$ then implies that
\begin{equation}
	\label{avg_H}
	\braket{\tilde{H}} = 0,~\hbox{which is equivalent to } \braket{H} = \frac{\mathrm{Tr}H}{n}.
\end{equation}
Applying eq.\ (\ref{zee7}) to $\ket{\psi}$,
\begin{equation}
	\label{fi}
	\ket{\phi} = \biggl(-\lambda \tilde{H} + \braket{\psi|\phi}\biggl)\ket{\psi}.
\end{equation}
Inserting this back into eq.\ (\ref{zee7}), we get
\begin{equation}
	\label{H_OP}
	\tilde{H} = \tilde{H} P + P \tilde{H},
\end{equation}
which gives the optimal Hamiltonian and $P=\Ket{\psi}\bra{\psi}$. From eqs.\ (\ref{avg_H}) and (\ref{H_OP}), we get
\begin{equation}\label{const}
	(\Delta E)^2 = \braket{H^2} - \braket{H}^2 = \braket{\tilde{H}^2} = \frac{\mathrm{Tr}\tilde{H}^2}{2} = \omega^2.
\end{equation}
Substituting eq.\ (\ref{fi}) back into eq.\ (\ref{zee7}), we get
\begin{equation}\label{OP}
	\frac{d}{dt} (\lambda \tilde{H})\ket{\psi}=0.
\end{equation}
Multiplying throughout by $\bra{\psi}H$, we get $\lambda$ to be a constant. Subsequently, eq.\ (\ref{OP}) implies 
\begin{equation}\label{deriH}
	\frac{d\tilde{H}}{dt}\ket{\tilde{\psi}}=0.
\end{equation}
Considering $\ket{\tilde{\psi}}=\exp\bigl[i\int_{0}^{t}dt\braket{H}\bigr]\ket{\psi}$, it is easy to conclude that $\ket{\tilde{\psi}}$ satisfies the Schr\"{o}dinger equation with the optimal Hamiltonian $\tilde{H}$:
\begin{equation}\label{new_Schro}
	i\ket{\tilde{\psi}} = \tilde{H}\ket{\tilde{\psi}} ~~~ \hbox{and}~~~P=\ket{\psi}\bra{\psi} =\ket{\tilde{\psi}}\bra{\tilde{\psi}}=\tilde{P}.
\end{equation} 
Using eqs.\ (\ref{new_Schro}) and (\ref{H_OP}), we find
\begin{equation}\label{tildeH}
	\tilde{H}=i\biggl(\ket{\dot{\tilde{\psi}}}\bra{\tilde{\psi}}-\ket{\tilde{\psi}}\bra{\dot{\tilde{\psi}}}\biggr).
\end{equation} 
Eq.\ (\ref{avg_H}) implies that $\braket{\dot{\tilde{\psi}}|\tilde{\psi}}=0$. Then using eqs.\ (\ref{tildeH}) and (\ref{new_Schro}), eq.\ (\ref{deriH}) implies
\begin{equation}\label{opti_t}
	(1-\tilde{P})\ket{\ddot{\tilde{\psi}}}=0,
\end{equation}
which is the optimal trajectory for the quantum brachistochrone. Using eqs.\ (\ref{tildeH}), (\ref{opti_t}) and (\ref{avg_H}), we get
\begin{equation}\label{H0}
	\dot{\tilde{H}}=0.
\end{equation}
Now using equation eqs.\ (\ref{new_Schro}) and (\ref{H0}), the differential equation for the optimal trajectory becomes
\begin{equation}\label{eq161}
	\ket{\ddot{\tilde{\psi}}} = -\omega^2
	\ket{\tilde{\psi}},
\end{equation}
where we have used [eq.\ (\ref{const})] $\braket{\tilde{\psi}|\tilde{H}^2|\tilde{\psi}}=(\Delta E)^2 = \omega^2$. One can solve eq.\ (\ref{eq161}) with the initial conditions on $\ket{\tilde{\psi}(0)}$ and $\ket{\dot{\tilde{\psi}}(0)}$ to get
\begin{equation}\label{op_tr}
	\ket{\tilde{\psi}(t)}=\cos(\omega t) \ket{\tilde{\psi}(0)}+\frac{\sin (\omega t)}{\omega} \ket{\dot{\tilde{\psi}}(0)}
\end{equation}

Thus, the Dirac--Bergmann approach correctly reproduces the known results \cite{carlini2005quantum} for the optimal Hamiltonian [eq.\ (\ref{H_OP})] and the optimal trajectories [eq.\ (\ref{op_tr})].
