	&(D^{-1})_{11,2} = \frac{x_4^4}{(x_2^2 + x_4^2)(x_4 \Lambda_3 + g \Lambda_4)}
\end{align*}
\vspace{-15pt}
\begin{align*}
	(D^{-1})_{11,4} &= -\frac{x_2 x_4^3}{(x_2^2 + x_4^2)(x_4 \Lambda_3 + g \Lambda_4)} \
	&(D^{-1})_{11,7} = \frac{x_4^3 \Lambda_4}{(x_2^2 + x_4^2)(x_4 \Lambda_3 + g \Lambda_4)}
\end{align*}
\vspace{-15pt}
\begin{align*}
	(D^{-1})_{11,9} &= -\frac{x_2 x_4^2 \Lambda_4}{(x_2^2 + x_4^2)(x_4 \Lambda_3 + g \Lambda_4)} \
	&(D^{-1})_{11,10} = \frac{2 g x_4^3 (-x_2^2 + x_4^2)}{(x_2^2 + x_4^2)^2 (x_4 \Lambda_3 + g \Lambda_4)}
\end{align*}
\vspace{-15pt}
\begin{align*}
	(D^{-1})_{11,12} &= -\frac{x_4^4}{(x_2^2 + x_4^2)(x_4 \Lambda_3 + g \Lambda_4)} \
	&(D^{-1})_{12,9} = -1
\end{align*}
