\subsection{Spencer-regularity}
A cohomological vanishing criteria for PDEs is now introduced which is compatible with Definition \ref{defn: D-geom m-involutive}. Given a $\D$-subscheme $Z\subset \mathrm{Spec}_{\D}(\A)$, defined by a $\D$-stable ideal $\I$, we will always now write $\mathrm{gr}(\mathcal{I})$ for the symbolic module, to emphasize it is determined via $\mathcal{I}.$ See the following remark.

\begin{rmk}
\label{gr(I)}
Consider a $\D$-subscheme $Z\subset \mathrm{Spec}_{\D}(\A)$ and consider the standard filtrations (\ref{defn: Standard filt}). Geometrically (c.f. \ref{eqn: Cosymbol iso}), morphisms $J_X^{\ell
+1}E\rightarrow J_X^{\ell}E$ are affine with associated vector bundle, 
$(p_{\ell}^0)^*Sym^{\ell}(T_X^*)\otimes(p_{\ell}^1)^*T_{E/X},$ with $p_{\ell}^k:J_X^kE\rightarrow J_x^{\ell}E,$ where $J_X^0E=E.$ Dualizing, gives (\ref{eqn: ChKahler1}).
Thus, set $\mathrm{gr}(\A)\simeq Sym_{\mathcal{O}_X}(\Theta_X)\otimes_{\mathcal{O}_X}\mathcal{E},$ with $\mathcal{E}$ the sheaf associated with $E.$ Then $\mathrm{gr}(\I):=\oplus_q F^q\mathcal{I}/F^{q-1}\mathcal{I}\subset \mathrm{gr}(\A).$ We have $\mathrm{gr}_q(\I)\subset Sym^q(\Theta_X)\otimes \mathcal{E}.$
\end{rmk}






Denote by $\mathcal{H}_{\delta}^{p,q}(\mathrm{gr}(\mathcal{I}))$ the $\delta$-Spencer cohomologies.
\begin{defn}
\label{defn: D-geometric generalized involutivity}
\normalfont 
Let $Z$ be formally integrable and involutive. Its \emph{degree of involution} is 
    $\mathrm{reg}_{Sp}(\mathcal{I}):=\underset{q_0\in \mathbb{N}}{\mathrm{inf}}\big\{H_{\delta}^{p,q}(\mathrm{gr}(\mathcal{I}))=0,\text{ for all } 0\leq p\leq \mathrm{dim}X, q\geq q_0\big\}.$
Module $\mathrm{gr}(\mathcal{I})$ is said to be \emph{$p_0$-acyclic at $q_0$} for $0\leq p_0\leq \mathrm{dim}X$ if:
 $H_{\delta}^{p,q}(\mathrm{gr}(\mathcal{I}))=0,\hspace{2mm} \forall q\geq q_0, 0\leq p\leq p_0.$
\end{defn}
We use the notation $\mathrm{reg}_{Sp}$ due to the following result.
\begin{prop}
\label{prop: Unifying}
    Suppose that $\mathcal{I}$ is formally integrable and $\D$-involutive. Then its degree of involution, given by Definition \ref{defn: D-geometric generalized involutivity} agrees with the Spencer-regularity (\ref{defn: D-Geometric Regularity}), and thus agrees with the Castelnuovo-Mumford regularity of its (linearized, in the non-linear setting) symbolic $\D$-module. 
\end{prop}
The proof makes use of tools not introduced above e.g. Pommaret basis. See \cite{Ma} for details.
\begin{proof}
The Koszul homology of $\mathcal{M}$ is equivalent to its minimal free resolution, if $\mathrm{reg}_{CM}(\mathcal{I})=m,$ meaning $Syz^i(\mathcal{I})$ is generated in degrees $\leq m+i,$ then 
$H_{p,q}(\mathcal{I})=0,\forall q>\mathrm{reg}_{CM}(\mathcal{I})=m.$
If one has a local involutive basis $\mathcal{H}_q$ for Pommaret division and $\mathcal{I}_{k+1}$ are the homogeneous degree $k+1$ elements, then
$\mathrm{dim}(\mathcal{I}_{k+1})\geq \sum_{\ell=1}^{\mathrm{dim}(X)}\ell\cdot \beta_k^{(\ell)}.$
It is an equality if and only if it gives rise to a Pommaret basis. The integers $\beta_k^{(\ell)}$ are the number of elements in the basis with leading term of class $\ell.$
Let $H_{p,q}$ denote the Koszul homology, then one has
$H_{p,q}(\mathcal{I})=0\forall r>\mathrm{reg}_{CM}(\mathcal{I})=m \Leftrightarrow H_{p,q}(\mathcal{M})=0,\forall q\geq \mathrm{reg}_{CM}(\mathcal{I}).$
Therefore, $\mathrm{reg}_{CM}=\mathrm{reg}_{Sp}(\mathcal{I}).$ 
If $\mathcal{H}_k$ is the basis of $\mathcal{I}_k$ whose generators have different leading terms, we may choose as representatives of a basis of $\mathcal{M}_k$ polynomials whose leading terms do not appear in the leading term set of $\mathcal{H}_k.$ Thus, if $\mathcal{H}_k$ contains $\beta_k^{(\ell)},$ elements with leading term of class $\ell$, the basis of $\mathcal{M}_k$ contains
$\alpha_k^{(\ell)}=m\cdot C_{k-1}^{k+n-\ell-1}-\beta_k^{(\ell)}$,
representatives.
\end{proof}
We also have the following obvious statement.
\begin{prop}
    If $Z$ is Spencer $m$-regular, then it is Spencer $m'$-regular for all $m'\geq m.$
\end{prop}

Giving a sequence of $\D$-ideal sheaves in the same ambient $\D$-algebra of jets gives a sequence of corresponding characteristic modules.

\begin{prop}
\label{prop: Involutivity sequences}
    Consider smooth morphisms of $\D$-schemes, $\mathcal{Y}'\rightarrow \mathcal{Y}\rightarrow \mathcal{Y}''$ defined by $\D$-ideal sheaves $\I',\I,\I'',$ respectively, which induce a short exact sequence of symbolic modules. Suppose each $\D$-scheme is Spencer regular. The following statements hold:
    \begin{enumerate}
    \item Suppose that $\mathrm{reg}_{Sp}(\I')=\mathrm{reg}_{Sp}(\I'')=m$.Then $\mathrm{reg}_{Sp}(\I)=m;$

    \item Suppose that $\mathrm{reg}_{Sp}(\I')=(m+1)$ and $\mathrm{reg}_{Sp}(\I)=m.$ Then $\mathrm{reg}_{Sp}(\I'')=(m+1);$

    \item Suppose that $\mathrm{reg}_{Sp}(\I)=m$ and $\mathrm{reg}_{SP}(\I'')=(m-1).$ Then $\mathrm{reg}_{Sp}(\I')=m.$
    \end{enumerate}
\end{prop}
\begin{proof}
This is proven using long-exact sequence and standard homological arguments. In some detail, consider the relative cotangent sequence associated to the morphism of $\D$-schemes $\EQ'\rightarrow\EQ\rightarrow \EQ''$ and the corresponding long-exact sequence in cohomology applied to the Spencer sequences of these cotangent sheaves e.g.
$$\alpha^*\Omega_{\EQ/\EQ^{''}}^1\rightarrow \Omega_{\EQ^{'}/\EQ^{''}}^1\rightarrow \Omega_{\EQ^{'}/\EQ}^1\rightarrow 0,$$
or dually, denoting the corresponding commutative $\mathcal{D}_X$-algebras by $\mathcal{A},\mathcal{A}',\mathcal{A}^{''},$ 
we have a sequence $\mathcal{A}^{'}\otimes_{\mathcal{O}_X}\mathcal{D}_X$-modules,
$$\mathcal{A}^{'}\otimes_{\mathcal{A}}\Omega_{\mathcal{A}/\mathcal{A}^{''}}^1\rightarrow \Omega_{\mathcal{A}'/\mathcal{A}''}^1\rightarrow\Omega_{\mathcal{A}'/\mathcal{A}}^1\rightarrow 0.$$
Using the exact sequences,
$p_{\infty}^*\Omega_{E/X}^1\rightarrow \Omega_{\EQ/X}^1\rightarrow \Omega_{\EQ/E}^1\rightarrow 0,$
for each structure map $p_{\infty}:\EQ\rightarrow X,p_{\infty}^{'}:\EQ^{'}\rightarrow X,p_{\infty}^{''}:\EQ^{''}\rightarrow X,$ together with the sequences (\ref{eqn: Filtered Kahler sequences}), one establishes the claim by passing to the corresponding long-exact sequence. Simply denoting the induced sequence of graded modules $\mathrm{gr}(\I')\rightarrow \mathrm{gr}(\I)\rightarrow \mathrm{gr}(\I''),$ a segment of the LES is 
$$\cdots\rightarrow \mathcal{H}_{Sp}^{p,q}\big(\mathrm{gr}(\I'')\big)\rightarrow \mathcal{H}_{Sp}^{p,q}\big(\mathrm{gr}(\I)\big)\rightarrow \mathcal{H}_{Sp}^{p,q}\big(\mathrm{gr}(\I')\big)\rightarrow \cdots.$$
For (i), since $\mathcal{H}_{Sp}^{p,q}\big(\mathrm{gr}(\I')\big)=\mathcal{H}_{Sp}^{p,q}\big(\mathrm{gr}(\I'')\big)=0,q\geq m$ and for all $p$, the claim is obvious. Claim (ii) is proven similarly, and (iii) reduces to a sequence of the form 
$$0\rightarrow \mathcal{H}_{Sp}^{p,q}\big(\mathrm{gr}(\I')\big)\rightarrow 0,$$
precisely at $q=m.$
\end{proof}

\section{Moduli of $\D_X$-ideal sheaves}
\label{sec: Moduli Space of D-Ideal Sheaves}
This section establishes the construction of the $\D$-geometric analog of the Hilbert and Quot functors that parameterize ideal sheaves in $\D$-geometry with Spencer-regular behaviour. We discuss the numerical characterizations of these sheaves.



\subsection{$\D$-bundles, projectivity and flatness}
Let $X$ be a $\D$-affine $k$-scheme and when necessary, we will assume it is quasi-projective. 
If $\EQ$ is a $\D$-scheme over $X$ the projectivity of an $\mathcal{O}_{\mathcal{Y}}[\mathcal{D}_X]$-module is local property for the $\D$-Zariski topology. 
We thus have a notion of $\mathcal{Y}$-locally
projective $\mathcal{O}_{\mathcal{Y}}[\mathcal{D}_X]$-module sheaves on $X$.

The property of being finitely generated is étale local and defines a notion of $\mathcal{Y}$-locally finitely generated and projective $\mathcal{O}_{\mathcal{Y}}[\mathcal{D}_X]$-modules. We call them \emph{vector $\D$-bundles over $\mathcal{Y}.$} As an example, any induced $\mathcal{O}_{\EQ}[\mathcal{D}_X]$-module with underlying locally free finitely generated $\mathcal{O}_X$-module is a vector $\D$-bundle on $\EQ.$ Every such object has a dual that is again a vector $\D$-bundle and the canonical pairing between them is non-degenerate. 

\begin{rmk}

\label{rmk: Ranks and Chern class}
   The non-commutative ring $\D$ has a skew field of fractions thus for locally projective $\D$-modules it makes sense to consider their ranks. Therefore a vector $\D$-bundle over a smooth $\D$-scheme $Z$ (e.g. jets) has a well-defined rank. By \cite[Prop 2.20]{KSY2}, there is a well-defined sequence of characteristic classes. In particular, we may fix the $\D$-geometric Chern class of a $\D$-bundle.
\end{rmk}
We tacitly make use of a $\D$-analog of the Raynaud-Gruson flattening theorem \cite[Lemma 2.3.8]{BD}.

Given a $\D$-algebraic space $\mathcal{Y}$ for each test $\D$-algebra $\mathcal{R}$, set $\mathcal{Y}_{\mathcal{R}}:=\mathcal{Y}\times_X\mathrm{Spec}(\mathcal{R}),$ and for each $\mathcal{M}\in \mathrm{Mod}_{\mathcal{D}}(\mathcal{Y}),$ set $\mathcal{M}_{\mathcal{R}}:=\mathcal{M}\otimes \mathcal{R}\in \mathrm{Mod}_{\mathcal{D}}(\mathcal{Y}_\mathcal{R}).$
Similarly, for $X\rightarrow S$ a quasi-projective and proper $S$-scheme with sheaf of relative differential operators $\mathcal{D}_{X/S},$ for any $s\in S$ denote by $i_s:X\times\{s\}\rightarrow X\times S$ the inclusion and set
$$i_{s}^*:=p_{X}^{-1}(\mathcal{O}_S/\mathfrak{m}_s)\otimes_{p_X^{-1}\mathcal{O}_S}(-):\mathbf{D}_{f.p}^b(\mathcal{D}_{X\times S/S})\rightarrow \mathbf{D}^b(\mathcal{D}_X),$$
where $p_X:X\times S\rightarrow S$ and $\mathfrak{m}_s$ is maximal ideal of functions vanishing at $s.$



\begin{prop}
    \label{prop: RelJets BC}
  Let $\pi:X\rightarrow S$ be a smooth and proper morphism of relative dimension $d_{X/S}$ with $\mathcal{E}$ a locally free finite rank $\mathcal{O}_X$-module. 
  Letting $\Delta\subset X\times_S X$ with projections $p_1,p_2$ one has an equivalence
  $$R^ip_{1*}p_2^*\mathcal{E}\simeq \pi^*R^i\pi_*\mathcal{E},\forall i\geq 0,$$ 
  and an isomorphism of $\mathcal{O}_X$-modules $p_{1*}p_2^*\mathcal{E}\simeq \pi^*\pi_*\mathcal{E}\otimes\mathcal{O}_X.$ 
\end{prop}
\begin{proof}
    Using for each $k\geq 0$ the exact sequence of sheaves of $\mathcal{O}_X$-modules,
    $$0\rightarrow \mathcal{I}_{\Delta}^{k}\rightarrow \mathcal{O}_{X\times_SX}\rightarrow \mathcal{O}_{X\times_S X}/\mathcal{I}_{\Delta}^{k+1}\rightarrow 0,$$
    tensoring with $\pi_2^*\mathcal{E}$, taking $p_{1*}$, one has the long-exact sequence in cohomology
    $$0\rightarrow p_{1*}(\mathcal{I}_{\Delta}^{k}\otimes p_2^*\mathcal{E})\rightarrow p_{1*}p_2^*\mathcal{E}\rightarrow p_{1*}(\mathcal{O}_{X\times_S X}/\mathcal{I}_{\Delta}^{k}\otimes p_2^*\mathcal{E})\rightarrow$$
    $$\rightarrow R^1p_{1*}(\mathcal{I}_{\Delta}^{k}\otimes p_{2}^*\mathcal{E})\rightarrow R^1p_{1*}p_2^*\mathcal{E}\rightarrow R^1p_{1*}(\mathcal{O}_{X\times_S X}/\mathcal{I}_{\Delta}^k\otimes p_2^*\mathcal{E})\rightarrow\cdots $$
    from which the flat-base change gives the result.
\end{proof}

\begin{cor}
    If $X$ is projective, set $\mathcal{O}_X(d)=i^*\mathcal{O}(1)^{\otimes d}$ where $i$ is the Plucker embedding of $X$ into projective space. Then, $J_{X/S}^k(\mathcal{O}_{X}(d))$ has the property that 
    $R^1p_{1*}(\mathcal{O}_{X\times X}/\mathcal{I}_{\Delta}^k\otimes p_2^*\mathcal{O}_X(d))=0.$
\end{cor}
Let us record the functoriality of sheaves of relative jets, for convenience. These results are well-known.

\begin{prop}
\label{prop: pb Jets}
Let $f:X\rightarrow Y$ be a smooth morphisms of $S$-schemes and $\mathcal{E}$ a finite rank locally free $\mathcal{O}_Y$-module. Then, there is a commutative diagram of locally free $\mathcal{O}_X$-modules, 
\[
\begin{tikzcd}
    0\arrow[r] & \mathrm{Sym}(f^*\Omega_{Y/S}^1)\otimes f^*\mathcal{E}\arrow[d]\arrow[r] & f^*J_{Y/S}^k(\mathcal{E})\arrow[d] \arrow[r] & f^*J_{Y/S}^{k-1}(\mathcal{E})\arrow[d]\arrow[r] & 0
    \\
0\arrow[r] & \mathrm{Sym}^k(\Omega_{X/S}^1)\otimes f^*\mathcal{E}\arrow[r] & J_{X/S}^k(f^*\mathcal{E})\arrow[r] & J_{X/S}^{k-1}(f^*\mathcal{E})\arrow[r] & 0
\end{tikzcd}
\]
If $V\subset Y$ is an open embedding, there is an equivalence $j_{V}^{-1}J_{Y/S}^k(\mathcal{E})\simeq J_{V/S}^k(j^*\mathcal{E})$ of $\mathcal{O}_V$-modules.
\end{prop}
The following collects the structural aspects of the sheaf of relative $k$-jets for a projective variety.
\begin{prop}
    Suppose that $X\subseteq \mathbb{P}_S^n,$ and let $\mathcal{E}$ be a finite rank locally free sheaf. Then there is a universal $k$-th order differential operator $\pi^*\pi_*\mathcal{E}\otimes\mathcal{O}_X\rightarrow J_{X/S}^k(\mathcal{E}),$ that is equivalent to the morphism,
$j_k:H^0(X,\mathcal{E})\otimes\mathcal{O}_X\rightarrow J_{X/S}^k(\mathcal{E}),$ which maps $s\in H^0(X,\mathcal{E})$ and a $k$-rational point $x_0\in X$ to the $k$-th order Taylor expansion of $s$ around $x_0.$
\end{prop}


\subsubsection*{Good filtrations for $\D_{\A}$-modules}
An analog of a good filtration (see e.g. \cite{K,Sch,Sa}) for $\mathcal{A}[\D]$-modules $\M$ of finite presentation is now given. It is compatible with both the order filtration on $\D_X$ and with the jet-filtration $\{F^k\A\}_{k\geq 0}$ on $\A,$ via the $\A$-module multiplication $\A\otimes \M\rightarrow \M.$ 
\begin{rmk}
It may be conveniently formulated via the standard order filtration on $\mathcal{A}[\D]$ given in Proposition \ref{prop: Char inclusions}. However, since $\D$-spaces are not  $\mathcal{O}_X$-finitely generated in general, and instead only $\D$-finitely generated or $\D$-finitely presented when $Z$ is formally integrable and $m$-regular for some $m\geq 0,$ we need a new criteria for finiteness of the filtered pieces $\mathrm{Fl}_j\M$ of a good filtration (in the $\D$-module setting, it is coherency).
\end{rmk}


\begin{defn}
\normalfont 
A \emph{good $\mathcal{A}[\D]$-filtration} on an $\mathcal{A}[\D]$-module $\M$ of finite-presentation, is a filtration on $\M$, denoted
$\mathrm{Fl}\M:=\{\mathrm{Fl}_m\mathcal{M}|m\in \mathbb{Z}\},$ by $\mathcal{A}[\D]$-submodules $\mathrm{Fl}_m\M$ satisfying:
\begin{equation}
\label{eqn: Goodfil}
    \begin{cases}
    \text{\'Etale-locally on }\EQ, \mathrm{Fl}_j\M=0,j \ll 0,
    \\
        \mathrm{Fl}_j\M \text{ is a vector }\D_X-\text{bundle},
        \\
        \mathrm{Fl}_k^{ord}\mathcal{O}_{\EQ}[\D_X]\cdot \mathrm{Fl}_j\M=\mathrm{Fl}_{k+j}\M,\hspace{1mm} j\gg0,k\geq 0.
    \end{cases}
\end{equation}
\end{defn}
The first condition in (\ref{eqn: Goodfil}) implies also $\mathrm{Fl}_j\M=0,j\ll 0,$ locally on $X.$ Moreover, for the initial object $\A=\mathcal{O}_X$ in $\mathrm{CAlg}_X(\D_X),$ a good $\mathcal{O}_X[\D_X]$-filtration is a good filtration as usual.
\begin{prop}
\label{prop: Associated graded}
Consider an $\mathcal{A}[\D]$-module $\M$ with a good $\mathcal{A}[\D]$-filtration. Then its associated graded module is an $\mathcal{O}_{T^*(X,\EQ)}$-module of finite-presentation.
\end{prop}
\begin{proof}
Given such an object $\mathrm{Fl}\M$, its associated graded module 
$\mathrm{Gr}^F(\M)$ is naturally a $\mathrm{Gr}^{F_{ord}}\mathcal{O}_{\EQ}[\D_X]$-module. Then, by Proposition \ref{prop: Char inclusions} it is an $\mathcal{O}_{T^*(X,\EQ)}$-module. Finite-presentation is clear from (\ref{eqn: Goodfil}).
\end{proof}
This result indicates by considering the derived functors of internal solutions (c.f. \cite{KSY}), namely $\mathbf{R}\mathcal{H}om_{\A[\D]}(-,\A[\D])$, applied to finitely-presented modules with good filtrations, their cohomologies are isomorphic to certain natural subquotients.
\begin{prop}
\label{prop: Approximations}
Let $Z$ be a $\D$-smooth scheme and consider a $\D$-subscheme $\mathrm{Spec}_{\mathcal{D}}(\mathcal{B})\hookrightarrow Z.$ Set $\mathcal{O}_Z=\mathcal{A}.$ Suppose that $\mathcal{M}^{\bullet}$ is a dg-$\mathcal{A}[\mathcal{D}]$-module that is quasi-isomorphic to a bounded complex of finitely generated $\mathcal{A}[\mathcal{D}_X]$-modules of finite rank. Then, there exists a good filtration such that the associated graded sheaves  
$\mathrm{Gr}^F\mathcal{E}xt_{\mathcal{O}_{\EQ}[\mathcal{D}]}^i\big(\mathcal{M}^{\bullet},\mathcal{O}_{\EQ}[\mathcal{D}]),$ are isomorphic to a sub-quotient of the sheaf
$$\mathcal{E}\mathrm{xt}_{\mathrm{Gr}^F\mathcal{O}[\mathcal{D}]}^i\big(\mathrm{Gr}^F\mathcal{M}^{\bullet},\mathcal{O}_{T^*(X,Z)}),$$
for every $i.$
\end{prop}

\begin{proof}
By assumptions write $\mathcal{M}^{\bullet}$ locally as a complex
$0\leftarrow \mathcal{M}\leftarrow \mathcal{V}_0\leftarrow \mathcal{V}_1\leftarrow \dots,$
with each $\mathcal{V}_i$ finitely generated and free $\mathcal{A}[\mathcal{D}]$-modules of finite rank. Locally, we may write $\mathcal{V}_i=\bigoplus_k\mathcal{A}[\mathcal{D}]\bullet \gamma_k^i$ on generators $\gamma=\{\gamma_k^i\}.$ 
Fix integers $\{c_{jk}\in \mathbb{Z}\}$ and define the desire good filtration by
$$\mathrm{Fl}(\mathcal{V}_i)=\{\mathrm{Fl}^m(\mathcal{V}_i)\},\hspace{1mm} with \hspace{2mm} \mathrm{Fl}^m(\mathcal{V}_i)=\bigoplus_k\mathrm{F}^{m-c_{jk}}(\mathcal{A}[\mathcal{D}])\bullet \gamma_k^i,$$
via the canonical filtration of Proposition \ref{prop: Char inclusions}.
On the one hand, by passing to graded objects we get, for every $m\in \mathbb{Z},$
$0\leftarrow \mathrm{Gr}_m^F(\mathcal{M})\leftarrow \mathrm{Gr}_m^F(\mathcal{V}_0)\leftarrow \mathrm{Gr}_m^F(\mathcal{V}_1)\leftarrow \cdots.$
On the other, dualizing via the $\mathcal{A}[\mathcal{D}]$-dual $\mathcal{H}om_{\mathcal{A}[\mathcal{D}]}(-,\mathcal{A}[\mathcal{D}]),$ gives a complex of $\mathcal{A}^r[\mathcal{D}_X^{op}]$-modules,
$$0\rightarrow \mathcal{H}om_{\mathcal{A}[\mathcal{D}]}(\mathcal{V}_0,\mathcal{A}[\mathcal{D}])\rightarrow  \mathcal{H}om_{\mathcal{A}[\mathcal{D}]}(\mathcal{V}_1,\mathcal{A}[\mathcal{D}])\rightarrow \cdots.$$
Since 
$\mathcal{E}xt_{\mathcal{A}[\mathcal{D}]}^k$ sheaves agree with the $k$-th cohomology of this complex, standard arguments give that 
$$\mathcal{E}xt_{\mathrm{Gr}^F\mathcal{A}[\mathcal{D}]}^k\big(\mathrm{Gr}^F(\mathcal{M}),\mathrm{Gr}^F\mathcal{A}[\mathcal{D}]\big)\simeq \mathcal{H}^k\big(\mathcal{H}om_{\mathrm{Gr}^F\mathcal{A}[\mathcal{D}]}(\mathrm{Gr}^F\mathcal{V}_{\bullet},\mathrm{Gr}^F\mathcal{A}[\mathcal{D}]\big),$$
for each $k$ and this shows in particular that $\mathrm{Gr}^F(\mathcal{H}^k(\mathcal{H}om_{\mathcal{A}[\mathcal{D}]}(\mathcal{V}_{\bullet},\mathcal{A}[\mathcal{D}])\big)$ is isomorphic to a sub-quotient of $\mathcal{H}^k\big(\mathrm{Gr}^F\mathcal{H}om_{\mathcal{A}[\mathcal{D}}(\mathcal{V}_{\bullet},\mathcal{A}[\mathcal{D}])\big).$
Via standard $\D$-module arguments and using Proposition \ref{prop: Associated graded}, we have that 
\begin{eqnarray*}
\mathrm{Char}\big(\mathcal{E}xt_{\mathcal{A}[\mathcal{D}]}^k(\mathcal{M},\mathcal{A}[\mathcal{D}])\big)&\subset &\mathrm{Supp}\big(\mathcal{E}xt_{\mathcal{O}_{T^*(X,Z)}}^k(\mu \mathrm{Gr}^F\mathcal{M}^{\bullet},\mathcal{O}_{T^*(X,Z)})\big)
\\
&\subset& \mathrm{Supp}(\mu\mathrm{Gr}\mathcal{M}^{\bullet}),
\end{eqnarray*}
again via the filtration of Proposition \ref{prop: Char inclusions}.
\end{proof}

Finally, let $\mathcal{A}_{X/S}^{\ell}=J_{X/S}(\mathcal{O}_C)$ for a commutative $\mathcal{O}_{X\times S}$-algebra $\mathcal{O}_C.$ Then, $i_s^*\mathcal{A}_{X/S}=i_s^*J_{X/S}(\mathcal{O}_C),$ is the pull-back sheaf of $\mathcal{D}_{X/S}$-algebras given by Proposition \ref{prop: pb Jets}. Assume $X/S$ is a non-characteristic fibration (c.f \ref{ssec: NC subspaces}). Then fiber-wise derived restriction defines a functor for each $s\in S$ on derived categories from $\mathcal{A}_{X/S}[\mathcal{D}_{X/S}]$-modules to $i_s^*\mathcal{A}_{X/S}[\mathcal{D}_X]$-modules.

\begin{rmk}
If $\mathcal{M}^{\bullet}$ is a finitely presented $\mathcal{A}[\mathcal{D}_{X/\times S/S}]$-module in amplitude $[p,q]$ then locally in a neighbourhood of $(x,s)\in X\times S$ there is a complex of free $\mathcal{A}[\mathcal{D}]$-modules of finite rank in degrees $[p-2n-n_S,q]$ quasi-isomorphic to $\mathcal{M}.$ Moreover, considering any two such modules, the sheaf of solutions satisfies $i_s^*\mathbb{R}\mathcal{S}\mathrm{ol}_{\mathcal{D}_{X\times S/S}}(\mathcal{M},\mathcal{N})\simeq \mathbb{R}\mathcal{S}\mathrm{ol}_{i_s^*\mathcal{D}_{X\times S/S}}(i_s^*\mathcal{M},i_s^*\mathcal{N}).$
\end{rmk}

\subsubsection*{Flatness}
Consider a complex $\mathcal{E}^{\bullet}$ of $\mathcal{O}_X$-modules and $\mathcal{M}^{\bullet}$ a complex of $\D_X$-modules. It naturally determines a complex of $\mathcal{O}_X$-modules, denoted $\mathrm{For}_{\mathcal{D}}(\mathcal{M}^{\bullet})$, by forgetting the $\D_X$-module structure. We follow \cite{BD}.
\begin{defn}
\label{defn: Flatness Definitions}
\normalfont
Complex $\mathcal{E}^{\bullet}$ (resp. $\mathcal{M}^{\bullet}$) is \emph{homotopically $\mathcal{O}_X$-flat} if for all acyclic $\mathcal{O}$-modules $\mathcal{F}^{\bullet}$, the complex $\mathcal{E}\otimes\mathcal{F}$ (resp. $\mathrm{For}_{\mathcal{D}}(\mathcal{M})\otimes \mathcal{F}$) is acyclic.
Similarly, $\mathcal{M}^{\bullet}$ is \emph{homotopically $\mathcal{D}_X$-flat} if for all acyclic complexes $\mathcal{L}^{\bullet}$ of $\mathcal{D}_X$-modules, $\mathcal{M}\otimes_{\mathcal{D}_X}\mathcal{L}$ is an acyclic complex of $k$-vector spaces.
Finally, a complex of $\mathcal{D}$-modules $\mathcal{M}^{\bullet}$ is \emph{homotopically $\D_X$-quasi-induced} if for all homotopically $\mathcal{O}_X$-flat $\D_X$-modules $\mathcal{L}^{\bullet}$ there is a quasi-isomorphism $\mathcal{M}^{\bullet}\otimes_{\mathcal{D}_X}^{\mathbb{L}}\mathcal{L}^{\bullet}\simeq \mathcal{M}\otimes_{\mathcal{D}}\mathcal{L}.$
\end{defn}
Any induced $\D_X$-module is quasi-induced. This can be written as the condition that for an $\mathcal{O}_X$-flat $\D_X$-module $\mathcal{M}$, we have $Tor_{>0}^{\mathcal{D}_X}(\mathcal{M},\mathcal{L})=0,$ or globally, as 
$$R\Gamma_{dR}(X,\mathcal{M}\otimes\mathcal{L})\simeq R\Gamma\big(X,h(\mathcal{M}\otimes\mathcal{L})\big).$$
We collect some properties of quasi-induced $\D$-modules.
\begin{prop}
The following statements hold:
\begin{enumerate}
\item The direct image of a quasi-induced
$\D_X$-module under an affine morphism is quasi-induced;
\item The exterior tensor product
of quasi-induced $\D_X$-modules is quasi-induced;
\item A holonomic $\D_X$-module is quasi-induced if and only if its support has dimension $0$.
\item Any tensor product of an $\mathcal{O}_X$-flat
$\D_X$-module and a quasi-induced $\D_X$-module is quasi-induced.
\end{enumerate}
\end{prop}

For a differential graded $\D$-algebra $\mathcal{A}$, put $U(\mathcal{A})$ the dg-$\mathcal{O}_X$-algebra which is quasi-coherent. 
\begin{defn}
    \label{definition: Flatness for D-Algebras}
    \normalfont 
    A morphism $f:\mathcal{A}\rightarrow \mathcal{B}$ of dg-$\D$-algebras is \emph{faithfully $\D$ flat} if $U(f):U(\mathcal{A})\rightarrow U(\mathcal{B})$ is faithfully flat.
\end{defn}
 If $f:\mathcal{A}\rightarrow \mathcal{B}$ is faithfully $\D$-flat then $\mathcal{B}$ is homotopically $\mathcal{A}$-flat if it is homotopically $\mathcal{A}$-flat as a dg-$\mathcal{A}[\mathcal{D}_X]$-module i.e. for all $\mathcal{M}^{\bullet}\in \DG(\mathcal{A}),$ the complex $\mathcal{M}\otimes_{\mathcal{A}}\mathcal{B}$ is acyclic. For non-dg-$\D$-algebras, e.g. those concentrated in degree zero, given a morphism $f:\mathcal{B}\rightarrow \mathcal{C}$, $\mathcal{C}$ is $\mathcal{B}$-flat as a $\D$-algebra if the morphism preserves $\D$-action and multiplication, and $\mathcal{C}$ is flat as a $\mathcal{B}$-module, via $f.$

\begin{prop}
\label{prop: Global HoFlat}
    Let $X$ be $D$-affine and and suppose that $Z$ is a smooth $\D$-scheme. Suppose that $\mathcal{M}^{\bullet}$ is a homotopically flat $\mathcal{O}_Z[\mathcal{D}_X]$-module. Then $\Gamma(Z,\mathcal{M})$ is homotopically flat over $\Gamma(Z,\mathcal{O}_{Z}[\mathcal{D}_X]).$   
\end{prop}
\begin{proof}
    Any such $\mathcal{M}$ has a finite left resolution since it is flat as a $\mathcal{O}_Z$-module (de Rham resolution). Thus, to prove the claim suppose
$0\rightarrow \mathcal{N}_1\rightarrow \mathcal{N}_0\rightarrow \mathcal{M}\rightarrow 0,$ is a short exact sequence with $\mathcal{N}_i$ globally flat. We must prove that if $\mathcal{M}$ is flat, it is globally flat. To this end, decompose $\mathcal{N}_i$ as a direct sum over finitely generated free $\mathcal{O}_Z[\mathcal{D}]$-modules. Then 
for all $\mathcal{L}$ a complex of left $\mathcal{O}_Z[\mathcal{D}_X]$-modules, the natural map
$\Gamma(Z,\mathcal{N}_1)\otimes_{\Gamma(Z,\mathcal{O}_{Z}[\mathcal{D}_X])}\Gamma(Z,\mathcal{L})\rightarrow \Gamma(Z,\mathcal{N}_0)\otimes_{\Gamma(Z,\mathcal{O}_{Z}[\mathcal{D}])}\Gamma(Z,\mathcal{L}),$
is injective and we have an isomorphism,
$\Gamma(Z,\mathcal{N}_i)\otimes_{\Gamma(Z,\mathcal{O}_{Z}[\mathcal{D}])}\Gamma(Z,\mathcal{L})\simeq \Gamma(Z,\mathcal{N}_i\otimes_{\mathcal{O}_Z[\mathcal{D}]}\mathcal{L}),$ thus since $\mathcal{M}$ is (homotopically) flat by assumption, the map $\mathcal{N}_1\otimes_{\mathcal{O}_Z[\mathcal{D}]}\mathcal{L}\hookrightarrow \mathcal{N}_0\otimes_{\mathcal{O}_Z[\mathcal{D}]}\mathcal{L})$ is an injective $\D$-module morphism. 
\end{proof}

\begin{prop}
    Suppose that $X$ is quasi-projective. Then there exists a homotopy $\D$-flat non-unital commutative $\D$-algebra resolution of $\mathcal{O}_X.$
\end{prop}
Moreover, for arbitrary $X$ one can take a resolution whose terms are isomorphic as graded commutative $\D$-algebras to free $\D$-algebras on $X$-locally projective graded $\D$-modules $\mathcal{M}$ in degrees $\leq 0$ i.e. $\mathrm{Sym}^{>0}(\mathcal{M}).$ 

When $X$ is quasi-projective $\mathcal{M}$ can be chosen to be a direct sum of induced $\D$-modules $\mathrm{ind}_{\mathcal{D}}^{\ell}(L)$ for a line bundle $L.$ In particular, each $L$ is a negative power of a given ample line bundle.


\subsection{$\mathcal{D}_X$-Geometric Hilbert Polynomials}
\label{ssec: D-Hilb Polynomials}
Given a linear system $\mathcal{M}$, its associated symbol generates an ideal in $\mathbb{C}[\xi_1,\ldots,\xi_n].$ This ideal gives rise to a variety in $T^*X$, denoted as usual $\mathrm{Char}(\mathcal{M})$ and one gets a (polynomial) function
$H_{\mathcal{M}}'(n)$ defined to be the dimension of the space of formal solutions. Via standard constructions of Gröbner bases, there exists a Hilbert function $H_{\mathcal{M}},$ and for $n\gg 0$, $H_{\mathcal{M}}(n)=H_{\mathcal{M}}'(n).$
We highlight this in two situations of interest.
\begin{notate}
Following \cite{CFK2}, given a (graded) associative algebra $A$ and a left $A$-module $M,$ one has $A$-Grassmannians
$Gr_{A}(k,M)\subset Gr(k,M),$
whose scheme of left ideals is $J(k,A):=Gr_{A}(k,A).$ We apply it to commutative algebras $A$. This describes two-sided ideals of $A$ whose quotients $A/I$ are again commutative.
\end{notate}

Fix coordinates $(x;\xi)\in T^*X$ and some integer codimension $C\in \mathbb{N}.$ Consider non-reduced sub-schemes of $T^*X$ cut-out by symbol ideals. We consider not only prime ideals $\mathcal{I}$ but $\mathcal{I}$-primary ideals $\mathcal{J}$ and consider the Hilbert scheme of points 
$Hilb^k\big(\mathbb{C}[\xi_1,\ldots,\xi_C\!]\big).$

\begin{prop}
\label{cor: Application 1}
Let $J_{C}(k,T^*X)$ be the set of codimension $C$ primary ideals in $\mathcal{O}_{T^*X}$ of multiplicity $k.$ 
Then there is an isomorphism of sets
$$Hilb^k\big(\mathbb{C}[\xi_1,\ldots,\xi_C]\big)\simeq J_{C}(k,T^*X),$$ as well as an equivalence of quasi-projective schemes,
\begin{equation}
    \label{eqn: Hilb and G equi}
Hilb^k\big(\mathbb{C}[\xi_1,\ldots,\xi_C]\big)\simeq Gr_{\mathbb{C}}^{\mathcal{D}}(k,\mathbb{C}[z_1,\ldots,z_C]),
\end{equation}
where $Gr_{\mathbb{C}}^{\mathcal{D}}(k,\mathbb{C}[z_1,\ldots,z_C])$ is the scheme of $k$-dimensional $\mathbb{C}$-vector subspaces of $\mathbb{C}[z_1,\ldots,z_C]$ closed under differentiation i.e. $\D$-subspaces.
\end{prop}
\begin{proof}
Firstly, by Grothendieck \cite{Gro3} we have that $Hilb^k(\mathbb{C}[\xi])$ is a quasi-projective scheme over $\mathbb{C}$. Its classical points are
ideals of co-length $k$ in the local ring $\mathbb{C}[\xi]$ (see also \cite{HL}). This ring is the completion of the polynomial ring in variables $\xi_i$ given by localization at the prime $\mathcal{I}.$ Recall the multiplicity $k$ of a primary ideal $\mathcal{J}$ over its
prime $\mathcal{I}=\sqrt{\mathcal{J}}$ is the length of a corresponding Artinian local ring. 

Let $\mathcal{I}$ denote a point of $J_{C}(k,T^*X)$ i.e. a primary ideal and note that by making formal replacements
$\partial_i\leftrightarrow \xi_i,$ with $\partial_{z_i}$ for $i=1,\ldots,C,$ (essentially via microlocalizing or Fourier-transformation) this ideal gives a point in 
$Hilb^k\big(\mathbb{C}[\partial_1,\ldots,\partial_{C}]\big).$ In one direction the differentially stable vector space is determined by the space of solutions in Proposition \ref{prop: Sol}: 
$$Sol(\mathcal{I}):=\{f\in \mathbb{C}[z_1,\ldots,z_C]|\mathbf{F}\bullet f=0,\forall \mathbf{F}\in \mathcal{I}\}.$$
Conversely, any $k$-dimensional $\mathbb{C}$-vector space $V$ stable under the action by $\mathcal{D}_{\mathbb{C}^C}$, determines a point in the punctual Hilbert scheme via $\mathcal{I}:=\mathrm{Ann}_{\mathbb{C}[\partial_1,\ldots,\partial_C]}(V),$
or equivalently $\mathrm{Ann}_{\mathbb{C}[\xi_1,\ldots,\xi_C]}(V).$
Thus, the point of $J_{C}(k,T^*X)$ determined by $\mathcal{I}$ is the ideal $\mathcal{J}:=\sqrt{\mathrm{Ann}_{\mathbb{C}[\xi_1,\ldots,\xi_C]}(V)}.$ The corresponding algebraic variety defined by $\mathcal{J}$ is the characteristic variety (\ref{annideal}). 
\end{proof}

These ideas also apply to the study of ideals in the Weyl algebra. That is, consider the moduli problem of studying finitely generated ideals in the $n$-th Weyl algebra $A_n:=\mathbb{C}[x_1,\ldots,x_n]\big<\partial_1,\ldots,\partial_n\big>.$
Equivalently, consider a finite set of generators $N\subset (A_n)^r$ given as an $A_n$-submodule, and study quotient modules
$M:=(A_n)^r/N.$ Also, we could study modules of the form
$$\mathcal{M}:=\mathcal{D}_{\mathbb{C}^n}\otimes_{A_n}\big(A_n^r/N\big),$$
for some generators $N=\sum_{i=1}^s A_n\cdot P_i$ for $P_i\in (A_n)^r,$ for $i=1,\ldots,s.$

\begin{prop}
\label{cor: Application 2}
    There is an equivalence between finitely generated left ideals in $A_n$ with a trivialization to $\mathcal{D}_{\mathbb{C}^n}$ and ideal sheaves
    $\mathcal{I}_{\nu}\subset \mathcal{O}_{T^*X},$
    with fixed numerical characteristics given via the polynomial
    $H:=\sum_{\nu=1}^rdim_{\mathbb{C}}\big(\mathbb{C}\{x,\xi\}/\mathcal{I}_{\nu}+\mathcal{J}^k\big),$
    for the maximal ideal $\mathcal{J}$ of $\mathbb{C}\{x,\xi\}.$
\end{prop}
\begin{proof}
Notice that 
$H(k)$ of (\ref{ssec: D-Hilb Polynomials}) agrees with the Hilbert polynomial of the microlocalization $\mu\big(gr^F(\mathcal{M})\big)$ for a `canonical' filtration. That is, using coherent filtrations 
$$H_{\mu(\mathrm{Gr}^F(\mathcal{M}))}(k)=\mathrm{dim}_{\mathbb{C}}\big(\mu \mathrm{Gr}^F\mathcal{M}/\mathcal{J}^k\cdot \mu \mathrm{Gr}^F\mathcal{M}\big).$$
The result follows from a standard argument via Gröbner bases. Roughly, let $\mathbf{G}_{\nu}:=\{P| lp(P)=\nu\},\forall\nu=1,\ldots,r,$
where $lp(P)=i$ is the leading point of $P$, defined when $lexp(P)=(\alpha,i).$ Since the characteristic variety is given by 
$$\mathrm{Char}(\mathcal{M})=\bigcup_{\nu=1}^r\big\{(x,\xi)\in T^*X|\sigma_{\nu}(P)(x,\xi)=0\forall P\in\mathbf{G}_{\nu}\big\}\hookrightarrow T^*X,$$
the result follows as the ideal $\mathcal{I}_{\nu}$ is generated by 
$\sigma(\mathbf{G}_{\nu}):=\{\sigma(P)_{\nu}|P\in\mathbf{G}_{\nu}\}.$
\end{proof}

In the $\D$-algebraic setting these notions must be adjusted using canonical filtrations and the characteristic module (\ref{eqn: Char Module of A}).

\subsubsection{Growth functions and Krull dimension}
Consider a $k$-th order PDE $Z=\{Z_k\subset J_X^kE\}.$ Following ideas of \cite{B}, we may define a numerical growth function,
\begin{equation}
    \label{eqn: Growth}
    G_{Z_k}:\mathbb{N}\rightarrow \mathbb{N}, G_{Z}(n):=\mathrm{dim}(\mathrm{Pr}_{\ell}(Z_k)).
    \end{equation}
Say that $Z$ is of \emph{polynomial growth} if there exists a numerical polynomial $H\in \mathbb{R}[t],$ such that for $r\gg 0, \mathrm{dim}(\mathrm{Pr}_r(Z_k))=H(r),$ for $r\geq k.$  

Hilbert polynomials may be defined for symbolic systems associated with infinite-prolongations $Z^{\infty}$ of formally integrable equations. Thus, 
 $\D_X$-schemes determined by formally $\D$-involutive ideal sheaves are of polynomial growth. 
Indeed, for $\D$-involutive ideal sheaves, fixing the $\D$-Hilbert polynomial is equivalent to fixing that of its characteristic (symbolic) $\D$-module.
Fix a differentially generated ideal $\mathcal{I}$ with filtration $F^k\mathcal{I}$. 

 It is natural to define the `Krull dimension $\I$', by
\begin{equation}\label{eqn: Krull}
\mathfrak{d}_{\mathcal{I}}:\mathbb{Z}_{+}\rightarrow \mathbb{Z}_+, k\mapsto \mathfrak{d}_{\mathcal{I}}(k):=dim\big(F^k\mathcal{A}/F^k\mathcal{I}\big).
\end{equation}
The following result is easily checked.
\begin{prop}
\label{prop: D-Dim Polynomial}
    Let $\mathcal{A}$ be the $\D$-smooth infinite jet $\mathcal{D}_X$-algebra in $\mathrm{rank}(E)$-variables with $d_X=\mathrm{dim}(X).$ Let $\mathcal{I}$ be a $\D$-ideal corresponding to a formally integrable involutive algebraic PDE. Then, there is a numerical polynomial $\mathbf{h}_{\mathcal{I}}(k)\in\mathbb{Q}[k],$ such that $\mathbf{h}_{\mathcal{I}}(k)=\mathrm{dim}(F^k\mathcal{A}/F^k\mathcal{I}),$ for sufficiently large $k$. Moreover, $\mathbf{h}_{\mathcal{I}}$ satisfies:
    \begin{itemize}
        \item[(i)] $0\leq \mathbf{h}_{\mathcal{I}}(k)\leq \mathrm{rank}(E)\cdot C_{d_X}^{k+d_X}.$
        \item[(ii)] If $\mathcal{I}\subseteq \mathcal{J}$, then $\mathbf{h}_{\mathcal{J}}\leq \mathbf{h}_{\mathcal{I}}.$

        \item[(iii)] Prime $\mathcal{D}_X$-ideals $\mathcal{I}\subseteq\mathcal{J}$ are equal if and only if $\mathbf{h}_{\mathcal{I}}=\mathbf{h}_{\mathcal{J}}.$ 
    \end{itemize}
    Furthermore, the degrees of this polynomial is bounded as $deg_{k}(\mathbf{h}_{\mathcal{I}})\leq \mathrm{dim}(X).$
\end{prop}
\begin{proof}
Follows immediately from observing that $\mathcal{I}\subseteq\mathcal{J}$ implies that $F^k\mathcal{I}\subseteq F^k\mathcal{J}$ for all $k\geq 0.$ 
This induces a surjective morphism (of $\mathcal{O}_X$-modules), $F^k\mathcal{B}\rightarrow F^k\mathcal{C},$ such that 
$\mathrm{dim}(F^k\mathcal{A}/F^k\mathcal{I})\geq \mathrm{dim}(F^k\mathcal{A}/F^k\mathcal{J}).$
In other words, the inclusion of ideals gives a sequence
$$0\rightarrow \mathcal{K}\rightarrow \mathcal{O}(J_X^{\infty}E)/\mathcal{I}\rightarrow \mathcal{O}(J_X^{\infty}E)/\mathcal{J}\rightarrow 0,$$
with $\mathcal{K}$ the kernel of the induced surjection from which 
$$0\rightarrow F^k\mathcal{K}\rightarrow \mathcal{O}(J_X^kE)/\mathcal{I}\cap \mathcal{O}(J_X^kE)\rightarrow \mathcal{O}(J_X^kE)/\mathcal{J}\cap \mathcal{O}(J_X^kE)\rightarrow 0,$$
which tells us 
$h_{\mathcal{I}}(k)=h_{\mathcal{J}}(k)+dim(F^k\mathcal{K})\geq h_{\mathcal{J}}(k),$ as required.
\end{proof}
%\begin{ex}
 %   The viscous Burgers equation has $\mathbf{h}_{<u_0-uu_1-u_2>}(k)=2k+1,$ where $u_0:=u_t$ and $u_1:=u_x,u_2:=u_{xx}.$
%\end{ex}
The $\D$-Hilbert function counts the number of free functions in the Taylor expansion of a generic formal solution. For formally integrable and involutive systems a general solution depends on $d$ functions of $p$ variables with $p\in \mathbb{N}$ called the functional dimension of $\mathrm{Sol}_{\mathcal{I}}$ while $d$ is the functional rank (see e.g. \cite{KL},\cite{Sei}).
Compute the Cartan numbers using $\mathrm{Char}(\mathcal{B})$ via the Hilbert-Serre theorem e.g. $p=\mathrm{dim}(Char)+1.$ An explicit formula for the $\D$-Hilbert polynomial can be written down from the dimension microcharacteristic varieties given by Proposition \ref{prop: Char inclusions}.
\begin{prop}
\label{prop: Hilbprop}
Let $\mathcal{I}$ be a Spencer-regular $\D$-ideal and suppose it is of formal codimension $N$ and of pure order $k$. Then there is a numerical polynomial $P$ associated with $\mathcal{I}$ which agrees with the Hilbert function of its symbolic system $P_{\mathcal{B}}(z)=H_{\mathcal{M}}(z).$ If $p=\mathrm{deg}(P_{\mathcal{B}}(z))$ and $d=P_{\mathcal{B}}^{(p)}(z)$ then 
    $P_{\mathcal{B}}(z)=d\cdot z^p+(\ldots),$
omitting the lower order terms.
Generally, one may write
$$P_{\mathcal{B}}(z)=\sum_{i,j,k}(-1)^i\beta^{q,i}s_{j}^n\frac{(z-k-i)^{n-j}}{(n-j)!},$$
where $\beta^{i,j}$ are the Betti numbers determined by the resolution of the symbol module, $s_i^n:=\frac{(n-i)!}{n!}S_i(1,\ldots,n)$ where $S_j(k_1,\ldots,k_n)=\sum_{i_1<\ldots<i_j}k_{i_1}\cdots k_{i_j}$ is the $j$-th symmetric polynomial associated to the orders $k_i$ of the equations defining the system. 
\end{prop}

%\begin{proof}
%This is a rephrasing of certain results of \cite{GeomDEQ} and \cite{SeilerInvolution} (and references therein), for the context of $\D$-modules.
%\end{proof}

In order to calculate the Hilbert polynomial in practice one uses a resolution of the linearization of the symbol module. In this linearized case, the resolution of $\mathcal{M}_{\mathcal{I}}$ exists and is expressed as the $\mathbb{R}$-dual of the Koszul homology, denoted $H_{\delta}^{i,j}$ then $\beta^{i,j}=\mathrm{dim}(H_{\delta}^{i,j}).$

For formally integrable PDEs, $P_{\D}(\I;\ell)=\sum_{i\leq \ell}\mathrm{dim}(\mathcal{N}_i)$ is a polynomial for $\ell\gg 1,$ so $\mathrm{dim}(\mathcal{N}_z)=P_{\D}(\I;z)-P_{\D}(\I;z-1)$ for all larger integers $z=\ell,$ which extends to all $z\in\mathbb{C}.$
The following convenient formula computes the $\D$-Hilbert function,
\begin{equation}
\label{eqn: DHilbAgain}
P_{\D}(\I;z)=\sum_{p,q}(-1)^{p+q}\mathrm{dim}\mathcal{H}_{Sp}^{p,q}(\mathcal{N})\cdot C^{z+n-p-q-1}_{n-1}.
\end{equation}

\begin{prop}
\label{prop: Hilbert D-Polynomial}
    Let $\mathcal{B}$ be a $\mathcal{D}_X$-smooth non-linear PDE i.e. $H^0(\mathbb{T}_{\mathcal{B}})\simeq \Theta_{\mathcal{B}}.$ Then there exists a numerical polynomial 
    $H_{\Theta_{\mathcal{B}}}'$ defined by 
    $\mathrm{dim}\big(F^k\Theta_{\mathcal{B}}^{\ell}\big)\simeq \mathrm{dim}\big(\Theta_{F^k\mathcal{B}}^{\ell}\big),$
    as a $F^k\mathcal{B}$-vector space such that for $k$ large enough,
    $H_{\Theta_{\mathcal{B}}}'$ agrees with $\mathbf{h}_{\mathcal{I}}.$
\end{prop}
Rather than fixing a $\D$-numerical polynomial, for vector $\D$-bundles by the Remark \ref{rmk: Ranks and Chern class}, one can instead fix the $\D$-geometric Chern class.


\subsection{Spencer (semi)stability}
\label{ssec: Spencer stability}
Via Proposition \ref{prop: D-Dim Polynomial} and Proposition \ref{prop: Hilbprop} we define a \emph{reduced $\D$-Hilbert polynomial} by normalizing via the generic (functional) rank\footnote{This is the first Cartan character \cite{C}.} of the solution sheaf, i.e., the number of independent functional parameters in a formal solution, at each $x\in X.$  Denote it by $\mathrm{rank}(\mathcal{I}),$ and put
\begin{equation}
    \label{eqn: Reduced D-Hilb}
\overline{P}_{\mathcal{D}}(\mathcal{I},n):=\frac{P_{\mathcal{D}}(\mathcal{I},n)}{\mathrm{rank}(\mathcal{I})}.
\end{equation}
This suggests the following definition.
\begin{defn}
\normalfont
\label{defn: Spencer ss}
A $\D$-ideal sheaf $\mathcal{I}$ is \emph{Spencer semi-stable} (resp. \emph{Spencer stable}) if for every differentially-generated involutive $\D$ sub-ideal $\mathcal{J}\subset \mathcal{I}$, (resp. proper ideal),
we have that $\overline{P}_{\D}(\mathcal{J})\leq \overline{P}_{\mathcal{D}}(\mathcal{I})$, (resp. $\overline{P}_{\mathcal{D}}(\mathcal{J})<\overline{P}_{\mathcal{D}}(\mathcal{I})$).
\end{defn}
Representing the numerator as the Euler characteristic of the Spencer $\delta$-complex (\ref{eqn: Spencer delta symbol}), Spencer-semistability is an equality,
$$\frac{\sum_{i}(-1)^ih^i(\mathcal{J},n)}{\mathrm{rank}(\mathcal{J})}\leq \frac{\sum_{i}(-1)^ih^i(\mathcal{I},n)}{\mathrm{rank}(\mathcal{I})},\hspace{2mm}\text{ for } n \gg0.$$

\begin{prop}
    Suppose that $\I$ is $m$-involutive for some $m\geq 0.$ Then, $\mathrm{rank}(\mathcal{I})=dim\mathcal{H}^{0,m-1}\big(\mathcal{S}p(\mathrm{gr}\mathcal{I})\big)$. More generally, it is the leading coefficient of $P_{\mathcal{I}}(n)\cdot n^{p}$, where $p$ is determined by the dimension of characteristic variety.
\end{prop}
It is convenient to also define \emph{Spencer slopes}, as
\begin{equation}
\label{eqn: Spencer slope}
\mu_{Sp}(\mathcal{I}):=\frac{\mathrm{deg}\big(H^0(\mathcal{S}p(\mathcal{I})\big)}{\mathrm{rank}(\mathcal{I})}.
\end{equation}
There is an obvious notion of \emph{Spencer slope semistability} as $\mu_{Sp}(\mathcal{J})\leq \mu_{Sp}(\mathcal{I}).$ Slope stability is defined via strict inequality.
\begin{prop}
    Suppose that $\mathcal{I}$ is a differentially finitely generated $\D$-ideal. Suppose it is Spencer semi-stable (resp. Spencer stable). Then it is Spencer slope semi-stable (resp. Spencer slope stable).
\end{prop}
\begin{proof}
Note that the degree is equal to the leading coefficient in $\mathrm{lim}_{k\rightarrow \infty}P(\mathcal{I};k)/k^d,$ with $d$ the characteristic dimension. Then, note that (\ref{eqn: Spencer slope}) are equivalently written as $lim_{k\rightarrow \infty}P(\mathcal{I},k)/\mathrm{rank}(\mathcal{I})\cdot k^d.$ It is then a standard argument that one may consider $\overline{P}(\mathcal{J},k)\leq \overline{P}(\mathcal{I},k)$ for large $k$, and compare leading order terms, which are precisely the degrees. Then, the Spencer slope semi-stability (resp. stability) inequality gives $\mu_{Sp}(\mathcal{J})\leq \mu_{Sp}(\mathcal{I})$ (resp. $\mu_{Sp}(\mathcal{J})<\mu_{Sp}(\mathcal{I})$).
\end{proof}

\subsection{Differential algebra quotients by algebraic pseudogroups}
\label{ssec: Differential algebra quotients}
We describe the quotient $\D$-ideal, to be denoted $\mathcal{I}^{\mathcal{G}},$ by an algebraic group, and the $\mathcal{G}$-invariant symbolic system $\mathrm{gr}(\mathcal{I})^{\mathcal{G}}:=\mathrm{gr}(\mathcal{I}^{\mathcal{G}}).$ These constructions are used below to prove that the moduli space of Spencer semi-stable $\D$-ideal sheaves admits a presentation as a GIT-quotient.
Working in the (almost) algebraic category, we make use of a type of Noetherian property on quotient symbolic systems which leads to finite generation of the $\D$-algebra of functions constant along orbits.


The main result of this subsection is given by Proposition \ref{prop: GeometricQuotientEquation} which roughly states that, given an algebraic action on a formally integrable $\D$-scheme $Z$, then if $G$ acts algebraically and transitively on $X$, there exists an integer $\ell$ and a Zariski closed $G$-invariant proper subset $W_{\ell}\subset F^{\ell}Z,$ such that the action is regular on $(p_{\ell}^{\infty})^{-1}(W_{\ell})\subset Z.$
In other words, for any $k\geq \ell,$ the orbits on $F^kZ\backslash (p_{\ell}^k)^{-1}(W_{\ell})$ are closed, equidimensional and have the structure of algebraic varieties. This implies the existence of a quotient equation as a geometric quotient.

\subsubsection*{Recollections on geometric quotients}
Recall that a surjective open moprhism between algebraic varieties $f:X\rightarrow Y$ is a \emph{geometric quotient} if the fibers $f^{-1}(y)$ are $G$-orbits and for every open subset $U\subset Y$ the map $\mathcal{O}_Y(U)\rightarrow \mathcal{O}_X\big(f^{-1}(U)\big)^G$ is an isomorphism of algebras.

A geometric quotient is a categorical quotient. This means that any morphism $g:X\rightarrow Z$ of algebraic varieties constant along the orbits of $G$  can be factorized through $f$ i.e. there exists a morphism $h:Y\rightarrow Z$ such that $g=h\circ f.$ In particular, if a geometric quotient $X/G$ exists, it is unique in this categorical sense.

For differential equations, we study categorical quotients by \emph{pseudogroups}, following \cite{SiSt},\cite{Kum}.
\begin{defn}
\normalfont
A \emph{pseudogroup} is a collection
of local diffeomorphisms $G$, that contains unit, inverse,
and composition whenever defined. It is called a \emph{Lie pseudogroup} if
its elements are solutions to a system of differential equations.
\end{defn}

A \emph{Lie equation} of differential order $\leq r$ means an embedding $G^{(r)}\subset J_X^r$ that uniquely determines a groupoid $\{G^k\}_{k\geq r},$ by prolongation (see \cite{Li,Li2}). By the Cartan-Kuranishi theorem, analytic pseudogroups transitive on $X$ are always Lie pseudogroups. We always assume a type of formal-integrability of $G=\{G^k\}$ i.e.  that $G^k$ is a bundle over $G^{k-1}$ for all $k>0.$ Its' infinite prolongation is thus well-defined and is denoted by $G^{\infty}.$ There are well-defined tangents $TG^k,k>0,$ and joint relative tangent sheaves under projections $G^k\rightarrow G^{k-1}$ define a notion of symbolic system for $G^{\infty}.$

One may extend for each $\phi\in G$ via prolongation to act $\mathrm{Pr}_{\ell}(\phi):J^{\ell}\rightarrow J^{\ell}$, by setting $\mathrm{Pr}_{\ell}(\phi\circ \psi^{-1})=\mathrm{Pr}_{\ell}(\phi)\circ \big(\mathrm{Pr}_{\ell}\psi\big)^{-1}.$ For example, $\phi:\mathbb{C}^2\rightarrow \mathbb{C}^2$ action by $Sl_2(\mathbb{C})$ prolongs to $J^k$ by $\phi^{(k)}[f]_x^k:=[\phi(f)]_{\phi(x)}^k.$
It extends compatibly as an action on $J_X^{\infty}$.

The stabilizer of order $\leq k$ at $x\in X$ is denoted $G_{x}^k:=\{\phi\in G^k|\phi(x)=x\}.$ It acts on $k$-jets based at $x$. 

\begin{defn}
\normalfont
Let $Z_k\subset J_X^k(E)$ be a system of PDEs.
    A $G$ action is \emph{algebraic} if for the order $r$ of the
pseudogroup the stabilizer $G_{x}^r$ is an algebraic group acting algebraically on $J_X^r(E)_{x},x\in X.$
There exists an action $G_x^k$ on $Z_{k,x}$ and we call it \emph{algebraic} if for every $x\in X$, $Z_{k,x}\subset J_{X,x}^k(E)$ is an algebraic (non-singular) subvariety on which $G_{x}^k$ acts algebraically. 
\end{defn}
The pair of a $\D$-scheme $Z:=\{Z_k\}$ together with a formally integrable algebraic pseudogroup action $G=\{G^{(r)}\}$ is called a \emph{$G$-algebraic $\D$-scheme}, written as a pair $(Z,G)\subset J_X^{\infty}(E).$

We compute the quotient, which when combined with the co-filtered Douady-type construction for differential ideals given by Proposition \ref{prop: Douady} below, proves the $\D$-Hilbert scheme is a GIT quotient of the Spencer-semistable $\D$-ideal sheaves (Subsect. \ref{ssec: GIT}, below). Call a subset $W\subset J_X^kE$ Zariski closed if its fiber $W_x:=W\cap J_{X,x}^k(E),x\in X$ is Zariski closed. Similarly for $W\subset Z_k.$

\begin{prop}
\label{prop: Irreducible}
Assume that $G$ acts on $Z$ such that all $G$-orbits project to $X$. Then the algebraic variety $Z_x^k$ is irreducible for every $k$ and for all $x\in X.$
\end{prop}
\begin{proof}
By assumptions it follows at each finite order $Z_k\subset J_X^kE$ it is enough to restrict to a single fiber $Z_x^k$ with induced action by $G_x^k.$ By induction on $k$, with base case $k=\mathrm{Ord}(\I)$ (max order). This case is immediate and suppose it holds for $\mathrm{Ord}(\I)-1.$ Since $Z$ is formally integrable, $(p^k_{k-1})_x:Z_X^k\rightarrow Z_{x}^{k-1}$ is affine. Fixing polynomials $F_1,F_2$ in $k$-jets at $x\in X$, assume $(F_1\cdot F_2)(z_k)=0$ for all $z_k\in Z_x^k$ and that $F_1\neq 0.$ Then, for all $z_k$ with $F_1(z_k)\neq 0,$ the fiber $(p^{k}_{k-1})^{-1}(z_{k-1}),z_{k-1}=p^k_{k-1}(z_k)$ is affine and irreducible so that $(F_1F_2)|_{(p^k_{k-1})^{-1}(z_{k-1})}=0$ implies $F_2$ restricted to the fiber vanishes. But since $F_1(z_k)\neq 0$ for generic $z_k\in Z^k$, this implies $F_2=0$ on all fibers over a Zariski open set in $Z_x^{k-1}$. Since $Z_x^{k-1}$ is irreducible, $F_2$ is identically zero.
\end{proof}
Consider $G$ as in Proposition \ref{prop: Irreducible}. Such an algebraic action has a geometric quotient outside a $G$-stable Zariski closed subset. In particular, such a subset is nowehere dense, and removing a finite-codimension locus of singularity the quotient of an algebraic $\D$-scheme by an algebraic pseudo group is again an algebraic $\D$-scheme.
\begin{prop}
\label{prop: GeometricQuotientEquation}
    Let $(G,Z)$ be a $G$-algebraic formally integrable $\D$-space defined by a $\D$-ideal $\mathcal{I}.$ Then, there exists an integer $r\geq 0,$ and a Zariski-closed invariant proper subset $W_r\subset F^r(Z)$ such that the action is regular in 
    $$(p_r^{\infty})^{-1}\big(F^rZ\backslash W_r\big)\subset \mathrm{Spec}_{\D}(\mathcal{A}/\mathcal{I})=Z,$$
    with $p^{\infty}:Z\rightarrow X$ the structure map with $p^{\infty}_r:Z\rightarrow F^rZ,$ the induced projections $r>0.$
    In particular, $F^kZ\backslash (p_{r}^k)^{-1}(W_r)$ for every $k\geq r$ is algebraically filtered by closed and equidimensional orbits of $G^{(k)}.$ Thus, there exists a geometric quotient,
    $$\big(F^kZ\backslash (p_r^{k})^{-1}(W_r)\big)/ G^{(k)}.$$
\end{prop}
We now give the proof but note it makes use of a result (Proposition \ref{prop: KumLemma}) proven after.
\begin{proof}
Regular orbits have the maximal possible dimension and they
fiber a neighborhood after possibly restricting to an open dense subset. We may remove singular orbits inducing a geometric quotient.

To this end, note by our assumptions, we have for each $k$ a proper closed subset $W_k\subset Z^k\subset J_X^k(E)$ such that its compliment admits a geometric quotient, 
$Q_0^k\simeq (Z^k\backslash W_k)/G^k,$ since $W_k$ is Zariski-closed meaning $W_k\cap Z_x^k$ is Zariski-closed for every $x\in X.$ Then, we have
$$(Z^k\backslash W_k)/G^k\simeq \big(Z_x^k\backslash (W_k\cap Z_x^k)\big)/G_x^k.$$
Fix $\mathfrak{l}>\mathrm{Reg}_{\D}(\mathcal{I}).$ Since $G$ is transitive on $X$, orbits in $Z_k$ project to $X.$ In particular, the choice of $x\in X$ is irrelevant and we may restrict to the fiber 
$$Q_{x}^k:=[Z^k/G^k]_x^0=\widetilde{Z}_k\cap p_{k}^{-1}(x)/G_x^k.$$
By Proposition \ref{prop: KumLemma}, such a Zariski subset $\widetilde{Z}_k$ exists. We want to show fibers are affine and their restricted projections are affine morphisms of algebraic varieties. They are clearly the orbits of the $G_{x}^k$-action on affine fibers $Z^{k+1}\cap (p_k^{k+1})^{-1}(z_k)$ for $z_k\in Z_k$, with $p_k(z_k)=x\in X.$ Taking the quotient, which is given by the fibers of the canonical projection
\begin{equation}
\label{eqn: Q proj}
[Z^{k+1}/G^{k+1}]^0=\widetilde{Z}_{k+1}\cap p_{k+1}^{-1}(x)/G_{x}^{k+1}\rightarrow [Z^k/G^k]^0=\widetilde{Z}_k\cap p_k^{-1}(x)/G_x^k,
\end{equation}
we see they are affine. To show the induced quotient tower by the maps (\ref{eqn: Q proj}) are affine, we show the locus of singularity is of finite-codimension in $Z^{\infty}.$
To this end, note that for each $k\geq \ell>\mathrm{Reg}(Z)$, there are no singulariteis over regular points $\widetilde{Z}_{\ell}=Z^{\ell}\backslash W_{\ell}.$ Thus, the singular stratum of the $\D$-scheme is $(p_{\ell}^{\infty})^{-1}(W_{\ell})\subset Z^{\infty}.$ It is of finite codimension as reguired and this $W_{\ell},$ given by $Z^{\ell}\backslash \widetilde{Z}_{\ell}$ is a Zariski closed locus of singularity. Thus, for each $k\geq \ell$ singularities are contained in $(p_{\ell}^k)^{-1}(W_{\ell}),$ and consequently, for all $k\geq\ell >\mathrm{Reg}(Z),$ there is a tower of quotient equations,
$$\cdots\rightarrow [F^{k+r}Z/G^{k+r}]\rightarrow\cdots\rightarrow [F^{k+1}Z/G^{k+1}]\rightarrow [F^kZ/G^k]\rightarrow\cdots.$$
Each morphism is an affine map and the corresponding limit defines the algebraic $\D$-scheme $[Z/G]^{\infty}.$

\end{proof}
Thus given an involutive and formally integrable $\D$-ideal $\mathcal{I}$, with defining exact-sequence $0\rightarrow \mathcal{I}\rightarrow \mathcal{O}(J_X^{\infty}E)\rightarrow \mathcal{B}\rightarrow 0,$ with corresponding $\D$-scheme $Z:=\mathrm{Spec}_{\D}(\mathcal{B})=\mathrm{Spec}_{\D}\big(\mathcal{O}(J_X^{\infty}E)/\mathcal{I}\big),$ by Proposition \ref{prop: GeometricQuotientEquation}, we obtain a quotient equation (which is again almost-algebraic) and we denote the corresponding $\D$-ideal by $\mathcal{I}^G$, with corresponding exact sequence
\begin{equation}
    \label{eqn: QuotientIdeals}
    0\rightarrow \mathcal{I}^G\rightarrow \mathcal{O}(J_X^{\infty}E)^G\rightarrow \mathcal{B}^G\rightarrow 0.
\end{equation}
The corresponding $\D$-scheme defined by (\ref{eqn: QuotientIdeals}) is denoted by $Z^G:=\mathrm{Spec}_{\D}(\mathcal{B}^G)=\mathrm{Spec}_{\D}\big(\mathcal{O}(J_X^{\infty}(E))^G/\mathcal{I}^G).$
Since $G=\{G^k\}$ is formally integrable, it defines a $\D$-group scheme $\mathcal{G}$, in the sense of \cite{BD}. We will show in Subsect. \ref{Ssec: Spencer-regularity of the geometric quotient}, that one may then write 
$$Z^G=\mathrm{Spec}_{\D}(\mathcal{B}^G)\simeq \big[\mathrm{Spec}_{\D}(\mathcal{B})/\mathcal{G}]^{0},$$
by taking the regular (stable) locus.
%\begin{rmk}
 %   Similar results hold for functions $\mathcal{O}(Z^{\infty})$ analytic in $(t,x)$ and rational on fibers of $p_{\infty}:\mathrm{Spec}_{\D}(\A)\rightarrow X.$ Also the same hold if $Z=\{Z^{\ell}\}_{\ell\gg 1}$ is a complex analytic Stein space and $G$ is a complex-reductive Lie group acting by symmetries. Then, there exists a rational quotient on each finite jet-level.
%\end{rmk}

\subsection{Regularity of the geometric quotient}
\label{Ssec: Spencer-regularity of the geometric quotient}
We prove the following central result which states the complexity of the ideal $\mathcal{I}^G$ corresponding to the geometric quotient system given by Proposition \ref{prop: GeometricQuotientEquation} is controlled. This is necessary to ensure finite dimensionality and boundedness.

Since the $G$-action is transitive on $X$, $Z_x^k/G_x^k$ is a rational quotient whose set of singularities is nowhere dense, $x\in X.$ Denote by 
\begin{equation}
    \label{eqn: RegularGeomQuot}
    Q^k:=(Z^k/G^k)_0\subset Z^k/G^k,
\end{equation}
the geometric quotient on an open subset of $Z_x^k$ where the subscript indicates taking the regular part. 
The $G$-orbit of a $k$-jet of a section $j_k(s)(x)\in Z^k$ for some $x\in X$ is, by definition $G^k\cdot j_k(s)\in Z_x^k,$ and the tangent sheaf to this orbit, at the point $z_k=j_k(s)(x)\in Z^k$ is denoted $R_k(z_k).$ Setting $(Z_k)^0\subset Z_k,k\geq 0,$ the set of regular orbits, then $R_k|_{Z_k^0}\subset TZ_k^0,$ for each $k.$ A point $z_k\in Z_k$ is said to be \emph{regular} if $z_k\in Z_k^0.$

For any $z\in Z=Z^{\infty}$ the associated $\D$-scheme, with $z_k=p^{\infty}_k(z),$ consider the sequence, 
\begin{equation}
    \label{eqn: Regular tangent sequence}
    0\rightarrow T_{p^k_{k-1}}\rightarrow TZ_k^0\xrightarrow{(dp^k_{k-1})|_0}TZ_{k-1}^0\rightarrow 0,
\end{equation}
obtained by restriction of the differentials to the regular set $Z_k^0.$
Restricting further, to $R_k,$ we obtain a kernel,
\begin{equation}
    \label{eqn: W symbols}
    0\rightarrow ker(Tp^k_{k-1}|_{Z_k^0})\rightarrow R_k\rightarrow R_{k-1},\hspace{1mm} k\geq 0.
\end{equation}
By restriction from the equation manifold to its sub-variety of regular points $Z_k^0,$ one may show that the family $\mathrm{gr}(R)_0:=\{ker(Tp^k_{k-1}|_{Z_k^0})\}_{k\geq \ell_0}$ defines a symbolic system to this induced equation. One may then apply the Poincar\'e $\delta$-lemma, Proposition \ref{prop: Delta-Poincare}, to obtain the following result.
\begin{prop}
\label{prop: KumLemma}
    There exists an integer $\ell_0\geq 0$ and a $G$-invariant Zariski open subset $\widetilde{U}_{\ell_0}\subset Z_{\ell_0}$ such that for every geometric point $z\in Z^{\infty},$ there exists $z_{\ell_0}\in \widetilde{U}_{\ell_0}$ with $p^{\infty}_{\ell_0}(z)=z_{\ell_0}.$ Moreover, there exists a Zariski open subset $\widetilde{Z}^{\infty}\subset Z^{\infty}$ of the $\D$-scheme such that 
    $\mathcal{H}_{Sp}^{p,q}(\mathrm{gr}(R)_0)=0$ for $p\geq \ell_0$ and for all $q\geq 0$.
\end{prop}
\begin{proof}
This follows by applying \cite[Lemma 22.5,23.1]{Kum}. Explicitly, we note the Zariski-open subset is given by $\widetilde{U}^{\infty}:=(p^{\infty}_{\ell_0})^{-1}(\widetilde{U}_{\ell_0}).$
\end{proof}
We then study the quotient equation.
\begin{prop}
\label{prop: Existence of geometric quotient involutive degree}
Consider $\{Z/\!/ G\}:=\{Z^k/G^k\}_{k\geq 0}$ with geometric quotient $\D$-scheme given by (\ref{eqn: RegularGeomQuot}). 
Consider the fiber sequence,
$$0\rightarrow \mathfrak{q}_k\rightarrow T_{[Z^k/G^k]}\rightarrow T_{[Z^{k-1}/G^{k-1}]}\rightarrow 0.$$
Then there exists $\mathfrak{l}\in \mathbb{N}$ and a Zariski open subset $\widetilde{Z}_{\mathfrak{\ell}}\subset Z^{\mathfrak{\ell}}$ such that for every generic point $z_k\in Z^k$ with $p^k_{\mathfrak{l}}(z_k)=z_{\mathfrak{l}}\in \widetilde{Z}_{\mathfrak{l}},$ then 
$H_{Sp}^{p,q}(\mathfrak{q})=0,$ for all $p,\geq \mathfrak{l}$ and $q\geq 0.$ In particular, for every $k\geq \mathfrak{l}$ the number $dim(\mathfrak{q}_k)$ grows polynomially.
\end{prop}
\begin{proof}
Suppose $\mathfrak{l}\geq \mathrm{InvDeg}(Z)$. Then, $\mathcal{H}_{\delta}^{p,q}(\big(\mathrm{gr}(\mathcal{I})\big)=0$ for $p\geq \mathfrak{l},q\geq 0.$
By dualizing the isomorphism (\ref{eqn: ChKahler1}) and using Proposition \ref{prop: Omega and Ch isom}, consider there is and induced diagram,
\begin{equation}
\label{eqn: Symbol analysis diagram}
\adjustbox{scale=.90}{
\begin{tikzcd}
& 0\arrow[d] & 0\arrow[d] &  0\arrow[d] 
\\
0\arrow[r] & ker(Tp^k_{k-1}|_{Z_k^0}) \arrow[d] \arrow[r]& R_k\subset TZ_k^0\arrow[d]\arrow[r] & \arrow[d]R_{k-1}\subset TZ_{k-1}^0\rightarrow 0
\\
0\arrow[r] & \mathrm{gr}_k(\I)\arrow[d]\arrow[r] & TZ_k\arrow[d]\arrow[r] & TZ_{k-1} \arrow[d] \rightarrow 0
\\
0\arrow[r] & \mathfrak{q}_k \arrow[d]\arrow[r]& T(Z^k/G^k)\arrow[d]\arrow[r]& T(Z^{k-1}/G^{k-1})\arrow[d] \rightarrow 0   
\\
& 0 & 0&   0
\end{tikzcd}}
\end{equation}
By functoriality of Spencer $\delta$-complexes, diagram (\ref{eqn: Symbol analysis diagram}) induces a short-exact sequence of complexes,
$0\rightarrow \mathcal{S}p^{\bullet}(ker(Tp^k_{k-1}|_{Z_k^0}))\rightarrow \mathcal{S}p^{\bullet}(\mathrm{gr}_k(\I))\rightarrow \mathcal{S}p^{\bullet}(\mathfrak{q}_k)\rightarrow 0,$
for each $k\geq 0.$ Standard homological arguments, as in Proposition \ref{prop: Involutivity sequences}, give that $\mathcal{H}_{\delta}^{i,j+1}(ker(Tp^k_{k-1}|_{Z_k^0}))\simeq \mathcal{H}_{\delta}^{i+1,j}(\mathfrak{q}).$
Thus if $\mathfrak{\ell}$ is as in Proposition \ref{prop: KumLemma},
then there exists $\widetilde{Z}_{\mathfrak{\ell}}$ such that $\mathcal{H}_{\delta}^{i,j}(\mathfrak{q})=0$ over $\widetilde{Z}_{\mathfrak{\ell}}.$ This immediately implies that the polynomial (e.g. bounded) growth of $dim(\mathfrak{q}_k).$
\end{proof}
A more detailed description of the $\D$-Hilbert polynomial for the geometric quotient equation i.e. the ideal $\mathcal{I}^G$, is given in Proposition \ref{prop: HilbPolyForGeomQuot} below.

\subsection{$\D$-Hilbert and Quot functors}
\label{ssec: D-Hilb and Quot}
Having at our disposal a good notion of numerical polynomials $P\in \mathbb{Q}[t]$ for characteristic modules associated to $\D$-involutive $\D$-ideal sheaves, we can now proceed to construct the moduli space of such objects with \emph{fixed} $\D$-Hilbert polynomials equal to $P.$

We arrive at the main Definition \ref{defn: D-Hilb Functor} for the $\D$-Hilbert functor (\ref{eqn: D-Hilbert}) by  first constructing the $\D$-Quot functor. It is well-known that in the classical setting they are equivalent constructions \cite{Gro3}.\footnote{This fact is no longer true in the derived setting, as observed in \cite{CFK2,BKS,BKSY2}. We discuss this further in \cite{KSh2}.}
\begin{cons}
    \label{cons: DHilb}
    \normalfont 
    Fix a $\D$-smooth scheme of jets $Z=\mathrm{Spec}_{\mathcal{D}}(\mathcal{A}),$ and a numerical polynomial $P\in \mathbb{Q}[t].$
    Consider the assignment
    \begin{equation}
        \label{eqn: Classical D-Quot}
\underline{Q}_{\mathcal{D}_X,Z}^{P}:\mathrm{CAlg}_{\mathcal{D}_X}\rightarrow \mathrm{Set},\hspace{2mm}\mathcal{B}\mapsto \underline{Q}_{\mathcal{D}_X,Z}^{P}(\mathcal{B}),
\end{equation}
where for each commutative left $\D$-algebra $\mathcal{B}$, we set $\underline{Q}_{\mathcal{D}_X,Z}^{P}(\mathcal{B})$ to be the set of surjective $\mathcal{D}_X$-linear morphisms, $$\varphi:\mathcal{O}_{Z}\otimes_{\mathcal{O}_X}\mathcal{B}\twoheadrightarrow \mathcal{Q},$$  to a module $\mathcal{Q}$ of finite  $(\mathcal{O}_{Z}\otimes\mathcal{B})[\mathcal{D}_X]$-presentation with proper support relative to $\mathrm{Spec}_{\mathcal{D}_X}(\mathcal{B})$, modulo the equivalence relation: $\varphi_1\simeq\varphi_2$ if there exists a $\mathcal{D}_X$-isomorphism $\alpha:\mathcal{Q}_1\simeq \mathcal{Q}_2$ such that $\alpha\circ\varphi_1=\varphi_2.$ That is, the natural diagram
\[
\begin{tikzcd}
    \mathcal{O}_{Z}\otimes_{\mathcal{O}_X}\mathcal{B}\arrow[r,two heads,"\varphi_1"] \arrow[dr,two heads, "\varphi_2"] & \mathcal{Q}_1\arrow[d,"\alpha"]
    \\
    & \mathcal{Q}_2,
\end{tikzcd}
\]
commutes.
From the discussions so far (\ref{eqn: Classical D-Quot})  should be defined on the sub-category spanned by $\D_X$-involutive $\D_X$-schemes and will be denoted the same:
$$\underline{Q}_{\mathcal{D}_X}^{P}:\mathrm{CAlg}_{X}^{\mathrm{inv}}(\mathcal{D}_X)\simeq Sch_X^{aff}(\mathcal{D}_X)_{inv}^{op}\rightarrow \mathrm{Set}.$$

Fixing a numerical polynomial $P\in \mathbb{Q}[t],$ we characterize the $\D$-ideals via their regularizing properties of their symbols, using Proposition \ref{prop: Hilbert D-Polynomial}. 
In this way, we define a moduli functor $\underline{Q}_{\mathcal{D}_X,Z}^P$whose objects parameterize quotient $\D$-modules of the form $\varphi:\mathcal{O}_{Z}\twoheadrightarrow\mathcal{O}_{Z}/\mathcal{I}_X,$ for some $\D_X$-ideal sheaf $\mathcal{I}$ corresponding to a $\D$-involutive affine $\D_X$-scheme as in Definition \ref{defn: D-geom m-involutive}, whose $\D$-Hilbert polynomial $P_{\mathcal{I}}$ is equal to $P$. 

The equivalence relation $\alpha$ asserts there is an isomorphism $\mathrm{ker}(\varphi_1)=\mathrm{ker}(\varphi_2)$ of $\D_X$-ideals.
\end{cons}

\begin{rmk}
By definition, the functor (\ref{eqn: Classical D-Quot}) coincides with the $\D$-Hilbert functor. However, it can be defined more generally for a fixed vector $\D$-bundle or locally $X$-projective $\mathcal{O}_Z[\mathcal{D}]$-module $\mathcal{V}$, denoted $\underline{Q}_{\mathcal{D}_X,\mathcal{V}}.$ The corresponding numerical characterization is suggested in Remark \ref{rmk: Ranks and Chern class} e.g. by fixing the $\D$-Chern classes.
\end{rmk}
We enunciate the situation for the tautological vector $\D$-bundle $\mathcal{V}$ over $Z$ given by $\mathcal{O}_Z.$ 
\begin{defn}
\label{defn: D-Hilb Functor}
\normalfont 
Let $X$ be a proper scheme and fix a smooth affine $\mathcal{D}$-scheme $Z=\mathrm{Spec}_{\mathcal{D}_X}(\mathcal{A}).$ The functor of \emph{$\D_X$-involutive $\mathcal{D}$-geometric PDEs with fixed $\D$ Hilbert polynomial} is the assignment
\begin{eqnarray}
    \label{eqn: D-Hilbert}
\mathcal{H}\underline{\mathrm{ilb}}_{\mathcal{D}_X/Z}^{P}:\mathrm{Sch}_{\mathcal{D}_X}^{\mathrm{inv}}&\rightarrow& \mathrm{Sets},\nonumber
    \\
    \mathcal{Y}&\mapsto & \mathcal{H}\mathrm{ilb}_{\mathcal{D}_X/Z}^{P}(\mathcal{Y}),
\end{eqnarray}
where $\mathcal{H}\mathrm{iln}_{\D_X/Z}^{P}(\EQ):=\{\mathcal{T}\subset \mathcal{Y}\times Z,\text{involutive, }\mathcal{D}\text{-flat over } \mathcal{Y}, P_{\mathcal{I}_{\mathcal{T}}}=P\}$.
Functor (\ref{eqn: D-Hilbert}) is simply to be called the $\D$-\emph{geometric Hilbert functor} and the conditions explicitly mean $\mathcal{O}_{\mathcal{T}}$ is $\D$-flat over $\mathcal{O}_{\mathcal{Y}}$ and given by a $\D$-involutive $\D$-ideal sheaf and its restriction to $\{y\}\times Z$ has $\D$-Hilbert polynomial equal to $P.$
\end{defn}
Functor (\ref{eqn: D-Hilbert}) is defined on the sub-category spanned by $\mathcal{D}_X$-schemes determined by formally $\mathcal{D}$-integrable equations which are additionally $\D$-involutive.

\begin{rmk}
 If $\mathcal{B}$ is not $\D$-formally integrable and if $\mathcal{B}'$ 
is obtained from
it by Kuranishi's prolongation-projection theorem, by our prescription of dimension and numerical polynomials (thus of regularity), the numbers $p,d$ in Proposition \ref{prop: Hilbprop} change (in fact, decrease).  Consequently, the dimension of the support of the linearization sheaf is not constant nor does it tend to a constant during prolongation. 
\end{rmk}
We now prove the representability of the $\D$-Hilbert functor for $\D$-ideal sheaves by a $\D$-scheme. We \emph{assume} there exists a universal $\mathcal{D}$-flat family of closed sub-schemes of $Z$, 
$$\mathcal{U}\subset Z\times \mathrm{Hilb}_{\mathcal{D}_X,Z}^{P(t)},$$ 
with $P_{\mathcal{U}}=P,$ such that: for every test $\mathcal{D}_X$-algebra of finite-type $\mathcal{R}^{\ell},$ with corresponding finite-type $\mathcal{D}$-scheme $\mathrm{Spec}_{\mathcal{D}}(\mathcal{R}_X^{\ell}),$ and for every flat family as above, there exists a unique morphism 
$$\mathrm{Spec}_{\mathcal{D}}(\mathcal{R}_X^{\ell})\rightarrow \mathrm{Hilb}_{\mathcal{D}_X,Z}^{P(t)},$$ 
such that $\mathrm{Spec}_{\mathcal{D}}(\mathcal{R}_X^{\ell})\times_{\mathrm{Hilb}_{\mathcal{D},Z}^{P}}\mathcal{U}\subset Z\times \mathrm{Spec}_{\mathcal{D}}(\mathcal{R}_X^{\ell}).$ In particular, there is a universal $\D$-algebra quotient
$\mathcal{B}_{univ}:=\mathcal{O}_{Z\times \mathcal{H}ilb_{\D_X}^{P,\Lambda}(Z)}/\mathcal{I}_{univ},$
with universal ideal $\mathcal{I}_{univ}\subset \mathcal{O}_{Z\times \mathcal{H}ilb_{\mathcal{D}_X}^{P,\Lambda}(Z)}.$
Since the numerical polynomials for a $\D$-ideal sheaf and its characteristic module contain the same information, one may show these two moduli spaces are isomorphic. If we consider projectivization of the characteristic variety e.g. in $\mathbb{P}T^*X,$ then the ($\D$-)Hilbert scheme is representable by a ($\D$-) scheme.


\subsection{Douady-type Grassmannians for differential ideals}
\label{ssec: Douady}
Due to the pro-algebraic nature of $J_X^{\infty}E$, the $\D$-Hilbert functor is to be viewed as a pro-ind object. To treat the infinite-dimensional (pro-finite-dimensionality), we adapt a construction of \cite{Dou}.



\begin{prop}
\label{prop: Douady}
Fix $Z:=J_X^{\infty}E.$ There is ind-scheme of finite-type 
    $\mathrm{Grass}_{\D}(Z),$ given by
$$\mathrm{Grass}_{\D}(Z):=\varprojlim_k \mathcal{G}r_X(J_X^kE)\simeq \varprojlim_k\big(\bigcup_{d\geq 0}Quot(J^kE;d)\big),$$
where $Quot(J^kE;d)$ is the moduli space parameterizing $d$-dimensional $\mathcal{O}_X$-coherent quotients $\mathcal{O}(J^kE)\twoheadrightarrow Q.$
\end{prop}
\begin{proof}
Note $\mathrm{dim}(J_X^kE)=n+m\cdot C_k^{n+k}.$ For each $k\geq 0$, we set $\mathcal{G}r_X(J_X^E):=\bigcup_{d\geq 0}Quot(J_X^kE;d).$ We want to show that specifying a point in $\mathrm{Grass}_{\D}(Z)$, built out of a system of $\mathcal{G}r_X(J_X^kE)$, it suffices to give compatible systems of coherent subspaces $R_k\subset J_X^kE$ ($\mathcal{O}_{R_k}$ is coherent), arising from kernels of quotient sheaves $\mathcal{O}(J_X^kE)\rightarrow Q_k,$ of rank $d_k,k\geq 0.$ Then, we generate a subspace $R\subset J_X^{\infty}E$ where $R_k=R\cap J_X^kE\subset J_X^kE$ with the compatibilities $R_k\simeq R_{k+1}\cap J_X^kE$ under the natural projections $J_X^{k+1}E\rightarrow J_X^kE.$ This compatible system then corresponds to a compatible system of points in Quot-schemes $[Q_k]\in Quot(J_X^kE;d_k)$.
To this end, note for each $k>0,$ there exists a natural morphism 
$\phi_k:\mathcal{G}r_X(J_X^{k+1}E)\rightarrow \mathcal{G}r_X(J_X^kE),$ defined as follows.
Consider a quotient i.e. a point $[Q_{k+1}]\in Quot(J_X^{k+1}E;d_{k+1})$ for some $d_{k+1},$ represented as a surjection $\mathcal{O}(J_X^{k+1}E)\rightarrow Q_{k+1}$, and since $p^{k+1}_k:J_X^{k+1}E\rightarrow J_X^kE$ is a surjective morphism between smooth algebraic varieties (vector bundles over $X$), then $\mathcal{O}(J_X^kE)\hookrightarrow \mathcal{O}(J_X^{k+1}E)$ is an injection of $\mathcal{O}_X$-modules, and we define the image of $[Q_{k+1}]$ under $\phi_k$ to be 
$$\phi_k[\mathcal{O}(J_X^kE)\twoheadrightarrow Q_{k+1}]:=[\mathcal{O}(J_X^kE)\rightarrow Q_{k}],$$
via $(p_k^{k+1})^*$, where $Q_k$ is define as follows. Since the composition $q_{k,k+1}:\mathcal{O}(J_X^kE)\subset\mathcal{O}(J_X^{k+1}E)\twoheadrightarrow Q_{k+1}$ need not be surjective, we consider 
$ker(q_{k,k+1})$ and define $Q_k:=Q_{k+1}/ker(q_{k,k+1}).$ Defined in this way, $\phi_k$ is induced from the  morphism
$$\psi_k:Quot(J_X^{k+1}E)\rightarrow Quot(J_X^kE), [Q_{k+1}]\mapsto [Q_k:=Q_{k+1}/ker(q_{k,k+1})].$$
It follows there exists a compatible system, whose limit is a (pro-ind) scheme of finite-type.
\end{proof}
The representability of the $\D$-Hilbert functor (\ref{eqn: D-Hilbert}) is established by proving there exists a finite-type ind-subscheme of the $\D$-geometric Douady-type Grassmannian in Proposition \ref{prop: Douady}. Roughly, it is obtained via the compatible system of kernels obtained from $\phi_k,\psi_k$, e.g. $\mathcal{I}:=\varprojlim ker[\mathcal{O}(J_X^kE)\twoheadrightarrow Q_k],$ which stabilizes due to regularity assumptions (\ref{defn: D-Geometric Regularity}).


\subsection{Algebraic quotients and GIT}
\label{ssec: GIT}
Fix a $G$-algebraic $\D$-space $(G,Z).$ In subsection \ref{ssec: Differential algebra quotients}, we assumed that $G$ is algebraic. It is possible to remove this assumption by separating orbits in low level jets. Higher order jets are automatic, as the prolonged actions are always algebraic. 
The growth of the $\D$-Hilbert function for the geometric quotient equation is bounded.

\begin{prop}
\label{prop: HilbPolyForGeomQuot}
    Let $(G,Z)$ be a $G$-algebraic $\D$-space defined by a formally integrable $\D$-ideal $\mathcal{I}$. Consider the quotient $\D$-scheme $Z^G:=\{[Z^k/G^k]\}$ as in (\ref{eqn: RegularGeomQuot}) and its
   associated numerical Hilbert function $h(Z^G;k):=dim(\mathfrak{q}_k)$. Then there exists a polynomial for large $n$ i.e. $\D$-Hilbert polynomial $P_{\D}(\mathcal{I}^{\mathcal{G}},n)$ such that $h(Z^G) \simeq P_{\D}(\mathcal{I}^G)$ for $n\gg 0.$

\end{prop}
\begin{proof}
Note that the growth is controlled by the value of $\mathrm{dim}(\mathfrak{q}_k)$ at generic points $z_k\in Z^k.$ It is given by 
$P_{\D}(\mathcal{I}^G,k):=dim(\mathfrak{q}_k)=dim([Z^k/G^k])-dim([Z^{k-1}/G^{k-1}]),$
where by Proposition \ref{prop: GeometricQuotientEquation}, $dim(Q^k)$ is the transcendence degree of the field of rational $G_x^k$-invariant functions on $Z_x^k$ i.e. $\mathcal{O}_{rat}(Z_x^k)^{G_x^k}.$
By Proposition \ref{prop: Existence of geometric quotient involutive degree}, there exists a numerical polynomial $P\in \mathbb{Q}[t]$ such that 
$P_{\D}(\mathcal{I}^G,k)=P(k),\hspace{1mm} k\gg1.$
\end{proof}
The following corollary is immediate from Proposition \ref{prop: Existence of geometric quotient involutive degree} and Proposition \ref{prop: HilbPolyForGeomQuot}.
\begin{cor}
The $\D$-Hilbert polynomial of the $\D$-ideal of the geometric quotient is 
$P_{\D}(\mathcal{I}^{\mathcal{G}},z)=P_{\D}(\mathcal{I},z)-P_{\D}(G/\mathcal{I},z),$
for a uniquely determined numerical $\D$-Hilbert polynomial $P_{\D}(G/\mathcal{I}).$
\end{cor}
\begin{proof}
Note there exists a uniquely defined numerical function,
$$h_{G/Z}(k):=dim(ker(Tp^k_{k-1}|_{Z_k^0})),k\gg 1.$$
By a similar argument as in Proposition \ref{prop: HilbPolyForGeomQuot}, it is given by a polynomial $P_{\D}(G/\mathcal{I},z)$. Then, by diagram (\ref{eqn: Symbol analysis diagram}), the result follows.
\end{proof}
To prove there exists a GIT-quotient of the moduli problem, with all boundedness arguments, 
we restrict to $\mathfrak{M}_{\D}^{Sp-ss,inv}\subset \mathfrak{M}_{\D}^{inv}$, consists of those $\D$-ideals, involutive and formally integrable, which are also Spencer semistable. 
Given an algebraic pseudogroup $G$ acting on points of $\mathfrak{M}_{\D}^{inv}(P,n,m)$, we now describe the induced quotient
$$\mathfrak{M}_{\D}^{Sp-ss,inv}(P,n,m)/\!/\mathcal{G}.$$


\section{Existence and finiteness}
\label{sec: Main Result Proof}
This section is devoted to the proof of the main result of the paper. 

\begin{thm}
\label{MainTheorem}
    Let $X$ be a smooth $D$-affine variety and consider a locally free $\mathcal{O}_X$-module $E$ of finite rank. Let $Z:=J_X^{\infty}E$ denote the algebraic infinite jets of $E$, endowed with its natural $\D_X$-algebra structure.
Consider the moduli functor (\ref{eqn: D-Hilbert}) classifying formally integrable, involutive $\D_X$-ideal sheaves in $J_X^{\infty}E.$ Then it is representable by an ind-scheme of finite-type,
    $$\mathbf{Hilb}_{\D_X}(Z)\simeq \varinjlim_{(d,k)}\mathrm{Hilb}^{(d,k)}(J_X^kE),$$
    where $\mathrm{Hilb}^{(d,k)}(J^kE)$ is the scheme of algebraic ideals $I$ in $J_X^kE$ with Hilbert polynomial $d$ and order $\leq k.$ Moreover, for each $m\geq 0$, the locus $\mathbf{Hilb}_{\D_X}^{inv,m}(J_X^{\infty}E)\subset \mathbf{Hilb}_{\D_X}(J_X^{\infty}E)$ where $\mathcal{I}$ is Spencer $m$-regular defines a Zariski-open finite-type subscheme.
\end{thm}

We split the proof of the Theorem \ref{MainTheorem} into several steps:
\begin{itemize}
\item[-] First, we discuss global generation and prove boundedness in Proposition \ref{prop: Boundedness 1}). 

\item[-] We prove a PDE-analog of the Lefschetz hyperplane theorem in Proposition \ref{prop: Inv Res}, ensuring consistency of Spencer-regularity along non-characteristic sub-manifolds.

\item[-] Introducing a dimension filtration (implicit from Douady's construction in Sect. \ref{ssec: Douady})) we prove representability in Proposition \ref{prop: HilbRep}.
\end{itemize}
A preliminary fact.

\begin{prop}
Fixing a (global) section $s_d\in \mathcal{O}_{T^*X}(d),$ induces a surjective map
$\mathcal{O}_{T^*X}(d)\otimes_{\mathcal{O}_{T^*X}}\mathcal{C}h_k\rightarrow \mathcal{C}h_{k+d},$ on global sections for all $k\geq \mathrm{Reg}_{\mathcal{D}}(\EQ).$ 
Moreover, $\mathcal{C}h$ is generated by its global sections.
\end{prop}
\begin{proof}
    The first part can be seen by noting that multiplication with some $\xi_j$ generates a morphism of quotient rings by Proposition \ref{prop: Mult by microlocal coordinates}. There exists $p\in \mathbb{Z},$ for which $\mathcal{C}h(\geq p)$ is generated by $\mathcal{C}h(p)$ and 
    $dim\big(\mathcal{C}h(r)\big)=\mathbf{h}^{\mathcal{Y}}(r),\forall r\gg p.$
    Since prolongations of involutive symbols are again involutive i.e.
    $\alpha_{k+1}^{(i)}=\sum_{\ell=i}^{n}\alpha_k^{(\ell)},$ gives by induction
$\alpha_{k+r}^{(\ell)}=\sum_{j=\ell}^{n}C_{r-1}^{r+j-\ell-1}\cdot \alpha_k^{(j)},$
and then we simply notice that 
$rank\big(\mathcal{C}h_{k+r}\big)=\sum_{\ell=1}^{n}C_{r}^{r+\ell-1}\cdot \alpha_k^{(\ell)},$
where the right-hand side agrees with the Hilbert polynomial for the non-linear PDE system $\EQ.$ The second statement follows from finite cogeneration of involutive symbolic systems and from the fact that $X$ is $\mathcal{D}$-affine, so the corresponding $\D$-module is indeed generated by its global sections.
\end{proof}



%A practical observation to be drawn from Proposition \ref{prop: Involutivity sequences}, which seems previously unknown in the classical geometric theory of PDEs, is that any quotient/factor equation by a sub-equation must always possess \emph{less} compatibility conditions.

\subsection{Boundedness}
\label{ssec: Boundedness}
Consider an $\mathcal{O}_X$-submodule of $\mathcal{O}(J_X^kE)$, let $M_k^*$ denote its sections. Recall sections of $J_X^kE$ are dual to $\D_X^{\leq k}\otimes_{\mathbb{C}}E^*.$ Consider a compliment $M_k^{\perp}$ in this dual and put $\M_k:=\D_X^{\leq k}\otimes_{\mathbb{C}}E^*/M_k^{\perp},$ the quotient. One may consider prolongations, and set  $\M=\{\M_k\}$ and similarly for $M^{\perp}.$ Consider the smallest $\ell,m\in \mathbb{N}$ such that involutivity is imposed. For $N_{\ell}:=M_m^{\perp}\cap (\D_{X}^{\leq \ell}\otimes_{\mathbb{C}}E^*),$ and restricting to an open dense subset $U$ of $X$, if $q:=\ell-k$, then $\mathrm{pr}_q(M_k^*)$ is free and involutive. By \cite{Ma3}, the integers $m,\ell$ are uniformly bounded by some $\rho=\rho(k,rankE,n).$ See also the over-estimate \cite{Sw}.

Under Spencer regularity assumptions (\ref{defn: D-geom m-involutive}), this applies to families of $\D$-schemes. Namely, using the notion of $\mathcal{D}$-geometric regularity we have an analog of Mumford's boundedness result.
\begin{prop}
\label{prop: Boundedness 1}
Consider a family $\{\EQ_i\}_{i\in I}$ of Spencer regular and formally integrable algebraic non-linear PDEs imposed on sections of a $\mathrm{rank}(E)=m$ bundle $E\rightarrow X$ over a $\D$-affine $k$-scheme $X$ of dimension $n$. Then the family is bounded if and only if the set of $\mathcal{D}$ Hilbert polynomials $\{P_{\EQ_i}\}$ is finite and there is a uniform bound on the involutivity degrees i.e.
    $\mathrm{Reg}_{\mathcal{D}_X}(\EQ_i)\leq \rho,\forall i\in I.$
\end{prop}
This result essentially gives the appropriate `flattening stratification' \cite{Gro3}; it identifies sub-loci of the $\D$-Hilbert scheme which are better behaved, consisting of those $\D$-ideals which are Spencer $m$-regular for a fixed $m$. In particular, by (\ref{defn: D-geom m-involutive}) (ii), they are differentially generated from a fixed finite order.

\begin{proof}
For a given $\D$-scheme $Z^{\infty}$ in the family, fix $\ell\geq 0$ and consider the family of projections of $\mathrm{pr}_mZ_k$ with $\ell\leq m+k$ in $J_X^{\ell}E.$ Then, as $m\rightarrow \infty$ the family is decreasing and stationary. Let $m=k+p\geq \ell$ be the smallest integer such that the projection in $\mathcal{I}_{\ell}$ of $\mathrm{pr}_pZ_k\subset J_X^mE$ is equal to the closed subscheme $F^{\ell}Z^{\infty}.$ This always holds over a Zariski dense open subset $U\subset X.$ Malgrange proved that the integer $m$ is bounded by a function $\rho=\rho(k,\mathrm{dim}X).$
Thus, by assumption that the family is bounded, there exists a finite set $\{\rho_i\}_{i\in I}$ of bounds, obtained this way. Looking at the symbolic systems of each $\D$-scheme, we obtain a family of homogeneous ideals defining the characteristic modules, and let $\mathfrak{D}_i,i\in I$ be a bound for the elements of a Gröbner basis for the lexicographic order. Upon choosing generic coordinates, there exists by \cite[Theorem 3.4, Theorem 3.5]{Ma2}, an upper bound $\mathfrak{D}_i(n,d_i)$ for $\mathcal{I}$ generated by elements of degree $d_i,i\in I.$
Moreover, there exists a smallest $\ell_i,i\in I$ such that the symbolic module for PDE $Z_i^{\infty}$ is $\ell_i$-involutive. It is bounded by an integer $\gamma_i$ (see \cite{Sw}, or Appendix \ref{Appendix Sweeney}, and Theorem 3.4 \emph{loc.cit.}). Further, there exists a minimum $r_i$ for each $i\in I$ such that the $\ell_i$'th prolongation is contained in that of degree $r_i.$ This integer is bounded as well.



First, notice the general fact that if $\mathcal{N}$ is a symbol co-module for an involutive PDE, then for all $k\geq 0$ and for all $1\leq p\leq \mathrm{dim}(X),$ 
$$H_{\delta}^{p,q}(\mathcal{N})^*\simeq H_{p,q}(\mathcal{N}^*)\simeq H_{p-1,q+1}(\mathcal{N}^0),$$
where $\mathcal{N}^0$ is the annihilator.

Now, let $\mathcal{N}$ be a $\mathcal{C}:=\mathrm{Sym}(V^*)$-comodule and $\mathcal{M}$ be a $\mathrm{Sym}(V)$-module. Here, $V$ is the $n$-dimensional vector space which may be thought of as corresponding to the tangent sheaf $\Theta_{X,x}$ for each $x\in X.$
From Definitions \ref{defn: D-Geometric Regularity} and \ref{defn: D-geometric generalized involutivity}, we have involutivity at degree $k_0$ if it is $\mathrm{dim}(V)$-acyclic at degree $k_0.$
By duality, a graded $\mathrm{Sym}(V)$-module $\mathcal{M}$ is involutive at degree $k_0$ if 
$$H_{p,q}(\mathcal{M})=0,\forall k\geq k_0,0\leq p\leq \mathrm{dim}(V).$$

A graded ideal $\mathcal{I}$ is $k$-regular if its $i$-th syzygy module is generated by elements of degrees $\leq k+i.$ It follows that
$$\mathrm{reg}(\mathcal{I})=k\Rightarrow H_{p,q}(\mathcal{I})=0,q>k.$$
By our assumptions, each $\EQ_i$ is a $\mathcal{D}$-involutive PDE with corresponding $\mathcal{D}$-algebra of functions $\mathcal{B}_i=\mathcal{A}/\mathcal{I}_i$ with $\mathcal{A}$ our polynomial ring in derivatives of dependent variables for which $\mathcal{I}_i$ is $k_i$-regular:
$$H_{p,q}(\mathcal{B}_i)=0,\forall r\geq k_i,$$
and therefore by Proposition \ref{prop: Unifying},
$\mathrm{reg}(\mathcal{I}_i) \equiv \mathrm{deg}^{\mathrm{inv}}(\mathcal{B}_i).$
We may also apply Cartan's test \cite{C,C2}, which states there exists an integer $m_0\geq 0$ such that $H_{\delta}^{p,q}(\mathcal{N})=0,\forall q\geq m_0,0\leq p\leq \mathrm{dim}(X).$
By our assumptions on involutivity, we have that 
$\mathcal{M}$ is a finitely generated graded polynomial module, so by Hilbert's syzygy theorem there exists an integer $m_0\geq 0$ such that 
$H_{p,q}(\mathcal{M})=0,\forall q\geq m_0,0\leq p\leq \mathrm{dim}(X).$
Moreover, 
$H_{\delta}^{0,q}(\mathcal{N})=0,$ and the dimension of $H_{\delta}^{1,q-1}(\mathcal{N})$ equals the dimension of the quotient of the prolongation of $\mathcal{N}_{q-1}$ by $\mathcal{N}_q$ for every $q>0.$
\end{proof}
\subsubsection{Involutive restriction}
Given the $\D$-affine variety $X$ as before, the existence of non-characteristic sub-spaces follows from an analog of Noether normalization lemma applied to characteristic varieties defined by symbol ideals e.g. (\ref{eqn: Filtered Char ideal}). The set of all non microcharacteristic subspaces of $T^*X$ of fixed dimension define an open dense subset of the corresponding Grassmannian of $T^*X$. A subvariety $U\subset X$ is said to be non-microcharacteristic if it is when viewed, via the zero-section, as a sub-space of $T^*X.$
\begin{prop}
\label{prop: Inv Res}
Let $\mathcal{I}_X$ be a $\D$-involutive $\D$-ideal sheaf. For $j:H\subset T^*X$ a non-microcharacteristic analytic subset, denote by $\mathcal{I}_{H}$ the $\D$-ideal obtain by non-characteristic restriction. Then $\mathrm{Reg}_{\mathcal{D}}(\mathcal{I}_X)=m$ if and only if $\mathrm{Reg}_{\mathcal{D}}(\mathcal{I}_H)=m.$  
\end{prop}
\begin{proof}
We have the ideal sequence
\begin{equation}
    \label{eqn: Ideal sequence of H}
0\rightarrow \EuScript{J}_H\hookrightarrow \mathcal{O}_{T^*X}\rightarrow \mathcal{O}_H\rightarrow 0,
\end{equation}
which is a sequence of sheaves of filtered algebras by polynomial degree, which for homogeneous degree $k$ reads
$0\rightarrow \EuScript{J}_{H}(k)\hookrightarrow \mathcal{O}_{T^*X}(k)\rightarrow \mathcal{O}_{H}(k)\rightarrow 0.$
In particular, consider $k=1,$ and the dual sequence, considered stalk-wise, for a 
$k$-rational point $x$ of $X$ as
$$0\rightarrow \mathcal{V}_x^*\rightarrow \Theta_{X,x}^{\vee}\simeq\Omega_{X,x}^1\xrightarrow{\nu_{x}}\mathcal{W}^*\rightarrow 0,$$
where we use the notation: for $W\subset T_xX,$ we have $W^*$ is its dual, and $V^*=\mathrm{Ann}(W)\subset T_x^*X.$

Recalling $\mathcal{N}_k$ and $\mathcal{C}h_k^{\mathcal{Y}},$ as in (\ref{eqn: k-th symbol module}), and (\ref{eqn: k-characteristic module}), respectively. Viewed as a submodule of 
$\mathrm{Sym}^k(\Theta_{X,x}^{\vee})\otimes \mathcal{B},$ tensoring with (\ref{eqn: Ideal sequence of H}) gives $H$-restriction, $j^*\mathcal{C}h_{k}=\mathcal{C}h_k|_{H}\subset \mathrm{Sym}^k(\mathcal{W}_{x}^*)\otimes \mathcal{B}.$ It is the image of $\mathcal{C}h_k$ by the restriction $\mathrm{Sym}^k(\Omega_X^1)\otimes_{F^k\mathcal{B}}\mathcal{B}\twoheadrightarrow \mathrm{Sym}^k(\mathcal{W}_x^*)\otimes \mathcal{B},$ induced by $\nu_x,$ for $x\in X.$
Omitting reference to $x\in X$ from notation, we have on one hand a commutative diagram 

\[
\begin{tikzcd}
    \mathcal{C}h_{k+1}\arrow[d]\arrow[r] & \mathcal{C}h_k\otimes\Omega_{X}^1\arrow[d]
    \\
    \mathcal{C}h_{k+1}|_{H}\arrow[r] & \mathcal{C}h_k|_H\otimes W^*,
\end{tikzcd}
\]
as well as, for the $\ell$-th Spencer sequence, the isomorphism of first $\ell-\mathrm{I}+1$ terms:
\[
\begin{tikzcd}
    \mathcal{C}h_{\ell}\arrow[d]\arrow[r] & \mathcal{C}h_{\ell-1}\otimes W^*\arrow[d]\arrow[r] & \mathcal{C}h_{\ell-2}\otimes \wedge^2W^*\arrow[d]\arrow[r] & \cdots
    \\
    \mathcal{C}h_{\ell}|_{H}\otimes W^*\arrow[r] & \mathcal{C}h_{\ell-1}|_{H}\otimes W^*\arrow[r] & \mathcal{C}h_{\ell-2}|_{H}\otimes \wedge^2 W^*\arrow[r] & \cdots
\end{tikzcd}
\]
giving 
$$H^{*,*}(\mathcal{C}h)\simeq H^{*,*}(\mathcal{C}h|_{H}).$$
Here, $I$ is the degree of involutivity.

For $i<I$ it suffices to consider that, 
$\mathcal{C}h_i\simeq Sym^i(\Omega_X^1)\otimes\mathcal{B}_X,$ and $\mathcal{C}h_{i}|_{H}\simeq Sym^i(W^*)\otimes i^*\mathcal{B},$ where $i^*\mathcal{B}\simeq \mathcal{B}_H,$ we obtain that:
\[
\begin{tikzcd}
\arrow[r]
\mathcal{C}h_{I}\otimes\wedge^{q-1}W^*\arrow[d]\arrow[r] & Sym^{I-1}(\Omega_X^1)\otimes\mathcal{B}\otimes \wedge^qW^*\arrow[d]\arrow[r] & \cdots\\
    \arrow[r] \mathcal{C}h_{I}|_{H}\otimes\wedge^{q-1}W^*\arrow[r] & Sym^{I-1}W^*\otimes i^*\mathcal{B}\otimes \wedge^q W^*\arrow[r] & \cdots
\end{tikzcd}
\]
and the only contributions to cohomology are $H^{I,q-1}$ and $H^{I-1,q}.$ 
Calculating the Spencer cohomology is achieved by standard spectral sequence arguments. Namely, introduce a filtration by powers of $\Omega_X^1$ in $\wedge^q\Omega_X^1$, denoted $G_p^q:=\wedge^p\mathcal{V}^*\wedge \wedge^{q-p}\Omega_X^1,$ so that $G_{q}^q\subset G_{q-1}^q\subset \cdots\subset G_0^q:=\wedge^q\Omega_X^1.$
There is an induced filtration, given for each $\ell\geq 0,$ by
$$Fl_{\EQ}^{p,q}:=\mathcal{C}h_{\ell-p-q}^{\EQ}\otimes G_{p}^{p+q}\simeq \mathcal{C}h_{\ell-p-q}^{\EQ}\otimes \bigwedge^p\mathcal{V}^*\wedge\bigwedge^q\Omega_X^1.$$
It satisfies $Fl_{\EQ}^{p+1,q-1}\subset Fl_{\EQ}^{p,q},$ and its successive quotients, giving the $0$-th page are
$E_0^{p,q}:=Fl_{\EQ}^{p,q}/Fl_{\EQ}^{p+1,q-1}\simeq \mathcal{C}h_{\ell-p-q}^{\EQ}\otimes \wedge^p\mathcal{V}^*\otimes \wedge^q\mathcal{W}^*.$
The differential acts according to $W$ and one may show that 
$$E_1^{p,q}\simeq H^{\ell-p-q,q}(\mathcal{C}h)\otimes \wedge^p\mathcal{V}^*.$$
From these arguments, one may show that 
$$H^{0,q}(\mathcal{C}h)\simeq \bigoplus_{q_0\geq 0}H^{0,q_0}(\mathcal{C}h|_{H})\otimes \wedge^{q-q_0}(V^*).$$ 
To establish the full vanishing except for the position where involutivity occurs, one may proceed inductively on $\ell\geq k$ to show $H^{i,\ell-i}=0$ except at $i=k-1$ and if this holds for $\mathcal{C}h$ it holds for $\mathcal{C}h|_{H}.$ It is a long check so we omit the details in full but mention that every differential $d_{r}^{p,q}$ for $r>0$ is trivial except for the case of $d_{1}^{p,0}$ which happens when $\ell-p<k.$
\end{proof}
By \cite{G,G2}, we note the following.
\begin{rmk}
The obstructions for formal
integrability belong to the groups $H^{p,2}$, but after finitely many prolongations
the system becomes $m$-acyclic and $m$-involutive.
\end{rmk}
Proposition \ref{prop: Inv Res} states that the degree where this occurs is the same for characteristic modules and all their non-characteristic restrictions.

\begin{prop}
\label{prop: Involutive restriction is involutive}
For all $i \geq ord$ if $H^{i,j}(\mathcal{C}h)=0$ for all $j\geq n-m,$ then for every non-characteristic $H\subset T^*X$ whose dual is denote by $V$,
with restricted symbol $\mathcal{C}h|_{H},$ one has 
$H^{i,j}(\mathcal{C}h|_{H})=0,\forall j\geq n-m.$
\end{prop}
Denote for each non-negative integer $k$, and each classical solution $\varphi$ the restriction map
\begin{equation}
    \label{eqn: Restriction map}
    \mathrm{res}_{k}:H^0(T^*X,\mathcal{C}h_{k,\varphi})\rightarrow H^0(V,\mathcal{C}h_{k,\varphi}|_{V}).
    \end{equation}

\begin{prop}
    Suppose $H\subset T^*X$ is non-characteristic and for each classical solution $\varphi$ the restriction  $\mathcal{C}h_{k,\varphi}|_{V}$ is $m$-involutive. Then, if for some $m_0\geq m,$ map \emph{(\ref{eqn: Restriction map})} defining restriction $\mathrm{res}_{m_0}$ is surjective, then $\mathrm{res}_{p}$ is surjective for all $p\geq m_0.$
    \end{prop}
\begin{proof}
By assumption, the map  $\mathrm{res}_{k}:H^0(T^*X,\mathcal{C}h_{k,\varphi}))\rightarrow H^0(V,\mathcal{C}h_{k,\varphi}|_{V})$ is surjective and since $\mathcal{C}h_{k}|_{V}$ is $m$-regular, the natural morphism 
$$H^0(V,\mathcal{O}_V(1))\otimes H^0(V,\mathcal{C}h_{k}|_{V})\rightarrow H^0(V,\mathcal{C}h_{r+1}|_{V}),$$
is surjective as well. It follows that $\mathrm{res}_{r+1}$ corresponding to (\ref{eqn: Restriction map}) is surjective. The statement follows similarly.
\end{proof}

\subsection{Representability}
To conclude the proof of Theorem \ref{MainTheorem}, we construct a directed system defining an ind-scheme $\mathrm{Hilb}_{\D_X}^P(Z)=\varprojlim_k \mathrm{Hilb}_{\mathcal{D}_x}^{P,\leq q}(Z).$ It is filtered colimit of schemes of finite type, with each piece corresponding to data truncated at a finite jet level. This inverse system captures the behaviour of the entire formally integrable system as $q\rightarrow \infty.$

\begin{prop}
\label{prop: HilbRep}
The $\D$-Hilbert functor with fixed numerical polynomial $P\in \mathbb{Q}[t]$ that classifies formally integrable algebraic differential systems with fixed (regular) symbolic data is representable by an ind-scheme $\mathrm{Hilb}_{\D_X}(Z),$ equipped with a compatible $\D_X$-action. It is functorial for $S$-families of differential systems, for any non-characteristic fibration $f:X\rightarrow S$ i.e. the fibers $f^{-1}(s)$ are non-characteristic, for each $s\in S.$
\end{prop}
\begin{proof}
Consider the dimension filtration denoted $_{\leq d}\mathcal{H}ilb_{\D_X}(Z)\subset \mathcal{H}ilb_{\mathcal{D}_X}(Z)$ with $S$-points
$$\{\mathcal{I}_S|dim(Char(\mathcal{O}_{Z_s}/\mathcal{I}_s)\leq d, s\in S\}.$$
We consider the geometric points $s\in S.$ This is well-defined since $s\in S\mapsto dim(Char(\mathcal{B}_s))$ is upper semi-continuous.
The corresponding loci of characteristic dimension $d$, is the open strata given by the quotient pieces to the filtration,
\begin{equation}
\label{eqn: d-open loci}
\mathrm{Hilb}_{\D_X}^d(Z):=_{\leq d}\mathcal{H}ilb_{\D_X}(Z)/\hspace{1mm}_{\leq d-1}\mathcal{H}ilb_{\mathcal{D}_X}(Z).
\end{equation}
Set 
$$\mathcal{H}ilb_q^{\leq P}(Z):=\{\mathcal{O}_{Jet^q(E)}-\text{ideals } \hspace{1mm} I_q, \text{ algebraic and whose }$$
$$\text{differential closure }\overline{I}_q^{diff}\subset\mathcal{O}_Z \text{ has Hilbert polynomial }\leq P\}.$$
The ordering means $P_{I_q}(t)\leq P(t),$ for all integers $t.$
    The differential closure of $I_q\subset \mathcal{O}_{Jet^q(E)}$ spanned by equations $f_1,\ldots,f_r$ is spanned by $\{D^{\sigma}(f_A)|f_A\in I_q,A=1,\ldots,r |\sigma|\geq 0\}.$ We write $\big<\mathcal{D}_X\bullet I_q\big>\subset \mathcal{O}_Z$ for simplicity. It is the smallest left $\D_X$-ideal in $\mathcal{O}_Z$ such that
    $\overline{I_q}^{diff}\cap \mathcal{O}_{Jet^q(E)}\simeq I_q.$
This is just the colimit of all prolongations
$\mathrm{Pr}_r(I_q):=I_{q+r}.$ The sequence of prolongations corresponds to a filtered system of closed sub-schemes
$Y_q\subset Y_{q+1}\subset \cdots\subset Y^{\infty}.$
By formal integrability, there exists $r_0\geq 0$ such that for all $r\geq r_0,$ it holds that $\mathrm{Pr}_r(I_q)=I_{q+r}\simeq I_{q+r+1}\cap \mathcal{O}_{Jets^{q+r}(E)}.$
In particular, $I_{q+r_0}$ is closed under total derivatives and $\overline{I}_q^{diff}$ may be identified with 
$I_{q+r_0}\cdot \mathcal{O}_{Jets_X^{\infty}E}.$
There is a natural morphism 
$\mathcal{H}ilb_q^{\leq P}(Z)\hookrightarrow Quot_P(\mathcal{O}_{Jets^qE/X}),$ where the Quot-scheme is obtained as in Proposition \ref{prop: Douady}. This acts by $I_q\mapsto \big(\mathcal{O}_{Jets^q(E)}\twoheadrightarrow \mathcal{B}_q:=\mathcal{O}_{Jets^q(E)}/I_q\big).$ It is an isomorphism and by \cite{Gro3}, each Quot-functor is representable by scheme of finite-type. Thus 
$$\mathcal{H}ilb_{\D_X}^{\leq P}(Z)=\varinjlim_q\mathcal{H}ilb_q^{\leq P}(Z),$$
is a filtered colimit of schemes and therefore a finite-type ind-scheme. Since, prolongation imposes linear equations on the Quot scheme, it defines a closed subscheme of $\mathrm{Grass}_{\D}(Z)$, as in Proposition \ref{prop: Douady}. This corresponding limit identifies the desired $\D_X$-Hilbert scheme. It $\D$-structure is encoded in the differential closure of its points i.e. they correspond to $\D$-stable ideals.
\end{proof}


\subsection{Zariski tangent spaces}
\label{ssec: Zariski tangent spaces}
By Theorem \ref{MainTheorem}, we know the $\D$-Hilbert moduli functor is well-behaved in the $\D$-geometric setting. This suggests we can make sense of its Zariski tangent space. 
First, by extending results of \cite[Section 2]{BD},  natural differential complexes may be associated to $\D$-ideal sheaf sequences e.g. to points $[\mathcal{I}]$ of the $\D$-Hilbert scheme. Indeed, for such a $\D$-ideal, we have
 $$\ldots\rightarrow \Omega_{\mathcal{B}}^{(-2)}\rightarrow\mathcal{I}/\mathcal{I}^2\rightarrow \Omega_{\mathcal{A}}^1\otimes\mathcal{B}\rightarrow \Omega_{\mathcal{B}}^1\rightarrow 0.$$
 Let $\EQ\hookrightarrow Z$ be the corresponding embedding with $Z$ ambient $\D$-smooth $\D$-scheme.
The universal $\D$-linear de Rham differential is denoted $d_Z^v:\mathcal{O}_Z\rightarrow \Omega_Z^1,$ and consider the composition,
$$d_Z^v|_{\mathcal{I}}:\mathcal{I}\hookrightarrow \mathcal{O}_Z\rightarrow \Omega_Z^1,$$ 
as a morphism of $\mathcal{O}_Z[\mathcal{D}_X]$-modules. Since
$\Omega_{\mathcal{Y}}^1\leftarrow i_{\EQ}^*\Omega_{Z}^1\leftarrow \mathcal{I}/\mathcal{I}^2,$
we get an $\mathcal{O}_{\EQ}[\mathcal{D}_X]$-linear morphisms 
$d_{\EQ/Z}:\mathcal{I}/\mathcal{I}^2\rightarrow i_{\EQ}^*\Omega_{Z}^1,$ such that
$\mathrm{coker}(d_{\EQ/Z}^v)\simeq \Omega_{\EQ}^1.$
One may set
\begin{equation}
\label{eqn: Truncated Cotangent}
\mathbb{L}_{\EQ}^{\bullet}:=\mathcal{I}/\mathcal{I}^2\xrightarrow{d_{\EQ/}^v}i_{\EQ}^*\Omega_{Z}^1.
\end{equation}
The object (\ref{eqn: Truncated Cotangent}) is the \emph{truncated} cotangent complex. It is concentrated in degrees $[-1,0].$ 
\begin{rmk}
Approximating cotangent complexes via perfect complexes in a suitable derived category serves the basis of a perfect-obstruction theory for PDEs defined by $\D$-ideal sheaves. This is beyond the scope of the current work, and is only mentioned for completeness.\end{rmk}
We now sketch how to impose further geometric constraints on the $\D$-ideals $[\I]\in\mathcal{H}ilb_{\D}^P(Z)$ whose associated Spencer cohomologies as well as cohomologies of $\D$-module solution functors (e.g. de Rham cohomologies), are finite-dimensional. 

\subsubsection{Microlocal stratifications}
We restrict attention throughout to non-singular algebraic PDEs, which we interpret more precisely by imposing microlocal conditions on the characteristic varieties of the corresponding $\mathcal{D}_X$-ideal sheaves. Constraining the geometry of these varieties enables control over singularities and induces natural stratifications on the $\mathcal{D}_X$-Hilbert stack.

While a full treatment requires the $\infty$-categorical functoriality of the $\mathcal{D}$-cotangent complex and is deferred to the sequel \cite{KSh2}, we outline here the key microlocal input. In particular, this allows us to isolate loci in the $\mathcal{D}_X$-Hilbert moduli space corresponding to elliptic equations, using the geometric criterion for ellipticity via characteristic varieties as developed in \cite{KSY}.

Let $U_{\alpha}\subset \mathcal{C}har(\mathcal{I})$ be an irreducible component of the characteristic variety of $\mathcal{I}$, and put
$$mult_{U_{\alpha}}(\mathcal{C}h):=\sum_{U_{\alpha}\subset \mathcal{C}har(\mathcal{I})}mult_{S}(\mathcal{C}h)[U_{\alpha}].$$
In families, let $\Lambda\subset T^*(X/S)$. Assume it is involutive, but note the fibers are not necessarily involutive since $\Lambda_s:=\Lambda\cap T^*(X/S)_s\subset T^*(X_s),$
for $s\in S,$ is not always a proper intersection. There exists a relative analog $\mathcal{C}har^{rel}(\I)$, defined as in Subsect. \ref{sssec: D-Geometric Microcharacteristic Varieties}, by adapting constructions of \cite{SS,SS2}.

\begin{prop}
Assume $\Lambda$ is smooth over $S$. Then $\Lambda_s\subset T^*X_s$ is either empty or involutive.
\end{prop}
\begin{proof}
Let $Char^{rel}(\mathcal{I})\cap W$ be smooth over $U\subseteq S$ with $U$ open and $W$ an open neighbourhood of a point in $Char^{re}.$ By relative smoothness, 
$(Char^{rel}(\mathcal{I})\cap W)\cap T^*X_s$
is involutive in $T^*X_s$ for all $s\in S$ implying $dim\geq dimX-dimS.$ Then, one may use upper semi-continuity of fibers of $Char^{rel}.$
\end{proof}

%\begin{rmk}
%Consider subsection \ref{ssec: Differential algebra quotients}, with an algebraic action of a connected pseudogroup
%$G$ on an irreducible algebraic differential equation $Z^{\infty}=\{Z^k\subset J_X^kE\},$ transitive along $X.$ Then it is possible to show there exists a subset $\Sigma\subset Z^{\infty}$ of infinite-codimension and a co-filtered stratification $Z^{\infty}\backslash \Sigma\simeq \bigcup_{\alpha}Z_{\alpha},$ and a Poincar\'e function $P_{\alpha}(z)=P(\theta_{\infty};z)=\sum_{k=0}^{\infty}\big(codim(G\cdot \theta_k\subset Z^k)-codim(G\cdot \theta_{k-1}\subset Z^{k-1})z^k,$ for $\theta_k\in Z_{\alpha}^k,$ depending only on $\alpha$, for each $\theta_{\infty}=\{\theta_k\}_{k=0}^{\infty}\in Z_x^{\infty},x=\theta_0\in X,$ which is a rational function.
%\end{rmk}
Let $\Lambda \subset T^*X,$ be a closed conic subset and define $\mathcal{H}ilb_{\D_X}^{\Lambda}(Z),$ which parameterizes $\D$-ideal sheaves $\mathcal{I}$, with 
$Char_{\D}(\mathcal{I})\subset \Lambda.$
This defines a closed subfunctor. 
\begin{defn}
\label{defn: Non-singular Hilb}
\normalfont
Let $\Lambda\subset T^*X$ be a closed coisotropic conic subset, such that $\pi(\Lambda)\subset T^*X$ is smooth, with $\pi:T^*X\rightarrow X.$ 
The $\D$-Hilbert functor of $\D$-ideals $\mathcal{I}$ with $\D$-Hilbert polynomial $P\in \mathbb{Q}[t],$ which are \emph{non-singular relative to $\Lambda$}, is $\mathcal{H}ilb_{\mathcal{D}_X}^{P,\Lambda}(Z):=\mathcal{H}ilb_{\mathcal{D}_X}^{P}(Z)\cap \mathcal{H}ilb_{\mathcal{D}_X}^{\Lambda}(Z).$
\end{defn}
Consider (\ref{eqn: Truncated Cotangent}). In \cite{KSY}, the derived $\D$-characteristic variety was defined as the cohomological support of the tangent complex, denoted by $\mathbf{Char}_{\D}(\mathcal{I}).$ 


\begin{prop}
Consider a $\D$-ideal $\mathcal{I}$ and assume the cotangent complex of the associated $\D$-subscheme is of the form (\ref{eqn: Truncated Cotangent}). Let $\mathcal{C}\mathrm{har}_{\D}(\I)$ be the characteristic variety, given by Proposition \ref{prop: Char inclusions}. Then, 
$\mathcal{C}\mathrm{har}_{\D}(\I)\subseteq \mathbf{Char}_{\D}(\mathcal{I}).$
\end{prop}
\begin{proof}
Clearly from (\ref{eqn: Truncated Cotangent}) there exists a
canonical map $\mathbb{L}_{\EQ}^{\bullet}\rightarrow \mathcal{H}_{\mathcal{D}}^0(\mathbb{L}_{\EQ}^{\bullet})\simeq \Omega_{\EQ}^1.$ The result is immediate since
$$\mathbf{Char}_{\D}(\mathcal{I})\simeq \mathrm{supp}\big(\mathcal{H}_{\D}^0(\mathbb{L}_{\mathcal{Y}})\big)\cup \bigcup_{i\neq 0}\mathrm{supp}\big(\mathcal{H}_{\D}^i(\mathbb{L}_{\mathcal{Y}})\big).$$

\end{proof}
These results serve to allow microlocal control over singularities, while also providing a means to consider only certain classes of $\D$-ideals whose corresponding solution functors have finite-dimensional cohomologies. For more general non-linearities, one should work with $s$-microcharacteristics (see Reminder \ref{rem: s-microchars}) with appropriate modifications to Definition \ref{defn: Non-singular Hilb}.
Microlocal constraints can imply finite-dimensionality of deformation-obstruction spaces of the corresponding $\D$-modules given by the Zariski tangent sheaves, as we now compute in the second main result. 

\begin{thm}
    \label{MainTheorem2}
Consider Theorem \ref{MainTheorem}. The Zariski tangent space at a point $[\mathcal{I}]$ controlling first-order deformations of $\mathcal{I}$ as a $\D$-ideal, is given by
    $$T_{[\mathcal{I}]}\mathbf{Hilb}_{\D_X}(J_X^{\infty}E)\simeq Hom_{\D_X}(\mathcal{I},\mathcal{O}(J_X^{\infty}E)/\mathcal{I}).$$
The space of obstructed deformations at $[\mathcal{I}]$ is,
$$\mathcal{O}bs_{[\mathcal{I}]}=Ext_{\mathcal{O}(J_X^{\infty}E)/\mathcal{I}\otimes_{\mathcal{O}_X}\D_X}^1(\mathcal{I}/\mathcal{I}^2,\mathcal{O}(J_X^{\infty}E)/\mathcal{I}\otimes_{\mathcal{O}_X}\D_X),$$
which is naturally endowed with a good $\mathcal{O}(J_X^{\infty}E)[\D]$-filtration whose associated graded algebra is isomorphic to $\bigoplus_{q< \mathrm{Reg}_{\D}(\mathcal{I})}\mathcal{H}_{Sp}^{1,q}\big(\mathrm{gr}(\mathcal{I})\big).$
\end{thm}
\begin{proof}
Fixing $[\mathcal{I}]$, viewed geometrically as a closed $\D$-subscheme $\mathrm{Spec}_{\D}(\A/\mathcal{I})\hookrightarrow \mathrm{Spec}_{\D}(\A),$ consider the defining exact sequence $\IAB$, with $\mathcal{B}:=\A/\mathcal{I}.$ Consider the conormal sequence in $\mathcal{A}/\mathcal{I}[\D]$-modules (essentially defining (\ref{eqn: Truncated Cotangent})):
\begin{equation}
    \label{eqn: ConormalD}
\mathcal{I}/\mathcal{I}^2\rightarrow \Omega_{\mathcal{A}}^1\otimes_{\mathcal{A}}\mathcal{A}/\mathcal{I}\rightarrow \Omega_{\mathcal{A}/\mathcal{I}}^1\rightarrow 0,
\end{equation}
where $\Omega_{\mathcal{A}}^1=\mathcal{H}om_{\A[\mathcal{D}]}(\Theta_{\mathcal{A}},\mathcal{A}\otimes_{\mathcal{O}_X}\D_X)$ is a left $\mathcal{A}[\mathcal{D}]$-module and $\Theta_{\A}=\mathcal{D}er_{\D}(\mathcal{A},\mathcal{A})$ is naturally a right-module.
Apply the functor $\mathcal{H}om_{\mathcal{A}/\mathcal{I}\otimes\D_X}(-,\mathcal{A}/\mathcal{I}\otimes_{\mathcal{O}_X}\D_X)$ to (\ref{eqn: ConormalD}) gives
\begin{eqnarray}
\label{eqn: LES Conormal}
    0\rightarrow \mathcal{H}om_{\mathcal{A}/\mathcal{I}\otimes\D_X}(\Omega_{\mathcal{A}/\mathcal{I}}^1,\mathcal{A}/\mathcal{I}[\D])&\rightarrow& \mathcal{H}om_{\mathcal{A}/\mathcal{I}\otimes\D_X}(\Omega_{\mathcal{A}}^1\otimes_{\mathcal{A}}\mathcal{A}/\mathcal{I},\mathcal{A}/\mathcal{I}[\D]) \nonumber
    \\  &\rightarrow&\mathcal{H}om_{\mathcal{A}/\mathcal{I}\otimes\D_X}(\mathcal{I}/\mathcal{I}^2,\mathcal{A}/\mathcal{I}[\D])\rightarrow\cdots
    \end{eqnarray}
The vector fields on $\mathrm{Spec}_{\D}(\mathcal{A}/\mathcal{I}),$ are by definition $\mathcal{H}om_{\mathcal{A}/\mathcal{I}\otimes\D_X}(\Omega_{\mathcal{A}/\mathcal{I}}^1,\mathcal{A}/\mathcal{I}[\D])$, since $\mathcal{A}$ is smooth (as a jet $\D$-algebra), then $\Omega_{\A}^1$ is a projective $\A[\mathcal{D}]$-module and consequently,
$\mathcal{H}om_{\mathcal{A}/\mathcal{I}\otimes\D_X}(\Omega_{\mathcal{A}}^1\otimes_{\mathcal{A}}\mathcal{A}/\mathcal{I},\mathcal{A}/\mathcal{I}[\D])\simeq \Theta_{\A}\otimes_{\mathcal{A}}\mathcal{A}/\mathcal{I}$ by adjunction.

The long-exact sequence (\ref{eqn: LES Conormal}) is thus written,
\begin{eqnarray*}
0\rightarrow \Theta_{\mathcal{A}/\mathcal{I}}\rightarrow \Theta_{\mathcal{A}}\otimes_{\mathcal{A}}\mathcal{A}/\mathcal{I}&\rightarrow& \mathcal{H}om_{\mathcal{A}/\mathcal{I}\otimes\D_X}(\mathcal{I}/\mathcal{I}^2,\mathcal{A}/\mathcal{I}[\D])\rightarrow 
\\
&\rightarrow& Ext_{\mathcal{A}/\mathcal{I}[\D]}^1(\Omega_{\mathcal{A}/\mathcal{I}}^1,\mathcal{A}/\mathcal{I}[\D])\rightarrow \cdots.
\end{eqnarray*}
Then the second map sends a vector field $v$ to the deformation $\mathcal{I}_v\mapsto \mathcal{I}+\epsilon\cdot v(\mathcal{I}),$ of the ideal. Namely, first-order deformations of $\mathcal{I}$ over $\mathbb{C}[\epsilon]/(\epsilon)^2,$ correspond to elements of an associated ideal $\mathcal{I}_{\epsilon}\subset \mathcal{O}(J_X^{\infty}E)[\epsilon]/(\epsilon^2),$ such that $\mathcal{I}_{\epsilon}\otimes_{\mathbb{C}[\epsilon]}\mathbb{C}\simeq \mathcal{I}.$ Explicitly, such deformations are $\D$-homomorphisms $\phi:\mathcal{I}\rightarrow \mathcal{A}/\mathcal{I}$ so $\mathcal{I}_{\epsilon}\simeq \{F+\epsilon\cdot G|F\in \mathcal{I},G=\phi(F) \text{mod }\mathcal{I}\}.$

Its kernel consists of trivial deformations, therefore the $Ext^1$-group contains the obstructions to lifting a first-order deformation i.e. tangent vector, corresponding to an element of $\mathcal{H}om_{\mathcal{A}/\mathcal{I}\otimes\D_X}(\mathcal{I}/\mathcal{I}^2,\mathcal{A}/\mathcal{I}[\D]).$ Thus, we conclude that for $[\mathcal{I}]\in \mathcal{H}ilb_{\D}^P(\mathcal{A}),$
$$T_{[\mathcal{I}]}\mathcal{H}ilb_{\D}^P(\A)\simeq \mathcal{H}om_{\mathcal{A}/\mathcal{I}\otimes\D_X}(\mathcal{I}/\mathcal{I}^2,\mathcal{A}/\mathcal{I}[\D]).$$
Sequence (\ref{eqn: ConormalD}) is compatible with the filtrations, since $\mathcal{I}/\mathcal{I}^2$ inherits a filtration with components $\bigoplus_{k\geq 0}F^k\mathcal{I}+\mathcal{I}^2/F^{k+1}\mathcal{I}+\mathcal{I}^2,$ and then noting that for each $k\geq 0,$ the $k$-th geometric symbol is isomorphic to $F^k\mathcal{I}/F^{k+1}\mathcal{I}+F^k\mathcal{I}\cap F^1\mathcal{A}\cdot F^{k-1}\mathcal{A}.$ 
Immediately from the long-exact sequence, the statement concerning the space of obstructions is clear. We now establish its relation with the Spencer cohomologies and Spencer regularity of the point $[\mathcal{I}].$
Namely, since $F^k(\mathcal{I}/\mathcal{I}^2)=(F^k\mathcal{I}+\mathcal{I}^2)/\mathcal{I}^2,$ there exists a filtration 
$$F^{-q}Ext_{\mathcal{A}/\mathcal{I}[\D_X]}^1(\mathcal{I}/\mathcal{I}^2,\mathcal{A}/\mathcal{I}[\D]):=\{\psi|\psi(F^{\ell}(\mathcal{I}/\mathcal{I}^2)\subset F^{\ell-q}(\mathcal{A}/\mathcal{I}[\D_X]),\ell\geq 0\}.$$
An element $\psi\in F^{-q}\mathcal{O}bs_{[\mathcal{I}]}$ restricts as $\psi|_{F^q}:F^q(\mathcal{I}/\mathcal{I}^2)\rightarrow \mathcal{A}/\mathcal{I}[\D_X].$
Consider 
$$\mathrm{gr}_{-q}\mathcal{O}bs_{[\mathcal{I}]}:=F^{-q}Ext_{\mathcal{A}/\mathcal{I}[\D_X]}^1(\mathcal{I}/\mathcal{I}^2,\mathcal{A}/\mathcal{I}[\D])/F^{-q-1}Ext_{\mathcal{A}/\mathcal{I}[\D_X]}^1(\mathcal{I}/\mathcal{I}^2,\mathcal{A}/\mathcal{I}[\D]).$$
Then, by restriction, $\psi\in F_{-q}$ vanishes on $F^{q+1}(\mathcal{I}/\mathcal{I}^2)$ as $\psi \notin F_{-q-1}.$ Thus, descends to the quotient, denoted by
$\psi':F^q(\mathcal{I}/\mathcal{I}^2)/F^{q+1}(\mathcal{I}/\mathcal{I}^2)\rightarrow \mathcal{A}/\mathcal{I}[\D].$
Note the isomorphism
$F^q(\mathcal{I}/\mathcal{I}^2)/F^{q+1}(\mathcal{I}/\mathcal{I}^2)\simeq F^q\mathcal{I}/F^{q+1}\mathcal{I}+F^q\mathcal{I}\cdot F^1\A\simeq \mathrm{gr}_q(\mathcal{I}),$
of $\mathcal{O}_X$-coherent submodules of $\mathrm{gr}^q(\A)\simeq Sym^q(T^*X)\otimes E^*,$ as in (\ref{gr(I)}). 
Using a spectral sequence argument and the Spencer $\delta$-complex resolution for $\mathcal{I}/\mathcal{I}^2,$ one has 
$$Ext_{\A/\mathcal{I}\otimes\D_X}^i(\mathcal{I}/\mathcal{I}^2,\mathcal{A}/\mathcal{I}[\D])\simeq H^i\big(\mathcal{H}om_{\mathcal{A}/\mathcal{I}[\D]}(Sp(\mathcal{I}),\mathcal{A}/\mathcal{I})\big).$$
Thus, there is an isomorphism of $\mathcal{O}_X$-modules,
$\mathrm{gr}_{-q}\mathcal{O}bs_{[\mathcal{I}]}\simeq \mathcal{H}_{Sp}^{1,q}(\mathrm{gr}(\mathcal{I})), g\geq 0.$
By Proposition \ref{prop: Approximations}, the associated graded is isomorphic to a subquotient, therefore upon taking a direct sum, due to Spencer regularity bound for $\mathcal{I},$ there is an isomorphism 
$$\bigoplus_{q<\mathrm{Reg}_{\D}(\mathcal{I})}\mathrm{gr}_{q}Ext^1\simeq \bigoplus_{q<\mathrm{Reg}(\mathcal{I})}\mathcal{H}_{\mathrm{Sp}}^{1,q}(\mathrm{gr}(\mathcal{I})).$$

\end{proof}
The perfectness and finite-dimensionality (e.g. of Spencer cohomologies) is tied to properties of the differential operator defining the $\D$-ideal \emph{c.f.} (\ref{SpRmk}). We use microlocal stratifications of Definition \ref{defn: Non-singular Hilb}, to isolate those PDEs whose sheaf of solutions, e.g $R\mathcal{H}om_{\D_X},$ has finite-dimensional cohomologies.
In a general setting, consider a morphism $f:Z\rightarrow X$ of varieties and suppose $\Sigma_Z\subset Z,\Sigma_X\subset X$ are closed sub-manifolds. Denote $f_{\Sigma}$ the restriction and assume it is a closed embedding. There is a corresponding diagram,
\[
\begin{tikzcd}
    T^*Z & \arrow[l,"j_d"] Z\times_XT^*X\arrow[d] \arrow[r,"j_{\pi}"] & T^*X
\\
T_{\Sigma_Z}^*Z\arrow[u] \arrow[d,"\pi_{\Sigma_Z}"] & \arrow[l,"j_d"] \Sigma_Z\times_{\Sigma_X}T_{\Sigma_X}^*X\arrow[d,"\pi"] \arrow[r,"j_{\pi}"] & T_{\Sigma_X}^*X\arrow[u]\arrow[d,"\pi_{\Sigma_X}"]
\\
\Sigma_Z \arrow[r,"id"] & \Sigma_X \arrow[r,"j"] & \Sigma_X
\end{tikzcd}
\]

As a special case, take $(\Sigma\subset X),$ and consider a $\mathcal{D}_X$-algebra $\mathcal{B},$ defined by $[\mathcal{I}]\in \mathcal{H}ilb_{\D}^P(Z).$

\begin{defn}
\label{eqn: Elliptic Moduli}
\normalfont
The $\D$-Hilbert functor of $\D$-ideals \emph{elliptic with respect to} $\Sigma$, is defined by $\mathcal{H}ilb_{\D}^{P,\Sigma \times_X T_X^*X}(Z).$
\end{defn}
Definition \ref{eqn: Elliptic Moduli} generalizes the notion of ellipticity given in \cite[Sect. 5.3.1]{KSY}. Indeed, it states that (by pull-back along solutions), 
$$\mathbf{Char}_{\D}(\mathcal{I})\cap T_{\Sigma}^*X\subset \Sigma\times_X T_X^*X.$$ In particular, if $\Sigma$ is a real manifold $M$ and $X$ a complexification of $M$, then Definition \ref{eqn: Elliptic Moduli} recovers the usual notion of ellipticity: the linearized $\mathcal{D}_X$-module is elliptic i.e. $Char_{\mathcal{D},\varphi}(\mathcal{Y})\cap T_M^*X\subset M\times_X T_X^*X.$

\section{Spencer-stability is Gieseker stability}
In this final section we given an application of the ideas developed in this paper pertaining to a classification problem of PDE-theoretic nature. We follow \cite{Do,UY} (motivated by the examples given in Subsect. \ref{ssec: Overview and statement of results}), by introducing Spencer polystability, discuss a conjectural correspondence for moduli of polystable differential ideals. We prove the conjecture in a particular case.

\subsection{Correspondences for moduli of Spencer-stable sheaves}
Let $X$ be a compact Kähler manifold, $E$ a holomorphic vector bundle and $\mathcal{I}\subset \mathcal{O}(J_X^{\infty}E)$ a formally integrable, involutive $\D_X$-ideal sheaf encoding a (non-linear) PDE system. We propose to investigate the correspondence between Spencer stability of $\mathcal{I}$ and existence of a canonical (possibly singular) solutions to the PDE defined by $\mathcal{I}$.

In Theorem \ref{thm: DSUY implies DUY} we prove this correspondence in the case when $\mathcal{I}$ is the $\D$-ideal associated to the equation of flat-connections (constructed in the proof, given in Subsect. \ref{sssec: Proof of DSUY}). 
\begin{defn}
    \label{defn: Sp-polystable}
    \normalfont
    A $\D$-ideal $\mathcal{I}\subset \mathcal{O}(J_X^{\infty}E)$ is \emph{Spencer-polystable}
if we may write
$\mathcal{I}\simeq\mathcal{I}_1\oplus \cdots\oplus \mathcal{I}_k,$
with each $\mathcal{I}_i$ Spencer-stable with $\mu_{Sp}(\mathcal{I}_i)=\mu_{Sp}(\mathcal{I}).$
\end{defn}
The conjectural correspondence suggests to search for a canonical solution $\varphi\in H^0(X,\mathcal{A}/\mathcal{I})$ such that its graph $\Gamma_{\varphi}\subset J_X^{\infty}(E)$ minimizes a PDE-theoretic energy functional.
To this end, fix $\varphi\in \mathrm{Sol}_{\D}(\mathcal{I}),$ and a cycle in singular homology $H_{*c}(X)$. Then, there are natural assignments,
$H_{*,c}(X)\times \mathcal{H}^{*}(Z)\rightarrow \Omega_H^p,(K,\omega)\mapsto \lambda_{K,\omega},$
where $\lambda_{K,\omega}$ is defined for each open subset $U$ of $X$ by its values on $U$-parameterized sections $s_U\in \Gamma_K(X,E)(U)\subseteq Hom(X\times U,E),$ with support in compact subsets $K$, by 
$\lambda_{K,\omega}(s_U):=\int_{\sigma}(j_{\infty}(\varphi(x,u))^*\omega\in \Omega_U^p.$ Here $H$ is an appropriate sub-space of the space of solutions, via Proposition \ref{prop: Sol}. Integrating singular solutions this way, one may try to define
\emph{Spencer-type energy},
$$\mathcal{E}(\varphi,K):=\int |\!|\overline{\mathcal{H}}_{Sp}^{*}(\varphi)|\!|^2dVol,$$
where the $L^2$-norm on the right comes from a certain non-holomorphic Spencer defect e.g defined by a sub-complex of the Spencer complex, induced by the usual splitting, $T_X\otimes\mathbb{C}=T_X^{1,0}\oplus T_X^{0,1}$ with $\overline{T}_X^{1,0}=T_X^{0,1},$ whose cohomologies detect deformations of analytic solutions $\overline{\mathcal{H}}^{1,0}.$

That is, if $\varphi$ is not a holomorphic solution section, its deviation from being holomorphic is measured by some class
$\overline{\partial}_{Sp}(\varphi)$ in the cohomology of a natural sub-complex of the Spencer complex. If this class vanishes, $\varphi$ is a holomorphic. We interpret the class $[\overline{\partial}_{Sp}(\varphi)]$ as the (analytic) obstruction to solving the PDE defining $\mathcal{I}$ at $\varphi.$
\\

\noindent\textbf{Conjecture.}\emph{ Let $(X,\omega)$ be a compact Kähler manifold, $E$ a holomorphic vector bundle and $\mathcal{I}\subset \mathcal{O}(J_X^{\infty}E)$ a formally integrable, $\D$-involutive $\D$-ideal sheaf. Then, $\mathcal{I}$ is Spencer-polystable if and only if there exists a (possibly singular) solution $\varphi\in H^0(X,\mathcal{B})$ minimizing a Spencer-type functional e.g. $\mathcal{E}(\varphi).$}
\\

In the remainder of this subsection we prove a result which provides evidence for this conjecture. 


\subsection{The equation of flat-connections}
Consider variables $(x_1,\ldots,x_n)\in X$ with $dim_X=n$ and $u=(u^1,\ldots,u^m)(x)$ in a rank $m$ bundle $E$ (fiber-wise coordinates). Fix a collection of $nm$-functions $g_i^{\alpha}=g_i^{\alpha}(x_1,\ldots,x_n,u^1,\ldots,u^m),$ which determine a connection $\nabla$ e.g. by $\nabla(\partial_i)=\partial_i+\sum_{\alpha=1}^mg_i^{\alpha}\partial_{u^{\alpha}},i=1,\ldots,n.$

Consider the system of $m n(n-1)/2$ non-linear PDEs in $m n$-unknowns,
\begin{equation}
    \label{eqn: Flat-connection equation}
    \frac{\partial g_j^{\alpha}}{\partial x_j}+\sum_{\beta=1}^mg_i^{\beta}\frac{\partial g_j^{\alpha}}{\partial u^{\beta}}=\frac{\partial g_i^{\alpha}}{\partial x_j}+\sum_{\beta=1}^mg_j^{\beta}\frac{\partial g_i^{\alpha}}{\partial u^{\beta}},\hspace{1mm} 1\leq i<j\leq n,\hspace{1mm}\alpha=1,\ldots,m.
\end{equation}

System (\ref{eqn: Flat-connection equation}) is the coordinate description expressing flatness of $\nabla$. It defines a $\D_X$-ideal, denoted $\mathcal{I}_{\nabla}.$ It may be given an invariant meaning using the language of $\D$-geometry in (\ref{eqn: Flat connection functions}) below, so that by Proposition \ref{prop: Sol}, any solution gives a flat connection $\nabla$. 
We verify the conjecture by showing that if $\mathcal{I}_{\nabla}$ is Spencer-polystable, then there exists a Hermitian-Yang-Mills metric on $E$ and conversely, if $E$ admits a HYM metric $h$, then $\mathcal{I}_{\nabla}$ is Spencer-polystable. 

The proof implicitly invokes Simpson's non-abelian Hodge theory and the classical DUY-correspondence. In particular, the key observation is that the Spencer complex for $\mathcal{I}_{\nabla}$ encodes the full deformation theory of $\nabla$ (see e.g. \cite{KP}) while symbol stability i.e. Spencer stability, matches the stability condition of Higgs bundles (Proposition \ref{prop: Stability compare}). 

\begin{thm}
\label{thm: DSUY implies DUY}
Let $(X,\omega)$ be a compact Kähler manifold, $(E,\nabla)$ a holomorphic vector bundle with flat connection i.e. a flat bundle. Consider the $\D$-ideal sheaf sequence 
$$\mathcal{I}_{\nabla}:=\{F_{\nabla}\}\hookrightarrow \mathcal{O}(J_E^{\infty}J_X^1E)\rightarrow \mathcal{B}_{\nabla},$$
where $\mathcal{B}_{\nabla}$ is the $\D$-algebra of functions associated with the equation of flat-connections.
Then, the ideal $\mathcal{I}_{\nabla}$ is Spencer-polystable if and only if the holomorphic bundle $(E,\nabla)$ admits a Hermitian-Yang-Mills metric.
\end{thm}

%In other words, Theorem \ref{thm: DSUY implies DUY} states that DSUY-correspondence implies classical DUY.
\subsubsection{Proof of Theorem \ref{thm: DSUY implies DUY}}
\label{sssec: Proof of DSUY}
We first construct the $\D$-scheme of flat-connections and describe the associated symbolic structure and its cohomological properties under Spencer-stability assumptions.
\begin{proof}
Given $(E,\nabla)$, the curvature of the connection $F_{\nabla}$ defines a differentially generated, formally-integrable $\D_X$-ideal sheaf $\mathcal{I}_{\nabla}.$ It is canonically obtained from (\ref{eqn: Flat-connection equation}) via prolongation.


Assume that the coefficients $\{\nabla_i^{\alpha}\}$ determining $\nabla$ (there are $dim(X)\cdot rank(E)$-many of them) are expressed generically via
\begin{equation}
    \label{eqn: Flat connection functions}
\{F_k\equiv F_k(x,u,\nabla_i^{\alpha})|i=1,\ldots,n,\alpha=1,\ldots,m, k=1,\ldots,r\}.
\end{equation}
We associate with (\ref{eqn: Flat connection functions})
a $\D$-scheme $\EQ_{F},$ with the property that points of
$\mathrm{Sol}_{\mathcal{D}_X}(\EQ_F)$ are connections in $E,$ using Proposition \ref{prop: Sol}. We sketch the proof. 
To this end, let $[\![-,-]\!]$ be the Fr\"olicher-Nijenhuis bracket on vector valued derivations, and consider the finite-rank vector bundle $J_X^1(E),$ viewed as a bundle over $E.$ Consider $J_E^1\big(J_X^1(E)\big).$ Via the well-known one-to-one correspondence between connection $1$-forms $Der(E,\Omega_E^1)$ satisfying $[\![U,U]\!]=0$ and flat-connections in $E,$ sections of $J_X^1(E)$ are first-order differential operators with scalar-type symbol. Let  
$\theta_1:=[\nabla]_{\theta}^1$ denote an element of $J_E^1(J_X^1(E)).$
This defines a function 
$$F(U):=[\![U,U]\!]:\mathcal{O}(J_{E}^1J_X^1(E))\rightarrow \mathbb{C},$$
via evaluation.
In particular, when $U=U_{\nabla}$ then 
$F(U_{\nabla})=0,$
is the equation of flat connections $\nabla$ in $E\rightarrow X.$
This is given a coordinate independent invariant meaning by setting
\begin{equation}
\label{eqn: FlatConns}
\EQ_{E}^{flat}:=\{\theta_1\in J_E^1(J_{X}^1E)| F(U)(\theta_1)=0\}.
\end{equation}
There is an induced action of differential operators $\partial_{x_i}$ and $\partial_{u^{\alpha}}$ on this bundle. In other words, the natural $\D$-action prolongs as a differentially stable system with $\D$-ideal $\mathcal{I}_{\nabla}.$
\begin{defn}
\normalfont
The \emph{$\D$-scheme of flat-connections,} is the closed $\D$-subscheme associated with the infinite-prolongation of (\ref{eqn: FlatConns}), given by
\begin{equation}
\label{eqn: D-Scheme of Flat Connections}
Z_{(E,\nabla)}:=\mathrm{Spec}_{\mathcal{D}}(\mathcal{O}_{\EQ_E^{flat,(\infty)}})\hookrightarrow J_X^{\infty}\big(J_X^1E\big).
\end{equation}
\end{defn}
By Definition \ref{defn: Algebraic solution}, an algebraic section 
$s:E\rightarrow J_X^1E$ 
is a flat-connection (solution) in $E$ if and only if $s(E)\subset \EQ_E^{flat}.$
This equation of flat connections is imposed in the bundle 
$J_E^1(J_X^1(E)).$ By Proposition \ref{prop: Sol}, we obtain the following.
\begin{prop}
There is an isomorphism of $\D$-spaces of sections
$\mathrm{Sol}_{E}(\EQ_E^{flat,\infty})\simeq \mathrm{Sect}(E,J_X^1E)\times_{\mathrm{Sect}(E,J_E^{\infty}J_X^1E)}\mathrm{Sect}(E,\EQ_{E}^{flat,\infty}).$
\end{prop}
This result is intuitively clear as solutions to $J_E^{\infty}(J_X^1E)$ (the `empty' equation) are sections of $J_X^1E$, which is dual to the Atiyah algebroid of $E,$ thus are connections in the bundle $E$. Then, solutions to the sub-$\D$-scheme of flat connections picks out the sub-space of sections of $J_X^1E,$ thus connections in $E$, which are additionally flat.

Since the $\D$-scheme of flat connections (\ref{eqn: D-Scheme of Flat Connections}) arises from a \emph{non-linear} system (\ref{eqn: Flat-connection equation}), we linearize and use the Spencer complexes in the $\D_{\A}$-module setting.

Namely, linearizing at a solution $\nabla$, we obtain the operator of (universal) linearization,
$$L_{\nabla}:\Omega^1(X;EndE)\rightarrow \Omega^2(X;EndE),\hspace{1mm}\eta\mapsto d_{\nabla}\eta.$$
Seen in another way, the symbolic modules $\mathrm{gr}(\mathcal{I}_{\nabla})$ associated with this $\D$-ideal correspond to the compatibility complex for linearized flatness equation $d_{\nabla}\phi=0,$ for $\phi\in \Omega^1(EndE).$ Looking at $\mathrm{gr}^*(\I_{\nabla})$, we have a compatibility complex for $L_{\nabla}$ isomorphic to
$$\mathcal{S}p(\mathcal{I}_{\nabla})\simeq 0\rightarrow End(E)\rightarrow \Omega^1(End(E))\rightarrow \Omega^2(End(E))\rightarrow \cdots \Omega^{n}(X;End(E))\rightarrow 0.$$
Then the Spencer slope (\ref{eqn: Spencer slope}) is 
$$\mu_{Sp}(\mathcal{I}_{\nabla}):=deg\big(H^0(\mathcal{S}p(\mathcal{I}_{\nabla})\big)/\mathrm{rank}(\mathcal{I}_{\nabla}).$$
Note
$H^0(\mathcal{S}p(\mathcal{I}_{\nabla}))\simeq ker(d_{\nabla}:End(E)\rightarrow \Omega^1EndE),$
and $\mathrm{rank}(\mathcal{I}_{\nabla})=rank(EndE)=rank(E)^2.$ 

Using non-abelian Hodge theory and the classical DUY-correspondence, we compare the stability conditions.
\begin{prop}
\label{prop: Stability compare}
    Spencer stability of $\mathcal{I}_{\nabla}$ is equivalent to Gieseker polystability of the Higgs bundle $(E,\theta),$ where $\theta$ is induced via the harmonic metric from $\nabla.$ 
\end{prop}
\begin{proof}
    Suppose $\mathcal{J}\subset \mathcal{I}$ is a non-zero sub $\D$-ideal. Assume it corresponds to a sub-bundle $F\subset E$ which is moreover $\nabla$-invariant i.e. $\nabla^F:=\nabla|_{F}$ is a sub-connection. Sub-connections and sub-$\D$-ideals are in correspondence this way, so we write $\mathcal{J}_{\nabla_F}.$ Consider $\mathrm{gr}_*(\mathcal{J}_{\nabla_F}),$ and reduced $\D$-Hilbert polynomials, i.e.
$$\frac{P_{\D}(\mathcal{J}_{\nabla_F},n)}{\mathrm{rank}(\mathcal{J}_{\nabla_F})}=\frac{deg H_{Sp}^0(\mathcal{S}p(\mathcal{J}_{\nabla_F}))}{rank(F)^2}=\frac{deg(ker(d_{\nabla_F}^0))}{rank(F)^2},$$
since $\mathrm{rank}(\mathcal{J}_{\nabla_F})=rank(F)^2.$ One may also verify $deg(ker_{\nabla})$ is determined by $rank(E)$ and $deg(E)$ by Hirzebruch-Riemann-Roch theorem.
Spencer-stability implies 
$$deg(ker(d_{\nabla_F}))/rank(F)^2\leq deg(ker(d_{\nabla}))/rank(E)^2,$$
which for stable sheaves is trivially satisfied, but for $\nabla$-invariant sub-bundles reduces to 
$\mu(F)\leq \mu(E),\mu(F)=deg(F)/rank(F),$ as usual.

Now we prove that $\mathcal{I}_{\nabla}$ is Spencer polystable if and only if there exists a harmonic metric $h$ solving $F_{\nabla}+[\theta,\theta^*]=0.$ 
To this end, assume $\mathcal{I}_{\nabla}$ is Spencer polystable. Then there exists a harmonic metric since $(E,\nabla)$ decomposes into stable summands of equal slope. 

This follows since jet-functors are additive, so $J_X^{\infty}(E)\simeq \bigoplus_i J_X^{\infty}(E_i),$ and under this decomposition the direct sum connection obviously block-diagonally. Moreover any $s\in \Gamma(X,E)$ maybe written $s=\sum_i s_i, s_i\in \Gamma(X,E_i).$ Then, their Taylor expansions $j_{\infty}(s)$ are of the form $\sum_i j_{\infty}(s_i),$ locally.

We use the following result, stated without proof.
\begin{prop}
Given a flat bundle $(E,\nabla)$, defined over some open neighbourhood $U$ of $X$, if $s\in \Gamma(U_0,E|_{U_0})$ is a flat section to the restriction $(E,\nabla)|_{U_0},$ where $U_0\subset U,$ then there exists a unique flat section $\widetilde{s}\in \Gamma(U,E)$ extending $s.$
\end{prop}

These facts imply $\mathcal{I}\simeq \mathcal{I}_1\oplus\cdots \oplus\mathcal{I}_k$ with $\mu_{Sp}(\mathcal{I}_i)=\mu_{Sp}(\mathcal{I})$. Then, since each $\mathcal{I}_i,i=1,\ldots,k$ corresponds to a stable flat bundle $(F_i,\nabla_{F_i})$ with $\mu(F_i)=\mu(E).$
By the classic DUY correspondence, each summand $(F_i,\nabla_{F_i}),i=1,\ldots,k$ admits a Hermitian-Yang-Mills metric $\beta_i,$ which glues to $h$. Conversely, suppose that $h$ is harmonic, this implies Spencer polystability since $h$ splits the flat bundle $(E,\nabla)$ into stable summands $(E_i,\nabla_i)$ of equal slope. Thus, $\mathcal{I}_{\nabla}$ decomposes into Spencer stable $\D$-ideals $\mathcal{I}_{\nabla_i},i=1,\ldots,k$. It is straightforward to check $\mu_{Sp}(\mathcal{I}_{\nabla_i})=\mu_{Sp}(\mathcal{I}).$ This concludes the proof of Proposition \ref{prop: Stability compare}.
\end{proof}
The proof of Theorem \ref{thm: DSUY implies DUY} is then concluded by adapting the well-known deformation-theoretic argument for unubstructedness of deformations of flat connections in holomorphic budles. 

%In our case, the Kuranishi map controlling obstructions is the map in cohomology induced by the Lie bracket on $End(E)$-valued differential forms on $X$, as
%$K:H_{Sp}^1(\mathcal{I}_{\nabla})\rightarrow H_{Sp}^2(\mathcal{I}_{\nabla}).$ If $K\equiv 0,$ all infinitesimal deformations of $\phi$ are integrable and $\nabla+\epsilon\phi +\mathcal{O}(\epsilon^2).$ 
\end{proof}


\appendix

\section{Proof of Proposition \ref{prop: Redux}}
\label{proof of redux}
\begin{proof}

We consider scalar PDEs $F=(F_1,\ldots,F_N)$ of orders $ord(F_A),$ for $A=1,\ldots,N,$ for simplicity, noting generalization to non-scalar PDEs is straightforward but more involved.

Each $F_A$ determines a corresponding map $J_X^k(E)\rightarrow J_{X}^{k-k_A}(X\times \mathbb{C}),$ and set 
$V:=\bigoplus_s V_s,$ the vector bundle with $dim(V_s)$ defined as the number of $A\in \{1,\ldots,N\}$ such that $ord(A)=s,$ and with $\sum dim(V_s)=N.$
Then $\mathsf{F}=(F_1,\ldots,F_N)$ determines a map
$$\mathsf{F}^{\infty}:J_X^{\infty}E\rightarrow J_{X}^{\infty}(V).$$
Set $\mathcal{V}_X:=\mathcal{O}(J_{X}^{\infty}V).$ 
 Then, pre-composition of $\mathsf{F}^{\infty}:\mathcal{A}_X\rightarrow \mathcal{V}_X,$ with other non-linear PDEs, we obtain a right-exact sequence
 \begin{equation}
     \label{eqn: Seq1}
     \mathrm{diff}(V,X\times\mathbb{C})\xrightarrow{-\mathsf{F}^{\infty}}\mathrm{diff}(E,X\times\mathbb{C})\rightarrow \mathcal{B}_X\rightarrow 0.
 \end{equation}
Letting $\mathcal{I}_X$ be the defining $\D$-ideal of $\mathcal{B}_X,$ then 
$$F^i\mathcal{I}_X\simeq Im(-\mathsf{F}^{\infty})\subset F^i\mathrm{diff}(E,X\times\mathbb{C}),$$
where $F^i\mathcal{I}$ is the usual filtration (\ref{eqn: FiniteIdeal}).
Consequently, 
\begin{equation}
    \label{eqn: B-cokernel}
F^i\mathcal{B}_X\simeq F^i(Coker(-\mathsf{F}^{\infty})\big)\simeq F^i\mathrm{diff}(E,X\times\mathbb{C})/F^i\mathcal{B}_X.
\end{equation}

Each term of (\ref{eqn: Seq1}) is a module over $\mathcal{A}[\D]$ and are moreover filtered:
$$\mathrm{Fil}^i\mathcal{A}[\D]\simeq \cup_{i,j}F^i\A_X\otimes \D_X^{\leq j},$$
which extends in the obvious way to 
$\mathrm{Fil}^i\mathcal{A}[\D](E,\mathcal{O})\simeq \bigcup_{i,j}F^i\A\otimes F^j\D_X(E,\mathcal{O}),$
and similarly for $\mathrm{Fil}^j\mathcal{B}_X[\D_X].$
Identifying $\mathrm{diff}(E,\mathcal{O}$ with $\mathcal{A}_X$ in the standard way,
we get from (\ref{eqn: B-cokernel}) an exact-sequence
$$0\rightarrow F^i\mathcal{I}\otimes F^i\D_X(E,\mathcal{O})\rightarrow \mathrm{Fil}^i\mathcal{A}[\D](E,\mathcal{O})\rightarrow \mathrm{Fil}^i\mathcal{B}_X[\mathcal{D}_X](E,\mathcal{O})\rightarrow 0.$$
Arguing in the exact same manner for $V$ and for $\mathcal{V}_X,$ we obtain a well defined filtered $\mathcal{B}_X^{\ell}$-module $\mathcal{M}_{\mathsf{F}^{\infty}},$ defined by the sequence
\begin{equation}
    \label{eqn: Seq2}
    \mathrm{Fil}^i\mathcal{B}[\mathcal{D}](V,\mathcal{O})\xrightarrow{lin_{\mathsf{F}}}\mathrm{Fil}^{i+k}\mathcal{B}_X[\mathcal{D}_X](E,\mathcal{O})\rightarrow F^{s+k}\mathcal{M}_{\mathsf{F}}\rightarrow 0.
\end{equation}
There is a canonical morphism $\mathrm{diff}(E,V)\rightarrow \A_X^{\ell}\otimes \D_X(E,V),$ sending $\mathsf{F}$ to $lin_{\mathsf{F}}.$
Consider the restriction of $\ell$ to the $i$-th filtered piece, we set 
$$Im(lin_{\mathsf{F}}^i)=lin_{\mathsf{F}}\big(\mathrm{Fil}^i\mathcal{B}_X[\D_X](V,\mathcal{O})\big).$$
This is a $F^i\mathcal{B}_X$-module and via base-chang along the canonical morphism $F^i\mathcal{B}_X\hookrightarrow F^{i+k}\mathcal{B}_X,$ we it generates a $F^{i+k}\mathcal{B}_X$-submodule in $\mathrm{Fil}^{i+k}\mathcal{B}_X[\mathcal{D}_X](E,\mathcal{O}).$
Via this base-change, by considering (\ref{eqn: Seq2}) we have that
\begin{equation}
\label{eqn: FM_F}
F^i\M_{\mathsf{F}}\simeq \mathrm{Fil}^i\mathcal{B}_X[\mathcal{D}_X](E,\mathcal{O})/F^i\mathcal{B}_X\cdot \mathrm{Im}(lin_{\mathsf{F}}^i).
\end{equation}
Using the canonical order filtration on differential operators, (\ref{eqn: Seq1}) is canonically filtered and subsequently taking quotient of two successive levels of the filtration, we obtain a sequence
$$F^{i-1}\M_{\mathsf{F}}\rightarrow F^i\mathcal{M}_{\mathsf{F}}\rightarrow \mathrm{Gr}_i^F(\M_{\mathsf{F}})\rightarrow 0,$$
as required.
\end{proof}


\section{Compatibility complexes and differential syzygy}
\label{sec: Compatibility complex}
We include here the construction of a compatibility complex for $\D_{\A}$-modules and an important proposition concerning its exactness.
\begin{cons}
\label{cons: Compatibility}
\normalfont
    For every $k_1\in \mathbb{N}\backslash\{0\},$ consider $\varphi_{P}^{k+k_1}:\overline{Jets}^{k+k_1}(\M_0)\rightarrow \overline{Jets}^{k_1}(\M_1),$ c.f. (\ref{eqn: InfiniteAhom}). We construct a compatibility complex for $P$ in a canonical way.
    If $k_1=0$ one may assume without loss of generality $\varphi_P^k$ is surjective. For $k_1>0,$ set 
    $\M_2:=\overline{J}^{k_1}(\M_1)/Im(\varphi_P^{k+k_1})\equiv coker(\varphi_P^{k+k_1}).$
    Denote by $q_1:\overline{J}^{k_1}(\M_1)\rightarrow \M_2,$ the quotient map. It is an element of 
    $$\mathcal{H}om(\overline{J}^{k_1}(\M_1),\M_2),$$ 
    thus corresponds to some $P_1\in \mathcal{A}[\D](\M_1,\M_2)$ of order $\leq k_1.$
    This representability result implies we may write $P_1=q_1\circ j_{k_1}.$ Now, 
    by construction,
    $$\M_0\xrightarrow{P}\M_1\xrightarrow{P_2}\M_2,$$
    is a complex of $\mathcal{A}[\D]$-modules, since
    $$P_1\circ P=(q\circ j_{k_1})\circ P=(q_1\circ \varphi_P^{k_1})\circ j_{k+k_1}=0.$$
One continues in this fashion: for $k_2$, we construct the quotient module $\M_3:=\overline{J}^{k_2}(\M_2)/Im(\varphi_{P_1}^{k+k_1+k_2})$, the quotient map $q_2$ and an operator $P_2$ so that $P_2\circ P_1=0.$ Eventually, we obtain a complex of $\mathcal{A}[\D]$-modules of the form:
$$0\rightarrow \M_0\xrightarrow{P}\M_1\xrightarrow{P_2}\M_2\xrightarrow{P_2}\cdots\rightarrow \M_i\xrightarrow{P_i}\M_{i+1}\rightarrow\cdots.$$
The question of its formal exactness is seen by considering $\mathsf{Sp}_{\mathcal{D}}(\M_0)^{\bullet}$, and arguing via (\ref{eqn: k-horizontal delta jet}).
\end{cons}
\begin{prop}
\label{prop: Exists CC formally exact}
    Suppose that $P\in \mathrm{Fil}^k\mathcal{A}[\D](\M_0,\M_1)$ is involutive in the above sense. Then there exists a compatibility complex described by \autoref{cons: Compatibility}, which is moreover formally exact for all integers $\{k_1,k_2,k_3,\ldots \in \mathbb{Z}_+\}.$
\end{prop}
\begin{proof}
    We need to show that for every $\ell\geq 1,$ the sequences
    $$\Sym^{k_{i-1}+k_i+\ell}(p_{\infty}^*\Omega_X^1)\otimes_\A\mathcal{M}_{i-1}\rightarrow \Sym^{k_i+\ell}(p_{\infty}^*\Omega_X^1)\otimes_{\A}\mathcal{M}_i\rightarrow \Sym^{\ell}(p_{\infty}^*\Omega_X^1)\otimes_\A\mathcal{M}_{i+1},$$
    are exact. Proceed by induction on $i,\ell$ and whose inductive step employs a spectral sequence argument applied to the bicomplex, where we denote $\overline{S}^k:=\Sym^{k}(p_{\infty}^*\Omega_X^1),$ for simplicity:
    \begin{equation}
\label{eqn: DiagramN}
\adjustbox{scale=.85}{
\begin{tikzcd}
 0\arrow[d] & 0\arrow[d] & 0\arrow[d] & 
\\
 \overline{\mathcal{N}}^{K+\ell}\arrow[d] \arrow[r]& p_{\infty}^*\Omega_X^1\otimes_{\A}\overline{\mathcal{N}}^{K+\ell-1}\arrow[d,]\arrow[r] & p_{\infty}^*\Omega_X^2\otimes_{\A}\overline{\mathcal{N}}^{K+\ell-2}\arrow[d]\arrow[d] \arrow[r] & \cdots 
\\
  \overline{S}^{K+\ell}\otimes_{\A}\M_0\arrow[d] \arrow[r]& p_{\infty}^*\Omega_X^1\otimes \overline{S}^{K+\ell-1}\otimes \M_0 \arrow[d]\arrow[r] & p_{\infty}^*\Omega_X^2\otimes \overline{S}^{K+\ell-2}\otimes \M_0\arrow[d]\arrow[r] & \cdots 
\\
 \vdots \arrow[d] & \vdots \arrow[d] & \vdots \arrow[d] & \vdots 
 \\
\overline{S}^{k_i+\ell}\otimes_{\A}\M_i\arrow[d] \arrow[r]& p_{\infty}^*\Omega_X^1\otimes \overline{S}^{k_i+\ell-1}\otimes \M_i \arrow[d]\arrow[r] & p_{\infty}^*\Omega_X^2\otimes \overline{S}^{k_i+\ell-2}\otimes \M_i \arrow[d]\arrow[r] & \cdots  
\\
\overline{S}^{\ell}\otimes_{\A}\M_{i+1}\arrow[d] \arrow[r]& p_{\infty}^*\Omega_X^1\otimes \overline{S}^{\ell-1}\otimes \M_{i+1} \arrow[d]\arrow[r] & p_{\infty}^*\Omega_X^2\otimes \overline{S}^{\ell-2}\otimes \M_{i+1}\arrow[d]\arrow[r] & \cdots
\\
0& 0 & 0&  
\end{tikzcd}}
\end{equation}
We have $K:=ord(P)+k_1+k_2+\cdots+k_i$.
\end{proof}




\section{Uniform bounds}
\label{Appendix Sweeney}
It is possible to give an explicit upper-bound for the Spencer-regularity of the family of $\D$-ideal sheaves as in Proposition \ref{prop: Boundedness 1}.
The characteristic $\D$-module defining the $\D$-characteristic variety (pulled back along a solution) as in proof of Proposition \ref{prop: D-Char is coisotropic}, is a submodule of the free $\mathcal{O}_{T^*X}\simeq\mathrm{Sym}^*(\Theta_X)$ module of finite rank and finitely generated by homogeneous elements, one can write down a bound. It is typically an overestimate \cite{Sw} depending only on values: $n,m,k$ with $k$ the order of the operator (corresponding to the degree of homogeneous polynomial). We now express it via recursion relations\footnote{It is given here for a single operator, but the generalization to systems (with possibly multiple orders) is straightforward but adds extra technicalities so we choose to omit it.}.
\begin{prop}
\label{prop: Sweeney Bound}
    There exists integers $\rho_1=\rho_1\big(n,m,\mathrm{Ord}(P)\big),$ which can be chosen such that
    \begin{equation}
        \label{eqn: Bounds}
        \begin{cases}
            \rho_1(0,m,1)=0;
            \\
            \rho_1(n,m,1)=m\cdot C_{n-1}^{\mathfrak{a}+n}+ \mathfrak{a}+1,\hspace{1mm}\text{ if } \mathfrak{a}=\rho_1(n-1,m,1);
            \\
            \rho_1(n,m,k_0)=\rho_1(n,\mathfrak{b},1),\hspace{1mm}\text{ if } \mathfrak{b}=\sum_{0}^{k_0}C_{n-1}^{\ell+n-1}\cdot m
        \end{cases}
    \end{equation}
If the operator $P$ is involutive then for all $\rho\geq \rho_0$ the symbol sequence it determines is exact.    
\end{prop}
In particular, for a family of $\D_X$-ideals $\{\mathcal{I}_j\}$ with orders $k_j$ (although we will just take pure orders) we write $\rho_1(0,m,1)=0$ and have that
$$\rho\big(n,m,\mathrm{Ord}_{\mathcal{D}_X}(\mathcal{I}_j)\big)=\rho\big(n,m\cdot  C_{n}^{k_j+n-1},1\big),$$
and 
$$
\rho(n,m,1)=m\cdot C_{n-1}^{\rho(n-1,m,1)+n}+\rho(n-1,m,1)+1.$$
\begin{prop}
Let $\mathcal{N}$ be the symbolic comodule such that $\mathcal{C}h_{k,1}=\mathcal{C}h_{k+1},$ for all $k\geq m_0.$ Then $\mathrm{Reg}_{\mathcal{D}_X}(\EQ)=m_0$ if and only if there exists a basis $\{\xi_1,\ldots,\xi_n\}$ in $T^*X,$ for which
$\mathrm{dim}(\mathcal{C}h_{k+1})=\sum_{\ell=1}^{n}\ell\cdot \alpha_k^{(\ell)},$
holds for $k=m_0.$
\end{prop}





