\title{On the relativistic effect in the Dirac--Fock theory}

\author{Long Meng\footnote{ 
\textsc{Long Meng, Mathematisches Institut,   Ludwig-Maximilians-Universit\"at M\"unchen, 80333 M\"unchen, Germany} 
