\section{Some technical estimates}\label{sec:A}
In this section, we list some basic estimates used in this paper taken from \cite{sere2023new,meng2024rigorous}. The difference is only because of the change of units for $Z$, $\alpha$ and $c$.
\begin{lemma}\label{lem:ope}
Let $\gamma\in X$. 
\begin{enumerate}
    \item 
    \begin{align}\label{eq:5.1-1}
    \|W_{\gamma}\|_{\mathcal{B}(\mathcal{H})}\leq \frac{\pi}{2}\|\gamma\|_X\leq \frac{\pi}{2 c}\|\gamma\|_{X_c}    
    \end{align}
    \item 
    \begin{align}\label{eq:5.1-2}
        \|W_{\gamma}u\|_{\mathcal{H}}\leq 2\|\gamma\|_{\mathfrak{S}_1}\|\nabla u\|_{\mathcal{H}}\leq \frac{2\|\gamma\|_{\mathfrak{S}_1}}{c}\||\cD|^{1/2}u\|_{\mathcal{H}}.
    \end{align}
    \item  Let $\gamma\in \Gamma_{q}$ and $\kappa_c<1$. Then
    \begin{align}\label{eq:5.1-3}
        (1-\kappa_c)^2|\cD|^2\leq |\mathcal{D}^c_{\gamma}|^2\leq  (1+\kappa_c)^{2}|\cD|^2.
    \end{align}
As a result,
\begin{align}\label{eq:D-D}
        (1-\kappa_c)|\cD|\leq |\mathcal{D}^c_{\gamma}|\leq  (1+\kappa_c)|\cD|.
    \end{align}
\item Let $\gamma\in \Gamma_{q}$, we have
\begin{equation}\label{eq:DP}
    \||\cD|^{1/2}P^{\pm}_{\gamma}u\|_{\mathcal{H}}\leq \frac{(1+\kappa_c)^{1/2}}{(1-\kappa_c)^{1/2}}\||\cD|^{1/2} u\|_{\mathcal{H}}.
\end{equation}
\item Let $\gamma\in \Gamma_{q}$ and $\max(q,Z)<\frac{2}{\pi/2+2/\pi}$, then
\begin{align}\label{eq:5.1-5}
    \inf|\sigma(\mathcal{D}^c_{\gamma})|\geq c^2\lambda_{0,c}(\alpha,c)=c^2(1-\max(\alpha_c q,Z_c)).
\end{align}
\item Let $h\in X^2$ and $\gamma\in \Gamma_{q}$, then 
\begin{align}\label{eq:W-cD}
    \|[W_h,\cD_{\gamma}]\|_{\cB(\cH)}\leq 16c(1+\kappa_c)\|h\|_{X^2}+c^2\|[W_h,\beta]\|_{\cB(\cH)}.
\end{align}
\end{enumerate}
\end{lemma}
\begin{proof}
Estimates \eqref{eq:5.1-1}-\eqref{eq:5.1-5} can be found in \cite[Lemma 2.6]{sere2023new}. Here they are a direct copy of \cite[Lemma A.1]{meng2024rigorous}. The last estimate \eqref{eq:W-cD} is a modification of \cite[Lemma 5.5]{meng2024rigorous}.
\end{proof}



