\title{Methods for Reducing Ancilla-Overhead in Block Encodings}


\author[1]{Francisca Vasconcelos\footnote{francisca@berkeley.edu}}
\author[2]{András Gilyén\footnote{gilyen.andras@renyi.hu}}
