\section{Part I: Approximate Single-Ancilla Block Encodings} \label{sec:part_i}
In this section, we will show how to uncompute all but one of a block encoding's ancillae. The uncomputed ancillae can then be reused for other tasks (beyond implementing the block encoding) in a quantum algorithm. This establishes a ``space-time tradeoff'' in which we can free up space (ancilla) via computation (time). Alternatively, this demonstrates that for any matrix $\general$, there exists an $\epsilon$-precise block-encoding of $\general$ requiring only one ancilla qubit.

In \Cref{sec:hermitian_uncompute} we describe this uncomputation procedure, in detail, for single-ancilla block encodings of Hermitian matrices $\herm$. In \Cref{sec:non_hermitian} we describe how this procedure can be generalized to single-ancilla block encodings of general matrices $\general$. 

\subsection{Single-Ancilla Block Encodings of Hermitian Matrices} \label{sec:hermitian_uncompute}

Let $V_{\herm}$ be a $(1, a, 0)$-block-encoding of $n$-qubit Hermitian matrix $\herm$, where $\norm{\herm} \leq 1-\delta$ for any $\delta \in (0,1)$.
In this section, we will show that we can efficiently map $V_{\herm}$, which requires several ancilla qubits, into $U_{\herm}$, an $\calO(\eps)$-block encoding of $\herm$ requiring only a single ancilla, where $\epsilon \in (0,1)$. 
In particular, we will prove the following main theorem.
\begin{theorem} \label{thm:main_thm_appendix}
    Let $V_{\herm}$ be a $(1, a, 0)$-block-encoding of Hermitian matrix $\herm$, where $\norm{\herm} \leq 1-\delta$, for some $\delta \in (0,1)$. For any $\eps \in (0,1)$, there exists a quantum circuit, requiring $c=\calO(1)$ additional ancillae and $\calO\left(\frac{1}{\delta}\log(\frac{1}{\epsilon})\right)$-queries to $V_\herm$ and $V_\herm^\dagger$, that implements a $(1,1,\epsilon)$-block encoding of $\herm$.
\end{theorem}
\begin{proof}[Proof of \Cref{thm:main_thm_appendix}]
We will propose a specific quantum circuit (parameterized by $\delta$ and $\epsilon$) that implements an $(n+a+c)$-qubit matrix $\widetilde{W}_\herm$ (for $c=\calO(1))$, which is a $(1, a+c-1, \epsilon)$-block encoding of the $(n+1)$-qubit matrix
\begin{align}
    U_{\herm} = Z \otimes \herm + X \otimes \sqrt{I - \herm^2}= \begin{pmatrix}
        \herm & \sqrt{I - \herm^2} \\
        \sqrt{I - \herm^2} & -\herm
    \end{pmatrix}.
\end{align}
We will now prove that $U_{\herm}$ is a $(1,1,0)$-block encoding of $\herm$. (To see this intuitively, consider the trivial case $\herm = \cos(x)$).
\begin{claim} \label{thm:hermitian}
Let $\herm$ be any Hermitian matrix with operator norm at most 1. Then, the matrix 
\[
U_{\herm} = Z \otimes \herm + X \otimes \sqrt{I - \herm^2}
\]
is a single-qubit Hermitian unitary block-encoding of $ \herm $, in the sense that $\herm= (\bra{0}\otimes I) U_\herm (\ket{0}\otimes I)$.
\end{claim}
\begin{proof}[Proof of \Cref{thm:hermitian}]
Note that $ Z $ and $ X $ are Pauli matrices, which are Hermitian, and $\sqrt{I - \herm^2}$ is also Hermitian. 
Since the tensor product and sum of Hermitian matrices is Hermitian, $U$ is Hermitian.

Next, consider the block structure of $ U $:
\begin{align}\label{eq:HermitianU}
    U_{\herm} = \begin{pmatrix}
        \herm & \sqrt{I - \herm^2} \\
        \sqrt{I - \herm^2} & -\herm
    \end{pmatrix}.
\end{align}
This matrix has $ \herm $ as the block component we are interested in and is thus a block-encoding of $ \herm $. Now, we verify that $ U_{\herm} $ is unitary by showing that
\begin{align}
U_{\herm}^\dagger U_{\herm} = U_{\herm}^2 = (Z \otimes \herm + X \otimes \sqrt{I - \herm^2})^2 = I.
\end{align}
In the last equality we used the properties of Pauli matrices, $ Z^2 = X^2 = I $, and $ ZX = -XZ $~to~get:
\begin{align}
U_{\herm}^2 = Z^2 \otimes \herm^2 + X^2 \otimes (I - \herm^2) + (ZX + XZ) \otimes (\herm \sqrt{I - \herm^2}) = I \otimes \herm^2 + I \otimes (I - \herm^2) = I. 
\end{align}
This concludes the proof of \Cref{thm:hermitian}.
\end{proof}
\noindent With this, we will now prove that the matrix block encoded by $\widetilde{W}_{\herm}$, which we will denote $\widetilde{U}_{\herm}$, is itself a $(1,1,\epsilon)$-block encoding of $\herm$.
\begin{claim} \label{thm:be}
    The matrix $\widetilde{U}_{\herm}=\bra{\bar{0}^{a+c-1}} \widetilde{W}_\herm\ket{\bar{0}^{a+c-1}}$ is a $(1,1,\epsilon)$-block encoding of $\herm$.
\end{claim}
\begin{proof}[Proof of \Cref{thm:be}]
    Let $\widetilde{U}_{\herm}$ denote the $n+1$ qubit matrix block-encoded by $\widetilde{W}_\herm$, i.e.
    \begin{align}
        \widetilde{U}_{\herm} = \left(\bra{0^{a+c-1}} \otimes I^{n+1}\right) \widetilde{W}_\herm \left(\ket{0^{a+c-1}} \otimes I^{n+1}\right).
    \end{align}
    Since $\widetilde{W}_\herm$ is an $\epsilon$-precise block encoding of $U_\herm$, i.e. $\| U_\herm - \widetilde{U}_{\herm} \| \leq \epsilon$, this implies that, i.e.
    \begin{align}
         \| \herm - \bra{0}\widetilde{U}_{\herm}\ket{0} \| =\| \bra{0}U_\herm\ket{0} - \bra{0}\widetilde{U}_{\herm}\ket{0} \|\leq \| U_\herm - \widetilde{U}_{\herm} \| \leq \eps.
    \end{align}
    Thus, $\widetilde{U}_{\herm}$ is a $(1,1,\eps)$-block encoding of $\herm$.
\end{proof}
\noindent Therefore, by computing $\widetilde{W}_\herm$ and post-selecting for the $a+c-1$-qubit measurement corresponding to block-encoding $\widetilde{U}_{\herm}$, we obtain a $(1,1,\eps)$-block encoding of $\herm$, as desired. 

The remainder of the proof will be dedicated to specifying a quantum algorithm
that computes $\widetilde{W}_\herm$. Specifically, we will formally prove each of the steps delineated by the high-level pseudocode of \Cref{alg:uncompute}.

\paragraph{Step 1.} We begin by leveraging linear combination of unitaries (LCU) to construct an explicit circuit mapping $V_\herm$ to $V_{\frac{I-\herm^2}{2}}$, which is a $(1,a+1,0)$-block encoding of the matrix $\frac{I-\herm^2}{2}$. This circuit requires two controlled-$V_\herm$ queries.
\begin{claim} \label{thm:lcu_1}
    The circuit 
    \begin{align} \label{eqn:i-h_be}
        V_{\frac{I-\herm^2}{2}} = (XH \otimes I_a)~C_{\Pi_1} V_{\herm}^2~(H \otimes I_a)
    \end{align}
    is a $(1,a+1,0)$-block-encoding of $\frac{I-\herm^2}{2}$.
\end{claim}
\begin{proof}[Proof of \Cref{thm:lcu_1}]
    Since $V_{\herm}$ is a $(1,a,0)$-block-encoding of $\herm$, by \cite[Lemma 54]{gilyen2018QSingValTransf}, $V_{\herm}^2$ is a $(1,a,0)$-block-encoding of $\herm^2$. Furthermore, the circuit defined in \Cref{eqn:i-h_be} is a $(1,1,0)$-block-encoding of $\frac{I-V_{\herm}^2}{2}$. Note that the unitary $\frac{I-V_{\herm}^2}{2}$ is a $(1,1,0)$-block encoding of $\frac{I-\herm^2}{2}$.
\end{proof}

\paragraph{Step 2.} With this, we can now leverage quantum singular value transformation (QSVT) to approximately apply a function to the singular values of $V_{\frac{I-\herm^2}{2}}$, implementing the matrix $V_{\frac{\sqrt{I - \herm^2}}{\sqrt{8}}}$, which is a $(1,a+\calO(1),\frac{\eps}{9})$-block-encoding of  $\frac{\sqrt{I-\herm^2}}{\sqrt{8}}$. 
\begin{claim} \label{thm:qsvt}
    The QSVT can be used to approximately apply the function $f(x) := \frac12 \sqrt{x}$ to $V_{\frac{I-\herm^2}{2}}$ so as to implement the unitary $V_{\frac{\sqrt{I - \herm^2}}{\sqrt{8}}}$, which is a $(1,a+\calO(1),\frac{\eps}{9})$-block-encoding of  $\frac{\sqrt{I-\herm^2}}{\sqrt{8}}$.  
\end{claim}
\begin{proof}[Proof of \Cref{thm:qsvt}]
    Since $\|\herm\| \leq 1-\delta$, we have that $I-\herm^2 \succeq 1-\delta$. Therefore, when applying functions to the singular values of $\frac{I-\herm^2}{2}$, we only need to consider the action of the function on the domain $[\delta, 1]$.

    The QSVT can be used to apply many polynomials to block-encoded matrices, with arbitrary precision. Specifically, in the case of functions of degree $c$ such that  $0< c\leq 1$, we can leverage the following result.
    \begin{fact}[\cite{gilyen2018QSingValTransfThesis} Corollary 3.4.14] \label{thm:qsvt_err}
    Let $\delta,\eta\in (0,\frac12]$, $c \in (0,1]$, and $f(x) := \frac12 x^c$. Then, there exist even/odd polynomials $P,P' \in \mathbb{R}[x]$ such that $\norm{P-f}_{[\delta,1]}\leq \eta$, $\norm{P}_{[-1,1]}\leq 1$ and $\norm{P'-f}_{[\delta,1]}\leq \eta$, $\norm{P'}_{[-1,1]}\leq 1$ \footnote{Note that for a polynomial $Q$, $\norm{Q}_{[a,b]}$ denotes the norm of $Q(x)$ in the interval $x\in [a,b]$.}. Moreover, the degree of the polynomials is $\bigO{\frac{1}{\delta}\log\left(\frac{1}{\eta}\right)}$.
    \end{fact}

    By \Cref{thm:qsvt_err}, there exists a degree-$\bigO{\frac{1}{\delta}\log\left(\frac{1}{\eps}\right)}$ polynomial $P^*$, such that $\norm{P^*}_{[-1,1]}\leq 1$ and, for $f(x) := \frac12 \sqrt{x}$,
    \begin{align} \label{eqn:poly_err}
        \norm{P^*-f}_{[\delta,1]}\leq \frac{\eps}{9}.
    \end{align}
    Via the QSVT, we can use $\calO(1)$ additional ancillae to apply the polynomial $P^*$ to the singular values of $V_{\frac{I-\herm^2}{2}}$. We will denote the output matrix of this QSVT operation as $V_{\frac{\sqrt{I - \herm^2}}{\sqrt{8}}} = P^* \left(V_{\frac{I-\herm^2}{2}}\right)$. Leveraging the triangle inequality, the error induced by this QSVT procedure is bounded as
    \begin{align}
        &\norm{\bra{0^{a+2}} V_{\frac{\sqrt{I - \herm^2}}{\sqrt{8}}} \ket{0^{a+2}} - \frac{\sqrt{I - \herm^2}}{\sqrt{8}}} = \norm{\bra{0^{a+2}} P^* \left(V_{\frac{I-\herm^2}{2}}\right) \ket{0^{a+2}} - \frac{\sqrt{I - \herm^2}}{\sqrt{8}}} \\
        & \leq \norm{ \bra{0^{a+2}} P^* \left(V_{\frac{I-\herm^2}{2}}\right) - f \left(V_{\frac{I-\herm^2}{2}}\right) \ket{0^{a+2}} } + \norm{\bra{0^{a+2}} f \left(V_{\frac{I-\herm^2}{2}}\right) \ket{0^{a+2}} - \frac{\sqrt{I - \herm^2}}{\sqrt{8}} } \\
        & \leq \norm{ P^* \left(V_{\frac{I-\herm^2}{2}}\right) - f \left(V_{\frac{I-\herm^2}{2}}\right) } + \norm{f \left(\bra{0^{a+2}} V_{\frac{I-\herm^2}{2}}\ket{0^{a+2}}\right)  - \frac{\sqrt{I - \herm^2}}{\sqrt{8}} } \\
        & \leq \frac{\eps}{9} + \norm{  \frac{\sqrt{I - \herm^2}}{\sqrt{8}}  - \frac{\sqrt{I - \herm^2}}{\sqrt{8}} } =  \frac{\eps}{9}. \label{eqn:temp} 
    \end{align}
    This concludes the proof of \Cref{thm:qsvt}.
\end{proof}

\paragraph{Step 3.} With a subroutine to compute $V_{\frac{\sqrt{I - \herm^2}}{\sqrt{8}}}$, we will leverage linear combination of unitaries again in order to compute a 
matrix $W_{U_\herm}$, which is a $(1,a+\calO(1),\frac{\eps}{14})$-block-encoding of $\sin(\pi/14) \cdot U_\herm$.
\begin{lemma} \label{thm:lcu}
    Linear combination of unitaries with $V_\herm$ and $V_{\frac{\sqrt{I - \herm^2}}{\sqrt{8}}}$, can be used to implement
    \begin{align}
        W_{U_\herm} =\sqrt{8}\sin(\pi/14) \cdot X \otimes V_{\frac{\sqrt{I - \herm^2}}{\sqrt{8}}}  + \sin(\pi/14) \cdot Z  \otimes V_{\herm},
    \end{align}
    which is a $(1,a+\calO(1),\frac{\eps}{14})$-block-encoding of $\sin(\pi/14) \cdot U_\herm$.
\end{lemma}
\begin{proof}[Proof of \Cref{thm:lcu}]
    Recall that $V_{\frac{\sqrt{I - \herm^2}}{\sqrt{8}}}$ is a $(1,a+\calO(1),\frac{\eps}{9})$-block-encoding of  $\frac{\sqrt{I-\herm^2}}{\sqrt{8}}$, operating on $n+a+\calO(1)$ qubits. Meanwhile, $V_{\herm}$ is a $(1, a, 0)$-block-encoding of $\herm$, operating on $n+a$ qubits. 

    Performing the standard LCU procedure \cite{childs2012hamiltonian} with the selection oracle
    \begin{align}
        U_\text{SEL} = \ketbra{0}{0} \otimes  X \otimes \widetilde{V}_{\sqrt{I-\herm^2}} + \ketbra{1}{1} \otimes Z \otimes I^{\otimes \calO(1)} \otimes V_{\herm}
    \end{align}
    and preparation oracle
    \begin{align}
        V_\text{PREP} \ket{0} = \frac{1}{3 \sqrt{\sin(\pi/14)}} \left( \sqrt{8 \sin(\pi/14)} \ket{0} + \sqrt{ \sin(\pi/14)} \ket{1}\right),
    \end{align}
    we can implement
    \begin{align}
        W_{U_\herm} &=V_\text{PREP}~U_\text{SEL}~V_\text{PREP}^\dagger = \sin(\pi/14) \cdot \left(\sqrt{8} \cdot X \otimes \widetilde{V}_{\sqrt{I-\herm^2}}  +  Z \otimes I^{\otimes \calO(1)}\otimes V_{\herm} \right) %\\
    \end{align}
    According to the selection $\ket{\bar{0}}=\ket{0^{a+\calO(1)}}$, this matrix block-encodes
    \begin{align}
        \bra{\bar{0}}W_{U_\herm} \ket{\bar{0}} &= \sin(\pi/14) \cdot \left(\sqrt{8} \cdot X \otimes \bra{\bar{0}}V_{\frac{\sqrt{I - \herm^2}}{\sqrt{8}}} \ket{\bar{0}}  +  Z \otimes \bra{0^a}V_{\herm} \ket{0^a} \right). %\\
    \end{align}
    Using the facts that $\norm{A \otimes B} \leq \norm{A}\norm{B}$, $\norm{U}=1$ for any unitary matrix $U$, and $\norm{a \cdot A}=|a|\cdot \norm{A}$ for any scalar $a$, we will now prove that  $\bra{\bar{0}}W_{U_\herm} \ket{\bar{0}}$ is $\frac{\eps}{14}$-close to $U_\herm$.
    \begin{align}
        &\norm{\sin(\pi/14) \cdot U_\herm - \bra{\bar{0}}W_{U_\herm} \ket{\bar{0}}} \\
        &= \sin(\pi/14) \cdot \norm{(X \otimes \sqrt{I - \herm^2}+Z \otimes \herm) - \left(\sqrt{8} \cdot X \otimes \bra{\bar{0}}V_{\frac{\sqrt{I - \herm^2}}{\sqrt{8}}} \ket{\bar{0}}  +  Z \otimes \bra{0^a}V_{\herm} \ket{0^a} \right)} \\
        &= \sin(\pi/14) \cdot \norm{X \otimes \left(\sqrt{I - \herm^2} - \sqrt{8} \cdot \bra{\bar{0}}V_{\frac{\sqrt{I - \herm^2}}{\sqrt{8}}} \ket{\bar{0}}\right)+Z \otimes \left(\herm -  \herm \right)} \\
        & \leq \sin(\pi/14) \cdot \left( \norm{X \otimes \left(\sqrt{I - \herm^1} - \sqrt{8} \cdot \bra{\bar{0}}V_{\frac{\sqrt{I - \herm^2}}{\sqrt{8}}} \ket{\bar{0}}\right)} \right) \\
        & \leq \sin(\pi/14) \cdot \left( \norm{X} \norm{\sqrt{I - \herm^2} - \sqrt{8} \cdot \bra{\bar{0}}V_{\frac{\sqrt{I - \herm^2}}{\sqrt{8}}} \ket{\bar{0}}} \right) \\
        &  = \sin(\pi/14) \cdot \left( \sqrt{8} \cdot \norm{\frac{\sqrt{I - \herm^2}}{\sqrt{8}} - \bra{\bar{0}}V_{\frac{\sqrt{I - \herm^2}}{\sqrt{8}}} \ket{\bar{0}}} \right) \\
        &  \leq \sin(\pi/14) \cdot \left( \sqrt{8} \cdot \frac{\eps}{9} \right) \\
        & \leq \frac{\eps}{14}
    \end{align}
    This concludes the proof of \Cref{thm:lcu}.
\end{proof}

\paragraph{Step 4.} In order to produce a block-encoding that is $\eps$-close to $U_\herm$, we will perform oblivious amplitude amplification (OAA) on $W_{U_\herm}$. The following result guarantees our ability to amplify the desired coefficient.

\begin{fact}[\cite{gilyen2018QSingValTransf} Theorem 28] \label{thm:oaa}
Let $n \in \mathbb{N}_+$ be odd, let $\eps\in\mathbb{R}_+$, let $Q$ be a unitary, let $\widetilde{\Pi}$, $\Pi$ be orthogonal projectors and let $M: \textnormal{img}(\Pi) \mapsto \textnormal{img}(\widetilde{\Pi})$ be an isometry, such that 
\begin{align}
    \norm{\sin\left(\frac{\pi}{2n}\right)M\ket{\psi}-\widetilde{\Pi} Q \ket{\psi}} \leq \eps
\end{align}
for all $\ket{\psi} \in \textnormal{img}(\Pi)$. Then, we can construct a unitary $\widetilde{Q}$ such that for all $\ket{\psi} \in \textnormal{img}(\Pi)$,
\begin{align}
    \norm{M \ket{\psi}-\widetilde{\Pi} \widetilde{Q} \ket{\psi}} \leq 2n \eps,
\end{align}
which uses a single ancilla qubit, with $n$ uses of $Q$ and $Q^\dagger$, $n$ uses of $C_\Pi NOT$ and $n$ uses of $C_{\widetilde{\Pi}} NOT$ gates and $n$ single qubit gates.
\end{fact}
\noindent Specifically, in our case, we have that
\begin{align}\label{eq:closeBlockEncoding}
    \norm{\sin\left(\frac{\pi}{14}\right)\cdot U_{\herm}\ket{\psi}- \bra{\bar{0}}W_{U_\herm} \ket{\bar{0}} \ket{\psi}} \leq \frac{\eps}{14}.
\end{align}
Thus, by \Cref{thm:oaa}, we can implement matrix $\widetilde{W}_{U_\herm}$, which is an $\eps$-precise block-encoding of $U_{\herm}$, i.e.
\begin{align}
    \norm{U_{\herm}\ket{\psi}- \bra{\bar{0}}\widetilde{W}_{U_\herm} \ket{\bar{0}} \ket{\psi}} \leq \eps.
\end{align}
In practice, $\widetilde{W}_{U_\herm}$ is implemented via the QSVT. Using one ancilla qubit,  four $W_{U_\herm}$ queries, and three $W_{U_\herm}^\dagger$ queries a Chebyshev polynomial of $7^\text{th}$ order is applied to the block-encoded matrix. Since $T_7 \left(\sin\left(\frac{\pi}{14}\right)\right)=-1$, this amplifies the amplitude of the matrix block-encoded by $W_{U_\herm}$ to the desired amplitude (up to a phase).

\paragraph{Step 5.}
By \Cref{thm:oaa}, we know that the top left corner of the implemented matrix is close to the desired. It is not too difficult to see that this in particular implies that the implemented approximate block encoding is $\bigO{\eps}$-close to an ideal ancilla-saving unitary $U$ for which $(\bra{\bar{0}}\otimes I)U(\ket{\bar{0}}\otimes I)=U_{\herm}$, see for example~\cite[Lemma 23]{gilyen2018QSingValTransf} and its proof for a detailed argument.

Indeed, \Cref{eq:closeBlockEncoding} combined with the proof of~\cite[Lemma 23]{gilyen2018QSingValTransf} shows that there is a unitary $V$ such that $\bra{\bar{0}} V \ket{\bar{0}}=\sin\left(\frac{\pi}{14}\right)\cdot U_{\herm}$ and $\norm{W_{U_\herm} - V}=\bigO{\eps}$. If we were using $V$ in the oblivious amplitude amplification we would end up with a unitary whose top left corner is exactly $U_\herm$, and that unitary is $\bigO{n\eps}$ close to $\widetilde{W}_{U_\herm}$.
\end{proof}  


\subsection{Single-Ancilla Block Encodings of General Matrices} \label{sec:non_hermitian}
In the previous section, we focused on single-ancilla block encodings of Hermitian matrices $\herm$. We will now show how an analogous procedure can be leveraged to implement a single-ancilla block-encoding of general sub-normalized matrices $\general$.
\begin{corollary}[Ancilla Uncomputation for General Matrices] \label{thm:general_corollary_appendix}
     Let $V_{\general}$ be a $(1, a, 0)$-block-encoding of general matrix $\general$, where $\norm{\general} \leq 1-\delta$, for some $\delta \in (0,1)$. For any $\eps \in (0,1)$, there exists a quantum circuit, requiring a small constant number $c=\calO(1)$ of additional ancillae and $\calO\left(\frac{1}{\delta}\log(\frac{1}{\epsilon})\right)$-queries to $V_\general$ and $V_\general^\dagger$, that implements a $(1,1,\epsilon)$-block encoding of $\general$ and returns the remaining $a-1$ ancilla to the state $\ket{0^{a-1}}$.
\end{corollary}
\begin{proof}[Proof of \Cref{thm:general_corollary_appendix}]
    The critical difference in the procedure for general matrices $\general$ from that of Hermitian matrices $\herm$ (\Cref{thm:main_thm_appendix}) is in the form of the single-ancilla block encoding to be implemented. For general matrices we will implement a block encoding of the following Hermitian matrix, which we also prove to be unitary. (To get some intuition for the following statement it is worth considering the trivial case $\general=\sin(x)$.)
    \begin{claim} \label{thm:hermitian_general} 
        Let $\general$ be any matrix with operator norm at most 1. Then, the matrix 
        \begin{align}
            U_\general = \begin{pmatrix}
            \sqrt{I - \general^\dagger \general} & \general^\dagger \\
            \general & -\sqrt{I - \general \general^\dagger}
            \end{pmatrix}
        \end{align}
        is a Hermitian unitary block-encoding of $\general$ in the sense that $\general= (\bra{1}\otimes I) U_\general (\ket{0}\otimes I)$.
    \end{claim}
    \begin{proof}[Proof of \Cref{thm:hermitian_general}] 
        $U_\general$ is Hermitian by design, since $ \sqrt{I - \general^\dagger \general} $ and $ \sqrt{I - \general \general^\dagger} $ are Hermitian. 

        We will now prove that $ U $ is unitary. To do so, we leverage the following facts,
        \begin{align}
            \sqrt{I - \general^\dagger \general} \general^\dagger &= \general^\dagger \sqrt{I - \general \general^\dagger} \\
            \quad \general \sqrt{I - \general^\dagger \general} &= \sqrt{I - \general \general^\dagger} \general, \\
            \left(\sqrt{I - \general^\dagger \general}\right)^2 &+ \general^\dagger \general = I \\
            \left(\sqrt{I - \general \general^\dagger}\right)^2&+ \general \general^\dagger = I
        \end{align}
        which can be verified via the singular value decomposition of $\general$. Thus,
        \begin{align}U_\general^\dagger U_\general = U_\general^2 
        &= \begin{pmatrix}
        \left(\sqrt{I - \general^\dagger \general}\right)^2 + \general^\dagger \general & \sqrt{I - \general^\dagger \general} \general^\dagger - \general^\dagger \sqrt{I - \general \general^\dagger} \\
        \general \sqrt{I - \general^\dagger \general} - \sqrt{I - \general \general^\dagger} \general & \general \general^\dagger + \left(\sqrt{I - \general \general^\dagger}\right)^2
        \end{pmatrix} \\
        & = \begin{pmatrix}
        I & \general^\dagger \left( \sqrt{I - \general \general^\dagger}-\sqrt{I - \general \general^\dagger} \right)\\
        \general \left(\sqrt{I - \general^\dagger \general} -\sqrt{I - \general^\dagger \general}\right) & I
        \end{pmatrix}
         = I,
        \end{align}
        confirming that $U_\general$ is in fact unitary.
    \end{proof}
    The protocol for implementing $U_\general$ follows closely to that of $U_\herm$. However, we offer a brief outline for completeness. We are given access to $V_\general$, an $a$-ancilla block encoding of $\general$, as well as $V_\general^\dagger$, which block encodes $\general^\dagger$. Linear combination of unitaries is used to implement block encodings of $I-\general \general^\dagger$ and $I- \general^\dagger\general$. Application of the QSVT to these block encodings results in approximate block encodings of $\sqrt{I-\general \general^\dagger}$ and  $\sqrt{I- \general^\dagger\general}$. Via linear combination of unitaries, these are combined into an approximate block encoding of $\alpha \cdot U_\general$, for a coefficient $\alpha$. Since $U_\general$ is a unitary matrix, oblivious amplitude amplification is used to boost the amplitude $\alpha$, resulting in the desired approximate block encoding of $U_\general$. 
\end{proof}


\section{Part II: Approximate Multiplication of Block Encodings} \label{sec:part_ii}

In general, an $(n+a)$-qubit block encoding can be defined for any bit-strings $b_1, b_2 \in \{0,1\}^a$,
\begin{align}
    A = (\bra{b_1} \otimes I_n) U_A (\ket{b_2} \otimes I_n).
\end{align}
Note, however, that we can straightforwardly modify the block encoding unitary as
\begin{align}
    \widetilde{U}_A = (X^{b_1} \otimes I_n) U_A (X^{b_2} \otimes I_n)
\end{align}
to obtain a new unitary $\widetilde{U}_A$ such that
\begin{align}
    A = (\bra{0^a} \otimes I_n) \widetilde{U}_A (\ket{0^a} \otimes I_n).
\end{align}
Therefore, without loss of generality, in this section, we will only consider block encodings where $A$ is embedded in the top left corner of the unitary. Where obvious, we will also not explicitly write the $I_n$ terms to improve readability.

For a series of $K$ $(n+a)$-qubit block encodings $(U_{A_i})_{i=1}^K$, we will denote the desired multiplication of block encodings as
\begin{align}
    A_{[K]} = A_K \cdots A_2 A_1.
\end{align}
In terms of the full unitaries, this can be decomposed as  
\begin{align} \label{eqn:multibe}
    A_{[K]} &= \bra{0^a} U_{A_K} \ketbra{0^a}{0^a} \cdots \ketbra{0^a}{0^a} U_{A_2} \ketbra{0^a}{0^a} U_{A_1} \ket{0^a} \\
    & = \bra{0^a} U_{A_K} \pzeroa \cdots \pzeroa U_{A_2} \pzeroa U_{A_1} \ket{0^a},
\end{align}
where $\pzeroa = \ketbra{0^a}{0^a}$ with orthogonal projector $\pperp = I - \pzeroa$
However, the projectors $\pzeroa$ are not unitary and can thus only be implemented either by performing measurements incoherently or coherently block encoding them. 

A coherent block encoding of the projector $\pzeroa$ takes the general form
\begin{align}
    U_{\pzeroa} = G \otimes \pzeroa + B \otimes \pperp,
\end{align}
where  $G$ and $B$ are both unitaries. We will prove that this construction is in fact unitary. 
\begin{claim} \label{thm:unitary}
    For arbitrary unitaries $G$ and $B$, $U_{\pzeroa} = G \otimes \pzeroa + B \otimes \pperp$ is unitary.
\end{claim}
\begin{proof}[Proof of \Cref{thm:unitary}]
    To confirm that $U_{\pzeroa}$ is unitary, we must show that $U_{\pzeroa}^\dagger U_{\pzeroa} = U_{\pzeroa} U_{\pzeroa}^\dagger = I$.
    \begin{align}
        U_{\pzeroa}^\dagger U_{\pzeroa} &= G^\dagger G \otimes \pzeroa + B^\dagger B \otimes \pperp = I \otimes (\pzeroa + \pperp) = I \\
        U_{\pzeroa}^\dagger U_{\pzeroa} &= G G^\dagger \otimes \pzeroa + B B^\dagger \otimes \pperp = I \otimes (\pzeroa + \pperp)=I
    \end{align}
    This concludes the proof of \Cref{thm:unitary}.
\end{proof}

If $G$ and $B$ are $m$-qubit unitaries, $U_{\pzeroa}$ specifically block-encodes the matrix
\begin{align}
    \bra{0^m} U_{\pzeroa} \ket{0^m} = \bra{0^m} G \ket{0^m} \cdot \pzeroa + \bra{0^m} B \ket{0^m} \cdot \pperp.
\end{align}
Thus, by setting $m=1$, $G = I$ and $B=X$, we obtain the desired block-encoding $\bra{0} U_{\pzeroa} \ket{0} = \pzeroa$
of a single $\pzeroa$ projector.

Returning to \Cref{eqn:multibe}, to implement the multiplication of $K$ block encodings, an $m$-qubit block encoding of $A_{[K]}$ takes the general form 
\begin{align} \label{eqn:encode_circuit}
    U_{A_{[K]}} = U_{A_K} (G_{K-1} \otimes \pzeroa + B_{K-1} \otimes \pperp) U_{A_{K-1}} \cdots  U_{A_2} (G_1 \otimes \pzeroa + B_1 \otimes \pperp) U_{A_1}.
\end{align}
Specifically, this matrix block encodes
\begin{align}
    \bra{0^m} U_{A_{[K]}} \ket{0^m} &= \sum_{x \in \{0,1\}^{K-1}} \bra{0^m} \prod_{i=1}^{K-1} G_i^{x_i} B_i^{1-x_i} \ket{0^m} \cdot U_{A_K}\prod_{i=1}^{K-1} \pzeroa^{x_i} \pperp^{1-x_i} U_{A_i} \\
    & = \bra{0^m} G_{K-1}\cdots G_1 \ket{0^m} \cdot U_{A_K} \pzeroa U_{A_{K-1}} \cdots  U_{A_2} \pzeroa U_{A_1} \\
    & \quad \quad \quad + \sum_{x \in \{0,1\}^{K-1}\backslash 0^{K-1}} \bra{0^m} \prod_{i=1}^{K-1} G_i^{x_i} B_i^{1-x_i} \ket{0^m} \cdot U_{A_K}\prod_{i=1}^{K-1} \pzeroa^{x_i} \pperp^{1-x_i} U_{A_i} \\
    & = \bra{0^m} \prod_{i=1}^{K-1} G_i \ket{0^m} \cdot A_{[K]} \\
    & \quad\quad\quad+ \sum_{x \in \{0,1\}^{K-1}\backslash 0^{K-1}} \bra{0^m} \prod_{i=1}^{K-1} G_i^{x_i} B_i^{1-x_i} \ket{0^m} \cdot U_{A_K}\prod_{i=1}^{K-1} \pzeroa^{x_i} \pperp^{1-x_i} U_{A_i}
\end{align}
For large enough $m$ and careful choice of the unitaries $(G_i)_{i=1}^{K-1}$ and $(B_i)_{i=1}^{K-1}$, this construction is guaranteed to implement the desired multiplication of block encodings, such that 
\begin{align} 
    \bra{0^{m+a}} U_{A_{[K]}} \ket{0^{m+a}} =\bra{0^a}U_{A_K} \pzeroa \cdots  \pzeroa U_{A_2} \pzeroa U_{A_1}\ket{0^a}= A_{[K]}.
\end{align}
The key question that we explore in this section is how small we can make the number of measurement ancillae $m$, while still achieving this desired block encoding (or something close to it).

\subsection{The Multiple Coherent Measurement (\circclass)~Circuit Class}

We begin by formalizing the Multiple Coherent Measurement  (\circclass) circuit class, which implements unitaries of the form of $U_{A_{[K]}}$, as described in \Cref{eqn:encode_circuit}. This circuit class will serve as the central object of study in Part II. We will show that all known procedures for implementing multiplication of block encodings can be implemented in this circuit class. Furthermore, restriction to this circuit class will enable us to prove a lower-bound on the number of measurement ancillae $m$ required to achieve \emph{exact} multiplication of block encodings (\Cref{def:exact_mbe}).
\begin{definition}[\circclass$_{\vec{U}_A, K, \vec{\Pi}}$ Circuit Class] 
    Suppose we are given series of $K$ $(n+a)$-qubit block-encodings $\vec{U}_A = (U_{A_i})_{i=1}^K$. Without loss of generality, assume that all $U_{A_i}$ have $\pzeroa$ as the $a$-qubit projector onto ``good'' measurement outcome and $\pperp=I_a-\pzeroa$ as the $a$-qubit projector onto ``bad'' measurement outcome. With this, we define $\circclass_{\vec{U}_A, K,m}$ to be the class of all circuits of the form,
    \begin{align} \label{eqn:mcm_general}
        \circclass_{\vec{U}_A, K,m} (\vec{W}, \vec{G}, \vec{B}) = (W_{K-1} \otimes U_K) \prod_{i=1}^{K-1}   \left( \left(G_{K-i} \otimes \pzeroa \otimes I_n \right)\left( B_{K-i} \otimes \pperp \otimes I_n \right)    \left(W_{K-i-1} \otimes U_{K-i}\right) \right),
    \end{align}
    parameterized by the series of $m$-qubit unitaries $\vec{W} = (W_i)_{i=0}^{K-1}$, $\vec{G} = (G_i)_{i=1}^{K-1}$, and $\vec{B} = (B_i)_{i=1}^{K-1}$. The circuit is illustrated in \Cref{fig:mcm}.
\end{definition}
\begin{figure}[t!]
    \centering
    \includegraphics[width=.8\textwidth]{figs/proof2.pdf}
    \caption{An $\circclass_{\vec{U}, K,m} (\vec{W}, \vec{G}, \vec{B})$ circuit.}
    \label{fig:mcm}
\end{figure}
\noindent  The \circclass$_{\vec{U}_A, K, m}$ circuit class was to defined to be as general possible, making it clear that it contains all circuits of the form of \Cref{eqn:encode_circuit}. However, as defined, the circuit class is overparameterized and its circuits can be simplified as follows.
\begin{lemma}[Simplified \circclass~Structure] \label{thm:simplify}
    For every $\circclass_{\vec{U}_A, K,m} (\vec{W}, \vec{G}, \vec{B})$ circuit, there exists a series of $m$-qubit unitaries $\vec{V} = (V_i)_{i=1}^{K-1}$ and  a single $m$-qubit unitary $Q$ such that $\circclass_{\vec{U}_A, K,m} (\vec{W}, \vec{G}, \vec{B})$ can be simplified to a circuit of the form
    \begin{align}
        \circclass_{\vec{U}_A, K,m} (\vec{V}, Q) = (Q\otimes U_K) \cdot \prod_{i=1}^{K-1} \left(  \left(V_{K-i}\otimes \pperp \otimes I_n \right) \left(I_{m+a} \otimes U_{K-i}\right)\right),
    \end{align}
    as depicted in \Cref{fig:lemma_con_uni}.
\end{lemma}
\begin{proof}[Proof of \Cref{thm:simplify}]
    For ease of notation, we will denote the unitary implemented by $\circclass_{\vec{U}_A, K,m} (\vec{W}, \vec{G}, \vec{B})$, in \Cref{eqn:mcm_general}, as $U_\circclass$. Leveraging the following identity
    \begin{align}
        (G_{j}\otimes \pzeroa) (B_{j}\otimes \pperp) &= \left( G_j \otimes \pzeroa + I \otimes\pperp \right) \left(I \otimes \pgood^{(j)} + B_j\otimes \pperp\right) \\
        &= G_j \left( I \otimes \pzeroa + G_j^\dagger \otimes\pperp \right) \left(I \otimes \pzeroa + B_j\otimes \pperp\right) \\
        &=  G_j \left(I  \otimes \pzeroa +  G_j^\dagger B_j \otimes \pperp\right). 
    \end{align}
    and setting $W_j^* = W_j G_{j+1}$ and $V_j^* = G_j^\dagger B_j$, the unitary simplifies to
    \begin{align}
        U_\circclass = (W_{K} W^*_{K-1} \otimes U_K) \prod_{i=1}^{K-1}  \left( \left( V^*_{K-i} \otimes \pperp \otimes I_n \right) \left(W_{K-i-1}^* \otimes U_{K-i}\right) \right),
    \end{align}
    which can be depicted as:
    \begin{figure}[H]
        \centering
        \includegraphics[width=.75\textwidth]{figs/proof3.pdf}
    \end{figure}

    \noindent We will now recursively commute all the $W_i^*$ gates through all the $V_i^*$ gates to their right. Begin by defining the set of unitaries $V_{j+1}$ such that
    \begin{align}
        \left(\prod_{i=0}^j W^*_{j-1}\right) V_{j+1}  =  V^*_{j+1} \left(\prod_{i=0}^j W^*_{j-i}\right),
    \end{align}
    which implies that 
    \begin{align}
        (V^*_{j+1}\otimes \pperp) \left(\prod_{i=0}^j W^*_{j-i} \otimes I_a\right) &= \left( I  \otimes \pzeroa +  V^*_{j+1} \otimes \pperp  \right) \left(\prod_{i=0}^j W^*_{j-i} \otimes I_a\right)  \\
        &= \left(\prod_{i=0}^j W^*_{j-i}\right)  \otimes \pzeroa +  V^*_{j+1} \left(\prod_{i=0}^j W^*_{j-i}\right) \otimes \pperp \\
        &= \left(\prod_{i=0}^j W^*_{j-i}\right)  \otimes \pzeroa +   \left(\prod_{i=0}^j W^*_{j-i}\right) V_{j+1} \otimes \pperp \\
        &= \left(\prod_{i=0}^j W^*_{j-i} \otimes I_a\right) \left( I  \otimes \pzeroa +  V_{j+1} \otimes \pperp  \right) \\
        &=  \left(\prod_{i=0}^j W^*_{j-i} \otimes I_a\right) (V_{j+1}\otimes \pperp).
    \end{align}
    Thus, the circuit reduces to
    \begin{align}
        U_{\circclass} = (W_{K} \otimes I_{a+n}) \prod_{j=1}^{K} (W^*_{K-j} \otimes I_{a+n})  \prod_{i=0}^{K-1}  \left( \left( V_{K-i}\otimes \pperp \otimes I_n \right)  \left(I_m \otimes U_{K-i}\right) \right),
    \end{align}
    which is depicted as:
    \begin{figure}[H]
        \centering
        \includegraphics[width=.8\textwidth]{figs/proof4.pdf}
    \end{figure}

    \noindent Therefore, setting $Q = W_K \prod_{j=1}^{K} W^*_{K-j} $, it is clear that $U_{\circclass} = \circclass_{\vec{U}_A, K,m} (\vec{V}, Q)$.
\end{proof}
\noindent From hereon, when we refer to the \circclass~circuit class, we will be referring to circuits of the form $\circclass_{\vec{U}_A, K,m} (\vec{V}, Q)$.


\subsection{Exact Compression Gadgets}
We will now introduce the notions of \emph{exact} multiplication of block encodings and \emph{exact} compression gadgets. Although multiplication of block encodings and compression gadgets are typically defined this way, we emphasize that they are exact to contrast with our eventual introduction of \emph{approximate} multiplication of block encodings and \emph{approximate} compression gadgets.


\begin{definition}[Exact Multiplication of Block Encodings (EMBE)] \label{def:exact_mbe}
    We will refer to an $\circclass_{\vec{U}_A, K,m} (\vec{V}, Q)$ circuit as an  \textbf{exact multiplication of block encodings (EMBE)} if it satisfies
    \begin{align} 
        \bra{0^{m+a}} \circclass_{\vec{U}_A, K,m} (\vec{V}, Q) \ket{0^{m+a}} = A_{[K]},
    \end{align}
    thereby exactly implementing the desired multiplication of block encodings.
\end{definition}


As described in the introduction (\Cref{sec:intro_part2}), the naive approach to implementing an exact multiplication of block encodings involves adding a measurement ancilla qubit for each block encoding. We can formally define this procedure in the \circclass~framework as follows.
\begin{definition}[Naive EMBE] \label{def:naive_dmbe}
    For a sequence of $K$ block encoding unitaries $(U_{A_i})_{i=1}^K$, a naive deterministic multiplication of block encodings can be implemented by a $\circclass_{\vec{U}_A, K,m} (\vec{V}, Q)$~circuit setting with $m=K-1$ measurement ancillae, $Q=I_m$, and   
    \begin{align}
        V_i  = X_i \otimes I_{[K-1]\backslash i} \quad \forall i \in [K-1].
    \end{align}
\end{definition}
\noindent However, as discussed in the introduction, this Naive EMBE is far from optimal in terms of the number of measurement ancillae $m$. This leads us to define the notion of an exact compression gadget\footnote{Note that the name ``compression gadget'' comes from the work of \cite{low2019Hamiltonian}.}. 
\begin{definition}[Exact Compression Gadget (ECG)] 
    For a sequence of $K$ block encoding unitaries $(U_{A_i})_{i=1}^K$,  any $\circclass_{\vec{U}_A, K,m} (\vec{V}, Q)$~circuit which implements an exact multiplication of block encodings using $m<K-1$ measurement ancillae is an \textbf{exact compression gadget (ECG)}.
\end{definition}

In this subsection, we will discuss the original ECG proposal of \cite{low2019Hamiltonian} and then prove a lower bound on the number of measurement ancillae required to implement \emph{any} ECG within the \circclass~circuit class. With this lower bound, we establish that the \cite{low2019Hamiltonian} ECG is in fact optimal in terms of number of measurement ancillae used. Therefore, the only way to use less measurement ancillae is to move to an approximate model of compression, as will be discussed in the next subsection.

\subsubsection{The \texorpdfstring{\cite{low2019Hamiltonian}}{[LW19]} Exact Compression Gadget} \label{sec:lw_dcg}

In their work on quantum simulation via truncated Dyson series, Low and Wiebe \cite{low2019Hamiltonian} proposed an ECG requiring only $m=\lceil \log_2 (K+1)\rceil$ measurement ancillae. Note, however, that their construction did not take advantage of the fact that we can determine whether the $k^{th}$ block-encoding was successful simply via the measurement outcome on the $a$-qubit block encoding ancilla register (it will have outcome $0^a$ if the block encoding was successful and outcome $x \in\{0,1\}^a\backslash 0^a$ if unsuccessful). Thus, we can implement their proposal within the \circclass~circuit class using only $\lceil \log_2 K \rceil$ measurement ancillae as follows (the gadget is a special case of the circuit depicted in \Cref{fig:add_gadget}).

\begin{definition}[\cite{low2019Hamiltonian} Exact Compression Gadget] \label{def:lw_dcg}
    For a sequence of $K$ block encoding unitaries $(U_{A_i})_{i=1}^K$, the \cite{low2019Hamiltonian} exact compression gadget is implemented by a $\circclass_{\vec{U}_A, K,m} (\vec{V}, Q)$~circuit with $m=\lceil \log_2 (K)\rceil$ measurement ancillae, $Q=I_m$, and   
    \begin{align}
        V_i  = \textnormal{\addm} \quad \forall i \in [K-1],
    \end{align}
    where  $\textnormal{\addm} \ket{c} = \ket{c+1 \bmod{2^m}}$ is the addition operation mod-$2^m$.
\end{definition}
To see gain intuition for why this DCG successfully implements a DMBE, note that the $m$-qubit measurment ancillae register can count bit strings up to $2^m = 2^{\lceil \log_2 (K+1)\rceil}\geq K+1$. The register is initialized to $\ket{0^m}$ and, for each bad ($\perp$) measurement, $+1$ is added, mapping to a basis state $\ket{x} \neq \ket{0}$. Furthermore, since at most, the \addm operation is applied $K$ times and the addition is at least mod-$(K+1)$, there will never be a case in which the modulo maps the sum back to the $\ket{0}$ state. Thus, if all measurements are good, the measurement register will remain in the $\ket{0^m}$ state and, for any bad measurement sequence, the measurement register will be in a basis state $\ket{x}\neq\ket{0}$. Therefore, come measurement time, if we measure the $\ket{0^m}$ state, the final state in the computation register is accepted. Otherwise, the final state is rejected.

\subsubsection{An Ancilla Lower-Bound for Exact Compression Gadgets} \label{sec:lb}
We will now prove a tight lower bound on the number of measurement ancillae necessary to implement an ECG and, thus, EMBE within the \circclass~circuit class.

\begin{theorem}(ECG Ancilla Lower-Bound) \label{thm:ancilla_lb}
    Any $\circclass_{\vec{U}_A, K,m} (\vec{V}, Q)$~circuit that implements an exact multiplication of $K$ block encodings requires  at least $m=\lceil\log_2(K)\rceil$ measurement ancillae.
\end{theorem}
\begin{remark}
    This lower bound is tight, since the modified \cite{low2019Hamiltonian} ECG saturates this bound.
\end{remark}
\begin{proof}[Proof of \Cref{thm:ancilla_lb}]
    In order to implement a DMBE, we must ensure that we have enough degrees of freedom (measurement ancillae) to distinguish two cases: 1) all intermediate measurements are $0^a$ and 2) any combination of intermediate measurements such that at least one is not $0^a$. 

    Note that we can directly determine whether or not the $K^{th}$ block-encoding was successful via our ultimate measurement of the $a$-qubit block encoding ancilla register. Therefore, we only need to determine the success of the first $K-1$ intermediate block encodings. If we think of each of these intermediate measurements as taking value $0^a$ or value $\perp=($not $0^a)$, then the set of all possible intermediate measurement outcomes is $\calM = \{0^a, \perp\}^{K-1}$, such that $|\calM|=2^{K-1}$. Our goal is to distinguish the $\{0^a\}^{K-1}$ outcome from the $\calM \backslash \{0^a\}^{K-1}$ outcomes. 

    Leveraging the \circclass~circuit structure, described in \Cref{thm:simplify}, we can reason about the number of ancillary degrees of freedom needed to distinguish these measurement outcomes. Let $\calS_0$ denote the intermediate measurement indices corresponding to good $0^a$ outcomes after the deferred measurement. We will define $\calS_\perp=[K]\backslash \calS_0$ to be indices corresponding to bad $\perp$ outcomes. Thus, before the deferred measurement, the measurement ancilla register of a $\circclass_{\vec{U}_A, \vec{\Pi}} (\vec{V}, Q)$~circuit will contain the state 
    \begin{align}
        \ket{\phi} = Q \left(\prod_{i \in \calS_\perp} V_i\right) \ket{0^m}.
    \end{align}
    Note that if all the measurements are good, i.e. $\calS_0=[K-1]$ and $\calS_\perp=\emptyset$, the measurement ancilla register will simply contain the state $\ket{\phi_0}=Q\ket{0^m}$. At the end of the computation, to distinguish ``good'' from ``bad'' measurement sequences, we must perform a projective measurement onto the basis $\{\good,\bad\}$, with projectors
    \begin{align}
        \good &:= Q\ketbra{0^m}{0^m} Q^\dagger  \\
        \bad &:= I- \good.
    \end{align}

    With this projective measurement basis, if all the measurements are good, then
    \begin{align}
        \bra{\phi_0}\good\ket{\phi_0} = \bra{0^m} Q^\dagger Q\ketbra{0^m}{0^m} Q^\dagger Q \ket{0^m}=1.
    \end{align}
    Therefore, in order to determinstically distinguish this state from all the bad measurement outcome sequences, there must exist sufficient ancilliary degrees of freedom to ensure that, for all $\calS_\perp \subseteq [K]$ such that $\calS_\perp \neq \emptyset$, 
    \begin{align}
        \bra{\phi}\bad\ket{\phi} &= 1- \bra{0^m} \left(\prod_{i \in \calS_\perp} V_i\right)^\dagger \ketbra{0^m}{0^m} \prod_{i \in \calS_\perp} V_i \ket{0^m}=1-\left|\bra{0^m} \prod_{i \in \calS_\perp} V_i \ket{0^m}\right|^2 = 1. 
    \end{align}
    This implies that 
    \begin{align}
        \bra{0^m} \prod_{i \in \calS_\perp} V_i \ket{0^m} = 0, \quad \forall \calS_\perp \subseteq [K-1]~\text{ s.t. }\calS_\perp \neq \emptyset,
    \end{align}
    meaning the set of states
    \begin{align}
        \left\{V_1 \ket{0^m},V_2 \ket{0^m}, V_2 V_1 \ket{0^m}, V_3 \ket{0^m},..., \prod_{i\in [K-1]} V_i \ket{0^m}\right\}
    \end{align}
    must all be perpendicular to the state $\ket{0^m}$. 

    In order to determine the minimum possible number of measurement ancillae $m$ needed to ensure that all these constraints are satisfied and states are perpendicular, we will reason about the smallest possible Hilbert space in which all these states can be orthogonal. Let $\widetilde{\calH}_i$ be the Hilbert space containing all possible measurement ancilla states orthogonal to $\ket{0^m}$ after measurement $i$. That is,
    \begin{align}
        \widetilde{\calH}_0 &= \spant\{\emptyset\}, 
        \\
        \widetilde{\calH}_1 &= \spant\{V_1 \ket{0^m}\}, \\
        \widetilde{\calH}_2 &= \spant\{V_1 \ket{0^m},V_2 \ket{0^m}, V_2 V_1 \ket{0^m}\}, \\
        \widetilde{\calH}_3 &= \spant\{V_1 \ket{0^m},V_2 \ket{0^m}, V_3 \ket{0^m}, V_2 V_1 \ket{0^m}, V_3 V_2 \ket{0^m}, V_3 V_1 \ket{0^m}, V_3 V_2 V_1 \ket{0^m}\} \\
        & \vdots \\
        \widetilde{\calH}_{i+1} &= \spant\{V_{i+1}\ket{0^m}, V_{i+1} \widetilde{\calH}_{i}, \widetilde{\calH}_{i}\} \label{eqn:Hi+1}
    \end{align}
    We will now prove that,
    \begin{align}
        \dim(\widetilde{\calH}_{i+1}) \geq \dim(\widetilde{\calH}_i)+1, \quad \forall i \in [K-1],
    \end{align}
    via proof by contradiction. 

    We begin by assuming that $\dim(\widetilde{\calH}_{i+1}) = \dim(\widetilde{\calH}_i)$. Since $\widetilde{\calH}_{i+1} \supseteq \widetilde{\calH}_{i}$, this implies that $\widetilde{\calH}_{i+1} = \widetilde{\calH}_{i}$. Thus, there exists a bijection between $\widetilde{\calH}_{i+1}$ and $ \widetilde{\calH}_{i}$, governed by multiplication by the $V_{i+1}$ unitary matrix and its inverse $V_{i+1}^\dagger$. From \Cref{eqn:Hi+1}, since $V_i \ket{0^m}$ is an element of $\widetilde{\calH}_{i+1}$, via the inverse mapping,  
    $V_i^\dagger V_i \ket{0^m}=\ket{0^m} \in \widetilde{\calH}_i$. This, however, is a contradiction, since $\widetilde{\calH}_i$ was defined to be the set of all possible measurement ancilla states \emph{orthogonal} to $\ket{0^m}$ after measurement $i$.

    Following from our proof, after $K-1$ measurements the dimension of Hilbert space orthogonal to $\ket{0^m}$ is lower-bounded as $\dim(\widetilde{\calH}_{K-1}) \geq K-1$. Note, however, that the full Hilbert space of the measurement ancillae, $\calH_{K-1}$ must also contain $\ket{0^m}$ state, meaning
    \begin{align}
        \calH_{K-1} = \spant\{\ket{0^m}, \widetilde{\calH}_{K-1}\}, \quad \text{s.t. } \dim(\calH_{K-1}) \geq K.
    \end{align}
    Therefore, the number of measurement ancillae needed to produce an $\calH_{K-1}$ Hilbert space is
    \begin{align}
        m \geq \lceil\log_2 K\rceil,
    \end{align}
    obtaining our desired lower-bound.
\end{proof}


\subsection{Approximate Compression Gadgets}
In the standard block encodings literature, oftentimes creating exact block encodings can be too challenging or demanding. As such, there exists a notion of \emph{approximation} for block encodings. In particular, the matrix $U_B$ is considered an $\epsilon$-precise block encoding of matrix $B$ if
\begin{align}
    \| B - \bra{0^a} U_B \ket{0^a} \| \leq \epsilon,
\end{align}
where $\| \cdot \|$ denotes the operator norm. Inspired by this measure of ``closeness'' to a desired block encoding, in this section, we will introduce the notions of \emph{approximate} multiplication of block encodings and \emph{approximate} compression gadgets. Leveraging these, we will show that in certain regimes of multiplication of block encodings, approximate compression gadgets can be constructed that achieve high-precision multiplication of block encodings while requiring only a constant number of measurement ancillae---surpassing the previously established EMBE lower-bound.

We begin by defining \emph{approximate} multiplication of block encodings (AMBE) and \emph{approximate} compression gadgets (ACGs) as follows.
\begin{definition}[$\epsilon$-Approximate Multiplication of Block Encodings ($\epsilon$-AMBE)]
    We will refer to an $\circclass_{\vec{U}_A, K,m} (\vec{V}, Q)$ circuit as an  \textbf{approximate multiplication of block encodings ($\epsilon$-AMBE)} if
    \begin{align} 
        \| A_{[K]} - \bra{0^{m+a}} \circclass_{\vec{U}_A, K,m} (\vec{V}, Q) \ket{0^{m+a}} \| \leq \epsilon,
    \end{align}
    thereby implementing an $\epsilon$-precise block encoding of the desired  multiplication $A_{[K]}$.
\end{definition}
\noindent Note that from this definition, it follows that for any input $\ket{\psi}$, the output state of an $\epsilon$-approximate multiplication of block encodings circuit is $\epsilon$-close to the desired $A_{[K]}\ket{\psi}$ output state.
\begin{claim} \label{thm:closeness}
    Let $U_{\widetilde{A}_{[K]}}$ denote the unitary implemented by an $\epsilon$-approximate multiplication of block encodings circuit, such that $\widetilde{A}_{[K]} = \bra{0^{m+a}} U_{\widetilde{A}_{[K]}} \ket{0^{m+a}}$. For an arbitrary input state $\ket{\psi}$, let $\ket*{\widetilde{\phi}} = \widetilde{A}_{[K]} \ket{\psi}$ denote the post-selected $\epsilon$-approximate circuit output and let $\ket{\phi} = A_{[K]} \ket{\psi}$ denote the desired exact output. Then, the approximate and desired outputs have fidelity
    \begin{align} \label{eqn:fidelity}
        |\bra{\phi} \ket*{\widetilde{\phi}} |^2 \geq 1-\epsilon^2.
    \end{align}
\end{claim}
\begin{proof}[Proof of \Cref{thm:closeness}]
    From the definition of $\epsilon$-AMBE, we have that
    \begin{align}
        \| A_{K} - \widetilde{A}_{[K]}\| \leq \epsilon.
    \end{align}
    Since the input state to the circuit $\ket{\psi}$ is normalized, i.e. $\|\ket{\psi}\|=1$, this implies that 
    \begin{align}
        \| \ket{\phi}- \ket*{\widetilde{\phi}} \| = \| A_{K} \ket{\psi}- \widetilde{A}_{[K]} \ket{\psi}\| \leq \| A_{K} - \widetilde{A}_{[K]}\|\cdot \|\ket{\psi}\| \leq \epsilon.
    \end{align}
    By the properties of the operator norm,
    \begin{align}
        \epsilon^2 \geq \| \ket{\phi}- \ket*{\widetilde{\phi}} \|^2 = (\bra{\phi}- \bra*{\widetilde{\phi}})(\ket{\phi}- \ket*{\widetilde{\phi}}) = 2 - 2\Re{\bra{\phi}\ket*{\widetilde{\phi}}}, 
    \end{align}
    which implies that 
    \begin{align}
        |\bra{\phi}\ket*{\widetilde{\phi}}| \geq \Re{\bra{\phi}\ket*{\widetilde{\phi}}} \geq 1-\frac{\epsilon^2}{2}.
    \end{align}
    Via some arithmetic manipulation, we obtain the desired lower-bound:
    \begin{align}
        |\bra{\phi}\ket*{\widetilde{\phi}}|^2 \geq \left(1-\frac{\epsilon^2}{2}\right)^2=1-\epsilon^2 + \frac{\epsilon^4}{4} \geq 1-\epsilon^2.
    \end{align}
    This concludes the proof.
\end{proof}


In the last section, we established that \emph{exact} MBE can be implemented optimally with $m = \lceil \log_2 K\rceil$ measurement ancillae. Therefore, we will require that an approximate compression gadget use less than this number of measurement ancillae. 
\begin{definition}[$\epsilon$-Approximate Compression Gadget ($\epsilon$-ACG)] 
    For a sequence of $K$ block encoding unitaries $(U_{A_i})_{i=1}^K$,  any $\circclass_{\vec{U}_A, K,m} (\vec{V}, Q)$~circuit which implementing $\epsilon$-approximate multiplication of block encodings using $m<\lceil \log_2 K \rceil$ measurement ancillae is an \textbf{$\epsilon$-approximate compression gadget ($\epsilon$-ACG)}.
\end{definition}
\noindent  With these general definitions, we will now propose a specific compression gadget--the $p$-Modular Addition Compression Gadget ($p$-MACG)--and prove that it is an $\epsilon$-ACG for a large regime of multiplication of block encodings.

\subsubsection{The \texorpdfstring{$p$}{p}-Modular Addition Compression Gadget}
Our proposal for an $\epsilon$-ACG is heavily inspired by the \cite{low2019Hamiltonian} ECG (as described in \Cref{sec:lw_dcg}). Specifically, we re-parameterize the \addm~addition operations of the \cite{low2019Hamiltonian} ECG as $\addp$ addition operations, where $p\in \mathbb{Z}$ is a constant (relative to $K$). We refer to this compression gadget as the $p$-Modular Addition Compression Gadget ($p$-MACG), since instead of doing addition modulo $2^m=K$ as in the \cite{low2019Hamiltonian} ECG, we perform addition modulo-$2^p$. The $\addp$ operation is implementable with only $p=\calO(1)$ qubits, which implies that the $p$-MACG requires only $m=p<\lceil \log_2 K\rceil$ measurement ancillae. Formally, the $p$-MACG is defined within the \circclass~circuit class as follows.

\begin{definition}[$p$-Modular Addition Compression Gadget ($p$-MACG)]
    For constant $p>1$ and a sequence of $K$ block encoding unitaries $(U_{A_i})_{i=1}^K$, with $\eta_{\max}=\calO(1/K)$, the \textbf{$p$-Modular Addition Compression Gadget ($p$-MACG)} is an $\circclass_{\vec{U}_A, \vec{\Pi}} (\vec{V}, Q)$~circuit composed of: $m=p=\calO(1)$ measurement ancillae, $Q=I_m$, and   
    \begin{align}
        V_i  = \addp, \quad \forall i \in [K-1],
    \end{align}
    where $\addp \ket{x} = \ket{x + 1 \bmod{2^p}}$.
\end{definition}
\noindent All that remains is to show that the $p$-MACG achieves an $\epsilon$-precision block encoding of the desired multiplication and is, thus, an $\epsilon$-ACG.

\subsubsection{Surpassing the Ancilla Lower-Bound for Exact Compression Gadgets}

We will now show that for a broad regime of multiplication of block encoding sequences, the $p$-MACG is an $\epsilon$-ACG where $\epsilon = \calO(1/K^{2^p})$.

We begin by specifying the regime of multiplication of block encoding sequences that we will consider. Suppose we have a sequence of $K$ block encoding unitaries $(U_{A_i})_{i=0}^{K-1}$, such that
\begin{align}
    A_i = \bra{0^a} U_{A_i} \ket{0^a},
\end{align} 
where $A_i$ acts on $n$ qubits and  $U_{A_i}$ acts on $n+a$ qubits. Performing an asymptotic number of multiplications of block encodings only makes sense if each block encoding is fairly close to the identity, i.e., for all $i$,
\begin{align} \label{eqn:id_constrain}
    \|U_{A_i}-I\| \leq \eta_i
\end{align}
for some small $\epsilon_i << 1$. Since $\eta_i$ captures the deviation of the $i^\text{th}$ block encoding matrix from the identity, we will refer to $\eta_i$ as the $i^\text{th}$ ``deviation coefficient''. Block encodings of this form can be decomposed as
\begin{align} \label{eqn:block_enc}
    U_{A_i} = \begin{bmatrix}
        \bra{0^a} U_{A_i} \ket{0^a} & \bra{0^a} U_{A_i} \ket{\perp} \\
        \bra{\perp} U_{A_i} \ket{0^a} & \bra{\perp} U_{A_i} \ket{\perp}
    \end{bmatrix} = \begin{bmatrix}
        A_i & B_i \\
        C_i & D_i
    \end{bmatrix}.
\end{align}
This implies that
\begin{align}
    U_{A_i} = \ketbra{0^a}{0^a} \otimes A_i + \ketbra{0^a}{\perp} \otimes B_i + \ketbra{\perp}{0^a} \otimes C_i +  \ketbra{\perp}{\perp} \otimes D_i 
\end{align}
where \Cref{eqn:id_constrain} imposes that
\begin{align} \label{eqn:op_norm}
    1-\eta_i \leq \| A_i \| \leq 1+\eta_i, \quad \quad \| B_i \| \leq \eta_i, \quad \| C_i \| \leq \eta_i, \quad 1-\eta_i \leq \| D_i \| \leq 1+\eta_i.
\end{align}
Finally, we will denote the maximal deviation coefficient among all $K$ block encodings as
\begin{align}
    \eta_{\text{max}} = \max_{i \in [K]} \eta_i.
\end{align}

With this new notation, we will now prove that in the regime of MBEs where $\eta=\calO(1/K)$, (despite only requiring a constant number of measurement ancillae) a $p$-ACG can implement an $\epsilon$-precise block-encoding of the desired multiplication with $\epsilon=\calO(1/K^{2^p})$.
\begin{theorem} \label{thm:main_mbe}
    Let $(U_{A_i})_{i=1}^K$ be a sequence of $K$ block encodings, with maximal deviation coefficent $\eta_{\max}=\frac{c}{K}$ for some constant $c\in \mathbb{R}$.
    For any $p\in \mathbb{Z}$ such that $p=\calO(1)$, let $U_{pACG}$ be the unitary implemented by the $p$-ACG on $(U_{A_i})_{i=1}^K$. The  $p$-ACG obtains an $\epsilon$-precise block encoding of the desired multiplication sequence $A_{[K]}$, i.e.
    \begin{align}
        \| A_{[K]} - \bra{0^{p+a}} U_{pACG} \ket{0^{p+a}} \| \leq \epsilon, 
    \end{align}
    with inverse-polynomial precision in $K$:
    \begin{align}
        \epsilon = 2 e^c \cdot \left(\frac{e \cdot c^2 }{K\cdot 2^p}\right)^{2^p} = \calO\left(\frac{1}{K^{2^p}}\right).
    \end{align}
\end{theorem}
\begin{proof}[Proof of \Cref{thm:main_mbe}]
    For ease of notation, we will denote the block encoding error as
    \begin{align}
        \err(U_{pACG}) &= \| A_{[K]} - \bra{0^{m+a}} U_{pACG} \ket{0^{m+a}} \|.
    \end{align}
    Thus, the block encoding achieved by the $p$-ACG can be decomposed as:
    \begin{align}
        \bra{0^{p+a}}& U_{pACG} \ket{0^{p+a}} \\
        &= \sum_{x \in \{0,1\}^{K-1}} \bra{0^p}~\addp^{|x|}~\ket{0^p} \cdot \bra{0^a} U_{A_K}\left(\prod_{i=1}^{K-1} \pzeroa^{1-x_i} \pperp^{x_i} U_{A_i}\right) \ket{0^a} \\
        &=  \braket{0^p}{0^p} \cdot \bra{0^a} U_{A_K} \left(\prod_{i=1}^{K-1} \pzeroa U_{A_i}\right) \ket{0^a} \\
        & \quad + \sum_{x \in \{0,1\}^{K-1}\backslash 0^{K-1}} \bra{0^p}~\addp^{|x|}~\ket{0^p} \cdot  \bra{0^a} U_{A_K} \left(\prod_{i=1}^{K-1} \pzeroa^{1-x_i} \pperp^{x_i} U_{A_i} \right) \ket{0^a} \\
        &= A_{[K]} + \sum_{x \in \{0,1\}^{K-1}\backslash 0^{K-1}} \bra{0^p}~\addp^{|x|}~\ket{0^p} \cdot  \bra{0^a} U_{A_K} \left(\prod_{i=1}^{K-1} \pzeroa^{1-x_i} \pperp^{x_i} U_{A_i} \right) \ket{0^a}. \label{eqn:u_hr}
    \end{align}
    From hereon, we will denote the block encoded matrix corresponding to the bad measurement sequence governed by string $x$ as
    \begin{align}
        \seq = \bra{0^a} U_{A_K} \left(\prod_{i=1}^{K-1} \pzeroa^{1-x_i} \pperp^{x_i} U_{A_i} \right) \ket{0^a} .
    \end{align}
    Furthermore, note that
    \begin{align}
        \bra{0^p}~\addp^{|x|}~\ket{0^p} = \delta \{ |x| = 0 \bmod{2^p}\}.
    \end{align}
    Thus, \Cref{eqn:u_hr} further simplifies to
    \begin{align} \label{eqn:uhr_decomp}
        \bra{0^{p+a}} U_{pACG} \ket{0^{p+a}} &= A_{[K]} + \sum_{x \in \{0,1\}^{K-1}\backslash 0^{K-1}} \seq \cdot \delta \{ |x| = 0 \bmod{2^p}\} \\
        &= A_{[K]} + \sum_{\substack{x \in \{0,1\}^{K-1}\backslash 0^{K-1}:\\|x| = 0 \bmod{2^p}}} \seq, 
    \end{align}
    which implies that the block encoding error can be upper-bounded as
    \begin{align}
        \err(U_{pACG}) &= \| A_{[K]} - \bra{0^{p+a}} U_{HR} \ket{0^{p+a}} \| = \left\| \sum_{\substack{x \in \{0,1\}^{K-1}\backslash 0^{K-1}:\\|x| = 0 \bmod{2^p}}} \seq  \right\|  \leq  \sum_{\substack{x \in \{0,1\}^{K-1}\backslash 0^{K-1}:\\|x| = 0 \bmod{2^p}}} \| \seq \|.  \label{eqn:be_temp}
    \end{align}
    We will now show that the $\|\seq\|$ terms in this expression have a simple upper-bound in terms of $\eta_{\max}$, $|x|$, and $K$.
    \begin{claim} \label{thm:seq_bound}
        $\|\seq\| \leq (\eta_{\max})^{2|x|}\cdot (1+\eta_{\max})^{K}$
    \end{claim}
    \begin{proof}[Proof of \Cref{thm:seq_bound}]
        For $x \in \{0,1\}^{K-1}\backslash 0^{K-1}$, the $\seq$ terms
        encode all possible ``bad'' multiplication sequences. The length-$(K-1)$ bit-string $x$ encodes whether each measurement outcome was ``good''  (0) or ``bad'' (1). Therefore, in the length-$(K+1)$ bit-string sequence $\widetilde{x}=(0,x,0)$, each time a 0 is followed by a 1, this represents a transition between the good and bad ancilla subspaces. This corresponds to the application of one of the off-diagonal block encoded matrices, i.e. $B_i$ or $C_i$ in \Cref{eqn:block_enc}, which both have operator norm $\leq \eta_i$ (\Cref{eqn:op_norm}). Meanwhile, if a 0 is followed by a 0 or a 1 is followed by a 1, the measurement leaves the system in the good or bad subspace, respectively. This corresponds to the application of one of the off-diagonal block encoded matrices, i.e. $A_i$ or $D_i$ in \Cref{eqn:block_enc}, which both have operator norm $\leq 1+\eta_i$ (\Cref{eqn:op_norm}). 

        Let $\Delta x$ denote the length-$K$ bit string that tracks these differences in $\widetilde{x}$, i.e.
        \begin{align}
            \Delta x_i = \begin{cases}
                0, &\text{ if } \widetilde{x}_{i+1} = \widetilde{x}_i\\
                1, &\text{ if } \widetilde{x}_{i+1} \neq \widetilde{x}_i 
            \end{cases}.
        \end{align}
        Therefore, leveraging the fact that $|\Delta x| \leq 2|x|$,
        \begin{align}
             \|\seq\| & \leq (\eta_{\max})^{|\Delta x|}\cdot (1+\eta_{\max})^{K-|\Delta x|} \leq (\eta_{\max})^{2|x|}\cdot (1+\eta_{\max})^{K}.
        \end{align}
        This concludes the proof of \Cref{thm:seq_bound}.
    \end{proof}
    \noindent Plugging this into the block encoding error upper-bound of \Cref{eqn:be_temp},
    \begin{align}
        \err(U_{pACG}) &\leq  \sum_{\substack{x \in \{0,1\}^{K-1}\backslash 0^{K-1}:\\|x| = 0 \bmod{2^p}}} (\eta_{\max})^{2|x|}\cdot (1+\eta_{\max})^{K} \\
        & = (1+\eta_{\max})^{K} \cdot \sum_{\substack{r\in[K-1]:\\r = 0 \bmod{2^p}}} \binom{K-1}{r} (\eta_{\max})^{2r}. \label{thm:ub_temp}
    \end{align}
    We will now derive an upper-bound for the summation in this expression.
    \begin{claim} \label{thm:sum_bound}
        $\sum_{\substack{r\in[K-1]:\\r = 0 \bmod{P}}} \binom{K-1}{r} (\eta_{\max})^{2r} \leq 2 \left(\frac{e \cdot \eta_{\max}^2 \cdot K}{P}\right)^P$
    \end{claim}
    \begin{proof}[Proof of \Cref{thm:sum_bound}] 
    We begin by re-expressing the sum as
        \begin{align} \label{eqn:inter}
            \sum_{\substack{r\in[K-1]:\\r = 0 \bmod{P}}} \binom{K-1}{r} (\eta_{\max})^{2r} = \sum_{j=1}^{\lfloor(K-1)/P\rfloor} \binom{K-1}{j P} (\eta_{\max})^{2jP}.
        \end{align}
        Since $\eta_{\max} < 1$, we note that the largest contribution in this sum comes from the $j=1$ term
        \begin{align}
            T_1 = \binom{K-1}{P} (\eta_{\max})^{2P} \leq \left(\frac{e(K-1)}{P}\right)^P(\eta_{\max})^{2P} = e^P \cdot \left(\eta_{\max}^2 \cdot \frac{K-1}{P}\right)^P.
        \end{align}
        Furthermore, note that the ratio of the $(j+1)$st to the 1st term is:
        \begin{align}
            R_{j+1} &= \frac{\binom{K-1}{(j+1) P} (\eta_{\max})^{2(j+1)P}}{\binom{K-1}{P} (\eta_{\max})^{2P}} = (\eta_{\max})^{2Pj} \cdot  \prod_{i=1}^{jP} \left(\frac{K-P-i}{P+i}\right)  \leq \left(\eta_{\max}^2 \cdot \frac{K-1}{P}\right)^{Pj}.
        \end{align}
        From hereon, we will denote
        \begin{align}
            r = \left(\eta_{\max}^2 \cdot \frac{K-1}{P}\right)^P.
        \end{align}
        With this notation, we have that
        \begin{align}
            T_1 \leq r\cdot e^P, \quad R_{j+1} \leq r^j.
        \end{align}
        Furthermore, since we are in the regime where $\eta_{\max} = \calO(1/K)$, note that $r=\calO(1/K^P)<1$. 
        With this, we can decompose \Cref{eqn:inter} by factoring out the dominating $T_1$ term and upper-bounding the resultant expression via a geometric series  as
        \begin{align}
            \sum_{j=1}^{\lfloor(K-1)/P\rfloor} \binom{K-1}{j P} (\eta_{\max})^{2jP} &= T_1 \left[1+\sum_{j=1}^{\lfloor(K-1)/P\rfloor-1}R_{j+1}\right] \leq T_1 \left[1+\sum_{j\geq1}R_{j+1}\right] \\
            &= T_1 \left[1+\sum_{j\geq1}r^j\right] = \frac{T_1}{1-r} \leq e^P \cdot \frac{r}{1-r}
        \end{align}
        Leveraging the fact that $r=\calO(1/K^P) \leq 1/2$, we achieve the desired bound,
        \begin{align}
            \sum_{j=1}^{\lfloor(K-1)/P\rfloor} \binom{K-1}{j P} (\eta_{\max})^{2jP} \leq e^P \cdot \frac{r}{1-r} \leq e^P \cdot \frac{r}{1-\frac{1}{2}} \leq 2e^Pr \leq 2 \left(\frac{e \cdot \eta_{\max}^2 \cdot K}{P}\right)^P.
        \end{align}
        This concludes the proof of \Cref{thm:sum_bound}.
    \end{proof}
    \noindent Plugging this upper-bound into \Cref{thm:ub_temp}, and leveraging the fact that $(1+x)^K \leq e^{Kx}$ for $x \in (0,1)$, the block encoding error upper-bound simplifies to
    \begin{align}
        \err(U_{pACG}) \leq (1+\eta_{\max})^{K} \cdot 2 \left(\frac{e \cdot \eta_{\max}^2 \cdot K}{P}\right)^P \leq e^{K \cdot \eta_{\max}}\cdot 2 \left(\frac{e \cdot \eta_{\max}^2 \cdot K}{P}\right)^P.
    \end{align}
    Plugging in $\eta_{\max} = c/K$, we obtain the desired error bound, 
    \begin{align}
        \err(U_{pACG}) \leq  2e^c \cdot  \left(\frac{e \cdot c^2}{K \cdot P}\right)^P = 2e^c \cdot  \left(\frac{e \cdot c^2}{K \cdot 2^p}\right)^{2^p}= \calO\left(\frac{1}{K^{2^p}}\right).
    \end{align}
    This concludes the proof of \Cref{thm:main_mbe}.
\end{proof}

\begin{corollary} \label{thm:seq_cor}
    For a given error $\epsilon \in (0,1)$, a $p$-MACG can achieve an $\epsilon$-precise for any multiplication of block encoding sequences $(U_{A_i})_{i=1}^K$ satisfying $\eta_{\max}=c/K$ and 
    \begin{align} \label{eqn:seq_lb}
        K \geq \frac{e c^2}{2^p} \cdot \left(\frac{2}{\epsilon}\right)^{1/2^p}.
    \end{align}
\end{corollary}
\begin{proof}[Proof of \Cref{thm:seq_cor}]
    By \Cref{thm:main_mbe}, we have that $\err(U_{pACG}) \leq \epsilon$ if $\eta_{\max}=c/K$ and
    \begin{align}
        2e^c \cdot  \left(\frac{e \cdot c^2}{K \cdot 2^p}\right)^{2^p} \leq \epsilon.
    \end{align}
    Solving this expression in term of $K$ results in the lower-bound of \Cref{eqn:seq_lb}.
\end{proof}

\subsection{Oblivious Amplitude Amplification for Multiplication of Block Encodings} \label{sec:approx_oaa}
As the number of measurements $K$ in a multiplication of block encoding sequence increases, the probability of the all-good-measurement sequence $\{0^a\}^K$ decreases. Thus, we would like a way to boost the probability of measuring this sequence. 

To this end, we will briefly describe the standard quantum algorithms subroutines of amplitude amplification (AA) [\Cref{sec:aa}] and oblivious amplitude amplification (OAA) [\Cref{sec:oaa}]. We will then show how OAA can be tailored to MBE, so as to boost the probability of measuring the all-good-measurement sequence. In particular, we will show that OAA can boost the probability to $\Omega(1)$ for EMBE [\Cref{sec:oaa_embe}] and  $\Omega(1-\eps^2)$ for $\eps$-AMBE [\Cref{sec:oaa_ambe}].

\subsubsection{Amplitude Amplification (AA)} \label{sec:aa}
Amplitude amplification (AA) was originally proposed by \cite{brassard2000quantum} and has become a standard sub-routine in quantum algorithms.
Suppose,
\begin{align}
    \ket{\psi_0} = \alpha_\text{good}\ket{\psi_\text{good}} + \alpha_\text{bad}\ket{\psi_\text{bad}},
\end{align}
where $|\alpha_\text{good}|^2<<1$ is the probability of being in the desired ``good'' state $\ket{\psi_\text{good}}$ and $|\alpha_\text{bad}|^2=1-|\alpha_\text{good}|^2$ is the probability of being in any orthogonal ``bad'' state $\ket{\psi_\text{bad}}$. AA enables us to map $\ket{\psi_0}$ to a state with large overlap with $\ket{\psi_\text{good}}$ or, in other words, AA amplifies the amplitude of the desired $\ket{\psi_\text{good}}$ state.

In terms of implementation, AA requires access to two reflection oracles. The first is a reflection about the $\ket{\psi_\text{good}}$ state,
\begin{align}
    R_\text{good}=I_n-2\ketbra{\psi_\text{good}}{\psi_\text{good}},
\end{align}
and the second is a reflection with respect to the initial $\ket{\psi_0}$ state,
\begin{align}
    R_{\psi_0}=2\ketbra{\psi_0}{\psi_0}-I_n.
\end{align}
Following a similar procedure to Grover's algorithm, these are used to implement the Grover iterate
\begin{align}
    G = R_{\psi_0}R_\text{good}.
\end{align}
Letting $k=\bigO{1/|\alpha_\text{good}|}$, $G^k\ket{\psi_0}$ maps $\ket{\psi_0}$ to a state with $\Omega(1)$ overlap with $\ket{\psi_\text{good}}$.

\subsubsection{Oblivious Amplitude Amplification (OAA)} \label{sec:oaa}

The main downside of AA is that knowledge of the ``good'' state $\ket{\psi_\text{good}}$ is required in order to implement the reflection oracle $R_\text{good}$. However, if $\ket{\psi_\text{good}}$ is unknown or inefficient to implement, this  requirement can be avoided with block encodings and so-called ``signal'' qubits. The form of AA we will now describe, which is ``oblivious'' to the precise form of the good state, is known as oblivious amplitude amplification (OAA) and was originally introduced by \cite{low2016HamSimQubitization}.

In addition to $n$ qubits encoding the good and bad states, the initial state will also include $m$ signal ancilla qubits, distinguishing the good and bad subspaces. Specifically,
\begin{align} \label{eqn:aa}
    \ket{\psi^m_0} = U_{\psi^m_0} \ket{0^m}\ket{0^n} = \alpha_\text{good}\ket{0^m}\ket{\psi_\text{good}} + \alpha_\text{bad}\ket{\perp}\ket{\psi_\text{bad}}.
\end{align}
The signal qubits have value $\ket{0^m}$ only if the main register is in the good state, $\ket{\psi_\text{good}}$. When the main register is in a bad state, the signal qubits are in a state orthogonal to  $\ket{0^m}$, denoted $\ket{\perp}$. Thus, for $\Pi=\ketbra{0^m}{0^m}$,
\begin{align}
    (\Pi \otimes I_n)\ket{0^m}\ket{\psi_\text{good}} &= \ket{0^m}\ket{\psi_\text{good}} \quad \text{and}\quad 
    (\Pi \otimes I_n)\ket{\perp}\ket{\psi_\text{bad}} = 0,
\end{align}
meaning that the good subspace can be easily identified by measuring $\ket{\psi^m_0}$'s signal ancillae and post-selecting the $0^m$ outcome. In expectation, $1/|\alpha_\text{good}|^2$ measurements of $\ket{\psi^m_0}$ would be required to obtain $\ket{\psi_\text{good}}$. Once again, we can improve this quadratically by leveraging AA.

Since the good and bad states have signal ancillae, the AA reflection oracles can be simplified. Namely, reflection about the good state reduces to reflection only about the signal ancillae,
\begin{align}
    R_\text{good} = (I_m-2\ketbra{0^m}{0^m}) \otimes I_n.
\end{align}
Meanwhile, the reflection about the initial state $\ket{\psi^m_0}$ is about both the main register and ancillae,
\begin{align}
    R_{\psi_0^m} = 2\ketbra{\psi^{m}_0}{\psi^{m}_0}-I_{m+n}.
\end{align}
Thus,  the Grover iterate is defined as $G = R_{\psi_0^m} R_\text{good}$. For $k=\bigO{1/|\alpha_\text{good}|}$, $G^k \ket{\psi^m_0}$ produces a state with $\Omega(1)$ overlap with $\ket{\psi_\text{good}}$.

\subsubsection{OAA for Exact Multiplication of Block Encodings}\label{sec:oaa_embe}

In an MBE circuit, each unitary $U_{A_i}$ has probability $p_i$ of the good $0^a$ ancilla measurement outcome and, thus, probability $1-p_i$ of a bad $\perp$ outcome. Thus, the desired all-good-measurements sequence $\{0^a\}^K$ has probability 
\begin{align} \label{eqn:probs}
    p = \prod_{i=1}^K p_i
\end{align}
which can be quite small depending on the number of measurements $K$ and individual measurement probabilities $p_i$. Furthermore, $\bigO{1/p}$ repetitions of the MBE circuit would be required in expectation. However, via OAA, the success probability can be coherently amplified to a constant value with quadractic queries to an EMBE circuit.

In this case, the OAA signal ancillae are the $m$ measurement ancillae and $a$ block encoding ancillae of the EMBE circuit, which together indicate whether the multiplication sequence was successful or not. Specifically, in the successful case, the main $n$-qubit register is in the desired state $\ket{\psi_\text{good}}=A_{[K]}\ket{\psi}$ and the $(m+a)$ signal ancillae in the state $\ket{0^{m+a}}$. In the unsuccessful case, the $(m+a)$ signal ancillae are in a state $\ket{\perp}$, orthogonal to $\ket{0^a}$, and the main $n$-qubit register is in a junk state $\ket{\psi_\text{bad}}$. 

Formally, denoting the unitary implemented by the EMBE circuit as $U_\embe$,
\begin{align}
    \ket{\psi_\embe} = U_\embe \ket{0^{m+a}} \ket{\psi_0} = \alpha_\text{good} \ket{0^{m+a}}\ket{\psi_\text{good}} + \alpha_\text{bad} \ket{\perp} \ket{\psi_\text{bad}},
\end{align}
where $|\alpha_\text{good}|^2=p$ as defined in \Cref{eqn:probs}.
This state is analogous to the initial state $\ket{\psi_0^m}$ in OAA (\Cref{eqn:aa}). Thus, to run OAA we construct the two reflection oracles: 
\begin{align}
    R_\text{good} &= (I_{m+a}-2\ketbra{0^{m+a}}{0^{m+a}}) \otimes I_{n} \\
    R_{\psi_\embe} &= 2\ketbra{\psi_\embe}{\psi_\embe}-I_{m+a+n}=U_{\psi_\embe}(2\ketbra{0^{m+a},\psi_0}{0^{m+a},\psi_0}-I_{m+a+n})U_{\psi_\embe}^\dagger,
\end{align}
and the Grover iterate $G = R_{\psi_\embe} R_\text{good}$. Letting $k=\calO(1/\sqrt{p})$, then $G^k \ket{\psi_\embe}$ produces a state with $\Omega(1)$ overlap with $\ket{0^{m+a}}\ket{\psi_\text{good}}$, as desired.

\subsubsection{OAA for Approximate Multiplication of Block Encodings} \label{sec:oaa_ambe}
To conclude, we will demonstrate how OAA can be used to coherently boost the probability of the all-good-measurement sequence, even in the setting of \emph{approximate} MBE. The OAA implementation for AMBE does not differ too much from that of EMBE, but the analysis is a bit more involved. In particular, we prove the following lemma.
\begin{lemma}[OAA for $\eps$-AMBE] \label{thm:oaa_ambe}
    Via repeated queries to an $\eps$-approximate multiplication of block encodings circuit, oblivious amplitude amplification can be used to boost the fidelity between the circuit output and the desired state to $\Omega(1-\eps^2)$.
\end{lemma}
\begin{proof}[Proof of \Cref{thm:oaa_ambe}]
    Let $U_\ambe$ denote the unitary implemented by an $\epsilon$-AMBE circuit. The key difference from EMBE is that the $\epsilon$-AMBE outputs a state of the form:
    \begin{align} \label{eqn:ambe_aa_state}
        \ket{\psi_\ambe} = U_\ambe \ket{0^{m+a}} \ket{\psi_0} = \alpha_\text{good} \ket{0^{m+a}}\ket{\psi_\text{good}} + \alpha_\text{wrong} \ket{0^{m+a}}\ket{\psi_\text{wrong}} + \alpha_\text{bad} \ket{\perp} \ket{\psi_\text{bad}}.
    \end{align}
    As for EMBE, $\ket{\psi_\text{good}}=A_{[K]}\ket{\psi}$ is the desired good state, with signal ancillae $\ket{0^{m+a}}$, and $\ket{\psi_\text{bad}}$ is a junk state with signal ancillae $\ket{\perp}$ (orthogonal to $\ket{0^{m+a}}$). However, for  $\epsilon$-AMBE there is an additional junk state $\ket{\psi_\text{wrong}}$, which has the same signal ancillae $\ket{0^{m+a}}$ as the good state $\ket{\psi_\text{good}}$. For ease of notation, we will denote the $n$-qubit sub-state with signal ancilla $\ket{0^{m+a}}$ as
    \begin{align}
        \ket{\psi_\text{sig}} = \frac{1}{\alpha_\text{sig}} \cdot \left(\alpha_\text{good} \ket{\psi_\text{good}} + \alpha_\text{wrong} \ket{\psi_\text{wrong}}\right),
    \end{align}
    where $\alpha_\text{sig}=\sqrt{|\alpha_\text{good}|^2+|\alpha_\text{wrong}|^2}$ is a normalization factor. Note that $\ket{\psi_\text{sig}}$ is the state obtained by post-selecting $\ket{\psi_\ambe}$ for the ancillae outcome $0^{m+a}$, i.e.
    \begin{align}
        \ket{\psi_\text{sig}} = (\bra{0^{m+a}} \otimes I_n) U_\ambe \ket{0^{m+a}} \ket{\psi_0} = (\bra{0^{m+a}} \otimes I_n)\ket{\psi_\text{sig}}.
    \end{align}
    Thus, \Cref{eqn:ambe_aa_state} simplifies to 
    \begin{align} 
        \ket{\psi_\ambe} = \alpha_\text{sig} \ket{0^{m+a}}\ket{\psi_\text{sig}} + \alpha_\text{bad} \ket{\perp} \ket{\psi_\text{bad}}.
    \end{align}

    In this form, it is clear that OAA can be used to boost the amplitude of the $\ket{\psi_\text{sig}}$ state. Specifically, OAA will be run with the Grover iterate $G =  R_{\psi_\ambe} R_\text{sig}$, where:
    \begin{align}
         R_\text{sig} &= (I_{m+a}-2\ketbra{0^{m+a}}{0^{m+a}}) \otimes I_{n} \\
        R_{\psi_\ambe} &= 2\ketbra{\psi_\ambe}{\psi_\ambe}-I_{m+a+n}= U_{\psi_\ambe}(2\ketbra{0^{m+a},\psi_0}{0^{m+a},\psi_0}-I_{m+a+n})U_{\psi_\ambe}^\dagger.
    \end{align}
    Letting $k=\calO(1/\sqrt{|\alpha_\text{sig}|^2})$, $G^k \ket{\psi_\ambe}$ produces a state with $\Omega(1)$ overlap with $\ket{0^{m+a}}\ket{\psi_\text{sig}}$. Furthermore, by \Cref{thm:closeness}, $\ket{\psi_\text{sig}}$ has fidelity at least $1-\epsilon^2$ with $\ket{\psi_\text{good}}$. Thus, the output state of this OAA procedure has $\Omega(1-\eps^2)$ overlap with the desired exact state $\ket{\psi_\text{good}}$.
\end{proof}

