\section{Additional constitutive details}

In this appendix, we provide the additional constitutive details used in solving the boundary value problems.

\subsection{Compressible Neo-Hookean solid}\label{Appendix:Constitutive_Neo}

Following \citet{lee2023finite}, we take the free energy of the undamaged body such that
%
\begin{equation}\label{eqn:FreeEnergy_NeoCompressible}
    \hat{\psi}_\mat^{0} (\bfC) = \frac{G}{2} \left[ \Tr (\bfC) - 3  \right] + \frac{G}{\beta} \left[ (\det \bfF)^{-\beta} - 1  \right]\,,
\end{equation}
%
where $G$ represents the shear modulus,  $\beta \Def \frac{2 \nu_\text{poi}}{1 - 2 \nu_\text{poi}}$, with $\nu_\text{poi}$  
 representing Poisson's ratio. 
 %
 Next, the Cauchy stress can be obtained using \eqref{eqn:LocalFreeEnergyGeneric}, \eqref{eqn:g(d)}, and \eqref{eqn:FreeEnergy_NeoCompressible} such that
 %
 \begin{equation}    
\begin{split} \label{eq:CauchyNeohookean}
    \bfT & = 
    J^{-1} \bfF \big( 2 \frac{\partial \hat{\psi}_\mat^{\ast}}{\partial \bfC} )  {\bfF}^\trans \\ & = J^{-1} (1 - d)^2 \left[ G \big( \bfB - (\det F)^{-\beta} \id \big) \right] \,,
\end{split}
\end{equation}
with parameters tabulated in Table \ref{tab:BVP_MaterialParameters}.
%
\begin{table}[htb]
\centering
\begin{tabular}{cc|cc}
\multicolumn{2}{c}{Deformation} & \multicolumn{2}{c}{Damage} \\
\hline
Parameter & Value & Parameter & Value \\
\hline
$G$ (MPa) &  $5$ &  $\epsilonR$ (MPa) &  $240$ \\
$\nu_\text{poi}$ &  $0.45$ & $l$ (mm) &  $0.03$ \\ 
 &  & $\zetaR$ (MPa s) &  $0.001$ \\
\hline
\end{tabular}
\caption{Deformation and damage material parameters for a representative compressible Neo-Hookean solid.}
\label{tab:BVP_MaterialParameters}
\end{table}


\subsection{Linear elastic solid}\label{Appendix:Constitutive_LE}
%
We introduce the Green strain tensor 
%
\begin{equation}\label{eqn:GreenStrain}
    \bfE = \frac{1}{2} (\bfC - \id)\,,
\end{equation}
%
along with the displacement gradient
%
\begin{equation}
    \bfH = \bfF - \id \,,
\end{equation}
%
and use it to recast \eqref{eqn:GreenStrain} so that
%
\begin{equation}\label{eqn:GreenStrainDG}
    \bfE = \frac{1}{2} (\bfH + \bfH^\trans + \bfH \bfH^\trans)\,.
\end{equation}
%
And since we focus our attention on small deformations (or small strains), we drop the higher order terms in \eqref{eqn:GreenStrainDG} to obtain
%
\begin{equation}\label{eqn:smallStrain}
    \bfE = \frac{1}{2} (\bfH + \bfH^\trans) \,,
\end{equation}
%
and take the elastic free energy of the undamaged body such that
\begin{equation}\label{eqn:FreeEnergy_Elastic}
	 \hat{\psi}_\mat^{0} (\bfE)  = G \lvert {\bfE_{0}}\rvert ^{2} + \frac{1}{2} K(\Tr\bfE)^{2}\,,
\end{equation}
%
where
%
\begin{equation}\label{eqn:ShearModulus}
   G \Def \frac{E}{2 (1+\nu_\text{poi})}\,,
\end{equation}
%
is the shear modulus, and
%
\begin{equation}\label{eqn:BulkModulus}
     K \Def \frac{E}{3(1 - 2\nu_\text{poi})}\,,
\end{equation}
%
is the bulk modulus.
%
Next, the Cauchy stress can be obtained using \eqref{eqn:LocalFreeEnergyGeneric}, \eqref{eqn:g(d)}, and \eqref{eqn:FreeEnergy_Elastic} such that
 %
 \begin{equation}    
 \label{eq:CauchyLinearElastic}
    \bfT  = \frac{\partial  \hat{\psi}_\mat^{\ast}}{\partial \bfE^{e}} = (1 - d)^2 \left[2G  \bfE_{0}^{e} + K (\Tr\bfE^{e}) \id  \right]\,,
\end{equation}
with parameters tabulated in Table \ref{tab:BVP_MaterialParameters_Elastic}.
%
\begin{table}[htb]
\centering
\begin{tabular}{cc|cc}
\multicolumn{2}{c}{Deformation} & \multicolumn{2}{c}{Damage} \\
\hline
Parameter & Value & Parameter & Value \\
\hline
$E$ (MPa) &  $ 210000$ &  $\epsilonR$ (MPa) &  $20.7$ \\
$\nu_\text{poi}$ &  $0.3$ & $l$ (mm) &  $0.03$ \\ 
 &  & $\zetaR$ (MPa s) &  $0.001$ \\
\hline
\end{tabular}
\caption{Deformation and damage material parameters for a representative linear elastic solid.}
\label{tab:BVP_MaterialParameters_Elastic}
\end{table}


\subsection{Large deformation rate-dependent plasticity}\label{Appendix:Constitutive_FeFp}
%
We assume in this example that damage nucleates only after the energy exceeds a critical value $\psi_\text{cr}$, and that damage initiation and propagation can only occur under tensile loading.
Accordingly, \eqref{eqn:HistoryFunction} is modified as follows 
\begin{equation}
    \HR(t) = 
    \begin{cases}
        \displaystyle\max_{s \in [0,t]}  \langle \hat{\psi}_{\mat}^{0} \big(\bfC(s)\big) - \psi_\text{cr}  \rangle & \text{if } J > 1 \\
        \HR(t-1) & \text{if } J \leq 1\,,
    \end{cases}
\end{equation}
where $\langle \bullet \rangle$ correspond to the Macaulay brackets and $\HR(t-1)$ to the history function in the prior step. Such a formulation allows damage to nucleate only after a critical energy threshold is reached, while preventing damage under compressive loading.\footnote{Other successful formulations for preventing damage under compressive loadings, such as the volumetric-deviatoric split  \citep{amor2009regularized} and the spectral decomposition \citet{miehe2010thermodynamically} have been reported in the literature.}
%

Next, following the previous work of Anand and co-workers \citep{Anand2009a,Srivastava2010}, we revisit \eqref{eqn:DefGrad}, and introduce the velocity gradient $\bfL$
%
\begin{equation}\label{eq:DefGrad}
  \bfF = \nabla \bfchi, \qquad \bfL = \grad  \bfv = \dot{\bfF}\bfF^{-1}\,.
\end{equation}
%
Moving forward, we adopt the standard multiplicative decomposition 
%
\begin{equation}\label{eq:FeFp}
  \bfF = \bfF^{e} \bfF^{p}, \qquad \text{with} \qquad \det\bfF^{e} > 0 \qquad \text{and} \qquad \det\bfF^{p} > 0\,,
\end{equation}
%
of the deformation gradient $\bfF$ into elastic $\bfF^{e}$ and plastic $\bfF^{p}$ parts.
%
With \eqref{eq:DefGrad} and \eqref{eq:FeFp}, we write the velocity gradient as 
%
\begin{equation}
\bfL = \dot{\bfF}\bfF^{-1} = {\bfL}^{e} + {\bfF}^{e} {\bfL}^{p} {{\bfF}^{e}}^{-1}
\end{equation}
%
where 
\begin{equation}
{\bfL}^{e} = \dot{\bfF}^{e}{{\bfF}^{e}}^{-1}, \qquad \text{and} \qquad {\bfL}^{p} = {\dot{\bfF}}^{p}{{\bfF}^{p}}^{-1}\,,
\end{equation}
%
are the elastic and plastic velocity gradients, respectively.
%
We also introduce the corresponding elastic and plastic stretching and spin tensors for completeness, such that 
\begin{equation}
\begin{split}
\bfD = \sym \bfL\,, \qquad  & \qquad \bfW = \skw \bfL\,, \\
\bfD^{e} = \sym \bfL^{e}\,, \qquad & \qquad \bfW^{e} = \skw \bfL^{e}\,, \\
\bfD^{p} = \sym \bfL^{p}\,, \qquad & \qquad \bfW^{p} = \skw \bfL^{p}\,, 
 \end{split}
\end{equation}
%
with $\bfL = \bfD + \bfW$, ${\bfL}^{e} = {\bfD}^{e} + {\bfW}^{e}$, and ${\bfL}^{p} = {\bfD}^{p} + {\bfW}^{p}$.
%
Further, since assuming an isotropic response, the plastic flow is taken to be irrotational such that 
\begin{equation}
\bfW^{p} = \bf0\,.
\end{equation}
%
As a consequence, $\bfL^{p} = \bfD^{p}$, and 
\begin{equation} \label{eq:FpDot}
\dot{\bfF}^{p} = \bfD^{p} \bfF^{p}\,.
\end{equation}
%
And lastly, plastic flow is assumed to be incompressible such that
%
\begin{equation}
J^{p} = 1,
\end{equation}
%
and as a result
%
\begin{equation}
\text{tr} \bfL^{p} = \text{tr} \bfD^{p} = 0\,,
\end{equation}
%
and therefore 
\begin{equation}
J^{e} = J\,.
\end{equation}
%
We pick the standard form of the free energy \emph{per unit intermediate volume} 
%
\begin{equation} \label{eqn:FreeEnergy_Elastic_LD_Inter}
 \psi^{e} (\bfELN) = G\lvert \bfELN_{0}^{e}\rvert ^{2} + \frac{1}{2} K (\text{tr}\bfELN^{e})^{2}\,, 
\end{equation}
%
where $G$ and $K$ are the shear and bulk moduli, given in \eqref{eqn:ShearModulus} and \eqref{eqn:BulkModulus}, respectively, and $\bfELN_{0}^{e}$ is the deviatoric part of the logarithmic elastic strain $\bfELN^{e}=\ln\bfU^e$.
%

Following \citet{narayan2021fracture}, we take the undamaged energy \emph{per unit reference volume} such that \begin{equation}\label{eqn:FreeEnergy_Elastic_LD_Ref}
\hat{\psi}_\mat^{0} (\bfELN) = J^{p} \psi^{e} (\bfELN) =  \psi^{e} (\bfELN) \,.
\end{equation}
%
Next, the corresponding Mandel stress can be obtained using \eqref{eqn:LocalFreeEnergyGeneric}, \eqref{eqn:g(d)}, \eqref{eqn:FreeEnergy_Elastic_LD_Inter}, and \eqref{eqn:FreeEnergy_Elastic_LD_Ref} such that
%
\begin{equation}
\bfM^{e} = \frac{\partial \hat{\psi}_\mat^{\ast}}{\partial \bfELN^{e}} = (1 - d)^2 \left[2G \bfELN_{0}^{e} + K (\text{tr\bfELN}^{e}) \id \right] \,.
\end{equation}
%
We focus our attention on isotropic materials, hence, the corresponding Cauchy stress is related to the Mandel stress by
%
\begin{equation}
\bfT \Def J^{-1} \bfR^{e} \bfM^{e} \bfR^{e\trans}\,.
\end{equation}
%
Now, keeping \eqref{eq:FeFp} and \eqref{eq:FpDot} in mind, we write the flow rule in the shear-driven form
%
\begin{equation}
\bfD^{p} = \sqrt{\frac{1}{2}} \nup \bfN^{p}\,,
\end{equation}
%
where $\nu^{p}$ and $\bfN^{p}$ are the equivalent plastic shear strain rate and the direction of plastic flow, respectively, and are given by
%
\begin{equation}\label{eq:EqRate}
\nu^{p} = \nu_{0} \Big(\frac{\bar{\tau}}{(1 - d)^2 S}\Big)^{1/m}\,,
\end{equation} 
%
and
%
\begin{equation}\label{eq:DirectionFlow}
\bfN^{p} = \frac{\bfM_{0}^{e}}{\sqrt{2}\bar{\tau}}\,,
\end{equation}
%
where $\bfM_{0}^{e}$ is the deviator of the Mandel stress. Moreover,
%
\begin{equation}
\bar{\tau} \Def \sqrt{\frac{1}{2} \bfM_{0}^{e} \tendot \bfM_{0}^{e}}\,,
\end{equation} 
%
is defined as the equivalent shear stress, and $S$ is the deformation resistance. The evolution equation of the deformation resistance is taken to follow 
%
\begin{equation}
    \dot{S} = h (S_\text{sat} - S) \nup\,, \quad S \left( \bfx, t=0 \right) = S_{0}\,,
\end{equation}
where $h$, $S_\text{sat}$, and $S_{0}$ represent the hardening slope, the saturation level of the deformation resistance, and the initial yield strength, respectively.
%
Lastly, material parameters are tabulated in Table \ref{tab:BVP_MaterialParameters_ElasticPlastic}.
%
